insert into books (volume_id, book_no, title_ml, title_ar, start_page) values (2, 16, 'ഗ്രന്ഥകർത്താവിനെക്കുറിച്ച്', null, 1021) on conflict (volume_id, book_no) do update set title_ml=excluded.title_ml, title_ar=coalesce(excluded.title_ar, books.title_ar), start_page=excluded.start_page;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 1, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا أُمِّ الْمُؤْمِنِينَ رَضِيَ اللهُ عَنْهَا أَنَّهَا قَالَتْ: يَا رَسُولَ اللَّهِ، نَرَى الْجِهَادَ أَفْضَلَ الْعَمَلِ أَفَلَا نُجَاهِدُ؟ قَالَ: "لَا لَكِنَّ أَفْضَلَ الْجِهَادِ حَجٌّ مَبْرُورٌ". (خ)', 'ആഇശ(റ): അവർ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, ദൈവമാർഗ്ഗത്തിലുള്ള ധർമ്മ യുദ്ധത്തെ ഏറ്റവും ശ്രേഷ്ഠമായ കർമ്മമായാണ് ഞങ്ങൾ (സ്ത്രീകൾ) കാണുന്നത്. ഞങ്ങളും അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ യുദ്ധം ചെയ്യട്ടെയോ? അവിടന്ന് പറഞ്ഞു: "വേണ്ട, ഏറ്റവും ശ്രേഷ്ഠമായ ധർമ്മസമരം സ്വീകാര്യമായ ഹജ്ജാണ്." (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 253, 253, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 2, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ حَجَّ لِلَّهِ فَلَمْ يَرْفُثْ، وَلَمْ يَفْسُقْ، رَجَعَ كَيَوْمِ وَلَدَتْهُ أُمُّهُ". (خ)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "തെമ്മാടിത്തം പ്രവർത്തിക്കാതെയും കാമപൂർത്തിക്കുള്ള മാർഗ്ഗം അവലംബിക്കാതെയും അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ ഹജ്ജ് ചെയ്തവൻ, തന്റെ മാതാവ് തന്നെ പ്രസവിച്ച ദിവസത്തെപ്പോലെയാണ് (പാപരഹിതനായാണ്) മടങ്ങിയെത്തുക." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 253, 253, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 3, 'عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "تَابِعُوا بَيْنَ الْحَجِّ وَالْعُمْرَةِ، فَإِنَّهُمَا يَنْفِيَانِ الْفَقْرَ وَالذُّنُوبَ كَمَا يَنْفِي الْكِيرُ خَبَثَ الْحَدِيدِ وَالذَّهَبِ وَالْفِضَّةِ، وَلَيْسَ لِلْحَجَّةِ الْمَبْرُورَةِ ثَوَابٌ إِلَّا الْجَنَّةُ". (ت,ن)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ഹജ്ജിനോടൊപ്പം ഉംറയും നിർവ്വഹിക്കുക. കാരണം, സ്വർണം, വെള്ളി, ഇരുമ്പ് എന്നിവയിലുണ്ടാവുന്ന തുരുമ്പ് ഉല ഇല്ലാതാക്കുന്നതുപോലെ, ഹജ്ജും ഉംറയും ദാരിദ്ര്യവും പാപങ്ങളും ഇല്ലാതാക്കുന്നു. സ്വീകാര്യമായ ഹജ്ജിന് സ്വർഗ്ഗമല്ലാതെ പ്രതിഫലമില്ല." (തു,ന)', 'عَبْدِ اللَّهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['ت','ن']::text[], array['തു','ന']::text[], null, null, 253, 253, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 4, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ حَجَّ، فَلَمْ يَرْفُثْ وَلَمْ يَفْسُقْ، غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ". (ق,ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "കാമപൂർത്തിക്കുള്ള മാർഗമവലംബിക്കാതെയും, തെമ്മാടിത്തം പ്രവർത്തിക്കാതെയും ഹജ്ജ് ചെയ്തവന് തന്റെ പൂർവ്വ ദോഷങ്ങളത്രയും പൊറുക്കപ്പെട്ടിരിക്കുന്നു." (ബു,മു,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 253, 253, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 5, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "الْحَجَّةُ الْمَبْرُورَةُ لَيْسَ لَهَا جَزَاءٌ- وَفِي رِوَايَةٍ: ثَوَابٌ- إِلَّا الْجَنَّةُ، وَالْعُمْرَةُ إِلَى الْعُمْرَةِ كَفَّارَةٌ لِمَا بَيْنَهُمَا". وَفِي رِوَايَةٍ: "تُكَفِّرُ مَا بَيْنَهُمَا". (ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "സ്വീകാര്യമായ ഹജ്ജിന് സ്വർഗ്ഗമല്ലാതെ പ്രതിഫലമില്ല. ഒരു ഉംറ അടുത്ത ഉംറ വരെയുള്ള ദോഷങ്ങൾക്ക് പ്രായശ്ചിത്തമാണ്." മറ്റൊരു നിവേദനത്തിൽ: "അവക്കിടയിലുള്ളത് പൊറുക്കുന്നതാണ്." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 253, 254, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=4 and h.hadith_no=5), 1, 'وَفِي رِوَايَةٍ: ثَوَابٌ- إِلَّا الْجَنَّةُ، وَالْعُمْرَةُ إِلَى الْعُمْرَةِ كَفَّارَةٌ لِمَا بَيْنَهُمَا".', 'മറ്റൊരു നിവേദനത്തിൽ: "അവക്കിടയിലുള്ളത് പൊറുക്കുന്നതാണ്." (ന)');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=4 and h.hadith_no=5), 2, 'وَفِي رِوَايَةٍ: "تُكَفِّرُ مَا بَيْنَهُمَا". (ن)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 6, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: سَأَلَ رَجُلٌ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ، أَيُّ الْأَعْمَالِ أَفْضَلُ؟ قَالَ: "الْإِيمَانُ بِاللَّهِ". قَالَ: ثُمَّ مَاذَا؟ قَالَ: "الْجِهَادُ فِي سَبِيلِ اللَّهِ". قَالَ: ثُمَّ مَاذَا؟ قَالَ: "ثُمَّ الْحَجُّ الْمَبْرُورُ". (ن)', 'അബൂഹുറൈറ(റ): ഒരാൾ റസൂൽ(സ)യോട് ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, ഏറ്റവും ശ്രേഷ്ഠമായ കർമ്മമേതാണ്? റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവിൽ വിശ്വസിക്കൽ." അയാൾ ചോദിച്ചു: പിന്നെ ഏതാണ്? റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ യുദ്ധം ചെയ്യൽ." അയാൾ ചോദിച്ചു: പിന്നെ ഏതാണ്? റസൂൽ(സ) പറഞ്ഞു: "സ്വീകാര്യമായ ഹജ്ജ് നിർവ്വഹിക്കൽ." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 254, 254, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 7, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "وَفْدُ اللَّهِ ثَلَاثَةٌ: الْغَازِي، وَالْحَاجُّ، وَالْمُعْتَمِرُ". (ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ യാത്രാസംഘം മൂന്നാണ്; (ദൈവമാർഗ്ഗത്തിൽ) യുദ്ധം ചെയ്യുന്നവൻ, ഹജ്ജ് ചെയ്യുന്നവൻ, ഉംറ ചെയ്യുന്നവൻ." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 254, 254, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 8, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ : عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "جِهَادُ الْكَبِيرِ وَالصَّغِيرِ، وَالضَّعِيفِ وَالْمَرْأَةِ الْحَجُّ وَالْعُمْرَةُ". (ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "വൃദ്ധന്റെയും കുട്ടിയുടെയും ദുർബ്ബലന്റെയും സ്ത്രീയുടെയും ധർമ്മസമരം ഹജ്ജും ഉംറയുമാണ്." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 254, 254, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 9, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: يَا رَسُولَ اللَّهِ، عَلَى النِّسَاءِ جِهَادٌ؟ قَالَ: "نَعَمْ، عَلَيْهِنَّ جِهَادٌ لَا قِتَالَ فِيهِ: الْحَجُّ وَالْعُمْرَةُ". (خ,ن,جه)', 'ആഇശ(റ): അവർ ചോദിച്ചു: റസൂലേ, സ്ത്രീകൾക്ക് (ദൈവമാർഗത്തിൽ) ധർമ്മസമരം നിർബന്ധമുണ്ടോ? റസൂൽ(സ) പറഞ്ഞു: "അതെ, അവരുടെമേൽ യുദ്ധമില്ലാത്ത ധർമ്മസമരമുണ്ട്, ഹജ്ജും ഉംറയും." (ബു,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ','ن','جه']::text[], array['ബു','ന','ജ']::text[], null, null, 254, 254, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 10, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "الْحَجُّ جِهَادُ كُلِّ ضَعِيفٍ". (جه)', 'ഉമ്മു സലമ(റ): റസൂൽ(സ) പറഞ്ഞു: "എല്ലാ ദുർബലന്റെയും ധർമ്മസമരമാണ് ഹജ്ജ്." (ജ)', 'أُمِّ سَلَمَةَ', 'ഉമ്മു സലമ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 254, 254, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 11, 'عَنْ طَلْحَةَ بْنِ عُبَيْدِ اللَّهِ رَضِيَ اللهُ عَنْهُ : أَنَّهُ سَمِعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "الْحَجُّ جِهَادٌ، وَالْعُمْرَةُ تَطَوُّعٌ". (جه)', 'ത്വൽഹ(റ): റസൂൽ(സ) പറയുന്നതായി അദ്ദേഹം കേട്ടു: "ഹജ്ജ് ധർമ്മസമരവും ഉംറ സുന്നത്താക്കപ്പെട്ട പുണ്യകർമ്മവുമാണ്." (ജ)', 'طَلْحَةَ بْنِ عُبَيْدِ اللَّهِ', 'ത്വൽഹ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 254, 254, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 12, 'عَنْ صَفْوَانَ بْنِ عَبْدِ اللَّهِ بْنِ صَفْوَانَ رَضِيَ اللهُ عَنْهُ ، وَكَانَتْ تَحْتَهُ ابْنَةُ أَبِي الدَّرْدَاءِ، قَالَ: فَأَتَاهَا فَوَجَدَ أُمَّ الدَّرْدَاءِ وَلَمْ يَجِدْ أَبَا الدَّرْدَاءِ، فَقَالَتْ لَهُ: تُرِيدُ الْحَجَّ الْعَامَ؟ قَالَ: نَعَمْ. قَالَتْ: فَادْعُ اللَّهَ لَنَا بِخَيْرٍ، فَإِنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُ: "دَعْوَةُ الْمَرْءِ مُسْتَجَابَةٌ لِأَخِيهِ بِظَهْرِ الْغَيْبِ، عِنْدَ رَأْسِهِ مَلَكٌ يُؤَمِّنُ عَلَى دُعَائِهِ، كُلَّمَا دَعَا لَهُ بِخَيْرٍ قَالَ: آمِينَ، وَلَكَ بِمِثْلِهِ". قَالَ: ثُمَّ خَرَجْتُ إِلَى السُّوقِ فَلَقِيتُ أَبَا الدَّرْدَاءِ، فَحَدَّثَنِي عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِمِثْلِ ذَلِكَ. (م,جه)', 'സ്വഫ്വാനുബ്നു അബ്ദുല്ലാഹിബ്നു സ്വഫ്വാൻ(റ): അബുദ്ദർദാഇന്റെ പുത്രി അദ്ദേഹത്തിന്റെ ഭാര്യയായിരുന്നു. അദ്ദേഹം പറയുന്നു: അദ്ദേഹം അവളുടെ അടുക്കൽ ചെന്നപ്പോൾ ഉമ്മുദർദാഇനെ കണ്ടു, അബുദർദാഇ(റ)നെ കണ്ടതുമില്ല.അപ്പോൾ അവൾ ചോദിച്ചു: നിങ്ങൾ ഈ വർഷത്തെ ഹജ്ജ് ചെയ്യാനുദ്ദേശിക്കുന്നുവോ? അദ്ദേഹം പറഞ്ഞു: അതെ. അവൾ പറഞ്ഞു: ഞങ്ങളുടെ നന്മക്കായി പ്രാർത്ഥിക്കുക. കാരണം, റസൂൽ(സ) പറയാറുണ്ടായിരുന്നു: "സഹോദരന്റെ അസാന്നിദ്ധ്യത്തിൽ അവനു വേണ്ടിയുള്ള പ്രാർത്ഥന ഉത്തരം ചെയ്യപ്പെടുന്നതാണ്. തന്റെ പ്രാർത്ഥനക്ക് ആമീൻ പറയാൻ ഒരു മലക്ക് അവന്റെ തലക്കരികത്തുണ്ട്. നന്മ കൊണ്ട് പ്രാർത്ഥിക്കുമ്പോഴെല്ലാം മലക്ക് ആമീൻ, നിനക്കും തത്തുല്യം ഉണ്ടാവട്ടെ എന്നുപറയും." അദ്ദേഹം പറയുന്നു: പിന്നെ ഞാൻ അങ്ങാടിയിൽ ചെന്നപ്പോൾ അബുദ്ദർദാഇനെ കണ്ടു. അപ്പോൾ മേൽ പറഞ്ഞതുപോലോത്ത ഹദീസ് അദ്ദേഹം നബിയിൽ നിന്നുദ്ധരിച്ചു. (മു.ജ)', 'صَفْوَانَ بْنِ عَبْدِ اللَّهِ بْنِ صَفْوَانَ', 'സ്വഫ്വാനുബ്നു അബ്ദുല്ലാഹിബ്നു സ്വഫ്വാൻ(റ)', null, null, array['م','جه']::text[], '{}'::text[], null, null, 255, 255, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 13, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا ، عَنْ عُمَرَ رَضِيَ اللهُ عَنْهُ : أَنَّهُ اسْتَأْذَنَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الْعُمْرَةِ فَأَذِنَ لَهُ، وَقَالَ لَهُ: "يَا أُخَيِّ، أَشْرِكْنَا فِي شَيْءٍ مِنْ دُعَائِكَ، وَلَا تَنْسَنَا". (د,ت,جه)', 'ഇബ്നുഉമർ(റ) ഉമർ(റ)വിൽ നിന്ന് നിവേദനം ചെയ്യുന്നു: ഉമർ(റ) റസൂൽ(സ)യോട് ഉംറക്ക് അനുവാദം തേടി. റസൂൽ(സ) അദ്ദേഹത്തിന് സമ്മതം നൽകുകയും ഇപ്രകാരം പറയുകയും ചെയ്തു: "സഹോദരാ, നിങ്ങളുടെ പ്രാർത്ഥനയിലെവിടെയെങ്കിലും ഞങ്ങളെയും ഉൾപ്പെടുത്തുക. ഞങ്ങളെ മറക്കരുത്." (ദ,തു,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 255, 255, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 14, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ : عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: "الْحُجَّاجُ وَالْعُمَّارُ وَفْدُ اللَّهِ: إِنْ دَعَوْهُ أَجَابَهُمْ، وَإِنِ اسْتَغْفَرُوهُ غَفَرَ لَهُمْ". (جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഹജ്ജ് ചെയ്യുന്നവരും ഉംറ നിർവ്വഹിക്കുന്നവരും അല്ലാഹുവിന്റെ നിവേദക സംഘമാണ്. അവർ അവനോട് പ്രാർത്ഥിച്ചാൽ ഉത്തരമേകും. മാപ്പിരന്നാൽ പൊറുത്തുകൊടുക്കും." (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 255, 255, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 15, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا : عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الْغَازِي فِي سَبِيلِ اللَّهِ، وَالْحَاجُّ وَالْمُعْتَمِرُ وَفْدُ اللَّهِ: دَعَاهُمْ فَأَجَابُوهُ، وَسَأَلُوهُ فَأَعْطَاهُمْ". (جه)', 'ഇബ്നുഉമർ(റ): നബി(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ പോരാടുന്നവനും ഹജ്ജ് ചെയ്യുന്നവനും ഉംറ നിർവ്വഹിക്കുന്നവനും അല്ലാഹുവിന്റെ നിവേദക സംഘമാണ്. പ്രാർത്ഥിച്ചാൽ അവൻ ഉത്തരം നൽകും, അവനോടവർ ചോദിച്ചാൽ അവർക്കത് നൽകുകയും ചെയ്യും." (ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 255, 255, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 16, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: خَطَبَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "أَيُّهَا النَّاسُ، قَدْ فَرَضَ اللَّهُ عَلَيْكُمُ الْحَجَّ، فَحُجُّوا". فَقَالَ رَجُلٌ: أَكُلَّ عَامٍ يَا رَسُولَ اللَّهِ؟ فَسَكَتَ، حَتَّى قَالَهَا ثَلَاثًا، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَوْ قُلْتُ نَعَمْ لَوَجَبَتْ، وَلَمَا اسْتَطَعْتُمْ". ثُمَّ قَالَ: ذَرُونِي مَا تَرَكْتُكُمْ، فَإِنَّمَا هَلَكَ مَنْ كَانَ قَبْلَكُمْ بِكَثْرَةِ سُؤَالِهِمْ،وَاخْتِلَافِهِمْ عَلَى أَنْبِيَائِهِمْ، فَإِذَا أَمَرْتُكُمْ بِشَيْءٍ فَأْتُوا مِنْهُ مَا اسْتَطَعْتُمْ، وَإِذَا نَهَيْتُكُمْ عَنْ شَيْءٍ فَدَعُوهُ". (م,ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) ഞങ്ങളോട് പ്രസംഗിച്ചു: "ജനങ്ങളേ! അല്ലാഹു നിങ്ങൾക്ക് ഹജ്ജ് നിർബന്ധമാക്കിയിരുക്കുന്നു. അതിനാൽ നിങ്ങൾ ഹജ്ജ് ചെയ്യുക". ഒരാൾ ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരേ, എല്ലാ വർഷവും ചെയ്യണോ? അവിടന്ന് മൗനം പാലിച്ചു. അയാൾ മൂന്നു പ്രാവശ്യം ആവർത്തിച്ചു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ഞാൻ ''അതെ'' എന്നു പറഞ്ഞാൽ അത് നിർബന്ധമാകും, നിങ്ങൾക്കതിന് കഴിയുകയുമില്ല". അവിടന്ന് തുടർന്നു: "ഞാൻ പറയാതെ വിട്ടുകളയുന്ന കാര്യങ്ങളെക്കുറിച്ച് നിങ്ങൾ ചുഴിഞ്ഞന്വേഷിക്കരുത്. കാരണം, നിങ്ങളുടെ പൂർവ്വീകർ നശിച്ചത് അവരുടെ ചോദ്യത്തിന്റെ ആധിക്യത്താലും, പ്രവാചകന്മാരോടുള്ള അഭിപ്രായ വ്യത്യാസത്താലുമാണ്. അതിനാൽ ഞാൻ ഒരു കാര്യം കൽപിച്ചാൽ അതിൽനിന്നും സാധ്യമായത് നിങ്ങൾ ചെയ്യുക. വല്ല കാര്യവും ഞാൻ നിരോധിച്ചാൽ അത് വെടിയുകയും ചെയ്യുക". (മു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], null, null, 256, 256, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 17, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُ : أَنَّ الْأَقْرَعَ بْنَ حَابِسٍ سَأَلَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ، الْحَجُّ فِي كُلِّ سَنَةٍ، أَوْ مَرَّةً وَاحِدَةً؟ قَالَ: "بَلْ مَرَّةً وَاحِدَةً، فَمَنِ اسْتَطَاعَ فَتَطَوُّعٌ". (د,ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): അഖ്റഉബ്നു ഹാബിസ്(റ) റസൂൽ(സ)യോട് ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, ഹജ്ജ്, എല്ലാ വർഷവുമാണോ അതോ ഒറ്റ പ്രാവശ്യമോ? റസൂൽ(സ) പറഞ്ഞു: "ഒറ്റ പ്രാവശ്യം, കൂടുതൽ ചെയ്യാൻ സാധിച്ചാൽ അത് സുന്നത്തുമാണ്." (ദ,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 256, 256, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 18, 'عَنْ أَبِي وَاقِدٍ اللَّيْثِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ لِأَزْوَاجِهِ فِي حَجَّةِ الْوَدَاعِ: "هَذِهِ، ثُمَّ ظُهُورَ الْحُصْرِ". (د)', 'അബൂവാഖിദ് അല്ലൈസീ(റ): റസൂൽ(സ) ഹജ്ജതുൽ വദാഇൽ തന്റെ പത്നിമാരോട് പറയുന്നത് ഞാൻ കേട്ടു: "ഇതാണ് (നിങ്ങൾക്ക് നിർബന്ധമായ ഹജ്ജ്). ഇനി പായകളിൽ അടങ്ങിയിരിക്കുക." (ദ)', 'أَبِي وَاقِدٍ اللَّيْثِيِّ', 'അബൂവാഖിദ് അല്ലൈസീ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 256, 256, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 19, 'عَنْ عَلِيٍّ كَرَّمَ اللهُ وَجْهَهُ قَالَ: لَمَّا نَزَلَتْ: {وَلِلَّهِ عَلَى النَّاسِ حَجُّ الْبَيْتِ مَنِ اسْتَطَاعَ إِلَيْهِ سَبِيلًا} [آل عمران: ٩٧] قَالُوا: يَا رَسُولَ اللَّهِ، الْحَجُّ فِي كُلِّ عَامٍ؟ فَسَكَتَ، ثُمَّ قَالُوا: أَفِي كُلِّ عَامٍ؟ فَقَالَ: "لَا، وَلَوْ قُلْتُ: نَعَمْ لَوَجَبَتْ، فَنَزَلَتْ: {يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَسْأَلُوا عَنْ أَشْيَاءَ إِنْ تُبْدَ لَكُمْ تَسُؤْكُمْ} [المائدة: ١٠١] (ت,جه)', 'അലി(റ): ''കഅ്ബയിൽ ചെന്ന് അല്ലാഹുവിന് ഹജ്ജ് ചെയ്യൽ അവിടെ എത്തിച്ചേരാൻ കഴിവുള്ള ജനങ്ങളുടെമേൽ ബാധ്യതയാണ്.'' (ആലുഇംറാൻ: 97) എന്ന സുക്തമിറങ്ങിയപ്പോൾ അവർ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, എല്ലാ വർഷവും നിർബന്ധമാണോ? റസൂൽ(സ) ഒന്നും മിണ്ടിയില്ല. അവർ പിന്നെയും ചോദിച്ചു: എല്ലാ വർഷവും നിർബന്ധമാണോ? റസൂൽ(സ) പറഞ്ഞു: "അല്ല, ഞാൻ അതെ എന്നു പറഞ്ഞാൽ അത് നിർബന്ധമാകുമായിരുന്നു". അപ്പോൾ ഈ സൂക്തം അവതരിച്ചു: ''വിശ്വാസികളെ, പല കാര്യങ്ങളെക്കുറിച്ചും നിങ്ങൾ അന്വേഷിക്കരുത്. അത് വെളിവാക്കപ്പെട്ടാൽ നിങ്ങൾക്കത് ദോഷമാകും.'' (മാഇദ: 101) (തു,ജ)', 'عَلِيٍّ كَرَّمَ اللهُ وَجْهَهُ قَالَ', 'അലി(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], 'المائدة: ١٠١', null, 256, 256, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 20, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُ : أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَامَ فَقَالَ: "إِنَّ اللَّهَ تَعَالَى كَتَبَ عَلَيْكُمُ الْحَجَّ". فَقَالَ الْأَقْرَعُ بْنُ حَابِسٍ التَّمِيمِيُّ: كُلُّ عَامٍ يَا رَسُولَ اللَّهِ؟ فَسَكَتَ، فَقَالَ: "لَوْ قُلْتُ نَعَمْ لَوَجَبَتْ، ثُمَّ إِذًا لَا تَسْمَعُونَ وَلَا تُطِيعُونَ، وَلَكِنَّهُ حَجَّةٌ وَاحِدَةٌ". (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) എഴുന്നേറ്റുനിന്നു പറഞ്ഞു: "അല്ലാഹു നിങ്ങൾക്ക് ഹജ്ജ് നിർബന്ധമാക്കിയിരുക്കുന്നു". അപ്പോൾ അഖ്റഅ്(റ) ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, എല്ലാ വർഷവുമാണോ? അവിടന്ന് ഒന്നും മിണ്ടിയില്ല. പിന്നെ പറഞ്ഞു: "ഞാൻ അതെ എന്നു പറഞ്ഞാൽ അത് നിർബന്ധമാകുമായിരുന്നു, പിന്നെ നിങ്ങൾ കേൾക്കുകയോ, അനുസരിക്കുകയോ ചെയ്യില്ല. പക്ഷേ, അത് ഒരൊറ്റ ഹജ്ജാണ്." (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 257, 257, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 21, 'عَنْ أَنَسِ ابْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالُوا: يَا رَسُولَ اللَّهِ، الْحَجُّ فِي كُلِّ عَامٍ؟ قَالَ: "لَوْ قُلْتُ: نَعَمْ لَوَجَبَتْ، وَلَوْ وَجَبَتْ لَمْ تَقُومُوا بِهَا، وَلَوْ لَمْ تَقُومُوا بِهَا عُذِّبْتُمْ". (جه)', 'അനസുബ്നു മാലിക്(റ): അവർ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, എല്ലാ വർഷവും ഹജ്ജ് നിർബന്ധമാണോ? റസൂൽ(സ) പറഞ്ഞു: "ഞാൻ അതെ എന്നു പറഞ്ഞാൽ അത് നിർബന്ധമാകുമായിരുന്നു. നിർബന്ധമായാലത് നിർവ്വഹിക്കാൻ നിങ്ങൾക്കാവില്ല. നിങ്ങളത് നിർവ്വഹിച്ചില്ലെങ്കിൽ ശിക്ഷിക്കപ്പെടുകയും ചെയ്യും". (ജ)', 'أَنَسِ ابْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 257, 257, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 22, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُ قَالَ: قَامَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ، مَا يُوجِبُ الْحَجَّ؟ قَالَ: "الزَّادُ وَالرَّاحِلَةُ". قَالَ: يَا رَسُولَ اللَّهِ فَمَا الْحَاجُّ؟ قَالَ: "الشَّعِثُ التَّفِلُ". وَقَامَ آخَرُ فَقَالَ: "يَا رَسُولَ اللَّهِ، مَا الْحَجُّ؟ قَالَ: "الْعَجُّ وَالثَّجُّ". (ت,جه)', 'ഇബ്നുഉമർ(റ): ഒരാൾ നബി(സ)യെ സമീപിച്ച് ചോദിച്ചു: റസൂലേ, എന്താണ് ഹജ്ജിനെ നിർബന്ധമാക്കുന്നത്? റസൂൽ(സ) പറഞ്ഞു: "പാഥേയവും വാഹനവും". അപ്പോൾ അയാൾ ചോദിച്ചു: റസൂലേ, ഹാജിയുടെ അവസ്ഥ എങ്ങനെയാണ്? റസൂൽ(സ) പറഞ്ഞു: "മുടി ജഢപിടിക്കലും മുഷിയലുമാണ്." വേറെ ഒരാൾ എഴുന്നേറ്റു ചോദിച്ചു: അല്ലാഹുവിന്റെ ദുതരേ, എന്താണ് ഹജ്ജ്? റസൂൽ(സ) പറഞ്ഞു: "ഒച്ചയും തിരക്കുമാണ്". (തു,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 257, 257, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 23, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الزَّادُ وَالرَّاحِلَةُ". يَعْنِي قَوْلَهُ: {مَنِ اسْتَطَاعَ إِلَيْهِ سَبِيلًا} [آل عمران: ٩٧]. (جه)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "പാഥേയവും വാഹനവുമാണ്." അതായത് ''വഴിയാൽ സാധിച്ചവൻ'' (ആലുഇംറാൻ: 97) എന്ന ദൈവിക വചനത്തിന്റെ ഉദ്ദേശ്യം ഇതാണ്. (ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'آل عمران: ٩٧', null, 257, 257, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 24, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ مَلَكَ زَادًا وَرَاحِلَةً تُبَلِّغُهُ إِلَى بَيْتِ اللَّهِ، وَلَمْ يَحُجَّ، فَلَا عَلَيْهِ أَنْ يَمُوتَ يَهُودِيًّا أَوْ نَصْرَانِيًّا. وَذَلِكَ أَنَّ اللَّهَ يَقُولُ فِي كِتَابِهِ: {وَلِلَّهِ عَلَى النَّاسِ حَجُّ الْبَيْتِ مَنِ اسْتَطَاعَ إِلَيْهِ سَبِيلًا} [آل عمران: ٩٧]". قَالَ الترمذي: فِي إِسْنَادِهِ مَقَالٌ. (ت)', 'അലി(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ ഭവനത്തിലേക്കെത്തിക്കുന്ന വാഹനവും പാഥേയവും ഉടമസ്ഥതയിലുണ്ടായിട്ട് ഹജ്ജ് ചെയ്യാത്തവൻ ക്രിസ്ത്യാനിയായോ ജൂതനായോ മരിക്കട്ടെ. കാരണം, അല്ലാഹു തന്റെ ഗ്രന്ഥത്തിൽ പറയുന്നു: ''അവിടെ എത്തിച്ചേരാൻ സാധിച്ചാൽ അല്ലാഹുവിന് ഹജ്ജ് ചെയ്യൽ ജനങ്ങളുടെ ബാധ്യതയാണ്.'' (ആലുഇംറാൻ: 97) (തു)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['ت']::text[], array['തു']::text[], 'آل عمران: ٩٧', null, 257, 258, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 25, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ، وَقَدْ سُئِلَ: كَمْ حَجَّ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ قَالَ: حَجَّةً وَاحِدَةً، وَاعْتَمَرَ أَرْبَعَ عُمَرٍ: عُمْرَةٌ فِي ذِي الْقَعْدَةِ، وَعُمْرَةُ الْحُدَيْبِيَةِ، وَعُمْرَةٌ مَعَ حَجَّتِهِ، وَعُمْرَةُ الْجِعِرَّانَةِ، إِذْ قَسَّمَ غَنِيمَةَ حُنَيْنٍ. (ق,ت)', 'അനസുബ്നു മാലിക്(റ): അദ്ദേഹത്തോട് ചോദിച്ചു: റസൂൽ(സ) എത്ര ഹജ്ജ് ചെയ്തിട്ടുണ്ട്? അദ്ദേഹം പറഞ്ഞു: ഒരൊറ്റ ഹജ്ജ്, നാല് ഉംറ നിർവ്വഹിച്ചിട്ടുണ്ട്: ദുൽഖഅദിൽ ഒന്ന്, ഹുദൈബിയ്യയിൽ നിന്ന് ഒന്ന്, ഹജ്ജിനോടൊപ്പം ഒന്ന്, ജിഅ്റാനയിലെ ഒരു ഉംറ; ഹുനൈനിലെ യുദ്ധമുതൽ ഓഹരി നടത്തിയപ്പോൾ. (ബു,മു,തു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 258, 258, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 26, 'عَنْ أَبِي إِسْحَاقَ رَضِيَ اللهُ عَنْهُ قَالَ: سَأَلْتُ زَيْدَ بْنَ أَرْقَمَ: كَمْ غَزَوْتَ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ قَالَ: سَبْعَ عَشْرَةَ. قَالَ: وَحَدَّثَنِي زَيْدُ بْنُ أَرْقَمَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ غَزَا تِسْعَ عَشْرَةَ، وَأَنَّهُ حَجَّ بَعْدَ مَا هَاجَرَ حَجَّةً وَاحِدَةً حَجَّةَ الْوَدَاعِ. قَالَ أَبُو إِسْحَاقَ: وَبِمَكَّةَ أُخْرَى. (م)', 'അബൂഇസ്ഹാഖ്(റ): ഞാൻ സൈദുബ്നു അർഖം(റ)വിനോട് ചോദിച്ചു: നിങ്ങൾ റസൂൽ(സ)യോടൊപ്പം എത്ര യുദ്ധം ചെയ്തു? അദ്ദേഹം പറഞ്ഞു: പതിനേഴ്. നിവേദകൻ തുടരുന്നു: റസൂൽ(സ) 19 യുദ്ധം ചെയ്തിട്ടുണ്ടെന്നും ഹിജ്റക്കു ശേഷം ഹജ്ജതുൽ വിദാഇലെ ഒറ്റ ഹജ്ജ് മാത്രമാണ് റസൂൽ(സ) ചെയ്തതെന്നും സൈദുബ്നു അർഖം(റ) എന്നോട് പറഞ്ഞു. അബൂഇസ്ഹാഖ് പറയുന്നു: മക്കയിൽ നിന്ന് മറ്റൊന്നും. (മു)', 'أَبِي إِسْحَاقَ', 'അബൂഇസ്ഹാഖ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 258, 258, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 27, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَجَّ ثَلَاثَ حِجَجٍ: حَجَّتَيْنِ قَبْلَ أَنْ يُهَاجِرَ، وَحَجَّةً بَعْدَ مَا هَاجَرَ، وَمَعَهَا عُمْرَةٌ. فَسَاقَ ثَلَاثَةً وَسِتِّينَ بَدَنَةً، وَجَاءَ عَلِيٌّ مِنَ الْيَمَنِ بِبَقِيَّتِهَا، فِيهَا جَمَلٌ لِأَبِي جَهْلٍ، فِي أَنْفِهِ بُرَةٌ مِنْ فِضَّةٍ، فَنَحَرَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَأَمَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ كُلِّ بَدَنَةٍ بِبَضْعَةٍ، فَطُبِخَتْ وَشَرِبَ مِنْ مَرَقِهَا. (ت,جه)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): റസൂൽ(സ) മൂന്ന് ഹജ്ജ് നിർവ്വഹിച്ചു: ഹിജ്റക്കു മുൻപ് രണ്ട് ഹജ്ജ്, ഹിജ്റക്കു ശേഷം ഒന്ന്, ഇതോടൊപ്പം ഉംറയും നിർവ്വഹിച്ചു. റസൂൽ(സ) അറുപത്തിമൂന്ന് ഒട്ടകത്തെ തെളിച്ചു. അലി(റ) അതിന്റെ ബാക്കിയുമായി യമനിൽ നിന്ന് വന്നു. അതിൽ അബൂജഹലിന്റെ ഒരൊട്ടകവുമുണ്ടായിരുന്നു. അതിന്റെ മൂക്കിൽ വെള്ളിയുടെ ഒരു കടിഞ്ഞാണുണ്ട്. റസൂൽ(സ) അതിനെ അറുത്തു. ഓരോ ഒട്ടകത്തിൽ നിന്നും ഒരു ഇറച്ചിക്കഷ്ണമെടുക്കാൻ റസൂൽ(സ) കൽപിച്ചു. പിന്നെ അത് പാകം ചെയ്യപ്പെടുകയും റസൂൽ(സ) അതിന്റെ കറി സേവിക്കുകയും ചെയ്തു. (തു,ജ)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 258, 258, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 28, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّهُ قِيلَ لَهُ: كَمِ اعْتَمَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ قَالَ: أَرْبَعًا إِحْدَاهُنَّ فِي رَجَب. قَالَ السائل: فَقُلْتُ لِعَائِشَةَ: يَا أُمَّاهُ، أَلَا تَسْمَعِينَ مَا يَقُولُ أَبُو عَبْدِالرَّحْمَنِ؟ قَالَتْ: مَا يَقُولُ؟ قَالَ: يَقُولُ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ اعْتَمَرَ أَرْبَعَ عُمَرَاتٍ إِحْدَاهُنَّ فِي رَجَب، قَالَتْ: يَرْحَمُ اللَّهُ أَبَا عَبْدِالرَّحْمَنِ مَا اعْتَمَرَ عُمْرَةً إِلَّا وَهُوَ شَاهِدُهُ، وَمَا اعْتَمَرَ فِي رَجَب قَطُّ. (خ)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): അദ്ദേഹത്തോട് ചോദിച്ചു: റസൂൽ(സ) എത്ര ഉംറ ചെയ്തു? അദ്ദേഹം പറഞ്ഞു: നാലെണ്ണം, റജബിൽ ഒന്ന്. ചോദ്യകർത്താവ് പറയുന്നു: ഞാൻ ആഇശ(റ)യോട് ചോദിച്ചു: മാതാവേ, അബൂ അബ്ദുർറഹ്മാൻ പറയുന്നത് നിങ്ങൾ കേൾക്കുന്നില്ലേ? അവർ ചോദിച്ചു: എന്താണ് അദ്ദേഹം പറയുന്നത്? ചോദ്യകർത്താവ് പറഞ്ഞു: റസൂൽ(സ) നാല് ഉംറ ചെയ്തുവെന്നും അതിലൊന്ന് റജബിലായിരുന്നെന്നും അദ്ദേഹം പറയുന്നു. ആഇശ(റ) പറഞ്ഞു: അബൂ അബ്ദുർറഹ്മാനെ അല്ലാഹു അനുഗ്രഹിക്കട്ടെ, അദ്ദേഹം സാക്ഷിയാവാതെ റസൂൽ(സ) ഒരു ഉംറയും നിർവ്വഹിച്ചിട്ടില്ല. റസൂൽ(സ) റജബിൽ ഒരു ഉംറയും ചെയ്തിട്ടില്ല. (ബു)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 259, 259, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 29, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ أَنَّهُ سُئِلَ: كَمِ اعْتَمَرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: أَرْبَعًا: عُمْرَةَ الْحُدَيْبِيَةِ فِي ذِي الْقَعْدَةِ حَيْثُ صَدَّهُ الْمُشْرِكُونَ، وَعُمْرَةٌ مِنَ الْعَامِ الْمُقْبِلِ فِي ذِي الْقَعْدَةِ حَيْثُ صَالَحَهُمْ، وَعُمْرَةُ الْجِعِرَّانَةِ إِذْ قَسَمَ غَنِيمَةَ أُرَاهُ حُنَيْنٍ، قُلْتُ: كَمْ حَجَّ؟ قَالَ: وَاحِدَةً.
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=4 and h.hadith_no=29), 1, 'وَفِي رِوَايَةٍ أَنَّهُ قَالَ: اعْتَمَرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَيْثُ رَدُّوهُ، وَمِنَ الْقَابِلِ عُمْرَةَ الْحُدَيْبِيَةِ، وَعُمْرَةً فِي ذِي الْقَعْدَةِ، وَعُمْرَةً مَعَ حَجَّتِهِ. (خ)', 'മറ്റൊരു നിവേദനത്തിൽ: ശത്രുക്കൾ തടഞ്ഞപ്പോൾ റസൂൽ(സ) ഉംറ ചെയ്തു, അടുത്ത വർഷം ഹുദൈബിയ ഉംറ, ദുൽഖഅദിൽ ഒരു ഉംറയും തന്റെ ഹജ്ജിനോടൊപ്പം മറ്റൊരു ഉംറയും നിർവ്വഹിച്ചു. (ബു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 30, 'عَنِ الْبَرَاءِ رَضِيَ اللهُ عَنْهُ أَنَّهُ قَالَ: اعْتَمَرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي ذِي الْقَعْدَةِ قَبْلَ أَنْ يَحُجَّ مَرَّتَيْنِ. (خ)', 'ബറാഅ്(റ): റസൂൽ(സ) തന്റെ ഹജ്ജിനു മുൻപ് ദുൽഖഅദിൽ രണ്ട് ഉംറ ചെയ്തിട്ടുണ്ട്. (ബു)', 'الْبَرَاءِ', 'ബറാഅ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 259, 259, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 31, 'عَنْ عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْر رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمَرَهُ أَنْ يُرْدِفَ عَائِشَةَ رَضِيَ اللهُ عَنْ هَا وَيُعْمِرَهَا مِنَ التَّنْعِيمِ، وَأَنَّ سُرَاقَةَ بْنَ مَالِكِ ابْنِ جُعْشُمٍ لَقِيَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالْعَقَبَةِ وَهُوَ يَرْمِيهَا، فَقَالَ: أَلَكُمْ هَذِهِ خَاصَّةً يَا رَسُولَ اللَّهِ؟ قَالَ: "لَا، بَلْ لِلْأَبَدِ". (خ)', 'അബ്ദുർറഹ്മാനുബ്നു അബൂബക്കർ(റ): ആഇശ(റ)യെ കുടെയിരുത്താനും തൻഈമിൽ നിന്ന് ഉംറ (ഇഹ്റാം) ചെയ്യിക്കാനും റസൂൽ(സ) എന്നോട് കല്പിച്ചു. റസൂൽ(സ) അഖബയിൽ എറിഞ്ഞു കൊണ്ടിരിക്കെ സുറാഖ(റ) നബി(സ)യെ കണ്ടു. അദ്ദേഹം ചോദിച്ചു: ഇതു താങ്കൾക്ക് പ്രത്യേകമാണോ? റസൂൽ(സ) പറഞ്ഞു: "അല്ല, എല്ലാവർക്കുമാണ്." (ബു)', 'عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْر', 'അബ്ദുർറഹ്മാനുബ്നു അബൂബക്കർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 259, 260, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 32, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ اعْتَمَرَ عُمْرَتَيْنِ: عُمْرَةً فِي ذِي الْقَعْدَةِ، وَعُمْرَةً فِي شَوَّال. (د)', 'ആഇശ(റ): റസൂൽ(സ) രണ്ട് ഉംറ നിർവ്വഹിച്ചു, ഒന്ന് ദുൽഖഅദിലും മറ്റൊന്ന് ശവ്വാലിലും. (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 260, 260, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 33, 'عَنْ أُمِّ مَعْقِلٍ رَضِيَ اللهُ عَنْهَا: عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "عُمْرَةٌ فِي رَمَضَانَ تَعْدِلُ حَجَّةً". (د,ن,جه)', 'ഉമ്മുമഅ്ഖൽ(റ): റസൂൽ(സ) പറഞ്ഞു:"റമദാനിലെ ഉംറ ഹജ്ജിനു സമാനമാണ്." (ദ,ന,ജ)', 'أُمِّ مَعْقِلٍ', 'ഉമ്മുമഅ്ഖൽ(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 260, 260, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 34, 'عن أُمِّ مَعْقِلٍ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ أَبُو مَعْقِلٍ رَضِيَ اللهُ عَنْهُ حَاجًّا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَلَمَّا قَدِمَ قَالَتْ أُمُّ مَعْقِلٍ: قَدْ عَلِمْتَ أَنَّ عَلَيَّ حَجَّةً، فَانْطَلَقَا يَمْشِيَانِ حَتَّى دَخَلَا عَلَيْهِ، فَقَالَتْ: يَا رَسُولَ اللَّهِ، إِنَّ عَلَيَّ حَجَّةً، وَإِنَّ لِأَبِي مَعْقِلٍ بَكْرًا، قَالَ أَبُو مَعْقِلٍ: صَدَقَتْ، جَعَلْتُهُ فِي سَبِيلِ اللَّهِ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَعْطِهَا فَلْتَحُجَّ عَلَيْهِ، فَإِنَّهُ فِي سَبِيلِ اللَّهِ". فَأَعْطَاهَا الْبَكْرَ، فَقَالَتْ: يَا رَسُولَ اللَّهِ، إِنِّي امْرَأَةٌ قَدْ كَبِرْتُ وَسَقِمْتُ، فَهَلْ مِنْ عَمَلٍ يُجْزِئُ عَنِّي مِنْ حَجَّتِي؟ قَالَ: "عُمْرَةٌ فِي رَمَضَانَ تُجْزِئُ حَجَّةً". (د,ن,جه)', 'ഉമ്മുമഅ്ഖൽ(റ): അബൂമഅ്ഖൽ(റ) തിരുമേനി(സ)യുടെ കൂടെ ഹജ്ജിനുണ്ടായിരുന്നു. അബൂമഅ്ഖൽ(റ) വന്നപ്പോൾ ഉമ്മുമഅ്ഖൽ(റ) പറഞ്ഞു: ഹജ്ജ് എനിക്ക് നിർബന്ധമാണെന്ന് താങ്കൾക്കറിയാമല്ലോ. അവർ രണ്ടു പേരും നടന്ന് റസൂൽ(സ)യുടെ അരികിലെത്തി. ഉമ്മുമഅ്ഖൽ(റ) പറഞ്ഞു: തിരുദൂതരെ, എന്റെ മേൽ ഹജ്ജുണ്ട്. അബുമഅ്ഖൽ(റ)വിനു ഒരു ഒട്ടകവുമുണ്ട്. അബൂമഅ്ഖൽ(റ) പറഞ്ഞു: അവർ പറഞ്ഞത് സത്യമാണ്. അതിനെ ഞാൻ അല്ലാഹുവിന്റെ മാർഗത്തിൽ ആക്കിയിട്ടുണ്ട്. റസൂൽ(സ) പറഞ്ഞു: "നീ അത് അവൾക്ക് നൽകുക, അവൾ അതിന്മേൽ ഹജ്ജ് ചെയ്യട്ടെ. നിശ്ചയം ഹജ്ജ് അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിലാണ്." അപ്പോൾ അവൾക്ക് ഒട്ടകം നൽകി. ഉമ്മുമഅ്ഖൽ(റ) പറഞ്ഞു: റസൂലേ, ഞാൻ രോഗിയും വൃദ്ധയുമായ ഒരു സ്ത്രീയാണ്. ഹജ്ജിന് പകരം എന്നിൽ നിന്ന് മതിയാവുന്ന വല്ല കർമ്മവുമുണ്ടോ? റസൂ(സ) പറഞ്ഞു: "റമളാനിലെ ഒരു ഉംറ ഒരു ഹജ്ജിന് മതിയാവും." (ദ,ന,ജ)', 'أُمِّ مَعْقِلٍ', 'ഉമ്മുമഅ്ഖൽ(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 260, 260, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 35, 'عن أُمِّ مَعْقِلٍ رَضِيَ اللهُ عَنْهَا قَالَتْ: لَمَّا حَجَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَجَّةَ الْوَدَاعِ، وَكَانَ لَنَا جَمَلٌ، فَجَعَلَهُ أَبُو مَعْقِلٍ فِي سَبِيلِ اللَّهِ، وَأَصَابَنَا مَرَضٌ، وَهَلَكَ أَبُو مَعْقِلٍ، وَخَرَجَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَلَمَّا فَرَغَ مِنْ حَجِّهِ جِئْتُهُ، فَقَالَ: "يَا أُمَّ مَعْقِلٍ، مَا مَنَعَكِ أَنْ تَخْرُجِي مَعَنَا". قَالَتْ: لَقَدْ تَهَيَّأْنَا فَهَلَكَ أَبُو مَعْقِلٍ، وَكَانَ لَنَا جَمَلٌ هُوَ الَّذِي نَحُجُّ عَلَيْهِ، فَأَوْصَى بِهِ أَبُو مَعْقِلٍ فِي سَبِيلِ اللَّهِ. قَالَ: "فَهَلَّا خَرَجْتِ عَلَيْهِ، فَإِنَّ الْحَجَّ فِي سَبِيلِ اللَّهِ، فَأَمَّا إِذْ فَاتَتْكِ هَذِهِ الْحَجَّةُ مَعَنَا فَاعْتَمِرِي فِي رَمَضَانَ، فَإِنَّهَا كَحَجَّةٍ". فَكَانَتْ تَقُولُ: الْحَجُّ حَجَّةٌ، وَالْعُمْرَةُ عُمْرَةٌ، وَقَدْ قَالَ هَذَا لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، مَا أَدْرِي أَلِيَ خَاصَّةً. (د)', 'ഉമ്മുമഅ്ഖൽ(റ): റസൂൽ(സ) വിടവാങ്ങൽ ഹജ്ജ് ചെയ്തപ്പോൾ ഞങ്ങൾക്ക് ഒരു ഒട്ടകമുണ്ടായിരുന്നു. അബൂമഅ്ഖൽ(റ) അതിനെ അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിലാക്കി. ഞങ്ങൾക്ക് രോഗം ബാധിക്കുകയും അബൂമഅ്ഖൽ(റ) മരിക്കുകയും ചെയ്തു. റസൂൽ(സ) ഹജ്ജ് ചെയ്ത് മടങ്ങിവന്നപ്പോൾ ഞാൻ റസൂൽ(സ)യുടെ അടുത്ത് ചെന്നു. അപ്പോൾ തിരുമേനി(സ) ചോദിച്ചു: "ഉമ്മുമഅ്ഖലേ, ഞങ്ങളുടെ കൂടെ പുറപ്പെടുന്നതിൽ നിന്ന് എന്താണ് നിന്നെ തടഞ്ഞു വെച്ചത്." അവർ പറഞ്ഞു: ഞങ്ങൾ തയ്യാറായിരുന്നു. പക്ഷെ, അബുമഅ്ഖൽ(റ) മരിച്ചു. ഞങ്ങൾ ഹജ്ജിന് പോവാൻ കരുതിവെച്ച ഒരു ഒട്ടകമുണ്ടായിരുന്നു. ഒട്ടകത്തെ അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിലാക്കാൻ അബൂമഅ്ഖൽ വസ്വിയ്യത് ചെയ്തു. റസൂൽ(സ) അരുളി: "നിനക്ക് ആ ഒട്ടകത്തിൻമേൽ തന്നെ യാത്ര പുറപ്പെടാമായിരുന്നല്ലോ, കാരണം ഹജ്ജ് അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിലാണ്. എന്നാൽ ഞങ്ങളോട് കുടെയുള്ള ഈ ഹജ്ജ് നിനക്ക് നഷ്ടമായതിന് നീ റമളാനിൽ ഉംറ നിർവ്വഹിക്കുക. കാരണം അത് ഹജ്ജ് പോലെയാണ്." ഉമ്മുമഅ്ഖൽ(റ) പറയുമായിരുന്നു: ഹജ്ജ് ഹജ്ജാണ്. ഉംറ ഉംറയും. ഇപ്രകാരം എന്നോട് തിരുമേനി(സ) പറഞ്ഞു. എനിക്കറിയില്ല, ഇത് എനിക്ക് മാത്രം പ്രത്യേകമാണോ എന്ന്. (ദ)', 'أُمِّ مَعْقِلٍ', 'ഉമ്മുമഅ്ഖൽ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 260, 261, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 36, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: أَرَادَ رَسُولُ [?] صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْحَجَّ، فَقَالَتِ امْرَأَةٌ لِزَوْجِهَا: أَحِجَّنِي مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى [?]. فَقَالَ: مَا عِنْدِي مَا أُحِجُّكِ عَلَيْهِ، قَالَتْ: أَحِجَّنِي عَلَى جَمَلِكَ فُلَانٍ، قَالَ: ذَاكَ حَبِيسٌ فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ. فَأَتَى رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: إِنَّ امْرَأَتِي تَقْرَأُ عَلَيْكَ السَّلَامَ وَرَحْمَةَ اللَّهِ، وَإِنَّهَا سَأَلَتْنِي الْحَجَّ مَعَكَ، قَالَتْ: أَحِجَّنِي مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقُلْتُ: مَا عِنْدِي مَا أُحِجُّكِ عَلَيْهِ، فَقَالَتْ أَحِجَّنِي عَلَى جَمَلِكَ فُلَانٍ، فَقُلْتُ: ذَاكَ حَبِيسٌ فِي سَبِيلِ اللَّهِ؟ فَقَالَ: "أَمَا إِنَّكَ لَوْ أَحْجَجْتَهَا عَلَيْهِ كَانَ فِي سَبِيلِ اللَّهِ". قَالَ: وَإِنَّهَا أَمَرَتْنِي أَنْ أَسْأَلَكَ مَا يَعْدِلُ حَجَّةً مَعَكَ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَقْرِئْهَا السَّلَامَ وَرَحْمَةَ اللَّهِ وَبَرَكَاتِهِ، وَأَخْبِرْهَا أَنَّهَا تَعْدِلُ حَجَّةً مَعِي". يَعْنِي عُمْرَةً فِي رَمَضَانَ. (د,ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) ഹജ്ജിന് പോകാനൊരുങ്ങി. അപ്പോൾ ഒരു സ്ത്രീ തന്റെ ഭർത്താവിനോട് പറഞ്ഞു: നിങ്ങളുടെ ഒട്ടകപ്പുറത്ത് റസൂൽ(സ)യോട് കൂടെ ഹജ്ജ് ചെയ്യാൻ എന്നെ അയക്കുക. അയാൾ പറഞ്ഞു: നിനക്ക് ഹജ്ജ് ചെയ്യാൻ പറ്റിയത് ഒന്നും തന്നെ എന്റെ കൈവശം ഇല്ല. അവൾ പറഞ്ഞു: നിങ്ങളുടെ ആ ഒട്ടകപ്പുറത്ത് എന്നെ ഹജ്ജിനയക്കുക. അയാൾ പറഞ്ഞു: അത് അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ ആക്കപ്പെട്ടതാണ്. അയാൾ തിരുമേനി(സ)യെ സമീപിച്ച് പറഞ്ഞു: എന്റെ ഭാര്യ അങ്ങേക്ക് അല്ലാഹുവിന്റെ കരുണയും സലാമും നേർന്നിരിക്കുന്നു. അങ്ങയോട് കൂടെ ഹജ്ജിനയക്കണമെന്ന് അവർ ആവശ്യപ്പെടുന്നു. അവൾ പറയുന്നു: തിരുമേനി(സ)ക്കൊപ്പം എന്നെ ഹജ്ജ് ചെയ്യിക്കുക. ഞാൻ പറഞ്ഞു: നിനക്ക് ഹജ്ജ് ചെയ്യാൻ പറ്റിയത് ഒന്നും എന്റെ കയ്യിലില്ല. അവൾ പറഞ്ഞു: നിങ്ങളുടെ ഇന്നാലിന്ന ഒട്ടകപ്പുറത്ത് എന്നെ ഹജ്ജ് ചെയ്യിക്കുക. ഞാൻ പറഞ്ഞു: അത് അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ ഉപയോഗിക്കാനുള്ളതാണ്. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "നിങ്ങൾ അവളെ അതിന്മേൽ ഹജ്ജ് ചെയ്യിച്ചാലും അത് അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിലാകും." അയാൾ പറഞ്ഞു: അങ്ങയുടെ കൂടെയുള്ള ഹജ്ജിന് പകരമായി നിൽക്കുന്നത് ഏതെന്ന് അന്വേഷിക്കാൻ അവൾ എന്നോട് ആവശ്യപ്പെട്ടിരിക്കുന്നു? റസൂൽ(സ) പറഞ്ഞു: "അവളുടെ മേൽ അല്ലാഹുവിന്റെ ബറകതും രക്ഷയും സലാമും പറയുക. അവളെ അറിയിക്കുക, അത് -റമളാനിലെ ഉംറ- എന്റെ കൂടെയുള്ള ഹജ്ജിന് പകരം നിൽക്കും." (ദ,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], '?', null, 261, 261, true from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 37, 'عَنْ عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمَرَهُ أَنْ يُرْدِفَ عَائِشَةَ، فَيُعْمِرَهَا مِنَ التَّنْعِيمِ. (ق,ت,جه)', 'അബ്ദുർറഹ്മാനുബ്നു അബീബക്ർ(റ): ആഇശ(റ)യെ തൻഈമിൽ നിന്ന് ഉംറ ചെയ്യാൻ വേണ്ടി എന്റെ വാഹനത്തിനു പിന്നിലിരുത്തി കൊണ്ടുപോകാൻ റസൂൽ(സ) എന്നോട് കല്പിച്ചിരുന്നു. (ബു,മു,തു,ജ)', 'عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرٍ', 'അബ്ദുർറഹ്മാനുബ്നു അബീബക്ർ(റ)', null, null, array['ق','ت','جه']::text[], array['ബു','മു','തു','ജ']::text[], null, null, 261, 262, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 38, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: خَرَجْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي حَجَّةِ الْوَدَاعِ، نُوَافِي هِلَالَ ذِي الْحِجَّةِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ أَرَادَ مِنْكُمْ أَنْ يُهِلَّ بِعُمْرَةٍ فَلْيُهْلِلْ، فَلَوْلَا أَنِّي أَهْدَيْتُ لَأَهْلَلْتُ بِعُمْرَةٍ". قَالَتْ: فَكَانَ مِنَ الْقَوْمِ مَنْ أَهَلَّ بِعُمْرَةٍ، وَمِنْهُمْ مَنْ أَهَلَّ بِحَجٍّ، فَكُنْتُ أَنَا مِمَّنْ أَهَلَّ بِعُمْرَةٍ. قَالَتْ: فَخَرَجْنَا حَتَّى قَدِمْنَا مَكَّةَ، فَأَدْرَكَنِي يَوْمُ عَرَفَةَ وَأَنَا حَائِضٌ، لَمْ أَحِلَّ مِنْ عُمْرَتِي. فَشَكَوْتُ ذَلِكَ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: "دَعِي عُمْرَتَكِ، وَانْقُضِي رَأْسَكِ، وَامْتَشِطِي، وَأَهِلِّي بِالْحَجِّ". قَالَتْ: فَفَعَلْتُ، فَلَمَّا كَانَتْ لَيْلَةُ الْحَصْبَةِ، وَقَدْ قَضَى اللَّهُ حَجَّنَا، أَرْسَلَ مَعِي عَبْدَ الرَّحْمَنِ بْنَ أَبِي بَكْر. فَأَرْدَفَنِي وَخَرَجَ إِلَى التَّنْعِيمِ، فَأَهْلَلْتُ بِعُمْرَةٍ، فَقَضَى اللَّهُ حَجَّنَا وَعُمْرَتَنَا، وَلَمْ يَكُنْ فِي ذَلِكَ هَدْيٌ وَلَا صَدَقَةٌ وَلَا صَوْمٌ. (ق,جه)', 'ആഇശ(റ): ദുൽഹജ്ജിലെ നവചന്ദ്രനെ നേരിൽ കണ്ടവരായി ഞങ്ങൾ റസൂൽസ)യോടൊപ്പം ഹജ്ജതുൽ വദാഇ(വിടവാങ്ങൽ ഹജ്ജ്)നു പുറപ്പെട്ടു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ഉംറക്ക് ഇഹ്റാം ചെയ്യാനുദ്ദേശിച്ചവർ അതു ചെയ്യുക. ഞാൻ ഹദ്‌യ കൊണ്ടുവന്നിരുന്നില്ലെങ്കിൽ ഉംറക്ക് ഇഹ്റാം ചെയ്യുമായിരുന്നു." ആഇശ(റ) പറഞ്ഞു: ഹജ്ജിന് ഇഹ്റാം ചെയ്തവരും ഉംറക്ക് ഇഹ്റാം ചെയ്തവരും അക്കൂട്ടത്തിലുണ്ടായിരുന്നു. ഞാൻ ഉംറക്ക് ഇഹ്റാം ചെയ്തിരുന്നവരോടൊപ്പമായിരുന്നു. ആഇശ(റ) പറയുന്നു: അങ്ങനെ ഞങ്ങൾ മക്കയിലെത്തി. അറഫാ ദിനത്തിൽ ഞാൻ ആർത്തവകാരിയായി. ഞാനെന്റെ ഉംറയിൽ നിന്ന് മുക്തയായിട്ടുണ്ടായിരുന്നില്ല. ഞാൻ ഇതേച്ചൊല്ലി നബിയോട് പരാതിപ്പെട്ടു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നീ നിന്റെ ഉംറ ഒഴിവാക്കുക, മുടി ചീകുകയും മെടയുകയും ചെയ്യുക. പിന്നെ ഹജ്ജിന് ഇഹ്റാം ചെയ്യുക." ആഇശ തുടരുന്നു: ഞാനങ്ങനെ ചെയ്തു. കല്ലേറിന്റെ രാത്രിയാവുകയും അല്ലാഹു ഞങ്ങളുടെ ഹജ്ജിനെ പൂർത്തിയാക്കുകയും ചെയ്തപ്പോൾ റസൂൽ(സ) അബ്ദുർറഹ്മാനെ എന്നോടൊപ്പം അയച്ചു. അദ്ദേഹം എന്നെ പിന്നിലിരുത്തി തൻഈമിലേക്കു പുറപ്പെട്ടു. അങ്ങനെ ഞാൻ ഉംറക്ക് ഇഹ്റാം ചെയ്തു. അപ്പോൾ ഞങ്ങളുടെ ഹജ്ജും ഉംറയും സ്വീകരിച്ചു. ഇക്കാര്യത്തിൽ ഹദ്‌യയോ, സ്വദഖയോ നോമ്പോ പ്രായശ്ചിതമായി ഉണ്ടായിരുന്നില്ല. (ബു,മു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','جه']::text[], array['ബു','മു','ജ']::text[], null, null, 262, 262, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 39, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ مُعَاوِيَةَ بْنَ أَبِي سُفْيَانَ أَخْبَرَهُ قَالَ: قَصَّرْتُ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِمِشْقَصٍ وَهُوَ عَلَى الْمَرْوَةِ. أَوْ: رَأَيْتُهُ يُقَصَّرُ عَنْهُ بِمِشْقَصٍ وَهُوَ عَلَى الْمَرْوَةِ. (م)', 'ഇബ്നുഅബ്ബാസ്(റ): മുആവിയ(റ) എന്നോട് പറഞ്ഞു: റസൂൽ(സ) മർവയിലായിരിക്കെ ഒരു കത്രിക കൊണ്ട് ഞാൻ അവിടത്തെ മുടി വെട്ടി.. അല്ലെങ്കിൽ മർവയിലായിരിക്കെ ഒരു കത്രിക കൊണ്ട് തിരുമേനി(സ)യുടെ മുടി വെട്ടുന്നത് ഞാൻ കണ്ടു. (മു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 262, 262, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 40, 'عَنْ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ الْفَضْلُ بْنُ عَبَّاسٍ رَدِيفَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ، وَسَلَّمَ فَجَاءَتْهُ امْرَأَةٌ مِنْ خَثْعَمَ تَسْتَفْتِيهِ، وَجَعَلَ الْفَضْلُ يَنْظُرُ إِلَيْهَا وَتَنْظُرُ إِلَيْهِ، وَجَعَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَصْرِفُ وَجْهَ الْفَضْلِ إِلَى الشِّقِّ الْآخَرِ، فَقَالَتْ: يَا رَسُولَ اللَّهِ، إِنَّ فَرِيضَةَ اللَّهِ فِي الْحَجِّ عَلَى عِبَادِهِ أَدْرَكَتْ أَبِي شَيْخًا كَبِيرًا، لَا يَسْتَطِيعُ أَنْ يَثْبُتَ عَلَى الرَّاحِلَةِ، أَفَأَحُجُّ عَنْهُ؟ قَالَ: "نَعَمْ". وَذَلِكَ فِي حَجَّةِ الْوَدَاعِ. (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): ഫള്ലുബ്നു അബ്ബാസ്(റ) റസൂൽ(സ)യുടെ സഹയാത്രികനായരിക്കെ ഖസ്അം ഗോത്രത്തിൽപ്പെട്ട ഒരു സ്ത്രീ റസൂൽ(സ)യോട് ഫത്വ ചോദിക്കാൻ വന്നു. ഫള്ൽ അവളേയും അവൾ ഫള്ൽ(റ)വിനേയും നോക്കിക്കൊണ്ടിരുന്നു. റസൂൽ(സ) ഫള്ൽ(റ)വിന്റെ മുഖം മറ്റൊരു ഭാഗത്തേക്ക് തിരിച്ചു. അവൾ ചോദിച്ചു: തന്റെ ദാസന്മാരുടെമേൽ ബാധ്യതയായ അല്ലാഹുവിനു വേണ്ടിയുള്ള ഹജ്ജ് കർമ്മം വൃദ്ധനായ എന്റെ പിതാവിന് നിർബന്ധമായിരിക്കുന്നു. അദ്ദേത്തന് വാഹനപ്പുറത്തിരിക്കാൻ കഴിയുകയില്ല. അതു കൊണ്ട് എന്റെ പിതാവിന് പകരം ഞാൻ ഹജ്ജ് നിർവ്വഹിക്കട്ടെയോ? അവിടന്ന് പറഞ്ഞു: "അതെ". ഹജ്ജതുൽ വിദാഇലാണ് ഈ സംഭവം. (ന)', 'عَبْدِ اللَّهِ بْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 262, 263, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 41, 'عَنِ الْفَضْلِ بْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّهُ كَانَ رَدِيفَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَجَاءَهُ رَجُلٌ فَقَالَ: يَا رَسُولَ اللَّهِ، إِنَّ أُمِّي عَجُوزٌ كَبِيرَةٌ، وَإِنْ حَمَلْتُهَا لَمْ تَسْتَمْسِكْ، وَإِنْ رَبَطْتُهَا خَشِيتُ أَنْ أَقْتُلَهَا؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَرَأَيْتَ لَوْ كَانَ عَلَى أُمِّكَ دَيْنٌ أَكُنْتَ قَاضِيَهُ". قَالَ: نَعَمْ. قَالَ: "فَحُجَّ عَنْ أُمِّكَ". (ن)', 'ഫള്ലുബ്നു അബ്ബാസ്(റ): അദ്ദേഹം റസൂൽ(സ)യുടെ സഹയാത്രികനായിരുന്നു. ഒരാൾ റസൂൽ(സ)യോട് ചോദിച്ചു: റസൂലേ, എന്റെ മാതാവ് അവശയായ വൃദ്ധയാണ്. ഞാനവരെ ചുമന്നാൽ അവർക്ക് നേരെ നിൽക്കാനാവില്ല. ഞാനവരെ കെട്ടിയിട്ടാൽ അവർ മരിച്ചു പോകുമെന്ന് ഭയക്കുന്നു. റസൂൽ(സ) ചോദിച്ചു: "അവർക്ക് കടമുണ്ടായിരുന്നെങ്കിൽ നീ അത് വീട്ടുമായിരുന്നില്ലേ?" അദ്ദേഹം പറഞ്ഞു: അതെ. റസൂൽ(സ) പറഞ്ഞു: "എങ്കിൽ ഉമ്മക്കു പകരമായി നീ ഹജ്ജ് ചെയ്യുക." (ന)', 'الْفَضْلِ بْنِ عَبَّاسٍ', 'ഫള്ലുബ്നു അബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 263, 263, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 42, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالرَّوْحَاءِ، فَلَقِيَ رَكْبًا فَسَلَّمَ عَلَيْهِمْ، قَالَ: "مَنِ الْقَوْمُ". فَقَالُوا: الْمُسْلِمُونَ، فَقَالُوا: فَمَنْ أَنْتُمْ؟ قَالُوا: "رَسُولُ اللَّهِ" صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَفَزِعَتِ امْرَأَةٌ فَأَخَذَتْ بِعَضُدِ صَبِيٍّ فَأَخْرَجَتْهُ مِنْ مِحَفَّتِهَا، قَالَتْ: يَا رَسُولَ اللَّهِ، هَلْ لِهَذَا حَجٌّ؟ قَالَ: "نَعَمْ، وَلَكِ أَجْرٌ". (م,د)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) റൗഹാഇലായിരിക്കെ ഒരു യാത്രാസംഘത്തെ കണ്ടു. റസൂൽ(സ) അവർക്ക് സലാം ചൊല്ലിക്കൊണ്ട് ചോദിച്ചു: "നിങ്ങൾ ഏതുകൂട്ടരാണ്?" അവർ പറഞ്ഞു: മുസ്ലികളാണ്. അവർ ചോദിച്ചു: നിങ്ങളാരാണ്? റസൂൽ(സ)യുടെ സംഘം പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരാണ്. അപ്പോൾ വെപ്രാളപ്പെട്ട ഒരു സ്ത്രീ ഒരു കുട്ടിയുടെ തോളിനു പിടിച്ച് തന്റെ മഞ്ചത്തിൽ നിന്ന് പുറത്തെടുത്ത് റസൂൽ(സ)യോട് ചോദിച്ചു: റസൂലേ, ഇവന് ഹജ്ജ് ചെയ്യാമോ? അവിടന്ന് പറഞ്ഞു: "ചെയ്യാം, പ്രതിഫലം നിനക്കാണ്." (മു,ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 263, 263, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 43, 'عَنِ السَّائِبِ بْنِ يَزِيدَ رَضِيَ اللهُ عَنْهُ قَالَ: حَجَّ بِي أَبِي مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي حَجَّةِ الْوَدَاعِ وَأَنَا ابْنُ سَبْعِ سِنِينَ". (خ,ت)', 'സാഇബുബ്നു യസീദ്(റ): എനിക്ക് ഏഴു വയസ്സായിരിക്കെ എന്റെ പിതാവ് എന്നെയും കൊണ്ടു ഹജ്ജതുൽ വിദാഇൽ റസൂൽ(സ)യോടൊപ്പം ഹജ്ജ് ചെയ്തു. (ബു,തു)', 'السَّائِبِ بْنِ يَزِيدَ', 'സാഇബുബ്നു യസീദ്(റ)', null, null, array['خ','ت']::text[], array['ബു','തു']::text[], null, null, 263, 264, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 44, 'عَنْ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لِرَجُلٍ: "أَنْتَ أَكْبَرُ وَلَدِ أَبِيكَ؟ فَحُجَّ عَنْهُ". (ن)', 'ഇബ്നുസുബൈർ(റ): റസൂൽ(സ) ഒരാളോട് ചോദിച്ചു: "നീയാണോ ഉപ്പയുടെ മൂത്ത മകൻ? എങ്കിൽ നീ അദ്ദേഹത്തിന് പകരം ഹജ്ജ് ചെയ്യുക." (ന)', 'عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ', 'ഇബ്നുസുബൈർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 264, 264, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 45, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَمَرَتِ امْرَأَةٌ سِنَانَ بْنَ سَلَمَةَ الْجُهَنِيَّ أَنْ يَسْأَلَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَنَّ أُمَّهَا مَاتَتْ وَلَمْ تَحُجَّ، أَفَيُجْزِئُ عَنْ أُمِّهَا أَنْ تَحُجَّ عَنْهَا؟ قَالَ: "نَعَمْ، لَوْ كَانَ عَلَى أُمِّهَا دَيْنٌ فَقَضَتْهُ عَنْهَا، أَلَمْ يَكُنْ يُجْزِئُ عَنْهَا؟ فَلْتَحُجَّ عَنْ أُمِّهَا". (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): ഹജ്ജ് ചെയ്യാതെ മരണപ്പെട്ട തന്റെ മാതാവിനു പകരമായി താൻ ചെയ്താൽ മതിയാവുമോ എന്ന് റസൂൽ(സ)യോട് അന്വേഷിക്കാൻ സിനാനുബ്നു സലമ(റ)വിന്റെ ഭാര്യ എന്നോടാവശ്യപ്പെട്ടു. റസൂൽ(സ) അതിന് മറുപടി പറഞ്ഞു: "അതെ, തന്റെ മാതാവിന്റെ കടം അവൾ വീട്ടിയാൽ അത് വീട്ടിയതിന് പകരമാവില്ലേ? എങ്കിൽ ഉമ്മാക്കുപകരമായി അവൾ ഹജ്ജ് ചെയ്തുകൊള്ളട്ടെ." (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 264, 264, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 46, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ امْرَأَةً سَأَلَتِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ أَبِيهَا مَاتَ وَلَمْ يَحُجَّ؟ قَالَ: "حُجِّي عَنْ أَبِيكِ". (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): ഹജ്ജ് ചെയ്യാതെ മരണപ്പെട്ട തന്റെ പിതാവിനെക്കുറിച്ച് ഒരു സ്ത്രീ റസൂൽ(സ)യോട് ചോദിച്ചു: റസൂൽ(സ) പറഞ്ഞു: "നീ നിന്റെ ഉപ്പാക്കു പകരമായി ഹജ്ജ് ചെയ്യുക." (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 264, 264, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 47, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَمِعَ رَجُلًا يَقُولُ: لَبَّيْكَ عَنْ شُبْرُمَةَ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ شُبْرُمَةُ". قَالَ: قَرِيبٌ لِي. قَالَ: "هَلْ حَجَجْتَ قَطُّ؟". قَالَ: لَا، قَالَ: "فَاجْعَلْ هَذِهِ عَنْ نَفْسِكَ، ثُمَّ حُجَّ عَنْ شُبْرُمَةَ". (د,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): ലബ്ബൈക അൻ ശുബ്റുമ (ശബറുമക്കു പകരം ലബ്ബൈക) എന്ന് ഒരാൾ പറയുന്നത് റസൂൽ(സ) കേട്ടു. റസൂൽ(സ) ചോദിച്ചു: "ആരാണീ ശുബ്റുമ?" അദ്ദേഹം പറഞ്ഞു: എന്റെ ഒരു ബന്ധു. റസൂൽ(സ) ചോദിച്ചു: "നീ നിനക്ക് വേണ്ടി ഹജ്ജ് ചെയ്തിട്ടുണ്ടോ?" അദ്ദേഹം പറഞ്ഞു: ഇല്ല. റസൂൽ(സ) പറഞ്ഞു: "എങ്കിലിത് നിനക്കാക്കുക, പിന്നീട് ശുബ്റുമക്ക് വേണ്ടി ചെയ്യുക." (ദ,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 264, 264, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 48, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: جَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: أَحُجُّ عَنْ أَبِي؟ قَالَ: "نَعَمْ حُجَّ عَنْ أَبِيكَ، فَإِنْ لَمْ تَزِدْهُ خَيْرًا لَمْ تَزِدْهُ شَرًّا". (جه)', 'ഇബ്നുഅബ്ബാസ്(റ): ഒരാൾവന്ന് റസൂൽ(സ)യോട് ചോദിച്ചു: ഞാനെന്റെ പിതാവിനു പകരമായി ഹജ്ജ് ചെയ്യട്ടെയോ? റസൂൽ(സ) പറഞ്ഞു: "അതെ, നീ നിന്റെ ഉപ്പാക്കു പകരമായി ഹജ്ജ് ചെയ്യുക. നീ അദ്ദേഹത്തിന് നന്മ വർദ്ധിപ്പിച്ചില്ലെങ്കിലും തിന്മ വർദ്ധിപ്പിക്കാതിരിക്കുക." (ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 264, 265, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 49, 'عَنْ أَبِي الْغَوْثِ بْنِ حُصَيْنٍ رَضِيَ اللهُ عَنْهُ – رَجُلٌ مِنَ الْفُرْعِ: أَنَّهُ اسْتَفْتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ حَجَّةٍ كَانَتْ عَلَى أَبِيهِ، مَاتَ وَلَمْ يَحُجَّ؟ قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "حُجَّ عَنْ أَبِيكَ". وَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "وَكَذَلِكَ الصِّيَامُ فِي النَّذْرِ، يُقْضَى عَنْهُ". (جه)', 'അബുൽഗൗസിബ്നു ഹുസ്വൈൻ(റ) (അദ്ദേഹം മക്കയുടെയും മദീനയുടെയുമിടയിലുള്ള ഫുർഅ് സ്വദേശിയാണ്.) ഹജ്ജ് ബാധ്യതയായിട്ടും അത് ചെയ്യാതെ മരണപ്പെട്ട തന്റെ പിതാവിന്റെ ഹജ്ജിനെപ്പറ്റി അദ്ദേഹം റസൂൽ(സ)യോട് ഫത്വ ചോദിച്ചു. റസൂൽ(സ) പറഞ്ഞു: "നീ നിന്റെ ഉപ്പാക്കു പകരമായി ഹജ്ജ് ചെയ്യുക." റസൂൽ(സ) തുടർന്നു: "അപ്രകാരം തന്നെ നേർച്ചയാക്കിയ നോമ്പും അദ്ദേഹത്തിന് പകരം വീട്ടപ്പെടേണ്ടതാണ്." (ജ)', 'أَبِي الْغَوْثِ بْنِ حُصَيْنٍ', 'അബുൽഗൗസിബ്നു ഹുസ്വൈൻ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 265, 265, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 50, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ امْرَأَةً نَذَرَتْ أَنْ تَحُجَّ فَمَاتَتْ، فَأَتَى أَخُوهَا النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَسَأَلَهُ عَنْ ذَلِكَ، فَقَالَ: "أَرَأَيْتَ لَوْ كَانَ عَلَى أُخْتِكَ دَيْنٌ، أَكُنْتَ قَاضِيَهُ؟". قَالَ: نَعَمْ. قَالَ: "فَاقْضُوا اللَّهَ، فَهُوَ أَحَقُّ بِالْوَفَاءِ". (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): ഹജ്ജ് നേർച്ചയാക്കിയ ഒരു സ്ത്രീ മരിച്ചു. അവരുടെ സഹോദരൻ അക്കാര്യത്തെക്കുറിച്ച് റസൂൽ(സ)യോട് ചോദിച്ചു. റസൂൽ(സ) പറഞ്ഞു: "നിന്റെ സഹോദരിക്ക് കടമുണ്ടായിരുന്നെങ്കിൽ നീ അത് കൊടുത്തു വീട്ടുമായിരുന്നില്ലേ?." അയാൾ പറഞ്ഞു: അതെ. റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ കടം നിങ്ങൾ വീട്ടുക. അവനത്രെ കടം വീട്ടാൻ ഏറ്റവും അർഹൻ" (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 265, 265, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 51, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا إِذَا حَجَجْنَا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: فَكُنَّا نُلَبِّي عَنِ النِّسَاءِ، وَنَرْمِي عَنِ الصِّبْيَانِ. (ت,جه)', 'ജാബിർ(റ): ഞങ്ങൾ റസൂൽ(സ)യോടൊപ്പം ഹജ്ജ് ചെയ്യുമ്പോൾ സ്ത്രീകൾക്കു പകരം തൽബിയത്തും, കുട്ടികൾക്കു പകരം എറിയലും ഞങ്ങളാണ് നടത്തിയിരുന്നത്. (തു,ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 265, 265, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 52, 'عَنْ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ امْرَأَةً مِنْ خَثْعَمٍ جَاءَتِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: يَا رَسُولَ اللَّهِ، إِنَّ أَبِي شَيْخٌ كَبِيرٌ، قَدْ أَفْنَدَ، وَأَدْرَكَتْهُ فَرِيضَةُ اللَّهِ عَلَى عِبَادِهِ فِي الْحَجِّ، وَلَا يَسْتَطِيعُ أَدَاءَهَا، فَهَلْ يُجْزِئُ عَنْهُ أَنْ أُؤَدِّيَهَا عَنْهُ؟ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "نَعَمْ". (جه)', 'ഇബ്നുഅബ്ബാസ്(റ): ഒരു ഖസ്അം ഗോത്രക്കാരി വന്ന് റസൂൽ(സ)യോട് ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരേ, എന്റെ പിതാവ് വയോവൃദ്ധനാണ്. അല്ലാഹുവിനുവേണ്ടി, ജനങ്ങളുടെമേൽ ബാധ്യതയായ ഹജ്ജ് അദ്ദേഹത്തിന് വന്നെത്തിയിട്ടുണ്ട്. അതു നിർവ്വഹിക്കാൻ അദ്ദേഹത്തിനു സാധിക്കില്ല. അദ്ദേഹത്തിന്റെ പകരമായി ഞാൻ ചെയ്താൽ മതിയാവുമോ? റസൂൽ(സ) പറഞ്ഞു: "അതെ." (ജ)', 'عَبْدِ اللَّهِ بْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 265, 266, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 53, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: أَخْبَرَنِي حُصَيْنُ بْنُ عَوْفٍ قَالَ: قُلْتُ: يَا رَسُولَ اللَّهِ، إِنَّ أَبِي أَدْرَكَهُ الْحَجُّ، وَلَا يَسْتَطِيعُ أَنْ يَحُجَّ إِلَّا مُعْتَرِضًا. فَصَمَتَ سَاعَةً، ثُمَّ قَالَ: "حُجَّ عَنْ أَبِيكَ". (جه)', 'ഇബ്നുഅബ്ബാസ്(റ): ഹുസ്വൈനുബ്നു ഔഫ്(റ) എന്നോട് പറഞ്ഞു: ഞാൻ ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരേ, എന്റെ പിതാവിന് ഹജ്ജ് നിർബന്ധമായിരിക്കുന്നു. ബുദ്ധിമുട്ടില്ലാതെ ഹജ്ജ് നിർവ്വഹിക്കാൻ അദ്ദേഹത്തിന് സാധിക്കില്ല. റസൂൽ(സ) അൽപനേരം നിശ്ശബ്ദനായശേഷം പറഞ്ഞു: "പിതാവിനു പകരം നീ ഹജ്ജ് ചെയ്യുക." (ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 266, 266, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 54, 'عَنْ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ رَضِيَ اللهُ عَنْهُ قَالَ: جَاءَ رَجُلٌ مِنْ خَثْعَمَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: إِنَّ أَبِي شَيْخٌ كَبِيرٌ، لَا يَسْتَطِيعُ الرُّكُوبَ، وَأَدْرَكَتْهُ فَرِيضَةُ اللَّهِ فِي الْحَجِّ، فَهَلْ يُجْزِئُ أَنْ أَحُجَّ عَنْهُ؟ قَالَ: "آنْتَ أَكْبَرُ وَلَدِهِ؟ قَالَ: نَعَمْ. قَالَ: "أَرَأَيْتَ لَوْ كَانَ عَلَيْهِ دَيْنٌ أَكُنْتَ تَقْضِيهِ؟". قَالَ: نَعَمْ. قَالَ: "فَحُجَّ عَنْهُ". (ن)', 'അബ്ദുല്ലാഹിബ്നു സുബൈർ(റ): ഒരു ഖസ്അം ഗോത്രക്കാരൻ റസൂൽ(സ)യോട് ചോദിച്ചു: എന്റെ പിതാവ് വാഹനം കയറാൻ സാധിക്കാത്ത വയോവൃദ്ധനാണ്. അല്ലാഹുവിന് വേണ്ടിയുള്ള ഹജ്ജ് അദ്ദേഹത്തിന് നിർബന്ധമായിരിക്കുന്നു. അത് ഞാൻ ചെയ്താൽ മതിയാകുമോ? റസൂൽ(സ) ചോദിച്ചു: "നിങ്ങളാണോ അദ്ദേഹത്തിന്റെ മൂത്ത പുത്രൻ?" അയാൾ പറഞ്ഞു: അതെ. റസൂൽ(സ) ചോദിച്ചു: "പിതാവിന് കടമുണ്ടെങ്കിൽ നീ വീട്ടുകയില്ലേ?" അയാൾ പറഞ്ഞു: വീട്ടും. റസൂൽ(സ) പറഞ്ഞു: "എങ്കിൽ അദ്ദേഹത്തിനു പകരമായി നീ ഹജ്ജ് ചെയ്യുക." (ന)', 'عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ', 'അബ്ദുല്ലാഹിബ്നു സുബൈർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 266, 266, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 55, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَجُلٌ: يَا رَسُولَ اللَّهِ، إِنَّ أَبِي مَاتَ وَلَمْ يَحُجَّ، أَفَأَحُجُّ عَنْهُ؟ قَالَ: "أَرَأَيْتَ لَوْ كَانَ عَلَى أَبِيكَ دَيْنٌ أَكُنْتَ قَاضِيَهُ؟". قَالَ: نَعَمْ. قَالَ: "فَدَيْنُ اللَّهِ أَحَقُّ". (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): ഒരാൾ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, എന്റെ പിതാവ് ഹജ്ജ് ചെയ്യാതെ മരണപ്പെട്ടു. അദ്ദേഹത്തിന് പകരം ഞാൻ ഹജ്ജ് ചെയ്യട്ടെയോ? റസൂൽ(സ) ചോദിച്ചു: "നിന്റെ പിതാവിന് കടം ഉണ്ടായിരുന്നെങ്കിൽ നീ അത് വീട്ടുമായിരുന്നില്ലേ?." അയാൾ പറഞ്ഞു: അതെ. റസൂൽ(സ) പറഞ്ഞു: "എങ്കിൽ അല്ലാഹുവിന്റെ കടമാണ് ഏറ്റവും വീട്ടാൻ അർഹമായത്." (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 266, 266, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 56, 'عَنْ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَجُلًا سَأَلَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ أَبِي أَدْرَكَهُ الْحَجُّ، وَهُوَ شَيْخٌ كَبِيرٌ لَا يَثْبُتُ عَلَى رَاحِلَتِهِ، فَإِنْ شَدَدْتُهُ خَشِيتُ أَنْ يَمُوتَ، أَفَأَحُجُّ عَنْهُ؟ قَالَ: "أَرَأَيْتَ لَوْ كَانَ عَلَيْهِ دَيْنٌ فَقَضَيْتَهُ، أَكَانَ مُجْزِئًا؟". قَالَ: نَعَمْ. قَالَ: "فَحُجَّ عَنْ أَبِيكَ". (ن)', 'അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ): ഒരാൾ റസൂൽ(സ)യോട് ചോദിച്ചു: എന്റെ പിതാവിന് ഹജ്ജ് നിൻബന്ധമായിരിക്കുന്നു. അദ്ദേഹം വൃദ്ധനും വാഹനത്തിൽ നന്നായി ഇരിക്കാൻ കഴിയാത്തവനുമാണ്. അദ്ദേഹത്തെ വാഹനത്തിൻമേൽ കെട്ടിയാൽ മരിക്കുമോ എന്ന് ഞാൻ ഭയപ്പെടുന്നു. അദ്ദേഹത്തിനു പകരം ഞാൻ ഹജ്ജ് ചെയ്യട്ടെയോ? റസൂൽ(സ) ചോദിച്ചു: "അദ്ദേഹത്തിനു കടമുണ്ടെങ്കിൽ നീ വീട്ടിയാൽ പകരമാവില്ലേ?" അയാൾ പറഞ്ഞു: അതെ. റസൂൽ(സ) പറഞ്ഞു: "എങ്കിൽ പിതാവിനു പകരം നീ ഹജ്ജ് ചെയ്യുക." (ന)', 'عَبْدِ اللَّهِ بْنِ عَبَّاسٍ', 'അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 266, 266, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 57, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "السَّفَرُ قِطْعَةٌ مِنَ الْعَذَابِ، يَمْنَعُ أَحَدَكُمْ نَوْمَهُ وَطَعَامَهُ وَشَرَابَهُ، فَإِذَا قَضَى أَحَدُكُمْ نَهْمَتَهُ فَلْيُعَجِّلْ إِلَى أَهْلِهِ". (ق,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "യാത്ര ശിക്ഷയുടെ ഒരു കഷ്ണമാണ്. അത് നിങ്ങളുടെ ഓരോരുത്തരുടെയും ഭക്ഷണവും പാനീയവും ഉറക്കവും തടയുന്നു. അതിനാൽ നിങ്ങളിലൊരാൾ യാത്രോദ്ദേശ്യം നിറവേറ്റിയാൽ ധൃതിയിൽ തന്റെ കുടുംബത്തിലേക്കു മടങ്ങിക്കൊള്ളട്ടെ." (ബു,മു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','جه']::text[], array['ബു','മു','ജ']::text[], null, null, 267, 267, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 58, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُ ، عَنِ الْفَضْلِ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ أَرَادَ الْحَجَّ فَلْيَتَعَجَّلْ، فَإِنَّهُ قَدْ يَمْرَضُ الْمَرِيضُ، وَتَضِلُّ الضَّالَّةُ، وَتَعْرِضُ الْحَاجَةُ". (د,جه)', 'ഫള്ലുബ്നു അബ്ബാസ്(റ)വിൽ നിന്ന് ഇബ്നു അബ്ബാസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ഹജ്ജ് ഉദ്ദേശിച്ചവൻ അത് ഉടനെ നിർവ്വഹിക്കട്ടെ.കാരണം ചിലപ്പോൾ രോഗംവന്ന് രോഗി ആയേക്കാം, വാഹനം നഷ്ടപ്പെട്ടേക്കാം, (പുതിയ) ആവശ്യങ്ങൾ വന്നേക്കാം." (ദ,ജ)', 'ابْنِ عَبَّاسٍ', 'ഫള്ലുബ്നു അബ്ബാസ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 267, 267, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 59, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَا يَطْرُقُ أَهْلَهُ، كَانَ لَا يَدْخُلُ إِلَّا غُدْوَةً أَوْ عَشِيَّةً. (خ)', 'അനസ്(റ): തിരുമേനി(സ) ദീർഘയാത്രയിൽ പുറത്തു പോയാൽ രാത്രി തിരിച്ചുവരാറുണ്ടായിരുന്നില്ല. അവിടന്ന് രാവിലെയോ സായാഹ്നത്തിലോ മാത്രമേ വീട്ടിൽ മടങ്ങിവരാറുണ്ടായിരുന്നുള്ളൂ. (ബു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 267, 267, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 60, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: نَهَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يَطْرُقَ أَهْلَهُ لَيْلًا. (خ)', 'ജാബിർ(റ): യാത്രയിൽ നിന്ന് രാത്രി അസമയത്തു വീട്ടിൽ തിരിച്ചെത്തുന്നത് തിരുമേനി(സ) നിരോധിച്ചിരിക്കുന്നു. (ബു)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 267, 267, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 61, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: خَرَجْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِخَمْسٍ بَقِينَ مِنْ ذِي الْقَعْدَةِ، لَا نُرَى إِلَّا الْحَجَّ، حَتَّى إِذَا دَنَوْنَا مِنْ مَكَّةَ أَمَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَنْ لَمْ يَكُنْ مَعَهُ هَدْيٌ إِذَا طَافَ بِالْبَيْتِ أَنْ يَحِلَّ. (ن)', 'ആഇശ(റ): ഞങ്ങൾ ദുൽഖഅദ് ഇരുപത്തിയഞ്ചിന് ഹജ്ജ് മാത്രം കരുതി റസൂൽ(സ)യോടൊപ്പം പുറപ്പെട്ടു. മക്കയോടടുത്തപ്പോൾ ഹദ്‌യ കൊണ്ടുവരാത്തവരോട് ത്വവാഫിനു ശേഷം തഹല്ലുലാ(ഇഹ്റാമിൽ നിന്നൊഴിവാകാൻ)വാൻ റസൂൽ(സ) കൽപിച്ചു. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 267, 267, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 62, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: خَرَجْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي حَجَّةِ الْوَدَاعِ، نُوَافِي هِلَالَ ذِي الْحِجَّةِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ أَرَادَ مِنْكُمْ أَنْ يُهِلَّ بِعُمْرَةٍ فَلْيُهْلِلْ، فَلَوْلَا أَنِّي أَهْدَيْتُ لَأَهْلَلْتُ بِعُمْرَةٍ". قَالَتْ: فَكَانَ مِنَ الْقَوْمِ مَنْ أَهَلَّ بِعُمْرَةٍ، وَمِنْهُمْ مَنْ أَهَلَّ بِحَجٍّ، فَكُنْتُ أَنَا مِمَّنْ أَهَلَّ بِعُمْرَةٍ. قَالَتْ: فَخَرَجْنَا حَتَّى قَدِمْنَا مَكَّةَ، فَأَدْرَكَنِي يَوْمُ عَرَفَةَ وَأَنَا حَائِضٌ، لَمْ أَحِلَّ مِنْ عُمْرَتِي. فَشَكَوْتُ ذَلِكَ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: "دَعِي عُمْرَتَكِ، وَانْقُضِي رَأْسَكِ، وَامْتَشِطِي، وَأَهِلِّي بِالْحَجِّ". قَالَتْ: فَفَعَلْتُ، فَلَمَّا كَانَتْ لَيْلَةُ الْحَصْبَةِ، وَقَدْ قَضَى اللَّهُ حَجَّنَا، أَرْسَلَ مَعِي عَبْدَ الرَّحْمَنِ بْنَ أَبِي بَكْرٍ. فَأَرْدَفَنِي وَخَرَجَ إِلَى التَّنْعِيمِ، فَأَهْلَلْتُ بِعُمْرَةٍ، فَقَضَى اللَّهُ حَجَّنَا وَعُمْرَتَنَا، وَلَمْ يَكُنْ فِي ذَلِكَ هَدْيٌ وَلَا صَدَقَةٌ وَلَا صَوْمٌ. (ق,جه)', 'ആഇശ(റ): ദുൽഹജ്ജിലെ നവചന്ദ്രനെ നേരിൽ കണ്ടവരായി ഞങ്ങൾ റസൂൽസ)യോടൊപ്പം ഹജ്ജതുൽ വദാഇ(വിടവാങ്ങൽ ഹജ്ജ്)നു പുറപ്പെട്ടു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ഉംറക്ക് ഇഹ്റാം ചെയ്യാനുദ്ദേശിച്ചവർ അതു ചെയ്യുക. ഞാൻ ഹദ്‌യ കൊണ്ടുവന്നിരുന്നില്ലെങ്കിൽ ഉംറക്ക് ഇഹ്റാം ചെയ്യുമായിരുന്നു." ആഇശ(റ) പറഞ്ഞു: ഹജ്ജിന് ഇഹ്റാം ചെയ്തവരും ഉംറക്ക് ഇഹ്റാം ചെയ്തവരും അക്കൂട്ടത്തിലുണ്ടായിരുന്നു. ഞാൻ ഉംറക്ക് ഇഹ്റാം ചെയ്തിരുന്നവരോടൊപ്പമായിരുന്നു. ആഇശ(റ) പറയുന്നു: അങ്ങനെ ഞങ്ങൾ മക്കയിലെത്തി. അറഫാ ദിനത്തിൽ ഞാൻ ആർത്തവകാരിയായി. ഞാനെന്റെ ഉംറയിൽ നിന്ന് മുക്തയായിട്ടുണ്ടായിരുന്നില്ല. ഞാൻ ഇതേച്ചൊല്ലി നബിയോട് പരാതിപ്പെട്ടു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നീ നിന്റെ ഉംറ ഒഴിവാക്കുക, മുടി ചീകുകയും മെടയുകയും ചെയ്യുക. പിന്നെ ഹജ്ജിന് ഇഹ്റാം ചെയ്യുക." ആഇശ(റ) തുടരുന്നു: ഞാനങ്ങനെ ചെയ്തു. കല്ലേറിന്റെ രാത്രിയാവുകയും അല്ലാഹു ഞങ്ങളുടെ ഹജ്ജിനെ പൂർത്തിയാക്കുകയും ചെയ്തപ്പോൾ റസൂൽ(സ) അബ്ദുർറഹ്മാൻ(റ)വിനെ എന്നോടൊപ്പം അയച്ചു. അദ്ദേഹം എന്നെ പിന്നിലിരുത്തി തൻഈമിലേക്കു പുറപ്പെട്ടു. അങ്ങനെ ഞാൻ ഉംറക്ക് ഇഹ്റാം ചെയ്തു. അപ്പോൾ ഞങ്ങളുടെ ഹജ്ജും ഉംറയും സ്വീകരിച്ചു. ഇക്കാര്യത്തിൽ ഹദ്‌യയോ, സ്വദഖയോ, നോമ്പോ പ്രായശ്ചിതമായി ഉണ്ടായിരുന്നില്ല. (ബു,മു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','جه']::text[], array['ബു','മു','ജ']::text[], null, null, 267, 268, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 63, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَرْكَبُ رَاحِلَتَهُ بِذِي الْحُلَيْفَةِ، ثُمَّ يُهِلُّ حَتَّى تَسْتَوِيَ بِهِ قَائِمَةً. (خ)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) ദുൽഹുലൈഫയിൽ വെച്ചു വാഹനത്തിൽ കയറുന്നതും വാഹനം നേരെ നിൽക്കുംവരെ തൽബിയത്തു ചൊല്ലുന്നതും ഞാൻ കണ്ടു. (ബു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 268, 268, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 64, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَجَّ عَلَى رَحْلٍ وَكَانَتْ زَامِلَتَهُ. (خ)', 'അനസ്(റ): റസൂൽ(സ) ഒട്ടകക്കട്ടിലിൻമേൽ ഇരുന്നുകൊണ്ട് ഹജ്ജ് ചെയ്തു. ആ ഒട്ടകം തന്നെയാണ് തിരുമേനി(സ)യുടെ യാത്ര സാമഗ്രികൾ ചുമന്നിരുന്നത്. (ബു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 268, 268, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 65, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَخْرُجُ مِنْ طَرِيقِ الشَّجَرَةِ وَيَدْخُلُ مِنْ طَرِيقِ الْمُعَرَّسِ، وَأَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا خَرَجَ إِلَى مَكَّةَ يُصَلِّي فِي مَسْجِدِ الشَّجَرَةِ، وَإِذَا رَجَعَ صَلَّى بِذِي الْحُلَيْفَةِ بِبَطْنِ الْوَادِي، وَبَاتَ حَتَّى يُصْبِحَ. (خ)', 'അനസ്(റ): റസൂൽ(സ) ''ശജറ'' വഴി ഹജ്ജിന് പുറപ്പെടുകയും, (ഹജ്ജ് കഴിഞ്ഞ് തിരിച്ചു വരുമ്പോൾ) ''മുഅർറസി''ലൂടെ പ്രവേശിക്കുകയുമാണ് ചെയ്തിരുന്നത്. റസൂൽ(സ) മക്കയിലേക്കു പുറപ്പെട്ടാൽ ''ശജറ'' പള്ളിയിൽ വെച്ച് നിസ്കരിക്കും. ദുൽഹുലൈഫയിലെ താഴ്വരയുടെ നടുവിൽനിന്ന് മടക്കയാത്രയിൽ പ്രാർത്ഥിക്കും. പ്രഭാതംവരെ അവിടെ രാപ്പാർക്കുകയും ചെയ്യും. (ബു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 268, 268, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 66, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: حَجَّ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى رَحْلٍ رَثٍّ، وَقَطِيفَةٍ تُسَاوِي أَرْبَعَةَ دَرَاهِمَ، أَوْ لَا تُسَاوِي. ثُمَّ قَالَ: "اللَّهُمَّ، حَجَّةٌ لَا رِيَاءَ فِيهَا وَلَا سُمْعَةَ". (جه)', 'അനസ്(റ): റസൂൽ(സ) ബലഹീനമായ വാഹനപ്പുറത്തും നാലു ദിർഹമിനു സമാനമാവുന്ന ഒരു വെൽവെറ്റ് വസ്ത്രം ധരിച്ചുകൊണ്ടും - മറ്റൊരു നിവേദനത്തിൽ: സമാനമാകാത്ത - ഹജ്ജ് നിർവ്വഹിച്ചു. പിന്നെ അവിടന്ന് പറഞ്ഞു: "അല്ലാഹുവെ, കീർത്തിയോ, ലോകമാന്യമോ ഇല്ലാത്ത ഹജ്ജാണിത്." (ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 268, 268, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=4 and h.hadith_no=66), 1, null, 'മറ്റൊരു നിവേദനത്തിൽ: സമാനമാകാത്ത - ഹജ്ജ് നിർവ്വഹിച്ചു. പിന്നെ അവിടന്ന് പറഞ്ഞു: "അല്ലാഹുവെ, കീർത്തിയോ, ലോകമാന്യമോ ഇല്ലാത്ത ഹജ്ജാണിത്." (ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 67, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَيْنَ مَكَّةَ وَالْمَدِينَةِ، فَمَرَرْنَا بِوَادٍ، فَقَالَ: "أَيُّ وَادٍ هَذَا؟". قَالُوا: وَادِي الْأَزْرَقِ. قَالَ: "كَأَنِّي أَنْظُرُ إِلَى مُوسَى صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ – فَذَكَرَ مِنْ طُولِ شَعَرِهِ شَيْئًا، لَا يَحْفَظُهُ دَاوُدُ – وَاضِعًا إِصْبَعَيْهِ فِي أُذُنَيْهِ، لَهُ جُؤَارٌ إِلَى اللَّهِ بِالتَّلْبِيَةِ، مَارًّا بِهَذَا الْوَادِي". قَالَ: ثُمَّ سِرْنَا حَتَّى أَتَيْنَا عَلَى ثَنِيَّةٍ، فَقَالَ: "أَيُّ ثَنِيَّةٍ هَذِهِ". قَالُوا: ثَنِيَّةُ هَرْشَى أَوْ لَفْتٍ. قَالَ: "كَأَنِّي أَنْظُرُ إِلَى يُونُسَ، عَلَى نَاقَةٍ حَمْرَاءَ، عَلَيْهِ جُبَّةُ صُوفٍ، وَخِطَامُ نَاقَتِهِ خُلْبَةٌ، مَارًّا بِهَذَا الْوَادِي، مُلَبِّيًا". (م,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): ഞങ്ങൾ റസൂൽ(സ)യോടൊപ്പം മക്കാ മദീനക്കിടയിലുള്ള ഒരു താഴ്വരയിലെത്തിയപ്പോൾ റസൂൽ(സ) ചോദിച്ചു: "ഏതാണീ താഴ്വര?" അവർ പറഞ്ഞു: അസ്റഖ് ഗോത്രത്തിന്റെ താഴ്വരയാണ്. റസൂൽ(സ) പറഞ്ഞു: "ഞാൻ മൂസാ നബി(അ)യെ കാണുന്നത് പോലെ തോന്നുന്നു; ഉച്ചത്തിൽ തന്റെ ചെവികളിൽ വിരൽ വെച്ച് തൽബിയത് ചൊല്ലിക്കൊണ്ട് മൂസാനബി(അ) - മൂസാനബി(അ)ന്റെ മുടിയുടെ നീളത്തെപ്പറ്റി റസൂൽ(സ) പറഞ്ഞത് ദാവൂദ് (നിവേദകൻ) അത് ഓർക്കുന്നില്ല - ഈ ചെരുവിലൂടെ നടക്കുന്നത് ഞാൻ കാണുന്നതു പോലെയുണ്ട്." ഇബ്നുഅബ്ബാസ്(റ) പറയുന്നു: പിന്നെ ഞങ്ങൾ നടന്ന് ഇടുങ്ങിയ വഴിയിലെത്തി. റസൂൽ(സ) ചോദിച്ചു: ഏതാണീ ഇടുങ്ങിയ വഴി? അവർ പറഞ്ഞു: ഹർഷാ ഗോത്രത്തിന്റെ അല്ലെങ്കിൽ ലിഫ്ത്തിന്റെ ഭൂമിയാണിത്. റസൂൽ(സ) പറഞ്ഞു: "രോമത്തിന്റെ ജുബ്ബ ധരിച്ച്, മരത്തിന്റെ നാര് കൊണ്ട് മൂക്കുകയറുള്ള ചുവന്ന ഒട്ടകത്തിന്മേൽ കയറി, ഈ ചെരുവിലൂടെ തൽബിയ്യത്ത് ചൊല്ലിക്കൊണ്ട് വേഗത്തിൽ നടന്നു പോകുന്ന യൂനുസ് നബിയെ ഞാൻ കാണുന്നതു പോലെയുണ്ട്." (മു,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['م','جه']::text[], array['മു','ജ']::text[], null, null, 269, 269, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 68, 'عَنْ عَلِيٍّ الْأَزْدِيِّ رَضِيَ اللهُ عَنْهُ : أَنَّ ابْنَ عُمَرَ عَلَّمَهُمْ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا اسْتَوَى عَلَى بَعِيرِهِ خَارِجًا إِلَى سَفَرٍ كَبَّرَ ثَلَاثًا، ثُمَّ قَالَ: {سُبْحَانَ الَّذِي سَخَّرَ لَنَا هَذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ. وَإِنَّا إِلَى رَبِّنَا لَمُنْقَلِبُونَ} اللَّهُمَّ إِنَّا نَسْأَلُكَ فِي سَفَرِنَا هَذَا الْبِرَّ وَالتَّقْوَى، وَمِنَ الْعَمَلِ مَا تَرْضَى. اللَّهُمَّ هَوِّنْ عَلَيْنَا سَفَرَنَا هَذَا وَاطْوِ عَنَّا بُعْدَهُ. اللَّهُمَّ أَنْتَ الصَّاحِبُ فِي السَّفَرِ، وَالْخَلِيفَةُ فِي الْأَهْلِ. اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ وَعْثَاءِ السَّفَرِ، وَكَآبَةِ الْمَنْظَرِ، وَسُوءِ الْمُنْقَلَبِ فِي الْمَالِ وَالْأَهْلِ". وَإِذَا رَجَعَ قَالَهُنَّ، وَزَادَ فِيهِنَّ: "آيِبُونَ تَائِبُونَ عَابِدُونَ، لِرَبِّنَا حَامِدُونَ". (م)', 'അലിയ്യുൽ അസ്ദീ(റ): ഇബ്നുഉമർ(റ) അവരെ പഠിപ്പിച്ചു: റസൂൽ(സ) വല്ല യാത്രക്കും പുറപ്പെടാനായി തന്റെ വാഹനത്തിന്മേൽ ഇരുന്നാൽ മൂന്നു തവണ തക്ബീർ ചൊല്ലും. പിന്നെ പറയും: "ഞങ്ങൾക്കീ വാഹനത്തെ കീഴടക്കിത്തന്നവനാണ് പരിശുദ്ധൻ. അല്ലെങ്കിൽ അതിനെ മെരുക്കാൻ ഞങ്ങൾക്കാവില്ല. നാം നമ്മുടെ നാഥനിലേക്ക് മടങ്ങുന്നവരാണ്. ഞങ്ങളുടെ ഈ യാത്രയിൽ നന്മയും നിന്നെ തൃപ്തനാക്കുന്ന പ്രവൃത്തിയും ഞങ്ങൾ തേടുന്നു. അല്ലാഹുവെ, ഈ യാത്ര ഞങ്ങൾക്ക് എളുപ്പമാക്കുകയും ദൂരം ചുരുക്കിത്തരികയും ചെയ്യേണമേ. അല്ലാഹുവെ, നീയാണ് യാത്രയിലെ കൂട്ടാളി, കുടുംബത്തിലെ പകരക്കാരൻ. അല്ലാഹുവെ, യാത്രയിലെ ക്ലേശത്തിൽ നിന്നും ദുഃഖ ദൃശ്യത്തിൽ നിന്നും കുടുംബത്തിലും സ്വത്തിലും മോശമായ പരിവർത്തനത്തിൽ നിന്നും ഞാൻ നിന്നോട് കാവൽ തേടുന്നു." മടങ്ങിവന്നാൽ റസൂൽ(സ) ഇതോടൊപ്പം ഇതുകൂടി കൂട്ടും: "ഞങ്ങളുടെ രക്ഷിതാവിനെ സ്തുതിച്ചും അവനെ ആരാധിച്ചും പശ്ചാത്തപിച്ചും ഞങ്ങളിതാ മടങ്ങുന്നു." (മു)', 'عَلِيٍّ الْأَزْدِيِّ', 'അലിയ്യുൽ അസ്ദീ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 269, 269, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 69, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَخْطُبُ يَقُولُ: "لَا يَخْلُوَنَّ رَجُلٌ بِامْرَأَةٍ إِلَّا وَمَعَهَا ذُو مَحْرَمٍ، وَلَا تُسَافِرِ الْمَرْأَةُ إِلَّا مَعَ ذِي مَحْرَمٍ". فَقَامَ رَجُلٌ فَقَالَ: يَا رَسُولَ اللَّهِ، إِنَّ امْرَأَتِي خَرَجَتْ حَاجَّةً، وَإِنِّي اكْتُتِبْتُ فِي غَزْوَةِ كَذَا وَكَذَا، قَالَ: "انْطَلِقْ فَحُجَّ مَعَ امْرَأَتِكَ". (م)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) പ്രസംഗിക്കുന്നത് ഞാൻ കേട്ടു: "ഒരു സ്ത്രീയോടൊപ്പം ഒരു പുരുഷൻ ഒറ്റക്കാവാൻ പാടില്ല; അവളോടൊപ്പം വിവാഹം നിഷിദ്ധമായ ഒരാളുണ്ടായിരിക്കുമ്പോഴല്ലാതെ. വിവാഹം നിഷിദ്ധമായ ഒരാളോടൊപ്പമല്ലാതെ ഒരു സ്ത്രീ യാത്രചെയ്യാൻ പാടില്ല." അപ്പോൾ ഒരാൾ എഴുന്നേറ്റ് നിന്ന് ചോദിച്ചു: റസൂലേ, എന്റെ ഭാര്യ ഹജ്ജിനായി പുറപ്പെടുന്നുണ്ട്. ഞാൻ ഇന്നാലിന്ന യുദ്ധത്തിൽ പങ്കെടുക്കാൻ നിശ്ചയിച്ചിട്ടുണ്ട്. റസൂൽ(സ) പറഞ്ഞു: "നീ പോയി അവളോടൊപ്പം ഹജ്ജ് ചെയ്യുക." (മു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 270, 270, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 70, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا يَحِلُّ لِامْرَأَةٍ مُسْلِمَةٍ تُسَافِرُ مَسِيرَةَ لَيْلَةٍ إِلَّا وَمَعَهَا رَجُلٌ ذُو حُرْمَةٍ مِنْهَا". (م,د,جه)
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=4 and h.hadith_no=70), 1, 'وَفِي رِوَايَةٍ: قَالَ: "لَا يَحِلُّ لِامْرَأَةٍ مُسْلِمَةٍ تُسَافِرُ مَسِيرَةَ لَيْلَةٍ". فَذَكَرَ مَعْنَاهُ.', 'മറ്റൊരു നിവേദനത്തിൽ: റസൂൽ(സ) പറഞ്ഞു: "ഒരു മുസ്ലിം സ്ത്രീ രാത്രിയുടെ വഴിദൂരമത്രയും യാത്ര ചെയ്യൽ (മഹ്റമില്ലാതെ) അനുവദനീയമല്ല." ശേഷം മൂന്നാമത്തേതിന്റെ ആശയം പറഞ്ഞു.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=4 and h.hadith_no=70), 2, 'وَفِي رِوَايَةٍ: فَذَكَرَ نَحْوَهُ، إِلَّا أَنَّهُ قَالَ: "بَرِيدًا". (د)', 'മറ്റൊരു നിവേദനത്തിൽ: അതേ ഹദീസ് പറഞ്ഞു, അതിൽ ഇപ്രകാരം കൂടിയുണ്ട്: "പന്ത്രണ്ട് മൈൽ ദൂരം" (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 71, 'عَنْ أَبِي سَعِيدٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا يَحِلُّ لِامْرَأَةٍ تُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ: أَنْ تُسَافِرَ سَفَرًا فَوْقَ ثَلَاثَةِ أَيَّامٍ فَصَاعِدًا إِلَّا وَمَعَهَا أَبُوهَا، أَوْ أَخُوهَا، أَوْ زَوْجُهَا، أَوِ ابْنُهَا، أَوْ ذُو مَحْرَمٍ مِنْهَا". (ق,د,ت,جه)', 'അബൂസഈദ്(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവിലും അന്ത്യനാളിലും വിശ്വസിക്കുന്ന സ്ത്രീക്ക് മൂന്നോ അതിൽ കൂടിയ ദിവസങ്ങളോ ഉള്ള യാത്ര, അവളോടൊപ്പം തന്റെ ഉപ്പയോ, സഹോദരനോ ഭർത്താവോ മകനോ മഹ്റമോ ഇല്ലാതെ അനുവദനീയമല്ല." (ബു,മു,ദ,തു,ജ)', 'أَبِي سَعِيدٍ', 'അബൂസഈദ്(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 270, 270, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 72, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُ : كَانَ يُرْدِفُ مَوْلَاةً لَهُ يُقَالُ لَهَا صَفِيَّةُ، تُسَافِرُ مَعَهُ إِلَى مَكَّةَ. (د)', 'ഇബ്നുഉമർ(റ): സ്വഫിയ എന്നു പേരുള്ള തന്റെ അടിമയെ അദ്ദേഹം തന്റെ കൂടെ യാത്ര ചെയ്യിക്കാറുണ്ടായിരുന്നു. അവൾ അദ്ദേഹത്തോടൊപ്പം മക്കയിലേക്ക് യാത്ര ചെയ്യുമായിരുന്നു. (ദ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 270, 270, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 73, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا صَرُورَةَ فِي الْإِسْلَامِ". (د)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "(കൂടെ യാത്ര ചെയ്യുന്ന മഹ്റമിനെ ലഭിക്കാത്തതിനാൽ) ഹജ്ജ് ചെയ്യാതിരിക്കുന്നത് ഇസ്ലാമിൽ പെട്ടതല്ല." (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 270, 271, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 74, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُ : أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا أَدْخَلَ رِجْلَهُ فِي الْغَرْزِ، وَاسْتَوَتْ بِهِ رَاحِلَتُهُ، أَهَلَّ مِنْ عِنْدِ مَسْجِدِ ذِي الْحُلَيْفَةِ. (جه)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) അങ്കവടി(ജീനിയിൽ നിന്നും തൂക്കിയിടുന്ന കാൽ വെക്കാനുള്ള വളയം)യിൽ ചവിട്ടുകയും വാഹനം നേരെ നിൽക്കുകയും ചെയ്താൽ ദുൽഹുലൈഫയിലെ പള്ളിക്കടുത്തു വെച്ച് ഇഹ്റാം ചെയ്യാറുണ്ടായിരുന്നു. (ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 271, 271, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 75, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: إِنِّي عِنْدَ ثَفِنَاتِ نَاقَةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عِنْدَ الشَّجَرَةِ، فَلَمَّا اسْتَوَتْ بِهِ قَائِمَةً قَالَ: "لَبَّيْكَ بِعُمْرَةٍ وَحَجَّةٍ مَعًا". وَذَلِكَ فِي حَجَّةِ الْوَدَاعِ. (جه)', 'അനസുബ്നു മാലിക്(റ): ശജറക്കടുത്ത് റസൂൽ(സ)യുടെ ഒട്ടകത്തിന്റെ കാൽമുട്ടിനരികെയായിരുന്നു ഞാൻ. ഒട്ടകം നേരെ നിന്നപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ഹജ്ജിനും ഉംറക്കും ഒന്നിച്ച് ഉത്തരം നൽകുന്നു." അത് വിടവാങ്ങൽ ഹജ്ജിലായിരുന്നു. (ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 271, 271, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 76, 'عَنِ السَّائِبِ بْنِ خَلَّادٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "جَاءَنِي جِبْرِيلُ فَقَالَ لِي: يَا مُحَمَّدُ، مُرْ أَصْحَابَكَ فَلْيَرْفَعُوا أَصْوَاتَهُمْ بِالتَّلْبِيَةِ". (ن)', 'സാഇബുബ്നു ഖല്ലാദ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ജിബ്രീൽ എന്റെ അടുത്തുവന്ന് പറഞ്ഞു: മുഹമ്മദ്(സ), തൽബിയത്തുകൊണ്ട് ശബ്ദമുയർത്താൻ അങ്ങയുടെ അനുയായികളോട് കൽപിക്കുക." (ന)', 'السَّائِبِ بْنِ خَلَّادٍ', 'സാഇബുബ്നു ഖല്ലാദ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 271, 271, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 77, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُ ، وَقَدْ سُئِلَ عَنْ حَجَّةِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَحَدَّثَ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَكَثَ بِالْمَدِينَةِ تِسْعَ حِجَجٍ، ثُمَّ أُذِّنَ فِي النَّاسِ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي حَاجٍّ هَذَا الْعَامِ، فَنَزَلَ الْمَدِينَةَ بَشَرٌ كَثِيرٌ، كُلُّهُمْ يَلْتَمِسُ: أَنْ يَأْتَمَّ بِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَيَفْعَلَ مَا يَفْعَلُ، فَخَرَجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِخَمْسٍ بَقِينَ مِنْ ذِي الْقَعْدَةِ وَخَرَجْنَا مَعَهُ. قَالَ جَابِرٌ: وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَيْنَ أَظْهُرِنَا، عَلَيْهِ يَنْزِلُ الْقُرْآنُ، وَهُوَ يَعْرِفُ تَأْوِيلَهُ، وَمَا عَمِلَ بِهِ مِنْ شَيْءٍ عَمِلْنَا، فَخَرَجْنَا لَا نَنْوِي إِلَّا الْحَجَّ. (ن)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): റസൂൽ(സ)യുടെ ഹജ്ജിനെക്കുറിച്ച് ചോദിക്കപ്പെട്ടപ്പോൾ അദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ) ഒമ്പത് വർഷം മദീനയിൽ താമസിച്ചു. അതിനുശേഷം "ഈ വർഷം റസൂൽ(സ) ഹജ്ജിനു പുറപ്പെടുന്നു"വെന്ന് ജനങ്ങൾക്കിടയിൽ വിളംബരം ചെയ്യപ്പെട്ടു. റസൂൽ(സ)യെ പിൻതുടരാനും റസൂൽ(സ) ചെയ്യുന്നത് ചെയ്യാനും അനുവാദം തേടിക്കൊണ്ട് നിരവധിപേർ മദീനയിൽ ഇറങ്ങി. റസൂൽ(സ) ദുൽഖഅദ് ഇരുപത്തി അഞ്ചിന് പുറപ്പെട്ടു, കൂടെ ഞങ്ങളും. ജാബിർ(റ) പറഞ്ഞു: ഞങ്ങൾക്കിടയിലായിരിക്കെ തിരുദൂതർ(സ)ക്ക് ഖുർആൻ ഇറങ്ങിക്കൊണ്ടിരുന്നു. നബി(സ)ക്ക് അതിന്റെ വിശദീകരണമറിയാമായിരുന്നു. റസൂൽ(സ) ചെയ്യുന്നതപോലെ ഞങ്ങളും ചെയ്തു. ഹജ്ജ് അല്ലാതെ മറ്റൊരുദ്ദേശ്യവുമില്ലാതെ ഞങ്ങൾ പുറപ്പെട്ടു. (ന)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 271, 272, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 78, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: خَرَجْنَا لَا نَنْوِي إِلَّا الْحَجَّ، فَلَمَّا كُنَّا بِسَرِفَ حِضْتُ، فَدَخَلَ عَلَيَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَنَا أَبْكِي، فَقَالَ: "أَحِضْتِ؟". قُلْتُ: نَعَمْ. قَالَ: "إِنَّ هَذَا شَيْءٌ كَتَبَهُ اللَّهُ عَزَّ وَجَلَّ عَلَى بَنَاتِ آدَمَ، فَاقْضِي مَا يَقْضِي الْمُحْرِمُ، غَيْرَ أَنْ لَا تَطُوفِي بِالْبَيْتِ". (ن)', 'ആഇശ(റ): ഹജ്ജ് മാത്രമുദ്ദേശിച്ച് ഞങ്ങൾ പുറപ്പെട്ടു. സരിഫിൽ എത്തിയപ്പോൾ എനിക്ക് ആർത്തവമുണ്ടായി. ഞാൻ കരഞ്ഞു കൊണ്ടിരിക്കുമ്പോൾ റസൂൽ(സ) വന്ന് ചോദിച്ചു: "നിനക്കാർത്തവമുണ്ടായോ?." ഞാൻ പറഞ്ഞു: അതെ, റസൂൽ(സ) പറഞ്ഞു: "ഇത് (ഹൈദ്) അല്ലാഹു ആദം പെൺമക്കൾക്ക് നിശ്ചയിച്ച ഒരു കാര്യമാണ്. നീ ഇഹ്റാം ചെയ്തവൻ ചെയ്യുന്നതൊക്കെ ചെയ്യുക. എന്നാൽ കഅ്ബ പ്രദക്ഷിണം മാത്രം ചെയ്യരുത്." (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 272, 272, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 79, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الْحَائِضُ وَالنُّفَسَاءُ إِذَا أَتَتَا عَلَى الْوَقْتِ تَغْتَسِلَانِ وَتُحْرِمَانِ، وَتَقْضِيَانِ الْمَنَاسِكَ كُلَّهَا، غَيْرَ الطَّوَافِ بِالْبَيْتِ". (د,ت)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ആർത്തവകാരിയും പ്രസവ രക്തകാരിയും (ഇഹ്റാം) സമയമായാൽ കുളിച്ച് ഇഹ്റാം ചെയ്യണം, കഅ്ബാ ത്വവാഫ് ഒഴികെയുള്ള മറ്റെല്ലാ കർമ്മങ്ങളും അവർ രണ്ടു പേരും നിർവ്വഹിക്കണം." (ദ,തു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 272, 272, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 80, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُ قَالَ: أَقَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تِسْعَ سِنِينَ لَمْ يَحُجَّ، ثُمَّ أَذَّنَ فِي النَّاسِ بِالْحَجِّ، فَلَمْ يَبْقَ أَحَدٌ يَقْدِرُ أَنْ يَأْتِيَ رَاكِبًا أَوْ رَاجِلًا إِلَّا قَدِمَ، فَتَدَارَكَ النَّاسُ لِيَخْرُجُوا مَعَهُ،حَتَّى جَاءَ ذَا الْحُلَيْفَةِ فَوَلَدَتْ أَسْمَاءُ بِنْتُ عُمَيْسٍ مُحَمَّدَ بْنَ أَبِي بَكْرٍ، فَأَرْسَلَتْ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "اغْتَسِلِي وَاسْتَثْفِرِي بِثَوْبٍ ثُمَّ أَهِلِّي". فَفَعَلَتْ. (ن)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): റസൂൽ(സ) ഹജ്ജ് ചെയ്യാതെ ഒമ്പത് വർഷം മദീനയിൽ താമസിച്ചു. പിന്നെ ഹജ്ജിനെക്കുറിച്ച് ജനങ്ങൾക്കിടയിൽ വിളംബരം ചെയ്തു. നടന്നോ വാഹനപ്പുറത്തോ വരാൻ സാധിക്കുന്നവർ ഒന്നൊഴിയാതെ വന്നു. തിരുമേനി(സ)യോടൊപ്പം പുറപ്പെടാൻ ജനങ്ങൾ ഒരുമിച്ചുകൂടി. ദുൽഹുലൈഫയിലെത്തിയപ്പോൾ അസ്മാഅ് ബിൻത് ഉമൈസ്(റ) അബൂബക്കർ(റ)വിന്റെ മകൻ മുഹമ്മദ്(റ)വിനെ പ്രസവിച്ചു. അവൾ തിരുമേനി(സ)യിലേക്ക് ആളെ അയച്ചു. റസൂൽ(സ) പറഞ്ഞു: "നീ കുളിച്ച് ഒരു വസ്ത്രം കൊണ്ട് കെട്ടുക. പിന്നെ ഇഹ്റാം ചെയ്യുക." അവർ അപ്രകാരം ചെയ്തു. (ന)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 272, 272, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 81, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُ قَالَ: أَقْبَلْنَا مُهِلِّينَ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِحَجٍّ مُفْرَدٍ، وَأَقْبَلَتْ عَائِشَةُ مُهِلَّةً بِعُمْرَةٍ،حَتَّى إِذَا كُنَّا بِسَرِفَ عَرَكَتْ، حَتَّى إِذَا قَدِمْنَا طُفْنَا بِالْكَعْبَةِ وَبِالصَّفَا وَالْمَرْوَةِ، فَأَمَرَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يَحِلَّ مِنَّا مَنْ لَمْ يَكُنْ مَعَهُ هَدْيٌ. قَالَ: فَقُلْنَا: حِلُّ مَاذَا؟ قَالَ: "الْحِلُّ كُلُّهُ". فَوَاقَعْنَا النِّسَاءَ وَتَطَيَّبْنَا بِالطِّيبِ وَلَبِسْنَا ثِيَابَنَا، وَلَيْسَ بَيْنَنَا وَبَيْنَ عَرَفَةَ إِلَّا أَرْبَعُ لَيَالٍ، ثُمَّ أَهْلَلْنَا يَوْمَ التَّرْوِيَةِ، ثُمَّ دَخَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى عَائِشَةَ فَوَجَدَهَا تَبْكِي، فَقَالَ: "مَا شَأْنُكِ؟". فَقَالَتْ: شَأْنِي أَنِّي قَدْ حِضْتُ، وَقَدْ حَلَّ النَّاسُ وَلَمْ أُحْلِلْ، وَلَمْ أَطُفْ بِالْبَيْتِ، وَالنَّاسُ يَذْهَبُونَ إِلَى الْحَجِّ الْآنَ. فَقَالَ: "إِنَّ هَذَا أَمْرٌ كَتَبَهُ اللَّهُ عَلَى بَنَاتِ آدَمَ، فَاغْتَسِلِي ثُمَّ أَهِلِّي بِالْحَجِّ". فَفَعَلَتْ، وَوَقَفَتِ الْمَوَاقِفَ، حَتَّى إِذَا طَهُرَتْ طَافَتْ بِالْكَعْبَةِ وَبِالصَّفَا وَالْمَرْوَةِ، ثُمَّ قَالَ: "قَدْ حَلَلْتِ مِنْ حَجَّتِكِ وَعُمْرَتِكِ جَمِيعًا". فَقَالَتْ: يَا رَسُولَ اللَّهِ، إِنِّي أَجِدُ فِي نَفْسِي أَنِّي لَمْ أَطُفْ بِالْبَيْتِ حَتَّى حَجَجْتُ؟ قَالَ: "فَاذْهَبْ بِهَا يَا عَبْدَ الرَّحْمَنِ فَأَعْمِرْهَا مِنَ التَّنْعِيمِ". وَذَلِكَ لَيْلَةَ الْحَصْبَةِ. (م,ن)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): ഹജ്ജ് ഒറ്റക്ക് (ഉംറയില്ലാതെ) നിർവ്വഹിക്കാനായി ഇഹ്റാം ചെയ്തവരായിക്കൊണ്ട് ഞങ്ങൾ റസൂൽ(സ)യോടൊപ്പം പുറപ്പെട്ടു. ഉംറക്ക് ഇഹ്റാം ചെയ്ത് ആഇശ(റ)യും വന്നു. സരിഫിലെത്തിയപ്പോൾ അവർക്ക് ആർത്തവമുണ്ടായി. ഞങ്ങൾ മക്കയിലെത്തിയപ്പോൾ കഅ്ബ ത്വവാഫ് ചെയ്യുകയും സ്വഫാ മർവക്കിടയിൽ ഓടുകയും ചെയ്തു. ഞങ്ങളുടെ കൂട്ടത്തിൽ ഹദ്യ കൂടെയില്ലാത്തവരോട് തഹല്ലുലാവാൻ റസൂൽ(സ) കൽപിച്ചു. ഞങ്ങൾ ചോദിച്ചു: ഏതുതരം തഹല്ലുലാണ്? റസൂൽ(സ) പറഞ്ഞു: പൂർണ്ണമായ തഹല്ലുൽ. അങ്ങനെ ഞങ്ങൾ ഭാര്യമാരുമായി ബന്ധപ്പെടുകയും സുഗന്ധം പൂശുകയും (തുന്നിയ) വസ്ത്രം ധരിക്കുകയും ചെയ്തു. ഞങ്ങൾക്കും അറഫാ ദിനത്തിനുമിടയിൽ നാല് രാത്രികളാണ് ബാക്കിയുണ്ടായിരുന്നത്. പിന്നീട് തർവിയ ദിനത്തിൽ ഞങ്ങൾ ഇഹ്റാം ചെയ്തു. പിന്നെ റസൂൽ(സ) ആഇശ(റ)യുടെയടുത്തു ചെന്നപ്പോൾ അവർ കരയുന്നതു കണ്ട് റസൂൽ(സ) ചോദിച്ചു: "എന്തുപറ്റി? " അവർ പറഞ്ഞു: ആർത്തവം തുടങ്ങി, ജനങ്ങൾ തഹല്ലുലായപ്പോൾ ഞാൻ തഹല്ലുലായില്ല. ഞാൻ കഅ്ബ ത്വവാഫ് ചെയ്തിട്ടില്ല. ഇപ്പോഴിതാ ജനങ്ങൾ ഹജ്ജിനു പോവുന്നു. റസൂൽ(സ) പറഞ്ഞു: "ഇത് (ആർത്തവം) ആദം പെൺമക്കൾക്ക് അല്ലാഹു നിശ്ചയിച്ച ഒരു കാര്യമാണ്. ആയതിനാൽ നീ കുളിച്ച് ഹജ്ജിന് ഇഹ്റാം ചെയ്യുക." അവർ നബി(സ)യുടെ കൽപന പ്രകാരം ചെയ്തു. നിൽക്കേണ്ടിടത്തെല്ലാം നിന്നു. ശുദ്ധിയായശേഷം കഅ്ബയും സ്വഫാ മർവയും ത്വവാഫ് ചെയ്തു. റസൂൽ(സ) പറഞ്ഞു: "നിന്റെ ഹജ്ജിൽ നിന്നും ഉംറയിൽ നിന്നും നീ ഒഴിവായി. " ആഇശ(റ) പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ഹജ്ജിനു മുൻപ് കഅ്ബ ത്വവാഫ് ചെയ്യാത്തതിൽ എനിക്കു വിഷമമുണ്ട്. റസൂൽ(സ) പറഞ്ഞു: "അബ്ദുർറഹ്മാൻ, നീ അവളുമായി തൻഈമിൽ ചെന്ന് ഉംറക്ക്(ഇഹ്റാം) ചെയ്യിക്കു." അത് കല്ലേറിന്റെ രാത്രിയായിരുന്നു. (മു,ന)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], null, null, 272, 273, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 82, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: خَرَجْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي حَجَّةِ الْوَدَاعِ، فَأَهْلَلْنَا بِعُمْرَةٍ، ثُمَّ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ كَانَ مَعَهُ هَدْيٌ فَلْيُهْلِلْ بِالْحَجِّ مَعَ الْعُمْرَةِ، ثُمَّ لَا يَحِلَّ حَتَّى يَحِلَّ مِنْهُمَا جَمِيعًا". فَقَدِمْتُ مَكَّةَ وَأَنَا حَائِضٌ، فَلَمْ أَطُفْ بِالْبَيْتِ وَلَا بَيْنَ الصَّفَا وَالْمَرْوَةِ، فَشَكَوْتُ ذَلِكَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "انْقُضِي رَأْسَكِ وَامْتَشِطِي، وَأَهِلِّي بِالْحَجِّ وَدَعِي الْعُمْرَةَ". فَفَعَلْتُ، فَلَمَّا قَضَيْتُ الْحَجَّ أَرْسَلَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَعَ عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرٍ إِلَى التَّنْعِيمِ فَاعْتَمَرْتُ، قَالَ: "هَذِهِ مَكَانُ عُمْرَتِكِ". فَطَافَ الَّذِينَ أَهَلُّوا بِالْعُمْرَةِ بِالْبَيْتِ وَبَيْنَ الصَّفَا وَالْمَرْوَةِ ثُمَّ حَلُّوا، ثُمَّ طَافُوا طَوَافًا آخَرَ بَعْدَ أَنْ رَجَعُوا مِنْ مِنًى لِحَجِّهِمْ، وَأَمَّا الَّذِينَ جَمَعُوا الْحَجَّ وَالْعُمْرَةَ فَإِنَّمَا طَافُوا طَوَافًا وَاحِدًا. (ن)', 'ആഇശ(റ): ഹജ്ജതുൽ വിദാഇൽ ഞങ്ങൾ റസൂൽ(സ)യോടൊപ്പം പുറപ്പെട്ടു. ഞങ്ങൾ ഉംറക്ക് ഇഹ്റാം ചെയ്തു. റസൂൽ(സ) പറഞ്ഞു: "ഹദ്യ ഉള്ളവർ ഉംറക്കൊപ്പം ഹജ്ജിനും ഇഹ്റാം ചെയ്യുക. അവ രണ്ടിൽ നിന്നും തഹല്ലുലാവുന്നതിനു മുൻപ് അവൻ തഹല്ലുലാവരുത്." ആർത്തവകാരിയായി ഞാൻ മക്കയിൽ പ്രവേശിച്ചു, ഞാൻ കഅ്ബയോ സ്വഫാ മർവയോ ത്വവാഫ് ചെയ്തിട്ടില്ല. ഇക്കാര്യം റസൂൽ(സ)യോട് പരാതിപ്പെട്ടപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നീ തല മെടയുക, മുടി ചീകുക. ഉംറ ഉപേക്ഷിച്ച് ഹജ്ജിന് ഇഹ്റാം ചെയ്യുക." ഞാനപ്രകാരം ചെയ്തു. ഞാൻ ഹജ്ജ് നിർവ്വഹിച്ചു കഴിഞ്ഞപ്പോൾ റസൂൽ(സ) എന്നെ അബ്ദുർറഹ്മാൻ(റ)വിനോടൊപ്പം തൻഈമിലേക്ക് പറഞ്ഞയച്ചു. ഞാൻ ഉംറക്ക് ഇഹ്റാം ചെയ്തു. റസൂൽ(സ) പറഞ്ഞു: "ഇതാണു നിന്റെ ഉംറയുടെ സ്ഥാനം." ഉംറക്ക് ഇഹ്റാം ചെയ്തവർ കഅ്ബയും സ്വഫാ മർവയും ത്വവാഫ് ചെയ്യുകയും പിന്നെ സ്വതന്ത്രരാവുകയും ചെയ്തു. മിനായിൽ നിന്ന് മടങ്ങിയ ശേഷം അവർ ഹജ്ജിനുവേണ്ടി മറ്റൊരു ത്വവാഫ് ചെയ്തു. എന്നാൽ ഹജ്ജും ഉംറയും ഒന്നിച്ച് നിർവ്വഹിച്ചവർ ഒരു ത്വവാഫ് മാത്രമേ ചെയ്തിട്ടുള്ളൂ. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 273, 274, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 83, 'عَنْ مُحَمَّدِ بْنِ أَبِي بَكْرٍ رَضِيَ اللهُ عَنْهُ ، عَنْ أَبِي بَكْرٍ رَضِيَ اللهُ عَنْهُ : أَنَّهُ خَرَجَ حَاجًّا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَجَّةَ الْوَدَاعِ وَمَعَهُ امْرَأَتُهُ أَسْمَاءُ بِنْتُ عُمَيْسٍ، فَوَلَدَتْ بِالشَّجَرَةِ مُحَمَّدَ بْنَ أَبِي بَكْرٍ، فَأَتَى أَبُو بَكْرٍ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَخْبَرَهُ، فَأَمَرَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يَأْمُرَهَا أَنْ تَغْتَسِلَ، ثُمَّ تُهِلَّ بِالْحَجِّ، وَتَصْنَعَ مَا يَصْنَعُ النَّاسُ، إِلَّا أَنَّهَا لَا تَطُوفُ بِالْبَيْتِ. (ن,جه)', 'മുഹമ്മദുബ്നു അബീബക്കർ(റ) തന്റെ പിതാവിൽ നിന്ന് നിവേദനം ചെയ്യുന്നു: അബൂബക്കർ(റ) ഹജ്ജത്തുൽ വദാഇൽ റസൂൽ(സ)യോടൊപ്പം ഹജ്ജിനു പുറപ്പെട്ടു. അബൂബക്കർ(റ)വിന്റെ കൂടെ തന്റെ ഭാര്യ അസ്മാഅ് ബിൻത് ഉമൈസ്(റ)യും ഉണ്ടായിരുന്നു. ശജറയിൽ വെച്ച് അവർ മുഹമ്മദ്(റ)നെ പ്രസവിച്ചു. അബൂബക്കർ(റ) റസൂൽ(സ)യോടു വന്ന് വിവരം പറഞ്ഞു. കുളിച്ച് ഹജ്ജിന് ഇഹ്റാം ചെയ്ത് കഅ്ബ ത്വവാഫ് ചെയ്യലൊഴിച്ച് മറ്റെല്ലാം മറ്റുള്ളവർ ചെയ്യുന്നതുപോലെ ചെയ്യാൻ പറയണമെന്ന് അബൂബക്കർ(റ)വിനോട് റസൂൽ(സ) കൽപ്പിച്ചു. (ന,ജ)', 'مُحَمَّدِ بْنِ أَبِي بَكْرٍ', 'മുഹമ്മദുബ്നു അബീബക്കർ(റ)', null, null, array['ن','جه']::text[], array['ന','ജ']::text[], null, null, 274, 274, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 84, 'عَنْ سَعِيدِ بْنِ جُبَيْرٍ رَضِيَ اللهُ عَنْهُ قَالَ: قُلْتُ لِعَبْدِ اللَّهِ بْنِ عَبَّاسٍ: يَا أَبَا الْعَبَّاسِ، عَجِبْتُ لِاخْتِلَافِ أَصْحَابِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي إِهْلَالِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ أَوْجَبَ؟ فَقَالَ: إِنِّي لَأَعْلَمُ النَّاسِ بِذَلِكَ، إِنَّهَا إِنَّمَا كَانَتْ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَجَّةً وَاحِدَةً، فَمِنْ هُنَاكَ اخْتَلَفُوا، خَرَجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَاجًّا، فَلَمَّا صَلَّى فِي مَسْجِدِهِ بِذِي الْحُلَيْفَةِ رَكْعَتَيْهِ أَوْجَبَ فِي مَجْلِسِهِ، فَأَهَلَّ بِالْحَجِّ حِينَ فَرَغَ مِنْ رَكْعَتَيْهِ، فَسَمِعَ ذَلِكَ مِنْهُ أَقْوَامٌ فَحَفِظْتُهُ عَنْهُ، ثُمَّ رَكِبَ فَلَمَّا اسْتَقَلَّتْ بِهِ نَاقَتُهُ أَهَلَّ، وَأَدْرَكَ ذَلِكَ مِنْهُ أَقْوَامٌ، وَذَلِكَ أَنَّ النَّاسَ إِنَّمَا كَانُوا يَأْتُونَ أَرْسَالًا، فَسَمِعُوهُ حِينَ اسْتَقَلَّتْ بِهِ نَاقَتُهُ يُهِلُّ، فَقَالُوا: إِنَّمَا أَهَلَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ اسْتَقَلَّتْ بِهِ نَاقَتُهُ. ثُمَّ مَضَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَلَمَّا عَلَا عَلَى شَرَفِ الْبَيْدَاءِ أَهَلَّ، وَأَدْرَكَ ذَلِكَ مِنْهُ أَقْوَامٌ فَقَالُوا: إِنَّمَا أَهَلَّ حِينَ عَلَا عَلَى شَرَفِ الْبَيْدَاءِ، وَايْمُ اللَّهِ لَقَدْ أَوْجَبَ فِي مُصَلَّاهُ، وَأَهَلَّ حِينَ اسْتَقَلَّتْ بِهِ نَاقَتُهُ، وَأَهَلَّ حِينَ عَلَا عَلَى شَرَفِ الْبَيْدَاءِ، قَالَ سَعِيدٌ: فَمَنْ أَخَذَ بِقَوْلِ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ أَهَلَّ فِي مُصَلَّاهُ إِذَا فَرَغَ مِنْ رَكْعَتَيْهِ. (د)', 'സഈദുബ്നു ജുബൈർ(റ): ഞാൻ ഇബ്നുഅബ്ബാസ്(റ)നോട് ചോദിച്ചു: അബൂ അബ്ബാസ്, റസൂൽ(സ)യുടെ ഇഹ്റാം എപ്പോഴായിരുന്നു നടന്നത് എന്നതിൽ സഹാബത്തിന്റെ അഭിപ്രായ വ്യത്യാസത്തിൽ ഞാൻ അത്ഭുതപ്പെടുന്നു. ഇബ്നുഅബ്ബാസ്(റ) പറഞ്ഞു: അതേപ്പറ്റി നന്നായറിയുന്നവൻ ഞാനാണ്. റസൂൽ(സ) ഒരു ഹജ്ജു മാത്രമേ ചെയ്തിട്ടുള്ളൂ. അതിനാലാണ് അവർ ഭിന്നിച്ചത്. റസൂൽ(സ) ഹജ്ജിനായി പുറപ്പെട്ട് ദുൽഹുലൈഫയിലെത്തിയപ്പോൾ റസൂൽ(സ)യുടെ പള്ളിയിൽ വെച്ച് രണ്ട് റക്അത്ത് നിസ്കരിച്ചു. ശേഷം തന്റെ സദസ്സിൽ മുട്ടുകുത്തി, തന്റെ രണ്ട് റക്അത്തിൽ നിന്ന് വിരമിച്ചശേഷം ഹജ്ജിനായി ഇഹ്റാം ചെയ്തു. ചിലർ അതുകേട്ട് അത് മനഃപാഠമാക്കി. പിന്നെ റസൂൽ(സ) വാഹനം കയറി. വാഹനം നിന്നപ്പോൾ റസൂൽ(സ) ഇഹ്റാം ചെയ്തു. അതും ചിലർ കണ്ട് മനസ്സിലാക്കി. കാരണം ജനങ്ങൾ ഘട്ടംഘട്ടമായാണ് വന്നുകൊണ്ടിരുന്നത്. തന്റെ വാഹനം നിന്നപ്പോൾ റസൂൽ(സ) ഇഹ്റാം ചെയ്യുന്നതായി അവർ കേട്ടു. അക്കാരണത്താൽ അവർ പറഞ്ഞു: തന്റെ വാഹനം നിന്നപ്പോഴാണ് റസൂൽ(സ) ഇഹ്റാം ചെയ്തത്. പിന്നെ റസൂൽ(സ) യാത്ര ചെയ്ത് ശറഫിൽ ബൈദാഇൽ കയറിയപ്പോൾ ഇഹ്റാം കെട്ടി. അതുകണ്ട ഒരു വിഭാഗക്കാർ പറഞ്ഞു: ശറഫുൽ ഫൈദാഇൽ കയറിയപ്പോഴാണ് റസൂൽ(സ) ഇഹ്റാം ചെയ്തത്. അല്ലാഹുവാണ് സത്യം, റസൂൽ(സ) തന്റെ നിസ്കാര സ്ഥലത്തു വെച്ച് ഇഹ്റാം ചെയ്തു. അവിടന്ന് വാഹനത്തിൽ നേരെ നിന്നപ്പോഴും ഇഹ്റാം ചെയ്തു. ശറഫിൽ ബൈദാഇൽ കയറിയപ്പോഴും ഇഹ്റാം ചെയ്തു. സഈദ് പറഞ്ഞു: ഇബ്നുഅബ്ബാസ്(റ)വിന്റെ വാക്ക് എടുക്കുന്നവർ തങ്ങളുടെ നമസ്കാര സ്ഥലത്തു നിന്ന് രണ്ട് റക്അത്ത് നമസ്കരിച്ച ശേഷം ഇഹ്റാം ചെയ്യണം. (ദ)', 'سَعِيدِ بْنِ جُبَيْرٍ', 'സഈദുബ്നു ജുബൈർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 274, 275, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 85, 'عَنْ عُبَيْدِ بْنِ جُرَيْجٍ رَضِيَ اللهُ عَنْهُ أَنَّهُ قَالَ لِعَبْدِ اللَّهِ بْنِ عُمَرَ: يَا أَبَا عَبْدِ الرَّحْمَنِ، رَأَيْتُكَ تَصْنَعُ أَرْبَعًا لَمْ أَرَ أَحَدًا مِنْ أَصْحَابِكَ يَصْنَعُهَا؟ قَالَ: مَا هُنَّ يَا ابْنَ جُرَيْجٍ؟ قَالَ: رَأَيْتُكَ لَا تَمَسُّ مِنَ الْأَرْكَانِ إِلَّا الْيَمَانِيَّيْنِ، وَرَأَيْتُكَ تَلْبَسُ النِّعَالَ السِّبْتِيَّةَ، وَرَأَيْتُكَ تَصْبُغُ بِالصُّفْرَةِ، وَرَأَيْتُكَ إِذَا كُنْتَ بِمَكَّةَ أَهَلَّ النَّاسُ إِذَا رَأَوُا الْهِلَالَ، وَلَمْ تُهِلَّ أَنْتَ حَتَّى كَانَ يَوْمَ التَّرْوِيَةِ. فَقَالَ عَبْدُ اللَّهِ بْنُ عُمَرَ: أَمَّا الْأَرْكَانُ فَإِنِّي لَمْ أَرَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَمَسُّ إِلَّا الْيَمَانِيَّيْنِ. وَأَمَّا النِّعَالُ السِّبْتِيَّةُ فَإِنِّي رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَلْبَسُ النِّعَالَ الَّتِي لَيْسَ فِيهَا شَعْرٌ وَيَتَوَضَّأُ فِيهَا، فَأَنَا أُحِبُّ أَنْ أَلْبَسَهَا. وَأَمَّا الصُّفْرَةُ فَإِنِّي رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَصْبُغُ بِهَا، فَأَنَا أُحِبُّ أَنْ أَصْبُغَ بِهَا، وَأَمَّا الْإِهْلَالُ فَإِنِّي لَمْ أَرَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُهِلُّ حَتَّى تَنْبَعِثَ بِهِ رَاحِلَتُهُ. (ق,د,ت,ن,جه)', 'ഉബൈദുബ്നു ജുറൈജ്(റ): അദ്ദേഹം ഇബ്നുഉമർ(റ)വിനോട് പറഞ്ഞു: അബൂഅബ്ദുറഹ്മാൻ, താങ്കളുടെ കൂട്ടുകാർ ചെയ്യാത്ത നാലു കാര്യങ്ങൾ താങ്കൾ ചെയ്യുന്നത് ഞാൻ കാണുന്നു. ഇബ്നുഉമർ(റ) ചോദിച്ചു: ഇബ്നു ജുറൈജ്, ഏതൊക്കെയാണവ? ഇബ്നുജുറൈജ്(റ) പറഞ്ഞു: രണ്ട് റുക്നുയമാനികൾ മാത്രമേ നിങ്ങൾ തൊടുന്നത് ഞാൻ കാണുന്നുള്ളൂ. ഊറക്കിട്ട തോൽ ചെരുപ്പ് നിങ്ങൾ ധരിക്കുന്നത് ഞാൻ കാണുന്നു. മഞ്ഞഛായം പുശുന്നതും ഞാൻ കാണുന്നു. നിങ്ങൾ മക്കയിലുണ്ടായിരിക്കെ ജനങ്ങളെല്ലാം (ദുൽഹജ്ജ്) മാസപ്പിറവി കണ്ടാലുടൻ ഇഹ്റാം ചെയ്യുമ്പോൾ നിങ്ങൾ മാത്രം തർവിയത് ദിനത്തിൽ ഇഹ്റാം ചെയ്യുന്നത് ഞാൻ കാണുന്നു. ഇബ്നുഉമർ(റ) പറഞ്ഞു: റുക്നുകളുടെ കാര്യം; രണ്ട് റുക്നുയമാനികൾ മാത്രമേ റസൂൽ(സ) തൊടുന്നത് ഞാൻ കണ്ടിട്ടുള്ളൂ. ഊറക്കിട്ട തോൽചെരിപ്പുകളുടെ കാര്യം; രോമമില്ലാത്ത ചെരിപ്പുകൾ ധരിച്ചുകൊണ്ട് റസൂൽ(സ) വുളൂഅ് ചെയ്യുന്നത് ഞാൻ കണ്ടു. അതുകൊണ്ട് അതു ധരിക്കാൻ ഞാനിഷ്ടപ്പെടുന്നു. പിന്നെ മഞ്ഞ നിറത്തിന്റെ കാര്യം; റസൂൽ(സ) അതുകൊണ്ട് ഛായം പൂശുന്നതു ഞാൻ കണ്ടിട്ടുണ്ട്. അതുകൊണ്ട് അതിനെ ഞാനിഷ്ടപ്പെടുന്നു. പിന്നെ ഇഹ്ലാൽ; തന്റെ വാഹനം ധൃതിയിൽ പുറപ്പെടുന്നതുവരെ റസൂൽ(സ) തൽബിയത് ചൊല്ലുന്നത് ഞാൻ കണ്ടിട്ടില്ല. (ബു,മു,ദ,തു,ന,ജ)', 'عُبَيْدِ بْنِ جُرَيْجٍ', 'ഉബൈദുബ്നു ജുറൈജ്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 275, 275, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 86, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: صَلَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الظُّهْرَ بِالْمَدِينَةِ أَرْبَعًا، وَصَلَّى الْعَصْرَ بِذِي الْحُلَيْفَةِ رَكْعَتَيْنِ، ثُمَّ بَاتَ بِذِي الْحُلَيْفَةِ حَتَّى أَصْبَحَ، فَلَمَّا رَكِبَ رَاحِلَتَهُ وَاسْتَوَتْ بِهِ أَهَلَّ. (ق,د,ت,ن)', 'അനസ്(റ): റസൂൽ(സ) മദീനയിൽ നിന്ന് നാലു റക്അത്ത് ളുഹ്ർ നിസ്കരിച്ചു. ദുൽഹുലൈഫയിൽ നിന്ന് അസ്ർ രണ്ട് റക്അത്തായി നിസ്കരിച്ചു. പിന്നീട് പ്രഭാതം വരെ ദുൽഹുലൈഫയിൽ രാപാർത്തു. പിന്നെ തന്റെ വാഹനം കയറി, അതു നിന്നപ്പോൾ അവിടന്ന് തൽബിയത് ചൊല്ലി. (ബു,മു,ദ,തു,ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 275, 275, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 87, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ : أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَّى الظُّهْرَ ثُمَّ رَكِبَ رَاحِلَتَهُ، فَلَمَّا عَلَا عَلَى جَبَلِ الْبَيْدَاءِ أَهَلَّ. (د,ن)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) ളുഹ്ർ നിസ്കരിച്ച ശേഷം തന്റെ വാഹനം കയറി ബൈദാഅ് പർവ്വതത്തിന്മേൽ എത്തിയപ്പോൾ തൽബിയത് ചൊല്ലി. (ദ,ന)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 275, 276, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 88, 'عَنْ سَعْدِ بْنِ أَبِي وَقَّاصٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا أَخَذَ طَرِيقَ الْفُرْعِ أَهَلَّ إِذَا اسْتَقَلَّتْ بِهِ رَاحِلَتُهُ، وَإِذَا أَخَذَ طَرِيقَ أُحُدٍ أَهَلَّ إِذَا أَشْرَفَ عَلَى جَبَلِ الْبَيْدَاءِ. (د)', 'സഅ്ദുബ്നു അബീവഖാസ്(റ): റസൂൽ(സ) മല വഴി യാത്ര തുടങ്ങിയാൽ തന്റെ വാഹനം നേരെ നിൽക്കുമ്പോൾ തൽബിയത് ചൊല്ലും. ഉഹ്ദ് വഴിയാണ് യാത്ര എങ്കിൽ ബൈദാഅ് പർവ്വതത്തിലെത്തിയാൽ തൽബിയത് ചൊല്ലും. (ദ)', 'سَعْدِ بْنِ أَبِي وَقَّاصٍ', 'സഅ്ദുബ്നു അബീവഖാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 276, 276, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 89, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَهَلَّ فِي دُبُرِ الصَّلَاةِ. (ت,ن)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) നിസ്കാര ശേഷമാണ് തൽബിയത് ചൊല്ലിയിരുന്നത്. (തു,ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ت','ن']::text[], array['തു','ന']::text[], null, null, 276, 276, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 90, 'عَنْ أَنَسِ ابْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ : أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَّى الظُّهْرَ بِالْبَيْدَاءِ، ثُمَّ رَكِبَ وَصَعِدَ جَبَلَ الْبَيْدَاءِ، فَأَهَلَّ بِالْحَجِّ وَالْعُمْرَةِ حِينَ صَلَّى الظُّهْرَ. (ن)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) ബൈദാഇൽ നിന്ന് ളുഹ്ർ നിസ്കരിച്ച ശേഷം അവിടത്തെ വാഹനം കയറി ബൈദാഅ് പർവ്വതത്തിന്മേൽ കയറി. ളുഹ്ർ നിസ്കരിച്ച ശേഷം ഹജ്ജിനും ഉംറക്കും ഇഹ്റാം ചെയ്തു. (ന)', 'أَنَسِ ابْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 276, 276, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 91, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّهُ كَانَ يُلَبِّي مِنْ ذِي الْحُلَيْفَةِ، فَإِذَا بَلَغَ الْحَرَمَ أَمْسَكَ حَتَّى إِذَا جَاءَ ذَا طُوًى بَاتَ فِيهِ، فَإِذَا صَلَّى الْغَدَاةَ اغْتَسَلَ، وَزَعَمَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَعَلَ ذَلِكَ. (خ)', 'ഇബ്നുഉമർ(റ): അദ്ദേഹം ദുൽഹുലൈഫയിൽ നിന്ന് തൽബിയത്ത് ചൊല്ലാറുണ്ടായിരുന്നു. ഹറമിലെത്തിയാൽ നിർത്തും. ദാത്വുവായിലെത്തിയാൽ അവിടെ രാപാർക്കും. സുബ്ഹി നിസ്കരിച്ചശേഷം കുളിക്കും. റസൂൽ(സ) ഇപ്രകാരമെല്ലാം ചെയ്തിരുന്നുവെന്ന് അദ്ദേഹം പറഞ്ഞു. (ബു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 276, 276, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 92, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: مَا أَهَلَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَّا مِنْ عِنْدِ الْمَسْجِدِ، يَعْنِي مَسْجِدَ ذِي الْحُلَيْفَةِ. (خ)', 'ഇബ്നുഉമർ(റ): പള്ളിയുടെ (ദുൽഹുലൈഫ പള്ളി) അടുത്തു നിന്നല്ലാതെ റസൂൽ(സ) ഇഹ്റാം ചെയ്തിട്ടില്ല. (ബു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 276, 276, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 93, 'عَنْ عَبْدِ اللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُ قَالَ: بَيْدَاؤُكُمْ هَذِهِ الَّتِي تَكْذِبُونَ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِيهَا، مَا أَهَلَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَّا مِنْ عِنْدِ الْمَسْجِدِ. يَعْنِي مَسْجِدَ ذِي الْحُلَيْفَةِ. وَفِي رِوَايَةٍ: مِنْ عِنْدِ الشَّجَرَةِ (ق,د,ت,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): നിങ്ങളുടെ ഈ ബൈദാഇന്റെ കാര്യത്തിൽ നിങ്ങൾ റസൂൽ(സ)യെപ്പറ്റി കള്ളമാണ് പറയുന്നത്, ദുൽഹുലൈഫ പള്ളിയുടെ അടുത്തു നിന്നല്ലാതെ അവിടന്ന് ഇഹ്റാം ചെയ്തിട്ടില്ല.
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=4 and h.hadith_no=93), 1, 'وَفِي رِوَايَةٍ: مِنْ عِنْدِ الشَّجَرَةِ (ق,د,ت,ن,جه)', 'മറ്റൊരു നിവേദനത്തിൽ: ശജറയുടെ അടുത്ത് നിന്ന് എന്നും കാണും. (ബു,മു,ദ,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 94, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُ قَالَ: لَمَّا أَرَادَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْحَجَّ أَذَّنَ فِي النَّاسِ فَاجْتَمَعُوا، فَلَمَّا أَتَى الْبَيْدَاءَ أَحْرَمَ. (ت)', 'ജാബിർ(റ): റസൂൽ(സ) ഹജ്ജ് ചെയ്യാനുദ്ദേശിച്ചപ്പോൾ ജനങ്ങൾക്കിടയിൽ വിളംബരം ചെയ്തു. ജനങ്ങൾ ഒരുമിച്ചുകൂടി. ബൈദാഇലെത്തിയപ്പോൾ ഇഹ്റാം ചെയ്തു. (തു)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിർ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 276, 277, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 95, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ: فِي حَجَّةِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: فَلَمَّا أَتَى ذَا الْحُلَيْفَةِ صَلَّى وَهُوَ صَامِتٌ حَتَّى أَتَى الْبَيْدَاءَ. (ن)', 'ജാബിർ(റ): റസൂൽ(സ)യുടെ ഹജ്ജിനെക്കുറിച്ച് അദ്ദേഹം പറയുന്നു: നബി(സ) ദുൽഹുലൈഫയിൽ വെച്ച് നിസ്കരിച്ചു. ബൈദാഇലെത്തും വരെ ഒന്നും മിണ്ടിയില്ല. (ന)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 277, 277, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 96, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُ: قَالَ: رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَرْكَبُ رَاحِلَتَهُ بِذِي الْحُلَيْفَةِ، ثُمَّ يُهِلُّ حِينَ تَسْتَوِي بِهِ قَائِمَةً. (ن)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): ദുൽഹുലൈഫയിൽ വെച്ച് റസൂൽ(സ) അവിടത്തെ വാഹനം കയറുന്നതും പിന്നീട് തന്റെ ഒട്ടകം നേരെ നിൽക്കുമ്പോൾ തൽബിയത് ചൊല്ലുന്നതും ഞാൻ കണ്ടു. (ന)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 277, 277, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 97, 'عَنْ عُبَيْدِ بْنِ جُرَيْجٍ رَضِيَ اللهُ عَنْهُ قَالَ: قُلْتُ لِابْنِ عُمَرَ: رَأَيْتُكَ تُهِلُّ إِذَا اسْتَوَتْ بِكَ نَاقَتُكَ؟ قَالَ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يُهِلُّ إِذَا اسْتَوَتْ بِهِ نَاقَتُهُ وَانْبَعَثَتْ. (ن)', 'ഉബൈദുബ്നു ജുറൈജ്(റ): ഞാൻ ഇബ്നുഉമർ(റ)നോട് ചോദിച്ചു: നിങ്ങളുമായി നിങ്ങളുടെ ഒട്ടകം നേരെ നിൽക്കുമ്പോൾ നിങ്ങൾ തൽബിയത് ചൊല്ലുന്നത് ഞാൻ കണ്ടുവല്ലോ? ഇബ്നുഉമർ(റ) പറഞ്ഞു: റസൂൽ(സ) അവിടത്തെ ഒട്ടകം നേരെയാവുകയും അതിന് വേഗതയുണ്ടാവുകയും ചെയ്താൽ തൽബിയത് ചൊല്ലാറുണ്ടായിരുന്നു. (ന)', 'عُبَيْدِ بْنِ جُرَيْجٍ', 'ഉബൈദുബ്നു ജുറൈജ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 277, 277, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 98, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: إِنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَقَّتَ لِأَهْلِ الْمَدِينَةِ ذَا الْحُلَيْفَةِ، وَلِأَهْلِ الشَّامِ الْجُحْفَةَ، وَلِأَهْلِ نَجْدٍ قَرْنَ الْمَنَازِلِ، وَلِأَهْلِ الْيَمَنِ يَلَمْلَمَ هُنَّ لَهُنَّ وَلِمَنْ أَتَى عَلَيْهِنَّ مِنْ غَيْرِهِنَّ مِمَّنْ أَرَادَ الْحَجَّ وَالْعُمْرَةَ، وَمَنْ كَانَ دُونَ ذَلِكَ فَمِنْ حَيْثُ أَنْشَأَ حَتَّى أَهْلُ مَكَّةَ مِنْ مَكَّةَ. (خ,ن)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) മദീനാ വാസികൾക്ക് ദുൽഹുലൈഫയും ശാമുകാർക്ക് ജുഹ്ഫയും നജ്ദുകാർക്ക് ഖർനുമനാസിലും യമൻകാർക്ക് യലംലമും മീഖാത്തായി നിശ്ചയിച്ചു. ഇവ അവർക്കും(തദ്ദേശവാസികൾ) ഹജ്ജും ഉംറയും ഉദ്ദേശിച്ച് ഇതിലൂടെ കടന്ന് വരുന്ന ഇതരർക്കുമുള്ളതാണ്. ഇതിലും കുറഞ്ഞ ദൂരമുള്ളവർക്ക് അവർ തുടങ്ങിയേടത്തു നിന്നാണ്(ഇഹ്റാം). മക്കക്കാർക്ക് മക്കയിൽ നിന്നാണ്.(ബു,ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 277, 277, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 99, 'عَنْ أَبِي الزُّبَيْرِ رَضِيَ اللهُ عَنْهُ : أَنَّهُ سَمِعَ جَابِرَ بْنَ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُمَا يُسْأَلُ عَنِ الْمُهَلِّ؟ فَقَالَ: سَمِعْتُ- أَحْسَبُهُ رَفَعَ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ- فَقَالَ: "مُهَلُّ أَهْلِ الْمَدِينَةِ مِنْ ذِي الْحُلَيْفَةِ، وَالطَّرِيقُ الْآخَرُ الْجُحْفَةُ، وَمُهَلُّ أَهْلِ الْعِرَاقِ مِنْ ذَاتِ عِرْقٍ، وَمُهَلُّ أَهْلِ نَجْدٍ مِنْ قَرْنٍ، وَمُهَلُّ أَهْلِ الْيَمَنِ مِنْ يَلَمْلَمَ. (م)', 'അബു സുബൈർ(റ): മീഖാത്തിനെക്കുറിച്ച് ജാബിർ(റ)നോട് ചോദിക്കുന്നതു അദ്ദേഹം കേട്ടു: ജാബിർ(റ) പറഞ്ഞു: ഞാൻ കേട്ടു: (അദ്ദേഹമിത് നബി(സ)യിലേക്ക് ചേർത്തു പറയുന്നതായി ഞാൻ മനസ്സിലാക്കിയിരുന്നു) റസൂൽ(സ) പറഞ്ഞു: "മദീനക്കാർ ഇഹ്റാം ചെയ്യേണ്ടത് ദുൽഹുലൈഫയിൽ നിന്നാണ്, മറ്റു വഴിക്കാർക്ക് ജുഹ്ഫയിൽ നിന്നും ഇറാഖുകാർ ദാതുഇർഖിൽ നിന്നും, നജ്ദുകാർ ഖർനിൽ നിന്നും യമൻകാർ യലംലമിൽ നിന്നുമാണ് ഇഹ്റാം ചെയ്യേണ്ടത്." (മു)', 'أَبِي الزُّبَيْرِ', 'അബു സുബൈർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 277, 277, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 100, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: وَقَّتَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِأَهْلِ الْمَشْرِقِ الْعَقِيقَ. (د,ت)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) പൗരസ്ത്യർക്ക് ''അഖീഖി''നെ മീഖാത്തായി നിശ്ചയിച്ചു. (ദ,തു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 278, 278, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 101, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهَا : أَنَّهَا سَمِعَتْ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ أَهَلَّ بِحَجَّةٍ أَوْ عُمْرَةٍ مِنَ الْمَسْجِدِ الْأَقْصَى إِلَى الْمَسْجِدِ الْحَرَامِ غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ وَمَا تَأَخَّرَ". أَوْ: "وَجَبَتْ لَهُ الْجَنَّةُ". (د,جه)', 'ഉമ്മു സലമ(റ): റസൂൽ(സ) പറയുന്നതു അവർ കേട്ടു: "ആരെങ്കിലും മസ്ജിദുൽ അഖ്സായിൽ നിന്ന് മസ്ജിദുൽ ഹറാം വരെ ഹജ്ജിനും ഉംറക്കും ഇഹ്റാം ചെയ്താൽ അവന്റെ കഴിഞ്ഞു പോയതും വരാനിരിക്കുന്നതുമായ പാപങ്ങൾ പൊറുക്കപ്പെടുന്നതാണ്." മറ്റൊരു റിപ്പോർട്ടിൽ: "അവന് സ്വർഗ്ഗം നിർബന്ധമാണ്." (ദ,ജ)', 'أُمِّ سَلَمَةَ', 'ഉമ്മു സലമ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 278, 278, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=4 and h.hadith_no=101), 1, null, 'മറ്റൊരു നിവേദനിൽ: "അവന് സ്വർഗ്ഗം നിർബന്ധമാണ്." (ദ,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 102, 'عَنِ الْحَارِثِ بْنِ عَمْرٍو السَّهْمِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: أَتَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ بِمِنًى أَوْ بِعَرَفَاتٍ، وَقَدْ أَطَافَ بِهِ النَّاسُ، قَالَ: فَتَجِيءُ الْأَعْرَابُ فَإِذَا رَأَوْا وَجْهَهُ قَالُوا: هَذَا وَجْهٌ مُبَارَكٌ، قَالَ: وَوَقَّتَ ذَاتَ عِرْقٍ لِأَهْلِ الْعِرَاقِ. (د,ن)', 'ഹാരിസുബ്നു അംറുസ്സഹ്മി(റ): റസൂൽ(സ) മിനാ അല്ലെങ്കിൽ അറഫയിലുള്ളപ്പോൾ ഞാനവിടത്തെ സമീപിച്ചു. നബി(സ)ക്കു ചുറ്റും ജനങ്ങളുണ്ടായിരുന്നു. അദ്ദേഹം തുടരുന്നു: കാട്ടറബികൾ വരുന്നുണ്ടായിരുന്നു. അവർ റസൂൽ(സ)യുടെ മുഖം കണ്ട് പറയുന്നുണ്ടായിരുന്നു: ഇതൊരു അനുഗ്രഹീത മുഖം തന്നെ. നിവേദകൻ പറഞ്ഞു: റസൂൽ(സ) ഇറാഖികൾക്ക് ദാതുഇർഖ് മീഖാത്തായി നിശ്ചയിച്ചു. (ദ,ന)', 'الْحَارِثِ بْنِ عَمْرٍو السَّهْمِيِّ', 'ഹാരിസുബ്നു അംറുസ്സഹ്മി(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 278, 278, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 103, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُ : أَنَّ رَجُلًا قَالَ: مِنْ أَيْنَ نُهِلُّ يَا رَسُولَ اللَّهِ؟ قَالَ: "يُهِلُّ أَهْلُ الْمَدِينَةِ مِنْ ذِي الْحُلَيْفَةِ، وَأَهْلُ الشَّامِ مِنَ الْجُحْفَةِ، وَأَهْلُ نَجْدٍ مِنْ قَرْنٍ، وَأَهْلُ الْيَمَنِ مِنْ يَلَمْلَمَ". (ق,ت)', 'ഇബ്നുഉമർ(റ): ഒരാൾ ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരേ, എവിടെ നിന്നാണ് ഞങ്ങൾ ഇഹ്റാം ചെയ്യേണ്ടത്? തിരുമേനി(സ) പറഞ്ഞു: "മദീനക്കാർ ദുൽഹുലൈഫയിൽ നിന്നും, ശാമുകാർ ജുഹ്ഫയിൽ നിന്നും, നജ്ദുകാർ ഖർനിൽ നിന്നും, യമനികൾ യലംലമിൽ നിന്നുമാണ് ഇഹ്റാം ചെയ്യേണ്ടത്." (ബു,മു,തു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 278, 278, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 104, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُ : أَنَّ رَجُلًا قَامَ فِي الْمَسْجِدِ فَقَالَ: يَا رَسُولَ اللَّهِ، مِنْ أَيْنَ تَأْمُرُنَا أَنْ نُهِلَّ؟ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "يُهِلُّ أَهْلُ الْمَدِينَةِ مِنْ ذِي الْحُلَيْفَةِ، وَيُهِلُّ أَهْلُ الشَّامِ مِنَ الْجُحْفَةِ، وَيُهِلُّ أَهْلُ نَجْدٍ مِنْ قَرْنٍ". قَالَ ابْنُ عُمَرَ: وَيَزْعُمُونَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "وَيُهِلُّ أَهْلُ الْيَمَنِ مِنْ يَلَمْلَمَ". وَكَانَ ابْنُ عُمَرَ يَقُولُ: لَمْ أَفْقَهْ هَذَا مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (ن)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): ഒരാൾ പള്ളിയിൽ എഴുന്നേറ്റു നിന്ന് ചോദിച്ചു: റസൂലേ, ഞങ്ങൾ എവിടെ നിന്ന് ഇഹ്റാം ചെയ്യാനാണ് അങ്ങ് കൽപിക്കുന്നത്? അവിടന്ന് മറുപടി പറഞ്ഞു: "മദീനക്കാർ ദുൽഹുലൈഫയിൽ നിന്നും, ശാമുകാർ ജുഹ്ഫയിൽ നിന്നും, നജ്ദുകാർ ഖർനിൽ നിന്നും" ഇബ്നുഉമർ(റ) പറഞ്ഞു: "യമനികൾ യലംലമിൽ നിന്നും" എന്ന് റസൂൽ(സ) പറഞ്ഞിട്ടുണ്ടെന്ന് അവർ പറയുന്നു. ഇബ്നുഉമർ(റ) പറയുന്നു: ഇത് ഞാൻ റസൂൽ(സ)യിൽ നിന്നും അറിഞ്ഞിട്ടില്ല. (ന)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 278, 278, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 105, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: وَقَّتَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِأَهْلِ الْمَدِينَةِ ذَا الْحُلَيْفَةِ، وَلِأَهْلِ الشَّامِ وَمِصْرَ الْجُحْفَةَ، وَلِأَهْلِ الْعِرَاقِ ذَاتَ عِرْقٍ، وَلِأَهْلِ الْيَمَنِ يَلَمْلَمَ. (ن)', 'ആഇശ(റ): റസൂൽ(സ) മദീനാ വാസികൾക്ക് ദുൽഹുലൈഫയും, ശാമുകാർക്കും ഈജിപ്തുകാർക്കും ജുഹ്ഫയും, ഇറാഖികൾക്ക് ദാതുഇർഖും, യമൻകാർക്ക് യലംലമും മീഖാത്തായി നിശ്ചയിച്ചു. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 278, 278, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 106, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: خَطَبَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "مُهَلُّ أَهْلِ الْمَدِينَةِ مِنْ ذِي الْحُلَيْفَةِ، وَمُهَلُّ أَهْلِ الشَّامِ مِنَ الْجُحْفَةِ، وَمُهَلُّ أَهْلِ الْيَمَنِ مِنْ يَلَمْلَمَ، وَمُهَلُّ أَهْلِ نَجْدٍ مِنْ قَرْنٍ، وَمُهَلُّ أَهْلِ الْمَشْرِقِ مِنْ ذَاتِ عِرْقٍ". ثُمَّ أَقْبَلَ بِوَجْهِهِ لِلْأُفُقِ ثُمَّ قَالَ: "اللَّهُمَّ أَقْبِلْ بِقُلُوبِهِمْ". (جه)', 'ജാബിർ(റ): റസൂൽ(സ) ഞങ്ങളോട് പ്രസംഗിച്ചു: "മദീനക്കാർ ദുൽഹുലൈഫയിൽ നിന്നും, ശാമുകാർ ജുഹ്ഫയിൽ നിന്നും, യമനികൾ യലംലമിൽ നിന്നും, നജ്ദുകാർ ഖർനിൽ നിന്നും, പൗരസ്ത്യർ ദാതുഇർഖിൽ നിന്നുമാണ് ഇഹ്റാം ചെയ്യേണ്ടത്." പിന്നെ റസൂൽ(സ) തന്റെ മുഖം മേൽപോട്ടുയർത്തി പറഞ്ഞു: "അല്ലാഹുവെ, അവരുടെ ഹൃദയങ്ങളെ നീ മുന്നിടീക്കണേ!." (ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 279, 279, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 107, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهُ : أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ أَهَلَّ بِعُمْرَةٍ مِنْ بَيْتِ الْمَقْدِسِ غُفِرَ لَهُ".
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=4 and h.hadith_no=107), 1, 'وَفِي رِوَايَةٍ: "مَنْ أَهَلَّ بِعُمْرَةٍ مِنْ بَيْتِ الْمَقْدِسِ كَانَتْ لَهُ كَفَّارَةً لِمَا قَبْلَهَا مِنَ الذُّنُوبِ". قَالَتْ: فَخَرَجْتُ- أَيْ مِنْ بَيْتِ الْمَقْدِسِ- بِعُمْرَةٍ. (د,جه)', 'മറ്റൊരു നിവേദനത്തിൽ: "ആരെങ്കിലും ബൈതുൽ മുഖദ്ദസിൽ നിന്നും ഉംറക്ക് ഇഹ്റാം ചെയ്താലത് അവന്റെ മുൻകഴിഞ്ഞ ദോഷങ്ങൾക്കുള്ള പ്രായശ്ചിത്തമാണ്." ഉമ്മുസലമ(റ) പറഞ്ഞു: ഞാൻ ബൈതുൽ മുഖദ്ദസിൽ നിന്ന് ഉംറക്ക് പുറപ്പെട്ടു. (ദ,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 108, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا [فِي رِوَايَةٍ] قَالَتْ: خَرَجْنَا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَلَا نُرَى إِلَّا أَنَّهُ الْحَجُّ فَلَمَّا قَدِمْنَا تَطَوَّفْنَا بِالْبَيْتِ، فَأَمَرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَنْ لَمْ يَكُنْ سَاقَ الْهَدْيَ أَنْ يَحِلَّ، فَحَلَّ مَنْ لَمْ يَكُنْ سَاقَ الْهَدْيَ، وَنِسَاؤُهُ لَمْ يَسُقْنَ فَأَحْلَلْنَ، قَالَتْ صَفِيَّةُ: مَا أُرَانِي إِلَّا حَابِسَتَهُمْ قَالَ: "عَقْرَى حَلْقَى أَوَ مَا طُفْتِ يَوْمَ النَّحْرِ"؟ قَالَتْ: قُلْتُ: بَلَى، قَالَ: "لَا بَأْسَ انْفِرِي". (خ)', 'ആഇശ(റ): ഹജ്ജല്ലാതെ മറ്റൊന്നും ഉദ്ദേശിക്കാതെ ഞങ്ങൾ റസൂൽ(സ)യോടൊപ്പം പുറപ്പെട്ടു. മക്കയിലെത്തിയപ്പോൾ കഅ്ബ ത്വവാഫ് ചെയ്തു. ഹദ്യ കൊണ്ടു വരാത്തവരോട് റസൂൽ(സ) ഇഹ്റാമിൽ നിന്ന് മുക്തമാവാൻ കല്പിച്ചപ്പോൾ അവർ അപ്രകാരം ചെയ്തു. റസൂൽ(സ)യുടെ പത്നിമാർ ഹദ്യ കൊണ്ടുവന്നിട്ടില്ലായിരുന്നു. അവരും തഹല്ലുലായി (ഇഹ്റാമിൽ നിന്ന് മുക്തമായി). സ്വഫിയ്യ(റ) പറഞ്ഞു: ഞാനവർക്ക് വിലങ്ങാവുമെന്ന് എനിക്കു തോന്നുന്നു. റസൂൽ(സ) പറഞ്ഞു: "നീ അറുക്കുക, മുടി വെട്ടുക. നീ പെരുന്നാളിനു ത്വവാഫ് ചെയ്തില്ലേ?" സ്വഫിയ്യ(റ) പറഞ്ഞു: അതെ. റസൂൽ(സ)പറഞ്ഞു: "എങ്കിൽ പ്രശ്നമില്ല, നീ വരിക." (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], 'فِي رِوَايَةٍ', null, 279, 279, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 109, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُ قَالَ: أَهْلَلْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالْحَجِّ مُفْرَدًا. وَفِي رِوَايَةٍ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَهَلَّ بِالْحَجِّ مُفْرَدًا. (م)', 'ഇബ്നുഉമർ(റ): ഞങ്ങൾ റസൂൽ(സ)യോടൊപ്പം ഹജ്ജിനു മാത്രം ഇഹ്റാം ചെയ്തു. മറ്റൊരു നിവേദനത്തിൽ: റസൂൽ(സ) ഹജ്ജിനു മാത്രം ഇഹ്റാം ചെയ്തു. (മു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 279, 279, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=4 and h.hadith_no=109), 1, 'وَفِي رِوَايَةٍ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَهَلَّ بِالْحَجِّ مُفْرَدًا. (م)', 'മറ്റൊരു നിവേദനത്തിൽ: റസൂൽ(സ) ഹജ്ജിനു മാത്രം ഇഹ്റാം ചെയ്തു. (മു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 110, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: خَرَجْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَامَ حَجَّةِ الْوَدَاعِ، فَمِنَّا مَنْ أَهَلَّ بِعُمْرَةٍ، وَمِنَّا مَنْ أَهَلَّ بِحَجٍّ وَعُمْرَةٍ، وَمِنَّا مَنْ أَهَلَّ بِالْحَجِّ، وَأَهَلَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالْحَجِّ، فَأَمَّا مَنْ أَهَلَّ بِالْحَجِّ- أَوْ جَمَعَ الْحَجَّ وَالْعُمْرَةَ- فَلَمْ يُحِلُّوا حَتَّى كَانَ يَوْمَ النَّحْرِ. وَفِي رِوَايَةٍ: فَأَمَّا مَنْ أَهَلَّ بِعُمْرَةٍ فَأَحَلَّ. (ق,د,ن,جه)', 'ആഇശ(റ): ഹജ്ജതുൽ വിദാഇൽ ഞങ്ങൾ റസൂൽ(സ)യോടൊപ്പം പുറപ്പെട്ടു. ഹജ്ജിന് ഇഹ്റാം ചെയ്തവരും ഉംറക്ക് ഇഹ്റാം ചെയ്തവരും ഹജ്ജിനും ഉംറക്കും ഇഹ്റാം ചെയ്തവരും ഞങ്ങളുടെ കൂട്ടത്തിലുണ്ടായിരുന്നു. റസൂൽ(സ) ഹജ്ജിനാണ് ഇഹ്റാം ചെയ്തത്. എന്നാൽ ഹജ്ജിന് ഇഹ്റാം ചെയ്തവരും അല്ലെങ്കിൽ ഹജ്ജിനും ഉംറക്കും ഒന്നിച്ച് ഇഹാറാം ചെയ്തവരും ബലിദിനം(പെരുന്നാൾ) വരെ ഇഹ്റാമിൽ നിന്ന് മുക്തമായില്ല. മറ്റൊരു നിവേദനത്തിൽ: ഉംറക്ക് ഇഹ്റാം ചെയ്തവർ തഹല്ലുലായി. (ബു,മു,ദ,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 280, 280, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=4 and h.hadith_no=110), 1, 'وَفِي رِوَايَةٍ: فَأَمَّا مَنْ أَهَلَّ بِعُمْرَةٍ فَأَحَلَّ. (ق,د,ن,جه)', 'മറ്റൊരു നിവേദനത്തിൽ: ഉംറക്ക് ഇഹ്റാം ചെയ്തവർ തഹല്ലുലായി. (ബു,മു,ദ,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 111, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: خَرَجْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي حَجَّةِ الْوَدَاعِ، فَأَهْلَلْنَا بِعُمْرَةٍ، ثُمَّ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ كَانَ مَعَهُ هَدْيٌ فَلْيُهِلَّ بِالْحَجِّ مَعَ الْعُمْرَةِ، ثُمَّ لَا يَحِلُّ حَتَّى يَحِلَّ مِنْهُمَا جَمِيعًا". فَقَدِمْتُ مَكَّةَ وَأَنَا حَائِضٌ، وَلَمْ أَطُفْ بِالْبَيْتِ، وَلَا بَيْنَ الصَّفَا وَالْمَرْوَةِ، فَشَكَوْتُ ذَلِكَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "انْقُضِي رَأْسَكِ، وَامْتَشِطِي وَأَهِلِّي بِالْحَجِّ، وَدَعِي الْعُمْرَةَ". قَالَتْ: فَفَعَلْتُ، فَلَمَّا قَضَيْنَا الْحَجَّ أَرْسَلَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَعَ عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرٍ إِلَى التَّنْعِيمِ، فَاعْتَمَرْتُ، فَقَالَ: "هَذِهِ مَكَانُ عُمْرَتِكِ". قَالَتْ: فَطَافَ الَّذِينَ أَهَلُّوا بِالْعُمْرَةِ بِالْبَيْتِ، وَبَيْنَ الصَّفَا وَالْمَرْوَةِ، ثُمَّ حَلُّوا، ثُمَّ طَافُوا طَوَافًا آخَرَ بَعْدَ أَنْ رَجَعُوا مِنْ مِنًى لِحَجِّهِمْ، وَأَمَّا الَّذِينَ كَانُوا جَمَعُوا الْحَجَّ وَالْعُمْرَةَ فَإِنَّمَا طَافُوا طَوَافًا وَاحِدًا. (ق,د,ن,جه)', 'ആഇശ(റ): ഹജ്ജതുൽ വിദാഇൽ ഞങ്ങൾ റസൂൽ(സ)യോടൊപ്പം പുറപ്പെട്ടു. ഞങ്ങൾ ഉംറക്ക് ഇഹ്റാം ചെയ്തു. പിന്നെ റസൂൽ(സ) പറഞ്ഞു: "ഹദ്യ കൂടെ ഉള്ളവർ ഉംറക്കൊപ്പം ഹജ്ജിനും ഇഹ്റാം ചെയ്യുക. അവരണ്ടിലെയും(കർമ്മങ്ങൾ) മുഴുവൻ കഴിഞ്ഞേ തഹല്ലുലാവാൻ പാടുള്ളൂ." ആർത്തവകാരിയായികൊണ്ട് ഞാൻ മക്കയിൽ പ്രവേശിച്ചു, ഞാൻ കഅ്ബയോ സ്വഫാ മർവയോ ത്വവാഫ് ചെയ്തില്ല. ഇക്കാര്യം ഞാൻ നബിയോട് പരാതിപ്പെട്ടപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നീ തലമുടി മെടയുകയും ചീകുകയും ചെയ്യുക. ഉംറ ഉപേക്ഷിച്ച് ഹജ്ജിന് ഇഹ്റാം ചെയ്യുക." ഞാനപ്രകാരം ചെയ്തു. ഞങ്ങൾ ഹജ്ജ് നിർവ്വഹിച്ചു കഴിഞ്ഞപ്പോൾ റസൂൽ(സ) എന്നെ അബ്ദുർറഹ്മാനോടൊപ്പം തൻഈമിലേക്ക് പറഞ്ഞയച്ചു. ഞാൻ ഉംറ ചെയ്തു. റസൂൽ(സ) പറഞ്ഞു: "ഇതാണു നിന്റെ ഉംറയുടെ സ്ഥാനം." ആയിശ പറഞ്ഞു: ഉംറക്ക് ഇഹ്റാം ചെയ്തവർ കഅ്ബയും സ്വഫാ മർവയും ത്വവാഫ് ചെയ്തശേഷം സ്വതന്ത്രരായി. മിനായിൽ നിന്ന് മടങ്ങിയശേഷം അവർ ഹജ്ജിനുവേണ്ടി മറ്റൊരു ത്വവാഫ് ചെയ്തു. എന്നാൽ ഹജ്ജും ഉംറയും ഒന്നിച്ച് നിർവ്വഹിച്ചവർ ഒരു ത്വവാഫ് മാത്രമേ ചെയ്തിട്ടുള്ളൂ. (ബു,മു,ദ,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 280, 280, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 112, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: لَبَّيْنَا بِالْحَجِّ، حَتَّى إِذَا كُنَّا بِسَرِفَ حِضْتُ، فَدَخَلَ عَلَيَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَنَا أَبْكِي، فَقَالَ: "مَا يُبْكِيكِ يَا عَائِشَةُ؟". فَقُلْتُ: حِضْتُ، لَيْتَنِي لَمْ أَكُنْ حَجَجْتُ، فَقَالَ: "سُبْحَانَ اللَّهِ، إِنَّمَا ذَلِكَ شَيْءٌ كَتَبَهُ اللَّهُ عَلَى بَنَاتِ آدَمَ". فَقَالَ: "انْسُكِي الْمَنَاسِكَ كُلَّهَا، غَيْرَ أَنْ لَا تَطُوفِي بِالْبَيْتِ". فَلَمَّا دَخَلْنَا مَكَّةَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ شَاءَ أَنْ يَجْعَلَهَا عُمْرَةً فَلْيَجْعَلْهَا عُمْرَةً، إِلَّا مَنْ كَانَ مَعَهُ الْهَدْيُ". قَالَتْ: وَذَبَحَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ نِسَائِهِ الْبَقَرَ يَوْمَ النَّحْرِ، فَلَمَّا كَانَتْ لَيْلَةُ الْبَطْحَاءِ وَطَهُرَتْ عَائِشَةُ قَالَتْ: يَا رَسُولَ اللَّهِ، أَتَرْجِعُ صَوَاحِبِي بِحَجٍّ وَعُمْرَةٍ، وَأَرْجِعُ أَنَا بِالْحَجِّ؟ فَأَمَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَبْدَ الرَّحْمَنِ بْنَ أَبِي بَكْرٍ فَذَهَبَ بِهَا إِلَى التَّنْعِيمِ، فَلَبَّتْ بِالْعُمْرَةِ. (ق,د,ن)', 'ആഇശ(റ): ഞങ്ങൾ ഹജ്ജിന് ഇഹ്റാം ചെയ്തു. സരിഫിലെത്തിയപ്പോൾ എനിക്ക് ആർത്തവമുണ്ടായി. റസൂൽ(സ) എന്റെ അടുത്തേക്ക് വന്നപ്പോൾ ഞാൻ കരയുന്നതു കണ്ടു. അപ്പോൾ റസൂൽ(സ) ചോദിച്ചു: "എന്തിനാണ് ആഇശാ നീ കരയുന്നത്?" ഞാൻ പറഞ്ഞു: എനിക്ക് ആർത്തവം തുടങ്ങി, ഞാൻ ഹജ്ജിനു വന്നില്ലായിരുന്നെങ്കിൽ എത്ര നന്നായേനെ!. റസൂൽ(സ) പറഞ്ഞു: "സുബ്ഹാനല്ലാഹ്, ഇത് (ആർത്തവം) ആദം പെൺമക്കൾക്ക് അല്ലാഹു നിശ്ചയിച്ച ഒരു കാര്യമാണ്." റസൂൽ(സ) പറഞ്ഞു: "കഅ്ബ ത്വവാഫൊഴിച്ച് മറ്റെല്ലാ കർമ്മങ്ങളും നീ ചെയ്യുക." ഞങ്ങൾ മക്കയിലെത്തിയപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും ഉംറ ചെയ്യാൻ ഉദ്ദേശിച്ചാൽ അവരത് ചെയ്യുക, ഹദ്യ ഉള്ളവർ ഒഴികെ." ആഇശ(റ) പറയുന്നു: പെരുന്നാൾ ദിവസം റസൂൽ(സ) തന്റെ പത്നിമാർക്കായി പശുവിനെ അറുത്തു. കല്ലേറിന്റെ രാത്രിയായപ്പോൾ (ആയിശ(റ) ശുദ്ധിയായി. അവർ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, എന്നോടൊപ്പമുള്ളവർ ഹജ്ജും ഉംറയുമായി മടങ്ങുമ്പോൾ ഞാൻ വെറും ഹജ്ജ് മാത്രവുമായി മടങ്ങുകയോ? അങ്ങനെ റസൂൽ(സ)യുടെ കല്പന പ്രകാരം ആഇശ(റ) അബ്ദുർറഹ്മാനോടൊപ്പം തൻഈമിൽ പോയി ഉംറക്ക് ഇഹ്റാം ചെയ്തു. (ബു,മു,ദ,ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 280, 281, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 113, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَقْبَلْنَا مُهِلِّينَ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالْحَجِّ مُفْرَدًا، وَأَقْبَلَتْ عَائِشَةُ مُهِلَّةً بِعُمْرَةٍ، حَتَّى إِذَا كَانَتْ بِسَرِفَ عَرَكَتْ، حَتَّى إِذَا قَدِمْنَا طُفْنَا بِالْكَعْبَةِ، وَبِالصَّفَا وَالْمَرْوَةِ، فَأَمَرَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يُحِلَّ مِنَّا مَنْ لَمْ يَكُنْ مَعَهُ هَدْيٌ، قَالَ: فَقُلْنَا: حِلُّ مَاذَا؟ فَقَالَ: "الْحِلُّ كُلُّهُ". فَوَاقَعْنَا النِّسَاءَ، وَتَطَيَّبْنَا بِالطِّيبِ، وَلَبِسْنَا ثِيَابَنَا، وَلَيْسَ بَيْنَنَا وَبَيْنَ عَرَفَةَ إِلَّا أَرْبَعُ لَيَالٍ، ثُمَّ أَهْلَلْنَا يَوْمَ التَّرْوِيَةِ، ثُمَّ دَخَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى عَائِشَةَ فَوَجَدَهَا تَبْكِي، فَقَالَ: "مَا شَأْنُكِ؟". قَالَتْ: شَأْنِي أَنِّي قَدْ حِضْتُ، وَقَدْ حَلَّ النَّاسُ وَلَمْ أُحْلِلْ، وَلَمْ أَطُفْ بِالْبَيْتِ، وَالنَّاسُ يَذْهَبُونَ إِلَى الْحَجِّ الْآنَ، فَقَالَ: "إِنَّ هَذَا أَمْرٌ كَتَبَهُ اللَّهُ عَلَى بَنَاتِ آدَمَ، فَاغْتَسِلِي ثُمَّ أَهِلِّي بِالْحَجِّ". فَفَعَلَتْ، وَوَقَفَتِ الْمَوَاقِفَ، حَتَّى إِذَا طَهُرَتْ طَافَتْ بِالْبَيْتِ وَبِالصَّفَا وَالْمَرْوَةِ، ثُمَّ قَالَ: "قَدْ حَلَلْتِ مِنْ حَجِّكِ وَعُمْرَتِكِ جَمِيعًا". قَالَتْ: يَا رَسُولَ اللَّهِ، إِنِّي أَجِدُ فِي نَفْسِي أَنِّي لَمْ أَطُفْ بِالْبَيْتِ حِينَ حَجَجْتُ؟ قَالَ: "فَاذْهَبْ بِهَا يَا عَبْدَ الرَّحْمَنِ فَأَعْمِرْهَا مِنَ التَّنْعِيمِ". وَذَلِكَ لَيْلَةَ الْحَصْبَةِ. وَفِي رِوَايَةٍ: "ثُمَّ حُجِّي، وَاصْنَعِي مَا يَصْنَعُ الْحَاجُّ، غَيْرَ أَنْ لَا تَطُوفِي بِالْبَيْتِ وَلَا تُصَلِّي" عِنْدَ قَوْلِهِ: "وَأَهِلِّي بِالْحَجِّ". (م,د,ن)', 'ജാബിർ(റ): ഹജ്ജിനു മാത്രം ഇഹ്റാം ചെയ്ത് ഞങ്ങൾ റസൂൽ(സ)യോടൊപ്പം പുറപ്പെട്ടു. ആഇശ(റ) ഉംറക്ക് ഇഹ്റാം ചെയ്തായിരുന്നു പുറപ്പെട്ടത്. സരിഫിലെത്തിയപ്പോൾ അവർക്ക് ആർത്തവമുണ്ടായി. ഞങ്ങൾ മക്കയിലെത്തിയപ്പോൾ കഅ്ബയും സ്വഫാ മർവയും ത്വവാഫ് ചെയ്തു. ഞങ്ങളിൽ ഹദ്യ കൂടെയില്ലാത്തവരോട് തഹല്ലുലാവാൻ റസൂൽ(സ) കൽപിച്ചു. ഞങ്ങൾ ചോദിച്ചു: ഏതുതരം തഹല്ലുലാണ്? റസൂൽ(സ) പറഞ്ഞു: "പൂർണ്ണമായ തഹല്ലുൽ." അങ്ങനെ ഞങ്ങൾ ഭാര്യമാരുമായി ബന്ധപ്പെടുകയും സുഗന്ധം പുശുകയും (തുന്നിയ) വസ്ത്രം ധരിക്കുകയും ചെയ്തു. ഞങ്ങൾക്കും അറഫാ ദിനത്തിനുമിടയിൽ നാല് രാത്രികളലാണ് ബാക്കിയുണ്ടായിരുന്നത്. പിന്നീട് തർവിയ ദിനത്തിൽ ഞങ്ങൾ ഇഹ്റാം ചെയ്തു. പിന്നെ ആഇശ(റ)യുടെയടുത്തു ചെന്നപ്പോൾ അവർ കരയുന്നതു കണ്ട റസൂൽ(സ) ചോദിച്ചു: "എന്തുപറ്റി?" അവർ പറഞ്ഞു: ആർത്തവം തുടങ്ങി, ജനങ്ങൾ തഹല്ലുലായപ്പോൾ ഞാൻ ആയില്ല. ഞാൻ കഅ്ബ ത്വവാഫ് ചെയ്തിട്ടില്ല. ഇപ്പോഴിതാ ജനങ്ങൾ ഹജ്ജിനു പോവുന്നു. റസൂൽ(സ) പറഞ്ഞു: "ഇത് (ആർത്തവം) ആദംപെൺമക്കൾക്ക് അല്ലാഹു നിശ്ചയിച്ച ഒരു കാര്യമാണ്. ആയതിനാൽ നീ കുളിച്ച് ഹജ്ജിന് ഇഹ്റാം ചെയ്യുക." അവർ (നബിയുടെ) കല്പനപ്രകാരം ചെയ്തു. നിൽക്കേണ്ടിടത്തെല്ലാം നിന്നു. ശുദ്ധിയായശേഷം കഅ്ബയും സ്വഫാ മർവയും ത്വവാഫ് ചെയ്തു. റസൂൽ(സ) പറഞ്ഞു: "നിന്റെ ഹജ്ജിൽ നിന്നും ഉംറയിൽ നിന്നും നീ സ്വതന്ത്രയായി." ആഇശ(റ) പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ഹജ്ജിന് കഅ്ബ ത്വവാഫ് ചെയ്യാത്തതിൽ എനിക്കു വിഷമമുണ്ട്. റസൂൽ(സ) പറഞ്ഞു: "അബ്ദുർറഹ്മാൻ, നീ അവളുമായി തൻഈമിൽ ചെന്ന് ഉംറക്ക് (ഇഹ്റാം) ചെയ്യിക്കു." അത് കല്ലേറിന്റെ രാത്രിയായിരുന്നു. മറ്റൊരു നിവേദനത്തിൽ: "ഹജ്ജിന് നീ ഇഹ്റാം ചെയ്യുക." മറ്റൊരു നിവേദനത്തിൽ, "പിന്നെ ഹജ്ജ് ചെയ്യുക" എന്ന റസൂൽ(സ)യുടെ വാക്കിനു ശേഷം "ഹാജി ചെയ്യുന്നതെല്ലാം ചെയ്യുക. പക്ഷേ, ത്വവാഫും നിസ്കാരവും നീ ചെയ്യരുത്." എന്നു കൂടിയുണ്ട്. (മു,ദ,ന)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['م','د','ن']::text[], array['മു','ദ','ന']::text[], null, null, 281, 282, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=4 and h.hadith_no=113), 1, 'وَفِي رِوَايَةٍ: "ثُمَّ حُجِّي، وَاصْنَعِي مَا يَصْنَعُ الْحَاجُّ، غَيْرَ أَنْ لَا تَطُوفِي بِالْبَيْتِ وَلَا تُصَلِّي" عِنْدَ قَوْلِهِ: "وَأَهِلِّي بِالْحَجِّ". (م,د,ن)', 'മറ്റൊരു നിവേദനത്തിൽ: "ഹജ്ജിന് നീ ഇഹ്റാം ചെയ്യുക."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=4 and h.hadith_no=113), 2, null, 'മറ്റൊരു നിവേദനത്തിൽ, "പിന്നെ ഹജ്ജ് ചെയ്യുക" എന്ന റസൂൽ(സ)യുടെ വാക്കിനു ശേഷം "ഹാജി ചെയ്യുന്നതെല്ലാം ചെയ്യുക. പക്ഷേ, ത്വവാഫും നിസ്കാരവും നീ ചെയ്യരുത്." എന്നു കൂടിയുണ്ട്. (മു,ദ,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 114, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُ قَالَ: أَهْلَلْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالْحَجِّ خَالِصًا، لَا يُخَالِطُهُ شَيْءٌ، فَقَدِمْنَا مَكَّةَ لِأَرْبَعِ لَيَالٍ خَلَوْنَ مِنْ ذِي الْحِجَّةِ، فَطُفْنَا وَسَعَيْنَا، ثُمَّ أَمَرَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ نُحِلَّ، وَقَالَ: "لَوْلَا هَدْيِي لَحَلَلْتُ". ثُمَّ قَامَ سُرَاقَةُ بْنُ مَالِكٍ فَقَالَ: يَا رَسُولَ اللَّهِ، أَرَأَيْتَ مُتْعَتَنَا هَذِهِ، أَلِعَامِنَا هَذَا أَمْ لِلْأَبَدِ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "بَلْ هِيَ لِلْأَبَدِ". (ق,د,ن,جه)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): ഞങ്ങൾ റസൂൽ(സ)യോടൊപ്പം ഹജ്ജിനു മാത്രം ഇഹ്റാം ചെയ്തു. അതോടൊപ്പം മറ്റൊന്നുമുണ്ടായിരുന്നില്ല. ദുൽഹിജ്ജ നാല് രാത്രികഴിഞ്ഞ് ഞങ്ങൾ മക്കയിലെത്തി ത്വവാഫും സഅ്യും നിർവ്വഹിച്ചു. റസൂൽ(സ) ഞങ്ങളോട് തഹല്ലുലാവാൻ കൽപിച്ചു. അവിടന്ന് പറഞ്ഞു: "ഹദ്യ ഇല്ലായിരുന്നുവെങ്കിൽ ഞാനും തഹല്ലുലാവുമായിരുന്നു." അപ്പോൾ സുറാഖഃ എഴുന്നേറ്റു നിന്ന് ചോദിച്ചു: തിരുദൂതരെ, നമ്മുടെ ഈ തമത്തുഅ് ഈ വർഷത്തേക്ക് പ്രത്യേകമായതാണോ അതോ എക്കാലവുമുണ്ടോ? അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "അതെ, എക്കാലവുമുണ്ട്." (ബു,മു,ദ,ന,ജ)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 282, 282, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 115, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَدِمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَصْحَابُهُ لِأَرْبَعِ لَيَالٍ خَلَوْنَ مِنْ ذِي الْحِجَّةِ، فَلَمَّا طَافُوا بِالْبَيْتِ وَبِالصَّفَا وَالْمَرْوَةِ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "اجْعَلُوهَا عُمْرَةً، إِلَّا مَنْ كَانَ مَعَهُ الْهَدْيُ". فَلَمَّا كَانَ يَوْمُ التَّرْوِيَةِ أَهَلُّوا بِالْحَجِّ، فَلَمَّا كَانَ يَوْمُ النَّحْرِ قَدِمُوا فَطَافُوا بِالْبَيْتِ، وَلَمْ يَطُوفُوا بَيْنَ الصَّفَا وَالْمَرْوَةِ . (ق,د,ن,جه)', 'ജാബിർ(റ): റസൂൽ(സ)യും അനുചരന്മാരും ദുൽഹിജ്ജ നാല് രാത്രി കഴിഞ്ഞ് മക്കയിൽ വന്നു. അവർ കഅ്ബ, സ്വഫാ, മർവ്വ എന്നിവ ത്വവാഫ് ചെയ്തപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ഹദ്യ കൂടെ ഇല്ലാത്തവർ ഇത് ഉംറയാക്കുക." തർവിയത്ത് ദിനത്തിൽ അവർ ഹജ്ജിന് ഇഹ്റാം ചെയ്തു. ബലി ദിനത്തിൽ അവർ മക്കയിൽ വന്ന് കഅബ ത്വവാഫ് ചെയ്തു. സ്വഫാ മർവ്വക്കിടയിൽ ത്വവാഫ് ചെയ്തില്ല. (ബു,മു,ദ,ന,ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 282, 282, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 116, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَهَلَّ هُوَ وَأَصْحَابُهُ بِالْحَجِّ، وَلَيْسَ مَعَ أَحَدٍ مِنْهُمْ يَوْمَئِذٍ هَدْيٌ، إِلَّا النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَطَلْحَةَ، وَكَانَ عَلِيٌّ رَضِيَ اللهُ عَنْهُ قَدِمَ مِنَ الْيَمَنِ وَمَعَهُ الْهَدْيُ، فَقَالَ: أَهْلَلْتُ بِمَا أَهَلَّ بِهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَإِنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمَرَ أَصْحَابَهُ أَنْ يَجْعَلُوهَا عُمْرَةً: يَطُوفُوا، ثُمَّ يُقَصِّرُوا، وَيُحِلُّوا، إِلَّا مَنْ كَانَ مَعَهُ الْهَدْيُ، فَقَالُوا: أَنَنْطَلِقُ إِلَى مِنًى وَذُكُورُنَا تَقْطُرُ؟ فَبَلَغَ ذَلِكَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: "لَوْ أَنِّي اسْتَقْبَلْتُ مِنْ أَمْرِي مَا اسْتَدْبَرْتُ مَا أَهْدَيْتُ، وَلَوْلَا أَنَّ مَعِي الْهَدْيَ لَأَحْلَلْتُ". (خ,د)', 'ജാബിർ(റ): റസൂൽ(സ)യും അനുചരന്മാരും ഹജ്ജിന് ഇഹ്റാം ചെയ്തു. റസൂൽ(സ)ക്കും ത്വൽഹ(റ)വിനുമൊഴികെ മറ്റാരുടെയും കൂടെ ഹദ്യ മൃഗം ഉണ്ടായിരുന്നില്ല. യമനിൽ നിന്നു വന്ന അലി(റ)വിന്റെ പക്കൽ ഹദ്യ മൃഗമുണ്ടായിരുന്നു. അലി(റ) പറഞ്ഞു: റസൂൽ(സ) ഇഹ്റാം ചെയ്തതിന് ഞാനും ഇഹ്റാം ചെയ്തു. റസൂൽ(സ) തന്റെ അനുചരന്മാരോട് അത് ഉംറയാക്കാൻ കല്പിച്ചു; ത്വവാഫ് ചെയ്യുക, മുടി വെട്ടുക, തഹല്ലുലാവുക. ഹദ്യ കൂടെയുള്ളവരൊഴികെ. അവർ ചോദിച്ചു: ഞങ്ങളുടെ പുരുഷൻമാർ ഈറൻ ഉറ്റിവീഴുന്നവരായികൊണ്ട്(തലയിൽനിന്ന്) ഞങ്ങൾ മിനായിലേക്കു പോവുകയോ? ഇക്കാര്യം റസൂൽ(സ) അറിഞ്ഞു. റസൂൽ(സ) പറഞ്ഞു: "ഞാൻ ശേഷം അറിഞ്ഞത് മുമ്പേ അറിഞ്ഞിരുന്നുവെങ്കിൽ ഞാൻ ഹദ്യ കൊണ്ടുവരുമായിരുന്നില്ല. എന്നോടൊപ്പം ഹദ്യ ഇല്ലായിരുന്നെങ്കിൽ ഞാനും തഹല്ലുലാവുമായിരുന്നു." (ബു,ദ)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിർ(റ)', null, null, array['خ','د']::text[], array['ബു','ദ']::text[], null, null, 282, 283, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 117, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا أَهَلَّ الرَّجُلُ بِالْحَجِّ، ثُمَّ قَدِمَ مَكَّةَ فَطَافَ بِالْبَيْتِ وَبِالصَّفَا وَالْمَرْوَةِ فَقَدْ حَلَّ، وَهِيَ عُمْرَةٌ". (د)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ഹജ്ജിന് ഇഹ്റാം ചെയ്തവൻ മക്കയിൽ വന്ന് കഅ്ബ, സ്വഫാ, മർവ്വ എന്നിവ ത്വവാഫ് ചെയ്ത് സ്വതന്ത്രനായാൽ അത് ഉംറയാണ്." (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 283, 283, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 118, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: أَهَلَّ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالْحَجِّ، فَلَمَّا قَدِمَ طَافَ بِالْبَيْتِ وَبَيْنَ الصَّفَا وَالْمَرْوَةِ، وَلَمْ يُقَصِّرْ، وَلَمْ يُحِلَّ مِنْ أَجْلِ الْهَدْيِ، وَأَمَرَ مَنْ لَمْ يَكُنْ سَاقَ الْهَدْيَ أَنْ يَطُوفَ، وَأَنْ يَسْعَى وَيُقَصِّرَ ثُمَّ يُحِلَّ، أَوْ يَحْلِقَ ثُمَّ يُحِلَّ. (م,د,ت)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) ഹജ്ജിന് ഇഹ്റാം ചെയ്ത് മക്കയിൽ വന്ന് കഅ്ബ, സ്വഫ, മർവ്വ ഇവക്കിടയിൽ ത്വവാഫ് ചെയ്തു. മുടി മുറിച്ചില്ല. ഹദ്യ ഉള്ളതിനാൽ തഹല്ലുലായില്ല. ഹദ്യ കൂടെ ഇല്ലാത്തവരോട് ത്വവാഫും സഅ്യും ചെയ്ത് മുടി മുറിച്ച് പിന്നെ തഹല്ലുലാവാൻ പറഞ്ഞു. അല്ലെങ്കിൽ മുടി കളഞ്ഞ് തഹല്ലുലാവാൻ കല്പിച്ചു. (മു,ദ,തു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], null, null, 283, 283, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 119, 'عَنْ سَعِيدِ بْنِ الْمُسَيِّبِ رَضِيَ اللهُ عَنْهُ : أَنَّ رَجُلًا مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَتَى عُمَرَ بْنَ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ، فَشَهِدَ عِنْدَهُ أَنَّهُ سَمِعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي مَرَضِهِ الَّذِي قُبِضَ فِيهِ يَنْهَى عَنِ الْعُمْرَةِ قَبْلَ الْحَجِّ. (د)', 'സഈദുബ്നുൽ മുസയ്യിബ്(റ): റസൂൽ(സ)യുടെ ഒരു അനുചരൻ ഉമർ(റ)വിന്റെ അടുത്ത് വന്ന്, റസൂൽ(സ) മരണാസന്ന രോഗബാധിതനായിരിക്കെ ഹജ്ജിനു മുൻപ് ഉംറ ചെയ്യുന്നത് വിരോധിച്ചിരിക്കുന്നത് താൻ റസൂൽ(സ)യിൽ നിന്ന് കേട്ടതായി സാക്ഷ്യം വഹിച്ചു. (ദ)', 'سَعِيدِ بْنِ الْمُسَيِّبِ', 'സഈദുബ്നുൽ മുസയ്യിബ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 283, 283, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 120, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَبَا بَكْرٍ وَعُمَرَ وَعُثْمَانَ أَفْرَدُوا الْحَجَّ. (جه)', 'ജാബിർ(റ): റസൂൽ(സ)യും അബൂബക്കർ(റ)വും ഉമർ(റ)വും ഉസ്മാൻ(റ)വും ഹജ്ജ് ഒറ്റക്ക് (ഇഫ്റാദായി) നിർവ്വഹിച്ചു. (ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 283, 283, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 121, 'عَنْ عُثْمَانَ رَضِيَ اللهُ عَنْهُ أَنَّهُ نَهَى عَنِ الْمُتْعَةِ وَأَنْ يُجْمَعَ بَيْنَهُمَا، فَلَمَّا رَأَى عَلِيٌّ أَهَلَّ بِهِمَا: لَبَّيْكَ بِعُمْرَةٍ وَحَجَّةٍ، قَالَ: مَا كُنْتُ لِأَدَعَ سُنَّةَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِقَوْلِ أَحَدٍ. (خ)', 'ഉസ്മാൻ(റ): തമത്തുആയി ഹജ്ജ് ചെയ്യുന്നതും ഹജ്ജും ഉംറയും ഒന്നിച്ചു നിർവ്വഹിക്കുന്നതും ഉസ്മാൻ(റ) വിലക്കി. അലി(റ) ഇതു കണ്ടപ്പോൾ രണ്ടിനും ഇഹ്റാം ചെയ്തു: ഹജ്ജ് കൊണ്ടും ഉംറ കൊണ്ടും അല്ലാഹുവേ ഞാൻ നിന്റെ വിളിക്കിതാ ഉത്തരം നൽകുന്നു. അലി(റ) പറഞ്ഞു: ആരുടെ വാക്കുകേട്ടും തിരുമേനി(സ)യുടെ സുന്നത് ഞാൻ ഉപേക്ഷിക്കുകയില്ല. (ബു)', 'عُثْمَانَ', 'ഉസ്മാൻ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 283, 283, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 122, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: "هَذِهِ عُمْرَةٌ اسْتَمْتَعْنَا بِهَا، فَمَنْ لَمْ يَكُنْ عِنْدَهُ هَدْيٌ فَلْيَحِلَّ الْحِلَّ كُلَّهُ، وَقَدْ دَخَلَتِ الْعُمْرَةُ فِي الْحَجِّ إِلَى يَوْمِ الْقِيَامَةِ". (م,د,ن)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "നാം തമത്തുഅ് ആയി ചെയ്യുന്ന ഉംറയാണിത്. ഹദ്യ കൂടെയില്ലാത്തവർ പൂർണ്ണമായും തഹല്ലുലാവുക. അന്ത്യനാൾ വരെ ഉംറ ഹജ്ജിൽ ഉൾപ്പെട്ടതാണ്." (മു,ദ,ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['م','د','ن']::text[], array['മു','ദ','ന']::text[], null, null, 284, 284, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 123, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّهُ سَأَلَهُ رَجُلٌ عَنِ التَّمَتُّعِ وَقَالَ: نَهَانِي نَاسٌ عَنْهُ فَأَمَرَهُ بِهِ قَالَ الرَّجُلُ: فَرَأَيْتُ فِي الْمَنَامِ كَأَنَّ رَجُلًا يَقُولُ لِي: حَجٌّ مَبْرُورٌ وَعُمْرَةٌ مُتَقَبَّلَةٌ. قَالَ: فَأَخْبَرْتُ ابْنَ عَبَّاسٍ فَقَالَ: سُنَّةَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (خ)', 'ഇബ്നുഅബ്ബാസ്(റ): ഒരാൾ ഇബ്നുഅബ്ബാസ്(റ)വിനോട് തമത്തുഇനെക്കുറിച്ച് ചോദിച്ചു. അയാൾ പറയുകയും ചെയ്തു: ചിലയാളുകൾ അതിൽ നിന്ന് എന്നെ വിലക്കിയിരിക്കുന്നു. ഇബ്നുഅബ്ബാസ്(റ) അത് അനുദവനീയമാണെന്ന് പറഞ്ഞു. അയാൾ പറയുന്നു: സ്വീകാര്യമായ ഹജ്ജും പൂർണ്ണമായ ഉംറയും എന്ന് ഒരാൾ എന്നോട് പറയുന്നതായി ഞാൻ സ്വപ്നം കണ്ടു. ഞാനത് ഇബ്നുഅബ്ബാസ്(റ)വിനെ അറിയിച്ചു. അപ്പോൾ ഇബ്നുഅബ്ബാസ്(റ) പറഞ്ഞു: അത് റസൂൽ(സ)യുടെ സുന്നത്തുമാണ്. (ബു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 284, 284, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 124, 'عَنْ أَبِي مُوسَى رَضِيَ اللهُ عَنْهُ قَالَ: بَعَثَنِي النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى قَوْمٍ بِالْيَمَنِ، فَجِئْتُ وَهُوَ بِالْبَطْحَاءِ، فَقَالَ: "بِمَا أَهْلَلْتَ؟". قُلْتُ: أَهْلَلْتُ كَإِهْلَالِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "هَلْ مَعَكَ مِنْ هَدْيٍ؟". قُلْتُ: لَا، فَأَمَرَنِي فَطُفْتُ بِالْبَيْتِ وَبِالصَّفَا وَالْمَرْوَةِ، ثُمَّ أَمَرَنِي فَأَحْلَلْتُ، فَأَتَيْتُ امْرَأَةً مِنْ قَوْمِي، فَمَشَطَتْنِي أَوْ غَسَلَتْ رَأْسِي، فَقَدِمَ عُمَرُ رَضِيَ اللهُ عَنْهُ فَقَالَ: إِنْ نَأْخُذْ بِكِتَابِ اللَّهِ فَإِنَّهُ يَأْمُرُنَا بِالتَّمَامِ، قَالَ اللَّهُ تَعَالَى: {وَأَتِمُّوا الْحَجَّ وَالْعُمْرَةَ لِلَّهِ} وَإِنْ نَأْخُذْ بِسُنَّةِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَإِنَّهُ لَمْ يَحِلَّ حَتَّى نَحَرَ الْهَدْيَ. (خ,ن)', 'അബൂമൂസ(റ): റസൂൽ(സ) യമനിലുള്ള ഒരു സമൂഹത്തിലേക്ക് എന്നെ അയച്ചു. റസൂൽ(സ) ബത്ഹാഇലായിരിക്കെ ഞാൻ ചെന്നു. റസൂൽ(സ) ചോദിച്ചു: "എങ്ങനെയാണ് നീ ഇഹ്റാം ചെയ്തത്?" ഞാൻ പറഞ്ഞു: തിരുമേനി(സ) ഇഹ്റാം ചെയ്തതു പോലെ. റസൂൽ(സ) ചോദിച്ചു: "നിന്നോടൊപ്പം ഹദ്യയുണ്ടോ? ഞാൻ പറഞ്ഞു: ഇല്ല. അപ്പോൾ റസൂൽ(സ) എന്നോട് കഅ്ബ, സ്വഫാ, മർവ്വ എന്നിവ ത്വവാഫ് ചെയ്യാനും, പിന്നെ തഹല്ലുലാവാനും കല്പിച്ചു. അങ്ങനെ ഞാനെന്റെ ജനതയിലെ എന്റെ സ്ത്രീയുടെയടുത്തു ചെന്നു. അവളെന്റെ മുടി ചീകി. അല്ലെങ്കിൽ തല കഴുകി. അപ്പോൾ ഉമർ(റ) വന്ന് പറഞ്ഞു: ഖുർആൻ അനുസരിച്ചാണ് നാം കാര്യങ്ങൾ ചെയ്യുന്നതെങ്കിൽ, പൂർണ്ണമാക്കി അതു ചെയ്യാനാണ് കല്പിക്കുന്നത്. അല്ലാഹു പറയുന്നു: ''നിങ്ങൾ അല്ലാഹുവിനു വേണ്ടി ഹജ്ജും ഉംറയും പൂർത്തിയാക്കുക.'' റസൂൽ(സ) ചര്യയാണ് നാം സ്വീകരിക്കുന്നതെങ്കിൽ റസൂൽ(സ) ഹദ്യ അറുത്തശേഷമല്ലാതെ തഹല്ലുലായിട്ടില്ല. (ബു,ന)', 'أَبِي مُوسَى', 'അബൂമൂസ(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 284, 284, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 125, 'عَنْ مُوسَى بْنِ نَافِعٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَدِمْتُ مَكَّةَ مُتَمَتِّعًا بِعُمْرَةٍ قَبْلَ التَّرْوِيَةِ بِأَرْبَعَةِ أَيَّامٍ، فَقَالَ النَّاسُ: تَصِيرُ حَجَّتُكَ الْآنَ مَكِّيَّةً، فَدَخَلْتُ عَلَى عَطَاءِ بْنِ أَبِي رَبَاحٍ فَاسْتَفْتَيْتُهُ، فَقَالَ عَطَاءٌ: حَدَّثَنِي جَابِرُ بْنُ عَبْدِ اللَّهِ الْأَنْصَارِيُّ رَضِيَ اللهُ عَنْهُمَا: أَنَّهُ حَجَّ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَامَ سَاقَ الْهَدْيَ مَعَهُ، وَقَدْ أَهَلُّوا بِالْحَجِّ مُفْرَدًا، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَحِلُّوا مِنْ إِحْرَامِكُمْ، فَطُوفُوا بِالْبَيْتِ وَبَيْنَ الصَّفَا وَالْمَرْوَةِ وَقَصِّرُوا، وَأَقِيمُوا حَلَالًا، حَتَّى إِذَا كَانَ يَوْمُ التَّرْوِيَةِ فَأَهِلُّوا بِالْحَجِّ، وَاجْعَلُوا الَّتِي قَدِمْتُمْ بِهَا مُتْعَةً". قَالُوا: كَيْفَ نَجْعَلُهَا مُتْعَةً وَقَدْ سَمَّيْنَا الْحَجَّ؟ قَالَ: "افْعَلُوا مَا آمُرُكُمْ بِهِ، فَإِنِّي لَوْلَا أَنِّي سُقْتُ الْهَدْيَ لَفَعَلْتُ مِثْلَ الَّذِي أَمَرْتُكُمْ بِهِ، وَلَكِنْ لَا يَحِلُّ مِنِّي حَرَامٌ، حَتَّى يَبْلُغَ الْهَدْيُ مَحِلَّهُ". فَفَعَلُوا. (م)', 'മൂസബ്നു നാഫിഅ്(റ): തർവിയ ദിനത്തിനു നാലു ദിവസങ്ങൾക്കു മുമ്പ് ഉംറക്ക് തമത്തുആയി ഇഹ്റാം ചെയ്ത് ഞാൻ മക്കയിൽ വന്നു. അപ്പോൾ ആളുകൾ പറഞ്ഞു: നിന്റെ ഇപ്പോഴത്തെ ഹജ്ജ് മക്കിയ്യ് ആയി. ഞാനിക്കാര്യത്തിൽ അത്വാഇനോട് വിധി തേടി. അത്വാഅ് പറഞ്ഞു: ജാബിർ(റ) എന്നോട് പറഞ്ഞു: റസൂൽ(സ) ഹദ്യയുമായി പോയ ഹജ്ജിൽ റസൂൽ(സ)യോടൊപ്പം അദ്ദേഹവും ഹജ്ജ് ചെയ്തു. അവർ ഹജ്ജിനു മാത്രമാണ് ഇഹ്റാം ചെയ്തത്. റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ ഹജ്ജിൽ നിന്ന് തഹല്ലുലാവുക. കഅ്ബ, സ്വഫാ, മർവ്വ ഇവക്കിടയിൽ ത്വവാഫ് ചെയ്യുക. മുടി വെട്ടി സ്വതന്ത്രരാവുക. (ഇഹ്റാമിനു മുമ്പ്) അനുവദനീയമായതൊക്കെയും ചെയ്യക. തർവിയ ദിവസമായാൽ ഹജ്ജിന് ഇഹ്റാം ചെയ്യുക. നിങ്ങൾ മുൻപു ചെയ്തത് മുത്അയാക്കുക." അവർ പറഞ്ഞു: ഹജ്ജ് എന്നു ഞങ്ങൾ പേരിട്ടതിനെ എങ്ങനെ മുത്അയാക്കും? റസൂൽ(സ) പറഞ്ഞു: "ഞാൻ കല്പിച്ചത് നിങ്ങൾ ചെയ്യുക. ഞാൻ ഹദ്യ കൊണ്ടു വന്നിട്ടില്ലായിരുന്നെങ്കിൽ ഞാനും നിങ്ങളോട് കൽപിച്ചതുപോലെ ചെയ്യുമായിരുന്നു. ഹദ്യ അതിന്റെ സ്ഥാനത്തെത്തും വരെ എനിക്ക് ഒരു ഹറാമും ഹലാലാവുകയില്ല." അപ്പോൾ അവർ അപ്രകാരം ചെയ്തു. (മു)', 'مُوسَى بْنِ نَافِعٍ', 'മൂസബ്നു നാഫിഅ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 284, 285, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 126, 'عَنْ أَبِي ذَرٍّ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَتِ الْمُتْعَةُ فِي الْحَجِّ لِأَصْحَابِ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَاصَّةً. (م)', 'അബൂദർറ്(റ): ഹജ്ജിലെ മുത്അഃ റസൂൽ(സ)യുടെ അനുചരർക്കു മാത്രം പ്രത്യേകമായുള്ളതായിരുന്നു. (മു)', 'أَبِي ذَرٍّ', 'അബൂദർറ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 285, 285, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 127, 'عَنْ سَالِمِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُمَا: أَنَّ عَبْدَ اللَّهِ بْنَ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: تَمَتَّعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي حَجَّةِ الْوَدَاعِ بِالْعُمْرَةِ إِلَى الْحَجِّ وَأَهْدَى، فَسَاقَ مَعَهُ الْهَدْيَ مِنْ ذِي الْحُلَيْفَةِ، وَبَدَأَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَهَلَّ بِالْعُمْرَةِ، ثُمَّ أَهَلَّ بِالْحَجِّ، وَتَمَتَّعَ النَّاسُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالْعُمْرَةِ إِلَى الْحَجِّ، فَكَانَ مِنَ النَّاسِ مَنْ أَهْدَى فَسَاقَ الْهَدْيَ، وَمِنْهُمْ مَنْ لَمْ يُهْدِ، فَلَمَّا قَدِمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَكَّةَ قَالَ لِلنَّاسِ: "مَنْ كَانَ مِنْكُمْ أَهْدَى فَإِنَّهُ لَا يَحِلُّ مِنْ شَيْءٍ حَرُمَ مِنْهُ حَتَّى يَقْضِيَ حَجَّهُ، وَمَنْ لَمْ يَكُنْ مِنْكُمْ أَهْدَى فَلْيَطُفْ بِالْبَيْتِ وَبِالصَّفَا وَالْمَرْوَةِ، وَلْيُقَصِّرْ وَلْيَحْلِلْ، ثُمَّ لِيُهِلَّ بِالْحَجِّ، وَلْيُهْدِ، فَمَنْ لَمْ يَجِدْ هَدْيًا فَلْيَصُمْ ثَلَاثَةَ أَيَّامٍ فِي الْحَجِّ، وَسَبْعَةً إِذَا رَجَعَ إِلَى أَهْلِهِ". وَطَافَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ قَدِمَ مَكَّةَ فَاسْتَلَمَ الرُّكْنَ أَوَّلَ شَيْءٍ، ثُمَّ خَبَّ ثَلَاثَةَ أَطْوَافٍ مِنَ السَّبْعِ، وَمَشَى أَرْبَعَةَ أَطْوَافٍ، ثُمَّ رَكَعَ حِينَ قَضَى طَوَافَهُ بِالْبَيْتِ عِنْدَ الْمَقَامِ رَكْعَتَيْنِ، ثُمَّ سَلَّمَ فَانْصَرَفَ فَأَتَى الصَّفَا فَطَافَ بِالصَّفَا وَالْمَرْوَةِ سَبْعَةَ أَطْوَافٍ، ثُمَّ لَمْ يَحْلِلْ مِنْ شَيْءٍ حَرُمَ مِنْهُ حَتَّى قَضَى حَجَّهُ، وَنَحَرَ هَدْيَهُ يَوْمَ النَّحْرِ، وَأَفَاضَ فَطَافَ بِالْبَيْتِ، ثُمَّ حَلَّ مِنْ كُلِّ شَيْءٍ حَرُمَ مِنْهُ، وَفَعَلَ مِثْلَ مَا فَعَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَنْ أَهْدَى وَسَاقَ الْهَدْيَ مِنَ النَّاسِ. (ق,د,ن)', 'സാലിമുബ്നു അബ്ദില്ല(റ): ഇബ്നുഉമർ(റ) പറഞ്ഞു: ഹജ്ജതുൽ വിദാഇൽ റസൂൽ(സ) ഉംറ ഹജ്ജിനോടൊപ്പം തമത്തുഅ് ആയി നിർവ്വഹികുകയും ഹദ്യ നൽകുകയും ചെയ്തു. ദുൽഹുലൈഫയിൽ നിന്ന് ഹദ്യ തന്റെ കൂടെ കൊണ്ടുപോയി. ആദ്യം ഉംറക്ക് ഇഹ്റാം ചെയ്തുകൊണ്ട് റസൂൽ(സ) ആരംഭിച്ചു. പിന്നെ ഹജ്ജിനും ഇഹ്റാം ചെയ്തു. റസൂൽ(സ)യോടൊപ്പം ജനങ്ങൾ ഉംറ ഹജ്ജിനോടൊപ്പം നിർവ്വഹിച്ച് തമത്തുഅ് ആക്കി. ഞങ്ങൾക്കിടയിൽ ഹദ്യ കൊണ്ടുവന്നവരും അല്ലാത്തവരുമുണ്ടായിരുന്നു. മക്കയിലെത്തിയപ്പോൾ റസൂൽ(സ) ജനങ്ങളോട് പറഞ്ഞു: "നിങ്ങളിലാരെങ്കിലും ഹദ്യ കൊണ്ടുവന്നിട്ടുണ്ടെങ്കിൽ, തന്റെമേൽ നിഷിദ്ധമായ ഒന്നും ഹജ്ജ് തീരുംവരെ ഹലാലാവുകയില്ല. ഇനി ഹദ്യ കൊണ്ടുവരാത്തവർ കഅ്ബ, സ്വഫാ, മർവ്വ ഇവക്കിടയിൽ ത്വവാഫ് ചെയ്യുക. മുടി വെട്ടി സ്വതന്ത്രരാവുക. പിന്നീട് ഹജ്ജിന് ഇഹ്റാം ചെയ്ത് ഹദ്യ നൽകട്ടെ. ഹദ്യ നൽകാൻ സാധിക്കാത്തവർ, ഹജ്ജ് ദിവസങ്ങളിൽ മൂന്നും, നാട്ടിലേക്ക് മടങ്ങിയ ശേഷം ഏഴും നോമ്പനുഷ്ഠിക്കട്ടെ." മക്കയിലെത്തിയ ഉടൻ റസൂൽ(സ) ത്വവാഫ് ചെയ്തു. ആദ്യം റുക്ൻ സ്പർശിച്ചു. ഏഴിൽ മൂന്ന് ത്വവാഫ് ധൃതിയിൽ നടന്നു. നാലു ത്വവാഫ് നടന്നും നിർവ്വഹിച്ചു. ത്വവാഫ് കഴിഞ്ഞപ്പോൾ മഖാമു ഇബ്റാഹീമിനടുത്ത് വെച്ച് രണ്ട് റക്അത്ത് നിസ്കരിച്ചു. സലാം വീട്ടി. എഴുന്നേറ്റ് സ്വഫാ മർവ്വകളിൽ ചെന്ന് ഏഴ് ത്വവാഫ് ചെയ്തു. ഹജ്ജ് തീരുവോളം തനിക്ക് നിഷിദ്ധമായ ഒന്നിൽ നിന്നും തഹല്ലുലായില്ല. ബലി ദിനം തന്റെ ഹദ്യ അറുത്തു. പിന്നെ ഇഫാളത്തിന്റെ ത്വവാഫ് ചെയ്തു. പിന്നെ തനിക്ക് നിഷിദ്ധമായവയിൽ മുഴുവനായും നിന്നും തഹല്ലുലായി. ഹദ്യ കൊണ്ടു വന്നവർ റസൂൽ(സ) ചെയ്തതപോലെ ചെയ്തു. (ബു,മു,ദ,ന)', 'سَالِمِ بْنِ عَبْدِ اللَّهِ', 'സാലിമുബ്നു അബ്ദില്ല(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 285, 286, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 128, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُ قَالَ: تَمَتَّعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَبُو بَكْرٍ وَعُمَرُ وَعُثْمَانُ رَضِيَ اللهُ عَنْهُمْ، وَأَوَّلُ مَنْ نَهَى عَنْهَا مُعَاوِيَةُ رَضِيَ اللهُ عَنْهُ. (ت,ن)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ)യും അബൂബക്കർ(റ)വും ഉമർ(റ)വും ഉസ്മാൻ(റ)വും തമത്തുഅ് ആയി ഹജ്ജ് നിർവ്വഹിച്ചു. അക്കാര്യം ആദ്യം നിരോധിച്ചത് മുആവിയ(റ) ആണ്. (തു,ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ت','ن']::text[], array['തു','ന']::text[], null, null, 286, 286, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 129, 'عَنْ سَعْدِ بْنِ أَبِي وَقَّاصٍ رَضِيَ اللهُ عَنْهُ وَالضَّحَّاكَ بْنَ قَيْسٍ: وَهُمَا يَذْكُرَانِ التَّمَتُّعَ بِالْعُمْرَةِ إِلَى الْحَجِّ عَامَ حَجَّ مُعَاوِيَةَ بْنِ أَبِي سُفْيَانَ رَضِيَ اللهُ عَنْهُمَا، فَقَالَ الضَّحَّاكُ بْنُ قَيْسٍ: لَا يَصْنَعُ ذَلِكَ إِلَّا مَنْ جَهِلَ أَمْرَ اللَّهِ. فَقَالَ سَعْدٌ: بِئْسَ مَا قُلْتَ، يَا ابْنَ أَخِي. فَقَالَ الضَّحَّاكُ بْنُ قَيْسٍ: فَإِنَّ عُمَرَ بْنَ الْخَطَّابِ قَدْ نَهَى عَنْ ذَلِكَ. فَقَالَ سَعْدٌ: قَدْ صَنَعَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَصَنَعْنَاهَا مَعَهُ. (ت,ن)', 'സഅ്ദുബ്നു അബീവഖാസ്, ളഹ്ഹാഖ് ബിൻ ഖൈസ്(റ): മുആവിയ(റ) ഹജ്ജ് ചെയ്ത വർഷം ഉംറയെ ഹജ്ജിലേക്ക് ചേർത്തി തമത്തുഅ് ആയി നിർവ്വഹിച്ചതിനെക്കുറിച്ച് അവർ രണ്ടുപേരും പറയുന്നു: ളഹ്ഹാഖ് പറഞ്ഞു: അല്ലാഹുവിന്റെ കല്പന അറിയാത്തവനൊഴികെ ഇതു ചെയ്യില്ല. സഅദ് പറഞ്ഞു: സഹോദരാ, നീ പറഞ്ഞതാണ് മോശം. ളഹ്ഹാഖ് പറഞ്ഞു: ഉമർ(റ) ഇത് വിരോധിച്ചിട്ടുണ്ട്. സഅദ് പറഞ്ഞു: റസൂൽ(സ) അത് ചെയ്തിട്ടുണ്ട്. നബിയോടൊപ്പം ഞങ്ങളും അത് ചെയ്തിട്ടുണ്ട്. (തു,ന)', 'سَعْدِ بْنِ أَبِي وَقَّاصٍ', 'സഅ്ദുബ്നു അബീവഖാസ്, ളഹ്ഹാഖ് ബിൻ ഖൈസ്(റ)', null, null, array['ت','ن']::text[], array['തു','ന']::text[], null, null, 286, 286, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 130, 'عَنْ سَالِمِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُ: أَنَّهُ سَمِعَ رَجُلًا مِنْ أَهْلِ الشَّامِ، وَهُوَ يَسْأَلُ عَبْدَ اللَّهِ بْنَ عُمَرَ عَنِ التَّمَتُّعِ بِالْعُمْرَةِ إِلَى الْحَجِّ، فَقَالَ عَبْدُ اللَّهِ بْنُ عُمَرَ: هِيَ حَلَالٌ. فَقَالَ الشَّامِيُّ: إِنَّ أَبَاكَ قَدْ نَهَى عَنْهَا. فَقَالَ عَبْدُ اللَّهِ بْنُ عُمَرَ: أَرَأَيْتَ إِنْ كَانَ أَبِي نَهَى عَنْهَا، وَصَنَعَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَأَمْرَ أَبِي نَتَّبِعُ أَمْ أَمْرَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ فَقَالَ الرَّجُلُ: بَلْ أَمْرَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: لَقَدْ صَنَعَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (ت)', 'സാലിമുബ്നു അബ്ദില്ല(റ): ഉംറ ഹജ്ജിനോടൊപ്പം തമത്തുഅ് ആയി നിർവ്വഹിക്കുന്നതിനെപ്പറ്റി ഒരു ശാമുകാരൻ ഇബ്നുഉമർ(റ)നോട് ചോദിക്കുന്നത് ഞാൻ കേട്ടു. ഇബ്നുഉമർ(റ) പറഞ്ഞു: അത് അനുവദനീയമാണ്. അയാൾ ചോദിച്ചു: നിങ്ങളുടെ പിതാവ് (ഉമർ) അതു നിരോധിച്ചിട്ടുണ്ടല്ലോ? ഇബ്നുഉമർ(റ) പറഞ്ഞു: എന്റെ പിതാവ് നിരോധിച്ചുണ്ടെങ്കിൽ റസൂൽ(സ) അത് ചെയ്തിട്ടുണ്ട്. റസൂൽ(സ)യുടെ കല്പനയാണോ, അതോ എന്റെ പിതാവിന്റെ കല്പനയാണോ നാം പിൻപറ്റേണ്ടത്? അയാൾ പറഞ്ഞു: റസൂൽ(സ)യുടേത്. ഇബ്നുഉമർ(റ) പറഞ്ഞു: റസൂൽ(സ) അത് നിർവ്വഹിച്ചിട്ടുണ്ട്. (തു)', 'سَالِمِ بْنِ عَبْدِ اللَّهِ', 'സാലിമുബ്നു അബ്ദില്ല(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 286, 286, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 131, 'عَنْ سَعِيدِ بْنِ الْمُسَيَّبِ رَضِيَ اللهُ عَنْهُ قَالَ: حَجَّ عَلِيٌّ وَعُثْمَانُ، فَلَمَّا كُنَّا بِبَعْضِ الطَّرِيقِ نَهَى عُثْمَانُ عَنِ التَّمَتُّعِ، فَقَالَ عَلِيٌّ: إِذَا رَأَيْتُمُوهُ قَدِ ارْتَحَلَ فَارْتَحِلُوا. فَلَبَّى عَلِيٌّ وَأَصْحَابُهُ بِالْعُمْرَةِ، فَلَمْ يَنْهَهُمْ عُثْمَانُ، فَقَالَ عَلِيٌّ: أَلَمْ أُخْبَرْ أَنَّكَ تَنْهَى عَنِ التَّمَتُّعِ؟ قَالَ: بَلَى. قَالَ لَهُ عَلِيٌّ: أَلَمْ تَسْمَعْ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تَمَتَّعَ؟ قَالَ: بَلَى. (ن)', 'സഈദുബ്നുൽ മുസയ്യബ്(റ): അലി(റ)വും, ഉസ്മാൻ(റ)വും ഹജ്ജ് ചെയ്തു. വഴിമദ്ധ്യേ ഉസ്മാൻ(റ) തമത്തുഅ് നിരോധിച്ചു. അപ്പോൾ അലി(റ) പറഞ്ഞു: അദ്ദേഹം യാത്രയായെന്നറിഞ്ഞാൽ നിങ്ങളും പുറപ്പെടുക. അലിയും അനുചരരും ഉംറക്ക് ഇഹ്റാം ചെയ്തു. ഉസ്മാൻ(റ) എതിർത്തില്ല. അലി(റ) ചോദിച്ചു: താങ്കൾ തമത്തുഅ് നിരോധിച്ചതായി വിവരം ലഭിച്ചുവല്ലോ? ഉസ്മാൻ(റ) പറഞ്ഞു: അതെ. അലി(റ) പറഞ്ഞു: റസൂൽ(സ) തമത്തുഅ് ചെയ്തതായി നിങ്ങൾ കേട്ടിട്ടില്ലേ? ഉസ്മാൻ(റ) പറഞ്ഞു: അതെ. (ന)', 'سَعِيدِ بْنِ الْمُسَيَّبِ', 'സഈദുബ്നുൽ മുസയ്യബ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 286, 287, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 132, 'عَنْ أَبِي مُوسَى رَضِيَ اللهُ عَنْهُ: أَنَّهُ كَانَ يُفْتِي بِالْمُتْعَةِ، فَقَالَ لَهُ رَجُلٌ: رُوَيْدَكَ بِبَعْضِ فُتْيَاكَ، فَإِنَّكَ لَا تَدْرِي مَا أَحْدَثَ أَمِيرُ الْمُؤْمِنِينَ فِي النُّسُكِ بَعْدُ. حَتَّى لَقِيتُهُ فَسَأَلْتُهُ، فَقَالَ عُمَرُ: قَدْ عَلِمْتُ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَدْ فَعَلَهُ، وَلَكِنْ كَرِهْتُ أَنْ يَظَلُّوا مُعَرِّسِينَ بِهِنَّ فِي الْأَرَاكِ، ثُمَّ يَرُوحُوا بِالْحَجِّ تَقْطُرُ رُءُوسُهُمْ. (م,ن,جه)', 'അബുമൂസ(റ): അദ്ദേഹം തമത്തുആയി ഹജ്ജ് ചെയ്യാമെന്ന് ഫത്വ കൊടുക്കാറുണ്ടായിരുന്നു. അപ്പോൾ ഒരാൾ പറഞ്ഞു: നിങ്ങളുടെ ചില വിധികളിൽ ഒന്നുകൂടി ചിന്തിക്കണം. പിൽക്കാലത്ത് അമീറുൽ മുഅമിനീൻ ഹജ്ജ് കർമ്മങ്ങളിൽ എന്തൊക്കെയാണ് പുതുക്കിയത് എന്ന് നിങ്ങൾക്കറിയില്ല. അങ്ങനെ ഞാൻ അമീറുൽ മുഅ്മിനീനെ കണ്ടുമുട്ടിയപ്പോൾ അതേക്കുറിച്ച് ചോദിച്ചു. ഉമർ(റ) പറഞ്ഞു: റസൂൽ(സ) അത് (തമത്തുഅ്) ചെയ്തയായി ഞാനറിഞ്ഞിട്ടുണ്ട്. എന്നാൽ രാവിലെ അവർ സോഫയിൽ (ഭാര്യമാരുമായി) സുഖിച്ച്, വൈകുന്നേരം തലയിൽ ഈറൻ ഉറ്റിവീഴുന്ന നിലയിൽ ഹജ്ജിന് പോകുന്നത് ഞാൻ വെറുക്കുന്നു. (മു,ന,ജ)', 'أَبِي مُوسَى', 'അബുമൂസ(റ)', null, null, array['م','ن','جه']::text[], array['മു','ന','ജ']::text[], null, null, 287, 287, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 133, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: سَمِعْتُ عُمَرَ يَقُولُ: وَاللَّهِ إِنِّي لَأَنْهَاكُمْ عَنِ الْمُتْعَةِ، وَإِنَّهَا لَفِي كِتَابِ اللَّهِ، وَلَقَدْ فَعَلَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. يَعْنِي الْعُمْرَةَ فِي الْحَجِّ. (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): ഉമർ(റ) പറയുന്നതായി ഞാൻ കേട്ടു: അല്ലാഹു തന്നെ സത്യം. തമത്തുആയി ഹജ്ജ് നിർവ്വഹിക്കുന്നതിൽ നിന്നു ഞാൻ നിങ്ങളെ തടയും. ഉംറ ഹജ്ജിനോടൊപ്പം നിർവ്വഹിക്കുന്നതിനെപ്പറ്റി ഖുർആനിലുണ്ട്, റസൂൽ(സ) അതു ചെയ്തിട്ടുമുണ്ട് എന്നാലും ശരി. (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 287, 287, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 134, 'عَنْ مُعَاوِيَةَ رَضِيَ اللهُ عَنْهُ: قَالَ لِابْنِ عَبَّاسٍ: أَعَلِمْتَ أَنِّي قَصَّرْتُ مِنْ رَأْسِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عِنْدَ الْمَرْوَةِ؟ قَالَ: لَا. يَقُولُ ابْنُ عَبَّاسٍ: هَذَا مُعَاوِيَةُ يَنْهَى النَّاسَ عَنِ الْمُتْعَةِ. وَقَدْ تَمَتَّعَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (ن)', 'മുആവിയ(റ): ഞാൻ ഇബ്നുഅബ്ബാസ്(റ)നോട് ചോദിച്ചു: മർവ്വക്കടുത്തുവെച്ച് ഞാൻ റസൂൽ(സ)യുടെ മുടി വെട്ടിയതായി താങ്കൾക്കറിയുമോ? ഇബ്നുഅബ്ബാസ്(റ) പറഞ്ഞു: ഇല്ല. ഇബ്നുഅബ്ബാസ്(റ) തുടരുന്നു: മുആവിയ തമത്തുഅ് ആയി ഹജ്ജ് ചെയ്യുന്നതിൽ നിന്ന് ജനങ്ങളെ വിലക്കുന്നു. റസൂൽ(സ) തമത്തുആയി ഹജ്ജ് ചെയ്തിട്ടുണ്ട്. (ന)', 'مُعَاوِيَةَ', 'മുആവിയ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 287, 287, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 135, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ : قَدِمَ عَلِيٌّ مِنْ سِعَايَتِهِ، فَقَالَ لَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "بِمَا أَهْلَلْتَ يَا عَلِيُّ؟". قَالَ: بِمَا أَهَلَّ بِهِ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. قَالَ: "فَاهْدِ وَامْكُثْ حَرَامًا كَمَا أَنْتَ". قَالَ: وَأَهْدَى عَلِيٌّ لَهُ هَدْيًا. (ن)', 'ജാബിർ(റ): അലി(റ) തന്റെ നികുതി പിരിവ് ജോലി കഴിഞ്ഞ് വന്നു. റസൂൽ(സ) അലി(റ)വിനോട് ചോദിച്ചു: "നിങ്ങൾ എന്തിനാണ് ഇഹ്റാം ചെയ്തത്?" അലി(റ) പറഞ്ഞു: റസൂൽ(സ) ഇഹ്റാം ചെയ്തതിന്. റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ ഹദ്യ അറുക്കണം. നിങ്ങൾ മുഹ്രിമായി തുടരുകയും വേണം." നിവേദകൻ പറയുന്നു: അലി(റ) ഹദ്യ കൊണ്ടുവന്നിരുന്നു. (ന)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 287, 287, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 136, 'عَنْ طَارِقِ بْنِ شِهَابٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ أَبُو مُوسَى: أَقْبَلْتُ مِنَ الْيَمَنِ وَالنَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُنِيخٌ بِالْبَطْحَاءِ حَيْثُ حَجَّ، فَقَالَ: "أَحَجَجْتَ؟". قُلْتُ: نَعَمْ. قَالَ: "كَيْفَ قُلْتَ؟". قَالَ: قُلْتُ: لَبَّيْكَ بِإِهْلَالٍ كَإِهْلَالِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. قَالَ: "فَطُفْ بِالْبَيْتِ وَبِالصَّفَا وَالْمَرْوَةِ وَأَحِلَّ". فَفَعَلْتُ، ثُمَّ أَتَيْتُ امْرَأَةً فَفَلَتْ رَأْسِي، فَجَعَلْتُ أُفْتِي النَّاسَ بِذَلِكَ حَتَّى كَانَ فِي خِلَافَةِ عُمَرَ، فَقَالَ لَهُ رَجُلٌ: يَا أَبَا مُوسَى، رُوَيْدَكَ بَعْضَ فُتْيَاكَ، فَإِنَّكَ لَا تَدْرِي مَا أَحْدَثَ أَمِيرُ الْمُؤْمِنِينَ فِي النُّسُكِ بَعْدَكَ. قَالَ أَبُو مُوسَى: يَا أَيُّهَا النَّاسُ، مَنْ كُنَّا أَفْتَيْنَاهُ فَلْيَتَّئِدْ فَإِنَّ أَمِيرَ الْمُؤْمِنِينَ قَادِمٌ عَلَيْكُمْ، فَأْتَمُّوا بِهِ، وَقَالَ عُمَرُ: إِنْ نَأْخُذْ بِكِتَابِ اللَّهِ فَإِنَّهُ يَأْمُرُنَا بِالتَّمَامِ، وَإِنْ نَأْخُذْ بِسُنَّةِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَإِنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَمْ يَحِلَّ حَتَّى بَلَغَ الْهَدْيُ مَحِلَّهُ. (ن)', 'ത്വാരിഖുബ്നു ശിഹാബ്(റ): അബൂമൂസാ(റ) പറഞ്ഞു: ഞാൻ യമനിൽ നിന്നും വന്നപ്പോൾ റസൂൽ(സ) ഹജ്ജിന് വന്ന് ബത്ഹാഇൽ ഒട്ടകത്തെ മുട്ടുകുത്തിച്ചു നിൽക്കുകയായിരുന്നു. റസൂൽ(സ) ചോദിച്ചു: "നീ ഹജ്ജിന് ഇഹ്റാം ചെയ്തുവോ?" ഞാൻ പറഞ്ഞു: അതെ. റസൂൽ(സ) ചോദിച്ചു: "എങ്ങനെയാണ് പറഞ്ഞത്?" ഞാൻ പറഞ്ഞു: റസൂൽ(സ) ഇഹ്റാം ചെയ്തത്പോലെ ഞാനും ഇഹ്റാം ചെയ്തു. റസൂൽ(സ) പറഞ്ഞു: "എങ്കിൽ നീ സ്വഫാ മർവ്വകളും കഅ്ബയും ത്വവാഫ് ചെയ്തശേഷം തഹല്ലുലാവുക." ഞാനപ്രകാരം ചെയ്തു. ഞാൻ ഭാര്യയുടെ അടുത്തെത്തി. അവളെന്റെ മുടി ചീകി. ഉമർ(റ)ന്റെ ഭരണം വരെ ഞാനിക്കാര്യം ജനങ്ങൾക്ക് ഫത്വ നൽകി. അക്കാലത്ത് ഒരാൾ പറഞ്ഞു: അബൂമൂസാ, നിങ്ങളുടെ ചില വിധികൾ ഒന്നുകൂടി ചിന്തിക്കണം. കാരണം, പിൽക്കാലത്ത് അമീറുൽ മുഅമിനീൻ ഹജ്ജ് കർമ്മങ്ങളിൽ എന്തൊക്കെയാണ് നടപ്പിലാക്കിയത് എന്ന് നിങ്ങൾക്കറിയില്ല. അബൂമൂസ(റ) പറഞ്ഞു: ജനങ്ങളേ, ഞാൻ ഫത്വ നൽകിയിരുന്നവർ അതുപേക്ഷിക്കുക. കാരണം, അമീറുൽ മുഅ്മിനീൻ നിങ്ങളിലേക്കു വരുന്നുണ്ട്. അദ്ദേഹത്തെ പിന്തുടരുക. ഉമർ(റ) പറഞ്ഞു: നാം അല്ലാഹുവിന്റെ ഗ്രന്ഥമാണു പൻതുടരുന്നതെങ്കിൽ അത് നമ്മോട് പൂർത്തീകരണത്തിനാണ് കല്പിക്കുന്നത്. റസൂൽ(സ) ചര്യയാണ് നാം പൻതുടരുന്നതെങ്കിൽ റസൂൽ(സ) ഹദ്യ അതിന്റെ സ്ഥാനത്തെത്തുന്നതുവരെ തഹല്ലുലായിട്ടില്ല. (ന)', 'طَارِقِ بْنِ شِهَابٍ', 'ത്വാരിഖുബ്നു ശിഹാബ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 287, 288, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 137, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: حَدَّثَنِي عُمَرُ بْنُ الْخَطَّابِ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ وَهُوَ بِالْعَقِيقِ: "أَتَانِي آتٍ مِنْ رَبِّي فَقَالَ: صَلِّ فِي هَذَا الْوَادِي الْمُبَارَكِ، وَقُلْ: عُمْرَةٌ فِي حَجَّةٍ". (خ,د,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): ഉമറുബ്നു ഖത്താബ്(റ) എന്നോട് പറഞ്ഞു: റസൂൽ(സ) അഖീഖിലായിരിക്കെ അവിടന്ന് പറയുന്നത് ഞാൻ കേട്ടു: "നാഥനിൽ നിന്ന് ഒരു ദൂതൻ വന്ന് എന്നോട് പറഞ്ഞു: ഈ പരിശുദ്ധ താഴ്വരയിൽ നിന്നും താങ്കൾ നിസ്കരിക്കുക. പറയുക; ഹജ്ജിൽ തന്നെയാണ് ഉംറ." (ബു,ദ,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ','د','جه']::text[], array['ബു','ദ','ജ']::text[], null, null, 288, 288, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 138, 'عَنْ مُطَرِّفِ بْنِ عَبْدِ اللَّهِ بْنِ الشِّخِّيرِ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ لِي عِمْرَانُ بْنُ الْحُصَيْنِ: إِنِّي أُحَدِّثُكَ حَدِيثًا لَعَلَّ اللَّهَ أَنْ يَنْفَعَكَ بِهِ بَعْدَ الْيَوْمِ، اعْلَمْ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَدِ اعْتَمَرَ طَائِفَةً مِنْ أَهْلِهِ فِي الْعَشْرِ مِنْ ذِي الْحِجَّةِ، فَلَمْ يَنْهَ عَنْهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَلَمْ يَنْزِلْ نَسْخُهُ، قَالَ فِي ذَلِكَ- بَعْدُ- رَجُلٌ بِرَأْيِهِ مَا شَاءَ أَنْ يَقُولَ. (م,جه)', 'മുതർരിഫുബ്നു അബ്ദില്ലാഹിബ്നിശ്ശിഖീർ(റ): ഇംറാനുബ്നുഹുസൈൻ(റ) എന്നോട് പറഞ്ഞു: ഈ ദിവസത്തിനു ശേഷം ചിലപ്പോൾ അല്ലാഹു നിങ്ങൾക്ക് പ്രയോജനപ്പെടുത്തുന്ന ഒരു കാര്യം ഞാൻ നിങ്ങളെ അറിയിക്കാം; റസൂൽ(സ) തന്റെ ഒരുപറ്റം ബന്ധുക്കളുമായി ദുൽഹിജ്ജ പത്തിന് ഉംറ ചെയ്തു. അത് റസൂൽ(സ) നിരോധിക്കുകയോ അതിനെ തടയുന്ന ഒരു സൂക്തം ഇറങ്ങുകയോ ചെയ്തിട്ടില്ല. അദ്ദേഹം പറഞ്ഞു: പിന്നീട് ഏതോ ഒരാൾ എന്തോ തന്നിഷ്ടം പറഞ്ഞതാണ്. (മു,ജ)', 'مُطَرِّفِ بْنِ عَبْدِ اللَّهِ بْنِ الشِّخِّيرِ', 'മുതർരിഫുബ്നു അബ്ദില്ലാഹിബ്നിശ്ശിഖീർ(റ)', null, null, array['م','جه']::text[], array['മു','ജ']::text[], null, null, 288, 288, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 139, 'عَنْ مُعَاوِيَةَ بْنِ أَبِي سُفْيَانَ رَضِيَ اللهُ عَنْهُ أَنَّهُ قَالَ لِأَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: هَلْ تَعْلَمُونَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ كَذَا وَكَذَا ،وَعَنْ رُكُوبِ جُلُودِ النُّمُورِ؟ قَالُوا: نَعَمْ. قَالَ: فَتَعْلَمُونَ أَنَّهُ نَهَى أَنْ يُقْرَنَ بَيْنَ الْحَجِّ وَالْعُمْرَةِ؟ فَقَالُوا: أَمَّا هَذَا فَلَا، فَقَالَ: أَمَا إِنَّهَا مَعَهُنَّ، وَلَكِنَّكُمْ نَسِيتُمْ. (د,ن)', 'മുആവിയതുബ്നു അബീസുഫ്യാൻ(റ): അദ്ദേഹം റസൂൽ(സ)യുടെ അനുചരന്മാരോട് ചോദിച്ചു: ഇന്നയിന്ന കാര്യങ്ങളും പുലിത്തോൽ വിരിച്ച വാഹനത്തിൽ കയറലും റസൂൽ(സ) നിരോധിച്ചതായി നിങ്ങളറിയുമോ? അവർ പറഞ്ഞു: അതെ. അദ്ദേഹം പറഞ്ഞു: ഹജ്ജും ഉംറയും ഒരുമിച്ച് നിർവ്വഹിക്കുന്നത് റസൂൽ(സ) നിരോധിച്ചതായി നിങ്ങളറിയുമോ? അവർ പറഞ്ഞു: ഇക്കാര്യം (ഞങ്ങൾക്ക്) അറിയില്ല. അദ്ദേഹം പറഞ്ഞു: അതും അവയോടൊപ്പമുള്ളതാണ്, പക്ഷേ, നിങ്ങൾ മറന്ന് പോയി. (ദ,ന)', 'مُعَاوِيَةَ بْنِ أَبِي سُفْيَانَ', 'മുആവിയതുബ്നു അബീസുഫ്യാൻ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 289, 289, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 140, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانُوا يَرَوْنَ أَنَّ الْعُمْرَةَ فِي أَشْهُرِ الْحَجِّ مِنْ أَفْجَرِ الْفُجُورِ فِي الْأَرْضِ، وَيَجْعَلُونَ الْمُحَرَّمَ صَفَرًا، وَيَقُولُونَ إِذَا بَرَا الدَّبَرْ وَعَفَا الْأَثَرْ وَانْسَلَخَ صَفَرْ، حَلَّتِ الْعُمْرَةُ لِمَنِ اعْتَمَرْ، قَدِمَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَصْحَابُهُ صَبِيحَةَ رَابِعَةٍ مُهِلِّينَ بِالْحَجِّ، فَأَمَرَهُمْ أَنْ يَجْعَلُوهَا عُمْرَةً، فَتَعَاظَمَ ذَلِكَ عِنْدَهُمْ، فَقَالُوا: يَا رَسُولَ اللَّهِ، أَيُّ الْحِلِّ؟ قَالَ: "حِلٌّ كُلُّهُ". (خ)', 'ഇബ്നുഅബ്ബാസ്(റ): ഹജ്ജ് മാസങ്ങളിൽ ഉംറ നിർവ്വഹിക്കുന്നത് ഭൂമുഖത്തെ ഏറ്റവും വലിയ തെമ്മാടിത്തമായി ബഹുദൈവ വിശ്വാസികൾ കണക്കാക്കിയിരുന്നു. അവർ മുഹർറമിനെ സഫറാക്കുമായിരുന്നു. (മുഹർറം മാസത്തെ ആദരണീയ മാസങ്ങളിൽ നിന്നൊഴിവാക്കി പകരം സഫറിനെ ആദരണീയ മാസത്തിൽ ഉൾപ്പെടുത്തുമായിരുന്നു.) അവർ പറയുമായിരുന്നു: യാത്രയുടെ ചിഹ്നങ്ങളെല്ലാം മാഞ്ഞു കഴിഞ്ഞു, ഒട്ടകത്തിന്റെ മുകളിലെ മുറിവുണങ്ങി, സ്വഫർ മാസം അവസാനിച്ചു. എങ്കിൽ ഉംറ ചെയ്യാനുദ്ദേശിക്കുന്നവർക്ക് ഉംറ ചെയ്യാം. റസൂൽ(സ)യും അനുചരന്മാരും ദുൽഹിജ്ജ നാലിനു രാവിലെ ഹജ്ജിന് ഇഹ്റാം ചെയ്തു. റസൂൽ(സ) അവരോട് അത് ഉംറയാക്കാൻ കൽപിച്ചു. അവർക്കത് വലിയ മനപ്രയാസമായി അനുഭവപ്പെട്ടു. അവർ ചോദിച്ചു: റസൂലെ, ഏതു തരം തഹല്ലുലാണ്? നബി(സ) പറഞ്ഞു: "പൂർണ്ണമായ തഹല്ലുൽ." (ബു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 289, 289, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 141, 'عَنْ حَفْصَةَ زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهَا قَالَتْ: يَا رَسُولَ اللَّهِ، مَا شَأْنُ النَّاسِ حَلُّوا بِعُمْرَةٍ وَلَمْ تَحْلِلْ أَنْتَ مِنْ عُمْرَتِكَ؟ قَالَ: "إِنِّي لَبَّدْتُ رَأْسِي، وَقَلَّدْتُ هَدْيِي، فَلَا أَحِلُّ حَتَّى أَنْحَرَ". (ق,د,ن,جه)', 'പ്രവാചകപത്നി ഹഫ്സ(റ): അവർ ചോദിച്ചു: അല്ലാഹിവിന്റെ ദൂതരേ, ജനങ്ങളെല്ലാം ഉംറയിൽ നിന്ന് തഹല്ലുലായി, അങ്ങെന്താണ് തഹല്ലുലാവാത്തത്? നബി(സ) പറഞ്ഞു: "ഞാനെന്റെ തല ഒട്ടിപ്പിടിപ്പിച്ചിരിക്കുന്നു. ഹദ്യ മൃഗത്തെ ഞാൻ കയറിൽ കെട്ടിയിരിക്കുന്നു. അതിനാൽ അറുക്കുന്നതു വരെ ഞാൻ തഹല്ലുലാവില്ല." (ബു,മു,ദ,ന,ജ)', 'حَفْصَةَ زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهَا قَالَتْ', 'പ്രവാചകപത്നി ഹഫ്സ(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 289, 289, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 142, 'عَنْ بَكْرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُ، عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُلَبِّي بِالْحَجِّ وَالْعُمْرَةِ جَمِيعًا، قَالَ بَكْرٌ: فَحَدَّثْتُ بِذَلِكَ ابْنَ عُمَرَ، فَقَالَ: لَبَّى بِالْحَجِّ وَحْدَهُ. فَلَقِيتُ أَنَسًا فَحَدَّثْتُهُ بِقَوْلِ ابْنِ عُمَرَ، فَقَالَ أَنَسٌ: مَا تَعُدُّونَنَا إِلَّا صِبْيَانًا، سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَبَّيْكَ عُمْرَةً وَحَجًّا". (م,ن)', 'ബക്റുബ്നു അബ്ദില്ല, അനസ്(റ)വിൽ നിന്ന് നിവേദനം ചെയ്യുന്നു: റസൂൽ(സ) ഹജ്ജിനും ഉംറക്കും ഒരുമിച്ച് ഇഹ്റാം ചെയ്യുന്നത് ഞാൻ കേട്ടു. ബക്ർ പറഞ്ഞു: ഞാനിക്കാര്യം ഇബ്നുഉമർ(റ)വിനോട് പറഞ്ഞു. അദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ) ഹജ്ജിന് മാത്രമാണ് ഇഹ്റാം ചെയ്തത്. ഞാൻ അനസ്(റ)വിനെ കണ്ടപ്പോൾ ഇബ്നുഉമർ(റ) പറഞ്ഞ കാര്യം അറിയിച്ചു. അപ്പോൾ അനസ്(റ) പറഞ്ഞു: നിങ്ങൾ നമ്മളെ കുട്ടികളായാണ് കാണുന്നത്. റസൂൽ(സ) പറയുന്നതായി ഞാൻ കേട്ടു: "ഞാൻ ഹജ്ജിനും ഉംറക്കുമായി ഇഹ്റാം ചെയ്യുന്നു." (മു,ന)', 'بَكْرِ بْنِ عَبْدِ اللَّهِ', 'ബക്റുബ്നു അബ്ദില്ല, അനസ്(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], null, null, 289, 290, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 143, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ أَصْحَابَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الَّذِينَ كَانُوا مَعَهُ لَمْ يَطُوفُوا حَتَّى رَمَوُا الْجَمْرَةَ. (د)', 'ആഇശ(റ): റസൂൽ(സ)യുടെ കൂടെയുണ്ടായിരുന്ന അവിടത്തെ അനുചരർ ജംറകളെ എറിയാതെ പ്രദക്ഷിണം നടത്തിയിട്ടില്ല. (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 290, 290, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 144, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لَهَا: "طَوَافُكِ بِالْبَيْتِ وَبَيْنَ الصَّفَا وَالْمَرْوَةِ يَكْفِيكِ لِحَجَّتِكِ وَعُمْرَتِكِ". (م,د)', 'ആഇശ(റ): റസൂൽ(സ) അവരോട് പറഞ്ഞു: "കഅബാലയപ്രദക്ഷിണവും സ്വഫാ മർവക്കിടയിലെ പ്രയാണവും നിങ്ങളുടെ ഹജ്ജിനും ഉംറക്കും മതിയാവുന്നതാണ്." (മു,ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 290, 290, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 145, 'عَنْ نَافِعٍ: أَنَّ عَبْدَ اللَّهِ بْنَ عُمَرَ رَضِيَ اللهُ عَنْهُمَا خَرَجَ فِي الْفِتْنَةِ مُعْتَمِرًا، وَقَالَ: إِنْ صُدِدْتُ عَنِ الْبَيْتِ صَنَعْنَا كَمَا صَنَعْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. فَخَرَجَ فَأَهَلَّ بِعُمْرَةٍ، وَسَارَ حَتَّى إِذَا ظَهَرَ عَلَى الْبَيْدَاءِ الْتَفَتَ إِلَى أَصْحَابِهِ فَقَالَ: مَا أَمْرُهُمَا إِلَّا وَاحِدٌ، أُشْهِدُكُمْ أَنِّي قَدْ أَوْجَبْتُ الْحَجَّ مَعَ الْعُمْرَةِ. فَخَرَجَ حَتَّى إِذَا جَاءَ الْبَيْتَ طَافَ بِهِ سَبْعًا وَبَيْنَ الصَّفَا وَالْمَرْوَةِ سَبْعًا، لَمْ يَزِدْ عَلَيْهِ، وَرَأَى أَنَّهُ مُجْزِئٌ عَنْهُ، وَأَهْدَى. (م)', 'നാഫിഅ്(റ): പ്രശ്ന ബാധിത സമയത്ത് ഇബ്നുഉമർ(റ) ഉംറക്ക് ഇഹ്റാം ചെയ്തു പുറപ്പെട്ടു. അദ്ദേഹം പറഞ്ഞു: കഅ്ബയിൽ നിന്ന് ഞാൻ തടയപ്പെട്ടാൽ റസൂൽ(സ)യോടൊപ്പം ഞങ്ങൾ ചെയ്തിരുന്നത് ഞാൻ ചെയ്യും. ഉംറക്ക് ഇഹ്റാം ചെയ്തവരായി അദ്ദേഹം പുറപ്പെട്ടു, അങ്ങനെ സഞ്ചരിച്ച് ബൈദാഇൽ വെച്ച് തന്റെ കൂടെയുള്ളവർക്കുനേരെ തിരിഞ്ഞുകൊണ്ട് ഇബ്നുഉമർ(റ) പറഞ്ഞു: രണ്ടിന്റെയും കാര്യം ഒന്നുതന്നെ, ഞാൻ ഉംറയോടൊപ്പം ഹജ്ജും ചെയ്തുവെന്നതിന് നിങ്ങൾ സാക്ഷി. അങ്ങനെ അദ്ദേഹം പുറപ്പെട്ട് കഅ്ബയിലെത്തിയപ്പോൾ അതിനെ ഏഴു തവണയും സ്വഫാ മർവ്വക്കിടയിൽ ഏഴു തവണയും ത്വവാഫ് ചെയ്തു. ഇതു തന്നെ മതിയെന്ന് സ്വയം മനസ്സിലാക്കിയതിനാൽ ഒന്നും വർദ്ധിപ്പിച്ചില്ല, ഹദ്യ അറുത്തു. (മു)', 'نَافِعٍ', 'നാഫിഅ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 290, 290, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 146, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ : أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَاتَ بِهَا- يَعْنِي بِذِي الْحُلَيْفَةِ- حَتَّى أَصْبَحَ، ثُمَّ رَكِبَ، حَتَّى إِذَا اسْتَوَتْ بِهِ عَلَى الْبَيْدَاءِ حَمِدَ اللَّهَ وَسَبَّحَ وَكَبَّرَ، ثُمَّ أَهَلَّ بِحَجٍّ وَعُمْرَةٍ، وَأَهَلَّ النَّاسُ بِهِمَا، فَلَمَّا قَدِمْنَا أَمَرَ النَّاسَ فَحَلُّوا، حَتَّى إِذَا كَانَ يَوْمُ التَّرْوِيَةِ أَهَلُّوا بِالْحَجِّ، وَنَحَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَبْعَ بَدَنَاتٍ بِيَدِهِ قِيَامًا. (خ,د)', 'അനസ്(റ): റസൂൽ(സ) ദുൽഹുലൈഫയിൽ രാപാർത്തു. നേരം പുലർന്നപ്പോൾ വാഹനം കയറി ബൈദാഇലെത്തിയപ്പോൾ ഹംദും, തസ്ബീഹും, തക്ബീറും ചൊല്ലി. പിന്നെ ഹജ്ജിനും ഉംറക്കും ഇഹ്റാം ചെയ്തു. ജനങ്ങളും അപ്രകാരം ചെയ്തു. ഞങ്ങൾ വന്നപ്പോൾ റസൂൽ(സ)യുടെ കൽപനയനുസരിച്ച് ജനങ്ങൾ തഹല്ലുലായി. തർബിയ ദിനമായപ്പോൾ അവർ ഹജ്ജിന് ഇഹ്റാം ചെയ്തു. റസൂൽ(സ) നിന്നുകൊണ്ട് തൃക്കരങ്ങളുപയോഗിച്ച് ഏഴ് ഒട്ടകങ്ങളെ അറുത്തു. (ബു,ദ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['خ','د']::text[], array['ബു','ദ']::text[], null, null, 290, 290, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 147, 'عَنِ الْبَرَاءِ بْنِ عَازِبٍ رَضِيَ اللهُ عَنْهُ قَالَ: كُنْتُ مَعَ عَلِيٍّ حِينَ أَمَّرَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى الْيَمَنِ، قَالَ: فَأَصَبْتُ مَعَهُ أَوَاقِيَ، فَلَمَّا قَدِمَ عَلِيٌّ مِنَ الْيَمَنِ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: وَجَدْتُ فَاطِمَةَ رَضِيَ اللهُ عَنْهَا قَدْ لَبِسَتْ ثِيَابًا صَبِيغًا، وَقَدْ نَضَحَتِ الْبَيْتَ بِنَضُوحٍ، فَقَالَتْ: مَا لَكَ؟ فَإِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَدْ أَمَرَ أَصْحَابَهُ فَأَحَلُّوا؟ قَالَ: قُلْتُ لَهَا: إِنِّي أَهْلَلْتُ بِإِهْلَالِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. قَالَ: فَأَتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ لِي: "كَيْفَ صَنَعْتَ؟". فَقَالَ: قُلْتُ: أَهْلَلْتُ بِإِهْلَالِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. قَالَ: فَإِنِّي قَدْ سُقْتُ الْهَدْيَ وَقَرَنْتُ. قَالَ لِي: "انْحَرْ مِنَ الْبُدْنِ سَبْعًا وَسِتِّينَ، أَوْ سِتًّا وَسِتِّينَ، وَأَمْسِكْ لِنَفْسِكَ ثَلَاثًا وَثَلَاثِينَ، أَوْ أَرْبَعًا وَثَلَاثِينَ، وَأَمْسِكْ لِي مِنْ كُلِّ بَدَنَةٍ مِنْهَا بَضْعَةً". (د,ن)', 'ബറാഉബ്നു ആസിബ്(റ): റസൂൽ(സ) അലി(റ)നെ യമനിലെ അമീറാക്കുമ്പോൾ ഞാൻ അദ്ദേഹത്തോടൊപ്പമുണ്ടായിരുന്നു. ബറാഅ്(റ) തുടരുന്നു: അദ്ദേഹത്തെ സംരക്ഷിച്ചു കൊണ്ട് ഞാനും ഇറങ്ങി. അലി(റ) യമനിൽ നിന്ന് റസൂൽ(സ)യുടെ അടുത്തു വന്നപ്പോൾ പറഞ്ഞു: ചായം പൂശിയ വസ്ത്രം ധരിച്ച് വെള്ളം തളിച്ച് വീട് വൃത്തിയാക്കുന്ന ഫാത്വിമ(റ)യെ ഞാൻ കണ്ടു. അവർ പറഞ്ഞു: നിങ്ങൾക്കെന്തു പറ്റി? റസൂൽ(സ) അനുചരന്മാരോട് തഹല്ലുലാവാൻ കൽപിക്കുകയും അവർ അപ്രകാരം ചെയ്യുകയും ചെയ്തുവല്ലോ? അലി(റ) പറഞ്ഞു: ഞാനവളോട് പറഞ്ഞു: റസൂൽ(സ) ചെയ്ത അതേ ഇഹ്റാമാണ് ഞാനും ചെയ്തിട്ടുള്ളത്. അലി(റ) പറയുന്നു: റസൂൽ(സ)യുടെ അടുത്തു ചെന്നപ്പോൾ റസൂൽ(സ) ചോദിച്ചു: "എങ്ങനെയാണ് നീ (ഇഹ്റാം) ചെയ്തത്? " ഞാൻ പറഞ്ഞു: ഞാൻ റസൂൽ(സ)യുടെ ഇഹ്റാമാണ് ചെയ്തത്. ഞാൻ ഹദ്‌യ കൊണ്ടു വന്നിട്ടുണ്ട്, ഖിറാൻ ചെയ്തിട്ടുമുണ്ട്. റസൂൽ(സ) പറഞ്ഞു: "നീ അറുപത്തി ഏഴോ അറുപത്താറോ ഒട്ടകങ്ങളെ അറക്കുക. നിനക്കു വേണ്ടി മുപ്പത്തിമൂന്ന് അല്ലെങ്കിൽ മുപ്പത്തിനാല് എണ്ണം ബാക്കിയാക്കുക. എല്ലാ ഒട്ടകങ്ങളിൽ നിന്നും ഒരു കഷ്ണം എനിക്കായി മാറ്റിവെക്കുക." (ദ,ന)', 'الْبَرَاءِ بْنِ عَازِبٍ', 'ബറാഉബ്നു ആസിബ്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 290, 291, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 148, 'عَنِ الصُّبَيِّ بْنِ مَعْبَدٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَهْلَلْتُ بِهِمَا مَعًا، فَقَالَ عُمَرُ: هُدِيتَ لِسُنَّةِ نَبِيِّكَ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (د,ن,جه)', 'സ്വുബയ്യുബ്നു മഅ്ബദ്(റ): ഞാൻ രണ്ടിനു(ഹജ്ജിനും ഉംറക്കും)മായി ഒന്നിച്ച് ഇഹ്റാം ചെയ്തു. ഉമർ(റ) പറഞ്ഞു: നിങ്ങളുടെ പ്രവാചകന്റെ ചര്യയിലേക്ക് നിങ്ങൾ നേർവഴിനടത്തപ്പെട്ടിരിക്കുന്നു. (ദ,ന,ജ)', 'الصُّبَيِّ بْنِ مَعْبَدٍ', 'സ്വുബയ്യുബ്നു മഅ്ബദ്(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 291, 291, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 149, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: أَهَلَّ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِعُمْرَةٍ، وَأَهَلَّ أَصْحَابُهُ بِحَجٍّ. (م,د,ن)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) ഉംറക്കും അനുചരന്മാർ ഹജ്ജിനും ഇഹ്റാം ചെയ്തു. (മു,ദ,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['م','د','ن']::text[], array['മു','ദ','ജ']::text[], null, null, 291, 291, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 150, 'عَنْ شَقِيقِ بْنِ سَلَمَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَجُلًا مِنْ بَنِي تَغْلِبَ يُقَالُ لَهُ الصُّبَيُّ بْنُ مَعْبَدٍ، وَكَانَ نَصْرَانِيًّا فَأَسْلَمَ، فَأَقْبَلَ فِي أَوَّلِ مَا حَجَّ فَلَبَّى بِحَجٍّ وَعُمْرَةٍ جَمِيعًا، فَهُوَ كَذَلِكَ يُلَبِّي بِهِمَا جَمِيعًا فَمَرَّ عَلَى سَلْمَانَ بْنِ رَبِيعَةَ وَزَيْدِ بْنِ صُوحَانَ، فَقَالَ أَحَدُهُمَا: لَأَنْتَ أَضَلُّ مِنْ جَمَلِكَ هَذَا. فَقَالَ الصُّبَيُّ: فَلَمْ يَزَلْ فِي نَفْسِي حَتَّى لَقِيتُ عُمَرَ بْنَ الْخَطَّابِ فَذَكَرْتُ ذَلِكَ لَهُ، فَقَالَ: هُدِيتَ لِسُنَّةِ نَبِيِّكَ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (ن)
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=4 and h.hadith_no=150), 1, 'وَفِي رِوَايَةٍ: كُنْتُ رَجُلًا أَعْرَابِيًّا نَصْرَانِيًّا فَأَسْلَمْتُ، فَأَتَيْتُ رَجُلًا مِنْ عَشِيرَتِي يُقَالُ لَهُ هُذَيْمُ بْنُ ثُرْمُلَةَ، فَقُلْتُ لَهُ: يَا هَنَاهْ، إِنِّي حَرِيصٌ عَلَى الْجِهَادِ، وَإِنِّي وَجَدْتُ الْحَجَّ وَالْعُمْرَةَ مَكْتُوبَيْنِ عَلَيَّ، فَكَيْفَ لِي بِأَنْ أَجْمَعَهُمَا؟ قَالَ: اجْمَعْهُمَا وَاذْبَحْ مَا اسْتَيْسَرَ مِنَ الْهَدْيِ فَأَهْلَلْتُ بِهِمَا مَعًا، فَلَمَّا أَتَيْتُ الْعُذَيْبَ لَقِيَنِي سَلْمَانُ بْنُ رَبِيعَةَ وَزَيْدُ بْنُ صُوحَانَ وَأَنَا أُهِلُّ بِهِمَا جَمِيعًا، فَقَالَ أَحَدُهُمَا لِلْآخَرِ: مَا هَذَا بِأَفْقَهَ مِنْ بَعِيرِهِ، قَالَ: فَكَأَنَّمَا أُلْقِيَ عَلَيَّ جَبَلٌ حَتَّى أَتَيْتُ عُمَرَ بْنَ الْخَطَّابِ، فَقُلْتُ لَهُ: يَا أَمِيرَ الْمُؤْمِنِينَ، إِنِّي كُنْتُ رَجُلًا أَعْرَابِيًّا نَصْرَانِيًّا، وَإِنِّي أَسْلَمْتُ، وَأَنَا حَرِيصٌ عَلَى الْجِهَادِ، وَإِنِّي وَجَدْتُ الْحَجَّ وَالْعُمْرَةَ مَكْتُوبَيْنِ عَلَيَّ، فَأَتَيْتُ رَجُلًا مِنْ قَوْمِي فَقَالَ لِي: اجْمَعْهُمَا وَاذْبَحْ مَا اسْتَيْسَرَ مِنَ الْهَدْيِ، وَإِنِّي أَهْلَلْتُ بِهِمَا مَعًا، فَقَالَ لِي عُمَرُ رَضِيَ اللهُ عَنْهُ: هُدِيتَ لِسُنَّةِ نَبِيِّكَ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (د,ن)', 'മറ്റൊരു നിവേദനത്തിൽ: സ്വുബയ്യ്(റ) പറഞ്ഞു: ഞാനൊരു ക്രിസ്തീയ അഅ്റാബിയായിരുന്നു. ഞാൻ മുസ്‌ലിമായി. എന്റെ കുടുംബത്തിൽപെട്ട ഹുദൈമുബ്നു സുർമുലയോട് ഞാൻ പറഞ്ഞു: എന്റെ സന്തോഷമേ! എനിക്ക് ജിഹാദിന് ആർത്തിയുണ്ട്. എനിക്ക് ഹജ്ജും ഉംറയും നിർബന്ധമാക്കപ്പെട്ടതായി ഞാൻ മനസ്സിലാക്കുന്നു. അവ രണ്ടും ഒന്നിച്ച് ഞാനെങ്ങനെ ചെയ്യും? അദ്ദേഹം പറഞ്ഞു: നിങ്ങൾ രണ്ടും ഒന്നിച്ച് ചെയ്യുക. ഞാൻ രണ്ടിനും ഇഹ്റാം ചെയ്തു. ''ഉദൈബ''യിൽ ചെന്നപ്പോൾ ഞാൻ ഹജ്ജിനം ഉംറക്കും ഒന്നിച്ച് ഇഹ്റാം ചെയ്ത അവസ്ഥയിൽ സൽമാനും സഅ്ദും എന്നെ കണ്ടു. അവരിലൊരാൾ മറ്റേയാളോട് പറഞ്ഞു: ഇവൻ തന്റെ ഒട്ടകത്തേക്കാൾ വിവരം കെട്ടവനാണ്. സ്വുബയ്യ്(റ) തുടരുന്നു: ഒരു പർവ്വതം എനിക്കുമേൽ ഇടപ്പെട്ട പ്രയാസം എനിക്കനുഭവപ്പെട്ടു. ഉമർ(റ)നെ കണ്ടപ്പോൾ ഞാനിക്കാര്യം പറഞ്ഞു; അമീറുൽ മുഅ്മിനീൻ, ഞാനൊരു ക്രിസ്തീയ അഅ്റാബിയായിരുന്നു. ഞാൻ മുസ്‌ലിമായി. ഞാൻ ജിഹാദിന് വല്ലാതെ ആഗ്രഹമുള്ളവനാണ്. എനിക്ക് ഹജ്ജും ഉംറയും നിർബന്ധമാക്കപ്പെട്ടതായി ഞാൻ മനസ്സിലാക്കുന്നു. ഞാനെന്റെ സമൂഹത്തിൽപെട്ട ഒരാളെ സമീപിച്ചപ്പോൾ അദ്ദേഹം പറഞ്ഞു: നിങ്ങൾ രണ്ടും ഒന്നിച്ച് ചെയ്യുക. സാധിക്കുന്ന ഹദ്‌യ അറുക്കുക. അങ്ങനെ ഞാൻ അവ രണ്ടിനും ഒന്നിച്ച് ഇഹ്റാം ചെയ്തിരിക്കുന്നു. ഉമർ(റ) പറഞ്ഞു: നിങ്ങളുടെ പ്രവാചകന്റെ ചര്യയിലേക്കു നിങ്ങൾ സന്മാർഗ്ഗസിദ്ധനാക്കപ്പെട്ടു. (ദ,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 151, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّهَا حَاضَتْ بِسَرِفَ فَتَطَهَّرَتْ بِعَرَفَةَ، فَقَالَ لَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "يُجْزِئُ عَنْكِ طَوَافُكِ بِالصَّفَا وَالْمَرْوَةِ عَنْ حَجِّكِ وَعُمْرَتِكِ". (م)', 'ആഇശ(റ): അവർക്ക് സരിഫിൽ വെച്ച് ആർത്തവമുണ്ടാവുകയും അറഫയിൽ വെച്ച് അവർ ശുദ്ധിയാവുകയും ചെയതു. അന്നേരം അവരോട് റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളുടെ ഹജ്ജിനും, ഉംറക്കും പകരമായി സ്വഫാ, മർവ്വാക്കിടയിലുള്ള പ്രദക്ഷിണം മതിയാവും." (മു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 292, 292, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 152, 'عَنْ سَبْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: خَرَجْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، حَتَّى إِذَا كَانَ بِعُسْفَانَ قَالَ لَهُ سُرَاقَةُ بْنُ مَالِكٍ الْمُدْلَجِيُّ: يَا رَسُولَ اللَّهِ، اقْضِ لَنَا قَضَاءَ قَوْمٍ كَأَنَّمَا وُلِدُوا الْيَوْمَ. فَقَالَ: "إِنَّ اللَّهَ تَعَالَى قَدْ أَدْخَلَ عَلَيْكُمْ فِي حَجِّكُمْ هَذَا عُمْرَةً، فَإِذَا قَدِمْتُمْ فَمَنْ تَطَوَّفَ بِالْبَيْتِ وَبَيْنَ الصَّفَا وَالْمَرْوَةِ فَقَدْ حَلَّ. إِلَّا مَنْ كَانَ مَعَهُ هَدْيٌ". (د)', 'സബുറ(റ): ഞങ്ങൾ റസൂൽ(സ)യോടൊപ്പം പുറപ്പെട്ടു. ഉസഫാനിലെത്തിയപ്പോൾ സുറാഖ(റ) റസൂൽ(സ)യോട് ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, ഈ ദിവസത്തിൽ ജനിച്ചവരുടെ വിധി ഞങ്ങൾക്ക് താങ്കൾ വിധിക്കുക. റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹു നിങ്ങളുടെ ഈ ഹജ്ജിൽ ഉംറയെ പ്രവേശിപ്പിച്ചിരിക്കുന്നു. നിങ്ങൾ മക്കയിൽ വന്നാൽ കഅ്ബയും സ്വഫാ മർവ്വക്കിടയിലും ത്വവാഫ് ചെയ്ത് തഹല്ലുലാവുക. ഹദ്‌യ കൂടെ ഉളളവരൊഴികെ." (ദ)', 'سَبْرَةَ', 'സബുറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 292, 292, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 153, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ مُعَاوِيَةَ قَالَ لَهُ: أَمَا عَلِمْتَ أَنِّي قَصَّرْتُ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِمِشْقَصِ أَعْرَابِيٍّ عَلَى الْمَرْوَةِ لِحَجَّتِهِ. (د,ن)', 'ഇബ്നുഅബ്ബാസ്(റ): മുആവിയ(റ) അദ്ദേഹത്തോട് പറഞ്ഞു: റസൂൽ(സ)യുടെ മുടി അവിടത്തെ ഹജ്ജിൽ മർവ്വയിൽ വെച്ച് ഒരു അഅ്റാബിയുടെ കത്രിക കൊണ്ട് ഞാൻ വെട്ടിയത് നിങ്ങൾക്കറിയില്ലേ? (ദ,ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 293, 293, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 154, 'عَنْ مَرْوَانَ: أَنَّ عُثْمَانَ رَضِيَ اللهُ عَنْهُ نَهَى عَنِ الْمُتْعَةِ، وَأَنْ يَجْمَعَ الرَّجُلُ بَيْنَ الْحَجِّ وَالْعُمْرَةِ، فَقَالَ عَلِيٌّ رَضِيَ اللهُ عَنْهُ: لَبَّيْكَ بِحَجَّةٍ وَعُمْرَةٍ مَعًا. فَقَالَ عُثْمَانُ: أَتَفْعَلُهَا وَأَنَا أَنْهَى عَنْهَا؟ فَقَالَ عَلِيٌّ: لَمْ أَكُنْ لِأَدَعَ سُنَّةَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِأَحَدٍ مِنَ النَّاسِ. (ن)', 'മർവാൻ: തമത്തുആയി ഹജ്ജ് ചെയ്യൽ ഉസ്മാൻ(റ) നിരോധിച്ചു. ഹജ്ജും ഉംറയും ഒരുമിച്ച് ചെയ്യലും നിരോധിച്ചു. അലി(റ) പറഞ്ഞു: ഹജ്ജിനും ഉംറക്കും ഒന്നിച്ച് ഞാൻ ഉത്തരം നൽകുന്നു. അപ്പോൾ ഉസ്മാൻ(റ) ചോദിച്ചു: ഞാൻ നിരോധിച്ചിരിക്കെ താങ്കൾ അത് ചെയ്യുകയോ? അലി(റ) പറഞ്ഞു: ജനങ്ങളിലൊരാൾക്കു വേണ്ടി ഞാൻ തിരുനബി(സ)യുടെ ചര്യ ഉപേക്ഷിക്കുകയില്ല. (ന)', 'مَرْوَانَ', 'മർവാൻ', null, null, array['ن']::text[], array['ന']::text[], null, null, 293, 293, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 155, 'عَنْ عِمْرَانَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جَمَعَ بَيْنَ حَجٍّ وَعُمْرَةٍ، ثُمَّ لَمْ يَنْزِلْ فِيهَا كِتَابٌ، وَلَمْ يَنْهَ عَنْهُمَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ فِيهِمَا رَجُلٌ بِرَأْيِهِ مَا شَاءَ. وفي رواية: تَمَتَّعْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ .(ن)', 'ഇംറാൻ(റ): റസൂൽ(സ) ഹജ്ജും ഉംറയും ഒരുമിച്ച് ചെയ്തു. പിന്നെ അക്കാര്യത്തിൽ ഖുർആൻ ഇറങ്ങുകയോ റസൂൽ(സ) അത് തടയുകയോ ചെയ്തിട്ടില്ല. പിന്നെ ഏതോ ഒരാൾ അവ്വിഷയകമായി സ്വന്തം അഭിപ്രായം പറഞ്ഞതാണ്. മറ്റൊരു നിവേദനത്തിൽ: ഞങ്ങൾ റസൂൽ(സ)യോടൊപ്പം തമത്തുഅ് ആയി ഹജ്ജ് നിർവ്വഹിച്ചു. (ന)', 'عِمْرَانَ', 'ഇംറാൻ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 293, 293, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=4 and h.hadith_no=155), 1, 'وَفِي رِوَايَةٍ: تَمَتَّعْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ .(ن)', 'മറ്റൊരു നിവേദനത്തിൽ: ഞങ്ങൾ റസൂൽ(സ)യോടൊപ്പം തമത്തുഅ് ആയി ഹജ്ജ് നിർവ്വഹിച്ചു. (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 156, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَخْبَرَنِي أَبُو طَلْحَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَرَنَ الْحَجَّ وَالْعُمْرَةَ. (جه)', 'ഇബ്നുഅബ്ബാസ്(റ): അബൂത്വൽഹ(റ) എന്നോട് പറഞ്ഞു: റസൂൽ(സ) ഹജ്ജും ഉംറയും ഖിറാനായി(ഒരുമിച്ച്) നിർവ്വഹിച്ചു. (ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 293, 293, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 157, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّهُ سُئِلَ عَنِ الْعُمْرَةِ قَبْلَ الْحَجِّ فَقَالَ: لَا بَأْسَ، وَقَالَ: اعْتَمَرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَبْلَ أَنْ يَحُجَّ. (خ)', 'ഇബ്നുഉമർ(റ): ഹജ്ജിനു മുമ്പ് ഉംറ ചെയ്യുന്നതിനെപ്പറ്റി ചോദിക്കപ്പെട്ടപ്പോൾ അദ്ദേഹം പറഞ്ഞു: കുഴപ്പമില്ല, റസൂൽ(സ) ഹജ്ജിനു മുമ്പ് ഉംറ ചെയ്തിട്ടുണ്ട്. (ബു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 293, 293, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=34 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 158, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَرَادَ الْحَجَّ عَامَ نَزَلَ الْحَجَّاجُ بِابْنِ الزُّبَيْرِ رَضِيَ اللهُ عَنْهُمَا: فَقِيلَ لَهُ: إِنَّهُ كَائِنٌ بَيْنَهُمْ قِتَالٌ، وَأَنَا أَخَافُ أَنْ يَصُدُّوكَ؟ قَالَ: {لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ} [الأحزاب: ٢١] إِذًا أَصْنَعُ كَمَا صَنَعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، إِنِّي أُشْهِدُكُمْ أَنِّي قَدْ أَوْجَبْتُ عُمْرَةً، ثُمَّ خَرَجَ حَتَّى إِذَا كَانَ بِظَاهِرِ الْبَيْدَاءِ قَالَ: مَا شَأْنُ الْحَجِّ وَالْعُمْرَةِ إِلَّا وَاحِدٌ، أُشْهِدُكُمْ أَنِّي قَدْ أَوْجَبْتُ حَجًّا مَعَ عُمْرَتِي. وَأَهْدَى هَدْيًا اشْتَرَاهُ بِقُدَيْدٍ، ثُمَّ انْطَلَقَ يُهِلُّ بِهِمَا جَمِيعًا حَتَّى قَدِمَ مَكَّةَ، فَطَافَ بِالْبَيْتِ وَبِالصَّفَا وَالْمَرْوَةِ وَلَمْ يَزِدْ عَلَى ذَلِكَ، وَلَمْ يَنْحَرْ وَلَمْ يَحْلِقْ وَلَمْ يُقَصِّرْ، وَلَمْ يَحِلَّ مِنْ شَيْءٍ حَرُمَ مِنْهُ حَتَّى كَانَ يَوْمُ النَّحْرِ، فَنَحَرَ وَحَلَقَ، فَرَأَى أَنْ قَدْ قَضَى طَوَافَ الْحَجِّ وَالْعُمْرَةِ بِطَوَافِهِ الْأَوَّلِ. وَقَالَ ابْنُ عُمَرَ: كَذَلِكَ فَعَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (ن)', 'ഇബ്നുഉമർ(റ): ഇബ്നുസുബൈർ(റ)വും ഹജ്ജാജും യുദ്ധമുണ്ടായ വർഷത്തിൽ ഇബ്നുഉമർ(റ) ഹജ്ജ് ചെയ്യാനുദ്ദേശിച്ചു. അദ്ദേഹത്തോട് ആരോ പറഞ്ഞു: അവിടെ യുദ്ധം നടക്കുകയാണ്, താങ്കളെ അവർ തടയുമെന്ന് ഞാൻ ഭയക്കുന്നു. ഇബ്നുഉമർ(റ) പറഞ്ഞു: ''അല്ലാഹുവിന്റെ റസൂൽ(സ)യിൽ നിങ്ങൾക്ക് ഉത്തമ മാതൃകയുണ്ട്.'' (അഹ്സാബ്: 21). റസൂൽ(സ) ചെയ്തതുപോലെ ഞാൻ ചെയ്യും. ഞാൻ ഉംറക്ക് ഇഹ്റാം ചെയ്തതായി നിങ്ങളെ സാക്ഷ്യപ്പെടുത്തുന്നു. പിന്നെ അവർ പുറപ്പെട്ട് ബൈദാഇനു പുറത്തെത്തി. അദ്ദേഹം പറഞ്ഞു: ഹജ്ജും ഉംറയും ഒരുപോലെയാണ്. ഞാനെന്റെ ഉംറക്കൊപ്പം ഹജ്ജിനും ഇഹ്റാം ചെയ്തതായി നിങ്ങളെ സാക്ഷ്യപ്പെടുത്തുന്നു. ഖുദൈദിൽ നിന്ന് വാങ്ങിയ ബലിമൃഗത്തെ അവർ കൂടെ കൊണ്ടുപോയി. പിന്നെ രണ്ടിനും ഇഹ്റാം ചെയ്തു മക്കയിലെത്തി കഅ്ബ, സ്വഫാ, മർവ്വ എന്നിവ ത്വവാഫ് ചെയ്തു. അതിൽ കൂടുതലൊന്നും അധികരിപ്പിച്ചില്ല. അറുക്കുകയോ മുടി വെട്ടുകയോ വടിക്കുകയോ ചെയ്തില്ല. പെരുന്നാൾ വരെ നിഷിദ്ധമായതിൽ നിന്നൊന്നും തഹല്ലുലായില്ല. പെരുന്നാൾ ദിനത്തിൽ അറുത്തു. മുടി വെട്ടി. ആദ്യ ത്വവാഫ് കൊണ്ടുതന്നെ ഹജ്ജ് ഉംറകളുടെ ത്വവാഫ് നിർവ്വഹിച്ചതായി അവർ അഭിപ്രായപ്പെട്ടു. ഇബ്നുഉമർ(റ) പറഞ്ഞു: റസൂൽ(സ) ഇപ്രകാരമാണ് ചെയ്തത്. (ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], 'الأحزاب: ٢١', null, 293, 294, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=34 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 159, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: حَدِيثُهَا فِي الْحَجِ قَدْ تَقَدَّمَ قَالَتْ فِي هَذِهِ الرِّوَايَةِ: خَرَجْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي أَشْهُرِ الْحَجِّ وَلَيَالِي الْحَجِّ وَحُرُمِ الْحَجِّ، فَنَزَلْنَا بِسَرِفَ، قَالَتْ: فَخَرَجَ إِلَى أَصْحَابِهِ فَقَالَ: مَنْ لَمْ يَكُنْ مِنْكُمْ مَعَهُ هَدْيٌ فَأَحَبَّ أَنْ يَجْعَلَهَا عُمْرَةً فَلْيَفْعَلْ، وَمَنْ كَانَ مَعَهُ الْهَدْيُ فَلَا، قَالَتْ: فَالْآخِذُ بِهَا وَالتَّارِكُ لَهَا مِنْ أَصْحَابِهِ، قَالَتْ: فَأَمَّا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَرِجَالٌ مِنْ أَصْحَابِهِ فَكَانُوا أَهْلَ قُوَّةٍ وَكَانَ مَعَهُمُ الْهَدْيُ فَلَمْ يَقْدِرُوا عَلَى الْعُمْرَةِ، وَذَكَرَ بَاقِي الْحَدِيثِ. (خ)', 'ആഇശ(റ): ഹജ്ജിനെപ്പറ്റി ഇവരിൽ നിന്നുള്ള റിപ്പോർട്ട് മുമ്പ് വന്നിട്ടുണ്ട്. ഈ നിവേദനത്തിൽ അവർ പറയുന്നു: ഹജ്ജ് മാസത്തിൽ ഹജ്ജിന്റെ രാത്രികളിൽ ഹജ്ജിന്റെ പവിത്രതയിൽ ഞങ്ങൾ റസൂൽ(സ)യോടൊപ്പം പുറപ്പെട്ടു. ഞങ്ങൾ സരിഫിലെത്തി. ആഇശ(റ) പറഞ്ഞു: റസൂൽ(സ) തന്റെ അനുചരരുടെ അടുത്തേക്ക് പോയി. റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളിലാരുടേയെങ്കിലും കൂടെ ഹദ്‌യ ഇല്ലാതിരിക്കുകയും, തന്റെ ഹജ്ജിനെ ഉംറയാക്കൻ ഇഷ്ടപ്പെടുകയും ചെയ്യുന്നവർ, അങ്ങനെ ചെയ്യട്ടെ. ഹദ്‌യ് കൂടെയുള്ളവർ അത് ചെയ്യരുത്." ആഇശ(റ) പറഞ്ഞു: അങ്ങനെ ചെയ്തവരും ഉപേക്ഷിച്ചവരും അക്കൂട്ടത്തിലുണ്ടായിരുന്നു. ആഇശ(റ) പറഞ്ഞു: റസൂൽ(സ)യും ചില അനുചരന്മാരും ശക്തരായിരുന്നു. അവർക്കൊപ്പം ഹദ്‌യയുണ്ടായിരുന്നു. അതിനാലവർക്ക് ഉംറ ചെയ്യാൻ സാധിച്ചില്ല. (ഹദീസ് തുടരുന്നു) (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 294, 294, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 160, 'عَنْ أَبِي ذَرٍّ رَضِيَ اللهُ عَنْهُ: أَنَّهُ كَانَ يَقُولُ فِيمَنْ حَجَّ ثُمَّ فَسَخَهَا بِعُمْرَةٍ: لَمْ يَكُنْ ذَلِكَ إِلَّا لِلرَّكْبِ الَّذِينَ كَانُوا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (م,د,ن,جه)', 'അബൂദർറ്(റ): ഹജ്ജ് ചെയ്യാനുദ്ദേശിച്ച് പിന്നെ അതിനെ ഉംറ കൊണ്ട് ഫസ്ഖ് (കാൻസൽ) ചെയ്തവരെപ്പറ്റി അദ്ദേഹം പറഞ്ഞു: അത് റസൂൽ(സ)യോടൊപ്പമുണ്ടായിരുന്നവർക്കു മാത്രമേ അനുവാദമുണ്ടായിരുന്നുളളു. (മു,ദ,ന,ജ)', 'أَبِي ذَرٍّ', 'അബൂദർറ്(റ)', null, null, array['م','د','ن','جه']::text[], array['മു','ദ','ന','ജ']::text[], null, null, 294, 295, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 161, 'عَنْ بِلَالِ بْنِ الْحَارِثِ رَضِيَ اللهُ عَنْهُ قَالَ: قُلْتُ: يَا رَسُولَ اللَّهِ، فَسْخُ الْحَجِّ، لَنَا خَاصَّةٌ أَوْ لِمَنْ بَعْدَنَا؟ قَالَ: "بَلْ لَكُمْ خَاصَّةٌ". (د,ن,جه)', 'ബിലാൽ ബിൻ ഹാരിസ്(റ): ഞാൻ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, ഹജ്ജ് ഒഴിവാക്കൽ ഞങ്ങൾക്കു മാത്രമായുള്ളതാണോ, അതോ ശേഷമുള്ളവർക്കുമുണ്ടോ? റസൂൽ(സ) പറഞ്ഞു: "അത് നിങ്ങൾക്കു മാത്രമുള്ള പ്രത്യേകതയാണ്." (ദ,ന,ജ)', 'بِلَالِ بْنِ الْحَارِثِ', 'ബിലാൽ ബിൻ ഹാരിസ്(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 295, 295, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 162, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا أَنَّهَا قَالَتْ: خَرَجْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَامَ حَجَّةِ الْوَدَاعِ، فَمِنَّا مَنْ أَهَلَّ بِعُمْرَةٍ وَمِنَّا مَنْ أَهَلَّ بِحَجٍّ، حَتَّى قَدِمْنَا مَكَّةَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ أَحْرَمَ بِعُمْرَةٍ وَلَمْ يُهْدِ فَلْيَحْلِلْ، وَمَنْ أَحْرَمَ بِعُمْرَةٍ وَأَهْدَى فَلَا يَحِلُّ حَتَّى يَنْحَرَ هَدْيَهُ، وَمَنْ أَهَلَّ بِحَجٍّ فَلْيُتِمَّ حَجَّهُ". قَالَتْ عَائِشَةُ رَضِيَ اللهُ عَنْهَا: فَحِضْتُ، فَلَمْ أَزَلْ حَائِضًا حَتَّى كَانَ يَوْمُ عَرَفَةَ، وَلَمْ أُهْلِلْ إِلَّا بِعُمْرَةٍ، فَأَمَرَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ أَنْقُضَ رَأْسِي، وَأَمْتَشِطَ، وَأُهِلَّ بِحَجٍّ، وَأَتْرُكَ الْعُمْرَةَ. قَالَتْ: فَفَعَلْتُ ذَلِكَ، حَتَّى إِذَا قَضَيْتُ حَجَّتِي بَعَثَ مَعِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَبْدَ الرَّحْمَنِ بْنَ أَبِي بَكْرٍ، وَأَمَرَنِي أَنْ أَعْتَمِرَ مِنَ التَّنْعِيمِ مَكَانَ عُمْرَتِي الَّتِي أَدْرَكَنِي الْحَجُّ وَلَمْ أَحْلِلْ مِنْهَا. (م)', 'ആഇശ(റ): ഹജ്ജതുൽ വിദാഇൽ ഞങ്ങൾ റസൂൽ(സ)യോടൊപ്പം പുറപ്പെട്ടു. ഉംറക്ക് ഇഹ്റാം ചെയ്തവരും ഹജ്ജിന് ഇഹ്റാം ചെയ്തവരും ഞങ്ങളിലുണ്ടായിരുന്നു. ഞങ്ങൾ മക്കയിലെത്തി. റസൂൽ(സ) പറഞ്ഞു: "ഉംറക്ക് ഇഹ്റാം ചെയ്ത, ഹദ്‌യ ഇല്ലാത്തവർ തഹല്ലുലാവട്ടെ. ഹദ്‌യ ഉള്ള ഉംറക്ക് ഇഹ്റാം ചെയ്തവർ ഹദ്‌യ അറുക്കുന്നതു വരെ തഹല്ലുലാവരുത്. ഹജ്ജിന് ഇഹ്റാം ചെയ്തവനത് പൂർത്തിയാക്കട്ടെ." ആഇശ(റ) പറയുന്നു: എനിക്ക് ആർത്തവമുണ്ടായി. അറഫാ ദിനം വരെ ഈ നിലയിൽ തുടർന്നു. ഞാൻ ഉംറക്കല്ലാതെ ഇഹ്റാം ചെയ്തിട്ടില്ല. അപ്പോൾ റസൂൽ(സ) എന്നോട് തല മെടയാനും മുടി ചീകാനും കൽപിച്ചു. ഉംറ ഉപേക്ഷിച്ച് ഹജ്ജിന് ഇഹ്റാം ചെയ്യാനും റസൂൽ(സ) കൽപിച്ചു. ആഇശ(റ) പറയുന്നു: ഞാനപ്രകാരം ചെയ്തു. എന്റെ ഹജ്ജിനു ശേഷം റസൂൽ(സ) എന്നോട് അബ്ദുർറഹ്മാനുബ്നു അബൂബക്കറിനൊപ്പം തൻഈമിൽ ചെന്ന് ഉംറക്ക് ഇഹ്റാം ചെയ്യാൻ കൽപിച്ചു. ഹജ്ജ് ചെയ്തപ്പോൾ ഞാൻ തഹല്ലുലാവാതിരുന്ന ഉംറക്ക് പകരമായിരുന്നു ഇത്. (മു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 295, 295, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 163, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: صَلَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَنَحْنُ مَعَهُ بِالْمَدِينَةِ الظُّهْرَ أَرْبَعًا، وَالْعَصْرَ بِذِي الْحُلَيْفَةِ رَكْعَتَيْنِ، ثُمَّ بَاتَ بِهَا حَتَّى أَصْبَحَ، ثُمَّ رَكِبَ حَتَّى اسْتَوَتْ بِهِ عَلَى الْبَيْدَاءِ حَمِدَ اللَّهَ وَسَبَّحَ وَكَبَّرَ، ثُمَّ أَهَلَّ بِحَجٍّ وَعُمْرَةٍ وَأَهَلَّ النَّاسُ بِهِمَا، فَلَمَّا قَدِمْنَا أَمَرَ النَّاسَ فَحَلُّوا حَتَّى كَانَ يَوْمُ التَّرْوِيَةِ أَهَلُّوا بِالْحَجِّ، قَالَ: وَنَحَرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَدَنَاتٍ بِيَدِهِ قِيَامًا، وَذَبَحَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالْمَدِينَةِ كَبْشَيْنِ أَمْلَحَيْنِ. (خ)', 'അനസ്(റ): റസൂൽ(സ)യും ഞങ്ങളും മദീനയിൽ വെച്ച് ളുഹ്ർ നാലു റക്അത്ത് നിസ്കരിച്ചു. ദുൽഹുലൈഫയിൽ വെച്ച് അസ്വർ രണ്ട് റക്അത്തും നിസ്കരിച്ചു. പിന്നെ പുലരുവോളം അവിടെ രാപാർത്തു. വാഹനത്തിലേറി ബൈദാഇലെത്തിയപ്പോൾ ഹംദും തസ്ബീഹും തക്ബീറും ചൊല്ലി. പിന്നെ റസൂൽ(സ)യും ഞങ്ങളും ഹജ്ജിനും ഉംറക്കും ഇഹ്റാം ചെയ്തു. പിന്നെ ഞങ്ങൾ മുന്നിട്ടപ്പോൾ അനുചരരോട് തഹല്ലുലാകാൻ കൽപ്പിച്ചു; അവർ (അനുചരർ) തഹല്ലുലായി. തർവിയത്ത് ദിനത്തിൽ ഹജ്ജിന് ഇഹ്റാം ചെയ്തു. റിപ്പോർട്ടർ പറയുന്നു: റസൂൽ(സ) അവിടത്തെ കൈകൾ കൊണ്ട് കുറേ ഒട്ടകങ്ങളെ നിന്നുകൊണ്ട് അറുത്തു. മദീനയിൽ വെച്ച് ചാരനിറമുള്ള രണ്ട് ആടുകളെ അവിടന്ന് അറുത്തു. (ബു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 295, 296, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 164, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَمَّا مُوسَى كَأَنِّي أَنْظُرُ إِلَيْهِ إِذِ انْحَدَرَ فِي الْوَادِي يُلَبِّي". (خ)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ഈ മലഞ്ചെരുവിൽ തൽബിയത്ത് ചൊല്ലിക്കൊണ്ട് മൂസാ(അ) ഇറങ്ങി വരുന്നത് ഞാനിപ്പോഴും കാണുന്നതു പോലെയുണ്ട്." (ബു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 296, 296, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 165, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا اسْتَوَتْ بِهِ رَاحِلَتُهُ قَائِمَةً عِنْدَ مَسْجِدِ ذِي الْحُلَيْفَةِ أَهَلَّ، فَقَالَ: "لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ، لَبَّيْكَ لَا شَرِيكَ لَكَ لَبَّيْكَ، إِنَّ الْحَمْدَ وَالنِّعْمَةَ لَكَ وَالْمُلْكَ، لَا شَرِيكَ لَكَ". قَالُوا: وَكَانَ عَبْدُ اللَّهِ بْنُ عُمَرَ رَضِيَ اللهُ عَنْهُمَا يَقُولُ: [هَذِهِ] تَلْبِيَةُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. قَالَ نَافِعٌ: كَانَ عَبْدُ اللَّهِ رَضِيَ اللهُ عَنْهُ يَزِيدُ مَعَ هَذَا: لَبَّيْكَ لَبَّيْكَ، لَبَّيْكَ وَسَعْدَيْكَ، وَالْخَيْرُ بِيَدَيْكَ، لَبَّيْكَ وَالرَّغْبَاءُ إِلَيْكَ وَالْعَمَلُ. (ق,د,ت,ن,جه)', 'അബ്ദുല്ല ബിൻ ഉമർ(റ): ദുൽഹുലൈഫയിലെ പള്ളിക്കു സമീപം അവിടത്തെ വാഹനം നേരെ നിന്നാൽ റസൂൽ(സ) ഇഹ്റാം ചെയ്യുമായിരുന്നു. റസൂൽ(സ) പറയുകയും ചെയ്തു: "ലബ്ബൈകല്ലാഹുമ്മ ലബ്ബൈക്, ലബ്ബൈക ലാ ശരീകലക ലബ്ബൈക്, ഇന്നൽ ഹംദ വന്നിഅ്മത ലക വൽ മുൽക്, ലാ ശരീക ലക്." (അല്ലാഹുവേ, നിന്റെ വിളിക്ക് ഞാനുത്തരം നൽകുന്നു, നിന്റെ വിളിക്ക് ഞാനുത്തരം നൽകുന്നു, നിന്റെ വിളിക്ക് ഞാനുത്തരം നൽകുന്നു. നിനക്കു പങ്കുകാരില്ല. നിനക്കുത്തരം നൽകുന്നു. അധികാരവും അനുഗ്രഹവും സ്തുതിയും നിനക്കാണ്. നിനക്കു പങ്കുകാരില്ല.) അനുചരന്മാർ പറഞ്ഞു: ഇതാണ് റസൂൽ(സ)യുടെ തൽബിയത് എന്ന് ഇബ്നുഉമർ(റ) പറയാറുണ്ട്. നാഫിഅ് പറഞ്ഞു: ഈ തൽബിയതിനോടൊപ്പം ലബ്ബൈക ലബ്ബൈക്, ലബ്ബൈക വസഅ്ദൈക, വൽ ഖൈറു ബിയദൈക ലബ്ബൈക വർറഗ്ബാഉ ഇലൈക വൽഅമലു എന്നുകൂടി ഇബ്നുഉമർ(റ) പറയാറുണ്ട്. (ബു,മു,ദ,തു,ന,ജ)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ല ബിൻ ഉമർ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], 'هَذِهِ', null, 296, 296, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 166, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: أَهَلَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَذَكَرَ التَّلْبِيَةَ مِثْلَ حَدِيثِ ابْنِ عُمَرَ، قَالَ: وَالنَّاسُ يَزِيدُونَ: ذَا الْمَعَارِجِ، وَنَحْوَهُ مِنَ الْكَلَامِ، وَالنَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَسْمَعُ فَلَا يَقُولُ لَهُمْ شَيْئًا. (د,جه)', 'ജാബിർ ബിൻ അബ്ദുല്ല(റ): റസൂൽ(സ) ഇഹ്റാം ചെയ്തു. ഇബ്നുഉമർ(റ) പറഞ്ഞതു പോലെയുള്ള തൽബിയത് ചൊല്ലി. റിപ്പോർട്ടർ പറഞ്ഞു: ''ദൽ മആരിജ്'' പോലുള്ള വാക്കുകൾ ജനങ്ങൾ വർദ്ധിപ്പിച്ചു. എന്നാൽ റസൂൽ(സ) അതുകേട്ട് അവരോട് ഒന്നും പറഞ്ഞില്ല. (ദ,ജ)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിർ ബിൻ അബ്ദുല്ല(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 296, 296, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 167, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُهِلُّ يَقُولُ: "لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ، لَبَّيْكَ لَا شَرِيكَ لَكَ لَبَّيْكَ، إِنَّ الْحَمْدَ وَالنِّعْمَةَ لَكَ وَالْمُلْكَ، لَا شَرِيكَ لَكَ". وَإِنَّ عَبْدَ اللَّهِ بْنَ عُمَرَ كَانَ يَقُولُ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَرْكَعُ بِذِي الْحُلَيْفَةِ رَكْعَتَيْنِ، ثُمَّ إِذَا اسْتَوَتْ بِهِ النَّاقَةُ قَائِمَةً عِنْدَ مَسْجِدِ ذِي الْحُلَيْفَةِ أَهَلَّ بِهَؤُلَاءِ الْكَلِمَاتِ. (ن)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) തൽബിയത് ചൊല്ലുന്നത് ഞാൻ കേട്ടു: "ലബ്ബൈകല്ലാഹുമ്മ ലബ്ബൈക്, ലബ്ബൈക ലാ ശരീക ലക ലബ്ബൈക്, ഇന്നൽ ഹംദ വന്നിഅ്മത ലക വൽ മുൽക്, ലാ ശരീക ലക്" ഇബ്നുഉമർ(റ) പറയുമായിരുന്നു: റസൂൽ(സ) ദുൽഹുലൈഫയിൽ വെച്ച് രണ്ട് റക്അത്ത് നിസ്കരിക്കാറുണ്ട്. പിന്നെ ദുൽഹുലൈഫ പള്ളിയുടെ അടുത്ത് വെച്ച് വാഹനം (യാത്രക്ക്) തയ്യാറായാൽ ഈ വചനങ്ങൾ ചൊല്ലി കൊണ്ട് ഇഹ്റാം ചെയ്യും. (ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 296, 297, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 168, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ مِنْ تَلْبِيَةِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَبَّيْكَ إِلَهَ الْحَقِّ". وَفِي رِوَايَةٍ: "لَبَّيْكَ إِلَهَ الْحَقِّ لَبَّيْكَ ". (ن,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ)യുടെ തൽബിയതിൽ ഇതുമുണ്ടായിരുന്നു: "ലബ്ബൈക ഇലാഹൽ ഹഖ്." മറ്റൊരു നിവേദനത്തിൽ: "ലബ്ബൈക ഇലാഹൽ ഹഖ് ലബ്ബൈക്." (ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن','جه']::text[], array['ന','ജ']::text[], null, null, 297, 297, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=4 and h.hadith_no=168), 1, 'وَفِي رِوَايَةٍ: "لَبَّيْكَ إِلَهَ الْحَقِّ لَبَّيْكَ ". (ن,جه)', 'മറ്റൊരു നിവേദനത്തിൽ: "ലബ്ബൈക ഇലാഹൽ ഹഖ് ലബ്ബൈക്." (ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 169, 'عَنْ سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ رَضِيَ اللهُ عَنْهُ: عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَا مِنْ مُلَبٍّ يُلَبِّي إِلَّا لَبَّى مَا عَنْ يَمِينِهِ وَشِمَالِهِ، مِنْ حَجَرٍ أَوْ شَجَرٍ أَوْ مَدَرٍ، حَتَّى تَنْقَطِعَ الْأَرْضُ مِنْ هَاهُنَا وَهَاهُنَا". (ت,جه)', 'സഹ്ൽ ബിൻ സഅ്ദ് അസ്സാഇദീ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരാൾ തൽബിയത് ചൊല്ലുമ്പോൾ അവന്റെ ഇടതും വലതുമുള്ള സകലതും, കല്ലും മരവും കളിമണ്ണും, അവിടെനിന്നും ഇവിടെനിന്നും ഭൂമി പിളരുന്നത് വരെയും അവനുത്തരം ചെയ്ത് കൊണ്ടിരിക്കും." (തു,ജ)', 'سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ', 'സഹ്ൽ ബിൻ സഅ്ദ് അസ്സാഇദീ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 297, 297, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 170, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "وَالَّذِي نَفْسِي بِيَدِهِ لَيُهِلَّنَّ ابْنُ مَرْيَمَ بِفَجِّ الرَّوْحَاءِ، حَاجًّا أَوْ مُعْتَمِرًا، أَوْ لَيَثْنِيَنَّهُمَا". (م)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "എന്റെ ആത്മാവ് ആരുടെ കയ്യിലാണോ അവൻ തന്നെ സത്യം, റൗഹാഇലെ കുണ്ടിൽ വെച്ച് ഇബ്നുമർയം(അ) ഹജ്ജിനോ ഉംറക്കോ അല്ലെങ്കിൽ രണ്ടിനുംകൂടിയോ ഇഹ്റാം ചെയ്യുക തന്നെ ചെയ്യും." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 297, 297, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 171, 'عَنِ السَّائِبِ الْأَنْصَارِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "أَتَانِي جِبْرِيلُ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأَمَرَنِي أَنْ آمُرَ أَصْحَابِي وَمَنْ مَعِي: أَنْ يَرْفَعُوا أَصْوَاتَهُمْ بِالْإِهْلَالِ. أَوْ قَالَ: بِالتَّلْبِيَةِ". يُرِيدُ أَحَدَهُمَا . (د,ت,ن,جه)', 'സാഇബുൽ അൻസ്വാരി(റ): റസൂൽ(സ) പറഞ്ഞു: "എന്റെ അനുചരന്മാരോടും കൂടെയുള്ളവരോടും തൽബിയത് അല്ലെങ്കിൽ ഇഹ്‌ലാൽ ഉറക്കെ ചൊല്ലാൻ കൽപിക്കാൻ ജിബ്‌രീൽ(അ) വന്ന് എന്നോട് കൽപിച്ചു." (ദ,തു,ന,ജ)', 'السَّائِبِ الْأَنْصَارِيِّ', 'സാഇബുൽ അൻസ്വാരി(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 297, 297, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 172, 'عَنْ زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "جَاءَنِي جِبْرِيلُ فَقَالَ: يَا مُحَمَّدُ، مُرْ أَصْحَابَكَ فَلْيَرْفَعُوا أَصْوَاتَهُمْ بِالتَّلْبِيَةِ، فَإِنَّهَا مِنْ شِعَارِ الْحَجِّ". (جه)', 'സൈദ് ബിൻ ഖാലിദുൽ ജുഹനി(റ): റസൂൽ(സ) പറഞ്ഞു: "ജിബ്‌രീൽ(അ) എന്നെ സമീപിച്ച് ഇങ്ങനെ കൽപിച്ചു; മുഹമ്മദ്(സ), തൽബിയത് ഉറക്കെ ചൊല്ലാൻ താങ്കളുടെ അനുചരന്മാരോട് കൽപിക്കുക. കാരണം, അത് ഹജ്ജിന്റെ അടയാളമാണ്." (ജ)', 'زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ', 'സൈദ് ബിൻ ഖാലിദുൽ ജുഹനി(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 297, 298, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 173, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ أُسَامَةَ رَضِيَ اللهُ عَنْهُ كَانَ رِدْفَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ عَرَفَةَ إِلَى الْمُزْدَلِفَةِ، ثُمَّ أَرْدَفَ الْفَضْلَ مِنَ الْمُزْدَلِفَةِ إِلَى مِنًى، فَكِلَاهُمَا قَالَ: لَمْ يَزَلِ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُلَبِّي حَتَّى رَمَى جَمْرَةَ الْعَقَبَةِ. (خ)', 'ഇബ്നുഅബ്ബാസ്(റ): അറഫയിൽ നിന്ന് മുസ്ദലിഫ വരെ ഉസാമ(റ) റസൂൽ(സ)യുടെ സഹയാത്രികനായിരുന്നു. മുസ്ദലിഫയിൽ നിന്ന് മിനാ വരെ റസൂൽ(സ) ഫള്‌ൽ(റ)വിനെ (വാഹനത്തിന്റെ) പിന്നിലിരുത്തി. അവർരണ്ട് പേരും പറഞ്ഞു: ജംറതുൽ അഖബയിൽ എറിയുംവരെ റസൂൽ(സ) തൽബിയത് ചൊല്ലിക്കൊണ്ടേയിരുന്നു. (ബു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 298, 298, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 174, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: غَدَوْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ مِنًى إِلَى عَرَفَاتٍ، مِنَّا الْمُلَبِّي وَمِنَّا الْمُكَبِّرُ. (م,د)', 'അബ്ദുല്ല ബിൻ ഉമർ(റ): ഞങ്ങൾ റസൂൽ(സ)യോടൊപ്പം മിനായിൽ നിന്ന് അറഫയിലേക്ക് പുറപ്പെട്ടു. ഞങ്ങളിൽ തൽബിയത് ചൊല്ലുന്നവരും തക്ബീർ ചൊല്ലുന്നവരുമുണ്ടായിരുന്നു. (മു,ദ)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ല ബിൻ ഉമർ(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 298, 298, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 175, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "يُلَبِّي الْمُعْتَمِرُ حَتَّى يَسْتَلِمَ الْحَجَرَ". (د,ت)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) പറഞ്ഞു: "ഹജർ (അസ്‌വദ്) ചുംബിക്കുന്നതു വരെ ഉംറ ചെയ്യുന്നവൻ തൽബിയത് ചൊല്ലണം." (ദ,തു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 298, 298, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 176, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ ضُبَاعَةَ بِنْتَ الزُّبَيْرِ بْنِ عَبْدِ الْمُطَّلِبِ أَتَتْ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: يَا رَسُولَ اللَّهِ، إِنِّي أُرِيدُ الْحَجَّ، أَأَشْتَرِطُ؟ قَالَ: "نَعَمْ". قَالَتْ: فَكَيْفَ أَقُولُ؟ قَالَ: "قُولِي: لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ، وَمَحِلِّي مِنَ الْأَرْضِ حَيْثُ حَبَسْتَنِي". وفي رواية زَادَ: "فَإِنَّ لَكِ عَلَى رَبِّكِ مَا اسْتَثْنَيْتِ". (م,د,ت,ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): സുബൈറിന്റെ പുത്രി ളുബാഅ(റ) റസൂൽ(സ)യെ സമീപിച്ചു ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, ഞാൻ ഹജ്ജ് ചെയ്യാനുദ്ദേശിക്കുന്നു, ഞാനതിൽ ഉപാധി വെക്കട്ടെയോ? റസൂൽ(സ) പറഞ്ഞു: "അതെ." അവർ ചോദിച്ചു: അപ്പോൾ ഞാനെങ്ങനെയാണ് പറയേണ്ടത്? റസൂൽ(സ) പറഞ്ഞു: "നീ പറയുക; ലബ്ബൈകല്ലാഹുമ്മ ലബ്ബൈക്... ഭൂമിയിൽവെച്ച് എന്നെ നീ തടയുന്നിടത്താണ് എന്റെ തഹല്ലുലിന്റെ സ്ഥാനം." മറ്റൊരു നിവേദനത്തിൽ: "നീ മാറ്റി നിർത്തിയതിൽ നിനക്ക് നിന്റെ രക്ഷിതാവിന്റെ അടുത്ത് പ്രതിഫലമുണ്ട്." (മു,ദ,തു,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 298, 299, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=4 and h.hadith_no=176), 1, 'وَفِي رِوَايَةٍ زَادَ: "فَإِنَّ لَكِ عَلَى رَبِّكِ مَا اسْتَثْنَيْتِ". (م,د,ت,ن,جه)', 'മറ്റൊരു നിവേദനത്തിൽ: "നീ മാറ്റി നിർത്തിയതിൽ നിനക്ക് നിന്റെ രക്ഷിതാവിന്റെ അടുത്ത് പ്രതിഫലമുണ്ട്." (മു,ദ,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 177, 'عَنْ أَبِي بَكْرِ بْنِ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ رَضِيَ اللهُ عَنْهُ، عَنْ جَدَّتِهِ- قَالَ: لَا أَدْرِي أَسْمَاءَ بِنْتَ أَبِي بَكْرٍ، أَوْ: سُعْدَى بِنْتَ عَوْفٍ- رَضِيَ اللهُ عَنْهُمْ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ دَخَلَ عَلَى ضُبَاعَةَ بِنْتِ عَبْدِ الْمُطَّلِبِ، فَقَالَ: "مَا يَمْنَعُكِ يَا عَمَّتَاهُ مِنَ الْحَجِّ". فَقَالَتْ: أَنَا امْرَأَةٌ سَقِيمَةٌ، وَأَنَا أَخَافُ الْحَبْسَ. قَالَ: "فَأَحْرِمِي وَاشْتَرِطِي: أَنَّ مَحِلَّكِ حَيْثُ حُبِسْتِ". (جه)', 'അബൂബക്ർ ബിൻഅബ്ദില്ല ബിൻസുബൈർ(റ) തന്റെ വല്യമ്മയിൽ നിന്ന്: - നിവേദകൻ പറയുന്നു: അസ്മാഅ് ബിൻത്അബീ ബക്റാണോ, അതോ സുഅ്ദാ ബിൻത്ഔഫാണോ എന്നെനിക്കറിയില്ല - റസൂൽ(സ) ളുബാഅ(റ)യെ സമീപിച്ച് ചോദിച്ചു: "അമ്മായി, എന്താണ് ഹജ്ജിൽനിന്ന് നിങ്ങളെ തടയുന്നത്?" അവർ പറഞ്ഞു: ഞാൻ രോഗിയാണ്. ഞാൻ തടസ്സം ഭയക്കുന്നു. റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ ഇഹ്റാം ചെയ്യുക, നിങ്ങളുടെ മഹില്ല് (തഹല്ലുൽ സ്ഥാനം) തടസ്സം വരുന്നിടത്താണ് എന്ന് നിബന്ധന വെക്കുകയും ചെയ്യുക." (ജ)', 'أَبِي بَكْرِ بْنِ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ', 'അബൂബക്ർ ബിൻഅബ്ദില്ല ബിൻസുബൈർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 299, 299, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 178, 'عَنْ ضُبَاعَةَ رَضِيَ اللهُ عَنْهُ قَالَتْ: دَخَلَ عَلَيَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَنَا شَاكِيَةٌ. فَقَالَ: "أَمَا تُرِيدِينَ الْحَجَّ الْعَامَ". قُلْتُ: إِنِّي لَعَلِيلَةٌ، يَا رَسُولَ اللَّهِ! قَالَ: "حُجِّي وَقُولِي: مَحِلِّي حَيْثُ تَحْبِسُنِي". (جه)', 'ളുബാഅ(റ): ഞാൻ രോഗിയായിരിക്കെ റസൂൽ(സ) എന്റെയടുത്തു വന്നു. റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ ഈ വർഷം ഹജ്ജ് ചെയ്യാനുദ്ദേശിക്കുന്നില്ലേയോ? ഞാൻ പറഞ്ഞു: ഞാൻ രോഗിയാണ്, റസൂലേ. റസൂൽ(സ) പറഞ്ഞു: "ഹജ്ജ് ചെയ്യുക, പറയുക: എന്റെ തഹല്ലുലിന്റെ സ്ഥാനം തടസ്സം വരുന്നിടത്താണ്." (ജ)', 'ضُبَاعَةَ', 'ളുബാഅ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 299, 299, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 179, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّهُ كَانَ يُنْكِرُ الِاشْتِرَاطَ فِي الْحَجِّ، وَيَقُولُ: أَلَيْسَ حَسْبُكُمْ سُنَّةَ نَبِيِّكُمْ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟. (ت)', 'ഇബ്നുഉമർ(റ): ഹജ്ജിൽ നിബന്ധന വെക്കുന്നത് ഇബ്നുഉമർ(റ) നിഷേധിക്കുമായിരുന്നു. അദ്ദേഹം പറയുമായിരുന്നു: നിങ്ങൾക്ക് റസൂൽ(സ)യുടെ സുന്നത്ത് മതിയാവില്ലേ? (തു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 299, 299, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 180, 'عَنْ زَيْدِ بْنِ ثَابِتٍ رَضِيَ اللهُ عَنْهُ: أَنَّهُ رَأَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تَجَرَّدَ لِإِهْلَالِهِ وَاغْتَسَلَ. (ت)', 'സൈദ് ബിൻ സാബിത്(റ): റസൂൽ(സ) ഒന്നിനു മാത്രം ഇഹ്റാം ചെയ്യുന്നതും കുളിക്കുന്നതും അദ്ദേഹം കണ്ടു. (തു)', 'زَيْدِ بْنِ ثَابِتٍ', 'സൈദ് ബിൻ സാബിത്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 299, 299, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=44 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 181, 'عَنْ مُحَمَّدِ بْنِ أَبِي بَكْرٍ رَضِيَ اللهُ عَنْهُ، عَنْ أَبِي بَكْرٍ رَضِيَ اللهُ عَنْهُ: أَنَّهُ خَرَجَ حَاجًّا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَجَّةَ الْوَدَاعِ، وَمَعَهُ امْرَأَتُهُ أَسْمَاءُ بِنْتُ عُمَيْسٍ الْخَثْعَمِيَّةُ، فَلَمَّا كَانُوا بِذِي الْحُلَيْفَةِ وَلَدَتْ أَسْمَاءُ مُحَمَّدَ بْنَ أَبِي بَكْرٍ، فَأَتَى أَبُو بَكْرٍ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَخْبَرَهُ، فَأَمَرَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يَأْمُرَهَا أَنْ تَغْتَسِلَ، ثُمَّ تُهِلَّ بِالْحَجِّ وَتَصْنَعَ مَا يَصْنَعُ النَّاسُ، إِلَّا أَنَّهَا لَا تَطُوفُ بِالْبَيْتِ. (ن)', 'അബൂബക്കർ(റ)വിൽ നിന്ന് മുഹമ്മദ് ബിൻ അബീബകർ(റ): ഹജ്ജതുൽ വിദാഇന്റെ ദിവസം അബൂബക്ർ(റ) റസൂൽ(സ)യോടൊപ്പം ഹജ്ജ് ഉദ്ദേശിച്ച് പുറപ്പെട്ടു. ഒപ്പം അദ്ദേഹത്തിന്റെ ഭാര്യ അസ്മാഅ് ബിൻത് ഉമൈസുൽ ഖസ്അമിയ്യയുമുണ്ടായിരുന്നു. അവർ ദുൽഹുലൈഫയിലെത്തിയപ്പോൾ അസ്മാഅ് മുഹമ്മദിനെ പ്രസവിച്ചു. അബൂബകർ വിവരം റസൂൽ(സ)യെ അറിയിച്ചു. അവളോട് കുളിക്കാൻ കല്പിക്കാൻ റസൂൽ(സ) അബൂബകർ(റ)വിനോട് പറഞ്ഞു. പിന്നെ ഹജ്ജിന് ഇഹ്റാം ചെയ്ത് ജനങ്ങൾ ചെയ്യും പ്രകാരം ചെയ്യാനും, എന്നാൽ കഅ്ബ ത്വവാഫ് ചെയ്യരുതെന്നും റസൂൽ(സ) കല്പിച്ചു. (ന)', 'مُحَمَّدِ بْنِ أَبِي بَكْرٍ', 'അബൂബക്കർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 299, 300, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=44 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 182, 'عَنْ عَبْدِ اللَّهِ بْنِ حُنَيْنٍ رَضِيَ اللهُ عَنْهُ: أَنَّ عَبْدَ اللَّهِ بْنَ عَبَّاسٍ وَالْمِسْوَرَ بْنَ مَخْرَمَةَ- رَضِيَ اللهُ عَنْهُمْ- اخْتَلَفَا بِالْأَبْوَاءِ، فَقَالَ عَبْدُ اللَّهِ بْنُ عَبَّاسٍ: يَغْسِلُ الْمُحْرِمُ رَأْسَهُ .وَقَالَ الْمِسْوَرُ: لَا يَغْسِلُ الْمُحْرِمُ رَأْسَهُ. فَأَرْسَلَنِي ابْنُ عَبَّاسٍ إِلَى أَبِي أَيُّوبَ الْأَنْصَارِيِّ-رَضِيَ اللهُ عَنْهُ- أَسْأَلُهُ عَنْ ذَلِكَ، فَوَجَدْتُهُ يَغْتَسِلُ بَيْنَ الْقَرْنَيْنِ، وَهُوَ يَسْتَتِرُ بِثَوْبٍ، فَسَلَّمْتُ عَلَيْهِ، فَقَالَ: مَنْ هَذَا؟ قُلْتُ أَنَا عَبْدُ اللَّهِ بْنُ حُنَيْنٍ، أَرْسَلَنِي إِلَيْكَ عَبْدُ اللَّهِ بْنُ عَبَّاسٍ أَسْأَلُكَ: كَيْفَ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَغْسِلُ رَأْسَهُ وَهُوَ مُحْرِمٌ؟ قَالَ: فَوَضَعَ أَبُو أَيُّوبَ يَدَهُ عَلَى الثَّوْبِ فَطَأْطَأَهُ حَتَّى بَدَا لِي رَأْسُهُ، ثُمَّ قَالَ لِإِنْسَانٍ يَصُبُّ عَلَيْهِ: اصْبُبْ. فَصَبَّ عَلَى رَأْسِهِ، ثُمَّ حَرَّكَ رَأْسَهُ بِيَدِهِ، فَأَقْبَلَ بِهِمَا وَأَدْبَرَ، ثُمَّ قَالَ: هَكَذَا رَأَيْتُهُ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَفْعَلُ. (ق,د,ن,جه)', 'അബ്ദുല്ല ബിൻ ഹുനൈൻ(റ): അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ)വും, മിസ്‌വറുബ്നു മഖ്റമ(റ)വും അബവാഇൽ വെച്ച് തർക്കിച്ചു. ഇബ്നുഅബ്ബാസ്(റ) പറഞ്ഞു: ഹജ്ജിന് ഇഹ്റാം കെട്ടിയവന് തല കഴുകാം. മിസ്‌വർ(റ) പറഞ്ഞു: പറ്റില്ല. ഇബ്നുഅബ്ബാസ്(റ) ഇക്കാര്യം ചോദിക്കാൻ എന്നെ അബൂഅയ്യൂബുൽ അൻസാരി(റ)വിന്റെ അടുത്തേക്കയച്ചു. ഒരു വസ്ത്രം കൊണ്ട് മറയുണ്ടാക്കി, രണ്ട് കയറുകൾക്കിടയിൽ കുളിക്കുന്നതായി ഞാനദ്ദേഹത്തെ കണ്ടു. ഞാൻ സലാം ചൊല്ലി. അദ്ദേഹം ചോദിച്ചു: ആരാണത്? ഞാൻ പറഞ്ഞു: ഞാൻ ഇബ്നുഹുനൈനാണ്. റസൂൽ(സ) ഇഹ്റാമിലായിരിക്കെ എങ്ങനെയാണ് തല കഴുകിയിരുന്നതെന്ന് അന്വേഷിക്കാൻ ഇബ്നുഅബ്ബാസ്(റ) പറഞ്ഞയച്ചതാണ്. ഇബ്നു ഹുനൈൻ(റ) പറയുന്നു: അബൂഅയ്യൂബ്(റ) തന്റെ കൈ വസ്ത്രത്തിൽ വെച്ച് അദ്ദേഹത്തിന്റെ തല കാണുംവിധത്തിൽ താഴ്ത്തി. വെള്ളം ഒഴിച്ചുകൊടുക്കുന്ന ആളോട് വെള്ളം ചൊരിക്കാനാവശ്യപ്പെട്ടു. അയാൾ അദ്ദേഹത്തിന്റെ തലയിൽ വെള്ളമൊഴിച്ചു. അദ്ദേഹം തന്റെ കൈ കൊണ്ട് തല ചലിപ്പിക്കുകയും മുന്നോട്ടും പിന്നോട്ടും ചലിപ്പിക്കുകയും ചെയ്തു. പിന്നെയദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ) ഇപ്രകാരം ചെയ്യുന്നത് ഞാൻ കണ്ടിട്ടുണ്ട്. (ബു,മു,ദ,ന,ജ)', 'عَبْدِ اللَّهِ بْنِ حُنَيْنٍ', 'അബ്ദുല്ല ബിൻ ഹുനൈൻ(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 300, 300, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 183, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا، عَنْ أُخْتِهِ حَفْصَةَ قَالَتْ: قُلْتُ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَا رَسُولَ اللَّهِ، مَا شَأْنُ النَّاسِ حَلُّوا وَلَمْ تَحِلَّ مِنْ عُمْرَتِكَ؟ قَالَ: "إِنِّي لَبَّدْتُ رَأْسِي وَقَلَّدْتُ هَدْيِي، فَلَا أُحِلُّ حَتَّى أُحِلَّ مِنَ الْحَجِّ". (ق,د,ن,جه)', 'ഇബ്നുഉമർ(റ) അവരുടെ സഹോദരി ഹഫ്സ(റ)യിൽ നിന്ന് നിവേദനം ചെയ്യുന്നു: അവർ റസൂൽ(സ)യോട് ചോദിച്ചു: റസുലേ, ജനങ്ങളെല്ലാം ഉംറയിൽ നിന്ന് തഹല്ലുലായി, അങ്ങെന്താണ് തഹല്ലുലാവാത്തത്? റസൂൽ(സ) പറഞ്ഞു: "ഞാനെന്റെ തല ഒട്ടിക്കുകയും, വാൾ ഉറയിലിടുകയും ചെയ്തു. ഇനി ബലി അറുത്തതിന് ശേഷമേ ഞാൻ തഹല്ലുലാവുകയുള്ളു." (ബു,മു,ദ,ന,ജ)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 300, 301, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 184, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُهِلُّ مُلَبِّدًا. (خ,ن)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) തലമുടി കെട്ടി ഇഹ്റാം ചെയ്യുന്നത് ഞാൻ കണ്ടു. (ബു,ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 301, 301, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 185, 'عَنْ يَعْلَى بْنِ أَبِي أُمَيَّةَ رَضِيَ اللهُ عَنْهُ أَنَّهُ قَالَ لِعُمَرَ رَضِيَ اللَّهُ عَنْهُ: أَرِنِي النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ يُوحَى إِلَيْهِ. قَالَ: فَبَيْنَمَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالْجِعْرَانَةِ وَمَعَهُ نَفَرٌ مِنْ أَصْحَابِهِ جَاءَهُ رَجُلٌ فَقَالَ: يَا رَسُولَ اللَّهِ،كَيْفَ تَرَى فِي رَجُلٍ أَحْرَمَ بِعُمْرَةٍ وَهُوَ مُتَضَمِّخٌ بِطِيبٍ؟ فَسَكَتَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَاعَةً فَجَاءَهُ الْوَحْيُ، فَأَشَارَ عُمَرُ رَضِيَ اللهُ عَنْهُ إِلَيَّ، فَجِئْتُ وَعَلَى رَأْسِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثَوْبٌ قَدْ أُظِلَّ بِهِ، فَأَدْخَلَ رَأْسَهُ فَإِذَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُحْمَرُّ الْوَجْهِ وَهُوَ يَغِطُّ ثُمَّ سُرِّيَ عَنْهُ، فَقَالَ: "أَيْنَ الَّذِي سَأَلَ عَنِ الْعُمْرَةِ؟". فَأُتِيَ بِرَجُلٍ فَقَالَ: "اغْسِلِ الطِّيبَ الَّذِي بِكَ ثَلَاثَ مَرَّاتٍ، وَانْزِعْ عَنْكَ الْجُبَّةَ، وَاصْنَعْ فِي عُمْرَتِكَ،كَمَا تَصْنَعُ فِي حَجَّتِكَ". (خ)', 'യഅ്‌ലാ ബിൻഅബീഉമയ്യ(റ): അദ്ദേഹം ഉമർ(റ)വിനോട് പറഞ്ഞു: വഹ്‌യ് നൽകപ്പെടുന്ന റസൂൽ(സ)യുടെ അവസ്ഥ എനിക്ക് കാണിച്ചു തരണം. ഉമർ(റ) പറഞ്ഞു: റസൂൽ(സ) ഒരുപറ്റം അനചരന്മാരോടൊപ്പം ജിഅ്റാനയിൽ ഇരിക്കുമ്പോൾ ഒരാൾ വന്ന് ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, സുഗന്ധം പുശിയവനായി ഉംറക്ക് ഇഹ്റാം ചെയ്തയാളെപ്പറ്റി എന്താണഭിപ്രായം? റസൂൽ(സ) അൽപ സമയം നിശ്ശബ്ദനായി. അപ്പോൾ വഹ്‌യ് ഇറക്കപ്പെട്ടു. ഉമർ(റ) എനിക്കത് കാണിച്ചുതന്നു. റസൂൽ(സ)യുടെ തലയിൽ തണലിനായിട്ട് ഒരു വസ്ത്രമുണ്ടായിരുന്നു. ഞാൻ ചെന്ന് എന്റെ തലയും അതിൽ പ്രവേശിപ്പിച്ചു. ചുവന്ന മുഖവുമായി റസൂൽ(സ) ശ്വാസം വലിച്ച് ശബ്ദമുണ്ടാക്കുന്നുണ്ടായിരുന്നു. പിന്നെയത് (പ്രയാസം) നീങ്ങി. റസൂൽ(സ) ചോദിച്ചു: "ഉംറയെപ്പറ്റി ചോദിച്ചവനെവിടെ?" അപ്പോൾ ഒരാൾ വന്നു. റസൂൽ(സ) പറഞ്ഞു: "നീ നിന്റെ മേലുള്ള സുഗന്ധം മുന്നു തവണ കഴുകുക. ജുബ്ബ അഴിക്കുക. ഹജ്ജിൽ ചെയ്യുന്നത് ഉംറയിലും ചെയ്യുക." (ബു)', 'يَعْلَى بْنِ أَبِي أُمَيَّةَ', 'യഅ്‌ലാ ബിൻഅബീഉമയ്യ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 301, 301, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 186, 'عَنْ يَعْلَى بْنِ أَبِي أُمَيَّةَ رَضِيَ اللهُ عَنْهُ قَالَ: جَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ بِالْجِعْرَانَةِ عَلَيْهِ جُبَّةٌ وَعَلَيْهَا خَلُوقٌ، أَوْ قَالَ: أَثَرُ صُفْرَةٍ فَقَالَ: كَيْفَ تَأْمُرُنِي أَنْ أَصْنَعَ فِي عُمْرَتِي؟ قَالَ: وَأُنْزِلَ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْوَحْيُ، فَسُتِرَ بِثَوْبٍ، وَكَانَ يَعْلَى يَقُولُ: وَدِدْتُ أَنِّي أَرَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَقَدْ نَزَلَ عَلَيْهِ الْوَحْيُ، قَالَ: فَقَالَ: أَيَسُرُّكَ أَنْ تَنْظُرَ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَقَدْ أُنْزِلَ عَلَيْهِ الْوَحْيُ؟ قَالَ: فَرَفَعَ عُمَرُ طَرَفَ الثَّوْبِ فَنَظَرْتُ إِلَيْهِ لَهُ غَطِيطٌ، قَالَ: وَأَحْسَبُهُ قَالَ: كَغَطِيطِ الْبَكْرِ. قَالَ: فَلَمَّا سُرِّيَ عَنْهُ قَالَ: "أَيْنَ السَّائِلُ عَنِ الْعُمْرَةِ؟ اغْسِلْ عَنْكَ أَثَرَ الصُّفْرَةِ- أَوْ قَالَ: أَثَرَ الْخَلُوقِ- وَاخْلَعْ عَنْكَ جُبَّتَكَ، وَاصْنَعْ فِي عُمْرَتِكَ مَا أَنْتَ صَانِعٌ فِي حَجِّكَ". (ق,د,ت,ن)', 'യഅ്‌ലാ ബിൻഅബീഉമയ്യ(റ): ഖലൂഖ് പുരട്ടിയ അല്ലെങ്കിൽ മഞ്ഞച്ചായം പൂശിയ ജുബ്ബയണിഞ്ഞ ഒരാൾ ജിഅ്റാനയിൽ വെച്ച് റസൂൽ(സ)യെ സമീപിച്ചു. അയാൾ ചോദിച്ചു: എന്റെ ഉംറയിൽ ഞാനെന്താണ് ധരിക്കേണ്ടത്? യഅ്‌ല പറയുന്നു: റസൂൽ(സ)ക്ക് വഹ്‌യ് ഇറക്കപ്പെട്ടു. ഒരു വസ്ത്രം കൊണ്ട് മറക്കപ്പെട്ടു. യഅ്‌ല(റ) പറയുമായിരുന്നു: റസൂൽ(സ)ക്ക് വഹ്‌യ് ഇറക്കപ്പെടുന്നത് കാണാൻ ഞാനാഗ്രഹിച്ചു.നിവേദകൻ പറയുന്നു: ഉമർ(റ) ചോദിച്ചു: റസൂൽ(സ)ക്ക് വഹ്‌യ് ഇറക്കപ്പെടുന്നത് കാണാൻ നിനക്ക് താത്പര്യമുണ്ടോ? ഉമർ(റ) ആ വസ്ത്രത്തിന്റെ അറ്റം ഉയർത്തി. ഞാൻ റസൂൽ(സ)യിലേക്ക് നോക്കിയപ്പോൾ ഗദ്ഗദമുണ്ടായിരുന്നു. നിവേദകൻ പറയുന്നു: റിപ്പോർട്ടർ പറഞ്ഞതായി തോന്നുന്നു: ചെറിയ ഒട്ടകത്തിന്റെ കൂർക്കം വലിപോലെ. അതിനു ശേഷം റസൂൽ(സ) ചോദിച്ചു: "ഉംറയെപ്പറ്റി ചോദിച്ചവനെവിടെ? മഞ്ഞച്ചായത്തിന്റെ അല്ലെങ്കിൽ ഖലൂഖിന്റെ അടയാളം കഴുകുക. ജുബ്ബ അഴിക്കുക. ഹജ്ജിൽ ചെയ്യുന്നത് ഉംറയിലും ചെയ്യുക." (ബു,മു,ദ,തു,ന)', 'يَعْلَى بْنِ أَبِي أُمَيَّةَ', 'യഅ്‌ലാ ബിൻഅബീഉമയ്യ(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 301, 302, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 187, 'عَنْ يَعْلَى بْنِ أَبِي أُمَيَّةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَجُلًا أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَقَدْ أَهَلَّ بِعُمْرَةٍ، وَعَلَيْهِ مُقَطَّعَاتٌ، وَهُوَ مُتَضَمِّخٌ بِخَلُوقٍ، فَقَالَ: أَهْلَلْتُ بِعُمْرَةٍ، فَمَا أَصْنَعُ؟ فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَا كُنْتَ صَانِعًا فِي حَجِّكَ". قَالَ: كُنْتُ أَتَّقِي هَذَا وَأَغْسِلُهُ. فَقَالَ: "مَا كُنْتَ صَانِعًا فِي حَجِّكَ فَاصْنَعْهُ فِي عُمْرَتِكَ". (ن)', 'യഅലാ ബിൻ അബീ ഉമയ്യ(റ): ഉംറക്ക് ഇഹ്റാം ചെയ്ത ഒരാൾ റസൂൽ(സ)യെ സമീപിച്ചു. അയാളുടെ മേൽ തുണിക്കഷ്ണങ്ങളുണ്ടായിരുന്നു. ഖലൂഖ് (ഒരുതരം സുഗന്ധം) പൂശിയിട്ടുണ്ട്. അദ്ദേഹം ചോദിച്ചു: ഞാൻ ഉംറക്ക് ഇഹ്റാം ചെയ്തിട്ടുണ്ട്, എന്താണ് ചെയ്യേണ്ടത്? റസൂൽ(സ) ചോദിച്ചു: "നീ എന്താണ് ഹജ്ജിൽ ചെയ്തിരുന്നത്?" അയാൾ പറഞ്ഞു: ഞാൻ ഈ തുണിക്കഷ്ണം ഒഴിവാക്കി, സുഗന്ധം കഴുകും. റസൂൽ(സ) പറഞ്ഞു: "ഹജ്ജിൽ ചെയ്യുന്നത് ഉംറയിലും ചെയ്യുക." (ന)', 'يَعْلَى بْنِ أَبِي أُمَيَّةَ', 'യഅലാ ബിൻ അബീ ഉമയ്യ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 302, 302, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 188, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّهُ سَمِعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى النِّسَاءَ فِي إِحْرَامِهِنَّ عَنِ الْقُفَّازَيْنِ وَالنِّقَابِ، وَمَا مَسَّ الْوَرْسُ وَالزَّعْفَرَانُ مِنَ الثِّيَابِ، وَلْتَلْبَسْ بَعْدَ ذَلِكَ مَا أَحَبَّتْ مِنْ أَلْوَانِ الثِّيَابِ: مُعَصْفَرًا، أَوْ خَزًّا، أَوْ حُلِيًّا، أَوْ سَرَاوِيلَ، أَوْ قَمِيصًا، أَوْ خُفًّا. (د)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): ഇഹ്റാമിൽ മുഖംമുടിയും കാലുറയും കുങ്കുമവും മഞ്ഞക്കളറുമുള്ള വസ്ത്രവും ധരിക്കുന്നതിൽ നിന്നും സ്ത്രീകളെ റസൂൽ(സ) വിലക്കുന്നതായി അദ്ദേഹം കേട്ടു. അതിനുശേഷമവർക്ക് ഇഷ്ടപ്പെടുന്ന വസ്ത്രം ധരിക്കാം. പട്ടോ, മഞ്ഞയോ ആഭരണമോ പാന്റ്സോ നീളൻ കുപ്പായമോ ഖുഫ്ഫയോ ധരിക്കാം. (ദ)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 302, 302, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 189, 'عَنْ عَبْدِاللَّهِ بْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: انْطَلَقَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنَ الْمَدِينَةِ بَعْدَ مَا تَرَجَّلَ وَادَّهَنَ وَلَبِسَ إِزَارَهُ وَرِدَاءَهُ هُوَ وَأَصْحَابُهُ، فَلَمْ يَنْهَ عَنْ شَيْءٍ مِنَ الْأَرْدِيَةِ وَالْأُزُرِ تُلْبَسُ إِلَّا الْمُزَعْفَرَةَ الَّتِي تَرْدَعُ عَلَى الْجِلْدِ، فَأَصْبَحَ بِذِي الْحُلَيْفَةِ، رَكِبَ رَاحِلَتَهُ حَتَّى اسْتَوَى عَلَى الْبَيْدَاءِ، أَهَلَّ هُوَ وَأَصْحَابُهُ وَقَلَّدَ بَدَنَتَهُ، وَذَلِكَ لِخَمْسٍ بَقِينَ مِنْ ذِي الْقَعْدَةِ فَقَدِمَ مَكَّةَ لِأَرْبَعِ لَيَالٍ خَلَوْنَ مِنْ ذِي الْحَجَّةِ، فَطَافَ بِالْبَيْتِ وَسَعَى بَيْنَ الصَّفَا وَالْمَرْوَةِ وَلَمْ يَحِلَّ مِنْ أَجْلِ بُدْنِهِ، لِأَنَّهُ قَلَّدَهَا، ثُمَّ نَزَلَ بِأَعْلَى مَكَّةَ عِنْدَ الْحَجُونِ وَهُوَ مُهِلٌّ بِالْحَجِّ، وَلَمْ يَقْرَبِ الْكَعْبَةَ بَعْدَ طَوَافِهِ بِهَا حَتَّى رَجَعَ مِنْ عَرَفَةَ، وَأَمَرَ أَصْحَابَهُ أَنْ يَطَّوَّفُوا بِالْبَيْتِ وَبَيْنَ الصَّفَا وَالْمَرْوَةِ ثُمَّ يُقَصِّرُوا مِنْ رُءُوسِهِمْ، ثُمَّ يَحِلُّوا وَذَلِكَ لِمَنْ لَمْ يَكُنْ مَعَهُ بَدَنَةٌ قَلَّدَهَا، وَمَنْ كَانَتْ مَعَهُ امْرَأَتُهُ فَهِيَ لَهُ حَلَالٌ وَالطِّيبُ وَالثِّيَابُ. (خ)', 'അബ്ദുല്ല ബിൻ അബ്ബാസ്(റ): ചെരുപ്പണിഞ്ഞ്, എണ്ണയിട്ട്, മേൽതട്ടവും തുണിയും ധരിച്ച് റസൂൽ(സ)യും അനുചരന്മാരും മദീനയിൽ നിന്ന് പുറപ്പെട്ടു. വസ്ത്രമായി ഉപയോഗിക്കുന്ന മേൽതട്ടം, തുണി എന്നിവയിൽ തോലിൽ കുങ്കുമ വർണ്ണം പുശിയതല്ലാത്ത ഒന്നും റസൂൽ(സ) നിരോധിച്ചില്ല. ദുൽഹുലൈഫയിൽ നിന്ന് നേരംപുലർന്നു. ബൈദാഅ് വരെ വാഹനത്തിലിരുന്നു അവർ സഞ്ചരിച്ചിരുന്നത്. റസൂൽ(സ)യും അനുചരന്മാരും അവിടെവെച്ച് ഇഹ്റാം ചെയ്തു. തന്റെ ഒട്ടകത്തിന് അടയാളം വെച്ചു. ദുൽഖഅദ 25നായിരുന്നു അത്. ദുൽഹിജ്ജ നാലിന് മക്കയിൽ വന്നു. കഅ്ബ ത്വവാഫ് ചെയ്തു, സ്വഫാ മർവ്വകൾക്കിടയിൽ സഅ്‌യ് ചെയ്തു. ഹദ്‌യ മൃഗമുള്ളതിനാൽ തഹല്ലുലായില്ല. കാരണം, അതിന് അടയാളം വെച്ചിരുന്നു. ശേഷം ഹജ്ജിന് ഇഹ്റാം ചെയ്ത് മക്കയുടെ ഉയർന്ന പ്രദേശമായ ഹജൂനിൽ ഇറങ്ങി. പിന്നെ അറഫയിൽ നിന്നു മടങ്ങും വരെ ത്വവാഫ് ചെയ്തില്ല. അനുചരന്മാരോട് ത്വവാഫ് ചെയ്യാനും, സ്വഫാമർവ്വക്കിടയിൽ സഅ്‌യ് ചെയ്യാനും മുടി വെട്ടാനും കല്പിച്ചു. അടയാളമിട്ട ഒട്ടകമില്ലെങ്കിൽ തഹല്ലുലാവുക, ഭാര്യ കൂടെയുള്ളവർക്ക് ബന്ധപ്പെടാം. സുഗന്ധവും വസ്ത്രവും ധരിക്കാമെന്നും റസൂൽ(സ) കൽപിച്ചു. (ബു)', 'عَبْدِاللَّهِ بْنِ عَبَّاسٍ', 'അബ്ദുല്ല ബിൻ അബ്ബാസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 302, 303, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 190, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: سَأَلَ رَجُلٌ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا يَتْرُكُ الْمُحْرِمُ مِنَ الثِّيَابِ؟ فَقَالَ: "لَا يَلْبَسُ الْقَمِيصَ، وَلَا الْبُرْنُسَ، وَلَا السَّرَاوِيلَ، وَلَا الْعِمَامَةَ، وَلَا ثَوْبًا مَسَّهُ وَرْسٌ وَلَا زَعْفَرَانٌ، وَلَا الْخُفَّيْنِ، إِلَّا لِمَنْ لَا يَجِدُ النَّعْلَيْنِ، فَمَنْ لَمْ يَجِدِ النَّعْلَيْنِ فَلْيَلْبَسِ الْخُفَّيْنِ، وَلْيَقْطَعْهُمَا حَتَّى يَكُونَا أَسْفَلَ مِنَ الْكَعْبَيْنِ". وفي رواية: "وَلَا تَنْتَقِبُ الْمَرْأَةُ الْحَرَامُ- وفي رواية: الْمُحْرِمَةُ لَا تَنْتَقِبُ- وَلَا تَلْبَسُ الْقُفَّازَيْنِ". (ق,د,ت,ن)', 'അബ്ദുല്ല ബിൻ ഉമർ(റ): ഒരാൾ റസൂൽ(സ)യോട് ചോദിച്ചു: മുഹ്‌രിം ഏതു വസ്ത്രമാണ് ഉപേക്ഷിക്കേണ്ടത്? റസൂൽ(സ) പറഞ്ഞു: "നീളക്കുപ്പായം, തൊപ്പി, പാന്റ്സ്, തലപ്പാവ്, കുങ്കുമമോ പട്ടോ സ്പർശിച്ച വസ്ത്രം, ഖുഫ്ഫ എന്നിവ ധരിക്കരുത്. ചെരിപ്പ് കിട്ടാത്തവൻ ഖുഫ്ഫ ധരിക്കട്ടെ. അതുരണ്ടും മുറിച്ച് ഞെരിയാണിക്ക് താഴെയാക്കണം." മറ്റൊരു നിവേദനത്തിൽ: "മുഹ്‌രിമായ സ്ത്രീ മുഖംമൂടി ധരിക്കരുത്." മറ്റൊരു നിവേദനത്തിൽ: മുഹ്‌രിമതായ സ്ത്രീ മുഖംമൂടി ധരിക്കുകയോ കയ്യുറ ധരിക്കുകയോ ചെയ്യരുത്. (ബു,മു,ദ,തു,ന)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ല ബിൻ ഉമർ(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 303, 303, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=4 and h.hadith_no=190), 1, 'وَفِي رِوَايَةٍ: "وَلَا تَنْتَقِبُ الْمَرْأَةُ الْحَرَامُ-', 'മറ്റൊരു നിവേദനത്തിൽ: "മുഹ്‌രിമായ സ്ത്രീ മുഖംമൂടി ധരിക്കരുത്."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=4 and h.hadith_no=190), 2, 'وَفِي رِوَايَةٍ: الْمُحْرِمَةُ لَا تَنْتَقِبُ- وَلَا تَلْبَسُ الْقُفَّازَيْنِ". (ق,د,ت,ن)', 'മറ്റൊരു നിവേദനത്തിൽ: മുഹ്‌രിമതായ സ്ത്രീ മുഖംമൂടി ധരിക്കുകയോ കയ്യുറ ധരിക്കുകയോ ചെയ്യരുത്. (ബു,മു,ദ,തു,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 191, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّهُ وَجَدَ الْقُرَّ، فَقَالَ: أَلْقِ عَلَيَّ ثَوْبًا يَا نَافِعُ. فَأَلْقَيْتُ عَلَيْهِ بُرْنُسًا، فَقَالَ: تُلْقِي عَلَيَّ هَذَا وَقَدْ نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يَلْبَسَهُ الْمُحْرِمُ؟. (خ,د,ن)', 'ഇബ്നു ഉമർ(റ): അദ്ദേഹത്തിന് തണുപ്പനുഭവപ്പെട്ടു. അദ്ദേഹം പറഞ്ഞു: നാഫിഅ്, എനിക്കുമേൽ വ്സത്രമിടു. ഞാൻ അദ്ദേഹത്തിന് ശിരോവസ്ത്രമിട്ടു കൊടുത്തു. ഇബ്നുഉമർ(റ) പറഞ്ഞു: മുഹ്‌രിം ധരിക്കുന്നത് റസൂൽ(സ) വിലക്കിയ വ്സത്രമാണോ നീയെന്നെ ധരിപ്പിക്കുന്നത്? (ബു,ദ,ന)', 'ابْنِ عُمَرَ', 'ഇബ്നു ഉമർ(റ)', null, null, array['خ','د','ن']::text[], array['ബു','ദ','ന']::text[], null, null, 303, 303, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 192, 'عَنْ يَعْلَى بْنِ أَبِي أُمَيَّةَ رَضِيَ اللهُ عَنْهُ قَالَ: رَأَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَعْرَابِيًّا قَدْ أَحْرَمَ وَعَلَيْهِ جُبَّةٌ، فَأَمَرَهُ أَنْ يَنْزِعَهَا. (ق,ت)', 'യഅ്‌ലാ ബിൻ അബീ ഉമയ്യ(റ): ജുബ്ബ ധരിച്ച് ഇഹ്റാം ചെയ്യുന്ന ഒരു അഅ്റാബിയെ റസൂൽ(സ) കണ്ടു. അയാളോട് അത് അഴിക്കാൻ റസൂൽ(സ) കല്പിച്ചു. (ബു,മു,തു)', 'يَعْلَى بْنِ أَبِي أُمَيَّةَ', 'യഅ്‌ലാ ബിൻ അബീ ഉമയ്യ(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 303, 304, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 193, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يَخْطُبُ يَقُولُ: "السَّرَاوِيلُ لِمَنْ لَمْ يَجِدِ الْإِزَارَ، وَالْخُفَّانِ- وفي رواية: وَالْخُفُّ- لِمَنْ لَمْ يَجِدِ النَّعْلَيْنِ". يَعْنِي الْمُحْرِمَ. (م)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) പ്രസംഗ വേളയിൽ പറയുന്നതായി ഞാൻ കേട്ടു: "തുണി ലഭിക്കാത്തവന്നാണ് പാന്റ്സ്. ചെരിപ്പ് ലഭിക്കാത്തവന്നാണ് ഖുഫ്ഫ." അഥവാ മുഹ്‌രിമിന്. (മു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 304, 304, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=4 and h.hadith_no=193), 1, 'وَفِي رِوَايَةٍ: وَالْخُفُّ- لِمَنْ لَمْ يَجِدِ النَّعْلَيْنِ". يَعْنِي الْمُحْرِمَ. (م)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 194, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: كَانَ يَصْنَعُ ذَلِكَ يَعْنِي يَقْطَعُ الْخُفَّيْنِ لِلْمَرْأَةِ الْمُحْرِمَةِ. ثُمَّ حَدَّثَتْهُ صَفِيَّةُ بِنْتُ أَبِي عُبَيْدٍ: أَنَّ عَائِشَةَ حَدَّثَتْهَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَدْ كَانَ رَخَّصَ لِلنِّسَاءِ فِي الْخُفَّيْنِ، فَتَرَكَ ذَلِكَ. (د)', 'അബ്ദുല്ല ബിൻ ഉമർ(റ): ഇഹ്റാം ചെയ്ത സ്ത്രീക്കു വേണ്ടി അദ്ദേഹം ഖുഫ്ഫ മുറിച്ചിരുന്നു. പിന്നെ സ്വഫിയ്യ(റ) ഇബ്നുഉമർ(റ)വിനോട് പറഞ്ഞു: സ്ത്രീകളുടെ ഖുഫ്ഫയുടെ കാര്യത്തിൽ റസൂൽ(സ) ഇളവനുവദിച്ചിരുന്നു എന്ന് ആഇശ(റ) എന്നോട് പറഞ്ഞിട്ടുണ്ട്. അങ്ങനെ അദ്ദേഹമത് ഉപേക്ഷിച്ചു. (ദ)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ല ബിൻ ഉമർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 304, 304, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 195, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "الْمُحْرِمُ إِذَا لَمْ يَجِدِ الْإِزَارَ فَلْيَلْبَسِ السَّرَاوِيلَ، وَإِذَا لَمْ يَجِدِ النَّعْلَيْنِ فَلْيَلْبَسِ الْخُفَّيْنِ". (ق,ت)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) പറയുന്നതായി ഞാൻ കേട്ടു: "മുഹ്‌രിം തുണി ലഭിച്ചില്ലെങ്കിൽ പാന്റ്സ് ധരിക്കട്ടെ. ചെരുപ്പ് ലഭിച്ചില്ലെങ്കിൽ ഖുഫ്ഫ ധരിക്കട്ടെ." (ബു,മു,തു,)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 304, 304, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 196, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذَكَرَ امْرَأَةً مِنْ بَنِي إِسْرَائِيلَ حَشَتْ خَاتَمَهَا مِسْكًا، وَالْمِسْكُ أَطْيَبُ الطِّيبِ. (م)', 'അബീസഈദുൽ ഖുദ്‌രി(റ): തന്റെ മോതിരം കസ്തൂരി കൊണ്ട് സുഗന്ധം പുശിയ ഒരു ഇസ്രാഈലീ വനിതയെക്കുറിച്ച് റസൂൽ(സ) പറഞ്ഞു: "കസ്തൂരിയാണ് സുഗന്ധങ്ങളുടെ സുഗന്ധം." (മു)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബീസഈദുൽ ഖുദ്‌രി(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 304, 304, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 197, 'عَنْ نَافِعٍ قَالَ: كَانَ ابْنُ عُمَرَ رَضِيَ اللهُ عَنْهُ إِذَا اسْتَجْمَرَ اسْتَجْمَرَ بِالْأَلُوَّةِ غَيْرَ مُطَرَّاةٍ، وَبِكَافُورٍ يَطْرَحُهُ مَعَ الْأَلُوَّةِ، ثُمَّ قَالَ: هَكَذَا كَانَ يَسْتَجْمِرُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (م)', 'നാഫിഅ്: ഇബ്നുഉമർ(റ) സുഗന്ധമുപയോഗിക്കുമ്പോൾ മുറിക്കാത്ത ഉലുവാൻ കൊണ്ടും ഉലുവാൻ എറിഞ്ഞ കാഫൂറും കൊണ്ട് പുകയിടും. ശേഷം അവർ പറഞ്ഞു: റസൂൽ(സ) ഇപ്രകാരമാണ് ചെയ്തിരുന്നത്. (മു)', 'نَافِعٍ قَالَ', 'നാഫിഅ്', null, null, array['م']::text[], array['മു']::text[], null, null, 304, 304, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 198, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ عُرِضَ عَلَيْهِ رَيْحَانٌ فَلَا يَرُدُّهُ، فَإِنَّهُ خَفِيفُ الْمَحْمِلِ طَيِّبُ الرِّيحِ". (م)', 'അബൂ ഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ആർക്കെങ്കിലും റൈഹാൻ നൽകപ്പെട്ടാൽ അവൻ അത് മടക്കരുത്. കാരണം, അത് ഭാരം കുറഞ്ഞതും സുഗന്ധവുമാണ്." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂ ഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 304, 305, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 199, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كُنَّا نَخْرُجُ مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى مَكَّةَ فَنُضَمِّدُ جِبَاهَنَا بِالسُّكِّ الْمُطَيَّبِ عِنْدَ الْإِحْرَامِ، فَإِذَا عَرِقَتْ إِحْدَانَا سَالَ عَلَى وَجْهِهَا، فَيَرَاهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَلَا يَنْهَاهَا. (د)', 'ആഇശ(റ): ഞങ്ങൾ റസൂൽ(സ)യോടൊപ്പം മക്കയിലേക്കു പുറപ്പെടും. ഇഹ്റാം വേളയിൽ ഞങ്ങളുടെ നെറ്റിയിൽ സുക്ക് എന്ന് സുഗന്ധം പുരട്ടും. ഞങ്ങളിലൊരാൾ വിയർത്താൽ അതവളുടെ മുഖത്തുകൂടെ ഒലിക്കും. റസൂൽ(സ) അത് കാണുമെങ്കിലും നിരോധിക്കാറില്ല. (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 305, 305, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 200, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: طَيَّبْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَبْلَ أَنْ يُحْرِمَ، وَيَوْمَ النَّحْرِ قَبْلَ أَنْ يَطُوفَ بِالْبَيْتِ، بِطِيبٍ فِيهِ مِسْكٌ. (ق,ت,ن)', 'ആഇശ(റ): ഞാൻ ഇഹ്റാമിനു മുമ്പും പെരുന്നാൾ ദിനത്തിൽ കഅ്ബ ത്വവാഫ് ചെയ്യുന്നതിനു മുമ്പും റസൂൽ(സ)ക്ക് കസ്തൂരിയുള്ള സുഗന്ധം പൂശിയിരുന്നു. (ബു,മു,തു,ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','ت','ن']::text[], array['ബു','മു','തു','ന']::text[], null, null, 305, 305, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 201, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: طَيَّبْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عِنْدَ إِحْرَامِهِ حِينَ أَرَادَ أَنْ يُحْرِمَ، وَعِنْدَ إِحْلَالِهِ قَبْلَ أَنْ يُحِلَّ بِيَدَيَّ. (ن)
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=4 and h.hadith_no=201), 1, 'وَفِي رِوَايَةٍ قَالَتْ: طَيَّبْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِإِحْرَامِهِ قَبْلَ أَنْ يُحْرِمَ، وَلِحِلِّهِ قَبْلَ أَنْ يَطُوفَ بِالْبَيْتِ.', 'മറ്റൊരു നിവേദനത്തിൽ: റസൂൽ(സ)യുടെ ഇഹ്റാം വേളയിലും ജംറ എറിഞ്ഞ ശേഷം കഅ്ബ ത്വവാഫ് ചെയ്യുന്നതിനു മുമ്പ് തഹല്ലുലാവുന്നതിനുവേണ്ടിയും ഞാൻ റസൂൽ(സ)ക്ക് സുഗന്ധം പൂശിക്കൊടുത്തു. (മു,ന)');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=4 and h.hadith_no=201), 2, 'وَفِي رِوَايَةٍ: وَلِحِلِّهِ حِينَ أَحَلَّ. (م,ن)', 'മറ്റൊരു നിവേദനത്തിൽ: റസൂൽ(സ)ക്ക് തഹല്ലുലാവുന്നതിനുവേണ്ടി ഞാൻ സുഗന്ധം പൂശിക്കൊടുത്തു. റസൂൽ(സ)യുടെ ഇഹ്റാം വേളയിലും ഞാൻ സുഗന്ധം പൂശിക്കൊടുത്തു. നിങ്ങളുടെ സുഗന്ധമല്ലാത്ത ഒന്ന്. അഥവാ വാസന അവശേഷിക്കാത്ത സുഗന്ധമാണ് ആഇശ(റ) ഉദ്ദേശിച്ചത്. (ന)');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=4 and h.hadith_no=201), 3, 'وَفِي رِوَايَةٍ قالت: طَيَّبْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِحُرْمِهِ حِينَ أَحْرَمَ، وَلِحِلِّهِ بَعْدَ مَا رَمَى جَمْرَةَ الْعَقَبَةِ قَبْلَ أَنْ يَطُوفَ بِالْبَيْتِ.', null);
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=4 and h.hadith_no=201), 4, 'وَفِي رِوَايَةٍ قالت: طَيَّبْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِإِحْلَالِهِ، وَطَيَّبْتُهُ لِإِحْرَامِهِ، طِيبًا لَا يُشْبِهُ طِيبَكُمْ هَذَا. تَعْنِي لَيْسَ لَهُ بَقَاءٌ. (ن)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 202, 'عَنْ عُرْوَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قُلْتُ لِعَائِشَةَ رَضِيَ اللهُ عَنْهَا: بِأَيِّ شَيْءٍ طَيَّبْتِ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ قَالَتْ: بِأَطْيَبِ الطِّيبِ عِنْدَ حُرْمِهِ وَحِلِّهِ. وفي رواية قالت: كُنْتُ أُطَيِّبُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عِنْدَ إِحْرَامِهِ بِأَطْيَبِ مَا أَجِدُ. وفي رواية قالت: كُنْتُ أُطَيِّبُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِأَطْيَبِ مَا أَجِدُ لِحُرْمِهِ وَلِحِلِّهِ، وَحِينَ يُرِيدُ أَنْ يَزُورَ الْبَيْتَ. (ن)', 'ഉർവ(റ): ഞാൻ ആഇശ(റ)യോട് ചോദിച്ചു: നിങ്ങൾ റസൂൽ(സ)ക്ക് ഏത് സുഗന്ധമാണ് പൂശിക്കൊടുത്തിരുന്നത്? ആഇശ(റ) പറഞ്ഞു: റസൂൽ(സ)യുടെ ഇഹ്റാമിലും, തഹല്ലുലിലും ഏറ്റവും മുന്തിയ സുഗന്ധമുപയോഗിച്ചായിരുന്നു ഞാൻ റസൂൽ(സ)ക്ക് സുഗന്ധം പൂശിയിരുന്നത്.
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=4 and h.hadith_no=202), 1, 'وَفِي رِوَايَةٍ قالت: كُنْتُ أُطَيِّبُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عِنْدَ إِحْرَامِهِ بِأَطْيَبِ مَا أَجِدُ.', 'മറ്റൊരു നിവേദനത്തിൽ: ലഭ്യമായതിൽ വെച്ചേറ്റവും നല്ല സുഗന്ധമുപയോഗിച്ചായിരുന്നു ഞാൻ റസൂൽ(സ)യുടെ ഇഹ്റാം വേളയിൽ സുഗന്ധം പൂശിക്കൊടുത്തിരുന്നത്.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=4 and h.hadith_no=202), 2, 'وَفِي رِوَايَةٍ قالت: كُنْتُ أُطَيِّبُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِأَطْيَبِ مَا أَجِدُ لِحُرْمِهِ وَلِحِلِّهِ، وَحِينَ يُرِيدُ أَنْ يَزُورَ الْبَيْتَ. (ن)', 'മറ്റൊരു നിവേദനത്തിൽ: റസൂൽ(സ)യുടെ ഇഹ്റാമിലും തഹല്ലുലിലും കഅ്ബാ സന്ദർശനത്തിനുദ്ദേശിക്കുമ്പോഴും ഏറ്റവും മുന്തിയ സുഗന്ധമുപയോഗിച്ചായിരുന്നു ഞാൻ റസൂൽ(സ)ക്ക് സുഗന്ധം പൂശിക്കൊടുത്തിരുന്നത്. (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 203, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يَتَزَعْفَرَ الرَّجُلُ. (ق,د,ت,ن)', 'അനസ്(റ): പുരുഷൻ കുങ്കുമം ഉപയോഗിക്കുന്നത് റസൂൽ(സ) വിലക്കിയിരിക്കുന്നു. (ബു,മു,ദ,തു,ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 306, 306, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 204, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا أَنَّهَا قَالَتْ: طَيَّبْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِإِحْرَامِهِ قَبْلَ أَنْ يُحْرِمَ، وَلِحِلِّهِ قَبْلَ أَنْ يُفِيضَ. وفي رواية: بِيَدَيَّ هَاتَيْنِ. (خ,جه)', 'ആഇശ(റ): റസൂൽ(സ)യുടെ ഇഹ്റാമിനു മുമ്പും തഹല്ലുൽ വേളയിൽ ഇഫാളത്തിന്റെ ത്വവാഫിനു മുമ്പും ഞാൻ സുഗന്ധം പൂശിക്കൊടുത്തു. മറ്റൊരു നിവേദനത്തിൽ: എന്റെ ഈ കൈകൾ കൊണ്ട്. (ബു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ','جه']::text[], array['ബു','ജ']::text[], null, null, 306, 306, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=4 and h.hadith_no=204), 1, 'وَفِي رِوَايَةٍ: بِيَدَيَّ هَاتَيْنِ. (خ,جه)', 'മറ്റൊരു നിവേദനത്തിൽ: എന്റെ ഈ കൈകൾ കൊണ്ട്. (ബു,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 205, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَأَنِّي أَنْظُرُ إِلَى وَبِيصِ الطِّيبِ فِي رَأْسِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ مُحْرِمٌ. (ق,ن)
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=4 and h.hadith_no=205), 1, 'وَفِي رِوَايَةٍ: كُنْتُ أَنْظُرُ إِلَى وَبِيصِ الطِّيبِ فِي أُصُولِ شَعْرِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ مُحْرِمٌ. (ن)', 'മറ്റൊരു നിവേദന്: ഇഹ്റാം ചെയ്ത നിലയിൽ റസൂലിന്റെ മുടിയുടെ മുരട്ടിലുള്ള സുഗന്ധം പൂശിയ അടയാളത്തിലേക്ക് ഞാൻ നോക്കുമായിരുന്നു. (ന)');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=4 and h.hadith_no=205), 2, 'وَفِي رِوَايَةٍ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا أَرَادَ أَنْ يُحْرِمَ ادَّهَنَ بِأَطْيَبِ مَا يَجِدُهُ، حَتَّى أَرَى وَبِيصَهُ فِي رَأْسِهِ. (ق,ن,جه)', 'മറ്റൊരു നിവേദന്: റസൂൽ(സ) തങ്ങൾ ഇഹ്റാം ചെയ്യാനുദ്ദേശിച്ചാൽ ലഭ്യമാകുന്നതിൽ വെച്ച് ഏറ്റവും സുഗന്ധമുള്ള വസ്തു ഉപയോഗിക്കുമായിരുന്നു. അതിന്റെ അടയാളം ശിരസ്സിൽ കാണാൻ പറ്റുമായിരുന്നു. (ബു,മു,ന,ജ)');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=4 and h.hadith_no=205), 3, 'وَفِي رِوَايَةٍ: كُنْتُ أُطَيِّبُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِأَطْيَبِ مَا كُنْتُ أَجِدُ مِنَ الطِّيبِ حَتَّى أَرَى وَبِيصَ الطِّيبِ فِي رَأْسِهِ وَلِحْيَتِهِ قَبْلَ أَنْ يُحْرِمَ. (ق,ن,جه)', 'മറ്റൊരു നിവേദന്: റസൂൽ(സ) ഇഹ്റാം ചെയ്യുന്നതിന് മുമ്പായി അവിടത്തെ താടിയിലും ശിരസ്സിലും സുഗന്ധത്തിന്റെ അടയാളം കാണും വിധത്തിൽ ഏറ്റവും വാസനയുള്ള സുഗന്ധം കൊണ്ട് ഞാൻ സുഗന്ധം പൂശിക്കൊടുക്കാറുണ്ട്. (ബു,മു,ന,ജ)');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=4 and h.hadith_no=205), 4, 'وَفِي رِوَايَةٍ: لَقَدْ رَأَيْتُ وَبِيصَ الطِّيبِ فِي مَفَارِقِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعْدَ ثَلَاثٍ. (ن)', 'മറ്റൊരു നിവേദന്: നിശ്ചയം റസൂൽ(സ) തങ്ങളുടെ ശിരസ്സിന്റെ മൂർദ്ധാവിലുള്ള സുഗന്ധത്തിന്റെ അടയാളം ഉപയോഗിച്ച മുന്ന് ദിവസങ്ങൾക്കു ശേഷവും ഞാൻ കണ്ടു. (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 206, 'عَنْ مُحَمَّدِ بْنِ الْمُنْتَشِرِ قَالَ: سَأَلْتُ ابْنَ عُمَرَ عَنِ الطِّيبِ عِنْدَ الْإِحْرَامِ؟ فَقَالَ: لَأَنْ أَطَّلِيَ بِالْقَطِرَانِ أَحَبُّ إِلَيَّ مِنْ ذَلِكَ. فَذَكَرْتُ ذَلِكَ لِعَائِشَةَ رَضِيَ اللهُ عَنْهَا فَقَالَتْ: يَرْحَمُ اللَّهُ أَبَا عَبْدِ الرَّحْمَنِ، لَقَدْ كُنْتُ أُطَيِّبُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَيَطُوفُ فِي نِسَائِهِ ثُمَّ يُصْبِحُ يَنْضَحُ طِيبًا.
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=4 and h.hadith_no=206), 1, 'وَفِي رِوَايَةٍ: سَمِعْتُ ابْنَ عُمَرَ رَضِيَ اللهُ عَنْهُمَا يَقُولُ: لَأَنْ أُصْبِحَ مُطَّلِيًا بِقَطِرَا[?] [?]بُّ إِلَيَّ مِنْ أَنْ أُصْبِحَ مُحْرِمًا أَنْضَحُ طِيبًا. فَدَخَلْتُ عَلَى عَائِشَةَ فَأَخْبَرْتُهَا بِقَوْلِهِ، فَقَالَتْ: طَيَّبْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَطَافَ فِي نِسَائِهِ ثُمَّ أَصْبَحَ مُحْرِمًا.(ن)', 'മറ്റൊരു നിവേദന്: ഇബ്നുഉമർ(റ) പറയുന്നത് ഞാൻ കേട്ടു: സുഗന്ധം പൂശി ഇഹ്റാം ചെയ്യുന്നതിനേക്കാളെനിക്കിഷ്ടം ടാർ പൂശലാണ്. ഞാൻ ആഇശ(റ)യുടെ അടുത്ത് ചെന്നിക്കാര്യം സുചിപ്പിച്ചു. അവർ പറഞ്ഞു: ഞാൻ റസൂലിന് സുഗന്ധം പൂശിക്കൊടുക്കുകയും റസൂൽ(സ) ഭാര്യമാർക്കിടയിൽ ചുറ്റിനടക്കുകയും പ്രഭാതത്തിൽ ഇഹ്റാം ചെയ്യുകയും ചെയ്തിരുന്നു. (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 207, 'عَنْ نُبَيْهِ بْنِ وَهْبٍ قَالَ: اشْتَكَى عُمَرُ بْنُ عُبَيْدِ اللَّهِ بْنِ مَعْمَرٍ عَيْنَيْهِ، فَأَرْسَلَ إِلَى أَبَانَ بْنِ عُثْمَانَ. وَهُوَ أَمِيرُ الْمَوْسِمِ. مَا يَصْنَعُ بِهِمَا؟ قَالَ: اضْمِدْهُمَا بِالصَّبِرِ، فَإِنِّي سَمِعْتُ عُثْمَانَ رَضِيَ اللهُ عَنْهُ يُحَدِّثُ ذَلِكَ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ . (م,د,ت,ن)', 'നുബൈഹ് ബിൻ വഹബ്(റ): ഉമറുബ്നു ഉബൈദില്ലാഹിബിൻ മഅ്മറിന് തന്റെ രണ്ട് കണ്ണിന് വേദനയനുഭവപ്പെട്ടപ്പോൾ ഒരാളെ ഹജ്ജ് വേളയിലെ അമീറായിരുന്ന അബാനുബ്നു ഉസ്മാൻ(റ)വിന്റെയടുത്തേക്കയച്ചു. അദ്ദേഹത്തോട് ചോദിച്ചു. ഈ രണ്ട് കണ്ണുകളുമായി എന്തു ചെയ്യും? അബാനുബ്നു ഉസ്മാൻ(റ) പറഞ്ഞു: താങ്കൾ കറ്റുവായ നീർ ഉപയോഗിച്ചു അവ കെട്ടുക. കാരണം നബി(സ) ഇപ്രകാരം കൽപ്പിച്ചതായി ഉസ്മാൻ(റ) പറയുന്നതായി ഞാൻ കേട്ടു. (മു,ദ,തു,ന)', 'نُبَيْهِ بْنِ وَهْبٍ قَالَ', 'നുബൈഹ് ബിൻ വഹബ്(റ)', null, null, array['م','د','ت','ن']::text[], array['മു','ദ','തു','ന']::text[], null, null, 307, 307, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=52 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 208, 'عَنْ عُثْمَانَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الْمُحْرِمِ إِذَا اشْتَكَى رَأْسَهُ وَعَيْنَيْهِ: "أَنْ يُضَمِّدَهُمَا بِصَبِرٍ". (ن)', 'ഉസ്മാൻ(റ): ഇഹ്റാം ചെയ്തയാൾക്ക് കണ്ണിനും തലക്കും വേദനയനുഭവപ്പെട്ടാൽ "കൈപുള്ള ഒരുതരം ചെടിയുടെ നീര് ഉപയോഗിച്ചു കെട്ടിക്കൊള്ളാൻ" റസൂൽ(സ) കൽപ്പിച്ചു. (ന)', 'عُثْمَانَ قَالَ', 'ഉസ്മാൻ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 307, 307, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=52 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 209, 'عَنْ أُمِّ الْحُصَيْنِ قَالَتْ: حَجَجْنَا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَجَّةَ الْوَدَاعِ، فَرَأَيْتُ أُسَامَةَ وَبِلَالًا، وَأَحَدُهُمَا آخِذٌ بِخِطَامِ نَاقَةِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَالْآخَرُ رَافِعٌ ثَوْبَهُ لِيَسْتُرَهُ مِنَ الْحَرِّ، حَتَّى رَمَى جَمْرَةَ الْعَقَبَةِ. (م,د,ن)', 'ഉമ്മുൽഹുസൈൻ(റ): ഹജ്ജതുൽ വിദാഇൽ റസൂൽ(സ)യോടൊപ്പം ഞങ്ങൾ ഹജ്ജ് ചെയ്തപ്പോൾ ബിലാൽ, ഉസാമ(റ) എന്നിവരെ ഞാനവിടെ കണ്ടു. ഒരാൾ റസൂൽ(സ)യുടെ ഒട്ടകത്തിന്റെ മൂക്കുകയർ പിടിച്ചു നിൽക്കുന്നു, മറ്റെയാൾ ചൂടിൽ നിന്ന് തിരുമേനി(സ)ക്ക് തണലേകാൻ വസ്ത്രം ഉയർത്തിപ്പിടിച്ച് നിൽക്കുന്നു. ജംറത്തുൽ അഖബ എറിയുന്നതു വരെ അവരിപ്രകാരം തുടർന്നു. (മു,ദ,ന)', 'أُمِّ الْحُصَيْنِ قَالَتْ', 'ഉമ്മുൽഹുസൈൻ(റ)', null, null, array['م','د','ن']::text[], array['മു','ദ','ന']::text[], null, null, 308, 308, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 210, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ الرُّكْبَانُ يَمُرُّونَ بِنَا وَنَحْنُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُحْرِمَاتٌ، فَإِذَا حَاذَوْا بِنَا سَدَلَتْ إِحْدَانَا جِلْبَابَهَا مِنْ رَأْسِهَا عَلَى وَجْهِهَا، فَإِذَا جَاوَزْنَا كَشَفْنَاهُ. (د,جه)', 'ആഇശ(റ): ഇഹ്റാം കെട്ടിയ നിലയിൽ ഞങ്ങൾ (സ്ത്രീകൾ) റസൂൽ(സ)യോടൊപ്പം നിൽക്കവെ ഞങ്ങൾക്കരികിലൂടെ യാത്ര സംഘം വരികയുണ്ടായി. അവർ ഞങ്ങൾക്കു നേരെ എത്തിയപ്പോൾ ഓരോരുത്തരും അവരുടെ തലയിൽ നിന്നും മുഖത്തേക്ക് മൂടുപടം താഴ്ത്തിയിടുകയും, യാത്രാസംഘം പോയപ്പോൾ മുഖം വെളിവാക്കുകയും ചെയ്തു. (ദ,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 308, 308, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 211, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كُنَّا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَنَحْنُ مُحْرِمُونَ، فَإِذَا لَقِيَنَا الرَّاكِبُ أَسْدَلْنَا ثِيَابَنَا مِنْ فَوْقِ رُؤُوسِنَا، فَإِذَا جَاوَزَنَا رَفَعْنَاهَا. (د,جه)', 'ആഇശ(റ): ഞങ്ങൾ ഇഹ്റാം ചെയ്തു റസൂൽ(സ)യോടൊപ്പം നിൽക്കെ യാത്ര സംഘത്തെ കണ്ടപ്പോൾ ഞങ്ങളുടെ ശിരസ്സിന് മുകളിൽ നിന്നും വസ്ത്രം താഴ്ത്തിയിട്ടു. അവർ പോയിക്കഴിഞ്ഞപ്പോൾ ഞങ്ങളത് ഉയർത്തുകയും ചെയ്തു. (ദ,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 308, 308, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 212, 'عَنْ أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ قَالَتْ: خَرَجْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حُجَّاجًا، حَتَّى إِذَا كُنَّا بِالْعَرْجِ نَزَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَنَزَلْنَا، فَجَلَسَتْ عَائِشَةُ رَضِيَ اللهُ عَنْهَا إِلَى جَنْبِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَجَلَسْتُ إِلَى جَنْبِ أَبِي بَكْرٍ، وَكَانَتْ زِمَالَةُ أَبِي بَكْرٍ وَزِمَالَةُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَاحِدَةً مَعَ غُلَامٍ لِأَبِي بَكْرٍ، فَجَلَسَ أَبُو بَكْرٍ يَنْتَظِرُ أَنْ يَطْلُعَ عَلَيْهِ، فَطَلَعَ وَلَيْسَ مَعَهُ بَعِيرُهُ، قَالَ: أَيْنَ بَعِيرُكَ؟ قَالَ: أَضْلَلْتُهُ الْبَارِحَةَ، قَالَ: فَقَالَ أَبُو بَكْرٍ: بَعِيرٌ وَاحِدٌ تُضِلُّهُ؟ قَالَ: فَطَفِقَ يَضْرِبُهُ وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَتَبَسَّمُ وَيَقُولُ: "انْظُرُوا إِلَى هَذَا الْمُحْرِمِ مَا يَصْنَعُ". فَمَا يَزِيدُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى أَنْ يَقُولَ: "انْظُرُوا إِلَى هَذَا الْمُحْرِمِ مَا يَصْنَعُ". وَيَتَبَسَّمُ. (د,جه)', 'അസ്മാഅ് ബിൻത്അബീബക്കർ(റ): ഞങ്ങൾ റസൂൽ(സ)യോടൊപ്പം ഹാജിമാരായി പുറപ്പെട്ടു. ''അർജി''ലെത്തിയപ്പോൾ റസൂൽ(സ)യും ഞങ്ങളും ഇറങ്ങി. ആഇശ(റ) റസൂൽ(സ)യുടെ ഭാഗത്തും ഞാൻ സിദ്ധീഖ്(റ)വിന്റെ ഭാഗത്തുമായി ഇരുന്നു. റസൂൽ(സ)യുടെയും അബൂബക്കർ(റ)വിന്റെയും സാമഗ്രികൾ വഹിക്കുന്ന ഒട്ടകം ഒന്നുതന്നെയായിരുന്നു. അത് അബൂബക്കർ(റ)ന്റെ ഭൃത്യന്റെ കൂടെയായിയുരന്നു. അദ്ദേഹത്തെയും പ്രതീക്ഷിച്ചിരിക്കയായിരുന്നു അബൂബക്കർ(റ). അദ്ദേഹം വന്നെങ്കിലും കൂടെ ഒട്ടകവുമുണ്ടായിരുന്നില്ല. സിദ്ധീഖ്(റ) ചോദിച്ചു: ഒട്ടകമെവിടെ? ഭൃത്യൻ പറഞ്ഞു: അതിന്നലെ നഷ്ടപ്പെട്ടു. സിദ്ധീഖ്(റ) പറഞ്ഞു: ആകെയുള്ള ഒരു ഒട്ടകത്തെ നീ നഷ്ടപ്പെടുത്തുകയായിരുന്നോ? നിവേദനകൻ പറയുന്നു: സിദ്ധീഖ്(റ) ഇതു ചോദിച്ചു അടിക്കാൻ തുടങ്ങിയപ്പോൾ റസൂൽ(സ) പുഞ്ചിരിച്ചുകൊണ്ട് പറയുകയാണ്: "ഈ ഇഹ്റാം ചെയ്ത ആളിലേക്ക് നോക്കു, അദ്ദേഹം എന്ത് ചെയ്യുന്നുവെന്ന്?" ഈ വാ[?]ല്ലാതെ റസൂൽ(സ) മറ്റൊന്നും അധികമായി പറഞ്ഞില്ല. അവിടന്ന് പുഞ്ചിരിക്കുന്നുണ്ടായിരുന്നു. (ദ,ജ)', 'أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ قَالَتْ', 'അസ്മാഅ് ബിൻത്അബീബക്കർ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 308, 309, true from books b left join chapters c on c.book_id=b.id and c.chapter_no=55 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 213, 'عَنِ ابْنِ بُحَيْنَةَ رَضِيَ اللهُ عَنْهُ قَالَ: احْتَجَمَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ مُحْرِمٌ بِلَحْيِ جَمَلٍ فِي وَسَطِ رَأْسِهِ. (خ)', 'ഇബ്നുബുഹൈന(റ): റസൂൽ(സ) ഇഹ്റാം ചെയ്ത നിലയിൽ ശിരസ്സിന്റെ മദ്ധ്യത്തിൽ ഒട്ടകത്തിന്റെ താടിയെല്ലു കൊണ്ട് കൊമ്പ് വെച്ചു. (ബു)', 'ابْنِ بُحَيْنَةَ', 'ഇബ്നുബുഹൈന(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 309, 309, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=56 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 214, 'عَنِ ابْنِ بُحَيْنَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ احْتَجَمَ بِطَرِيقِ مَكَّةَ وَهُوَ مُحْرِمٌ وَسَطَ رَأْسِهِ. (م,ن)', 'ഇബ്നു ബുഹൈന(റ): റസൂൽ(സ) തങ്ങൾ ഇഹ്റാം ചെയ്ത് മക്കയിലേക്ക് പോകും വഴി ശിരസ്സിന്റെ മദ്ധ്യത്തിൽ കൊമ്പു വെച്ചിരുന്നു. (മു,ന)', 'ابْنِ بُحَيْنَةَ', 'ഇബ്നു ബുഹൈന(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], null, null, 309, 309, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=56 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 215, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ احْتَجَمَ وَهُوَ مُحْرِمٌ. وفي رواية: فِي رَأْسِهِ مِنْ دَاءٍ- وفي رواية: مِنْ وَجَعٍ- كَانَ بِهِ. (ق,د,ت,ن,جه)', 'ഇബ്നു അബ്ബാസ്(റ): ഇഹ്റാം ചെയ്തിരിക്കെ റസൂൽ(സ) തങ്ങൾ കൊമ്പു വെച്ചു.
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=4 and h.hadith_no=215), 1, 'وَفِي رِوَايَةٍ: فِي رَأْسِهِ مِنْ دَاءٍ-', 'മറ്റൊരു നിവേദന്: ശിരസ്സിലുള്ള ഒരു രോഗ കാരണത്താൽ അവിടന്ന് കൊമ്പു വെച്ചു.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=4 and h.hadith_no=215), 2, 'وَفِي رِوَايَةٍ: مِنْ وَجَعٍ- كَانَ بِهِ. (ق,د,ت,ن,جه)', 'മറ്റൊരു നിവേദന്: റസൂൽ(സ)ക്കനുഭവപ്പെട്ട ഒരു വേദന കാരണം കൊമ്പു വെച്ചു (ബു,മു,ദ,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 216, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ احْتَجَمَ وَهُوَ مُحْرِمٌ عَلَى ظَهْرِ الْقَدَمِ، مِنْ وَثْءٍ كَانَ بِهِ. (ن)', 'അനസ്(റ): മുഹ്‌രിമായിരിക്കെ റസൂൽ(സ) ഒരു ഉളുക്ക് സംഭവിച്ചതിനാൽ കാൽപാദത്തിന്റെ മുകളിൽ കൊമ്പു വെച്ചു. (ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 309, 309, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=56 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 217, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ احْتَجَمَ وَهُوَ صَائِمٌ مُحْرِمٌ. (جه)', 'ഇബ്നു അബ്ബാസ്(റ): നോമ്പുള്ളവരും, ഇഹ്റാം ചെയ്തവരുമായിരിക്കെ തിരുമേനി(സ) കൊമ്പു വെച്ചു. (ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നു അബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 309, 309, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=56 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 218, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ احْتَجَمَ وَهُوَ مُحْرِمٌ، عَنْ رَهْصَةٍ أَخَذَتْهُ. (جه)', 'ജാബിർ(റ): റസൂൽ(സ) ഇഹ്റാം ചെയ്തിരിക്കെ അവിടത്തെ പിടികൂടിയ ഒരു ബുദ്ധിമുട്ട് കാരണം വേണ്ടി കൊമ്പു വെച്ചു. (ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 310, 310, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=56 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 219, 'عَنْ نُبَيْهِ بْنِ وَهْبٍ: أَنَّ عُمَرَ بْنَ عُبَيْدِ اللَّهِ أَرْسَلَ إِلَى أَبَانَ بْنِ عُثْمَانَ بْنِ عَفَّانَ يَسْأَلُهُ، وَأَبَانُ يَوْمَئِذٍ أَمِيرُ الْحَاجِّ، وَهُمَا مُحْرِمَانِ: إِنِّي أَرَدْتُ أَنْ أُنْكِحَ طَلْحَةَ بْنَ عُمَرَ ابْنَةَ شَيْبَةَ بْنِ جُبَيْرٍ، فَأَرَدْتُ أَنْ تَحْضُرَ ذَلِكَ. فَأَنْكَرَ ذَلِكَ عَلَيْهِ أَبَانُ، وَقَالَ: إِنِّي سَمِعْتُ أَبِي عُثْمَانَ بْنَ عَفَّانَ يَقُولُ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا يَنْكِحُ الْمُحْرِمُ وَلَا يُنْكِحُ". وَفِي رِوَايَةٍ: "وَلَا يَخْطُبُ". (م,د,ت,ن,جه)', 'നുബൈഹുബ്നു വഹബ്(റ): ഹാജിമാരുടെ അമീറായ അബാനുബിൻ ഉസ്മാനുബ്നു അഫ്ഫാനോ(റ)ട് അന്വേഷിക്കാൻ വേണ്ടി ഉമറുബ്നു ഉബൈദില്ലഹി ആളെ അയച്ചു. ഇവർ രണ്ടു പേരും ഇഹ്റാം ചെയ്തിട്ടുണ്ട്. ത്വൽഹത്തുബ്നു ഉമറിനെക്കൊണ്ട് ശൈബത്തുബ്നു ജുബൈറിന്റെ മകളെ വിവാഹം കഴിപ്പിക്കാൻ ഉദ്ധേശിക്കുകയും താങ്കൾ അതിൽ പങ്കെടുക്കണമെന്ന് ഞാനാശിക്കുകയും ചെയ്യുന്നു (എന്ന് പറഞ്ഞായിരുന്നു ആളെ അയച്ചത്). പക്ഷെ, അബാൻ(റ) ഈ കാര്യം വിലക്കി. അദ്ദേഹം പറഞ്ഞു: നിശ്ചയം എന്റെ പിതാവ് ഉസ്മാനുബ്നു അഫ്ഫാൻ(റ) പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്. റസൂൽ(സ) പറഞ്ഞു: "ഇഹ്റാം ചെയ്തയാൾ വിവാഹം ചെയ്യാനും ചെയ്യിക്കാനും പാടില്ല." മറ്റൊരു നിവേദനം: "അവൻ വിവാഹാലോചന നടത്തരുത്." (മു,ദ,തു,ന,ജ)', 'نُبَيْهِ بْنِ وَهْبٍ', 'നുബൈഹുബ്നു വഹബ്(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 310, 310, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=57 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=4 and h.hadith_no=219), 1, 'وَفِي رِوَايَةٍ: "وَلَا يَخْطُبُ". (م,د,ت,ن,جه)', 'മറ്റൊരു നിവേദനം: "അവൻ വിവാഹാലോചന നടത്തരുത്." (മു,ദ,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 220, 'عَنْ مَيْمُونَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: تَزَوَّجَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَنَحْنُ حَلَالَانِ بِسَرِفَ. (م,د,ت)', 'മൈമൂന(റ): സരിഫിൽ വെച്ച് ഞങ്ങൾ രണ്ടു പേരും തഹല്ലുലായ അവസരത്തിലാണ് റസൂൽ(സ) എന്നെ വിവാഹം ചെയ്തത്. (മു,ദ,തു)', 'مَيْمُونَةَ', 'മൈമൂന(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], null, null, 310, 310, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=58 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 221, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تَزَوَّجَ مَيْمُونَةَ وَهُوَ مُحْرِمٌ. (ق,د,ت,ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) മുഹ്രിമായിരിക്കെ മൈമൂന(റ)യെ വിവാഹം ചെയ്തു. (ബു,മു,ദ,തു,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 310, 310, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=58 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 222, 'عَنْ سَعِيدِ بْنِ الْمُسَيَّبِ قَالَ: وَهِمَ ابْنُ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا فِي تَزْوِيجِ مَيْمُونَةَ رَضِيَ اللهُ عَنْهَا وَهُوَ مُحْرِمٌ. (د)', 'സഈദുബ്നുൽ മുസയ്യബ്(റ): റസൂൽ(സ) മുഹ്രിമായിരിക്കെ മൈമൂന(റ)യെ വിവാഹം ചെയ്തതായി ഇബ്നുഅബ്ബാസ്(റ) ഊഹിച്ചിരുന്നു. (ദ)', 'سَعِيدِ بْنِ الْمُسَيَّبِ قَالَ', 'സഈദുബ്നുൽ മുസയ്യബ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 310, 310, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=58 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 223, 'عَنْ أَبِي رَافِعٍ رَضِيَ اللهُ عَنْهُ قَالَ: تَزَوَّجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَيْمُونَةَ وَهُوَ حَلَالٌ، وَبَنَى بِهَا وَهُوَ حَلَالٌ، وَكُنْتُ أَنَا الرَّسُولَ فِيمَا بَيْنَهُمَا. (ت)', 'അബൂറാഫിഅ്(റ): മൈമൂന(റ)യെ റസൂൽ(സ) വിവാഹം ചെയ്തതും കൂടിയിരുന്നതും തഹല്ലുലായ നിലയിൽ തന്നെയാണ്. കാരണം ഞാനായിരുന്നു രണ്ട് പേർക്കുമിടയിൽ ദൂതനായി വർത്തിച്ചത്. (തു)', 'أَبِي رَافِعٍ', 'അബൂറാഫിഅ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 310, 311, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=58 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 224, 'عَنْ مَيْمُونَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تَزَوَّجَهَا وَهُوَ حَلَالٌ، وَبَنَى بِهَا حَلَالًا، وَمَاتَتْ بِسَرِفَ، وَدَفَنَّاهَا فِي الظُّلَّةِ الَّتِي بَنَى بِهَا فِيهَا. (م,د,ت)', 'മൈമൂന(റ): നിശ്ചയം അവരെ റസൂൽ(സ) വിവാഹം ചെയ്തതും, വീട്ടിൽ കൂടിയതും തഹല്ലുലായ നിലയിലാണ്. മഹതി മൃതിയടഞ്ഞത് സരിഫയിൽ വെച്ചാണ്. അവർ കൂടിപ്പാർത്ത സ്ഥലത്താണ് ഞങ്ങളവരെ മറവു ചെയ്തത്. (മു,ദ,തു)', 'مَيْمُونَةَ', 'മൈമൂന(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], null, null, 311, 311, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=58 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 225, 'عَنِ الْبَرَاءِ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ اعْتَمَرَ فِي ذِي الْقَعْدَةِ. (خ,ت)', 'ബറാഅ്(റ): നിശ്ചയം, റസൂൽ(സ) ദുൽഖഅദയിൽ ഉംറ നിർവ്വഹിച്ചു. (ബു,തു)', 'الْبَرَاءِ', 'ബറാഅ്(റ)', null, null, array['خ','ت']::text[], array['ബു','തു']::text[], null, null, 311, 311, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=59 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 226, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: لَمْ يَعْتَمِرْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عُمْرَةً إِلَّا فِي ذِي الْقَعْدَةِ. (ق,د,جه)', 'ആഇശ(റ): ദുൽഖഅദിലല്ലാതെ നബി(സ) ഉംറ നിർവ്വഹിച്ചിട്ടില്ല. (ബു,മു,ദ,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','جه']::text[], array['ബു','മു','ദ','ജ']::text[], null, null, 311, 311, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=59 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 227, 'عَنْ عُرْوَةَ قَالَ: سُئِلَ ابْنُ عُمَرَ رَضِيَ اللهُ عَنْهُمَا : فِي أَيِّ شَهْرٍ اعْتَمَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ قَالَ: فِي رَجَبٍ. فَقَالَتْ عَائِشَةُ: مَا اعْتَمَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي رَجَبٍ قَطُّ، وَمَا اعْتَمَرَ إِلَّا وَهُوَ مَعَهُ تَعْنِي: ابْنَ عُمَرَ. (ق,ت,جه)', 'ഉർവ്വ(റ): ഏതു മാസത്തിലാണ് റസൂൽ(സ) ഉംറഃ നിർവ്വഹിച്ചതെന്ന് ഇബ്നു ഉമറി(റ)നോട് ചോദിക്കപ്പെട്ടു. അദ്ദേഹം പറഞ്ഞു: റജബ് മാസത്തിൽ. ആഇശ(റ) പറയുന്നു: റജബ് മാസത്തിൽ നബി(സ) ഉംറ നിർവ്വഹിച്ചിട്ടില്ല. അദ്ദേഹത്തോടൊപ്പമല്ലാതെ റസൂൽ(സ) ഉംറ നിർവ്വഹിച്ചിട്ടുമില്ല. അദ്ദേഹമെന്നത് കൊണ്ട് ആഇശ(റ) ഉദ്ദേശിച്ചത് ഇബ്നുഉമർ(റ)വിനെയാണ്. (ജ,മു,ബു,തു)', 'عُرْوَةَ قَالَ', 'ഉർവ്വ(റ)', null, null, array['ق','ت','جه']::text[], array['ജ','മു','ബു','തു']::text[], null, null, 311, 311, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=60 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 228, 'عَنْ مُحَرِّشٍ الْكَعْبِيِّ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَرَجَ مِنَ الْجِعِرَّانَةِ لَيْلًا مُعْتَمِرًا، فَدَخَلَ مَكَّةَ لَيْلًا، فَقَضَى عُمْرَتَهُ، ثُمَّ خَرَجَ مِنْ لَيْلَتِهِ فَأَصْبَحَ بِالْجِعِرَّانَةِ كَبَائِتٍ، فَلَمَّا زَالَتِ الشَّمْسُ مِنَ الْغَدِ خَرَجَ مِنْ بَطْنِ سَرِفَ، حَتَّى جَاءَ مَعَ الطَّرِيقِ، طَرِيقِ جَمْعٍ بِبَطْنِ سَرِفَ، فَمِنْ أَجْلِ ذَلِكَ خَفِيَتْ عُمْرَتُهُ عَلَى النَّاسِ. (د,ت,ن)', 'മുഹർരിശിൽ കഅ്ബീ(റ): റസൂൽ(സ) ഒരു രാത്രി ജിഅ്റാനത്തിൽ നിന്ന് ഉംറ ചെയ്യുന്നവരായി പുറപ്പെടുകയും ആ രാത്രിയിൽ തന്നെ മക്കയിൽ പ്രവേശിച്ചു ഉംറഃ പൂർത്തീകരിക്കുകയും ചെയ്തു. പിന്നീട് അതേ രാത്രിയിൽ തന്നെ ജിഅ്റാനയിലേക്ക് പുറപ്പെട്ടു. അപ്പോൾ അവിടന്ന് ജിഅ്റാനയിൽ രാപാർത്തവരെപ്പോലെ ആയി. അടുത്ത ദിവസം ഉച്ച തിരിഞ്ഞപ്പോൾ ബത്ഹ് സരിഫയിൽ നിന്നും മക്കയിലേക്കുള്ള വഴിയിൽ പ്രവേശിച്ചു. ഇപ്രകാരം (നേരം പുലരുന്നതിനു മുമ്പ്) ചെയ്തതിനാൽ റസൂൽ(സ)യുടെ ഉംറഃയെ സംബന്ധിച്ച് ജനങ്ങൾക്ക് അവ്യക്തതയുണ്ടായി. (ദ,തു,ന)', 'مُحَرِّشٍ الْكَعْبِيِّ', 'മുഹർരിശിൽ കഅ്ബീ(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 311, 312, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=61 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 229, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَصْحَابَهُ اعْتَمَرُوا مِنَ الْجِعْرَانَةِ، فَرَمَلُوا بِالْبَيْتِ، وَجَعَلُوا أَرْدِيَتَهُمْ تَحْتَ آبَاطِهِمْ، قَدْ قَذَفُوهَا عَلَى عَوَاتِقِهِمُ الْيُسْرَى. (د)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ)യും അനുയായികളും ജിഅ്റാനയിൽ നിന്ന് ഉംറ ചെയ്തു. കഅ്ബക്ക് ചുറ്റും റംല് നടത്തം നടന്നു. വസ്ത്രത്തിന്റെ മുഖ്യഭാഗം അവർ തങ്ങളുടെ കക്ഷത്തിനടിയിലാക്കുകയും അറ്റങ്ങൾ ഇടതു ചുമലിൻ മുകളിൽ ഇടുകയും ചെയ്തു. (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 312, 312, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=61 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 230, 'عَنْ مُحَرِّشٍ الْكَعْبِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَرَجَ لَيْلًا مِنَ الْجِعِرَّانَةِ حِينَ مَشَى مُعْتَمِرًا، فَأَصْبَحَ بِالْجِعِرَّانَةِ كَبَائِتٍ، حَتَّى إِذَا زَالَتِ الشَّمْسُ خَرَجَ عَنِ الْجِعِرَّانَةِ فِي بَطْنِ سَرِفَ، حَتَّى جَامَعَ الطَّرِيقَ طَرِيقَ الْمَدِينَةِ مِنْ سَرِفَ. وَفِي رِوَايَةٍ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَرَجَ مِنَ الْجِعِرَّانَةِ لَيْلًا، كَأَنَّهُ سَبِيكَةُ فِضَّةٍ، فَاعْتَمَرَ ثُمَّ أَصْبَحَ بِهَا كَبَائِتٍ. (ن)', 'മുഹർറിശിൽ കഅ്ബി(റ): റസൂൽ(സ) ഉംറ ചെയ്യുന്നവനായി ജിഅ്റാനിൽ നിന്ന് രാത്രി പുറപ്പെട്ടു. ജിഅ്റാനിൽ രാപ്പാർത്തവരെപ്പോലെ നിന്നു. ഉച്ചതിരിഞ്ഞപ്പോൾ ബത്നു ശരിഫിലൂടെ ജിഅ്റാനിൽ നിന്ന് പുറത്തു കടന്നു. അങ്ങനെ സരിഫിലെ മദീനയിലേക്കുള്ള വഴിയിൽ എത്തി. മറ്റൊരു നിവേദനം: റസൂൽ(സ) ജിഅ്റാനിൽ നിന്ന് രാത്രി പുറപ്പെട്ടു. തിരുമേനി(സ) ഒരു വെള്ളിക്കഷ്ണത്തെ പോലെയുണ്ടായിരുന്നു. ഉംറ ചെയ്ത് അവിടെ രാപ്പാർത്തവനെപ്പോലെ കഴിച്ചുകൂട്ടി. (ന)', 'مُحَرِّشٍ الْكَعْبِيِّ', 'മുഹർറിശിൽ കഅ്ബി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 312, 312, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=61 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=4 and h.hadith_no=230), 1, 'وَفِي رِوَايَةٍ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَرَجَ مِنَ الْجِعِرَّانَةِ لَيْلًا، كَأَنَّهُ سَبِيكَةُ فِضَّةٍ، فَاعْتَمَرَ ثُمَّ أَصْبَحَ بِهَا كَبَائِتٍ. (ن)', 'മറ്റൊരു നിവേദനം: റസൂൽ(സ) ജിഅ്റാനിൽ നിന്ന് രാത്രി പുറപ്പെട്ടു. തിരുമേനി(സ) ഒരു വെള്ളിക്കഷ്ണത്തെ പോലെയുണ്ടായിരുന്നു. ഉംറ ചെയ്ത് അവിടെ രാപ്പാർത്തവനെപ്പോലെ കഴിച്ചുകൂട്ടി. (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 231, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: وَاللَّهِ مَا أَعْمَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَائِشَةَ فِي ذِي الْحِجَّةِ إِلَّا لِيَقْطَعَ بِذَلِكَ أَمْرَ أَهْلِ الشِّرْكِ، فَإِنَّ هَذَا الْحَيَّ مِنْ قُرَيْشٍ وَمَنْ دَانَ دِينَهُمْ كَانُوا يَقُولُونَ: إِذَا عَفَا الْوَبَرْ، وَبَرَأَ الدَّبَرْ، وَدَخَلَ صَفَرْ، فَقَدْ حَلَّتِ الْعُمْرَةُ لِمَنِ اعْتَمَرْ. فَكَانُوا يُحَرِّمُونَ الْعُمْرَةَ حَتَّى يَنْسَلِخَ ذُو الْحِجَّةِ وَالْمُحَرَّمُ. (ق,د)', 'ഇബ്നുഅബ്ബാസ്(റ): ബഹുദൈവാരാധകരുടെ കൽപ്പനകളെ ധിക്കരിക്കാൻ വേണ്ടിയായിരുന്നു ദുൽഹിജ്ജ മാസത്തിൽ റസൂൽ(സ) ആഇശ(റ)യെക്കൊണ്ട് ഉംറ ചെയ്യിപ്പിച്ചത്. കാരണം ഖുറൈശികളും അവരുടെ മതം പിൻപറ്റുന്നവരും പറയുമായിരുന്നു: യാത്രയുടെ ചിഹ്നങ്ങളെല്ലാം മാഞ്ഞു കഴിഞ്ഞു, ഒട്ടകത്തിന്റെ മുതുകിലെ മുറിവുണങ്ങി, സ്വഫർ സമാഗതമായി. എങ്കിൽ ഉംറ ചെയ്യാനുദ്ദേശിക്കുന്നവർക്ക് ഉംറ ചെയ്യാം. ദുൽഹിജ്ജയും മുഹർറമും കഴിയുന്നത് വരെ ഉംറ ചെയ്യൽ അവർ നിഷിദ്ധമാക്കിയിരുന്നു. (ബു,മു,ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 312, 312, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=62 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 232, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سُئِلَ عَنِ الْعُمْرَةِ، أَوَاجِبَةٌ هِيَ؟ قَالَ: "لَا، وَأَنْ تَعْتَمِرُوا هُوَ أَفْضَلُ". (ت)', 'ജാബിർ(റ): ഉംറ നിർബന്ധമാണോ എന്ന് നബി(സ)യോട് ചോദിക്കപ്പെട്ടു. അവിടന്ന് പറഞ്ഞു: "അല്ല, ഉംറ നിർവ്വഹിക്കൽ ഏറ്റവും ശ്രേഷ്ഠമായ കാര്യമാണ്." (തു)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 312, 313, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=63 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 233, 'عَنْ كَعْبِ بْنِ عُجْرَةَ: أَنَّهُ كَانَ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُحْرِمًا، فَآذَاهُ الْقَمْلُ فِي رَأْسِهِ، فَأَمَرَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يَحْلِقَ رَأْسَهُ، وَقَالَ: "صُمْ ثَلَاثَةَ أَيَّامٍ، أَوْ أَطْعِمْ سِتَّةَ مَسَاكِينَ مُدَّيْنِ مُدَّيْنِ، أَوِ انْسُكْ شَاةً، أَيَّ ذَلِكَ فَعَلْتَ أَجْزَأَ عَنْكَ". وَفِي رِوَايَةٍ قَالَ: أَحْرَمْتُ، فَكَثُرَ قَمْلُ رَأْسِي، فَبَلَغَ ذَلِكَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَتَانِي وَأَنَا أَطْبُخُ قِدْرًا لِأَصْحَابِي، فَمَسَّ رَأْسِي بِإِصْبَعِهِ فَقَالَ: "انْطَلِقْ فَاحْلِقْهُ، وَتَصَدَّقْ عَلَى سِتَّةِ مَسَاكِينَ". (ن)', 'കഅ്ബുബ്നു ഉജ്റ(റ): റസൂൽ(സ)യോടൊപ്പം ഇഹ്റാം ചെയ്തിരിക്കെ അദ്ദേഹത്തിന് ശിരസ്സിൽ പേൻ ശല്യമനുഭവപ്പെട്ടു. അദ്ദേഹത്തോട് ശിരസ്സിലെ മുടി കളയുവാൻ റസൂൽ(സ) കൽപിക്കുകയും ഇപ്രകാരം പറയുകയും ചെയ്തു: "താങ്കൾ ഇതിന് പകരമായി മൂന്ന് ദിവസം നോമ്പനുഷ്ടിക്കുകയോ, രണ്ട് മുദ്ദ് വീതം ആറു സാധുക്കൾക്ക് ഭക്ഷിപ്പിക്കുകയോ, ഒരാടിനെ അറുക്കുകയോ ചെയ്യുക. ഇതിലേത് ചെയ്താലും താങ്കൾക്ക് മതിയാകും."
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=4 and h.hadith_no=233), 1, 'وَفِي رِوَايَةٍ قَالَ: أَحْرَمْتُ، فَكَثُرَ قَمْلُ رَأْسِي، فَبَلَغَ ذَلِكَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَتَانِي وَأَنَا أَطْبُخُ قِدْرًا لِأَصْحَابِي، فَمَسَّ رَأْسِي بِإِصْبَعِهِ فَقَالَ: "انْطَلِقْ فَاحْلِقْهُ، وَتَصَدَّقْ عَلَى سِتَّةِ مَسَاكِينَ". (ن)', 'മറ്റൊരു നിവേദനത്തിൽ: അദ്ദേഹം പറയുന്നു: ഞാൻ ഇഹ്റാം ചെയ്തിരിക്കെ എന്റെ ശിരസ്സിൽ പേൻ ശല്യം വർധിച്ചു. ഈ വിവരം അറിഞ്ഞ റസൂൽ(സ) എന്റടുത്ത് വന്നപ്പോൾ ഞാനെന്റെ സംഘത്തിന് ഭക്ഷണം പാകം ചെയ്യുകയായിരുന്നു. റസൂൽ(സ) എന്റെ തലയിൽ തൊട്ടു പറഞ്ഞു: "നീ പോയി മുടി കളയുക, ആറ് സാധുക്കളെ അതിനു പകരമായി ഭക്ഷിപ്പിക്കണം." (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 234, 'عَنْ كَعْبِ بْنِ عُجْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: وَقَفَ عَلَيَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالْحُدَيْبِيَةِ، وَرَأْسِي يَتَهَافَتُ قَمْلًا، فَقَالَ: "يُؤْذِيكَ هَوَامُّكَ؟" قُلْتُ: نَعَمْ، قَالَ: "فَاحْلِقْ رَأْسَكَ". قَالَ فِيَّ نَزَلَتْ هَذِهِ الْآيَةُ: {فَمَنْ كَانَ مِنْكُمْ مَرِيضًا أَوْ بِهِ أَذًى مِنْ رَأْسِهِ}...... إِلَى آخِرِهَا، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "صُمْ ثَلَاثَةَ أَيَّامٍ أَوْ تَصَدَّقْ بِفَرَقٍ بَيْنَ سِتَّةٍ أَوِ انْسُكْ بِمَا تَيَسَّرَ". (خ)', 'കഅ്ബുബ്നു ഉജ്റ(റ): ഹുദൈബിയ്യയിൽ തിരുമേനി(സ) എന്റെ മുമ്പിൽ നിൽക്കുമ്പോൾ എന്റെ തലയിൽ നിന്നും പേൻ കൊഴിഞ്ഞു വീണു കൊണ്ടിരുന്നു. തിരുമേനി(സ) ചോദിച്ചു: "ഈ പ്രാണികൾ നിന്നെ ശല്യപ്പെടുത്തുന്നുണ്ട് അല്ലേ?" ഞാൻ പറഞ്ഞു: അതെ, തിരുമേനി(സ) അരുളി: "നിന്റെ തലമുടി വടിച്ചു കളയുക." കഅ്ബ്(റ) പറയുന്നു: ''നിങ്ങളിൽ വല്ലവനും രോഗിയായി, അല്ലെങ്കിൽ തലയിൽ വല്ല അസുഖവുമുണ്ടായി എങ്കിൽ'' എന്നു തുടങ്ങുന്ന ആയത്ത് എന്റെ കാര്യത്തിലാണ് അവതരിച്ചത്. തിരുമേനി(സ) അരുളി: "പ്രയശ്ചിത്തമായി നീ മുന്നു ദിവസത്തെ നോമ്പ് നോൽക്കുക. അല്ലെങ്കിൽ ഒരു ഫറഖ് (മൂന്നു സ്വാഅ്) ആഹാര പദാർത്ഥം ആറു പേർക്കായി ദാനം ചെയ്യുക. അല്ലെങ്കിൽ കഴിവനുസരിച്ച് ബലിയറുക്കുക." (ബു)', 'كَعْبِ بْنِ عُجْرَةَ', 'കഅ്ബുബ്നു ഉജ്റ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 313, 313, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=64 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 235, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَدَّهِنُ رَأْسَهُ بِالزَّيْتِ وَهُوَ مُحْرِمٌ، غَيْرَ الْمُقَتَّتِ. (خ,ت,جه)', 'ഇബ്നുഉമർ(റ): മുഹ്രിമായിരിക്കെ റസൂൽ(സ) സുഗന്ധമില്ലാത്ത എണ്ണ പൂശുമായിരുന്നു,. (ബു,ജ,തു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ','ت','جه']::text[], array['ബു','ജ','തു']::text[], null, null, 313, 314, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 236, 'عَنِ الْبَرَاءِ قَالَ: لَمَّا صَالَحَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَهْلَ الْحُدَيْبِيَةِ صَالَحَهُمْ عَلَى أَنْ لَا يَدْخُلُوهَا إِلَّا بِجُلْبَانِ السِّلَاحِ. فَسُئِلَ: مَا جُلْبَانُ السِّلَاحِ؟ قَالَ: "الْقِرَابُ بِمَا فِيهِ". (ق,د)', 'ബറാഅ്(റ): റസൂൽ(സ) ഹുദൈബിയ്യയിൽ വെച്ച് സന്ധി നടത്തിയപ്പോൾ ആയുധം ഉറകളിൽ നിക്ഷേപിച്ചേ മക്കയിൽ പ്രവേശിക്കാവൂ എന്ന നിബന്ധനയുണ്ടായി. അപ്പോൾ ചോദിക്കപ്പെട്ടു: എന്താണ് ''ജിൽബാനു സ്സിലാഹ്''? തിരുമേനി(സ) മറുപടി പറഞ്ഞു: "ആയുധം നിക്ഷേപിക്കുന്ന ഉറ." (ബു,മു,ദ)', 'الْبَرَاءِ قَالَ', 'ബറാഅ്(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 314, 314, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=66 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 237, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا يَحِلُّ لِأَحَدِكُمْ أَنْ يَحْمِلَ بِمَكَّةَ السِّلَاحَ". (م)', 'ജാബിർ(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "മക്കയിൽ വെച്ച് ആയുധമേന്തൽ നിങ്ങൾക്കാർക്കും അനുവദനീയമല്ല." (മു)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 314, 314, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=66 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 238, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سُئِلَ عَمَّا يَقْتُلُ الْمُحْرِمُ؟ قَالَ: "الْحَيَّةُ، وَالْعَقْرَبُ، وَالْفُوَيْسِقَةُ، وَيَرْمِي الْغُرَابَ وَلَا يَقْتُلُهُ، وَالْكَلْبُ الْعَقُورُ، وَالْحِدَأَةُ، وَالسَّبُعُ الْعَادِي". (د)', 'അബൂ സഈദുൽ ഖുദ്രി(റ): ഇഹ്റാം ചെയ്തവന് ഏതിനെയൊക്കെ കൊല്ലാം എന്ന് റസൂൽ(സ)യോട് ചോദിക്കപ്പെട്ടു. റസൂൽ(സ) പറഞ്ഞു: "പാമ്പ്, തേൾ, പ്രശ്നകാരിയായ എലി, കടിക്കുന്ന പട്ടി, പരുന്ത്, പിടിമൃഗം, കാക്കയെ എറിയാം, കൊല്ലരുത്." (ദ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂ സഈദുൽ ഖുദ്രി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 314, 314, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=67 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 239, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَيْلَةَ عَرَفَةَ الَّتِي قَبْلَ يَوْمِ عَرَفَةَ، فَإِذَا حِسُّ الْحَيَّةِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "اقْتُلُوهَا". فَدَخَلَتْ شَقَّ جُحْرٍ، فَأَدْخَلْنَا عُودًا فَقَلَعْنَا بَعْضَ الْجُحْرِ، فَأَخَذْنَا سَعَفَةً فَأَضْرَمْنَا فِيهَا نَارًا. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "وَقَاهَا اللَّهُ شَرَّكُمْ وَوَقَاكُمْ شَرَّهَا". (ن)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): അറഫാ ദിനത്തിനുമുമ്പുള്ള രാത്രിയിൽ ഞങ്ങൾ റസൂൽ(സ)യോടൊപ്പമായിരുന്നു. അപ്പോൾ ഒരു പാമ്പിന്റെ അനക്കം. റസൂൽ(സ) പറഞ്ഞു: "അതിനെ കൊല്ലുക." അപ്പോൾ അത് മാളത്തിലേക്ക് പോയി. ഞങ്ങൾ ഒരു വടിയെടുത്ത് മാളത്തിന്റെ ചില ഭാഗങ്ങൾ പൊളിച്ചു. ഞങ്ങൾ ഈത്തപ്പന എടുത്ത് തീ കൊടുത്തു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അതിന്റെ ശല്യത്തിൽ നിന്ന് നിങ്ങളെയും നിങ്ങളുടെ ശല്യത്തിൽ അതിനെയും അല്ലാഹു സംരക്ഷിച്ചിരിക്കുന്നു." (ന)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 314, 314, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=67 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 240, 'عَنْ سَعِيدِ بْنِ الْمُسَيَّبِ رَضِيَ اللهُ عَنْهُ: أَنَّ امْرَأَةً دَخَلَتْ عَلَى عَائِشَةَ رَضِيَ اللهُ عَنْهَا وَبِيَدِهَا عُكَّازٌ، فَقَالَتْ: مَا هَذَا؟ فَقَالَتْ: لِهَذِهِ الْوَزَغِ، لِأَنَّ نَبِيَّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَدَّثَنَا أَنَّهُ لَمْ يَكُنْ شَيْءٌ إِلَّا يُطْفِئُ عَلَى إِبْرَاهِيمَ عَلَيْهِ السَّلَام، إِلَّا هَذِهِ الدَّابَّةُ، فَأَمَرَنَا بِقَتْلِهَا. وَنَهَى عَنْ قَتْلِ الْجِنَّانِ إِلَّا ذَا الطُّفْيَتَيْنِ وَالْأَبْتَرَ، فَإِنَّهُمَا يَطْمِسَانِ الْبَصَرَ وَيُسْقِطَانِ مَا فِي بُطُونِ النِّسَاءِ. (ن)', 'സഈദുബ്നുൽ മുസയ്യബ്(റ): അടിഭാഗത്ത് ഇരുമ്പ് പിടിപ്പിച്ച വടിയുമായി നിൽക്കെ ആഇശ(റ)യുടെ അടുത്തേക്ക് ഒരു സ്ത്രീ കടന്നു വന്നു. ആഗത ചോദിച്ചു. ഇതെന്താണ്? ആഇശ(റ) പറഞ്ഞു: ഇത് ഈ പല്ലികൾക്കുള്ളതാണ്. കാരണം ഈ ജന്തുവല്ലാതെ ഒരു വസ്തുവം ഇബ്റാഹീം (അ)ന്റെ തീയിൽ ഊതിയിട്ടില്ലെന്ന് തിരുമേനി(സ) ഞങ്ങളോട് പറയുകയും അതിനെ കൊല്ലാൻ കൽപ്പിക്കുകയും ചെയ്തിട്ടുണ്ട്. വാൽ മുറിയൻ പാമ്പും മുതുകിൽ രണ്ട് വെളുത്ത വരകളുള്ള പാമ്പും അല്ലാത്ത ചെറിയ കറുത്ത പാമ്പുകളെ വധിക്കുന്നത് റസൂൽ(സ) വിലക്കിയിട്ടുണ്ട്. അതു രണ്ടും കാഴ്ചയെയും സ്ത്രീയുടെ ഗർഭത്തിലുള്ളതിനെയും നശിപ്പിക്കും. (ന)', 'سَعِيدِ بْنِ الْمُسَيَّبِ', 'സഈദുബ്നുൽ മുസയ്യബ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 314, 315, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=67 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 241, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لِلْوَزَغِ. فُوَيْسِقٌ، وَلَمْ أَسْمَعْهُ أَمَرَ بِقَتْلِهِ. (خ)', 'ആഇശ(റ): തിരുമേനി(സ) പല്ലിയെക്കുറിച്ച് ഉപദ്രവകാരിയെന്നു പറഞ്ഞു. എന്നാൽ അതിനെ കൊല്ലാൻ കൽപ്പിച്ചത് ഞാൻ കേട്ടിട്ടില്ല. (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 315, 315, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=67 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 242, 'عَنْ عَبْدِاللَّهِ رَضِيَ اللهُ عَنْهُ قَالَ: بَيْنَمَا نَحْنُ مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي غَار بِمِنًى إِذْ نَزَلَ عَلَيْهِ وَالْمُرْسَلَاتِ وَإِنَّهُ لَيَتْلُوهَا وَإِنِّي لَأَتَلَقَّاهَا مِنْ فِيهِ وَإِنَّ فَاهُ لَرَطْبٌ بِهَا إِذْ وَثَبَتْ عَلَيْنَا حَيَّةٌ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "اقْتُلُوهَا". فَابْتَدَرْنَاهَا فَذَهَبَتْ فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "وُقِيَتْ شَرَّكُمْ كَمَا وُقِيتُمْ شَرَّهَا". (خ)', 'അബ്ദുല്ല(റ): ഞങ്ങൾ മിനായിലെ ഒരു ഗുഹയിൽ തിരുമേനി(സ)യുടെ കുടെയിരിക്കുമ്പോഴാണ് ഖുർആനിലെ വൽമുർസലാതി എന്ന അധ്യായം അവതരിച്ചത്. തിരുമേനി(സ) അതു ഓതിക്കൊണ്ടിരിക്കുമ്പോൾ അതു കേട്ടു ഞാനും ഓതിക്കൊണ്ടിരുന്നു. തിരുമേനി(സ) അത് ഓതിക്കഴിഞ്ഞില്ല, അതിനിടക്ക് ഒരു പാമ്പ് ഞങ്ങൾക്ക് നേരെ ചാടി വീണു. തിരുമേനി(സ) അരുളി: "അതിനെ കൊല്ലുക." ഞങ്ങൾ ധൃതിയിൽ അതിനെ കൊല്ലാൻ പുറപ്പെട്ടു. അപ്പോഴേക്കും അത് പോയിക്കഴിഞ്ഞിരുന്നു. തിരുമേനി(സ) അരുളി: "നിങ്ങൾ അതിന്റെ ഉപദ്രവത്തിൽ നിന്നും രക്ഷപ്പെട്ടതു പോലെ നിങ്ങളുടെ ഉപദ്രവത്തിൽ നിന്ന് അതും രക്ഷപ്പെട്ടു." (ബു)', 'عَبْدِاللَّهِ', 'അബ്ദുല്ല(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 315, 315, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=67 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 243, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "خَمْسٌ مِنَ الدَّوَابِّ كُلُّهُنَّ فَاسِقٌ يَقْتُلُهُنَّ فِي الْحَرَمِ، الْغُرَابُ وَالْحِدَأَةُ وَالْعَقْرَبُ وَالْفَأْرَةُ وَالْكَلْبُ الْعَقُورُ". (ق)', 'ആഇശ(റ): റസൂൽ(സ) അരുളി: "ജിവികളിൽ അഞ്ചെണ്ണം ഉപദ്രവകാരികളാണ്. ഹറമിൽ വെച്ചു പോലും അവയെ കൊല്ലാം. കാക്ക, പരുന്ത്, തേൾ, എലി, കടിക്കുന്ന നായ എന്നിവയാണവ." (ബു,മു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 315, 315, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=67 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 244, 'عَنْ أَبِي قَتَادَةَ رَضِيَ اللهُ عَنْهُ قَالَ: خَرَجْتُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ زَمَنَ الْحُدَيْبِيَةِ، فَأَحْرَمَ أَصْحَابُهُ وَلَمْ أُحْرِمْ، فَرَأَيْتُ حِمَارًا فَحَمَلْتُ عَلَيْهِ وَاصْطَدْتُهُ، فَذَكَرْتُ شَأْنَهُ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَذَكَرْتُ أَنِّي لَمْ أَكُنْ أَحْرَمْتُ، وَأَنِّي إِنَّمَا اصْطَدْتُهُ لَكَ. فَأَمَرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَصْحَابَهُ أَنْ يَأْكُلُوهُ، وَلَمْ يَأْكُلْ مِنْهُ حِينَ أَخْبَرْتُهُ أَنِّي اصْطَدْتُهُ لَهُ. (ق,ن,جه)', 'അബു ഖതാദ(റ): ഹുദൈബിയ്യാ വർഷം ഞാനും റസൂൽ(സ)യോടൊപ്പം പുറപ്പെട്ടു. അപ്പോൾ റസൂൽ(സ)യുടെ അനുയായികൾ ഇഹ്റാം ചെയ്തെങ്കിലും ഞാൻ ചെയ്തില്ല. അന്നേരം ഞാനൊരു മൃഗത്തെ കാണുകയും അതിനെ വേട്ടയാടുകയും ചെയ്തു. ഈ കാര്യം ഞാൻ റസൂൽ(സ) യോട് പറഞ്ഞു. ഞാൻ ഇഹ്റാം ചെയ്തിട്ടില്ലെന്നും താങ്കൾക്ക് വേണ്ടി വേട്ടയാടിയതാണെന്നും ബോധ്യപ്പെടുത്തി. അന്നേരം റസൂൽ(സ) അനുയായികളോട് ഭക്ഷിക്കാൻ കൽപ്പിച്ചു. ഞാൻ നബി(സ)ക്ക് വേണ്ടി വേട്ട ചെയ്തതാണെന്ന് അറിയിച്ചതിനാൽ റസൂൽ(സ) അതിൽ നിന്ന് ഭക്ഷിച്ചില്ല. (ബു,മു,ന,ജ)', 'أَبِي قَتَادَةَ', 'അബു ഖതാദ(റ)', null, null, array['ق','ن','جه']::text[], array['ബു','മു','ന','ജ']::text[], null, null, 315, 316, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=67 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 245, 'عَنْ أَبِي قَتَادَةَ رَضِيَ اللهُ عَنْهُ قَالَ انْطَلَقْنَا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَامَ الْحُدَيْبِيَةِ، فَأَحْرَمَ أَصْحَابُهُ وَلَمْ أُحْرِمْ أَنَا، فَأُنْبِئْنَا بِعَدُوٍّ بِغَيْقَةَ فَتَوَجَّهْنَا نَحْوَهُمْ، فَبَصُرَ أَصْحَابِي بِحِمَارِ وَحْشٍ فَجَعَلَ بَعْضُهُمْ يَضْحَكُ إِلَى بَعْضٍ، فَنَظَرْتُ فَرَأَيْتُهُ، فَحَمَلْتُ عَلَيْهِ الْفَرَسَ فَطَعَنْتُهُ فَأَثْبَتُّهُ، فَاسْتَعَنْتُهُمْ فَأَبَوْا أَنْ يُعِينُونِي، فَأَكَلْنَا مِنْهُ، ثُمَّ لَحِقْتُ بِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَخَشِينَا أَنْ نُقْتَطَعَ أَرْفَعُ فَرَسِي شَأْوًا، وَأَسِيرُ عَلَيْهِ شَأْوًا فَلَقِيتُ رَجُلًا مِنْ بَنِي غِفَارٍ فِي جَوْفِ اللَّيْلِ، فَقُلْتُ لَهُ: أَيْنَ تَرَكْتَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: تَرَكْتُهُ بِتَعْهَنَ، وَهُوَ قَائِلٌ السُّقْيَا، فَلَحِقْتُ بِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَتَّى أَتَيْتُهُ فَقُلْتُ: يَا رَسُولَ اللَّهِ إِنَّ أَصْحَابَكَ أَرْسَلُوا يَقْرَءُونَ عَلَيْكَ السَّلَامَ وَرَحْمَةَ اللَّهِ وَبَرَكَاتِهِ وَإِنَّهُمْ قَدْ خَشُوا أَنْ يَقْتَطِعَهُمُ الْعَدُوُّ دُونَكَ، فَانْظُرْهُمْ، فَفَعَلَ، فَقُلْتُ: يَا رَسُولَ اللَّهِ إِنَّا اصَّدْنَا حِمَارَ وَحْشٍ، وَإِنَّ عِنْدَنَا فَاضِلَةً، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِأَصْحَابِهِ: "كُلُوا". وَهُمْ مُحْرِمُونَ. (خ)', 'അബൂ ഖതാദ(റ): ഹുദൈബിയ്യ സന്ധിയുടെ വർഷത്തിൽ തിരുമേനി(സ)യോടൊപ്പം മക്കയിലേക്ക് ഞങ്ങളും പോയി. ഞാനൊഴികെ തിരുമേനി(സ)യുടെ അനുചരൻമാരെല്ലാവരും ഉംറക്ക് ഇഹ്റാം കെട്ടിയിരുന്നു. അന്നേരം ഗൈഖ എന്ന സ്ഥലത്ത് ഒരു ശത്രു സംഘം താവളമടിച്ചിട്ടുണ്ടെന്ന് ഞങ്ങൾക്ക് വിവരം കിട്ടി. ഞങ്ങളിൽ ഒരു സംഘം അങ്ങോട്ടു യാത്ര തിരിച്ചു. എന്റെ സനേഹിതൻമാർ ഒരു കാട്ടുകഴുതയെ കണ്ടു. അവർ പരസ്പരം നോക്കിച്ചിരിക്കാൻ തുടങ്ങി. ആ കഴുതയെ ഞാൻ കണ്ടു. ഞാനെന്റെ കുതിരയെ അതിന്റെ നേർക്ക് ഓടിച്ചു. ഒരു കുത്തു കൊണ്ടു ഞാനതിനെ വീഴ്ത്തി. ഞാനെന്റെ കൂട്ടുകാരോട് സഹായമഭ്യർത്ഥിച്ചു. അവർ സഹായിക്കാൻ വിസമ്മതിച്ചു. ഞാൻ തന്നെ അതിന്റെ മാംസം പാകപ്പെടുത്തിയ ശേഷം ഞങ്ങളെല്ലാവരും ഭക്ഷിച്ചു. എന്നിട്ട് ഞാൻ തിരുമേനി(സ)യുടെ അടുത്തേക്ക് പോയി. തിരുമേനി(സ)യിൽ നിന്ന് ഒറ്റപ്പെട്ടുപോകുമോ എന്ന് ഞങ്ങൾ ഭയപ്പെട്ടിരുന്നു. ഞാൻ കുതിരയെ ഇടക്കിടെ വേഗത്തിലും ഇടക്കിടെ സാവധാനത്തിലും ഓടിച്ചു കൊണ്ടിരുന്നു. അർദ്ധ രാത്രി ഒരു ബനൂഗിഫാർ കാരനെ കണ്ടുമുട്ടി. നിങ്ങൾ പോരുമ്പോൾ തിരുമേനി(സ) എവിടെയെത്തി എന്നു ഞാൻ ചോദിച്ചു. അയാൾ പറഞ്ഞു: ഞാൻ പോരുമ്പോൾ തിരുമേനി(സ) തഅ്ഹനയിലെത്തിയിട്ടുണ്ട്. തിരുമേനി(സ) സുഖ്യയിൽ മദ്ധ്യാഹ്ന വിശ്രമത്തിലാണ്. എന്ന് അദ്ദേഹം പറഞ്ഞു. തിരുദുതരെ കണ്ടുമുട്ടിയപ്പോൾ ഞാൻ പറഞ്ഞു: ദൈവ ദൂതരെ, അങ്ങയുടെ അനുചരൻമാർ എന്നെ അയച്ചിരിക്കുകയാണ്. അവർ അങ്ങേക്ക് സലാം പറഞ്ഞിരിക്കുന്നു. ശത്രുക്കൾ അവരെ താങ്കളിൽ നിന്നും ഒറ്റപ്പെടുത്തിക്കളയുമോ എന്നാണവരുടെ ഭയം. അതുകൊണ്ട് അവരെ കൂടി കാത്തു നിന്നാലും. തിരുമേനി(സ) അവരെ കാത്തു നിന്നു. ഞാൻ പറഞ്ഞു: ദൈവദൂതരെ, ഞങ്ങൾ ഒരു കാട്ടുകഴുതയെ വേട്ടയാടിപ്പിടിച്ചു. അതിൽ അൽപം ഞങ്ങളുടെ അടുക്കൽ ബാക്കിയുണ്ട്. "നിങ്ങൾ തിന്നുകൊള്ളുക." എന്നു തിരുമേനി(സ) അരുചരൻമാരോടരുളി. അവരെല്ലാം ഇഹ്റാം കെട്ടിയവരായിരുന്നു. (ബു)', 'أَبِي قَتَادَةَ', 'അബൂ ഖതാദ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 316, 316, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=68 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 246, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ الصَّعْبَ بْنَ جُثَّامَةَ اللَّيْثِيِّ رَضِيَ اللهُ عَنْهُ، أَنَّهُ أَهْدَى لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِمَارًا وَحْشِيًّا وَهُوَ بِالْأَبْوَاءِ أَوْ بِوَدَّانَ فَرَدَّهُ عَلَيْهِ فَلَمَّا رَأَى مَا فِي وَجْهِهِ، قَالَ: "إِنَّا لَمْ نَرُدَّهُ عَلَيْكَ، إِلَّا أَنَّا حُرُمٌ". (خ)', 'ഇബ്നുഅബ്ബാസ്(റ): ജസാമയുടെ മകൻ സഅ്ബ് തിരുമേനി(സ)ക്ക് ഒരു കാട്ടു കഴുതയെ സമ്മാനിച്ചു. തിരുമേനി(സ) അന്ന് ''അബവാഇ''ലായിരുന്നു, അല്ലെങ്കിൽ വദ്ദാനിൽ. അപ്പോൾ അത് തിരുമേനി(സ) അദ്ദേഹത്തിന് തന്നെ തിരിച്ച് കൊടുത്തു. അന്നേരം സഅബിന്റെ മുഖത്തെ ഭാവ വ്യത്യാസം കണ്ടപ്പോൾ തിരുമേനി(സ) അരുളി: "ഞങ്ങൾ ഇഹ്റാം കെട്ടിയതു കൊണ്ട് മാത്രമാണ് നിങ്ങൾക്കിത് തിരിച്ചു തരുന്നത്." (ബു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 316, 317, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=68 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 247, 'عَنِ ابْنِ أَبِي عَمَّارٍ عَبْدِ اللهِ بْنِ عَبْدِ اللهِ الْمَكِّيِّ قَالَ: سَأَلْتُ جَابِرَ بْنَ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُمَا عَنِ الضَّبُعِ، فَأَمَرَنِي بِأَكْلِهَا، قُلْتُ: أَصَيْدٌ هِيَ؟ قَالَ: نَعَمْ. قُلْتُ: أَسَمِعْتَهُ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ قَالَ: نَعَمْ. (ن)', 'ഇബ്നു അബീഅമ്മാർ അബ്ദുല്ല ബിൻ അബ്ദുല്ലാഹിൽ മക്കീ(റ): ഞാൻ ജാബിറുബ്നു അബ്ദുല്ല(റ)വിനോട് ഉടുമ്പിനെക്കുറിച്ച് അന്വേഷിച്ചു. അദ്ധേഹമെന്നോട് അതിനെ ഭക്ഷിച്ചുകൊള്ളാൻ പറഞ്ഞു. ഞാൻ ചോദിച്ചു. അതിനെ വോട്ടയാടിയതാണെങ്കിലോ? ജാബിർ(റ) പറഞ്ഞു: എന്നാലും ഭക്ഷിക്കാവുന്നതാണ്. ഞാൻ ചോദിച്ചു. ഈ കാര്യം താങ്കൾ റസൂൽ(സ)യിൽ നിന്നും കേട്ടതാണോ? അദ്ദേഹം പറഞ്ഞു. അതെ. (ന)', 'ابْنِ أَبِي عَمَّارٍ عَبْدِ اللهِ بْنِ عَبْدِ اللهِ الْمَكِّيِّ قَالَ', 'ഇബ്നു അബീഅമ്മാർ അബ്ദുല്ല ബിൻ അബ്ദുല്ലാഹിൽ മക്കീ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 317, 317, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=68 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 248, 'عَنْ زَيْدِ بْنِ كَعْبٍ الْبَهْزِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَرَجَ يُرِيدُ مَكَّةَ وَهُوَ مُحْرِمٌ، حَتَّى إِذَا كَانُوا بِالرَّوْحَاءِ إِذَا حِمَارُ وَحْشٍ عَقِيرٌ، فَذُكِرَ ذَلِكَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "دَعُوهُ، فَإِنَّهُ يُوشِكُ أَنْ يَأْتِيَ صَاحِبُهُ". فَجَاءَ الْبَهْزِيُّ - وَهُوَ صَاحِبُهُ - إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ، صَلَّى اللَّهُ عَلَيْكَ وَسَلَّمَ شَأْنَكُمْ بِهَذَا الْحِمَارِ. فَأَمَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَبَا بَكْرٍ فَقَسَّمَهُ بَيْنَ الرِّفَاقِ، ثُمَّ مَضَى حَتَّى إِذَا كَانَ بِالْأُثَايَةِ بَيْنَ الرُّوَيْثَةِ وَالْعَرْجِ إِذَا ظَبْيٌ حَاقِفٌ فِي ظِلٍّ، وَفِيهِ سَهْمٌ، فَزَعَمَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمَرَ رَجُلًا يَقِفُ عِنْدَهُ، لَا يُرِيبُهُ أَحَدٌ مِنَ النَّاسِ حَتَّى يُجَاوِزَهُ. (ن)', 'സൈദ് ബിൻ കഅ്ബിൽ ബഹ്സീ(റ): റസൂൽ(സ) ഇഹ്റാം ചെയ്തു മക്കയിലേക്ക് പുറപ്പെട്ടു. റൗഹാഇൽ എത്തിയപ്പോൾ ഒരു കാട്ടുകഴുത കൊല്ലപ്പെട്ടു കിടക്കുന്നതു കണ്ടു. വിവരം റസൂൽ(സ)യെ ധരിപ്പിച്ചു. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "അതിനെ ഒഴിവാക്കുക, ഒരുപക്ഷെ, അതിനെ വേട്ടയാടിയവൻ വന്നേക്കും." അപ്പോൾ അതിനെ വേട്ടയാടിയ ബഹ്സി വന്നു പറഞ്ഞു: തിരുദൂതരേ, ഈ കഴുതയെ കൊണ്ട് ഇഷ്ടമുള്ളത് പ്രവർത്തിച്ചാലും. റസൂൽ(സ) അബൂബക്കർ(റ)വിനോട് അത് കൂട്ടുകാർക്കിടയിൽ വീതിച്ചു നൽകാൻ കൽപ്പിച്ചു. അവർ യാത്ര ചെയ്തു ഉസായയിൽ എത്തിയപ്പോൾ ഒരു മാൻ കിടക്കുന്നത് കണ്ടു. അതിന്റെ മേൽ അമ്പുണ്ടായിരുന്നു. റസൂൽ(സ)യും കൂട്ടരും കടന്നു പോകുവോളം അതിനെ ആർക്കും കാണിക്കാതിരിക്കാൻ ഒരാളോട് അതിന്റെ അരികിൽ നിൽക്കാൻ റസൂൽ(സ) കൽപ്പിച്ചുവെന്ന് അവർ പറയുന്നു. (ന)', 'زَيْدِ بْنِ كَعْبٍ الْبَهْزِيِّ', 'സൈദ് ബിൻ കഅ്ബിൽ ബഹ്സീ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 317, 317, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=68 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 249, 'عَنْ عَبْدِ الرَّحْمَنِ التَّيْمِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا مَعَ طَلْحَةَ بْنِ عُبَيْدِ اللَّهِ رَضِيَ اللهُ عَنْهُ وَنَحْنُ مُحْرِمُونَ، فَأُهْدِيَ لَهُ طَيْرٌ وَهُوَ رَاقِدٌ، فَأَكَلَ بَعْضُنَا وَتَوَرَّعَ بَعْضُنَا، فَاسْتَيْقَظَ طَلْحَةُ فَوَفَّقَ مَنْ أَكَلَهُ وَقَالَ: أَكَلْنَاهُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (ن)', 'അബ്ദുർറഹ്മാനിത്തയ്മീ(റ): ഞങ്ങൾ ത്വൽഹതുബ്നു ഉബൈദില്ലാ(റ)ന്റെ കൂടെയായിരുന്നു. ഞങ്ങൾ എല്ലാവരും ഇഹ്റാം ചെയ്തവരായിരുന്നു. ത്വൽഹ(റ) ഉറങ്ങിക്കൊണ്ടിരിക്കെ അവർക്ക് ആരോ പക്ഷിയെ ഹദ്യയായി നൽകി. അപ്പോൾ ഞങ്ങളിൽ ചിലർ അതു തിന്നുകയും മറ്റു ചിലർ തിന്നാതെ മാറി നിൽക്കുകയും ചെയ്തു. ത്വൽഹ(റ) ഉണർന്നപ്പോൾ തിന്നവരോടൊപ്പം ചേർന്നു. എന്നിട്ട് പറഞ്ഞു: ഞങ്ങൾ അത് തിരുമേനി(സ)യുടെ കൂടെ ഭക്ഷിച്ചിരുന്നു. (ന)', 'عَبْدِ الرَّحْمَنِ التَّيْمِيِّ', 'അബ്ദുർറഹ്മാനിത്തയ്മീ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 317, 317, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=68 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 250, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: خَرَجْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي حَجٍّ أَوْ عُمْرَةٍ، فَاسْتَقْبَلَنَا رِجْلٌ مِنْ جَرَادٍ، فَجَعَلْنَا نَضْرِبُهُ بِسِيَاطِنَا وَعِصِيِّنَا، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "كُلُوهُ، فَإِنَّهُ مِنْ صَيْدِ الْبَحْرِ". (جه)', 'അബൂഹുറൈറ(റ): ഹജ്ജിനോ ഉംറക്കോ വേണ്ടി ഞങ്ങൾ തിനുമേനി(സ)യോട് കൂടെ പുറപ്പെട്ടു. വഴിയിൽ ധാരാളം വെട്ടുകിളികളെ കണ്ടു. അപ്പോൾ ഞങ്ങൾ അവയെ പാട്ടകൊണ്ടും വടികൊണ്ടും അടിക്കാൻ തുടങ്ങി. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "നിങ്ങളവ ഭക്ഷിക്കുക. കാരണമത് കടലിലെ വേട്ടയിനത്തിൽ പെട്ടതാണ്." (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 317, 318, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=68 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 251, 'عَنْ عَبْدِ اللَّهِ بْنِ الْحَارِثِ، وَكَانَ خَلِيفَةَ عُثْمَانَ رَضِيَ اللهُ عَنْهُ عَلَى الطَّائِفِ، فَصَنَعَ لِعُثْمَانَ رَضِيَ اللهُ عَنْهُ طَعَامًا فِيهِ مِنَ الْحَجَلِ وَالْيَعَاقِيبِ وَلَحْمِ الْوَحْشِ، قَالَ: فَبَعَثَ إِلَى عَلِيِّ بْنِ أَبِي طَالِب فَجَاءَهُ الرَّسُولُ وَهُوَ يَخْبِطُ لِأَبَاعِرَ لَهُ، فَجَاءَهُ وَهُوَ يَنْفُضُ الْخَبَطَ عَنْ يَدِهِ، فَقَالُوا لَهُ: كُلْ، فَقَالَ: أَطْعِمُوهُ قَوْمًا حَلَالًا فَأَنَا حُرُمٌ. فَقَالَ عَلِيٌّ رَضِيَ اللهُ عَنْهُ: أَنْشُدُ اللَّهَ مَنْ كَانَ هَا هُنَا مِنْ أَشْجَعَ، أَتَعْلَمُونَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَهْدَى إِلَيْهِ رَجُلٌ حِمَارَ وَحْشٍ وَهُوَ مُحْرِمٌ، فَأَبَى أَنْ يَأْكُلَهُ؟ قَالُوا: نَعَمْ. (د)', 'അബ്ദുല്ലാഹിബ്നു ഹാരിസ്(റ): അദ്ദേഹം ഉസ്മാൻ(റ)വിന്റെ ത്വാഇഫിലെ ഗവർണ്ണറായിരുന്നു. അദ്ദേഹം ഉസ്മാൻ(റ)വിന് വേണ്ടി പക്ഷിമാംസവും കാട്ടുകഴുതകളുടെ മാംസവും ചേർത്ത് ഭക്ഷണമുണ്ടാക്കി. നിവേദകൻ പറയുന്നു: അത് അദ്ദേഹം അലി(റ)ന് അയച്ചു കൊടുത്തു. ദൂതൻ എത്തുമ്പോൾ അലി(റ) തന്റെ ഒട്ടകങ്ങൾക്ക് ഇലകൾ പൊഴിച്ചു കൊടുക്കുകയും ഇലകൾ വീഴാൻ വേണ്ടി മരം കുലുക്കുകയുമായിരുന്നു. അവർ അലി(റ)വിനോട് പറഞ്ഞു: അങ്ങ് തിന്നുക. അലി(റ) പറഞ്ഞു: ഞാൻ ഇഹ്റാം ചെയ്തവനാണ്. ഇഹ്റാം ചെയ്യാത്തവരെ അത് ഭക്ഷിപ്പിക്കുക. അലി(റ) പറഞ്ഞു: ഇവിടെയുള്ള അശ്ജഅ് ഗോത്രക്കാരോട് അല്ലാഹുവിന്റെ നാമത്തിൽ ആണയിട്ടു ഞാൻ ചോദിക്കുന്നു: മുഹ്രിമായിരിക്കെ റസൂൽ(സ)ക്ക് ഒരാൾ കാട്ടുകഴുതയുടെ മാംസം സമ്മാനിച്ചതും റസൂൽ(സ) അത് ഭക്ഷിക്കാൻ വിസമ്മതിച്ചതും നിങ്ങൾക്കറിയില്ലേ? അവർ പറഞ്ഞു: അതെ. (ദ)', 'عَبْدِ اللَّهِ بْنِ الْحَارِثِ، وَكَانَ خَلِيفَةَ عُثْمَانَ', 'അബ്ദുല്ലാഹിബ്നു ഹാരിസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 318, 318, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=68 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 252, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُ أَنَّهُ قَالَ: يَا زَيْدَ بْنَ أَرْقَمَ، هَلْ عَلِمْتَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أُهْدِيَ إِلَيْهِ عَضُدُ صَيْدٍ فَلَمْ يَقْبَلْهُ، وَقَالَ: "إِنَّا حُرُمٌ". قَالَ: نَعَمْ. (م,د,ن)', 'ഇബ്നുഅബ്ബാസ്(റ): ഓ, സൈദുബ്നു അർഖം, നബി(സ)ക്ക് ഒരു വേട്ടജീവിയുടെ തോളെല്ല് ദാനമായി നൽകപ്പെട്ടതും അവിടന്ന് അത് നിരസിച്ചതും "ഞങ്ങൾ ഇഹ്റാം ചെയ്തവരാണ്" എന്ന് പറഞ്ഞതും താങ്കൾക്കറിയുമോ? സൈദുബ്നു അർഖം(റ) പറഞ്ഞു: അതെ. (മു,ദ,ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['م','د','ن']::text[], array['മു','ദ','ന']::text[], null, null, 318, 318, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=68 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 253, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا، عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللهُ عَنْهُ قَالَ: أُتِيَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِلَحْمِ صَيْدٍ، وَهُوَ مُحْرِمٌ، فَلَمْ يَأْكُلْهُ. [ز: في إسناده ضعيف] (جه)', 'ഇബ്നുഅബ്ബാസ്(റ) അലി(റ)വിൽ നിന്ന് നിവേദനം ചെയ്യുന്നു: ഇഹ്റാം ചെയ്തവരായിരിക്കെ റസൂൽ(സ)യുടെ അടുത്ത് വേട്ടയാടപ്പെട്ട മൃഗത്തിന്റെ മാംസം കൊണ്ടുവരപ്പെട്ടു. റസൂൽ(സ) അത് ഭക്ഷിച്ചില്ല. (ഇതിന്റെ സനദിൽ ബലഹീനതയുണ്ട്.) (ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', null, 318, 318, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=68 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 254, 'عَنْ أَبِي قَتَادَةَ رَضِيَ اللهُ عَنْهُ قَالَ: خَرَجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَاجًّا وَخَرَجْنَا مَعَهُ، قَالَ: فَصَرَفَ مِنْ أَصْحَابِهِ فِيهِمْ أَبُو قَتَادَةَ، فَقَالَ: "خُذُوا سَاحِلَ الْبَحْرِ حَتَّى تَلْقَوْنِي". قَالَ فَأَخَذُوا سَاحِلَ الْبَحْرِ، فَلَمَّا انْصَرَفُوا قِبَلَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَحْرَمُوا كُلُّهُمْ إِلَّا أَبَا قَتَادَةَ فَإِنَّهُ لَمْ يُحْرِمْ، فَبَيْنَمَا هُمْ يَسِيرُونَ إِذْ رَأَوْا حُمُرَ وَحْشٍ، فَحَمَلَ عَلَيْهَا أَبُو قَتَادَةَ فَعَقَرَ مِنْهَا أَتَانًا، فَنَزَلُوا فَأَكَلُوا مِنْ لَحْمِهَا، قَالَ: فَقَالُوا: أَكَلْنَا لَحْمًا وَنَحْنُ مُحْرِمُونَ؟ قَالَ: فَحَمَلُوا مَا بَقِيَ مِنْ لَحْمِ الْأَتَانِ، فَلَمَّا أَتَوْا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالُوا: يَا رَسُولَ اللَّهِ إِنَّا كُنَّا أَحْرَمْنَا، وَكَانَ أَبُو قَتَادَةَ لَمْ يُحْرِمْ، فَرَأَيْنَا حُمُرَ وَحْشٍ، فَحَمَلَ عَلَيْهَا أَبُو قَتَادَةَ فَعَقَرَ مِنْهَا أَتَانًا، فَنَزَلْنَا فَأَكَلْنَا مِنْ لَحْمِهَا، فَقُلْنَا: نَأْكُلُ لَحْمَ صَيْدٍ وَنَحْنُ مُحْرِمُونَ؟ فَحَمَلْنَا مَا بَقِيَ مِنْ لَحْمِهَا، فَقَالَ: "هَلْ مِنْكُمْ أَحَدٌ أَمَرَهُ أَوْ أَشَارَ إِلَيْهِ بِشَيْءٍ". [قَالَ]: قَالُوا: لَا. قَالَ: "فَكُلُوا مَا بَقِيَ مِنْ لَحْمِهَا". (م)', 'അബൂഖതാദ(റ): തിരുമേനി(സ) ഹജ്ജിനായി പുറപ്പെട്ടു. ഞങ്ങളും അവിടത്തോടൊപ്പം കൂടി. നിവേദകൻ പറുയുന്നു: ഒരു കൂട്ടമാളുകളെ റസൂൽ(സ) വഴി തിരിച്ചു വിട്ടു. അവരുടെ കൂട്ടത്തിൽ അബൂഖതാദ(റ)വുമുണ്ടായിരുന്നു. എന്നിട്ട് റസൂൽ(സ) പറഞ്ഞു: "എന്നെ കണ്ടുമുട്ടുന്നത് വരെ നിങ്ങൾ കടൽ തീരത്തിലൂടെ യാത്ര ചെയ്യുക." യാത്രയിൽ തിരുദൂതർ(സ)യുടെ ഭാഗത്തേക്ക് തിരിഞ്ഞപ്പോൾ അബൂഖതാദ(റ)വല്ലാത്ത എല്ലാവരും ഇഹ്റാം ചെയ്തു. അബൂഖതാദ(റ) ഇഹ്റാം ചെയ്തില്ല. അവർ യാത്ര തുടർന്നു കൊണ്ടിരിക്കെ അവർ ഒരു കൂട്ടം കാട്ടുകഴുതകളെ കണ്ടു. അപ്പോൾ അബൂഖതാദ(റ) ഒന്നിനെ വേട്ടയാടിപ്പിടിച്ച് അറുത്തു. തുടർന്ന് അവർ ഒരിടത്ത് ഇറങ്ങി അതു ഭക്ഷിച്ചു. അപ്പോൾ അവർ പറഞ്ഞു: മുഹ്രിമായിരിക്കെ നമ്മൾ വേട്ട മാംസം ഭക്ഷിച്ചിരിക്കുന്നു. നിവേദകൻ പറയുന്നു: ബാക്കിയുള്ള മാംസവും അവർ തങ്ങളുടെ കൂടെ കരുതി. അങ്ങനെ തിരുമേനി(സ)യുടെ സമീപത്ത് എത്തിയപ്പോൾ അവർ പറഞ്ഞു: റസൂലേ, ഞങ്ങൾ അബൂഖതാദ(റ) ഒഴികെ എല്ലാവരും ഇഹ്റാം ചെയ്തിരുന്നു. യാത്രയിൽ ഞങ്ങൾ ഒരു കാട്ടുകഴുത കൂട്ടത്തെ കണ്ടു. അപ്പോൾ അബൂഖതാദ(റ) അവയെ വേട്ടയാടി ഒരു പെൺകഴുതയെ പിടിക്കുകയും അറുക്കുകയും ചെയ്തു. ഞങ്ങൾ ഒരിടത്തിറങ്ങി അതിന്റെ മാംസം ഭക്ഷിച്ചു. ഞങ്ങൾ പറഞ്ഞു: മുഹ്രിമായിരിക്കെ നാം വേട്ടമാംസം ഭക്ഷിച്ചിരിക്കുന്നു. ബാക്കിയുള്ളത് അങ്ങയോട് ചോദിക്കാൻ വേണ്ടി ഞങ്ങൾ എടുക്കുകയും ചെയ്തു. അപ്പോൾ തിരുമേനി(സ) ചോദിച്ചു: "നിങ്ങളിൽ നിന്നാരെങ്കിലും അബൂഖതാദയോട് അങ്ങനെ ചെയ്യാൻ കൽപ്പിക്കുകയോ ആംഗ്യം കൊണ്ട് അറിയിക്കുകയോ ചെയ്തുവോ?" അവർ പറഞ്ഞു: ഇല്ല. തിരുമേനി(സ) പറഞ്ഞു: "എങ്കിൽ ബാക്കിയുള്ള ഇറച്ചി നിങ്ങൾ ഭക്ഷിക്കുക." (മു)', 'أَبِي قَتَادَةَ', 'അബൂഖതാദ(റ)', null, null, array['م']::text[], array['മു']::text[], 'قَالَ', null, 318, 319, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=68 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 255, 'عَنِ الزُّبَيْرِ رَضِيَ اللهُ عَنْهُ قَالَ: لَمَّا أَقْبَلْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ لِيَّةَ، حَتَّى إِذَا كُنَّا عِنْدَ السِّدْرَةِ وَقَفَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي طَرَفِ الْقَرْنِ الْأَسْوَدِ حَذْوَهَا، فَاسْتَقْبَلَ نَخِبًا بِبَصَرِهِ - وفي رواية: وَادِيَهُ - وَوَقَفَ حَتَّى اتَّقَفَ النَّاسُ كُلُّهُمْ، ثُمَّ قَالَ: "إِنَّ صَيْدَ وَجٍّ وَعِضَاهَهُ حَرَامٌ مُحَرَّمٌ لِلَّهِ". وَذَلِكَ قَبْلَ نُزُولِهِ الطَّائِفَ وَحِصَارِهِ لِثَقِيفٍ. (د)', 'സുബൈർ(റ): ഞങ്ങൾ തിരുദൂതർ(സ)യോട് കുടെ ലിയ്യിൽ നിന്ന് വരികയായിരുന്നു. കള്ളിമുൾച്ചെടിയുടെ അടുത്ത് എത്തിയപ്പോൾ ചെടിയിലേക്ക് തിരിഞ്ഞ് ഖർനുൽഅസ്വദിന്റെ അറ്റത്ത് നബി(സ) നിന്നു. റസൂൽ(സ) നഖ്ബിനെ അല്ലെങ്കിൽ തന്റെ മലഞ്ചെരുവിനെ നോക്കി. ജനങ്ങൾ മുഴുവനും നിൽക്കുന്നത് വരെ തിരുമേനി(സ) നിന്നു. എന്നിട്ട് പറഞ്ഞു: "ഹജ്ജിൽ വേട്ടയാടലും അവിടത്തെ മരങ്ങൾ മുറിക്കലും അല്ലാഹു നിഷിദ്ധമാക്കിയതാണ്." ഇത് റസൂൽ(സ) താഇഫിലിറങ്ങുകയും സഖീഫുകാരെ ഉപരോധിക്കുകയും ചെയ്യുന്നതിന്റെ മുമ്പാണ്. (ദ)', 'الزُّبَيْرِ', 'സുബൈർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 319, 319, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=68 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=4 and h.hadith_no=255), 1, 'وَفِي رِوَايَةٍ: وَادِيَهُ - وَوَقَفَ حَتَّى اتَّقَفَ النَّاسُ كُلُّهُمْ، ثُمَّ قَالَ: "إِنَّ صَيْدَ وَجٍّ وَعِضَاهَهُ حَرَامٌ مُحَرَّمٌ لِلَّهِ". وَذَلِكَ قَبْلَ نُزُولِهِ الطَّائِفَ وَحِصَارِهِ لِثَقِيفٍ. (د)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 256, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "صَيْدُ الْبَرِّ لَكُمْ حَلَالٌ وَأَنْتُمْ حُرُمٌ، مَا لَمْ تَصِيدُوهُ أَوْ يُصَدْ لَكُمْ". (د,ت,ن)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): റസൂൽ(സ) പറഞ്ഞു: "ഇഹ്റാം ചെയ്തവരായിരിക്കെ, നിങ്ങൾ വേട്ടയാടുകയോ നിങ്ങൾക്ക് വേണ്ടി വേട്ടയാടപ്പെടുകയോ ചെയ്തതല്ലെങ്കിൽ കരയിലെ വേട്ടമാംസം നിങ്ങൾക്ക് അനുവദിനീയമാണ്." (ദ,തു,ന)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 319, 319, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=68 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 257, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: جَعَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الضَّبُعِ يُصِيبُهُ الْمُحْرِمُ كَبْشًا، وَجَعَلَهُ مِنَ الصَّيْدِ. (د,ت,ن,جه)', 'ജാബിർ(റ): മുഹ്രിം വേട്ടയാടുന്ന കഴുതപ്പുലിക്ക് നഷ്ടപരിഹാരമായി ആടിനെ റസൂൽ(സ) നിശ്ചയിച്ചു. അതിനെ വേട്ട മൃഗത്തിൽ ഉൾപ്പെടുത്തുകയും ചെയ്തു. (ദ,തു,ന,ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 319, 320, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=69 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 258, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ فِي بَيْضِ النَّعَامِ يُصِيبُهُ الْمُحْرِمُ: "ثَمَنُهُ". [ز: في إسناده مجهول وضعيف] (جه)', 'അബുഹുറൈറ(റ): മുഹ്രിം വേട്ടയാടുന്ന ഒട്ടകപ്പക്ഷി മുട്ടകളുടെ വിഷയത്തിൽ റസൂൽ(സ) പറഞ്ഞു: "നഷ്ടപരിഹാരമായി അതിന്റെ വിലയാണ്." (ഈ ഹദീസിന്റെ പരമ്പരയിൽ ഭംഗമുള്ളവരും അറിയപ്പെടാത്തവരുമുണ്ട്.) (ജ)', 'أَبِي هُرَيْرَةَ', 'അബുഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده مجهول وضعيف', null, 320, 320, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=69 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 259, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: رَأَى شَيْخًا يُهَادَى بَيْنَ ابْنَيْهِ، قَالَ: "مَا بَالُ هَذَا؟" قَالُوا نَذَرَ أَنْ يَمْشِيَ، قَالَ : "إِنَّ اللَّهَ عَنْ تَعْذِيبِ هَذَا نَفْسَهُ لَغَنِيٌّ". وَأَمَرَهُ أَنْ يَرْكَبَ. (خ)', 'അനസ്(റ): ഒരു വൃദ്ധൻ തന്റെ രണ്ട് മക്കളുടെ ചുമലിൽ പിടിച്ച് ആടിക്കൊണ്ടുപോകുന്നത് തിരുമേനി(സ) കണ്ടു. "ഇദ്ദേഹം എന്താണിങ്ങനെ ചെയ്യുന്നത്?" എന്ന് തിരുമേനി(സ) ചോദിച്ചു. നടന്നു ഹജ്ജ് ചെയ്യാൻ നേർച്ച നേർന്നിരിക്കുകയാണ് എന്നവർ മറുപടി പറഞ്ഞു. തിരുമേനി(സ) അരുളി: "ഇദ്ദേഹം ശരീരത്തെ പീഢിപ്പിക്കുന്നത് കൊണ്ട് അല്ലാഹുവിന് യാതൊരു കാര്യവുമില്ല." തിരുമേനി(സ) അയാളോട് വാഹനത്തിൽ കയറി പോകാൻ കൽപ്പിച്ചു. (ബു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 320, 320, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=70 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 260, 'عَنْ عُقْبَةَ بْنِ عَامِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: نَذَرَتْ أُخْتِي أَنْ تَمْشِيَ إِلَى بَيْتِ اللَّهِ، وَأَمَرَتْنِي أَنْ أَسْتَفْتِيَ لَهَا النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَاسْتَفْتَيْتُهُ لَهَا النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ النَّبِيُّ صَلَّى اللهُ عليهِ وَسَلَّمَ: "لِتَمْشِ وَلْتَرْكَبْ". (خ)', 'ഉഖ്ബത്തുബ്നു ആമിർ(റ): എന്റെ സഹോദരി കഅബാലയത്തിലേക്ക് നടന്ന് പോവാൻ നേർച്ചയാക്കി. അവരെന്നോടു നബിതങ്ങളോട് മതവിധിയന്വേഷിക്കാനും കൽപിച്ചു. ഞാനവർക്ക് വേണ്ടി റസൂൽ(സ)യോടു വിധിയന്വേഷിച്ചപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അവൾ നടക്കുകയും, വാഹനത്തിലേറുകയും ചെയ്യട്ടെ." (ബു)', 'عُقْبَةَ بْنِ عَامِرٍ', 'ഉഖ്ബത്തുബ്നു ആമിർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 320, 320, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=70 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 261, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَقَفَ يَوْمَ النَّحْرِ بَيْنَ الْجَمَرَاتِ، فِي الْحَجَّةِ الَّتِي حَجَّ فِيهَا، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَيُّ يَوْمٍ هَذَا". قَالُوا: يَوْمُ النَّحْرِ. قَالَ: "فَأَيُّ بَلَدٍ هَذَا". قَالُوا: هَذَا بَلَدُ اللَّهِ الْحَرَامُ. قَالَ: "فَأَيُّ شَهْرٍ هَذَا". قَالُوا: شَهْرُ اللَّهِ الْحَرَامُ. قَالَ: "هَذَا يَوْمُ الْحَجِّ الْأَكْبَرِ، وَدِمَاؤُكُمْ وَأَمْوَالُكُمْ وَأَعْرَاضُكُمْ عَلَيْكُمْ حَرَامٌ، كَحُرْمَةِ هَذَا الْبَلَدِ، فِي هَذَا الشَّهْرِ، فِي هَذَا الْيَوْمِ". ثُمَّ قَالَ: "هَلْ بَلَّغْتُ". قَالُوا: نَعَمْ. فَطَفِقَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "اللَّهُمَّ اشْهَدْ". ثُمَّ وَدَّعَ النَّاسَ، فَقَالُوا: هَذِهِ حَجَّةُ الْوَدَاعِ. (خ,د,جه)', 'ഇബ്നുഉമർ(റ): ഹജ്ജ് വേളയിൽ ബലിദിനത്തിൽ ജംറകൾക്കിടയിൽ നിൽക്കെ തിരുമേനി(സ) ചോദിച്ചു: "ഏത് ദിവസമാണ് ഇന്ന്" അവർ പറഞ്ഞു: ബലി ദിനം. റസൂൽ(സ) ചോദിച്ചു: "ഏത് നാടാണ് ഇത്." അവർ മറുപടി നൽകി: ഇത് അല്ലാഹുവിന്റെ പവിത്ര നാടാണ്. റസൂൽ(സ) പറഞ്ഞു: "ഇന്നാണ് ഹജ്ജുൽ അക്ബറിന്റെ ദിനം. നിങ്ങളുടെ സമ്പത്തും അഭിമാനവും രക്തവും പവിത്രമാണ്. ഈ നാടും മാസവും ദിനവും പവിത്രമായതു പോലെ" എന്നിട്ട് റസൂൽ(സ) ചോദിച്ചു: "ഞാൻ നിങ്ങൾക്ക് എത്തിച്ചു തന്നില്ലയോ?" അവർ പറഞ്ഞു: അതെ. എന്നിട്ട് തിരുമേനി(സ) പറയാൻ തുടങ്ങി: "അല്ലാഹുവേ, നീ സാക്ഷി" ശേഷം അവിടന്ന് ജനങ്ങളോട് യാത്ര പറഞ്ഞു. അപ്പോൾ അവർ പറഞ്ഞു: ഇത് ഹജ്ജതുൽ വിദാആണ്. (ബു,ദ,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ','د','جه']::text[], array['ബു','ദ','ജ']::text[], null, null, 320, 321, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=70 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 262, 'عَنْ عَمْرِو بْنِ الْأَحْوَصِ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ فِي حَجَّةِ الْوَدَاعِ: "يَا أَيُّهَا النَّاسُ، أَلَا أَيُّ يَوْمٍ أَحْرَمُ". ثَلَاثَ مَرَّاتٍ. قَالُوا: يَوْمُ الْحَجِّ الْأَكْبَرِ. قَالَ: ''فَإِنَّ دِمَاءَكُمْ وَأَمْوَالَكُمْ وَأَعْرَاضَكُمْ بَيْنَكُمْ حَرَامٌ، كَحُرْمَةِ يَوْمِكُمْ هَذَا، فِي شَهْرِكُمْ هَذَا، فِي بَلَدِكُمْ هَذَا. أَلَا لَا يَجْنِي جَانٍ إِلَّا عَلَى نَفْسِهِ، وَلَا يَجْنِي وَالِدٌ عَلَى وَلَدِهِ، وَلَا مَوْلُودٌ عَلَى وَالِدِهِ. أَلَا إِنَّ الشَّيْطَانَ قَدْ أَيِسَ أَنْ يُعْبَدَ فِي بَلَدِكُمْ هَذَا أَبَدًا، وَلَكِنْ سَيَكُونُ لَهُ طَاعَةٌ فِي بَعْضِ مَا تَحْتَقِرُونَ مِنْ أَعْمَالِكُمْ، فَيَرْضَى بِهَا. أَلَا وَكُلُّ دَمٍ مِنْ دِمَاءِ الْجَاهِلِيَّةِ مَوْضُوعٌ، وَأَوَّلُ مَا أَضَعُ مِنْهَا دَمُ الْحَارِثِ بْنِ عَبْدِ الْمُطَّلِبِ. كَانَ مُسْتَرْضِعًا فِي بَنِي لَيْثٍ، فَقَتَلَتْهُ هُذَيْلٌ. أَلَا وَإِنَّ كُلَّ رِبًا مِنْ رِبَا الْجَاهِلِيَّةِ مَوْضُوعٌ، لَكُمْ رُءُوسُ أَمْوَالِكُمْ لَا تَظْلِمُونَ وَلَا تُظْلَمُونَ. أَلَا، يَا أُمَّتَاهُ، هَلْ بَلَّغْتُ". ثَلَاثَ مَرَّاتٍ. قَالُوا: نَعَمْ. قَالَ: "اللَّهُمَّ اشْهَدْ". ثَلَاثَ مَرَّاتٍ. (د,ت,جه)', 'അംറുബ്നു അഹ്വസ്(റ): ഹജ്ജതുൽ വിദാഇൽ റസൂൽ(സ) ഇപ്രകാരം ചോദിക്കുന്നത് ഞാൻ കേട്ടു: "ഓ, ജനങ്ങളേ, അറിയുക, ഏത് ദിനമാണ് ഏറ്റവും പവിത്രമായത്?" ഇത് മൂന്ന് തവണ പറഞ്ഞു. അവർ പറഞ്ഞു: ഹജ്ജുൽ അക്ബറിന്റെ ദിവസം. റസൂൽ(സ) അരുളി: "നിശ്ചയം നിങ്ങളുടെ രക്തവും സമ്പത്തും അഭിമാനവും നിങ്ങൾക്കിടയിൽ (കളങ്കപ്പെടുത്തൽ) നിഷിദ്ധമാണ്. ഈ ദിനവും മാസവും സ്ഥലവും നിഷിദ്ധമാമായതു പോലെ. അറിയുക, അക്രമം ചെയ്യുന്നവൻ തന്റെ ശരീരത്തോട് തന്നെയാണ് അക്രമം പ്രവർത്തിക്കുന്നത്. മക്കളുടെ കുറ്റത്തിന്റെ പേരിൽ പിതാവും പിതാവിന്റെ കുറ്റത്തിന്റെ പേരിൽ മക്കളും ശിക്ഷിക്കപ്പെടുകയില്ല. അറിയുക, നിങ്ങളുടെ ഈ നാട്ടിൽ താൻ ആരാധിക്കപ്പെടുമെന്നതിൽ പിശാച് ആശയറ്റവനാണ്. നിങ്ങൾ നിസ്സാരമെന്ന് കരുതുന്ന ചില കാര്യങ്ങളിൽ പക്ഷെ, അവനു വഴിപ്പെടലുകളുണ്ടാവും. അവൻ അതുകൊണ്ട് തൃപ്തിപ്പെടും. അറിയുക, അജ്ഞാന യുഗത്തിലെ പ്രതിക്രിയാ വധങ്ങൾ തള്ളപ്പെട്ടതാണ്. അതിൽ ഞാൻ പ്രഥമമായി ഒഴിവാക്കിക്കൊടുക്കുന്നത് ഹാരിസുബ്നു അബ്ദുൽ മുത്വലിബിന്റെ വധമാണ്. ബനൂ ലൈഥിൽ മുല കുടുക്കുന്നവനായിരുന്നു അദ്ദേഹം. ഹുദൈൽ ഗോത്രം അദ്ദേഹത്തെ വധിച്ചു. അറിയുക, അജ്ഞാന യുഗത്തിലെ പലിശകളത്രയും തള്ളപ്പെട്ടതാണ്. നിങ്ങൾക്ക് നിങ്ങളുടെ മൂലധനമുണ്ട്. അതിൽ നിങ്ങൾ അക്രമം പ്രവർത്തിക്കുകയോ, അക്രമിക്കപ്പെടുകയോ ചെയ്യരുത്. എന്റെ സമുദായമേ, അറിയുക, ഞാൻ നിങ്ങൾക്ക് എത്തിച്ചു തന്നില്ലെയോ?" മൂന്ന് തവണ ഇപ്രകാരം ചോദിച്ചു: അവർ പറഞ്ഞു: അതെ, റസൂൽ(സ): "അല്ലാഹുവേ, നീ സാക്ഷിയാണ്." എന്ന് മൂന്ന് തവണ പറഞ്ഞു. (ദ,തു,ജ)', 'عَمْرِو بْنِ الْأَحْوَصِ', 'അംറുബ്നു അഹ്വസ്(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 321, 321, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=71 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 263, 'عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَهُوَ عَلَى نَاقَتِهِ الْمُخَضْرَمَةِ بِعَرَفَاتٍ، فَقَالَ: "أَتَدْرُونَ أَيُّ يَوْمٍ هَذَا، وَأَيُّ شَهْرٍ هَذَا، وَأَيُّ بَلَدٍ هَذَا". قَالُوا: هَذَا بَلَدٌ حَرَامٌ، وَشَهْرٌ حَرَامٌ، وَيَوْمٌ حَرَامٌ. قَالَ: "أَلَا وَإِنَّ أَمْوَالَكُمْ وَدِمَاءَكُمْ عَلَيْكُمْ حَرَامٌ، كَحُرْمَةِ شَهْرِكُمْ هَذَا فِي بَلَدِكُمْ هَذَا، فِي يَوْمِكُمْ هَذَا، أَلَا وَإِنِّي فَرَطُكُمْ عَلَى الْحَوْضِ، وَأُكَاثِرُ بِكُمُ الْأُمَمَ، فَلَا تُسَوِّدُوا وَجْهِي. أَلَا وَإِنِّي مُسْتَنْقِذٌ أُنَاسًا، وَمُسْتَنْقَذٌ مِنِّي أُنَاسٌ، فَأَقُولُ: يَا رَبِّ أُصَيْحَابِي؟ فَيَقُولُ: إِنَّكَ لَا تَدْرِي مَا أَحْدَثُوا بَعْدَكَ". (جه)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): അറഫയിൽ ചെവിയുടെ അറ്റം മുറിച്ച തന്റെ ഒട്ടകപ്പുറത്തിരിക്കെ തിരുമേനി(സ) ചോദിച്ചു: "ഏത് ദിനമാണിത്, ഏത് മാസമാണിത്, ഏത് നാടാണിത് എന്ന് നിങ്ങൾക്കറിയുമോ?" അവർ പറഞ്ഞു: ഇത് നിഷിദ്ധമായ നാടാണ്. നിഷിദ്ധമായ ദിനമാണ്. നിഷിദ്ധമായ മാസമാണ്. തിരുമേനി(സ) പറഞ്ഞു: "അറിയുക, നിങ്ങളുടെ രക്തവും സമ്പത്തും നിങ്ങൾക്ക് നിഷിദ്ധമാണ്. നിങ്ങളുടെ ഈ നാടും ദിവസവും മാസവും നിഷിദ്ധമായതുപോലെ. അറിയുക, ഹൗളുൽ കൗസറിനടുത്തേക്ക് നിങ്ങളുടെ മുമ്പേ ഞാനെത്തും. മറ്റു സമുദായക്കാരുടെ മുന്നിൽ നിങ്ങളെക്കൊണ്ട് ഞാൻ പ്രൗഢി നടിക്കും. നിങ്ങളെന്റെ മുഖം കറുപ്പിക്കരുത്. അറിയുക, ഒരുപാടു പേരെ ഞാൻ സംരക്ഷിക്കും. ഒരുപാട് പേർ എന്റെ സംരക്ഷണത്തിൽ നിന്ന് തട്ടിയെടുക്കപ്പെടും. അപ്പോൾ ഞാൻ പറയും: നാഥാ, ഇവരെന്റെ അനുയായികളാണ്. അല്ലാഹു ഉത്തരം നൽകും: അങ്ങയുടെ ശേഷം അവരെന്താണ് പുതുതായി ഉണ്ടാക്കിയതെന്ന് അങ്ങേക്കറിയില്ല." (ജ)', 'عَبْدِ اللَّهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 321, 322, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=71 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 264, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: لَمَّا فَتَحَ اللَّهُ عَزَّ وَجَلَّ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَكَّةَ، قَامَ فِي النَّاسِ، فَحَمِدَ اللَّهَ وَأَثْنَى عَلَيْهِ، ثُمَّ قَالَ: "إِنَّ اللَّهَ حَبَسَ عَنْ مَكَّةَ الْفِيلَ، وَسَلَّطَ عَلَيْهَا رَسُولَهُ وَالْمُؤْمِنِينَ، وَإِنَّهَا لَنْ تَحِلَّ لِأَحَدٍ كَانَ قَبْلِي، وَإِنَّهَا أُحِلَّتْ لِي سَاعَةً مِنْ نَهَارٍ، وَإِنَّهَا لَنْ تَحِلَّ لِأَحَدٍ بَعْدِي، فَلَا يُنَفَّرُ صَيْدُهَا، وَلَا يُخْتَلَى شَوْكُهَا، وَلَا تَحِلُّ سَاقِطَتُهَا إِلَّا لِمُنْشِدٍ، وَمَنْ قُتِلَ لَهُ قَتِيلٌ فَهُوَ بِخَيْرِ النَّظَرَيْنِ: إِمَّا أَنْ يُفْدَى وَإِمَّا أَنْ يُقْتَلَ". فَقَالَ الْعَبَّاسُ: إِلَّا الْإِذْخِرَ يَا رَسُولَ اللَّهِ، فَإِنَّا نَجْعَلُهُ فِي قُبُورِنَا وَبُيُوتِنَا. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِلَّا الْإِذْخِرَ". فَقَامَ أَبُو شَاهٍ - رَجُلٌ مِنْ أَهْلِ الْيَمَنِ - فَقَالَ: اكْتُبُوا لِي يَا رَسُولَ اللَّهِ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "اكْتُبُوا لِأَبِي شَاهٍ". قَالَ الْوَلِيدُ: فَقُلْتُ لِلْأَوْزَاعِيِّ: مَا قَوْلُهُ: اكْتُبُوا لِي يَا رَسُولَ اللَّهِ؟ قَالَ: هَذِهِ الْخُطْبَةَ الَّتِي سَمِعَهَا مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (م)', 'അബൂഹുറൈറ(റ): അല്ലാഹു മക്ക കീഴ്പ്പെടുത്തിക്കൊടുത്തപ്പോൾ തിരുമേനി(സ) ജനങ്ങൾക്കിടയിൽ ഏഴുന്നേറ്റ് നിന്നു. അല്ലാഹുവിനെ സ്തുതിക്കുകയും അവനെ വാഴ്ത്തുകയും ചെയ്തു. എന്നിട്ട് പറഞ്ഞു: "നിശ്ചയമായും (അബ്രഹത്തിന്റെ) ആനയെ തടഞ്ഞു കൊണ്ട് അല്ലാഹു മക്കയെ സംരക്ഷിച്ചിരിക്കുന്നു. അതിനുമേൽ റസൂലും മുഅ്മിനീങ്ങളും ആധിപത്യമുറപ്പിച്ചിരിക്കുന്നു. തീർച്ചയായും പകൽ ഒരു നാഴിക നേരം മാത്രമാണ് മക്കയിൽ യുദ്ധം ചെയ്യാൻ അല്ലാഹു എനിക്ക് അനുമതി നൽകിയത്. എന്റെ മുൻഗാമികൾക്കാർക്കും അതിന് അനുമതി ലഭിച്ചിട്ടില്ല. എന്റെ ശേഷമുള്ളവർക്കും അതിന് അനുവാദം ലഭിക്കുകയില്ല. മക്കയിലെ വേട്ടമൃഗങ്ങളെ വേട്ടയാടിപ്പിടിക്കരുത്. മുള്ളുകൾ പൊട്ടിച്ചെടുക്കരുത്. വീണുകിട്ടിയ വസ്തു മറ്റുള്ളവരെ അറിയിക്കാൻ വേണ്ടിയല്ലാതെ എടുക്കരുത്. അപ്പോൾ വല്ലവനും (മക്കയിൽ വെച്ച്) കൊല്ലപ്പെട്ടാൽ അവന്റെ അവകാശികൾക്ക് രണ്ടിൽ ഉത്തമമെന്ന് തോന്നുന്ന ഒരു മാർഗ്ഗം തെരെഞ്ഞെടുക്കാം. ഒന്നുകിൽ നഷ്ടപരിഹാരം സ്വീകരിക്കുക. അല്ലെങ്കിൽ പകരം വധിക്കുക." അപ്പോൾ ഇബ്നുഅബ്ബാസ്(റ) പറഞ്ഞു: റസൂലേ, ഇദ്ഖർ(ഒരു തരം പുല്ല്) ഒഴിവാക്കിത്തന്നാലും. കാരണം ഞങ്ങൾ അത് പുര മേയാനും ഖബറിൽ വെക്കാനും ഉപയോഗിക്കാറുണ്ട്. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "ഇദ്ഖർ എന്ന പുല്ല് ഒഴികെ." അപ്പോൾ യമൻകാരനായ അബൂശാഹ്(റ) എഴുന്നേറ്റ് നിന്നുകൊണ്ട് പറഞ്ഞു: റസൂലേ, ഇവ എനിക്ക് എഴുതിത്തന്നാലും. റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളിത് അബൂശാക്ക് എഴുതിക്കൊടുക്കുക." വലീദ്(റ) പറയുന്നു: ഞാൻ ഔസാഇനോട് ചോദിച്ചു: എന്താണയാൾ ''എഴുതിത്തന്നാലും'' എന്നതു കൊണ്ട് ഉദ്ദേശിച്ചത്. അവർ പറഞ്ഞു: അയാൾ തിരുമേനി(സ)യിൽ നിന്ന് കേട്ട ഈ പ്രസംഗം. (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 322, 322, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=71 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 265, 'عَنْ أَبِي شُرَيْحٍ الْعَدَوِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّهُ قَالَ لِعَمْرِو بْنِ سَعِيدٍ - وَهُوَ يَبْعَثُ الْبُعُوثَ إِلَى مَكَّةَ -: ائْذَنْ لِي أَيُّهَا الْأَمِيرُ، أُحَدِّثْكَ قَوْلًا قَامَ بِهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْغَدَ مِنْ يَوْمِ الْفَتْحِ، سَمِعَتْهُ أُذُنَايَ، وَوَعَاهُ قَلْبِي، وَأَبْصَرَتْهُ عَيْنَايَ حِينَ تَكَلَّمَ بِهِ، أَنَّهُ حَمِدَ اللَّهَ وَأَثْنَى عَلَيْهِ ثُمَّ قَالَ: "إِنَّ مَكَّةَ حَرَّمَهَا اللَّهُ وَلَمْ يُحَرِّمْهَا النَّاسُ، وَلَا يَحِلُّ لِامْرِئٍ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ أَنْ يَسْفِكَ فِيهَا دَمًا، أَوْ يَعْضِدَ بِهَا شَجَرَةً. فَإِنْ أَحَدٌ تَرَخَّصَ بِقِتَالِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِيهَا فَقُولُوا لَهُ: إِنَّ اللَّهَ أَذِنَ لِرَسُولِهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَلَمْ يَأْذَنْ لَكَ، وَإِنَّمَا أَذِنَ لِي فِيهِ سَاعَةً مِنَ النَّهَارِ، وَقَدْ عَادَتْ حُرْمَتُهَا الْيَوْمَ كَحُرْمَتِهَا بِالْأَمْسِ، وَلْيُبَلِّغِ الشَّاهِدُ الْغَائِبَ". فَقِيلَ لِأَبِي شُرَيْحٍ: مَا قَالَ لَكَ عَمْرٌو؟ قَالَ: أَنَا أَعْلَمُ مِنْكَ بِذَلِكَ يَا أَبَا شُرَيْحٍ، إِنَّ الْحَرَمَ لَا يُعِيذُ عَاصِيًا، وَلَا فَارًّا بِدَمٍ، وَلَا فَارًّا بِخَرْبَةٍ. وَفِي رِوَايَةٍ: بِخِزْيَةٍ. قَالَ ترمذي حَدِيثُ أَبِي شُرَيْحٍ حَدِيثٌ حَسَنٌ صَحِيحٌ. (ق,ت)', 'അബുശുറൈഹിൽ അദവി(റ): അദ്ദേഹം അംറുബ്നു സഈദ് (ഇബ്നസ്സുബൈർ(റ)വിനോട് യുദ്ധം ചെയ്യാൻവേണ്ടി) മക്കയിലേക്ക് സൈന്യങ്ങളെ അയച്ചുകൊണ്ടിരിക്കുന്ന സന്ദർഭത്തിൽ അദ്ദേബഹം അംറുബ്നു സഈദ്(റ)വിനോട് പറഞ്ഞു: ബഹുമാന്യരെ, മക്കാവിജ ദിനത്തിന്റെ പിറ്റേദിവസം റസൂൽ(സ) അരുളിയ ഒരു കാര്യം താങ്കളോട് പറയുവാൻ എനിക്കനുമതി നൽകിയാലും, ഇതു തിരുമേനി(സ) എഴുന്നേറ്റു നിന്ന് പറയുന്നത് ഞാൻ നേർക്കുനേരെ കണ്ടതും എന്റെ കാതുകൾ കേട്ടതും ഹൃദയം ഭദ്രമായി സൂക്ഷിച്ചതുമായ കാര്യമാണ്. അല്ലാഹുവിനെ സ്തുതിക്കുകയും വാഴ്ത്തുകയും ചെയ്ത ശേഷം റസൂൽ(സ) ഇപ്രാകരം അരുളി: "നിശ്ചയമായും മക്കയെ അല്ലാഹു ആദരണീയമാക്കിയിരിക്കുന്നു. അതിനെ ജനങ്ങൾ ആദരിണീയമാക്കിയതല്ല. അതുകൊണ്ട് അല്ലാഹുവിലും അന്ത്യദിനത്തിലും വിശ്വസിക്കുന്ന ഏതൊരു മനുഷ്യനും അവിടെവെച്ച് രക്തം ചിന്തുവാനോ അവിടത്തെ വൃക്ഷം മുറിക്കുവാനോ പാടുള്ളതല്ല. അല്ലാഹുവിന്റെ റസൂൽ(സ) അവിടെ വെച്ച് യുദ്ധം ചെയ്തിട്ടുണ്ട് എന്നുപറഞ്ഞുകൊണ്ട് വല്ലവനും അതിൽ ഇളവ് ഉപയോഗപ്പെടുത്തുവാനുദ്ദേശിച്ചാൽ നിങ്ങൾ അവരോട് പറയുക; ''നിശ്ചയമായും അല്ലാഹു അവന്റെ ദൂതന്ന് അനുമതി നൽകിയിട്ടുണ്ട്. നിനക്ക് അനുമതി നൽകിയിട്ടില്ല''. എനിക്കവിടെ (യുദ്ധത്തിന്ന്) അനുമതി ലഭിച്ചത് തന്നെ ഒരു പകലിൽ അൽപസമയം മാത്രമാണ്. ഉടനെത്തന്നെ മുമ്പത്തെപ്പോലെ വീണ്ടും അത് ആദരണീയമാകുകയും ചെയ്തു. (ഈ കാര്യങ്ങൾ ഇവിടെ) സാക്ഷിയായവർ സാക്ഷിയല്ലാത്തവർക്ക് എത്തിച്ചുകൊടുക്കുക." അനന്തരം അബു ശുറൈഹ്(റ)വിനോട് ആരോ ഒരാൾ ചോദിച്ചു: അംറ് എന്താണ് നിങ്ങളോട് ഉത്തരമായി പറഞ്ഞത്. അബൂശുറൈഹ്(റ) പറയുന്നു: അദ്ദേഹം പറഞ്ഞു: ഹേ അബൂശുറൈഹേ, ഇക്കാര്യം എനിക്ക് നിന്നേക്കാൾ അറിയാം. നിശ്ചയമായും ''ഹറം'' ധിക്കാരിക്കും കൊലയാളിക്കും കൊള്ളക്കാരനും അഭയം നൽകുകയില്ല (എന്ന കാര്യം ഓർമ്മിക്കുക). (തുർമുദി(റ) പറയുന്നു: അബൂ ശുറൈഹ്(റ)വിന്റെ ഹദീസ് ഹസനും സ്വഹീഹുമാണ്.) (ബു,മു,ത)', 'أَبِي شُرَيْحٍ الْعَدَوِيِّ', 'അബുശുറൈഹിൽ അദവി(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','ത']::text[], null, null, 322, 323, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=71 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=4 and h.hadith_no=265), 1, 'وَفِي رِوَايَةٍ: بِخِزْيَةٍ. قَالَ ترمذي حَدِيثُ أَبِي شُرَيْحٍ حَدِيثٌ حَسَنٌ صَحِيحٌ. (ق,ت)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 266, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ الْأَنْصَارِيِّ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ دَخَلَ مَكَّةَ - وَقَالَ قُتَيْبَةُ: دَخَلَ يَوْمَ فَتْحِ مَكَّةَ - وَعَلَيْهِ عِمَامَةٌ سَوْدَاءُ بِغَيْرِ إِحْرَامٍ. (م)', 'ജാബിറുബ്നു അബ്ദില്ലാഹിൽ അൻസാരീ(റ): റസൂൽ(സ) കറുത്ത തലപ്പാവണിഞ്ഞ്, ഇഹ്റാം ചെയ്യാതെ മക്കയിൽ പ്രവേശിച്ചു. ഖുതൈബത്(റ) പറഞ്ഞത്; മക്കാ വിജയ നാളിൽ പ്രവേശിച്ചു എന്നാണ്. (മു)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ الْأَنْصَارِيِّ', 'ജാബിറുബ്നു അബ്ദില്ലാഹിൽ അൻസാരീ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 323, 323, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=72 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 267, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ دَخَلَ مَكَّةَ عَامَ الْفَتْحِ وَعَلَى رَأْسِهِ مِغْفَرٌ، فَلَمَّا نَزَعَهُ جَاءَهُ رَجُلٌ فَقَالَ: ابْنُ خَطَلٍ مُتَعَلِّقٌ بِأَسْتَارِ الْكَعْبَةِ، فَقَالَ: "اقْتُلُوهُ". (م)', 'അനസുബ്നു മാലിക്(റ): മക്ക ജയിച്ചടക്കിയ വർഷം റസൂൽ(സ) പടത്തൊപ്പി ധരിച്ചു കൊണ്ട് മക്കയിൽ പ്രവേശിച്ചു. അതു തലയിൽ നിന്നെടുത്തു നീക്കിയ അവസരത്തിൽ ഒരു മനുഷ്യൻ അവിടുത്തെ അടുക്കൽ വന്നു പറഞ്ഞു: ഇബ്നു ഖതൽ കഅ്ബയുടെ വിരികളിൽ കെട്ടിപ്പിടിച്ചിരിക്കുകയാണ്. അന്നേരം തിരുമേനി(സ) അരുളി: "നിങ്ങളവനെ വധിച്ചു കളയുക." (മു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 323, 324, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=72 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 268, 'عَنْ عَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى قَالَ: كُنَّا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ اعْتَمَرَ، فَطَافَ وَطُفْنَا مَعَهُ، وَصَلَّى وَصَلَّيْنَا مَعَهُ، وَكُنَّا نَسْتُرُهُ مِنْ أَهْلِ مَكَّةَ، لَا يُصِيبُهُ أَحَدٌ بِشَيْءٍ. (خ,د,جه)', 'അബ്ദുല്ലാഹിബ്നു അബീ ഔഫാ(റ): റസൂൽ(സ)യുടെ ഉംറ വേളയിൽ ഞങ്ങൾ അവിടുത്തോടൊപ്പമുണ്ടായിരുന്നു. റസൂൽ(സ) ത്വവാഫ് ചെയ്തപ്പോൾ കൂടെ ഞങ്ങളും ത്വവാഫ് ചെയ്തു. നിസ്കരിച്ചപ്പോൾ ഞങ്ങളും നിസ്കരിച്ചു. റസൂൽ(സ)ക്ക് ഒരാളും ഒരു ഉപദ്രവവുമേൽപ്പിക്കാതിരിക്കാൻ ഞങ്ങൾ നബി(സ)യെ മക്കക്കാരിൽ നിന്നും മറച്ചിരുന്നു. (ബു,ദ,ജ)', 'عَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى قَالَ', 'അബ്ദുല്ലാഹിബ്നു അബീ ഔഫാ(റ)', null, null, array['خ','د','جه']::text[], array['ബു','ദ','ജ']::text[], null, null, 324, 324, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=73 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 269, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ دَخَلَ مَكَّةَ وَلِوَاؤُهُ أَبْيَضُ. (ن)', 'ജാബിർ(റ): നബി(സ) മക്കയിൽ പ്രവേശിച്ചത് വെളുത്ത നിറത്തിലുള്ള പതാകയുമായാണ്. (ന)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 324, 324, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=73 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 270, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ دَخَلَ مَكَّةَ مِنَ الثَّنِيَّةِ الْعُلْيَا الَّتِي بِالْبَطْحَاءِ، وَخَرَجَ مِنَ الثَّنِيَّةِ السُّفْلَى. (ن)', 'ഇബ്നുഉമർ(റ): നിശ്ചയം നബി(സ) മക്കയിൽ പ്രവേശിച്ചിരുന്നത് ബത്ഹാഇലുള്ള സനിയ്യത്തുൽ ഉൽയാ എന്ന ഭാഗത്തിലൂടെയും, പുറത്ത് പോയിരുന്നത് സനിയ്യത്തുസ്സുഫ്ലാ എന്ന ഭാഗത്തിലൂടെയുമാണ്. (ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 324, 324, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=73 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 271, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَمَّا قَدِمَ مَكَّةَ اسْتَقْبَلَهُ أُغَيْلِمَةُ بَنِي هَاشِمٍ، قَالَ: فَحَمَلَ وَاحِدًا بَيْنَ يَدَيْهِ وَآخَرَ خَلْفَهُ. (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) മക്കയിൽ വന്നപ്പോൾ ബനുഹാഷിമിലെ കുട്ടികൾ റസൂൽ(സ)യെ സ്വീകരിച്ചു. അവിടന്ന് അവരിൽ ഒരാളെ വാഹനപ്പുറത്ത് തന്റെ മുന്നിലും മറ്റൊരാളെ പിന്നിലും ഇരുത്തി. (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 324, 324, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=73 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 272, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ دَخَلَ مَكَّةَ نَهَارًا. (ت,جه)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) പകൽ സമയത്ത് മക്കയിൽ പ്രവേശിച്ചു. (തു,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 324, 324, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=73 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 273, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: دَخَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَامَ الْفَتْحِ مِنْ كَدَاءٍ مِنْ أَعْلَى مَكَّةَ، وَدَخَلَ فِي الْعُمْرَةِ مِنْ كُدًى. قَالَ: وَكَانَ عُرْوَةُ يَدْخُلُ مِنْهُمَا جَمِيعًا، وَكَانَ أَكْثَرُ مَا كَانَ يَدْخُلُ مِنْ كُدًى، وَكَانَ أَقْرَبَهُمَا إِلَى مَنْزِلِهِ. (د)', 'ആഇശ(റ): മക്കാ വിജയ വർഷം മക്കയുടെ മുഗൾഭാഗത്തുള്ള കദാഅ് എന്ന സ്ഥലത്തിലൂടെയായിരുന്നു റസൂൽ(സ) മക്കയിൽ പ്രവേശിച്ചത്. എന്നാൽ ഉംറക്ക് വന്നപ്പോൾ കുദാ എന്ന പ്രദേശത്തു കുടിയാണ് അവിടുന്ന് മക്കയിൽ പ്രവേശിച്ചത്. നിവേദകൻ പറയുന്നു: ഉർവ(റ) രണ്ട് വഴിയിലൂടെയും മക്കയിൽ പ്രവേശിക്കുമായിരുന്നു. എന്നാൽ അധികവും പ്രവേശിച്ചത് കുദാ വഴിക്കായിരുന്നു. കാരണം ഉർവ്വയുടെ വീടിനോട് ഏറ്റവും അടുത്തത് അതായിരുന്നു. (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 324, 324, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=73 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 274, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا دَخَلَ مَكَّةَ دَخَلَ مِنْ أَعْلَاهَا وَخَرَجَ مِنْ أَسْفَلِهَا. (د)', 'ആഇശ(റ): റസൂൽ(സ) മക്കയിൽ പ്രവേശിക്കുകയാണെങ്കിൽ അതിന്റെ മേൽഭാഗത്തിലൂടെ പ്രവേശിക്കും. താഴ്ഭാഗത്തിലൂടെ പുറത്ത് കടക്കുകയും ചെയ്യും. (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 324, 324, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=73 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 275, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَدْخُلُ مَكَّةَ مِنَ الثَّنِيَّةِ الْعُلْيَا - وَفِي رِوَايَةٍ: مِنْ كَدَاءَ مِنْ ثَنِيَّةِ الْبَطْحَاءِ - وَيَخْرُجُ مِنَ الثَّنِيَّةِ السُّفْلَى. (د)', 'ഇബ്നുഉമർ(റ): നബി(സ) ഉയർന്ന മലഞ്ചെരുവിലൂടെ-മറ്റൊരു റിപ്പോർട്ട്: ബത്ഹാഅ് മലഞ്ചെരുവിലെ കദാഅ് എന്ന പ്രദേശത്തിലൂടെ- മക്കയിൽ പ്രവേശിക്കുകയും താഴ്ന്ന മലഞ്ചെരുവിലൂടെ പുറത്ത് വരികയും ചെയ്യുമായിരുന്നു. (ദ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 324, 325, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=73 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=4 and h.hadith_no=275), 1, 'وَفِي رِوَايَةٍ: مِنْ كَدَاءَ مِنْ ثَنِيَّةِ الْبَطْحَاءِ - وَيَخْرُجُ مِنَ الثَّنِيَّةِ السُّفْلَى. (د)', 'മറ്റൊരു നിവേദന്: ബത്ഹാഅ് മലഞ്ചെരുവിലെ കദാഅ് എന്ന പ്രദേശത്തിലൂടെ- മക്കയിൽ പ്രവേശിക്കുകയും താഴ്ന്ന മലഞ്ചെരുവിലൂടെ പുറത്ത് വരികയും ചെയ്യുമായിരുന്നു. (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 276, 'عَنْ عَيَّاشِ بْنِ أَبِي رَبِيعَةَ الْمَخْزُومِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا تَزَالُ هَذِهِ الْأُمَّةُ بِخَيْرٍ مَا عَظَّمُوا هَذِهِ الْحُرْمَةَ حَقَّ تَعْظِيمِهَا، فَإِذَا ضَيَّعُوا ذَلِكَ هَلَكُوا". (جه)', 'അയ്യാശിബിൻ അബീ റബീഅതൽ മഖ്സൂമീ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഈ ഹറം ഭൂമിയെ അതർഹിക്കുന്ന വിധത്തിൽ ബഹുമാനിക്കുന്ന കാലത്തോളം ഈ ഉമ്മത് നന്മയിലായിരിക്കും, ആ ബഹുമാനത്തെ പാഴാക്കിയാൽ അവർ നശിക്കും. (ജ)', 'عَيَّاشِ بْنِ أَبِي رَبِيعَةَ الْمَخْزُومِيِّ', 'അയ്യാശിബിൻ അബീ റബീഅതൽ മഖ്സൂമീ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 325, 325, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=74 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 277, 'عَنْ عَبْدِ اللَّهِ بْنِ عَدِيِّ بْنِ الْحَمْرَاءِ رَضِيَ اللهُ عَنْهُ قَالَ: رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ عَلَى نَاقَتِهِ، وَاقِفٌ بِالْحَزْوَرَةِ يَقُولُ: "وَاللَّهِ إِنَّكِ لَخَيْرُ أَرْضِ اللَّهِ، وَأَحَبُّ أَرْضِ اللَّهِ إِلَيَّ، لَوْلَا أَنِّي أُخْرِجْتُ مِنْكِ مَا خَرَجْتُ". (ت,جه)', 'അബ്ദുല്ലാഹിബ്നു അദിയ്യുബ്നു ഹംറാഅ്(റ): റസൂൽ(സ) അവിടത്തെ ഒട്ടകപ്പുറത്ത് "ഹസ്വറഃ"യിൽ നിൽക്കുന്നത് ഞാൻ കണ്ടു. റസൂൽ(സ) പറയുന്നുണ്ടായിരുന്നു: "അല്ലാഹുവാണ് സത്യം, നിശ്ചയം നീ അല്ലാഹുവിന്റെ ഗുണമേറിയ ഭൂമിയാണ്. അല്ലാഹുവിന്റെ ഭൂമികളിൽ വെച്ച് എനിക്കേറ്റവും ഇഷ്ടപ്പെട്ടതും നീ തന്നെ, നിന്നിൽ നിന്നും ഞാൻ പുറത്താക്കപ്പെട്ടിട്ടില്ലായിരുന്നുവെങ്കിൽ ഞാൻ ഇവിടെ നിന്ന് പോകുമായിരുന്നില്ല." (തു,ജ)', 'عَبْدِ اللَّهِ بْنِ عَدِيِّ بْنِ الْحَمْرَاءِ', 'അബ്ദുല്ലാഹിബ്നു അദിയ്യുബ്നു ഹംറാഅ്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 325, 325, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=74 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 278, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ دَخَلَ الْكَعْبَةَ هُوَ وَأُسَامَةُ بْنُ زَيْدٍ وَعُثْمَانُ بْنُ طَلْحَةَ الْحَجَبِيُّ وَبِلَالٌ، فَأَغْلَقَهَا عَلَيْهِ، فَمَكَثَ فِيهَا، قَالَ عَبْدُ اللَّهِ بْنُ عُمَرَ: فَسَأَلْتُ بِلَالًا حِينَ خَرَجَ: مَاذَا صَنَعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ فَقَالَ: جَعَلَ عَمُودًا عَنْ يَسَارِهِ وَعَمُودَيْنِ عَنْ يَمِينِهِ وَثَلَاثَةَ أَعْمِدَةٍ وَرَاءَهُ، وَكَانَ الْبَيْتُ يَوْمَئِذٍ عَلَى سِتَّةِ أَعْمِدَةٍ، ثُمَّ صَلَّى. وفي رواية: وَنَسِيتُ أَنْ أَسْأَلَهُ كَمْ صَلَّى. (ق,د,ت,ن)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): റസൂൽ(സ)യും ബിലാൽ(റ)വും ഉസാമതുബ്നു സൈദ്(റ)വും ഉസ്മാനുബ്നു ത്വൽഹ(റ)വും കഅ്ബയുടെ അകത്ത് കയറി. റസൂൽ(സ)ക്ക് വേണ്ടി അവർ കഅ്ബയുടെ വാതിലടച്ചു. റസൂൽ(സ) കഅ്ബയിൽ അൽപ നേരം നിന്നു. അബ്ദുല്ല(റ) പറയുന്നു: ബിലാൽ(റ) പുറത്തു വന്നപ്പോൾ ഞാൻ ചോദിച്ചു: തിരുമേനി(സ) എന്തൊക്കെയാണ് ചെയ്തത്. ബിലാൽ(റ) പറഞ്ഞു: റസൂൽ(സ) ഒരു തൂൺ ഇടതു ഭാഗത്തും രണ്ടെണ്ണം വലത് ഭാഗത്തും മൂന്നെണ്ണം തന്റെ പിന്നിലുമാക്കി. കഅ്ബക്ക് അന്ന് ആറു തൂണുകൾ ഉണ്ടായിരുന്നു. എന്നിട്ട് നിസ്കരിച്ചു. മറ്റൊരു നിവേദനത്തിലുണ്ട്: എത്ര റക്അതാണ് തിരുമേനി(സ) നിസ്കരിച്ചത് എന്ന് ചോദിക്കാൻ ഞാൻ മറന്നു. (ബു,മു,ദ,തു,ന)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 325, 325, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=74 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=4 and h.hadith_no=278), 1, 'وَفِي رِوَايَةٍ: وَنَسِيتُ أَنْ أَسْأَلَهُ كَمْ صَلَّى. (ق,د,ت,ن)', 'മറ്റൊരു നിവേദനത്തിലുണ്ട്: എത്ര റക്അതാണ് തിരുമേനി(സ) നിസ്കരിച്ചത് എന്ന് ചോദിക്കാൻ ഞാൻ മറന്നു. (ബു,മു,ദ,തു,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 279, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ أَدْرَكَ رَمَضَانَ بِمَكَّةَ فَصَامَ، وَقَامَ مِنْهُ مَا تَيَسَّرَ لَهُ، كَتَبَ اللَّهُ لَهُ مِائَةَ أَلْفِ شَهْرِ رَمَضَانَ فِيمَا سِوَاهَا، وَكَتَبَ اللَّهُ لَهُ بِكُلِّ يَوْمٍ عِتْقَ رَقَبَةٍ، وَكُلِّ لَيْلَةٍ عِتْقَ رَقَبَةٍ، وَكُلِّ يَوْمٍ حُمْلَانَ فَرَسٍ فِي سَبِيلِ اللَّهِ، وَفِي كُلِّ يَوْمٍ حَسَنَةً، وَفِي كُلِّ لَيْلَةٍ حَسَنَةً". (جه)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "വല്ലവനും റമളാനിൽ മക്കയിലുണ്ടാവുകയും നോമ്പെടുക്കുകയും കഴിയുന്നത്ര നിസ്കരിക്കുകയും ചെയ്താൽ അതല്ലാത്ത ആയിരം മാസത്തെ നോമ്പിന്റെ പ്രതിഫലം അല്ലാഹു അവനു നൽകും. ഓരോ പകലിനും രാത്രിക്കും ഓരോ അടിമയെ മോചിപ്പിച്ചതിന്റെ പ്രതിഫലവും ഓരോ പകലിനും കുതിരയെ അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ യുദ്ധത്തിനയിച്ചതിന്റെ പ്രതിഫലവും ഓരോ രാപകലിനും ഓരോ നന്മ വീതവും അല്ലാഹു അവന് നൽകും". (ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 325, 326, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=75 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 280, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: دَخَلَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَكَّةَ فِي عُمْرَةِ الْقَضَاءِ وَابْنُ رَوَاحَةَ بَيْنَ يَدَيْهِ يَقُولُ:
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 281, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَمَّا دَخَلَ مَكَّةَ طَافَ بِالْبَيْتِ وَصَلَّى رَكْعَتَيْنِ خَلْفَ الْمَقَامِ، يَعْنِي يَوْمَ الْفَتْحِ. (م,د)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) മക്കയിൽ പ്രവേശിച്ചപ്പോൾ (മക്കാ വിജയ ദിനത്തിൽ) കഅ്ബാലയം പ്രദക്ഷിണം ചെയ്തു. മഖാമിനു പിറകിൽ നിന്ന് രണ്ട് റക്അത് നിസ്കരിക്കുകയും ചെയ്തു. (മു,ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 326, 326, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=77 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 282, 'عن جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُمَا، سُئِلَ: أَيَرْفَعُ الرَّجُلُ يَدَيْهِ إِذَا رَأَى الْبَيْتَ؟ فَقَالَ: حَجَجْنَا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَفَكُنَّا نَفْعَلُهُ. (ت)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): അദ്ദേഹത്തോട് ചോദിക്കപ്പെടുകയുണ്ടായി: കഅ്ബാ ശരീഫ് കണ്ടാൽ കൈ ഉയർത്തേണ്ടതുണ്ടോ? അപ്പോൾ ജാബിറുബ്നു അബ്ദില്ല(റ) പറഞ്ഞു: ഞങ്ങൾ റസൂൽ(സ)യോടൊപ്പം ഹജ്ജ് ചെയ്തിട്ടുണ്ട്. ഞങ്ങൾ, പക്ഷെ, അപ്രകാരം ചെയ്തിട്ടുണ്ടോ. (തു)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 326, 327, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=77 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 283, 'عَنْ عَبْدِاللَّهِ بْنِ أَبِي أَوْفَى رَضِيَ اللهُ عَنْهُ قَالَ: اعْتَمَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَطَافَ بِالْبَيْتِ وَصَلَّى خَلْفَ الْمَقَامِ رَكْعَتَيْنِ، وَمَعَهُ مَنْ يَسْتُرُهُ مِنَ النَّاسِ، فَقَالَ لَهُ رَجُلٌ: أَدَخَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْكَعْبَةَ؟ قَالَ: لَا. (خ)', 'അബ്ദുല്ലാഹിബ്നു അബീഔഫാ(റ): റസൂൽ(സ) ഉംറഃ നിർവ്വഹിച്ചപ്പോൾ കഅ്ബാലയം പ്രദക്ഷിണം ചെയ്യുകയും, ഇബ്റാഹീം മഖാമിന് പിന്നിൽ നിന്ന് രണ്ട് റക്അത്ത് നിസ്കരിക്കുകയും ചെയ്തു. അന്നേരം റസൂൽ(സ)യെ മറച്ചു കൊണ്ട് ജനങ്ങൾ നിൽപുണ്ടായിരുന്നു. അപ്പോൾ, അബീ ഔഫ(റ)വിനോട് ഒരാൾ ചോദിച്ചു: റസൂൽ(സ) കഅബാലയത്തിൽ പ്രവേശിച്ചുവോ? അദ്ദേഹം പറഞ്ഞു: ഇല്ല. (ബു)', 'عَبْدِاللَّهِ بْنِ أَبِي أَوْفَى', 'അബ്ദുല്ലാഹിബ്നു അബീഔഫാ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 327, 327, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=78 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 284, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: خَرَجَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ عِنْدِي وَهُوَ قَرِيرُ الْعَيْنِ، طَيِّبُ النَّفْسِ، ثُمَّ رَجَعَ إِلَيَّ وَهُوَ حَزِينٌ، فَقُلْتُ: يَا رَسُولَ اللَّهِ، خَرَجْتَ مِنْ عِنْدِي وَأَنْتَ قَرِيرُ الْعَيْنِ، وَرَجَعْتَ وَأَنْتَ حَزِينٌ؟ فَقَالَ: "إِنِّي دَخَلْتُ الْكَعْبَةَ، وَوَدِدْتُ أَنِّي لَمْ أَكُنْ فَعَلْتُ، إِنِّي أَخَافُ أَنْ أَكُونَ أَتْعَبْتُ أُمَّتِي مِنْ بَعْدِي". (د,ت,جه)', 'ആഇശ(റ): റസൂൽ(സ) വളരെ പ്രസന്നതയോടെയും സന്തോഷത്തോടെയും എന്റെ അടുത്ത് നിന്ന് പോയി. പക്ഷെ അവിടന്ന് തിരിച്ചു വന്നത് വളരെ ദുഃഖിതനായിട്ടായിരുന്നു. ഞാൻ ചോദിച്ചു: തിരുദൂതരെ, അങ്ങ് വളരെ സന്തോഷത്തോടയാണല്ലോ എന്റെ അടുത്ത് നിന്ന് പോയത്, പക്ഷെ അങ്ങ് മടങ്ങി വന്നത് ദുഃഖിതനായിട്ടാണല്ലോ? റസൂൽ(സ) പറഞ്ഞു: "ഞാൻ കഅ്ബയുടെ ഉള്ളിൽ കയറി. ഞാൻ അങ്ങനെ ചെയ്തില്ലായിരുന്നുവെങ്കിൽ എന്ന് ഞാൻ ആഗ്രഹിക്കുന്നു. കാരണം എനിക്ക് ശേഷം എന്റെ സമുദായം ഞാൻ കാരണം ക്ഷീണിക്കലിനെ ഞാൻ ഭയക്കുന്നു." (ദ,തു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 327, 327, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=78 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 285, 'عن صَفِيَّةَ بِنْتِ شَيْبَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: سَمِعْتُ الْأَسْلَمِيَّةَ تَقُولُ: قُلْتُ لِعُثْمَانَ رَضِيَ اللهُ عَنْهُ: مَا قَالَ لَكَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ دَعَاكَ؟ قَالَ: قَالَ: "إِنِّي نَسِيتُ أَنْ آمُرَكَ أَنْ تُخَمِّرَ الْقَرْنَيْنِ، فَإِنَّهُ لَيْسَ يَنْبَغِي أَنْ يَكُونَ فِي الْبَيْتِ شَيْءٌ يَشْغَلُ الْمُصَلِّيَ". (د)', 'സ്വഫിയ്യ ബിൻത് ശൈബ(റ): അൽഅസ്ലമിയ്യത്(റ) പറയുന്നത് ഞാൻ കേട്ടു: ഞാൻ ഉസ്മാൻ(റ)വിനോട് ചോദിച്ചു: നിങ്ങളെ വിളിച്ചിട്ട് റസൂൽ(സ) എന്താണ് പറഞ്ഞത്? ഉസ്മാൻ(റ) പറഞ്ഞു: തിരുമേനി(സ) പറഞ്ഞു: "രണ്ട് ആടിന്റെ കൊമ്പുകൾ മറക്കണമെന്ന് നിങ്ങളോട് പറയാൻ ഞാൻ മറന്നു പോയി. നിസ്കരിക്കുന്നവന്റെ ശ്രദ്ധ തെറ്റിക്കുന്ന ഒന്നും കഅ്ബയിൽ ഉണ്ടാവുന്നത് ഉചിതമല്ല." (ദ)', 'صَفِيَّةَ بِنْتِ شَيْبَةَ', 'സ്വഫിയ്യ ബിൻത് ശൈബ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 327, 327, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=78 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 286, 'عَنِ الزُّبَيْرِ رَضِيَ اللهُ عَنْهُ قَالَ: لَمَّا أَقْبَلْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ لِيَّةَ، حَتَّى إِذَا كُنَّا عِنْدَ السِّدْرَةِ وَقَفَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي طَرَفِ الْقَرْنِ الْأَسْوَدِ حَذْوَهَا، فَاسْتَقْبَلَ نَخِبًا بِبَصَرِهِ - وفي رواية: وَادِيَهُ - وَوَقَفَ حَتَّى اتَّقَفَ النَّاسُ كُلُّهُمْ، ثُمَّ قَالَ: "إِنَّ صَيْدَ وَجٍّ وَعِضَاهَهُ حَرَامٌ مُحَرَّمٌ لِلَّهِ". وَذَلِكَ قَبْلَ نُزُولِهِ الطَّائِفَ وَحِصَارِهِ لِثَقِيفٍ. (د)', 'സുബൈർ(റ): ഞങ്ങൾ റസൂൽ(സ)യോട്കുടെ ലിയ്യിൽ നിന്ന് വരികയായിരുന്നു. കള്ളിമുൾച്ചെടിയുടെ അടുത്ത് എത്തിയപ്പോൾ ചെടിയിലേക്ക് തിരിഞ്ഞ് ''ഖറനുൽഅസ്വദി''ന്റെ അറ്റത്ത് നിന്നു. റസൂൽ(സ) നഖ്ബിനെ അല്ലെങ്കിൽ തന്റെ മലഞ്ചെരുവിനെ നോക്കി. ജനങ്ങൾ മുഴുവനും നിൽക്കുന്നത് വരെ തിരുമേനി(സ) നിന്നു. എന്നിട്ട് പറഞ്ഞു: "ഹജ്ജിൽ വേട്ടയാടലും അവിടത്തെ മരങ്ങൾ മുറിക്കലും നിഷിദ്ധമാണ്. അല്ലാഹു നിഷിദ്ധമാക്കിയതാണ്." ഇത് റസൂൽ(സ) താഇഫിലിറങ്ങുകയും സഖീഫുകാരെ ഉപരോധിക്കുകയും ചെയ്യുന്നതിന്റെ മുമ്പാണ്. (ദ)', 'الزُّبَيْرِ', 'സുബൈർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 327, 328, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=78 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=4 and h.hadith_no=286), 1, 'وَفِي رِوَايَةٍ: وَادِيَهُ - وَوَقَفَ حَتَّى اتَّقَفَ النَّاسُ كُلُّهُمْ، ثُمَّ قَالَ: "إِنَّ صَيْدَ وَجٍّ وَعِضَاهَهُ حَرَامٌ مُحَرَّمٌ لِلَّهِ". وَذَلِكَ قَبْلَ نُزُولِهِ الطَّائِفَ وَحِصَارِهِ لِثَقِيفٍ. (د)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 287, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَمَّا قَدِمَ مَكَّةَ أَبَى أَنْ يَدْخُلَ الْبَيْتَ وَفِيهِ الْآلِهَةُ، فَأَمَرَ بِهَا فَأُخْرِجَتْ، قَالَ: فَأُخْرِجَ صُورَةُ إِبْرَاهِيمَ وَإِسْمَعِيلَ عليهما السلام، وَفِي أَيْدِيهِمَا الْأَزْلَامُ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "قَاتَلَهُمُ اللَّهُ، وَاللَّهِ لَقَدْ عَلِمُوا مَا اسْتَقْسَمَا بِهَا قَطُّ". قَالَ: ثُمَّ دَخَلَ الْبَيْتَ، فَكَبَّرَ فِي نَوَاحِيهِ، وَفِي زَوَايَاهُ، ثُمَّ خَرَجَ وَلَمْ يُصَلِّ فِيهِ. (خ,د)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) മക്കയിൽ വന്നപ്പോൾ കഅബാലയത്തിൽ കടക്കാൻ വിസമ്മതിച്ചു. കാരണം അതിനുള്ളിൽ ബിംബങ്ങളുണ്ടായിരുന്നു. റസൂൽ(സ)യുടെ കൽപ്പനപ്രകാരം അവയെല്ലാം പുറത്തെടുക്കപ്പെട്ടു. ഇബ്നുഅബ്ബാസ്(റ) പറയുന്നു: കൂട്ടത്തിൽ ഇബ്റാഹീം(അ), ഇസ്മാഈൽ(അ) എന്നിവരുടെ രൂപങ്ങളും പുറത്തെടുക്കപ്പെട്ടു. അവരുടെ കൈകളിൽ പ്രശ്നം നോക്കുന്ന അമ്പുമുണ്ടായിരുന്നു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അവരെ അല്ലാഹു നശിപ്പിക്കട്ടെ, ഈ രണ്ടുപേരും ഈ വസ്തുവുമായി, ഒരിക്കലും സത്യം ചെയ്തിട്ടില്ലെന്ന് അവർക്കറിയാം". ഇബ്നുഅബ്ബാസ്(റ) പറയുന്നു: പിന്നീട് റസൂൽ(സ) കഅബാലയത്തിൽ പ്രവേശിക്കുകയും, അതിന്റെ പല ഭാഗങ്ങളിലും, മൂലകളിലും തക്ബീർ മുഴക്കുകയും ചെയ്തു. പക്ഷെ അവിടെ നിസ്കരിച്ചില്ല. (ബു,ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ','د']::text[], array['ബു','ദ']::text[], null, null, 328, 328, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=79 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 288, 'عَنْ عَبْدِ الرَّحْمَنِ بْنِ صَفْوَانَ رَضِيَ اللهُ عَنْهُمَا قَالَ: قُلْتُ لِعُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ: كَيْفَ صَنَعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ دَخَلَ الْكَعْبَةَ؟ قَالَ: صَلَّى رَكْعَتَيْنِ. (د)', 'അബ്ദുർറഹ്മാനുബ്നു സ്വഫ്വാൻ(റ): ഞാൻ ഉമർ(റ)വിനോട് ചോദിച്ചു: കഅ്ബയുടെ അകത്ത് കടന്ന് റസൂൽ(സ) എന്താണ് ചെയ്തത്? ഉമർ(റ) പറഞ്ഞു: രണ്ട് റക്അത്ത് നിസ്കരിച്ചു. (ദ)', 'عَبْدِ الرَّحْمَنِ بْنِ صَفْوَانَ', 'അബ്ദുർറഹ്മാനുബ്നു സ്വഫ്വാൻ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 328, 328, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=79 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 289, 'عَنِ ابْنِ عُمَرَ، عَنْ بِلَالٍ، رَضِيَ اللهُ عَنْهُم: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَّى فِي جَوْفِ الْكَعْبَةِ. قَالَ ترمذي هذا حَدِيثٌ حَسَنٌ صَحِيحٌ. (ت)', 'ഇബ്നുഉമർ(റ) ബിലാൽ(റ)വിൽ നിന്ന് നിവേദനം ചെയ്യുന്നു: നിശ്ചയം റസൂൽ(സ) കഅ്ബയുടെ ഉള്ളിൽ വെച്ച് നിസ്കരിച്ചു. (തു)', 'ابْنِ عُمَرَ، عَنْ بِلَالٍ،', 'ഇബ്നുഉമർ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 328, 328, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=79 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 290, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: دَخَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْكَعْبَةَ وَدَنَا خُرُوجُهُ وَوَجَدْتُ شَيْئًا، فَذَهَبْتُ وَجِئْتُ سَرِيعًا، فَوَجَدْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَارِجًا، فَسَأَلْتُ بِلَالًا: أَصَلَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الْكَعْبَةِ؟ قَالَ: نَعَمْ، رَكْعَتَيْنِ بَيْنَ السَّارِيَتَيْنِ. (ن)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) കഅ്ബാലയത്തിനുള്ളിൽ പ്രവേശിക്കുകയും പുറത്ത് വരാൻ അടുക്കുകയും ചെയ്തു. എനിക്കന്നേരം ഒരാവശ്യം നേരിടുകയും ഞാൻ അതിനു വേണ്ടി പോവുകയും വേഗത്തിൽ തരിച്ചു വരികയും ചെയ്തു. അപ്പോൾ റസൂൽ(സ) പുറത്ത് വരുന്നുണ്ട്. ഞാനുടൻ ബിലാൽ(റ)വിനോട് ചോദിച്ചു. റസൂൽ(സ) കഅ്ബാലയത്തിനുള്ളിൽ വെച്ച് നിസ്കരിച്ചുവോ? ബിലാൽ(റ) പറഞ്ഞു: അതെ, രണ്ടു തൂണുകൾക്കിടയിൽ വെച്ച് രണ്ട് റക്അത്ത് നിസ്കരിച്ചു. (ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 328, 328, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=79 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 291, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّهُ أَتِي فِي مَنْزِلِهِ، فَقِيلَ: هَذَا رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ قَدْ دَخَلَ الْكَعْبَةَ، فَأَقْبَلْتُ فَأَجِدُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَدْ خَرَجَ، وَأَجِدُ بِلَالًا عَلَى الْبَابِ قَائِمًا، فَقُلْتُ: يَا بِلَالُ، أَصَلَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الْكَعْبَةِ؟ قَالَ: نَعَمْ. قُلْتُ: أَيْنَ؟ قَالَ: مَا بَيْنَ هَاتَيْنِ الْأُسْطُوَانَتَيْنِ رَكْعَتَيْنِ، ثُمَّ خَرَجَ فَصَلَّى رَكْعَتَيْنِ فِي وَجْهِ الْكَعْبَةِ. (ن)', 'ഇബ്നുഉമർ(റ): അദ്ദേഹം തന്റെ ഭവനത്തിൽ വന്നു. റസൂൽ(സ) കഅബാലയത്തിൽ പ്രവേശിച്ചിട്ടുണ്ടെന്ന് പറയപ്പെട്ടു. ഞാനങ്ങോട്ട് ചെന്നപ്പോൾ റസൂൽ(സ) പുറത്ത് വന്നിരുന്നു. വാതിൽപ്പടിയിൽ ബിലാൽ(റ) നിൽക്കുന്നതായി കണ്ടു. ഞാൻ ബിലാൽ(റ)വിനോട് ചോദിച്ചു: റസൂൽ(സ) കഅ്ബാലയത്തിനുള്ളിൽ വെച്ച് നിസ്കരിച്ചുവോ? അദ്ദേഹം പറഞ്ഞു: അതെ. ഞാൻ ചോദിച്ചു: എവിടെ വെച്ച്? അദ്ദേഹം പറഞ്ഞു: ഈ കാണുന്ന തൂണുകൾക്കിടയിൽ വെച്ചും പിന്നീട് അവിടെ നിന്നും പുറപ്പെട്ട് കഅബാലയ മുഖത്ത് വെച്ചും രണ്ട് റക്അത്ത് നിസ്കരിച്ചു. (ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 329, 329, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=79 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 292, 'عَنْ صَفِيَّةَ بِنْتِ شَيْبَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: سَمِعْتُ الْأَسْلَمِيَّةَ تَقُولُ: قُلْتُ لِعُثْمَانَ رَضِيَ اللهُ عَنْهُ: مَا قَالَ لَكَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ دَعَاكَ؟ قَالَ: قَالَ: "إِنِّي نَسِيتُ أَنْ آمُرَكَ أَنْ تُخَمِّرَ الْقَرْنَيْنِ، فَإِنَّهُ لَيْس يَنْبَغِي أَنْ يَكُونَ فِي الْبَيْتِ شَيْءٌ يَشْغَلُ الْمُصَلِّيَ". (د)', 'സ്വഫിയ്യ ബിൻത് ശൈബ(റ): അൽഅസ്‌ലമിയ്യത്(റ) പറയുന്നതായി മഹതി കേട്ടു: ഞാൻ ഉസ്മാൻ(റ)വിനോട് ചോദിച്ചു: നിങ്ങളെ വിളിച്ചിട്ട് റസൂൽ(സ) എന്താണ് പറഞ്ഞത്? ഉസ്മാൻ(റ) പറഞ്ഞു: തിരുമേനി(സ) പറഞ്ഞു: "രണ്ട് ആടിന്റെ കൊമ്പുകൾ മറക്കണമെന്നത് നിങ്ങളോട് പറയാൻ ഞാൻ മറന്നു പോയി. നിസ്കരിക്കുന്നവന്റെ ശ്രദ്ധ തെറ്റിക്കുന്ന ഒന്നും കഅ്ബയിൽ ഉണ്ടാവുന്നത് ഉചിതമല്ല." (ദ)', 'صَفِيَّةَ بِنْتِ شَيْبَةَ', 'സ്വഫിയ്യ ബിൻത് ശൈബ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 329, 329, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=79 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 293, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كُنْتُ أُحِبُّ أَنْ أَدْخُلَ الْبَيْتَ فَأُصَلِّيَ فِيهِ، فَأَخَذَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِيَدِي فَأَدْخَلَنِي الْحِجْرَ، فَقَالَ: "صَلِّي فِي الْحِجْرِ إِنْ أَرَدْتِ دُخُولَ الْبَيْتِ، فَإِنَّمَا هُوَ قِطْعَةٌ مِنَ الْبَيْتِ، وَلَكِنَّ قَوْمَكِ اسْتَقْصَرُوهُ حِينَ بَنَوُا الْكَعْبَةَ، فَأَخْرَجُوهُ مِنَ الْبَيْتِ". قَالَ ترمذي هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ. (د,ت,ن)', 'ആഇശ(റ): കഅ്ബയുടെ ഉള്ളിൽ കയറി നിസ്കരിക്കാൻ ഞാൻ അതിയായി ആഗ്രഹിച്ചിരുന്നു. അപ്പോൾ തിരുമേനി(സ) എന്റെ കൈ പിടിച്ചു ''ഹിജ്റി''ൽ പ്രവേശിപ്പിച്ചു. എന്നിട്ട് പറഞ്ഞു: "കഅ്ബയിൽ പ്രവേശിക്കാൻ നീ ആഗ്രഹിക്കുന്നുവെങ്കിൽ ''ഹിജ്റി''ൽ വെച്ച് നിസ്കരിക്കുക. തീർച്ചയായും അത് കഅ്ബയിൽ പെട്ടതാണ്. പക്ഷെ, നിന്റെ സമൂഹം കഅ്ബ പുതുക്കി പണിതപ്പോൾ കഅ്ബ ചെറുതാക്കിപ്പണിയാൻ നിർബന്ധിതരായി. അപ്പോൾ അവർ ''ഹിജ്റി''നെ പുറത്താക്കി കഅ്ബ പണിതു." (ദ,ന,തു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د','ت','ن']::text[], array['ദ','ന','തു']::text[], null, null, 329, 329, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=80 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 294, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قُلْتُ: يَا رَسُولَ اللَّهِ، أَلَا أَدْخُلُ الْبَيْتَ؟ قَالَ: "ادْخُلِي الْحِجْرَ، فَإِنَّهُ مِنَ الْبَيْتِ". (ن)', 'ആഇശ(റ): അവിടുന്ന് പറയുന്നു: ഞാൻ റസൂൽ(സ)യോടു ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരെ, ഞാൻ കഅ്ബാലയത്തിൽ പ്രവേശിക്കട്ടെയോ? റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ ഹിജ്റിൽ പ്രവേശിക്കുക. നിശ്ചയമത് കഅ്ബയിൽ പെട്ടതാണ്." (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 329, 329, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=80 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 295, 'عَنْ أُسَامَةَ بْنِ زَيْدٍ رَضِيَ اللهُ عَنْهُ: أَنَّهُ دَخَلَ هُوَ وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْبَيْتَ، فَأَمَرَ بِلَالًا فَأَجَافَ الْبَابَ، وَالْبَيْتُ إِذْ ذَاكَ عَلَى سِتَّةِ أَعْمِدَةٍ، فَمَضَى حَتَّى إِذَا كَانَ بَيْنَ الْأُسْطُوَانَتَيْنِ اللَّتَيْنِ تَلِيَانِ بَابَ الْكَعْبَةِ جَلَس، فَحَمِدَ اللَّهَ وَأَثْنَى عَلَيْهِ، وَسَأَلَهُ وَاسْتَغْفَرَهُ، ثُمَّ قَامَ حَتَّى أَتَى مَا اسْتَقْبَلَ مِنْ دُبُرِ الْكَعْبَةِ فَوَضَعَ وَجْهَهُ وَخَدَّهُ عَلَيْهِ، وَحَمِدَ اللَّهَ وَأَثْنَى عَلَيْهِ وَسَأَلَهُ وَاسْتَغْفَرَهُ، ثُمَّ انْصَرَفَ إِلَى كُلِّ رُكْنٍ مِنْ أَرْكَانِ الْكَعْبَةِ فَاسْتَقْبَلَهُ بِالتَّكْبِيرِ وَالتَّهْلِيلِ وَالتَّسْبِيحِ وَالثَّنَاءِ عَلَى اللَّهِ وَالْمَسْأَلَةِ وَالِاسْتِغْفَارِ، ثُمَّ خَرَجَ فَصَلَّى رَكْعَتَيْنِ مُسْتَقْبِلَ وَجْهِ الْكَعْبَةِ، ثُمَّ انْصَرَفَ فَقَالَ: "هَذِهِ الْقِبْلَةُ، هَذِهِ الْقِبْلَةُ". (ن)', 'ഉസാമത്തുബ്നു സൈദ്(റ): നിശ്ചയം അദ്ദേഹവും റസൂൽ(സ)യും കഅ്ബാലയത്തിനുള്ളിൽ പ്രവേശച്ചു. അപ്പോൾ റസൂൽ(സ)യുടെ കൽപ്പനപ്രകാരം ബിലാൽ(റ) വാതിലടച്ചു. അന്നേരം കഅ്ബാലയം ആറു തൂണുകളിലാണ് നിന്നിരുന്നത്. ശേഷം കഅബാലയ വാതിലിനോട് ചേർന്നു നിൽക്കുന്ന രണ്ട് തൂണിന്റെയടുത്തെത്തിയപ്പോൾ അവിടെയിരുന്ന് നാഥനെ സ്തുതിക്കുകയും, പുകഴ്ത്തുകയും പൊറുക്കലിനെ തേടുകയും ആവശ്യമായത് ചോദിക്കുകയും ചെയ്തു. പിന്നീട് എണീറ്റു കഅബാലയത്തിന്റെ പിൻഭാഗത്തേക്ക് നിൽക്കുന്ന ഭാഗത്തേക്ക് ചെന്ന് മുഖവും കവിളും അതിനോട് ചേർത്ത് വെച്ചു. അല്ലാഹുവിനെ സ്തുതിക്കുകയും, പുകഴ്ത്തുകയും, ആവശ്യങ്ങൾ ചോദിക്കുകയും, പൊറുക്കലിനെ തേടുകയും ചെയ്തു. ശേഷം കഅ്ബാലയത്തിന്റെ എല്ലാ റുക്നുകളിലേക്കും തിരിഞ്ഞ് തക്ബീറും, തസ്ബീഹും, തഹ്‌ലീലും ചൊല്ലി, അല്ലാഹുവിനെ പുകഴ്ത്തി, ആവശ്യമായവ ചോദിക്കുകയും, പൊറുക്കലിനെ തേടുകയും ചെയ്തു. പിന്നീട് പുറത്ത് വരികയും, കഅ്ബാലയ മുഖത്തോട് ചേർന്ന് രണ്ട് റക്അത്ത് നിസ്കരിക്കുകയും ചെയ്ത ശേഷം അവിടെ നിന്നും തിരഞ്ഞു. എന്നിട്ട് പറഞ്ഞു: "ഇതാണ് ഖിബ്‌ല, ഇതാണ് ഖിബ്‌ല." (ന)', 'أُسَامَةَ بْنِ زَيْدٍ', 'ഉസാമത്തുബ്നു സൈദ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 330, 330, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=81 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 296, 'عَنْ شَقِيقِ بْنِ سَلَمَةَ الْأَسَدِي قَالَ: بَعَثَ رَجُلٌ مَعِي بِدَرَاهِم هَدِيَّةً إِلَى الْبَيْتِ، قَالَ: فَدَخَلْتُ الْبَيْتَ وَشَيْبَةُ جَالِسٌ عَلَى كُرْسِيٍّ، فَنَاوَلْتُهُ إِيَّاهَا. فَقَالَ لَهُ: أَلَكَ هَذِهِ؟ قُلْتُ: لَا، وَلَوْ كَانَتْ لِي لَمْ آتِكَ بِهَا. قَالَ: أَمَا لَئِنْ قُلْتَ ذَلِكَ، لَقَدْ جَلَسَ عُمَرُ بْنُ الْخَطَّابِ مَجْلِسَكَ الَّذِي جَلَسْتَ فِيهِ، فَقَالَ: لَا أَخْرُجُ حَتَّى أَقْسِمَ مَالَ الْكَعْبَةِ بَيْنَ فُقَرَاءِ الْمُسْلِمِينَ. قُلْتُ: مَا أَنْتَ فَاعِلٌ. قَالَ: لَأَفْعَلَنَّ. قَالَ: وَلِمَ ذَاكَ؟ قُلْتُ: لِأَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَدْ رَأَى مَكَانَهُ، وَأَبُو بَكْرٍ، وَهُمَا أَحْوَجُ مِنْكَ إِلَى الْمَالِ، فَلَمْ يُحَرِّكَاهُ. فَقَامَ كَمَا هُوَ، فَخَرَجَ. (خ,د,جه)', 'ശഖീഖ്(റ): കഅ്ബയിലേക്ക് ഹദ്‌യയായി കുറച്ച് ദിർഹം ഒരാൾ എന്റെ വശം തന്നയച്ചു. അങ്ങനെ ഞാൻ മസ്ജിദുൽ ഹറാമിൽ പ്രവേശിച്ചു. ശൈബ(റ) തന്റെ കസേരയിൽ അവിടെ ഇരിക്കുന്നുണ്ടായിരുന്നു. ഞാനത് ശൈബ(റ)നെ ഏൽപ്പിച്ചു. ശൈബ(റ) ചോദിച്ചു: ഇതു നിങ്ങളുടേതാണോ? ഞാൻ പറഞ്ഞു: അല്ല, അത് എന്റേത് ആയിരുന്നുവെങ്കിൽ ഞാനതുമായി നിങ്ങളുടെ അടുത്ത് വരുമായിരുന്നില്ല. അപ്പോൾ ശൈബ(റ) പറഞ്ഞു: നിങ്ങളങ്ങനെ പറയുകയാണെങ്കിൽ, നിങ്ങൾ ഇരിക്കുന്ന സ്ഥലത്തിരുന്ന് ഉമർ(റ) പറഞ്ഞു: കഅ്ബയുടെ സമ്പത്ത് ദരിദ്രരായ മുസ്‌ലിംകൾക്ക് വീതിച്ചു നൽകാതെ ഞാൻ ഇവിടെ നിന്നും പോവുകയില്ല. ഞാൻ (ശൈബ(റ) പറഞ്ഞു: നിങ്ങൾ അത് ചെയ്യുകയില്ല. ഉമർ(റ) പറഞ്ഞു: ഞാൻ അത് ചെയ്യുക തന്നെ ചെയ്യും. നിങ്ങളെന്തുകൊണ്ടാണ് അങ്ങനെ പറയുന്നത്? ഞാൻ പറഞ്ഞു: റസൂൽ(സ)യും അബൂബക്കർ(റ)വും ആ സ്ഥലം കണ്ടിട്ടുണ്ട്. അവർ രണ്ട് പേരും നിങ്ങളേക്കാൾ സമ്പത്തിന് ആവശ്യമുള്ളവരായിരുന്നു. അവരത് പക്ഷെ പുറത്തെടുത്തില്ല. അപ്പോൾ ഉമർ(റ) അതു പോലെ എഴുന്നേറ്റു പോയി. (ബു,ദ,ജ)', 'شَقِيقِ بْنِ سَلَمَةَ الْأَسَدِي قَالَ', 'ശഖീഖ്(റ)', null, null, array['خ','د','جه']::text[], array['ബു','ദ','ജ']::text[], null, null, 330, 331, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=82 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 297, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: سَأَلْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْجَدْرِ، أَمِنَ الْبَيْتِ هُوَ؟ قَالَ: "نَعَمْ". قُلْتُ: فَلِمَ لَمْ يُدْخِلُوهُ فِي الْبَيْتِ؟ قَالَ: "إِنَّ قَوْمَكِ قَصَّرَتْ بِهِمُ النَّفَقَةُ". قُلْتُ: فَمَا شَأْنُ بَابِه مُرْتَفِعًا؟ قَالَ: "فَعَلَ ذَلِكِ قَوْمُكِ لِيُدْخِلُوا مَنْ شَاءُوا وَيَمْنَعُوا مَنْ شَاءُوا، وَلَوْلَا أَنَّ قَوْمَكِ حَدِيثٌ عَهْدُهُمْ فِي الْجَاهِلِيَّةِ، فَأَخَافُ أَنْ تُنْكِرَ قُلُوبُهُمْ، لَنَظَرْتُ أَنْ أُدْخِلَ الْجَدْرَ فِي الْبَيْتِ، وَأَنْ أُلْزِقَ بَابَهُ بِالْأَرْضِ. (م)', 'ആഇശ(റ): ഞാനൊരിക്കൽ റസൂൽ(സ)യോട് ചോദിച്ചു: ഹജറുൽ അസ്‌വദ് കഅ്ബയിൽ പെട്ടതാണോ? തിരുമേനി(സ) അരുളി: അതെ, ഞാൻ ചോദിച്ചു: എങ്കിൽ എന്തുകൊണ്ട് അവർ അത് കഅ്ബയിൽ ഉൾപ്പെടുത്തിയില്ല. തിരുമേനി(സ)പറഞ്ഞു: "നന്റെ ജനങ്ങള്ളുടെ പക്കൽ അത് പൂർണ്ണമായി നിർമ്മിക്കാൻ വേണ്ട സമ്പത്തുണ്ടായിരുന്നില്ല". ഞാൻ ചോദിച്ചു: അതിന്റെ വാതിൽ എന്തുകൊണ്ടാണ് ഇത്രയധികം ഉയരത്തിൽ സ്ഥിതിചെയ്യുന്നത്? തിരുമേനി(സ) അരുളി: "തങ്ങളുദ്ദേശിക്കുന്നവരെ പ്രവേശിപ്പിക്കുവാനും, അല്ലാത്തവരെ തടയാനും വേണ്ടി നിന്റെ ജനങ്ങൾ ചെയ്തതാണത്. നിന്റെ ജനങ്ങൾ അജ്ഞാനകാലത്തോടടുത്തവരായിരുന്നില്ലെങ്കിൽ, അവരുടെ ഹൃദയങ്ങളിൽ പ്രതിഷേധം ഉണ്ടാകുമെന്ന് ഞാൻ ഭയപ്പെടുകയും ചെയ്തിരുന്നില്ലെങ്കിൽ ഹജറുൽ അസ്‌വദ് അതിൽ ഉൾപ്പെടുത്തുവാനും, അതിന്റെ വാതിൽ നിലത്തോടടുപ്പിച്ചു വെക്കുവാനും ഞാൻ (ശ്രമിച്ചു) നോക്കുമായിരുന്നു". (മു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 331, 331, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=83 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 298, 'عَنْ عَطَاءِ قَالَ: لَمَّا احْتَرَقَ الْبَيْتُ زَمَنَ يَزِيدَ بْنِ مُعَاوِيَةَ حِينَ غَزَاهَا أَهْلُ الشَّامِ، فَكَانَ مِنْ أَمْرِهِ مَا كَانَ، تَرَكَهُ ابْنُ الزُّبَيْرِ حَتَّى قَدِمَ النَّاسُ الْمَوْسِمَ يُرِيدُ أَنْ يُجَرِّئَهُمْ - أَوْ يُحَرِّبَهُمْ - عَلَى أَهْلِ الشَّامِ، فَلَمَّا صَدَرَ النَّاسُ قَالَ: يَا أَيُّهَا النَّاسُ أَشِيرُوا عَلَيَّ فِي الْكَعْبَةِ، أَنْقُضُهَا ثُمَّ أَبْنِي بِنَاءَهَا، أَوْ أُصْلِحُ مَا وَهَى مِنْهَا؟ قَالَ ابْنُ عَبَّاسٍ: فَإِنِّي قَدْ فُرِقَ لِي رَأْيٌ فِيهَا، أَرَى أَنْ تُصْلِحَ مَا وَهَى مِنْهَا، وَتَدَعَ بَيْتًا أَسْلَمَ النَّاسُ عَلَيْهِ، وَأَحْجَارًا أَسْلَمَ النَّاسُ عَلَيْهَا، وَبُعِثَ عَلَيْهَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. فَقَالَ ابْنُ الزُّبَيْرِ: لَوْ كَانَ أَحَدُكُمُ احْتَرَقَ بَيْتُهُ مَا رَضِيَ حَتَّى يُجِدَّهُ، فَكَيْفَ بَيْتُ رَبِّكُمْ؟ إِنِّي مُسْتَخِيرٌ رَبِّي ثَلَاثًا، ثُمَّ عَازِمٌ عَلَى أَمْرِي. فَلَمَّا مَضَى الثَّلَاثُ أَجْمَعَ رَأْيَهُ عَلَى أَنْ يَنْقُضَهَا، فَتَحَامَاهُ النَّاسُ أَنْ يَنْزِلَ بِأَوَّلِ النَّاسِ يَصْعَدُ فِيهِ أَمْرٌ مِنَ السَّمَاءِ، حَتَّى صَعِدَهُ رَجُلٌ فَأَلْقَى مِنْهُ حِجَارَةً، فَلَمَّا لَمْ يَرَهُ النَّاسُ أَصَابَهُ شَيْءٌ تَتَابَعُوا فَنَقَضُوهُ حَتَّى بَلَغُوا بِهِ الْأَرْضَ، فَجَعَلَ ابْنُ الزُّبَيْرِ أَعْمِدَةً فَسَتَّرَ عَلَيْهَا السُّتُورَ حَتَّى ارْتَفَعَ بِنَاؤُهُ. وَقَالَ ابْنُ الزُّبَيْرِ: إِنِّي سَمِعْتُ عَائِشَةَ تَقُولُ إِنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَوْلَا أَنَّ النَّاسَ حَدِيثٌ عَهْدُهُمْ بِكُفْرٍ، وَلَيْسَ عِنْدِي مِنَ النَّفَقَةِ مَا يُقَوِّي عَلَى بِنَائِهِ، لَكُنْتُ أَدْخَلْتُ فِيهِ مِنَ الْحِجْرِ خَمْسَ أَذْرُعٍ، وَلَجَعَلْتُ لَهَا بَابًا يَدْخُلُ النَّاسُ مِنْهُ، وَبَابًا يَخْرُجُونَ مِنْهُ". قَالَ: فَأَنَا الْيَوْمَ أَجِدُ مَا أُنْفِقُ، وَلَسْتُ أَخَافُ النَّاسَ. قَالَ: فَزَادَ فِيهِ خَمْسَ أَذْرُعٍ مِنَ الْحِجْرِ حَتَّى أَبْدَى أُسًّا نَظَرَ النَّاسُ إِلَيْهِ فَبَنَى عَلَيْهِ الْبِنَاءَ، وَكَانَ طُولُ الْكَعْبَةِ ثَمَانِيَ عَشْرَةَ ذِرَاعًا، فَلَمَّا زَادَ فِيهِ اسْتَقْصَرَهُ، فَزَادَ فِي طُولِهِ عَشْرَ أَذْرُعٍ، وَجَعَلَ لَهُ بَابَيْنِ أَحَدُهُمَا يُدْخَلُ مِنْهُ وَالْآخَرُ يُخْرَجُ مِنْهُ، فَلَمَّا قُتِلَ ابْنُ الزُّبَيْرِ كَتَبَ الْحَجَّاجُ إِلَى عَبْدِ الْمَلِكِ بْنِ مَرْوَانَ يُخْبِرُهُ بِذَلِكَ، وَيُخْبِرُهُ أَنَّ ابْنَ الزُّبَيْرِ قَدْ وَضَعَ الْبِنَاءَ عَلَى أُسٍّ نَظَرَ إِلَيْهِ الْعُدُولُ مِنْ أَهْلِ مَكَّةَ، فَكَتَبَ إِلَيْهِ عَبْدُ الْمَلِكِ: إِنَّا لَسْنَا مِنْ تَلْطِيخِ ابْنِ الزُّبَيْرِ فِي شَيْءٍ، أَمَّا مَا زَادَ فِي طُولِهِ فَأَقِرَّهُ، وَأَمَّا مَا زَادَ فِيهِ مِنَ الْحِجْرِ فَرُدَّهُ إِلَى بِنَائِهِ، وَسُدَّ الْبَابَ الَّذِي فَتَحَهُ. فَنَقَضَهُ وَأَعَادَهُ إِلَى بِنَائِهِ. (م)', 'അത്വാഅ്(റ): മുആവിയ(റ)വിന്റെ മകൻ യസീദിന്റെ ഭരണകാലത്ത്, ശാമുകാർ കഅ്ബയോട് യുദ്ധം ചെയ്യുകയും അതിനു കേടുപാടുകൾ സംഭവിക്കുകയും ചെയ്തപ്പോൾ, ജനങ്ങളെ ശാമുകാർക്കെതിരിൽ ഇളക്കിവിടാനും യുദ്ധത്തിനുള്ള പ്രചോദനം നൽകുവാനുമുദ്ദേശിച്ചുകൊണ്ട്, ജനങ്ങൾ തീർത്ഥാടന സ്ഥലത്ത് വന്ന് തടിച്ചു കൂടുന്നതുവരെ ഇബ്നുസുബൈർ(റ) കഅ്ബയെ കേടുപാടുകൾ തീർക്കാതെ വിട്ടു. അങ്ങനെ ജനങ്ങൾ എത്തിയപ്പോൾ ഇബ്നു സുബൈർ(റ) പറഞ്ഞു: ഹേ ജനങ്ങളേ! കഅ്ബയുടെ കാര്യത്തിൽ നിങ്ങളുടെ അഭിപ്രായം നിങ്ങൾ എന്നോട് പറയുക. ഞാൻ അത് പൊളിച്ച് പുതുക്കിപ്പണിയുകയാണോ അതോ അതിന്റെ ദുർബ്ബലമായ ഭാഗങ്ങൾ നന്നാക്കുകയാണോ ചെയ്യേണ്ടത്?. (അന്നേരം) ഇബ്നുഅബ്ബാസ്(റ) പറഞ്ഞു: നിങ്ങൾ അതിൽ നിന്ന് ദുർബ്ബലമായത് അഥവാ കേടുപാടുകൾ നന്നാക്കുകയും, ആ ഭവനം ഏത് അവസ്ഥയിൽ സ്ഥിതി ചെയ്തപ്പോൾ ജനങ്ങൾ ഇസ്‌ലാം മതം സ്വീകരിച്ചുവോ, ഏതു തരത്തിലുള്ള കല്ലുകൾ കൊണ്ട് നിർമ്മിക്കപ്പെട്ട അവസ്ഥയിൽ ജനങ്ങൾ ഇസ്‌ലാം ആശ്ലേഷിച്ചുവോ, ഏത് അവസ്ഥയിൽ സ്ഥിതി ചെയ്തപ്പോൾ മുഹമ്മദ്(സ) നിയോഗിക്കപ്പെട്ടുവോ അതേ രൂപത്തിൽ അത് നിലനിർത്തുകയും ചെയ്യുക. ഇതാണ് എന്റെ അഭിപ്രായം. അന്നേരം ഇബ്നുസുബൈർ(റ) പറഞ്ഞു: നിങ്ങളിൽ ഒരാളുടെ ഭവനമാണ് ഈ രൂപത്തിൽ അഗ്നിക്കിരയായിട്ടുള്ളതെങ്കിൽ അത് ഭദ്രമായ നിലക്ക് പുതുക്കിപ്പണിയുന്നതു വരെ അവൻ സംതൃപ്തനാവുകയില്ല എന്നിരിക്കെ നമ്മുടെ നാഥന്റെ ഭവനത്തെ സംബന്ധിച്ചു നാം എങ്ങനെ സംതൃപ്തരായി അടങ്ങിയിരിക്കും.? നിശ്ചയമായും ഞാൻ മൂന്ന് ദിവസം എന്റെ നാഥനോട് എനിക്ക് നല്ലത് തോന്നിപ്പിക്കുവാൻ പ്രാർത്ഥിക്കുകയും, അനന്തരം ഞാൻ എന്തു ചെയ്യണമെന്ന കാര്യം തീരുമാനിക്കുകയും ചെയ്യുന്നതാണ്. അങ്ങനെ മൂന്നു ദിവസം കഴിഞ്ഞപ്പോൾ അത് പൊളിച്ച് പുതുക്കിപ്പണിയുവാൻ അദ്ദേഹം തീരുമാനിക്കുകയും ചെയ്തു. അന്നേരം, ആദ്യമായി അതിൽ കയറി പൊളിക്കുന്നവന് ആകാശത്തു നിന്നും (അമാനുഷികമായ) വല്ല ആപത്തും ബാധിക്കുമെന്ന് വിചാരിച്ച് ജനങ്ങൾ അതിൽ നിന്നും വിട്ടു നിന്നു. അങ്ങനെ ഒരു മനുഷ്യൻ അതിന്മേൽ കയറുകയും അതിൽ നിന്ന് ഒരു കല്ല് പൊളിച്ചെടുത്ത് താഴെയിടുകയും ചെയ്തു അവന് യാതൊന്നും സംഭവിച്ചില്ലെന്ന് കണ്ടപ്പോൾ, ജനങ്ങൾ നിരനിരയായി വരികയും അത് അടിവരെ പൊളിച്ചിറക്കുകയും ചെയ്തു. അപ്പോൾ ഇബ്നുസുബൈർ(റ) അതിന്റെ കെട്ടിടം ഉയരുന്നത് വരെ (ജനങ്ങൾ നമസ്കരിച്ചിരിക്കുമ്പോൾ മറവുണ്ടാകുവാനായി) അതിൽ ഏതാനും തൂണുകൾ സ്ഥാപിച്ച് മറയുണ്ടാക്കി. ഇബ്നുസുബൈർ(റ) പറഞ്ഞു: ആഇശ(റ) ഇപ്രകാരം പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്. റസൂൽ(സ) ഇപ്രകാരം അരുളിയിരിക്കുന്നു: "ജനങ്ങൾ സത്യനിഷേധത്തിന്റെ സമീപകാലക്കാരായിരുന്നില്ലെങ്കിൽ, ഈ കഅ്ബ നിർമ്മിക്കുവാൻ ആവശ്യമായ സമ്പത്ത് എന്റെ വശം ഉണ്ടാവുകയും ചെയ്തിരുന്നുവെങ്കിൽ, ഹിജ്ർ ഇസ്മാഈലിൽ നിന്ന് അഞ്ചുമുഴം സ്ഥലവും കൂടി ഞാൻ ഈ കഅ്ബയിൽ ഉൾപ്പെടുത്തുകയും, ജനങ്ങൾക്ക് പ്രവേശിക്കുവാനായി ഒരു വാതിലും പുറത്ത് പോകുവാനായി വേറെ ഒരു വാതിലും ഇങ്ങനെ രണ്ടു വാതിൽ ഞാൻ അതിൽ ഉണ്ടാക്കുകയും ചെയ്യുമായിരുന്നു." ഇബ്നുസുബൈർ(റ) പറയുന്നു: അതിന് ചിലവ് ചെയ്യാൻ ആവശ്യമുള്ള സമ്പത്ത് ഇന്ന് എന്റെ വശം ഉണ്ട്. ജനങ്ങൾ സത്യനിഷേധത്തിന്റെ സമീപകാലക്കാരാണെന്ന ഭയവും എനിക്കില്ല. നിവേദകൻ പറയുന്നു: അങ്ങനെ അദ്ദേഹം, ഇബ്രാഹീം ഉണ്ടാക്കിയ അടിത്തറ കാണും വിധം ഭൂമി കീറുകയും അതിൻമേൽ ഹിജ്റിൽ നിന്ന് അഞ്ച് മുഴം ഉൾപ്പെടുത്തി കഅ്ബ പണിയുകയും അതിന് രണ്ട് വാതിൽ വെക്കുകയും ചെയ്തു. ജനങ്ങൾക്ക് അകത്തേക്ക് പ്രവേശിക്കുവാൻ ഒരു വാതിലും, പുറത്തേക്ക് പോകുവാൻ ഒരു വാതിലും. ശേഷം ഇബ്നുസുബൈർ(റ) കൊല്ലപ്പെട്ടപ്പോൾ ഗവർണറായിരുന്ന ഹജ്ജാജ് ഭരണാധികാരിയായ അബ്ദുൽ മലികുബ്നു മർവാന്റെ അടുക്കലേക്ക് ഈ വിവരം അറിയിച്ചു കൊണ്ടും, മക്കയിലെ നീതിമാൻമാരായ ജനങ്ങൾ ശരിയെന്ന് വിലയിരുത്തിയ ഒരു അടിസ്ഥാനത്തിന്റെ മേലാണ് ഇബ്നു സുബൈർ(റ) കഅ്ബ പണിതതെന്ന് അറിയിച്ച് കൊണ്ടും ഒരു കത്ത് എഴുതി. അബ്ദുൽ മലിക് അതിന് മറുപടി എഴുതി: ഇബ്നു സുബൈർ(റ)വിന്റെ ഇത്തരം ദുഷ്ചെയ്തികളുമായി നമുക്ക് യാതൊരു ബന്ധവുമില്ല. എന്നാൽ അദ്ദേഹം അതിന്റെ ദൈർഘ്യം വർദ്ധിപ്പിച്ചത് നിലനിർത്തുകയും ഹിജ്റിൽ നിന്ന് കൂട്ടിച്ചേർത്തത് അതിന്റെ പഴയ സ്ഥാനത്തേക്ക് തന്നെ മാറ്റുകയും ഇബ്നു സുബൈർ(റ) സ്ഥാപിച്ച (പുതിയ) വാതിൽ അടച്ചു കളയുകയും ചെയ്യുക. അതനുസരിച്ച് ഹജ്ജാജ് ആ ഭാഗം പൊളിക്കുകയും പഴയത് പോലെ മാറ്റിപ്പണിയുകയും ചെയ്തു. (മു)', 'عَطَاءِ قَالَ', 'അത്വാഅ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 331, 333, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=83 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 299, 'عَنْ أَبِي قَزْعَةَ: أَنَّ عَبْدَ الْمَلِكِ بْنَ مَرْوَانَ بَيْنَمَا هُوَ يَطُوفُ بِالْبَيْتِ إِذْ قَالَ: قَاتَلَ اللَّهُ ابْنَ الزُّبَيْرِ حَيْثُ يَكْذِبُ عَلَى أُمِّ الْمُؤْمِنِينَ، يَقُولُ: سَمِعْتُهَا تَقُولُ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "يَا عَائِشَةُ، لَوْلَا حِدْثَانُ قَوْمِكِ بِالْكُفْرِ لَنَقَضْتُ الْبَيْتَ حَتَّى أَزِيدَ فِيهِ مِنَ الْحِجْرِ، فَإِنَّ قَوْمَكِ قَصَّرُوا فِي الْبِنَاءِ". فَقَالَ الْحَارِثُ بْنُ عَبْدِ اللَّهِ بْنِ أَبِي رَبِيعَةَ: لَا تَقُلْ هَذَا يَا أَمِيرَ الْمُؤْمِنِينَ، فَأَنَا سَمِعْتُ أُمَّ الْمُؤْمِنِينَ تُحَدِّثُ هَذَا. قَالَ: لَوْ كُنْتُ سَمِعْتُهُ قَبْلَ أَنْ أَهْدِمَهُ لَتَرَكْتُهُ عَلَى مَا بَنَى ابْنُ الزُّبَيْرِ. (م)', 'അബൂഖസ്അ(റ): ഒരിക്കൽ അബ്ദുൽമലികുബ്നു മർവാൻ കഅ്ബ ത്വവാഫ് ചെയ്യുമ്പോൾ ഇങ്ങനെ പറഞ്ഞു: ഇബനു സുബൈർ(റ)വിനെ അല്ലാഹു ശപിക്കട്ടെ. അദ്ദേഹം സത്യവിശ്വാസികളുടെ മാതാവായ ആഇശ(റ)യുടെ പേരിൽ കളവ് പറഞ്ഞിരിക്കുന്നു. ആഇശ(റ) ഇങ്ങനെ പറയുന്നത് ഞാൻ കേട്ടുവെന്ന് ഇബ്നു സുബൈർ(റ) പറയുന്നു: റസൂൽ(സ) അരുളി: "ഓ, ആഇശ, നിന്റെ ജനങ്ങൾ സത്യനിഷേധത്തോട് അടുത്ത കാലക്കാരായിരുന്നില്ലെങ്കിൽ ഞാൻ കഅ്ബ പൊളിക്കുകയും എന്നിട്ട് ഹിജ്റിൽ നിന്ന് അൽപ്പം കൂട്ടിച്ചേർത്തുകൊണ്ട് പുതുക്കിപ്പണിയുകയും ചെയ്യുമായിരുന്നു. കാരണം നിന്റെ ജനങ്ങൾ കെട്ടിടത്തെ ചെറുതാക്കിയിരിക്കുന്നു". അന്നേരം ഹാരിസുബ്നു അബ്ദില്ലാഹിബ്നു റബീഅ(റ) പറഞ്ഞു: ഹേ, അമീറുൽമുഅ്മിനീൻ, നിങ്ങൾ ഇങ്ങനെ പറയരുത്. ആഇശ(റ) ഇതു പറയുന്നത്, ഞാനും കേട്ടിട്ടുണ്ട്. അബ്ദുൽ മാലിക് പറഞ്ഞു: അത് പൊളിക്കുന്നതിന്റെ മുമ്പ് ഇത് ഞാൻ കേട്ടിരുന്നുവെങ്കിൽ, ഇബ്നു സുബൈർ(റ) നിർമ്മിച്ച രൂപത്തിൽ ഞാൻ അതു നിലനിർത്തുമായിരുന്നു. (മു)', 'أَبِي قَزْعَةَ', 'അബൂഖസ്അ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 333, 333, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=83 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 300, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "أَلَمْ تَرَيْ أَنَّ قَوْمَكِ حِينَ بَنَوُا الْكَعْبَةَ اقْتَصَرُوا عَنْ قَوَاعِدِ إِبْرَاهِيمَ عَلَيْهِ السَّلَامِ". فَقُلْتُ: يَا رَسُولَ اللَّهِ، أَلَا تَرُدُّهَا عَلَى قَوَاعِدِ إِبْرَاهِيمَ عَلَيْهِ السَّلَامِ؟ قَالَ: "لَوْلَا حِدْثَانُ قَوْمِكِ بِالْكُفْرِ". فَقَالَ عَبْدُ اللَّهِ بْنُ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: لَئِنْ كَانَتْ عَائِشَةُ رَضِيَ اللهُ عَنْهَا سَمِعَتْ هَذَا مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَا أُرَى تَرْكَ اسْتِلَامِ الرُّكْنَيْنِ اللَّذَيْنِ يَلِيَانِ الْحِجْرَ إِلَّا أَنَّ الْبَيْتَ لَمْ يُتَمَّمْ عَلَى قَوَاعِدِ إِبْرَاهِيمَ عَلَيْهِ السَّلَامِ.
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=4 and h.hadith_no=300), 1, 'وَفِي رِوَايَةٍ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لَهَا: "يَا عَائِشَةُ، لَوْلَا أَنَّ قَوْمَكِ حَدِيثُ عَهْدٍ بِجَاهِلِيَّةٍ لَأَمَرْتُ بِالْبَيْتِ فَهُدِمَ، فَأَدْخَلْتُ فِيهِ مَا أُخْرِجَ مِنْهُ، وَأَلْزَقْتُهُ بِالْأَرْضِ، وَجَعَلْتُ لَهُ بَابَيْنِ: بَابًا شَرْقِيًّا وَبَابًا غَرْبِيًّا، فَإِنَّهُمْ قَدْ عَجَزُوا عَنْ بِنَائِهِ، فَبَلَغْتُ بِهِ أَسَاسَ إِبْرَاهِيمَ عَلَيْهِ السَّلَامِ". قَالَ: فَذَلِكَ الَّذِي حَمَلَ ابْنَ الزُّبَيْرِ عَلَى هَدْمِهِ. قَالَ يَزِيدُ: وَقَدْ شَهِدْتُ ابْنَ الزُّبَيْرِ حِينَ هَدَمَهُ وَبَنَاهُ وَأَدْخَلَ فِيهِ مِنَ الْحِجْرِ، وَقَدْ رَأَيْتُ أَسَاسَ إِبْرَاهِيمَ عَلَيْهِ السَّلَامِ: حِجَارَةً كَأَسْنِمَةِ الْإِبِلِ مُتَلَاحِكَةً. (ن)', 'മറ്റൊരു നിവേദനം: റസൂൽ(സ) അവരോട് പറഞ്ഞു: "ഓ, ആഇശ(റ), സത്യ നിഷേധത്തിന്റെ സമീപകാരായിരുന്നില്ല, നിന്റെ സുമുദായമെങ്കിൽ കഅ്ബയെ പൊളിക്കാൻ ഞാൻ കൽപ്പിക്കുമായിരുന്നു. അതിൽ നിന്ന് പുറത്താക്കിയതിനെ അകത്താക്കുകയും, ഞാൻ അതിനെ ഭൂമിയോട് നിരപ്പാക്കുകയും, പടിഞ്ഞാറും കിഴക്കുമായി രണ്ട് വാതിലുകൾ ഞാൻ വെക്കുകയും ചെയ്യുമായിരുന്നു. നിന്റെ സമൂഹത്തിന് അപ്രകാരം പണിയാൻ കഴിഞ്ഞില്ല. അങ്ങനെ ഞാൻ അതിനെ ഇബ്റാഹീം (അ)ന്റെ അടിത്തറയിലാക്കുകയും ചെയ്യുമായിരുന്നു." നിവേദനകൻ പറയുന്നു: ഇതാണ് കഅ്ബ പൊളിച്ചു പണിയാൻ ഇബ്നുസുബൈർ(റ)വിന് പ്രേരണ നൽകിയതും. യസീദ്(റ) പറയുന്നു: ഇബ്നുസുബൈർ(റ) കഅ്ബ പൊളിച്ചതിനും പുതുക്കി പണിതതിനും ഹിജ്റിനെ അകത്താക്കിയതിനും ഞാൻ സാക്ഷിയായിരുന്നു. ഇബ്റാഹീം (അ) ഇട്ട അടിത്തറ ഞാൻ കണ്ടു: കൂടിച്ചേർന്ന ഒട്ടകപൂഞ്ഞ പോലുള്ള ഒരു കല്ലായിരുന്നു അത്. (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 301, 'عَنْ حَفْصَةَ بِنْتِ عُمَرَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "يُبْعَثُ جُنْدٌ إِلَى هَذَا الْحَرَمِ، فَإِذَا كَانُوا بِبَيْدَاءَ مِنَ الْأَرْضِ خُسِفَ بِأَوَّلِهِمْ وَآخِرِهِمْ، وَلَمْ يَنْجُ أَوْسَطُهُمْ". قُلْتُ: أَرَأَيْتَ إِنْ كَانَ فِيهِمْ مُؤْمِنُونَ؟ قَالَ: "تَكُونُ لَهُمْ قُبُورًا".
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=4 and h.hadith_no=301), 1, 'وَفِي رِوَايَةٍ: لَيَؤُمَّنَّ هَذَا الْبَيْتَ جَيْشٌ يَغْزُونَهُ، حَتَّى إِذَا كَانُوا بِبَيْدَاءَ مِنَ الْأَرْضِ خُسِفَ بِأَوْسَطِهِمْ، فَيُنَادِي أَوَّلُهُمْ وَآخِرُهُمْ، فَيُخْسَفُ بِهِمْ جَمِيعًا، وَلَا يَنْجُو إِلَّا الشَّرِيدُ الَّذِي يُخْبِرُ عَنْهُمْ". (ن)', 'മറ്റൊരു നിവേദനം: "ഈ വീടിനോട് യുദ്ധം ചെയ്യാൻ ഒരു സൈന്യം ഇറങ്ങിപ്പുറപ്പെടും. അവർ ബൈദാഇലെത്തിയാൽ മധ്യത്തിലുള്ളവരെ ഭൂമി വിഴുങ്ങും. അപ്പോൾ ഇരു അറ്റത്തുമുള്ളവർ വിളിച്ചു പറയും. അപ്പോൾ അവരെയും വിഴുങ്ങും. അവരെക്കുറിച്ച് വിവരം തരുന്ന അവരിൽ നിന്ന് പിന്നിലായവർ അല്ലാതെ ആരും രക്ഷപ്പെടുകയില്ല." (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 302, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: كَأَنِّي بِهِ أَسْوَدَ أَفْحَجَ يَقْلَعُهَا حَجَرًا حَجَرًا. (خ)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "നടക്കുമ്പോൾ കാല് അകറ്റിവെച്ച് നടക്കുന്ന ഒരു കറുത്ത മനുഷ്യൻ കഅ്ബയുടെ കല്ലുകൾ ഓരോന്നായി പൊളിച്ചെടുക്കുന്നത് ഞാനിതാ കാണുന്നു." (ബു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 334, 334, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=84 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 303, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: يُخَرِّبُ الْكَعْبَةَ ذُو السُّوَيْقَتَيْنِ مِنَ الْحَبَشَةِ. (خ,ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറയുന്നു: "എത്യോപ്യക്കാരനായ കുറിയ കാലുകളുള്ള ഒരു മനുഷ്യൻ കഅബാലയം തകർക്കും." (ബു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 334, 334, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=84 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 304, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَاقَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِنَّ الرُّكْنَ وَالْمَقَامَ يَاقُوتَتَانِ مِنْ يَاقُوتِ الْجَنَّةِ، طَمَسَ اللَّهُ نُورَهُمَا، وَلَوْ لَمْ يَطْمِسْ نُورَهُمَا لَأَضَاءَتَا مَا بَيْنَ الْمَشْرِقِ وَالْمَغْرِبِ". (ت)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "നിശ്ചയം റുക്നും മഖാമും സ്വർഗ്ഗത്തിലെ രണ്ട് മാണിക്യങ്ങളാണ് അല്ലാഹു അവയുടെ പ്രകാശം മായ്ച്ചുകളഞ്ഞു. അത് മായ്ച്ചില്ലായിരുന്നെങ്കിൽ കിഴക്കിനും പടിഞ്ഞാറിനുമിടയിലുള്ളവയെ അത് പ്രകാശിപ്പിക്കുമായിരുന്നു". (തു)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 335, 335, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=85 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 305, 'عن طَاوُسِ بْنِ كَيْسَانَ: كَانَ يَمُرُّ بِالرُّكْنِ، فَإِنْ وَجَدَ عَلَيْهِ زِحَامًا مَرَّ وَلَمْ يُزَاحِمْ، وَإِنْ رَآهُ خَالِيًا قَبَّلَهُ ثَلَاثًا ثُمَّ قَالَ: رَأَيْتُ ابْنَ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا فَعَلَ مِثْلَ ذَلِكَ. وَقَالَ ابْنُ عَبَّاسٍ: رَأَيْتُ عُمَرَ بْنَ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ فَعَلَ مِثْلَ ذَلِكَ، ثُمَّ قَالَ: إِنَّكَ حَجَرٌ لَا تَنْفَعُ وَلَا تَضُرُّ، وَلَوْلَا أَنِّي رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَبَّلَكَ مَا قَبَّلْتُكَ. ثُمَّ قَالَ عُمَرُ: رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَعَلَ مِثْلَ ذَلِكَ. (ن)', 'ത്വാഊസുബ്നു കൈസാൻ(റ): അവർ റുക്നിന്റെ അരികിലൂടെ നടക്കുമായിരുന്നു. അവിടെ തിരക്കുണ്ടെങ്കിൽ ത്വാഊസ്(റ) തിരക്കാൻ പോവുകയില്ല. അവിടെ ഒഴിഞ്ഞു കിടക്കുന്നതു കണ്ടാൽ അതിനെ മൂന്ന് തവണ ചുംബിക്കും. ശേഷം ത്വാഊസ്(റ) ഇപ്രകാരം പറയുമായിരുന്നു: ഇബ്നുഅബ്ബാസ്(റ) ഇപ്രകാരം പ്രവർത്തിക്കുന്നത് ഞാൻ കണ്ടിട്ടുണ്ട്. ഇബ്നുഅബ്ബാസ്(റ) പറഞ്ഞു: ഉമർ(റ) ഇപ്രകാരം ചെയ്യുന്നത് ഞാൻ കണ്ടു. എന്നിട്ട് ഉമർ(റ) പറയും: നീ ഒരു കല്ലാണ്, നീ ഉപകാരമോ ഉപദ്രവമോ ചെയ്യുകയില്ല. റസൂൽ(സ) നിന്നെ ചുംബിക്കുന്നത് ഞാൻ കണ്ടില്ലായിരുന്നുവെങ്കിൽ ഞാൻ നിന്നെ ചുംബിക്കുമായിരുന്നില്ല. ശേഷം ഉമർ(റ) പറഞ്ഞു: തിരുമേനി(സ) ഇപ്രകാരം പ്രവർത്തിക്കുന്നത് ഞാൻ കണ്ടു. (ന)', 'طَاوُسِ بْنِ كَيْسَانَ', 'ത്വാഊസുബ്നു കൈസാൻ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 335, 335, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=86 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 306, 'عَنْ عَابِسِ بْنِ رَبِيعَةَ النخعي قَالَ: رَأَيْتُ عُمَرَ - رَضِيَ اللهُ عَنْهُ - جَاءَ إِلَى الْحَجَرِ فَقَالَ: "إِنِّي لَأَعْلَمُ أَنَّكَ حَجَرٌ، وَلَوْلَا أَنِّي رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُقَبِّلُكَ مَا قَبَّلْتُكَ. ثُمَّ دَنَا مِنْهُ فَقَبَّلَهُ. (ق,ن,د,ت,جه)', 'ആബിസുബ്നു റബീഅതുന്നഖഈ(റ): ഉമർ(റ) ഹജറുൽ അസ്‌വദിനരികിലേക്ക് വരുന്നത് ഞാൻ കണ്ടു. അപ്പോഴദ്ദേഹം പറയുന്നുണ്ടായിരുന്നു. നിശ്ചയം നീ ഒരു കല്ലാണെന്ന് എനിക്കറിയാം. റസൂൽ(സ) നിന്നെ ചുംബിക്കുന്നത് ഞാൻ കണ്ടില്ലായിരുന്നുവെങ്കിൽ ഞാനും നിന്നെ ചുംബിക്കില്ല. ശേഷം അതിനടുത്തേക്ക് നിൽക്കുകയും ചുംബിക്കുകയും ചയ്തു. (ബു,മു,ദ,തു,ന,ജ)', 'عَابِسِ بْنِ رَبِيعَةَ النخعي قَالَ', 'ആബിസുബ്നു റബീഅതുന്നഖഈ(റ)', null, null, array['ق','ن','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 335, 335, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=86 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 307, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: اسْتَقْبَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْحَجَرَ، ثُمَّ وَضَعَ شَفَتَيْهِ عَلَيْهِ يَبْكِي طَوِيلًا، ثُمَّ الْتَفَتَ فَإِذَا هُوَ بِعُمَرَ بْنِ الْخَطَّابِ يَبْكِي، فَقَالَ: "يَا عُمَرُ، هَاهُنَا تُسْكَبُ الْعَبَرَاتُ". [ز: في إسناده ضعيف] (جه)', 'ഇബ്നുഉമർ(റ): തിരുമേനി(സ) ഹജറുൽ അസ്‌വദിലേക്ക് മുന്നിട്ടു നിന്നു. ശേഷം തന്റെ രണ്ട് ചുണ്ടുകൾ ഹജറുൽ അസ്‌വദിൽ വെച്ച് ഏറെ നേരം കരഞ്ഞു. പിന്നെ പ്രവാചകർ(സ) തിരിഞ്ഞു നോക്കി. അപ്പോഴതാ ഉമർ(റ) കരയുന്നു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ഉമറേ, ഇവിടെയാണ് കണ്ണുനീർ ഒലിപ്പിക്കേണ്ടത്." (സനദ് ബലഹീനമാണ്.) (ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', null, 335, 335, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=86 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 308, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: طَافَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالْبَيْتِ فِي حَجَّةِ الْوَدَاعِ عَلَى رَاحِلَتِهِ، يَسْتَلِمُ الْحَجَرَ بِمِحْجَنِهِ، لِأَنْ يَرَاهُ النَّاسُ وَلِيُشْرِفَ وَلِيَسْأَلُوهُ، فَإِنَّ النَّاس غَشُوهُ. (ن)', 'ജാബിർ(റ): ഹജ്ജത്തുൽ വിദാഇൽ ഒട്ടകപ്പുറത്തിരുന്നു ഒരു വടി കൊണ്ട് ഹജറുൽ അസ്‌വദ് തൊട്ടുകൊണ്ടാണ് തിരുമേനി(സ) ത്വവാഫ് ചെയ്തത്. ജനങ്ങൾ പൊതിഞ്ഞതിനാൽ മറ്റുള്ളവർക്ക് റസൂൽ(സ)യെ കാണാനും റസൂൽ(സ)ക്ക് ജനങ്ങളെ കാണാനും അവർക്ക് റസൂൽ(സ)യോട് ചോദിക്കുവാൻ സൗകര്യമൊരുക്കാനുമായിരുന്നു തിരുമേനി(സ) അപ്രകാരം ചെയ്തത്. (ന)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 336, 336, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=86 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 309, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّهُ سَأَلَهُ رَجُلٌ عَنِ اسْتِلَامِ الْحَجَرِ، فَقَالَ: رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَسْتَلِمُهُ وَيُقَبِّلُهُ، فَقَالَ الرجل: أَرَأَيْتَ إِنْ زُحِمْتُ؟ أَرَأَيْتَ إِنْ غُلِبْتُ؟ قَالَ: اجْعَلْ أَرَأَيْتَ بِالْيَمَنِ! رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَسْتَلِمُهُ وَيُقَبِّلُهُ. (خ)', 'ഇബ്നുഉമർ(റ): അദ്ദേഹത്തോട് ഒരാൾ ഹജറുൽ അസ്‌വദിനെ തൊടുന്നതിനെ കുറിച്ചു ചോദിച്ചു. അന്നേരം ഇബ്നുഉമർ(റ) പറഞ്ഞു: റസൂൽ(സ) തങ്ങളതിനെ തൊടുന്നതും ചുംബിക്കുന്നതും ഞാൻ കണ്ടിട്ടുണ്ട്. അദ്ദേഹം ചോദിച്ചു: ഞാൻ തിരക്കിൽ പെട്ടുപോയി. തൊടാൻ കഴിഞ്ഞില്ല. എങ്കിൽ എന്തുചെയ്യണമെന്നാണ് താങ്കളുടെ അഭിപ്രായം? ഇബ്നുഉമർ(റ) പറഞ്ഞു: നീ നിന്റെ ''അങ്ങിനെയെങ്കിൽ'' ''ഇങ്ങനെയെങ്കിൽ'' എന്ന് ചോദ്യങ്ങൾ യമനിൽ കൊണ്ട് പോയി ഒഴിവാക്കുക. റസൂൽ(സ) അതിനെ തൊടുന്നതും, ചുംബിക്കുന്നതും ഞാൻ കണ്ടിട്ടുണ്ട്. (ബു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 336, 336, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=86 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 310, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "نَزَلَ الْحَجَرُ الْأَسْوَدُ مِنَ الْجَنَّةِ وَهُوَ أَشَدُّ بَيَاضًا مِنَ اللَّبَنِ، فَسَوَّدَتْهُ خَطَايَا بَنِي آدَمَ". حَسَنٌ صَحِيحٌ. (ت)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ഹജറുൽ അസ്‌വദ് സ്വർഗ്ഗത്തിൽ നിന്നാണിറങ്ങിയത്. പാലിനേക്കാൾ വെളുപ്പുണ്ടായിരുന്നു അതിന്, എന്നാൽ മനുഷ്യരുടെ ദോഷമതിനെ കറുപ്പിച്ചു". (തു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 336, 336, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=87 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 311, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الْحَجَرِ: "وَاللَّهِ لَيَبْعَثَنَّهُ اللَّهُ يَوْمَ الْقِيَامَةِ: لَهُ عَيْنَانِ يُبْصِرُ بِهِمَا، وَلِسَانٌ يَنْطِقُ بِهِ، يَشْهَدُ عَلَى مَنِ اسْتَلَمَهُ بِحَقٍّ". قَالَ ترمذي هَذَا حَدِيثٌ حَسَنٌ. (ت)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) ഹജറുൽ അസ്‌വദിനെ കുറിച്ച് ഇപ്രകാരം പറഞ്ഞു: "അല്ലാഹുവാണെ തീർച്ചയായും ഹജറുൽ അസ്‌വദിനെ അന്ത്യദിനത്തിൽ പുനർ ജീവിപ്പിക്കും. അന്നേരമതിന് കാഴ്ചയുള്ള രണ്ട് കണ്ണുകളുണ്ടാവും. സംസാരിക്കുന്ന നാവുണ്ടാകും. യഥാർത്ഥത്തിൽ അതിനെ ചുംബിക്കുന്നവർക്ക് അത് സാക്ഷി നിൽക്കും". (തു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 336, 336, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=87 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 312, 'عَنِ ابْنِ هِشَامٍ سَأَلَ عَطَاءَ بْنَ أَبِي رَبَاحٍ عَنِ الرُّكْنِ الْيَمَانِي، وَهُوَ يَطُوفُ بِالْبَيْتِ. فَقَالَ عَطَاءٌ: حَدَّثَنِي أَبُو هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "وُكِلَ بِهِ سَبْعُونَ مَلَكًا، فَمَنْ قَالَ: اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي الدُّنْيَا وَالْآخِرَةِ، رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ. قَالُوا: آمِينَ". فَلَمَّا بَلَغَ الرُّكْنَ الْأَسْوَدَ قَالَ: يَا أَبَا مُحَمَّدٍ، مَا بَلَغَكَ فِي هَذَا الرُّكْنِ الْأَسْوَدِ؟ فَقَالَ عَطَاءٌ: حَدَّثَنِي أَبُو هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّهُ سَمِعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ فَاوَضَهُ فَإِنَّمَا يُفَاوِضُ يَدَ الرَّحْمَنِ". قَالَ: يَا أَبَا مُحَمَّدٍ، فَالطَّوَافُ؟ قَالَ عَطَاءٌ: حَدَّثَنِي أَبُو هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّهُ سَمِعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ طَافَ بِالْبَيْتِ سَبْعًا، وَلَا يَتَكَلَّمُ إِلَّا بِسُبْحَانَ اللَّهِ، وَالْحَمْدُ لِلَّهِ، وَلَا إِلَهَ إِلَّا اللَّهُ، وَاللَّهُ أَكْبَرُ، وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ. مُحِيَتْ عَنْهُ عَشْرُ سَيِّئَاتٍ، وَكُتِبَتْ لَهُ عَشْرُ حَسَنَاتٍ، وَرُفِعَ لَهُ بِهَا عَشْرَةُ دَرَجَاتٍ. وَمَنْ طَافَ فَتَكَلَّمَ وَهُوَ فِي تِلْكَ الْحَالِ خَاضَ فِي الرَّحْمَةِ بِرِجْلَيْهِ، كَخَائِضِ الْمَاءِ بِرِجْلَيْهِ". (جه)', 'ഇബ്നു ഹിഷാം(റ): അത്വാഉബ്നു അബീറബാഹ(റ) ത്വവാഫ് ചെയ്യുന്നതിനിടെ ഇബ്നുഹിഷാം(റ) അവരോട് ''റുക്നുൽ യമാനി''നെക്കുറിച്ച് ചോദിച്ചു: അത്വാഅ്(റ) പറഞ്ഞു: അബൂഹുറൈറ(റ) എന്നോട് ഹദീസുദ്ധരിച്ചു. റസൂൽ(സ) പറഞ്ഞു: "എഴുപതു മലക്കുകൾ അതുകൊണ്ട് ഏൽപ്പിക്കപ്പെട്ടിരിക്കുന്നു. ആരെങ്കിലും ''അല്ലാഹുവേ, ഇഹത്തിലും പരത്തിലും ആരോഗ്യവും മാപ്പും ഞാൻ നിന്നോട് തേടുന്നു. ഞങ്ങളുടെ രക്ഷിതാവേ, ഇഹത്തിലും പരത്തിലും നന്മ നൽകേണമേ. നരക ശിക്ഷയിൽ നിന്ന് ഞങ്ങളെ കാക്കേണമേ'' എന്ന് പറഞ്ഞാൽ ആ മലക്കുകൾ ആമീൻ പറയും." ''റുക്നുൽ അസ്‌വദി''ന്റെ അരികിലെത്തിയപ്പോൾ ഇബ്നു ഹിഷാം(റ) ചോദിച്ചു: അബു മുഹമ്മദേ, റുക്നുൽ അസ്‌വദിനെക്കുറിച്ച് എന്ത് ഹദീസാണ് നിങ്ങൾക്ക് എത്തിയത്? അപ്പോൾ അത്വാഅ്(റ) പറഞ്ഞു: "അതിനെ തൊടുന്നവർ അല്ലാഹുവിന്റെ കരമാണ് സ്പർശിക്കുന്നത്." എന്ന് തിരുമേനി(സ) പറയുന്നത് ഞാൻ കേട്ടുവെന്ന് അബൂഹുറൈറ(റ) എന്നോട് പറഞ്ഞു. ഇബ്നു ഹിഷാം(റ) ചോദച്ചു: അബു മുഹമ്മദേ, ത്വവാഫിനെക്കുറിച്ച്..? അത്വാഅ്(റ) പറഞ്ഞു: തിരുമേനി(സ) ഇപ്രകാരം പറുയുന്നത് കേട്ടതായി അബൂഹുറൈറ(റ) എന്നോട് പറഞ്ഞു: "ആരെങ്കിലും ത്വവാഫ് ചെയ്യുകയും സുബ്ഹാനല്ലാഹി വൽ ഹംദു ലില്ലാഹി വല്ലാഹു അക്ബർ, വലാ ഹൗല വലാ ഖുവ്വത ഇല്ലാ ബില്ലാഹി'' എന്നതല്ലാതെ വേറെ ഒന്നും സംസാരിക്കുകയും ചെയ്തില്ലെങ്കിൽ അവന്റെ പത്ത് പാപങ്ങൾ പൊറുക്കപ്പെടുകയും അവന് പത്ത് നന്മകൾ എഴുതപ്പെടുകയും അവന്റെ പത്ത് സ്ഥാനങ്ങൾ ഉയർത്തപ്പെടുകയും ചെയ്യും. ആരെങ്കിലും ത്വവാഫ് ചെയ്യുമ്പോൾ സംസാരിച്ചാൽ അവൻ ആ അവസ്ഥയിൽ, തന്റെ കാലു കൊണ്ട് റഹ്മതിനെ ചവിട്ടിയകറ്റിയിരിക്കുന്നു. വെള്ളം കാലു കൊണ്ട് ചവിട്ടിയകറ്റുന്നത് പോലെ." (ജ)', 'ابْنِ هِشَامٍ سَأَلَ عَطَاءَ بْنَ أَبِي رَبَاحٍ عَنِ الرُّكْنِ الْيَمَانِي، وَهُوَ يَطُوفُ بِالْبَيْتِ. فَقَالَ عَطَاءٌ', 'ഇബ്നു ഹിഷാം(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 336, 337, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=87 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 313, 'عَنْ عَبْدِ اللَّهِ بْنِ السَّائِبِ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَا بَيْنَ الرُّكْنَيْنِ: {رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ} [البقرة: ٩٦]. (د)', 'അബ്ദുല്ലാഹിബ്നു സാഇബ്(റ): രണ്ട് റുക്നുകൾക്കിടയിൽ റസൂൽ(സ) "ഞങ്ങളുടെ നാഥാ, ഇഹത്തിലും പരത്തിലും ഞങ്ങൾക്ക് നീ നന്മ നൽകുകയും നരകാഗ്നിയിൽ നിന്ന് ഞങ്ങളെ രക്ഷിക്കുകയും ചെയ്യേണമേ" (അൽബഖറ: 96) എന്ന് പറയുന്നതായി ഞാൻ കേട്ടു. (ദ)', 'عَبْدِ اللَّهِ بْنِ السَّائِبِ', 'അബ്ദുല്ലാഹിബ്നു സാഇബ്(റ)', null, null, array['د']::text[], array['ദ']::text[], 'البقرة: ٩٦', null, 337, 337, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=88 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 314, 'عَنْ أَبِي الطُّفَيْلِ رَضِيَ اللهُ عَنْهُ قَالَ: كُنْتُ مَعَ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا، وَمُعَاوِيَةُ - رَضِيَ اللهُ عَنْهُ - لَا يَمُرُّ بِرُكْنٍ إِلَّا اسْتَلَمَهُ. فَقَالَ لَهُ ابْنُ عَبَّاسٍ: إِنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَمْ يَكُنْ يَسْتَلِمُ إِلَّا الْحَجَرَ الْأَسْوَدَ وَالرُّكْنَ الْيَمَانِيَ. فَقَالَ مُعَاوِيَةُ: لَيْسَ شَيْءٌ مِنَ الْبَيْتِ مَهْجُورًا. قَالَ ترمذي حَدِيثُ ابْنِ عَبَّاسٍ حَدِيثٌ حَسَنٌ صَحِيحٌ. (ق,ت)', 'അബുഥുഫൈൽ(റ): ഞാൻ ഇബ്നുഅബ്ബാസ്(റ)വിനോടൊപ്പമായിരുന്നു. മആവിയ(റ) എല്ലാ റുകനിനെയും തൊട്ട്കൊണ്ടായിരുന്നു നടന്നിരുന്നത്. അന്നേരമദ്ദേഹത്തോട് ഇബ്നുഅബ്ബാസ്(റ) പറഞ്ഞു: നിശ്ചയം റസൂൽ(സ) ഹജറുൽ അസ്‌വദിനെയും റുക്നുൽ യമാനിനെയുമല്ലാതെ മുത്തിയിട്ടില്ല. അപ്പോൾ മുആവിയ(റ) പറഞ്ഞു: കഅബാ ശരീഫിൽ ഒഴിവാക്കപ്പെടേണ്ടതതായൊന്നുമില്ല. തുർമുദി(റ)പറഞ്ഞു: ഇബ്നുഅബ്ബാസ്(റ)വിന്റെ ഹദീസ് ഹസനും സ്വഹീഹുമാണ്. (ബു,മു,തു)', 'أَبِي الطُّفَيْلِ', 'അബുഥുഫൈൽ(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 337, 338, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=89 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 315, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَسْتَلِمُ الرُّكْنَ الْيَمَانِيَ وَالْحَجَرَ فِي كُلِّ طَوَافٍ. (ن)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) റുക്നുൽ യമാനിയെയും ഹജറിനെയും എല്ലാ ത്വവാഫിലും തൊട്ടു മുത്താറുണ്ടായിരുന്നു. (ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 338, 338, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=89 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 316, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: لَمْ أَرَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَمْسَحُ مِنَ الْبَيْتِ إِلَّا الرُّكْنَيْنِ الْيَمَانِيَيْنِ. (ق,د,ن,جه)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) കഅ്ബാലയത്തിലെ രണ്ടു റുക്നു യമാനികളല്ലാതെ സ്പർശിക്കുന്നത് ഞാൻ കണ്ടിട്ടില്ല. (ബു,മു,ദ,ന,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 338, 338, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=89 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 317, 'عَنْ عُبَيْدِ بْنِ جُرَيْجٍ رَضِيَ اللهُ عَنْهُ قَالَ: قُلْتُ لِابْنِ عُمَرَ، رَضِيَ اللهُ عَنْهُمَا: رَأَيْتُكَ لَا تَسْتَلِمُ مِنَ الْأَرْكَانِ إِلَّا هَذَيْنِ الرُّكْنَيْنِ الْيَمَانِيَيْنِ؟ قَالَ: لَمْ أَرَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَسْتَلِمُ إِلَّا هَذَيْنِ. (ن)', 'ഉബൈദുബ്നു ജുറൈജ്(റ): ഞാൻ ഇബ്നുഉമർ(റ)വിനോട് ചോദിച്ചു: റുക്നുകളിൽ ഈ രണ്ടു റുക്നു യമാനികളെ മാത്രം താങ്കൾ തൊട്ടു മുത്തുന്നതായി ഞാൻ കാണുന്നു? ഇബ്നുഉമർ(റ) പറഞ്ഞു: നബി (സ) ഇവ രണ്ടിനെയുമല്ലാതെ തൊട്ടുമുത്തുന്നത് ഞാൻ കണ്ടിട്ടില്ല. (ന)', 'عُبَيْدِ بْنِ جُرَيْجٍ', 'ഉബൈദുബ്നു ജുറൈജ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 338, 338, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=89 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 318, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: مَا تَرَكْتُ اسْتِلَامَ هَذَيْنِ الرُّكْنَيْنِ مُنْذُ رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَسْتَلِمُهُمَا: الْيَمَانِيَ وَالْحَجَرَ، فِي شِدَّةٍ وَلَا رَخَاءٍ. وَفِي رِوَايَةٍ: مَا تَرَكْتُ اسْتِلَامَ الْحَجَرِ فِي رَخَاءٍ وَلَا شِدَّةٍ، مُنْذُ رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَسْتَلِمُهُ. (ن)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): റസൂൽ(സ) റുക്നു യമാനിയെയും ഹജറിനെയും തൊട്ടുമുത്തുന്നത് ഞാൻ കണ്ടത് മുതൽ ക്ഷാമത്തിലും ഐശ്വര്യത്തിലും അതിനെ തൊട്ടു മുത്തൽ ഞാൻ ഒഴിവാക്കിയിട്ടില്ല.
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=4 and h.hadith_no=318), 1, 'وَفِي رِوَايَةٍ: مَا تَرَكْتُ اسْتِلَامَ الْحَجَرِ فِي رَخَاءٍ وَلَا شِدَّةٍ، مُنْذُ رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَسْتَلِمُهُ. (ن)', 'മറ്റൊരു നിവേദന്: ക്ഷാമത്തിലും ഐശ്വര്യത്തിലും ഹജറിനെ തൊട്ടുമുത്തൽ ഞാൻ ഒഴിവാക്കിയിട്ടില്ല, റസൂൽ(സ)അപ്രകാരം മുത്തുന്നത് ഞാൻ കണ്ടതു മുതൽ. (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 319, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَا يَدَعُ أَنْ يَسْتَلِمَ الرُّكْنَ الْيَمَانِيَ وَالْحَجَرَ فِي كُلِّ طَوْفَةٍ، قَالَ: وَكَانَ عَبْدُ اللَّهِ بْنُ عُمَرَ يَفْعَلُهُ. (د,ن)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) റുക്നുൽ യമാനിയെയും ഹജറിനെയും എല്ലാപ്രദക്ഷിണത്തിലും മുത്താതിരിക്കാറില്ല. അബ്ദുല്ലാഹിബ്നു ഉമർ(റ) ഇങ്ങനെ ചെയ്യാറുണ്ട്. (ദ,ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 338, 338, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=89 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 320, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ طَافَ بِالْبَيْتِ، وَصَلَّى رَكْعَتَيْنِ، كَانَ كَعِتْقِ رَقَبَةٍ". (جه)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): റസൂൽ(സ) പറയുന്നതായി ഞാൻ കേട്ടു: "ആരെങ്കിലും കഅ്ബാലയം പ്രദക്ഷിണം ചെയ്യുകയും രണ്ട് റക്അത്ത് നിസ്കരിക്കുകയും ചെയ്താൽ അവർ അടിമ മോചനം നടത്തിയത് പോലെയായി". (ജ)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 338, 339, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=90 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 321, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ طَافَ بِالْبَيْتِ خَمْسِينَ مَرَّةً خَرَجَ مِنْ ذُنُوبِهِ كَيَوْمِ وَلَدَتْهُ أُمُّهُ". (ت)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) പറയുന്നു: "അൻപത് പ്രാവശ്യം ഒരാൾ കഅബാലയം പ്രദക്ഷിണം ചെയ്താൽ അയാൾ തന്റെ മാതാവ് പ്രസവിച്ച ദിവസത്തെ പോലെ ഒരു ദോഷവുമില്ലാത്തവനാകും." (തു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 339, 339, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=90 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 322, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِأَصْحَابِهِ، حِينَ أَرَادُوا دُخُولَ مَكَّةَ، فِي عُمْرَتِهِ بَعْدَ الْحُدَيْبِيَةِ: "إِنَّ قَوْمَكُمْ غَدًا سَيَرَوْنَكُمْ، فَلَيَرَوُنَّكُمْ جُلْدًا". فَلَمَّا دَخَلُوا الْمَسْجِدَ اسْتَلَمُوا الرُّكْنَ وَرَمَلُوا، وَالنَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَعَهُمْ، حَتَّى إِذَا بَلَغُوا الرُّكْنَ الْيَمَانِي مَشَوْا إِلَى الرُّكْنِ الْأَسْوَدِ، ثُمَّ رَمَلُوا حَتَّى بَلَغُوا الرُّكْنَ الْيَمَانِي، ثُمَّ مَشَوْا إِلَى الرُّكْنِ الْأَسْوَدِ. فَفَعَلَ ذَلِكَ ثَلَاثَ مَرَّاتٍ، ثُمَّ مَشَى الْأَرْبَعَ. (د,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ)യുടെ ഹുദൈബിയ്യാനന്തര ഉംറക്കിടെ സ്വഹാബാക്കൾ മക്കയിൽ പ്രവേശിക്കാനിരിക്കെ തിരുമേനി(സ) അവരോട് പറഞ്ഞു: "നാളെ നിങ്ങളുടെ സമൂഹം നിങ്ങളെ കാണും. അവർ നിങ്ങളെ കാണുന്നത് ശക്തരായ നിലയിൽ തന്നെയായിരിക്കട്ടെ." അങ്ങനെ അവർ മസ്ജിദുൽ ഹറാമിൽ ചെന്ന് റുക്ന് ചുംബിക്കുകകുയം റംല് നടത്തം നടക്കുകയും ചെയ്തു. റസൂൽ(സ) അവരുടെ കൂടെയുണ്ടായിരുന്നു. റുക്നുൽ യമാനിൽ എത്തിയപ്പോൾ റുക്നുൽ അസ്‌വദിലേക്ക് അവർ നടന്നു. ശേഷം റുക്നുൽ യമാനി വരെ അവർ റംല് നടത്തം നടത്തി. പിന്നെ റുക്നുൽ അസ്‌വദ് വരെ നടന്നു. മൂന്ന് തവണ ഇപ്രകാരം ചെയ്തു. ശേഷം നാല് തവണ സാധാരണനടത്തം നടക്കുകയും ചെയ്തു. (ദ,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 339, 339, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=91 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 323, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا طَافَ بِالْبَيْتِ الطَّوَافَ الْأَوَّلَ: رَمَلَ ثَلَاثَةً، وَمَشَى أَرْبَعَةً، مِنَ الْحِجْرِ إِلَى الْحِجْرِ. وَكَانَ ابْنُ عُمَرَ يَفْعَلُهُ. (جه)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) കഅബാലയം പ്രദക്ഷിണം നടത്തുമ്പോൾ ആദ്യ മൂന്ന് പ്രാവശ്യം റംലും പിന്നീട് നാല് പ്രാവശ്യം സാധാനടത്തവുമയാരിക്കും. ഹിജ്റിൽ നിന്നു തുടങ്ങി ഹിജ്ർ വരെയായിരിക്കുമത്. ഇബ്നുഉമർ(റ) ഇപ്രകാരം ചെയ്യുമായിരുന്നു. (ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 339, 339, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=91 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 324, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُمَا أَنَّهُ قَالَ: رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَمَلَ مِنَ الْحَجَرِ الْأَسْوَدِ حَتَّى انْتَهَى إِلَيْهِ ثَلَاثَةَ أَطْوَافٍ. (م)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): റസൂൽ(സ) ഹജറുൽ അസ്‌വദ് മുതൽ ഹജറുൽ അസ്‌വദ് വരെ മൂന്ന് ചുറ്റ് റംല് നടത്തം നടന്നു. (മു)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 339, 339, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=91 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 325, 'عَنْ أَبِي الطُّفَيْلِ قَالَ: قُلْتُ لِابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُم: أَرَأَيْتَ هَذَا الرَّمَلَ بِالْبَيْتِ ثَلَاثَةَ أَطْوَافٍ وَمَشْيَ أَرْبَعَةِ أَطْوَافٍ، أَسُنَّةٌ هُوَ، فَإِنَّ قَوْمَكَ يَزْعُمُونَ أَنَّهُ سُنَّةٌ؟ قَالَ: فَقَالَ: صَدَقُوا وَكَذَبُوا. قَالَ: قُلْتُ: مَا قَوْلُكَ صَدَقُوا وَكَذَبُوا؟ قَالَ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَدِمَ مَكَّةَ، فَقَالَ الْمُشْرِكُونَ: إِنَّ مُحَمَّدًا وَأَصْحَابَهُ لَا يَسْتَطِيعُونَ أَنْ يَطُوفُوا بِالْبَيْتِ مِنَ الْهُزَالِ، وَكَانُوا يَحْسُدُونَهُ، قَالَ: فَأَمَرَهُمْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يَرْمُلُوا ثَلَاثًا وَيَمْشُوا أَرْبَعًا: قَالَ: قُلْتُ لَهُ: أَخْبِرْنِي عَنِ الطَّوَافِ بَيْنَ الصَّفَا وَالْمَرْوَةِ رَاكِبًا - أَسُنَّةٌ هُوَ، فَإِنَّ قَوْمَكَ يَزْعُمُونَ أَنَّهُ سُنَّةٌ؟ قَالَ: صَدَقُوا وَكَذَبُوا، قَالَ: قُلْتُ: وَمَا قَوْلُكَ صَدَقُوا وَكَذَبُوا؟ قَالَ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَثُرَ عَلَيْهِ النَّاسُ، يَقُولُونَ: هَذَا مُحَمَّدٌ هَذَا مُحَمَّدٌ - صلى الله عليه وسلم - حَتَّى خَرَجَ الْعَوَاتِقُ مِنَ الْبُيُوتِ، قَالَ: وَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَا يُضْرَبُ النَّاسُ بَيْنَ يَدَيْهِ، فَلَمَّا كَثُرَ عَلَيْهِ رَكِبَ، وَالْمَشْيُ وَالسَّعْيُ أَفْضَلُ. (م)', 'അബുത്വുഫൈൽ(റ): ഞാൻ ഇബ്നുഅബ്ബാസ്(റ)വിനോട് ചോദിച്ചു: ത്വവാഫ് ചെയ്യുമ്പോൾ മൂന്ന് തവണ റംല് നടത്തം നടക്കുനനതിനെക്കുറിച്ചും നാലു തവണ സാധാരണ നടത്തം നടക്കുന്നതിനെക്കുറിച്ചും താങ്കളുടെ അഭിപ്രായമെന്താണ്? സുന്നത്താണോ? നിങ്ങളുടെ സമുദായം അത് സുന്നത്താണെന്ന് വാദിക്കുന്നു. ഇബ്നുഅബ്ബാസ്(റ) പറഞ്ഞു: അവർ പറഞ്ഞത് സത്യമാണ്, കളവുമാണ്. നിവേദകൻ പറയുന്നു: ഞാൻ ചോദിച്ചു: അവർ സത്യവും കളവുമാണ് പറയുന്നത് എന്നത് കൊണ്ട് താങ്കൾ എന്താണ് അർത്ഥമാക്കുന്നത്? ഇബ്നുഅബ്ബാസ്(റ) പറഞ്ഞു: തിരുമേനി(സ) മക്കയിൽ വന്നു. അപ്പോൾ ബഹുദൈവാരാധകർ പറഞ്ഞു: മുഹമ്മദ്(സ)യും കൂട്ടരും ശക്തിക്ഷയിച്ചവരാണ്. അത് കൊണ്ട് അവർക്ക് ത്വവാഫ് ചെയ്യാൻ സാധിക്കുകയില്ല. അവർ പ്രവാചകർ(സ)യോട് അസൂയയുള്ളവരായിരുന്നു. അപ്പോൾ മൂന്ന് തവണ വേഗത്തിൽ നടക്കാനും നാലുതവണ സാധാരണ നടത്തം നടക്കുവാനും തിരുമേനി(സ) അനുചരരോട് കൽപിച്ചു. നിവേദകൻ പറയുന്നു: ഞാൻ പറഞ്ഞു: സ്വഫക്കും മർവ്വക്കുമിടയിൽ വാഹനത്തിൽ പ്രദക്ഷിണം ചെയ്യുന്നതിനെക്കുറിച്ച് എനിക്ക് പറഞ്ഞു തരിക. അതു സുന്നത്താണോ? താങ്കളുടെ സമുദായം അത് സുന്നത്താണെന്ന് പറയുന്നു. ഇബ്നുഅബ്ബാസ്(റ) പറഞ്ഞു: അവർ പറഞ്ഞത് സത്യമാണ്, കളവുമാണ്. നിവേദകൻ പറയുന്നു: ഞാൻ ചോദിച്ചു: അവർ പറയുന്നത് സത്യവും കളവുമാണെന്നത് കൊണ്ട് താങ്കളെന്താണ് അർത്ഥമാക്കുന്നത്? ഇബ്നുഅബ്ബാസ്(റ) പറഞ്ഞു: ഇതാ മുഹമ്മദ്(സ) എന്ന് പറഞ്ഞ് കൊണ്ട് ജനങ്ങൾ, പ്രായപൂർത്തിയായ കന്യകമാർ വരെ, തിരുമേനി(സ)ക്ക് ചുറ്റും കൂടി. അവിടുത്തെ മുമ്പിലുള്ളവരെ തട്ടിമാറ്റപ്പെട്ടിരുന്നില്ല. അങ്ങനെ ജനങ്ങൾ അധികരിച്ചപ്പോൾ റസൂൽ(സ) വാഹനത്തിൽ കയറി (പ്രദക്ഷിണം നടത്തി). നടക്കുന്നതും ഓടുന്നതുമാണ് ഏറ്റവും ശ്രേഷ്ഠമായത്. (മു)', 'أَبِي الطُّفَيْلِ قَالَ', 'അബുത്വുഫൈൽ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 339, 340, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=91 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 326, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَدِمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَصْحَابُهُ فَقَالَ الْمُشْرِكُونَ: إِنَّهُ يَقْدَمُ عَلَيْكُمْ وَقَدْ وَهَنَهُمْ حُمَّى يَثْرِبَ فَأَمَرَهُمُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يَرْمُلُوا الْأَشْوَاطَ الثَّلَاثَةَ، وَأَنْ يَمْشُوا مَا بَيْنَ الرُّكْنَيْنِ وَلَمْ يَمْنَعْهُ أَنْ يَأْمُرَهُمْ أَنْ يَرْمُلُوا الْأَشْوَاطَ كُلَّهَا إِلَّا الْإِبْقَاءُ عَلَيْهِمْ. (خ)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ)യും, അനുചരൻമാരും മക്കയിൽ വന്നപ്പോൾ മുശ്‌രികുകൾ പറഞ്ഞു: നിശ്ചയം നിങ്ങളുടെ അടുത്തേക്ക് അവർ വരുന്നത് യസ്‌രിബിലെ പനി പിടിച്ച് ക്ഷീണിച്ചു കൊണ്ടാണ്. ഈ അവസരത്തിൽ റസൂൽ(സ) അവരോട് ആദ്യ മൂന്ന് പ്രാവശ്യത്തെ ത്വവാഫിൽ റംല്നടത്തം നടക്കുവാനും രണ്ട് റുക്നുകൾക്കിടയിൽ സാധാരണ നടത്തം നടക്കുവാനും കൽപ്പിച്ചു. "മുഴുവൻ പ്രദിക്ഷണവും അങ്ങിനെ ചെയ്യാൻ തിരുമേനി(സ) കൽപ്പിക്കാതിരുന്നത് അവരത് ചര്യയാക്കുമോ എന്ന ഭയം കൊണ്ട് മാത്രമായിരുന്നു. (ബു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 340, 340, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=91 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 327, 'عن ابن عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: فَمَا لَنَا وَلِلرَّمَلِ إِنَّمَا كُنَّا رَاءَيْنَا بِهِ الْمُشْرِكِينَ وَقَدْ أَهْلَكَهُمُ اللَّهُ، ثُمَّ قَالَ: شَيْءٌ صَنَعَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَلَا نُحِبُّ أَنْ نَتْرُكَهُ. (خ)', 'ഇബ്നുഉമർ(റ): അദ്ദേഹം പറയുന്നു: ''ഞങ്ങൾ എന്തിന് റംല് നടത്തം നടക്കണം? നിശ്ചയം ഞങ്ങളത് മുശ്‌രികുകളെ കാണിക്കാൻ വേണ്ടി ചെയ്തൊരു കാര്യമാണ്. അവരെ അല്ലാഹു നശിപ്പിച്ചിരിക്കുന്നു.'' പിന്നീട് അദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ) ചെയ്തൊരു കാര്യമായത് കൊണ്ട് അത് ഉപേക്ഷിക്കാൻ ഞങ്ങളിഷ്ടപ്പെടുന്നില്ല. (ബു)', 'ابن عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 340, 340, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=91 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 328, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: لَمَّا قَدِمَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَصْحَابُهُ مَكَّةَ قَالَ الْمُشْرِكُونَ: وَهَنَتْهُمْ حُمَّى يَثْرِبَ وَلَقُوا مِنْهَا شَرًّا. فَأَطْلَعَ اللَّهُ نَبِيَّهُ عَلَيْهِ الصَّلَاةُ وَالسَّلَامُ عَلَى ذَلِكَ، فَأَمَرَ أَصْحَابَهُ أَنْ يَرْمُلُوا وَأَنْ يَمْشُوا مَا بَيْنَ الرُّكْنَيْنِ، وَكَانَ الْمُشْرِكُونَ مِنْ نَاحِيَةِ الْحِجْرِ، فَقَالُوا: لَهَؤُلَاءِ أَجْلَدُ مِنْ كَذَا. (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ)യും അനുചരരും മക്കയിൽ വന്നപ്പോൾ ബഹുദൈവ വിശ്വാസികൾ പറഞ്ഞു: മുസ്‌ലിംകളെ മദീനയിലെ പനി ക്ഷയിപ്പിച്ചിരിക്കുന്നു. അവിടെ നിന്ന് അവർക്ക് പ്രശ്നങ്ങൾ ഏറ്റിരിക്കുന്നു. ഇത് അല്ലാഹു റസൂൽ(സ)ക്ക് അറിയിച്ചുകൊടുത്തു. അപ്പോൾ റസൂൽ(സ) അനുചരോട് റംല് നടത്തം നടക്കാനും രണ്ട് റുക്നുകൾക്കിടയിൽ സാധാരണ നടത്തം നടക്കാനും കൽപ്പിച്ചു. ബഹുദൈവവിശ്വാസികൾ ഹിജ്റിന്റെ മൂലയിൽ ഇരിക്കുകയായിരുന്നു. അവർ പറഞ്ഞു: ഇവർ അതിനേക്കാൾ ശക്തരാണല്ലോ. (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 340, 341, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=91 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 329, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا طَافَ فِي الْحَجِّ وَالْعُمْرَةِ أَوَّلَ مَا يَقْدَمُ فَإِنَّهُ يَسْعَى ثَلَاثَةَ أَطْوَافٍ وَيَمْشِي أَرْبَعًا، ثُمَّ يُصَلِّي سَجْدَتَيْنِ، ثُمَّ يَطُوفُ بَيْنَ الصَّفَا وَالْمَرْوَةِ. (ن)', 'ഇബ്നുഉമർ(റ): നിശ്ചയം റസൂൽ(സ) ഹജ്ജിനും ഉംറക്കും പ്രദക്ഷിണം ചെയ്യുമ്പോൾ ആദ്യം മൂന്ന് പ്രാവശ്യം റംല് നടത്തവും പിന്നീടുള്ള നാലു പ്രാവശ്യം സാധാരണ രീതിയിലും നടക്കുമായിരുന്നു. പിന്നീട് രണ്ട് റക്അത്ത് നിസ്കരിക്കുകയും ശേഷം സ്വഫാ-മർവ്വക്കിടയിൽ പ്രദക്ഷിണം നടത്തുകയും ചെയ്യുമായിരുന്നു. (ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 341, 341, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=91 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 330, 'عَنْ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ قَالَ: فِيمَ الرَّمَلَانُ الْيَوْمَ وَالْكَشْفُ عَنِ الْمَنَاكِبِ، وَقَدْ أَطَّأَ اللَّهُ الْإِسْلَامَ وَنَفَى الْكُفْرَ وَأَهْلَهُ؟ مَعَ ذَلِكَ لَا نَدَعُ شَيْئًا كُنَّا نَفْعَلُهُ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (د,جه)', 'ഉമർ(റ): ഇപ്പോളെന്തിനാണ് റംല് നടത്തവും ചുമൽ വെളിവാക്കിയിടുന്നതും, അല്ലാഹു ഇസ്‌ലാമിനെ സ്ഥിരപ്പെടുത്തിയിരിക്കുന്നു. സത്യ നിഷേധത്തെയും അതിന്റെ ആളുകളെയും അല്ലാഹു തുടച്ചു നീക്കിയിരിക്കുന്നു എന്നിരിക്കെ? അല്ലാഹുവാണ് സത്യം, തിരുദൂതരുടെ കാലത്ത് നാം ചെയ്തത് ഒന്നും തന്നെ നാം ഒഴിവാക്കുന്നതല്ല. (ദ,ജ)', 'عُمَرَ بْنِ الْخَطَّابِ', 'ഉമർ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 341, 341, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=91 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 331, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ اضْطَبَعَ فَاسْتَلَمَ وَكَبَّرَ، ثُمَّ رَمَلَ ثَلَاثَةَ أَطْوَافٍ، وَكَانُوا إِذَا بَلَغُوا الرُّكْنَ الْيَمَانِيَ وَتَغَيَّبُوا مِنْ قُرَيْشٍ مَشَوْا، ثُمَّ يَطْلُعُونَ عَلَيْهِمْ يَرْمُلُونَ، تَقُولُ قُرَيْشٌ: كَأَنَّهُمُ الْغِزْلَانُ. قَالَ ابْنُ عَبَّاسٍ: فَكَانَتْ سُنَّةً. (د)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) തന്റെ വസ്ത്രം വലതു കക്ഷത്തിനടിയിലൂടെയും ഇടതു ചുമലിനു മുകളിലുമായി ഇടുകയും, റുക്നിനെ തൊടുകയും തക്ബീർ ചൊല്ലുകയും ചെയ്തു. ശേഷം മൂന്ന് തവണ റംല് നടത്തം നടന്നു. റുക്നുൽ യമാനിയയുടെ അടുത്ത് എത്തുകയും ഖുറൈശികളുടെ കാഴ്ചയിൽ നിന്ന് മറയുകയും ചെയ്താൽ അവർ സാധാ നടത്തം നടക്കും. ഖുറൈശികൾ കാണുന്ന സ്ഥലത്തെത്തിയാൽ വീണ്ടും റംല് നടത്തം നടക്കും. ഖുറൈശികൾ പറഞ്ഞു: ഇവർ മാനുകളെപ്പോലെയാണ്. ഇബ്നുഅബ്ബാസ്(റ) പറയുന്നു: അങ്ങനെ അത് നബിചര്യയായി മാറി. (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 341, 341, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=91 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 332, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: طَافَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى رَاحِلَتِهِ، فَإِذَا انْتَهَى إِلَى الرُّكْنِ أَشَارَ إِلَيْهِ. قَالَ ترمذي حَدِيثُ ابْنِ عَبَّاسٍ حَدِيثٌ حَسَنٌ صَحِيحٌ. (خ,ت,ن)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) വാഹനപ്പുറത്തിരുന്ന് പ്രദക്ഷിണം ചെയ്തു. റുക്നിന്റെ അടുത്തെത്തിയാൽ അതിലേക്ക് കൈനീട്ടും. ഇബ്നുഅബ്ബാസ്(റ)വിന്റെ ഹദീസ് ഹസനാണെന്ന് തുർമുദി പറഞ്ഞിട്ടുണ്ട്. തുർമുദി(റ)പറഞ്ഞു: ഇബ്നുഅബ്ബാസ്(റ)വിന്റെ ഹദീസ് ഹസനും സ്വഹീഹുമാണ്. (ബു,തു,ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ','ت','ن']::text[], array['ബു','തു','ന']::text[], null, null, 341, 342, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=92 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 333, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهَا أَنَّهَا قَالَتْ: شَكَوْتُ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنِّي أَشْتَكِي، فَقَالَ: "طُوفِي مِنْ وَرَاءِ النَّاسِ وَأَنْتِ رَاكِبَةٌ". قَالَتْ: فَطُفْتُ وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَئِذٍ يُصَلِّي إِلَى جَنْبِ الْبَيْتِ، وَهُوَ يَقْرَأُ ب {وَالطُّورِ وَكِتَابٍ مَسْطُورٍ} (ق,د,ن,جه)', 'ഉമ്മു സലമ(റ): എനിക്ക് ബുദ്ധിമുട്ടനുഭവപ്പെടുന്ന കാര്യം ഞാൻ റസൂൽ(സ)യെ ധരിപ്പിച്ചു. അന്നേരം റസൂൽ(സ) പറഞ്ഞു: നീ വാഹനപ്പുറത്തേറി ജനങ്ങൾക്കു പിന്നിലായി ത്വവാഫ് നിർവ്വഹിക്കുക. ഉമ്മു സലമഃ(റ) പറഞ്ഞു: ഞാൻ ത്വവാഫ് ചെയ്യുമ്പോൾ റസൂൽ(സ) കഅ്ബാലയത്തിന്റെ ഒരു ഭാഗത്ത് നിസ്കരിക്കുകയായിരുന്നു. അവിടനന്ന് വത്ത്വൂരി വകിതാബിൻ മസ്ത്വൂർ എന്ന അദ്ധ്യായം പാരായണം ചെയ്യുന്നുണ്ടായിരുന്നു. (ബു,മു,ദ,ന,ജ)', 'أُمِّ سَلَمَةَ', 'ഉമ്മു സലമ(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 342, 342, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=92 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 334, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَرَّ وَهُوَ يَطُوفُ بِالْكَعْبَةِ بِإِنْسَانٍ رَبَطَ يَدَهُ إِلَى إِنْسَانٍ بِسَيْرٍ أَوْ بِخَيْطٍ أَوْ بِشَيْءٍ غَيْرِ ذَلِكَ فَقَطَعَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِيَدِهِ ثُمَّ قَالَ: قُدْهُ بِيَدِهِ. (خ,ن)', 'ഇബ്നുഅബ്ബാസ്(റ): തിരുമേനി(സ) ത്വവാഫ് ചെയ്യുന്നതിനിടക്ക്, തുകലിൽ നിന്നു മുറിച്ചെടുത്ത ചരടു കൊണ്ടോ നുലുകൊണ്ടോ മറ്റോ തന്റെ കൈ മറ്റൊരാളുടെ കയ്യുമായി കൂട്ടിക്കെട്ടി ത്വവാഫ് ചെയ്യുന്ന ഒരു മനുഷ്യന്റെ അടുത്തുകൂടെ നടന്നു പോയി. തിരുമേനി(സ) ആ കെട്ട് തന്റെ കൈ കൊണ്ട് മുറിച്ചുകളഞ്ഞു. അവിടുന്ന് അരുളി: "അവന്റെ കൈ പിടിച്ചു നടത്തുക." (ബു,ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 342, 342, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=93 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 335, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الطَّوَافُ حَوْلَ الْبَيْتِ مِثْلُ الصَّلَاةِ، إِلَّا أَنَّكُمْ تَتَكَلَّمُونَ فِيهِ، فَمَنْ تَكَلَّمَ فِيهِ فَلَا يَتَكَلَّمَنَّ إِلَّا بِخَيْرٍ". (ت,ن)', 'ഇബ്നുഅബ്ബാസ്(റ): നിശ്ചയം നബി(സ) പറഞ്ഞു: "കഅ്ബാലയത്തിനു ചുറ്റുമുള്ള ത്വവാഫ് നമസ്കാരം പോലെയാണ്. എങ്കിലും ത്വവാഫിൽ നിങ്ങൾക്ക് സംസാരിക്കാം. ആരെങ്കിലും ത്വവാഫിൽ സംസാരിക്കുന്നുവെങ്കിൽ നന്മയല്ലാത്തതൊന്നും പറയരുത്." (തു,ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ت','ن']::text[], array['തു','ന']::text[], null, null, 342, 342, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=93 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 336, 'عَنِ ابْنِ هِشَامٍ سَأَلَ عَطَاءَ بْنَ أَبِي رَبَاحٍ عَنِ الرُّكْنِ الْيَمَانِي، وَهُوَ يَطُوفُ بِالْبَيْتِ. فَقَالَ عَطَاءٌ: حَدَّثَنِي أَبُو هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "وُكِلَ بِهِ سَبْعُونَ مَلَكًا، فَمَنْ قَالَ: اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي الدُّنْيَا وَالْآخِرَةِ، رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ. قَالُوا: آمِينَ".
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 337, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: أَقِلُّوا الْكَلَامَ فِي الطَّوَافِ، فَإِنَّمَا أَنْتُمْ فِي الصَّلَاةِ. (ن)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): നിങ്ങൾ പ്രദക്ഷിണ സമയത്ത് സംസാരം കുറക്കുക. നിശ്ചയമായും ആ സമയം നിങ്ങൾ നിസ്കാരത്തിലാകുന്നു. (ന)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 343, 343, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=93 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 338, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: لَمَّا قَدِمَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَكَّةَ دَخَلَ الْمَسْجِدَ فَاسْتَلَمَ الْحَجَرَ، ثُمَّ مَضَى عَلَى يَمِينِهِ، فَرَمَلَ ثَلَاثًا وَمَشَى أَرْبَعًا، ثُمَّ أَتَى الْمَقَامَ فَقَالَ: {وَاتَّخِذُوا مِنْ مَقَامِ إِبْرَاهِيمَ مُصَلًّى} [البقرة: 125] فَصَلَّى رَكْعَتَيْنِ، وَالْمَقَامُ بَيْنَهُ وَبَيْنَ الْبَيْتِ، ثُمَّ أَتَى الْحَجَرَ بَعْدَ الرَّكْعَتَيْنِ فَاسْتَلَمَهُ، ثُمَّ خَرَجَ إِلَى الصَّفَا، أَظُنُّهُ قَالَ: {إِنَّ الصَّفَا وَالْمَرْوَةَ مِنْ شَعَائِرِ اللَّهِ} [البقرة: ١٥٨]. قَالَ ترمذي هذا حَدِيثٌ حَسَنٌ صَحِيحٌ. (م,ت,ن)', 'ജാബിർ(റ): റസൂൽ(സ) മക്കയിൽ വന്നപ്പോൾ പള്ളിയിൽ പ്രവേശിക്കുകയും ഹജറുൽ അസ്‌വദിനെ തൊട്ടു മുത്തുകയും ചെയ്തു. പിന്നീട് വലതു ഭാഗത്തേക്ക് നടന്നു. മൂന്ന് പ്രാവശ്യം റംല് നടത്തം നടന്നു. നാല് തവണ സാധാനടത്തവും നിർവ്വഹിച്ചു. പിന്നീട് ഇബ്റാഹീം മഖാമിൽ ചെന്നു. ''ഇബ്റാഹീം മഖാമിനെ നിങ്ങൾ നിസ്കാരസ്ഥലമാക്കുക.'' (അൽബഖറ: 125) എന്ന സൂക്തം ഉരുവിട്ട് രണ്ട് റക്അത്ത് നിസ്കരിച്ചു. നബിയുടെയും, കഅബാലയത്തിന്റെയുമിടയിലാണ് മഖാമുള്ളത്. രണ്ട് റക്അത് നിർവ്വഹിച്ച ശേഷം ഹജറുൽ അസ്‌വദിൽ ചെല്ലുകയും അത് തൊട്ടു ചുംബിക്കുകയും ചെയ്തു. പിന്നീട് സ്വഫായിലേക്ക് ചെന്നു. അവിടെ വെച്ച് ''തീർച്ചയായും സ്വഫായും, മർവായും അല്ലാഹുവിന്റെ അടയാളങ്ങളിൽ പെട്ടവയാണ്''. (അൽബഖറ: 158) എന്ന സൂക്തം ഉരുവിട്ടു. (മു,തു,ന)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['م','ت','ن']::text[], array['മു','തു','ന']::text[], 'البقرة: ١٥٨', null, 343, 343, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=94 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 339, 'عَنْ يَعْلَى رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ طَافَ بِالْبَيْتِ مُضْطَبِعًا، وَعَلَيْهِ بُرْدٌ. حَسَنٌ صَحِيحٌ. (د,ت,جه)', 'യഅ്‌ലാ(റ): വലത് ചുമൽ പുറത്താക്കിയും ഇടത് ചുമൽ മറച്ചും വസ്ത്രം ധരിച്ചായിരുന്നു റസൂൽ(സ) ത്വവാഫ് ചെയ്തത്. റസൂൽ(സ)യുടെ മേൽ ഒരു പുതപ്പുമുണ്ടായിരുന്നു. (ദ,തു,ജ)', 'يَعْلَى', 'യഅ്‌ലാ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 344, 344, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=95 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 340, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَصْحَابَهُ اعْتَمَرُوا مِنَ الْجِعْرَانَةِ، فَرَمَلُوا بِالْبَيْتِ، وَجَعَلُوا أَرْدِيَتَهُمْ تَحْتَ آبَاطِهِمْ، قَدْ قَذَفُوهَا عَلَى عَوَاتِقِهِمُ الْيُسْرَى. (د)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ)യും അനുയായികളും ജിഅ്റാനയിൽ നിന്ന് ഉംറ ചെയ്തു. കഅ്ബക്ക് ചുറ്റും റംല് നടത്തം നടന്നു. വസ്ത്രത്തിന്റെ മുഖ്യഭാഗം അവർ തങ്ങളുടെ കക്ഷത്തിനടിയിലാക്കുകയും അറ്റങ്ങൾ ഇടതു ചുമലിൻ മുകളിൽ ഇടുകയും ചെയ്തു. (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 344, 344, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=95 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 341, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ اضْطَبَعَ فَاسْتَلَمَ وَكَبَّرَ، ثُمَّ رَمَلَ ثَلَاثَةَ أَطْوَافٍ، وَكَانُوا إِذَا بَلَغُوا الرُّكْنَ الْيَمَانِيَ وَتَغَيَّبُوا مِنْ قُرَيْشٍ مَشَوْا، ثُمَّ يَطْلُعُونَ عَلَيْهِمْ يَرْمُلُونَ، تَقُولُ قُرَيْشٌ: كَأَنَّهُمُ الْغِزْلَانُ. قَالَ ابْنُ عَبَّاسٍ: فَكَانَتْ سُنَّةً. (د)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) തന്റെ വസ്ത്രം വലതു കക്ഷത്തിനടിയിലൂടെയും ഇടതു ചുമലിനു മുകളിലുമായി ഇടുകയും, റുക്നിനെ തൊടുകയും തക്ബീർ ചൊല്ലുകയും ചെയ്തു. ശേഷം മൂന്ന് തവണ റംല് നടത്തം നടന്നു. റുക്നുൽ യമാനിയയുടെ അടുത്ത് എത്തുകയും ഖുറൈശികളുടെ കാഴ്ചയിൽ നിന്ന് മറയുകയും ചെയ്താൽ അവർ സാധാ നടത്തം നടക്കും. ഖുറൈശികൾ കാണുന്ന സ്ഥലത്തെത്തിയാൽ വീണ്ടും റംല് നടത്തം നടക്കും. ഖുറൈശികൾ പറഞ്ഞു: ഇവർ മാനുകളെപ്പോലെയാണ്. ഇബ്നുഅബ്ബാസ്(റ) പറയുന്നു. അങ്ങനെ അത് നബിചര്യയായി മാറി. (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 344, 344, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=95 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 342, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَتِ الْمَرْأَةُ تَطُوفُ بِالْبَيْتِ وَهِيَ عُرْيَانَةٌ، تَقُولُ:
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 343, 'عَنْ زَيْدِ بْنِ أُثَيْعٍ قَالَ: سَأَلْتُ عَلِيًّا رَضِيَ اللهُ عَنْهُ: بِأَيِّ شَيْءٍ بُعِثْتَ؟ قَالَ: بِأَرْبَعٍ: لَا يَدْخُلُ الْجَنَّةَ إِلَّا نَفْسٌ مُسْلِمَةٌ، وَلَا يَطُوفُ بِالْبَيْتِ عُرْيَانٌ، وَلَا يَجْتَمِعُ الْمُسْلِمُونَ وَالْمُشْرِكُونَ بَعْدَ عَامِهِمْ هَذَا، وَمَنْ كَانَ بَيْنَهُ وَبَيْنَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَهْدٌ فَعَهْدُهُ إِلَى مُدَّتِهِ، وَمَنْ لَا مُدَّةَ لَهُ فَأَرْبَعَةُ أَشْهُرٍ. حَسَنٌ. (ت)', 'സൈദുബ്നു ഉസൈഗ്(റ): ഞാൻ അലി(റ)വിനോട് ചോദിച്ചു: നിങ്ങളെ എന്തുമായാണ് അയക്കപ്പെട്ടത്? (ഹജ്ജതുൽ വിദാഇന്റെ മുമ്പുള്ള വർഷം റസൂൽ(സ) അവരെ മക്കയിലേക്ക് അബുബക്കർ(റ)വിന്റെ നേതൃത്വത്തിൽ ഹജ്ജിനായി അയച്ചിരുന്നു.) അലി(റ) പറഞ്ഞു: നാലുകാര്യങ്ങളുമായി. സ്വർഗ്ഗത്തിൽ മുസ്‌ലിമല്ലാതെ പ്രവേശിക്കുകയില്ല. നഗ്നരായി കഅ്ബയെ ത്വവാഫ് ചെയ്യരുത്. മുസ്‌ലിമീങ്ങളും ബഹുദൈവാരാധകരും ഈ വർഷത്തിനു ശേഷം ഒരുമിച്ചു കൂടുകയില്ല. വല്ലവന്നും റസൂൽ(സ)യുമായി വല്ല കരാറുമുണ്ടെങ്കിൽ അത് അതിന്റെ കാലാവധി തീരുന്നത് വരെയാകുന്നു. കാലാവധി നിർണ്ണയിക്കപ്പെട്ടിട്ടില്ലെങ്കിൽ അതിന്റെ കാലാവധി നാല് മാസമാണ്. (തു)', 'زَيْدِ بْنِ أُثَيْعٍ قَالَ', 'സൈദുബ്നു ഉസൈഗ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 344, 345, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=96 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 344, 'عَنْ دَاوُدَ بْنِ عَجْلَانَ قَالَ: طُفْنَا مَعَ أَبِي عِقَالٍ فِي مَطَرٍ، فَلَمَّا قَضَيْنَا طَوَافَنَا أَتَيْنَا خَلْفَ الْمَقَامِ، فَقَالَ: طُفْتُ مَعَ أَنَسِ بْنِ مَالِكٍ فِي مَطَرٍ، فَلَمَّا قَضَيْنَا الطَّوَافَ أَتَيْنَا الْمَقَامَ فَصَلَّيْنَا رَكْعَتَيْنِ، فَقَالَ لَنَا أَنَسٌ: ائْتَنِفُوا الْعَمَلَ، فَقَدْ غُفِرَ لَكُمْ. هَكَذَا قَالَ لَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَطُفْنَا مَعَهُ فِي مَطَرٍ. [ز: في إسناده ضعيف] (جه)', 'ദാവൂദുബ്നു അജ്‌ലാൻ(റ): അബൂ ഇഖാൽ(റ)വിനോട് കൂടെ മഴയത്ത് ഞങ്ങൾ കഅ്ബ പ്രദക്ഷിണം ചെയ്തു. പ്രദക്ഷിണം കഴിഞ്ഞപ്പോൾ ഞങ്ങൾ (ഇബ്റാഹീം)മഖാമിന്റെ പിന്നിൽ ചെന്നുനിന്നു. അപ്പോൾ അബൂ ഇഖാൽ(റ) പറഞ്ഞു: ഞങ്ങൾ അനസുബ്നു മാലിക്(റ)വിന്റെ കൂടെ മഴയത്ത് ത്വവാഫ് ചെയ്തു. ത്വവാഫ് പൂർത്തിയാക്കിയതിന്റെ ശേഷം ഞങ്ങൾ മഖാമു ഇബ്രാഹീമിൽ ചെന്ന് രണ്ട് റക്അത്ത് നിസ്കരിച്ചു. തുടർന്ന് അനസ്(റ) ഞങ്ങളോട് പറഞ്ഞു: നിങ്ങൾ കർമങ്ങൾ ആരംഭിക്കുക. നിങ്ങൾക്ക് പൊറുക്കപ്പെട്ടിരിക്കുന്നു. ഇപ്രകാരം തിരുമേനി(സ) ഞങ്ങളോട് പറഞ്ഞു. ഞങ്ങൾ മഴയത്ത് റസൂൽ(സ)യോടൊപ്പം ത്വവാഫ് ചെയ്യുകയും ചെയ്തു. (ഇതിന്റെ പരമ്പരയിൽ ഭംഗമുള്ളവരുണ്ട്.) (ജ)', 'دَاوُدَ بْنِ عَجْلَانَ قَالَ', 'ദാവൂദുബ്നു അജ്‌ലാൻ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', null, 345, 345, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=97 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 345, 'عَنْ عَبْدِ الرَّحْمَنِ ابْنِ صَفْوَانَ رَضِيَ اللهُ عَنْهُ قَالَ: لَمَّا فَتَحَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَكَّةَ قُلْتُ: لَأَلْبَسَنَّ ثِيَابِي، وَكَانَتْ دَارِي عَلَى الطَّرِيقِ، فَلَأَنْظُرَنَّ كَيْفَ يَصْنَعُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. فَانْطَلَقْتُ، فَرَأَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَدْ خَرَجَ مِنَ الْكَعْبَةِ هُوَ وَأَصْحَابُهُ وَقَدِ اسْتَلَمُوا الْبَيْتَ مِنَ الْبَابِ إِلَى الْحَطِيمِ، وَقَدْ وَضَعُوا خُدُودَهُمْ عَلَى الْبَيْتِ، وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَسْطَهُمْ. (د)', 'അബ്ദുർറഹ്മാനുബ്നു സ്വഫ്‌വാൻ(റ): തിരുമേനി(സ) മക്ക ജയിച്ചടക്കിയപ്പോൾ ഞാൻ സ്വന്തത്തോട് പറഞ്ഞു: ഞാൻ എന്റെ വസ്ത്രം ധരിക്കും - എന്റെ വീട് വഴിയിലായിരുന്നു - റസൂൽ(സ) എന്തു ചെയ്യുന്നുവെന്നു ഞാൻ വീക്ഷിക്കും. അങ്ങനെ ഞാൻ പുറത്തു പോയി. റസൂൽ(സ)യും അനുചരരും കഅ്ബയുടെ പുറത്ത് വരുന്നതും കവാടം മുതൽ ഹതീം വരെയുള്ള ഭാഗത്തു നിന്ന് കഅ്ബയെ ചുംബിക്കുന്നതും ഞാൻ കണ്ടു. അവർ അവരുടെ കവിളുകൾ കഅ്ബയിൽ വെച്ചിരുന്നു. തിരുമേനി(സ)യും അവരുടെ മധ്യത്തിലുണ്ടായിരുന്നു. (ദ)', 'عَبْدِ الرَّحْمَنِ ابْنِ صَفْوَانَ', 'അബ്ദുർറഹ്മാനുബ്നു സ്വഫ്‌വാൻ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 345, 345, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=98 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 346, 'عَنْ شُعَيْبِ بْنِ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا قَالَ: طُفْتُ مَعَ عَبْدِ اللَّهِ، فَلَمَّا جِئْنَا دُبُرَ الْكَعْبَةِ قُلْتُ: أَلَا تَتَعَوَّذُ؟ قَالَ: نَعُوذُ بِاللَّهِ مِنَ النَّارِ. ثُمَّ مَضَى حَتَّى اسْتَلَمَ الْحَجَرَ، وَأَقَامَ بَيْنَ الرُّكْنِ وَالْبَابِ، فَوَضَعَ صَدْرَهُ وَوَجْهَهُ وَذِرَاعَيْهِ وَكَفَّيْهِ هَكَذَا، وَبَسَطَهُمَا بَسْطًا، ثُمَّ قَالَ: هَكَذَا رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَفْعَلُهُ. (د,جه)', 'ശുഐബുബ്നു അബ്ദില്ലാഹിബ്നു അംറ്(റ): ഞാൻ അബ്ദുല്ല(റ)വിന്റെ കൂടെ ത്വവാഫ് ചെയ്തു. കഅ്ബയുടെ പിന്നിലെത്തിയപ്പോൾ ഞാൻ ചോദിച്ചു: നിങ്ങൾ കാവലിനെ ചോദിക്കുന്നില്ലേ. അബ്ദുല്ല പറഞ്ഞു: നരകത്തിൽ നിന്ന് അല്ലാഹുവിനോട് നാം കാവൽ തേടുന്നു. എന്നിട്ട് അദ്ധേഹം പോയി ഹജറുൽ അസ്‌വദിനെ ചുംബിച്ചു. റുക്നിന്റെയും വാതിലിന്റെയും ഇടയിൽ നിൽക്കുകയും തന്റെ നെഞ്ച്, മുഖം, കൈ, മുൻകൈ എന്നിവ ഇപ്രകാരം വെച്ചു. എന്നിട്ട് കൈകൾ വിടർത്തുകയും ഇപ്രകാരം പറയുകയും ചെയ്തു: തിരുമേനി(സ) ഇപ്രകാരം ചെയ്യുന്നത് ഞാൻ കണ്ടു. (ദ,ജ)', 'شُعَيْبِ بْنِ عَبْدِ اللهِ بْنِ عَمْرٍو', 'ശുഐബുബ്നു അബ്ദില്ലാഹിബ്നു അംറ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 345, 346, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=98 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 347, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَمَّا دَخَلَ مَكَّةَ طَافَ بِالْبَيْتِ وَصَلَّى رَكْعَتَيْنِ خَلْفَ الْمَقَامِ، يَعْنِي يَوْمَ الْفَتْحِ. (م,د)', 'അബു ഹുറൈറ(റ): നിശ്ചയം, റസൂൽ(സ) മക്കയിൽ പ്രവേശിച്ചപ്പോൾ (മക്കാ വിജയ ദിനത്തിൽ) കഅബാലയം പ്രദക്ഷിണം ചെയ്തു. മഖാമിനു പിറകിൽ നിന്ന് രണ്ട് റക്അത് നിസ്കരിക്കുകയും ചെയ്തു. (മു,ദ)', 'أَبِي هُرَيْرَةَ', 'അബു ഹുറൈറ(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 346, 346, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=99 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 348, 'عَنِ الْمُطَّلِبِ بْنِ أَبِي وَدَاعَةَ رَضِيَ اللهُ عَنْهُ: أَنَّهُ رَأَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي مِمَّا يَلِي بَابَ بَنِي سَهْمٍ وَالنَّاسُ يَمُرُّونَ بَيْنَ يَدَيْهِ، وَلَيْسَ بَيْنَهُمَا سُتْرَةٌ. وفي رواية: لَيْسَ بَيْنَهُ وَبَيْنَ الْكَعْبَةِ سُتْرَةٌ. (د,ن,جه)', 'മുത്വലിബുബ്നു അബീ വിദാഅ(റ): പ്രവാചകർ(സ) ബനൂ സഹ്മിന്റെ വാതിലിനരികെ വെച്ച് നിസ്കരിക്കുന്നത് അവർ കണ്ടു. ജനങ്ങൾ തിരുമേനി(സ)യുടെ മുന്നിലൂടെ നടക്കുന്നുണ്ടായിരുന്നു. അവർക്കിടയിൽ മറയുണ്ടായിരുന്നില്ല. മറ്റൊരു നിവേദനം: റസൂൽ(സ)ക്കും കഅ്ബക്കുമിടയിൽ മറയുണ്ടായിരുന്നില്ല. (ദ,ന,ജ)', 'الْمُطَّلِبِ بْنِ أَبِي وَدَاعَةَ', 'മുത്വലിബുബ്നു അബീ വിദാഅ(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 346, 346, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=99 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=4 and h.hadith_no=348), 1, 'وَفِي رِوَايَةٍ: لَيْسَ بَيْنَهُ وَبَيْنَ الْكَعْبَةِ سُتْرَةٌ. (د,ن,جه)', 'മറ്റൊരു നിവേദനം: റസൂൽ(സ)ക്കും കഅ്ബക്കുമിടയിൽ മറയുണ്ടായിരുന്നില്ല. (ദ,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 349, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَدِمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَطَافَ بِالْبَيْتِ سَبْعًا، وَصَلَّى خَلْفَ الْمَقَامِ رَكْعَتَيْنِ، وَطَافَ بَيْنَ الصَّفَا وَالْمَرْوَةِ، وَقَالَ: {لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ} [الأحزاب: ٢١]. (ن)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) കഅബാലയത്തിൽ വന്ന് ഏഴ് പ്രാവശ്യം പ്രദക്ഷിണം ചെയ്തു. മഖാമിന് പിന്നിൽ നിന്ന് രണ്ട് റക്അത്ത് നിസ്കരിച്ചു. സ്വഫാ മർവ്വക്കിടയിൽ പ്രദക്ഷിണം വെക്കുകയും ചെയ്തു. ശേഷം അവിടന്ന് ഇപ്രകാരം പറഞ്ഞു: ''നിശ്ചയം അല്ലാഹുവിന്റെ ദൂതരിൽ നിങ്ങൾക്കു നല്ല ചര്യയുണ്ട്.'' (അൽ അഹ്സാബ്: 21) (ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], 'الأحزاب: ٢١', null, 346, 346, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=99 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 350, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَمَّا انْتَهَى إِلَى مَقَامِ إِبْرَاهِيمَ قَرَأَ: {وَاتَّخِذُوا مِنْ مَقَامِ إِبْرَاهِيمَ مُصَلًّى} [البقرة: ١٢٥] فَصَلَّى رَكْعَتَيْنِ، فَقَرَأَ فَاتِحَةَ الْكِتَابِ وَ {قُلْ يَا أَيُّهَا الْكَافِرُونَ} وَ {قُلْ هُوَ اللَّهُ أَحَدٌ} ثُمَّ عَادَ إِلَى الرُّكْنِ فَاسْتَلَمَهُ، ثُمَّ خَرَجَ إِلَى الصَّفَا. (ن)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): റസൂൽ(സ) ഇബ്റാഹീം മഖാമിൽ എത്തിയപ്പോൾ ''ഇബ്റാഹീം മഖാമിനെ നിങ്ങൾ നിസ്കാര സ്ഥലമാക്കുക.'' (അൽബഖറ: 125) എന്ന സൂക്തം ഉരുവിട്ടു. പിന്നീട് രണ്ട് റക്അത്ത് നിസ്കരിച്ചു. സൂറതുൽ ഫാതിഹഃയും സൂറതുൽ കാഫിറൂനയും സൂറതുൽ ഇഖ്‌ലാസും പാരായണം ചെയ്തു. പിന്നീട് റുക്നിലേക്ക് മടങ്ങുകയും തൊട്ടു മുത്തുകയും ശേഷം സ്വഫായിലേക്ക് പുറപ്പെടുകയും ചെയ്തു. (ന)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['ن']::text[], array['ന']::text[], 'البقرة: ١٢٥', null, 346, 347, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=99 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 351, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَرَأَ فِي رَكْعَتَيِ الطَّوَافِ بِسُورَتَيِ الْإِخْلَاصِ {قُلْ يَا أَيُّهَا الْكَافِرُونَ} وَ{قُلْ هُوَ اللَّهُ أَحَدٌ}. (ت)', 'ജാബിർ ബിൻ അബ്ദില്ലാഹ്(റ): റസൂൽ(സ) ത്വവാഫിന്റെ രണ്ട് റക്അത്തുകളിൽ ''ഖുൽ യാ അയ്യുഹൽ കാഫിറൂൻ'', ''ഖുൽ ഹുവല്ലാഹു അഹദ്'' എന്നീ സൂറതുൽ ഇഖ്‌ലാസുകൾ പാരായണം ചെയ്തു. (തു)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിർ ബിൻ അബ്ദില്ലാഹ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 347, 347, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=100 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 352, 'عَنْ جُبَيْرِ بْنِ مُطْعِمٍ رَضِيَ اللهُ عَنْهُ - يَبْلُغُ بِهِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - قَالَ: "لَا تَمْنَعُوا أَحَدًا يَطُوفُ بِهَذَا الْبَيْتِ وَيُصَلِّي أَيَّ سَاعَةٍ شَاءَ مِنْ لَيْلٍ أَوْ نَهَارٍ". وفي رواية: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "يَا بَنِي عَبْدِ مَنَافٍ، لَا تَمْنَعُوا أَحَدًا.." (د,ت,ن,جه)', 'ജുബൈർബിൻ മുത്ഇം(റ): റസൂൽ(സ) പറഞ്ഞതായി അദ്ദേഹം പറയുന്നു: "ഈ കഅബാലയത്തിൽ വെച്ച് പകലിലോ, രാത്രിയിലോ ഏതെങ്കിലുമൊരു സമയത്ത് നിസ്കരിക്കുകയോ, പ്രദക്ഷിണം നടത്തുകയോ ചെയ്യുന്ന വ്യക്തിയെ നിങ്ങൾ തടയരുത്". മറ്റൊരു റിപ്പോർട്ട്: "അബ്ദു മനാഫിന്റെ സന്തതികളെ, നിങ്ങൾ ആരെയും തടയരുത്". (ദ,തു,ന,ജ)', 'جُبَيْرِ بْنِ مُطْعِمٍ', 'ജുബൈർബിൻ മുത്ഇം(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 347, 347, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=101 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=4 and h.hadith_no=352), 1, 'وَفِي رِوَايَةٍ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "يَا بَنِي عَبْدِ مَنَافٍ، لَا تَمْنَعُوا أَحَدًا.." (د,ت,ن,جه)', 'മറ്റൊരു നിവേദന്: "അബ്ദു മനാഫിന്റെ സന്തതികളെ, നിങ്ങൾ ആരെയും തടയരുത്". (ദ,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 353, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ أَوَّلَ شَيْءٍ بَدَأَ بِهِ حِينَ قَدِمَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ تَوَضَّأَ، ثُمَّ طَافَ، ثُمَّ لَمْ تَكُنْ عُمْرَةً، ثُمَّ حَجَّ أَبُو بَكْرٍ وَعُمَرُ رَضِيَ اللهُ عَنْهُمَا مِثْلَهُ. (خ)', 'ആഇശ(റ): തീർച്ചയായും റസൂൽ(സ) മുന്നിട്ടു വന്ന അവസരത്തിൽ ആദ്യമായി ചെയ്ത കാര്യം, അംഗശുദ്ധി വരുത്തുകയായിരുന്നു. പിന്നീട് ത്വവാഫ് ചെയ്തു. പിന്നീട് ഉംറ ഉണ്ടായില്ല. പിന്നീട് അബുബക്ർ(റ)വും, ഉമർ(റ)വും അപ്രകാരം ഹജ്ജ് ചെയ്തു. (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 347, 347, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=102 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 354, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا حَدِيثَ طَوَافِ النَّبِيِّ تَقَدَّمَ قَرِيبًا، وَزَادَ فِي هَذِهِ الرِّوَايَةِ وَأَنَّهُ كَانَ يَسْجُدُ سَجْدَتَيْنِ بَعْدَ الطَّوَافِ، ثُمَّ يَطُوفُ بَيْنَ الصَّفَا وَالْمَرْوَةِ. (خ)', 'ഇബ്നുഉമർ(റ) റിപ്പോർട്ട് ചെയ്ത റസൂൽ(സ) തങ്ങളുടെ ത്വവാഫിനെ സംബന്ധിച്ച ഹദീസ് അടുത്ത് പറഞ്ഞു കഴിഞ്ഞു. ഈ നിവേദനത്തിൽ ഇബ്നുഉമർ(റ) ഇത് കുടി പറഞ്ഞു: നിശ്ചയം റസൂൽ(സ) ത്വവാഫിനു ശേഷം രണ്ട് സുജൂദ് ചെയ്യുകയും, പിന്നീട് സ്വഫാ മർവക്കിടയിൽ ത്വവാഫ് ചെയ്യുകയും ചെയ്തിരുന്നു. (ബു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 347, 347, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=102 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 355, 'عَنْ وَبَرَةَ - يَعْنِي ابْنَ عَبْدِ الرَّحْمَنِ - قَالَ: كُنْتُ جَالِسًا عِنْدَ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا، فَجَاءَهُ رَجُلٌ فَقَالَ: أَيَصْلُحُ لِي أَنْ أَطُوفَ بِالْبَيْتِ قَبْلَ أَنْ آتِيَ الْمَوْقِفَ؟ فَقَالَ: نَعَمْ، فَقَالَ: فَإِنَّ ابْنَ عَبَّاسٍ يَقُولُ: لَا تَطُفْ بِالْبَيْتِ حَتَّى تَأْتِيَ الْمَوْقِفَ. فَقَالَ ابْنُ عُمَرَ: فَقَدْ حَجَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَطَافَ بِالْبَيْتِ قَبْلَ أَنْ يَأْتِيَ الْمَوْقِفَ، فَبِقَوْلِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَحَقُّ أَنْ تَأْخُذَ أَوْ بِقَوْلِ ابْنِ عَبَّاسٍ إِنْ كُنْتَ صَادِقًا؟. وَفِي رِوَايَةٍ قَالَ: رَأَيْنَا رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَحْرَمَ بِالحَجِّ وَطَافَ بِالْبَيْتِ وَسَعَى بَيْنَ الصَّفَا وَالْمَرْوَةِ. (م)', 'വബറത്ത് ഇബ്നു അബ്ദുർറഹ്മാൻ(റ): ഞാൻ ഇബ്നുഉമർ(റ)ന്റെ അടുത്തിരിക്കുകയായിരുന്നു. അന്നേരം ഒരാൾ വന്നു ചോദിച്ചു. മൗഖിഫിലെത്തുന്നതിന് മുമ്പായി കഅ്ബാലയം പ്രദക്ഷിണം ചെയ്യുന്നതെനിക്ക് പറ്റുമോ? ഇബ്നുഉമർ(റ) പറഞ്ഞു: അതെ, പറ്റും. അപ്പോഴയാൾ പറഞ്ഞു: നിശ്ചയം ഇബ്നുഅബ്ബാസ്(റ) പറയുന്നു. മൗഖിഫിലെത്താതെ നിങ്ങൾ കഅ്ബാലയ പ്രദക്ഷിണം നടത്തരുതെന്ന്. അപ്പോൾ ഇബ്നുഉമർ(റ) പറഞ്ഞു: നിശ്ചയം റസൂൽ(സ) തങ്ങൾ ഹജ്ജ് നിർവ്വഹിച്ചപ്പോൾ മൗഖിഫിലെത്തുന്നതിന് മുമ്പായി കഅ്ബാലയ പ്രദക്ഷിണം നടത്തിയിട്ടുണ്ട്. നീ സത്യസന്ധനാണെങ്കിൽ റസൂൽ(സ)യുടെ വാക്കാണല്ലോ ഇബ്നുഅബ്ബാസി(റ)ന്റെ വാക്കിനേക്കാൾ നിങ്ങൾക്ക് സ്വീകരിക്കാൻ ഉത്തമമായി തോന്നുന്നത്. മറ്റൊരു റിപ്പോർട്ട്: റസൂൽ(സ) ഹജ്ജിന് ഇഹ്റാം ചെയ്യുകയും, കഅ്ബാലയ പ്രദക്ഷിണം നടത്തുകയും, സ്വഫാ മർവക്കിടയിൽ നടക്കുകയും ചെയ്തതായി ഞങ്ങൾ ദർശിച്ചു. (മു)', 'وَبَرَةَ - يَعْنِي ابْنَ عَبْدِ الرَّحْمَنِ - قَالَ', 'വബറത്ത് ഇബ്നു അബ്ദുർറഹ്മാൻ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 347, 348, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=102 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=4 and h.hadith_no=355), 1, 'وَفِي رِوَايَةٍ قَالَ: رَأَيْنَا رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَحْرَمَ بِالحَجِّ وَطَافَ بِالْبَيْتِ وَسَعَى بَيْنَ الصَّفَا وَالْمَرْوَةِ. (م)', 'മറ്റൊരു നിവേദന്: റസൂൽ(സ) ഹജ്ജിന് ഇഹ്റാം ചെയ്യുകയും, കഅ്ബാലയ പ്രദക്ഷിണം നടത്തുകയും, സ്വഫാ മർവക്കിടയിൽ നടക്കുകയും ചെയ്തതായി ഞങ്ങൾ ദർശിച്ചു. (മു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 356, 'عَنْ عَمْرِو بْنِ دِينَارٍ قَالَ: سَأَلْنَا ابْنَ عُمَرَ رَضِيَ اللهُ عَنْهُ عَنْ رَجُلٍ قَدِمَ بِعُمْرَةٍ، فَطَافَ بِالْبَيْتِ وَلَمْ يَطُفْ بَيْنَ الصَّفَا وَالْمَرْوَةِ، أَيَأْتِي امْرَأَتَهُ؟ فَقَالَ: قَدِمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَطَافَ بِالْبَيْتِ سَبْعًا، وَصَلَّى خَلْفَ الْمَقَامِ رَكْعَتَيْنِ، وَبَيْنَ الصَّفَا وَالْمَرْوَةِ سَبْعًا [جميعا]، وَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ. (م)', 'അംറുബ്നു ദീനാർ(റ): ഉംറക്ക് ഇഹ്റാം ചെയ്യുകയും, കഅ്ബാലയ പ്രദക്ഷിണം നടത്തി സ്വഫാ-മർവ്വക്കിടയിൽ ചുറ്റാതെ വന്ന ഒരാളെക്കുറിച്ച് ഇബ്നുഉമർ(റ)നോട് ഞങ്ങൾ ചോദിച്ചു. അദ്ദേഹത്തിന് ഭാര്യയെ സമീപിക്കാമോ? ഇബ്നുഉമർ(റ) പറഞ്ഞു: റസൂൽ(സ) ഇഹ്റാം ചെയ്തു വരികയും കഅബാലയം ഏഴ് പ്രാവശ്യം ചുറ്റുകയും, ഇബ്റാഹീം മഖാമിന് പിന്നിൽ നിന്ന് രണ്ട് റക്അത് നിസ്കരിക്കുകയും, സ്വഫാ-മർവ്വാക്കിടയിൽ ഏഴ് പ്രാവശ്യം നടക്കുകയും ചെയ്തു. നിശ്ചയം റസൂൽ(സ)യിൽ നിങ്ങൾക്ക് അനുകരണീയ മാതൃകയുണ്ട്. (മു)', 'عَمْرِو بْنِ دِينَارٍ قَالَ', 'അംറുബ്നു ദീനാർ(റ)', null, null, array['م']::text[], array['മു']::text[], 'جميعا', null, 348, 348, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=102 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 357, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانُوا يَصُومُونَ عَاشُورَاءَ قَبْلَ أَنْ يُفْرَضَ رَمَضَانُ وَكَانَ يَوْمًا تُسْتَرُ فِيهِ الْكَعْبَةُ فَلَمَّا فَرَضَ اللَّهُ رَمَضَانَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ شَاءَ أَنْ يَصُومَهُ فَلْيَصُمْهُ وَمَنْ شَاءَ أَنْ يَتْرُكَهُ فَلْيَتْرُكْهُ. (خ)', 'ആഇശ(റ): റമളാൻ മാസത്തെ നോമ്പ് ഫർളാക്കപ്പെടുന്നതിന് മുമ്പ് ജനങ്ങൾ ആശൂറാ നോമ്പ് അനുഷ്ഠിച്ചിരുന്നു. അന്നേ ദിവസം കഅ്ബക്ക് വിരിയിടപ്പെടുമായിരുന്നു. പിന്നീട് റമളാൻ ഫർളാക്കപ്പെട്ടപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ഇനി ഊദ്ദേശിക്കുന്നവർ ആശൂറാ നോമ്പനുഷ്ടിക്കുക. ഉദ്ദേശിക്കുന്നവർ അതുപേക്ഷിക്കുക." (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 348, 348, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=103 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 358, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَيُحَجَّنَّ الْبَيْتُ وَلَيُعْتَمَرَنَّ بَعْدَ خُرُوجِ يَأْجُوجَ وَمَأْجُوجَ. (خ)', 'അബൂസഈദിൽ ഖുദ്രി(റ): റസൂൽ(സ) പറഞ്ഞു: "നിശ്ചയം യഅ്ജൂജ് മഅ്ജൂജ് പുറപ്പെട്ടതിനു ശേഷവും കഅ്ബാശരീഫിൽ ഹജ്ജും ഉംറഃയും നിർവ്വഹിക്കപ്പെടും." (ബു)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 348, 349, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=103 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 359, 'عَنْ مَيْمُونَةَ رَضِيَ اللهُ عَنْهَا، زَوْجِ النَّبِيِّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ قَالَتْ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ يَقُولُ: "صَلَاةٌ فِي مَسْجِدِي هَذَا أَفْضَلُ مِنْ أَلْفِ صَلَاةٍ فِيمَا سِوَاهُ مِنَ الْمَسَاجِدِ، إِلَّا الْمَسْجِدَ الْكَعْبَةَ". (ن)', 'മൈമൂന(റ): നിശ്ചയം റസൂൽ(സ) പറഞ്ഞു: "എന്റെ ഈ പള്ളിയിലുള്ള ഒരു നിസ്കാരം മസ്ജിദുൽഹറാം ഒഴികെ മറ്റു പള്ളികളിൽ വെച്ചുള്ള ആയിരം നിസ്കാരങ്ങളേക്കാൾ ശ്രേഷ്ഠതയുള്ളതാണ്." (ന)', 'مَيْمُونَةَ', 'മൈമൂന(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 349, 349, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=104 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 360, 'عَنْ جَعْفَرِ بْنِ مُحَمَّدٍ عَنْ أَبِيهِ قَالَ: دَخَلْنَا عَلَى جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُم، فَسَأَلَ عَنِ الْقَوْمِ حَتَّى انْتَهَى إِلَيَّ، فَقُلْتُ: أَنَا مُحَمَّدُ بْنُ عَلِيِّ بْنِ حُسَيْنٍ، فَأَهْوَى بِيَدِهِ إِلَى رَأْسِي فَنَزَعَ زِرِّي الْأَعْلَى، ثُمَّ نَزَعَ زِرِّي الْأَسْفَلَ، ثُمَّ وَضَعَ كَفَّهُ بَيْنَ ثَدْيَيَّ، وَأَنَا يَوْمَئِذٍ غُلَامٌ شَابٌّ، فَقَالَ: مَرْحَبًا بِكَ يَا ابْنَ أَخِي، سَلْ عَمَّا شِئْتَ. فَسَأَلْتُهُ وَهُوَ أَعْمَى، وَحَضَرَ وَقْتُ الصَّلَاةِ فَقَامَ فِي نِسَاجَةٍ مُلْتَحِفًا بِهَا، كُلَّمَا وَضَعَهَا عَلَى مَنْكِبِهِ رَجَعَ طَرَفَاهَا إِلَيْهِ مِنْ صِغَرِهَا، وَرِدَاؤُهُ إِلَى جَنْبِهِ عَلَى الْمِشْجَبِ، فَصَلَّى بِنَا. فَقُلْتُ: أَخْبِرْنِي عَنْ حَجَّةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ بِيَدِهِ، فَعَقَدَ تِسْعًا. فَقَالَ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَكَثَ تِسْعَ سِنِينَ لَمْ يَحُجَّ، ثُمَّ أَذَّنَ فِي النَّاسِ فِي الْعَاشِرَةِ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَاجٌّ فَقَدِمَ الْمَدِينَةَ بَشَرٌ كَثِيرٌ، كُلُّهُمْ يَلْتَمِسُ أَنْ يَأْتَمَّ بِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَيَعْمَلَ مِثْلَ عَمَلِهِ، فَخَرَجْنَا مَعَهُ حَتَّى أَتَيْنَا ذَا الْحُلَيْفَةِ، فَوَلَدَتْ أَسْمَاءُ بِنْتُ عُمَيْسٍ مُحَمَّدَ بْنَ أَبِي بَكْرٍ رَضِيَ اللهُ عَنْهُم، فَأَرْسَلَتْ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: كَيْفَ أَصْنَعُ؟ قَالَ: "اغْتَسِلِي وَاسْتَثْفِرِي بِثَوْبٍ وَأَحْرِمِي". فَصَلَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الْمَسْجِدِ ثُمَّ رَكِبَ الْقَصْوَاءَ، حَتَّى إِذَا اسْتَوَتْ بِهِ نَاقَتُهُ عَلَى الْبَيْدَاءِ نَظَرْتُ إِلَى مَدِّ بَصَرِي بَيْنَ يَدَيْهِ مِنْ رَاكِبٍ وَمَاشٍ، وَعَنْ يَمِينِهِ مِثْلَ ذَلِكَ، وَعَنْ يَسَارِهِ مِثْلَ ذَلِكَ، وَمِنْ خَلْفِهِ مِثْلَ ذَلِكَ، وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَيْنَ أَظْهُرِنَا وَعَلَيْهِ يَنْزِلُ الْقُرْآنُ، وَهُوَ يَعْرِفُ تَأْوِيلَهُ، وَمَا عَمِلَ بِهِ مِنْ شَيْءٍ عَمِلْنَا بِهِ، فَأَهَلَّ بِالتَّوْحِيدِ: "لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ، لَبَّيْكَ لَا شَرِيكَ لَكَ لَبَّيْكَ، إِنَّ الْحَمْدَ وَالنِّعْمَةَ لَكَ وَالْمُلْكَ، لَا شَرِيكَ لَكَ". وَأَهَلَّ النَّاسُ بِهَذَا الَّذِي يُهِلُّونَ بِهِ، فَلَمْ يَرُدَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَيْهِمْ شَيْئًا مِنْهُ، وَلَزِمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تَلْبِيَتَهُ. قَالَ جَابِرٌ رَضِيَ اللهُ عَنْهُ: لَسْنَا نَنْوِي إِلَّا الْحَجَّ، لَسْنَا نَعْرِفُ الْعُمْرَةَ، حَتَّى إِذَا أَتَيْنَا الْبَيْتَ مَعَهُ، اسْتَلَمَ الرُّكْنَ، فَرَمَلَ ثَلَاثًا وَمَشَى أَرْبَعًا، ثُمَّ نَفَذَ إِلَى مَقَامِ إِبْرَاهِيمَ عَلَيْهِ السَّلَام فَقَرَأَ: {وَاتَّخِذُوا مِنْ مَقَامِ إِبْرَاهِيمَ مُصَلًّى} [البقرة: ١٢٥] فَجَعَلَ الْمَقَامَ بَيْنَهُ وَبَيْنَ الْبَيْتِ. فَكَانَ أَبِي يَقُولُ – وَلَا أَعْلَمُهُ ذَكَرَهُ إِلَّا عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقْرَأُ فِي الرَّكْعَتَيْنِ {قُلْ هُوَ اللَّهُ أَحَدٌ} وَ {قُلْ يَا أَيُّهَا الْكَافِرُونَ}. ثُمَّ رَجَعَ إِلَى الرُّكْنِ فَاسْتَلَمَهُ، ثُمَّ خَرَجَ مِنَ الْبَابِ إِلَى الصَّفَا، فَلَمَّا دَنَا مِنَ الصَّفَا قَرَأَ: {إِنَّ الصَّفَا وَالْمَرْوَةَ مِنْ شَعَائِرِ اللَّهِ} [البقرة: ١٥٨] "أَبْدَأُ بِمَا بَدَأَ اللَّهُ بِهِ" فَبَدَأَ بِالصَّفَا فَرَقِيَ عَلَيْهِ حَتَّى رَأَى الْبَيْتَ، فَاسْتَقْبَلَ الْقِبْلَةَ، فَوَحَّدَ اللَّهَ وَكَبَّرَهُ، وَقَالَ: "لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ. لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ، أَنْجَزَ وَعْدَهُ، وَنَصَرَ عَبْدَهُ، وَهَزَمَ الْأَحْزَابَ وَحْدَهُ". ثُمَّ دَعَا بَيْنَ ذَلِكَ قَالَ مِثْلَ هَذَا ثَلَاثَ مَرَّاتٍ. ثُمَّ نَزَلَ إِلَى الْمَرْوَةِ، حَتَّى إِذَا انْصَبَّتْ قَدَمَاهُ فِي بَطْنِ الْوَادِي سَعَى، حَتَّى إِذَا صَعِدْنَا مَشَى حَتَّى أَتَى الْمَرْوَةَ، فَفَعَلَ عَلَى الْمَرْوَةِ كَمَا فَعَلَ عَلَى الصَّفَا، حَتَّى إِذَا كَانَ آخِرُ طَوَافِهِ عَلَى الْمَرْوَةِ قَالَ: "لَوْ أَنِّي اسْتَقْبَلْتُ مِنْ أَمْرِي مَا اسْتَدْبَرْتُ لَمْ أَسُقِ الْهَدْيَ، وَجَعَلْتُهَا عُمْرَةً، فَمَنْ كَانَ مِنْكُمْ لَيْسَ مَعَهُ هَدْيٌ فَلْيَحِلَّ، وَلْيَجْعَلْهَا عُمْرَةً". فَقَامَ سُرَاقَةُ بْنُ مَالِكِ بْنِ جُعْشُمٍ فَقَالَ: يَا رَسُولَ اللَّهِ، أَلِعَامِنَا هَذَا أَمْ لِأَبَدٍ؟ فَشَبَّكَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَصَابِعَهُ وَاحِدَةً فِي الْأُخْرَى وَقَالَ: "دَخَلَتِ الْعُمْرَةُ فِي الْحَجِّ – مَرَّتَيْنِ – لَا بَلْ لِأَبَدٍ [أَبَدٍ]". وَقَدِمَ عَلِيٌّ رَضِيَ اللهُ عَنْهُ مِنَ الْيَمَنِ بِبُدْنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَوَجَدَ فَاطِمَةَ رَضِيَ اللهُ عَنْهَا مِمَّنْ حَلَّ وَلَبِسَتْ ثِيَابًا صَبِيغًا وَاكْتَحَلَتْ، فَأَنْكَرَ ذَلِكَ عَلَيْهَا، فَقَالَتْ: [إِنَّ] أَبِي أَمَرَنِي بِهَذَا، قَالَ: فَكَانَ عَلِيٌّ يَقُولُ بِالْعِرَاقِ: فَذَهَبْتُ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُحَرِّشًا عَلَى فَاطِمَةَ لِلَّذِي صَنَعَتْ، مُسْتَفْتِيًا لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِيمَا ذَكَرَتْ عَنْهُ، فَأَخْبَرْتُهُ أَنِّي أَنْكَرْتُ ذَلِكَ عَلَيْهَا، فَقَالَ: "صَدَقَتْ صَدَقَتْ، مَاذَا قُلْتَ حِينَ فَرَضْتَ الْحَجَّ". قَالَ: قُلْتُ: اللَّهُمَّ إِنِّي أُهِلُّ بِمَا أَهَلَّ بِهِ رَسُولُكَ، قَالَ: "فَإِنَّ مَعِيَ الْهَدْيَ، فَلَا تَحِلُّ". قَالَ: فَكَانَ جَمَاعَةُ الْهَدْيِ الَّذِي قَدِمَ بِهِ عَلِيٌّ مِنَ الْيَمَنِ، وَالَّذِي أَتَى بِهِ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِائَةً. قَالَ: فَحَلَّ النَّاسُ كُلُّهُمْ وَقَصَّرُوا، إِلَّا النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَمَنْ كَانَ مَعَهُ هَدْيٌ. فَلَمَّا كَانَ يَوْمُ التَّرْوِيَةِ تَوَجَّهُوا إِلَى مِنًى، فَأَهَلُّوا بِالْحَجِّ وَرَكِبَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَصَلَّى بِهَا الظُّهْرَ وَالْعَصْرَ وَالْمَغْرِبَ وَالْعِشَاءَ وَالْفَجْرَ، ثُمَّ مَكَثَ قَلِيلًا حَتَّى طَلَعَتِ الشَّمْسُ، وَأَمَرَ بِقُبَّةٍ مِنْ شَعَرٍ تُضْرَبُ لَهُ بِنَمِرَةَ. فَسَارَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَلَا تَشُكُّ قُرَيْشٌ إِلَّا أَنَّهُ وَاقِفٌ عِنْدَ الْمَشْعَرِ الْحَرَامِ، كَمَا كَانَتْ قُرَيْشٌ تَصْنَعُ فِي الْجَاهِلِيَّةِ، فَأَجَازَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَتَّى أَتَى عَرَفَةَ، فَوَجَدَ الْقُبَّةَ قَدْ ضُرِبَتْ لَهُ بِنَمِرَةَ، فَنَزَلَ بِهَا، حَتَّى إِذَا زَاغَتِ الشَّمْسُ أَمَرَ بِالْقَصْوَاءِ فَرُحِلَتْ لَهُ، فَأَتَى بَطْنَ الْوَادِي، فَخَطَبَ النَّاسَ وَقَالَ: "إِنَّ دِمَاءَكُمْ وَأَمْوَالَكُمْ حَرَامٌ عَلَيْكُمْ، كَحُرْمَةِ يَوْمِكُمْ هَذَا، فِي شَهْرِكُمْ هَذَا، فِي بَلَدِكُمْ هَذَا، أَلَا كُلُّ شَيْءٍ مِنْ أَمْرِ الْجَاهِلِيَّةِ تَحْتَ قَدَمَيَّ مَوْضُوعٌ، وَدِمَاءُ الْجَاهِلِيَّةِ مَوْضُوعَةٌ، وَإِنَّ أَوَّلَ دَمٍ أَضَعُ مِنْ دِمَائِنَا دَمُ ابْنِ رَبِيعَةَ بْنِ الْحَارِثِ – كَانَ مُسْتَرْضِعًا فِي بَنِي سَعْدٍ فَقَتَلَتْهُ هُذَيْلٌ – وَرِبَا الْجَاهِلِيَّةِ مَوْضُوعٌ، وَأَوَّلُ رِبًا أَضَعُ [ربانا] رِبَا عَبَّاسِ بْنِ عَبْدِ الْمُطَّلِبِ، فَإِنَّهُ مَوْضُوعٌ كُلُّهُ، فَاتَّقُوا اللَّهَ فِي النِّسَاءِ، فَإِنَّكُمْ أَخَذْتُمُوهُنَّ بِأَمَانِ اللَّهِ، وَاسْتَحْلَلْتُمْ فُرُوجَهُنَّ بِكَلِمَةِ اللَّهِ، وَلَكُمْ عَلَيْهِنَّ أَنْ لَا يُوطِئْنَ فُرُشَكُمْ أَحَدًا تَكْرَهُونَهُ، فَإِنْ فَعَلْنَ ذَلِكَ فَاضْرِبُوهُنَّ ضَرْبًا غَيْرَ مُبَرِّحٍ. وَلَهُنَّ عَلَيْكُمْ رِزْقُهُنَّ وَكِسْوَتُهُنَّ بِالْمَعْرُوفِ، وَقَدْ تَرَكْتُ فِيكُمْ مَا لَنْ تَضِلُّوا بَعْدَهُ إِنِ اعْتَصَمْتُمْ بِهِ: كِتَابُ اللَّهِ، وَأَنْتُمْ تُسْأَلُونَ عَنِّي فَمَا أَنْتُمْ قَائِلُونَ". قَالُوا: نَشْهَدُ أَنَّكَ قَدْ بَلَّغْتَ وَأَدَّيْتَ وَنَصَحْتَ، فَقَالَ بِإِصْبَعِهِ السَّبَّابَةِ يَرْفَعُهَا إِلَى السَّمَاءِ وَيَنْكُتُهَا إِلَى النَّاسِ: "اللَّهُمَّ اشْهَدْ، اللَّهُمَّ اشْهَدْ". ثَلَاثَ مَرَّاتٍ. ثُمَّ أَذَّنَ ثُمَّ أَقَامَ، فَصَلَّى الظُّهْرَ، ثُمَّ أَقَامَ فَصَلَّى الْعَصْرَ، وَلَمْ يُصَلِّ بَيْنَهُمَا شَيْئًا. ثُمَّ رَكِبَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَتَّى أَتَى الْمَوْقِفَ فَجَعَلَ بَطْنَ نَاقَتِهِ الْقَصْوَاءِ إِلَى الصَّخَرَاتِ وَجَعَلَ حَبْلَ الْمُشَاةِ بَيْنَ يَدَيْهِ، وَاسْتَقْبَلَ الْقِبْلَةَ، فَلَمْ يَزَلْ وَاقِفًا حَتَّى غَرَبَتِ الشَّمْسُ، وَذَهَبَتِ الصُّفْرَةُ قَلِيلًا حَتَّى غَابَ الْقُرْصُ، وَأَرْدَفَ أُسَامَةَ خَلْفَهُ، وَدَفَعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَقَدْ شَنَقَ لِلْقَصْوَاءِ الزِّمَامَ حَتَّى إِنَّ رَأْسَهَا لَيُصِيبُ مَوْرِكَ رَحْلِهِ، وَيَقُولُ بِيَدِهِ الْيُمْنَى: "أَيُّهَا النَّاسُ، السَّكِينَةَ السَّكِينَةَ". كُلَّمَا أَتَى حَبْلًا مِنَ الْحِبَالِ أَرْخَى لَهَا قَلِيلًا حَتَّى تَصْعَدَ حَتَّى أَتَى الْمُزْدَلِفَةَ، فَصَلَّى بِهَا الْمَغْرِبَ وَالْعِشَاءَ، بِأَذَانٍ وَاحِدٍ وَإِقَامَتَيْنِ، وَلَمْ يُسَبِّحْ بَيْنَهُمَا شَيْئًا، ثُمَّ اضْطَجَعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَتَّى طَلَعَ الْفَجْرُ، فَصَلَّى الْفَجْرَ حِينَ تَبَيَّنَ لَهُ الصُّبْحُ بِأَذَانٍ وَإِقَامَةٍ. ثُمَّ رَكِبَ الْقَصْوَاءَ حَتَّى أَتَى الْمَشْعَرَ الْحَرَامَ، فَاسْتَقْبَلَ الْقِبْلَةَ، فَدَعَاهُ، وَكَبَّرَهُ، وَهَلَّلَهُ، وَوَحَّدَهُ، فَلَمْ يَزَلْ وَاقِفًا حَتَّى أَسْفَرَ جِدًّا، فَدَفَعَ قَبْلَ أَنْ تَطْلُعَ الشَّمْسُ، وَأَرْدَفَ الْفَضْلَ بْنَ عَبَّاسٍ – وَكَانَ رَجُلًا حَسَنَ الشَّعْرِ أَبْيَضَ وَسِيمًا – فَلَمَّا دَفَعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَرَّتْ بِهِ ظُعُنٌ يَجْرِينَ، فَطَفِقَ الْفَضْلُ يَنْظُرُ إِلَيْهِنَّ، فَوَضَعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَدَهُ عَلَى وَجْهِ الْفَضْلِ فَحَوَّلَ الْفَضْلُ وَجْهَهُ إِلَى الشِّقِّ الْآخَرِ يَنْظُرُ، فَحَوَّلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَدَهُ مِنَ الشِّقِّ الْآخَرِ عَلَى وَجْهِ الْفَضْلِ يَصْرِفُ وَجْهَهُ مِنَ الشِّقِّ الْآخَرِ يَنْظُرُ، حَتَّى أَتَى بَطْنَ مُحَسِّرٍ فَحَرَّكَ قَلِيلًا، ثُمَّ سَلَكَ الطَّرِيقَ الْوُسْطَى الَّتِي تَخْرُجُ عَلَى الْجَمْرَةِ الْكُبْرَى، حَتَّى أَتَى الْجَمْرَةَ الَّتِي عِنْدَ الشَّجَرَةِ فَرَمَاهَا بِسَبْعِ حَصَيَاتٍ، يُكَبِّرُ مَعَ كُلِّ حَصَاةٍ مِنْهَا، [مِثْلِ] حَصَى الْخَذْفِ، رَمَى مِنْ بَطْنِ الْوَادِي، ثُمَّ انْصَرَفَ إِلَى الْمَنْحَرِ فَنَحَرَ ثَلَاثًا وَسِتِّينَ بِيَدِهِ، ثُمَّ أَعْطَى عَلِيًّا رَضِيَ اللهُ عَنْهُ فَنَحَرَ مَا غَبَرَ وَأَشْرَكَهُ فِي هَدْيِهِ، ثُمَّ أَمَرَ مِنْ كُلِّ بَدَنَةٍ بِبَضْعَةٍ فَجُعِلَتْ فِي قِدْرٍ فَطُبِخَتْ، فَأَكَلَا مِنْ لَحْمِهَا، وَشَرِبَا مِنْ مَرَقِهَا. ثُمَّ رَكِبَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَفَاضَ إِلَى الْبَيْتِ، فَصَلَّى بِمَكَّةَ الظُّهْرَ، فَأَتَى بَنِي عَبْدِ الْمُطَّلِبِ يَسْقُونَ عَلَى زَمْزَمَ، فَقَالَ: "انْزِعُوا بَنِي عَبْدِ الْمُطَّلِبِ، فَلَوْلَا أَنْ يَغْلِبَكُمُ النَّاسُ عَلَى سِقَايَتِكُمْ لَنَزَعْتُ مَعَكُمْ". فَنَاوَلُوهُ دَلْوًا فَشَرِبَ مِنْهُ. (م,د,جه)', 'ജഅ്ഫറുബ്നു മുഹമ്മദ്(റ): അദ്ദേഹം തന്റെ പിതാവിൽ നിന്ന് നിവേദനം ചെയ്യുന്നു: ഞങ്ങളൊരിക്കൽ ജാബിറുബ്നു അബ്ദുല്ല(റ)വിന്റെ അടുക്കൽ ചെന്നു. അപ്പോൾ അദ്ദേഹം നിങ്ങളാരാണ് എന്ന് ചോദിച്ചു കൊണ്ടു ഞങ്ങളിൽ ഓരോരുത്തരുമായും പരിചയപ്പെട്ടു. അങ്ങിനെ എന്നെക്കുറിച്ചു ചോദിച്ചപ്പോൾ ഞാൻ പറഞ്ഞു: ഞാൻ ഹുസൈൻ(റ)വിന്റെ മകനായ അലി(റ)വിന്റെ മകനാണ്. ഉടനെ അദ്ദേഹം എന്റെ തലയിലേക്ക് കൈനീട്ടുകയും, എന്റെ (ഷർട്ടിന്റെ) മേൽഭാഗത്തും, താഴ്ഭാഗത്തും ഉള്ള ബട്ടൻസ് അഴിക്കുകയും, എന്നിട്ട് അദ്ദേഹത്തിന്റെ മുൻകൈ എന്റെ നെഞ്ചിൽ വെക്കുകയും ചെയ്തു. ഞാൻ അന്ന് ഒരു യുവാവാണ്. അനന്തരം അദ്ദേഹം പറഞ്ഞു: എന്റെ സഹോദര പുത്രാ, നിനക്ക് സ്വാഗതം, നീ ഉദ്ദേശിക്കുന്ന കാര്യം എന്നോട് ചോദിച്ചു കൊള്ളുക. അദ്ദേഹം (അന്ന്) അന്ധനാണ്. അന്നേരം നമസ്കാര സമയം ആസന്നമായി തന്നിമിത്തം അദ്ദേഹം ഒരു വസ്ത്രം ചുറ്റിപ്പുതച്ചു കൊണ്ട് നമസ്കരിക്കാൻ എഴുന്നേറ്റു നിന്നു. ആ വസ്ത്രം ചെറുതായത് കൊണ്ട്, അദ്ദേഹം അത് ചുമലിൽ വെക്കുമ്പോഴെല്ലാം അതിന്റെ ഒരു ഭാഗം ഇഴഞ്ഞു വീണുകൊണ്ടിരുന്നു. അദ്ദേഹത്തിന്റെ തട്ടം വലതു ഭാഗത്ത് ഒരു സ്റ്റാന്റിൻമേൽ ഉണ്ടായിരുന്നു. അങ്ങിനെ അദ്ദേഹം ഞങ്ങളെയും കൊണ്ട് നമസ്കരിച്ചു. ഞാൻ (അദ്ദേഹത്തോട്) പറഞ്ഞു: റസൂൽ(സ)യുടെ ഹജ്ജിനെക്കുറിച്ച് എനിക്ക് ഒന്ന് പറഞ്ഞു തന്നാലും. ഉടനെ അദ്ദേഹം തന്റെ (കൈവിരൽ) കൊണ്ട് ഒമ്പത് വരെ എണ്ണുകയും എന്നിട്ട് ഇപ്രകാരം പറയുകയും ചെയ്തു. റസൂൽ(സ) ഹജ്ജ് ചെയ്യാതെ ഒമ്പത് വർഷം കഴിച്ചുകൂട്ടി. അനന്തരം പത്താം വർഷം ജനമധ്യേ അവിടുന്ന് ഇപ്രകാരം പ്രഖ്യാപിച്ചു: അല്ലാഹുവിന്റെ പ്രവാചകൻ(ഈ വർഷം) ഹജ്ജ് ചെയ്യുവാനുദ്ദേശിക്കുന്നു. അതോടെ തിരുമേനി(സ)യെ തുടർന്ന് ഹജ്ജ് ചെയ്യുവാനും അവിടുന്ന് പ്രവർത്തിക്കുന്ന പോലെ പ്രവർത്തിക്കുവാനുമായി ധാരാളം ആളുകൾ മദീനയിൽ എത്തി. അനന്തരം ഞങ്ങൾ അവിടുത്തോടൊപ്പം (ഹജ്ജിനായി മക്കയിലേക്ക്) പുറപ്പെട്ടു. ഞങ്ങൾ ദുൽഹുലൈഫയിലെത്തിയപ്പോൾ ഉമൈസിന്റെ മകൾ അസ്മാഅ്(റ) മുഹമ്മദുബ്നു അബീബക്കർ(റ)വിനെ പ്രസവിച്ചു. അന്നേരം ഞാനെന്ത് ചെയ്യണമെന്ന് അന്വേഷിച്ച് കൊണ്ട് അസ്മാഅ്(റ) തിരുമേനി(സ)യുടെ അടുക്കലേക്ക് ആളെ അയച്ചു. തിരുമേനി(സ) അരുളി: "നീ കുളിക്കുകയും ഒരു വസ്ത്രം കൊണ്ട് നല്ലവണ്ണം തുടക്കുകയും എന്നിട്ട് ഇഹ്റാം കെട്ടുകയും ചെയ്തു കൊള്ളുക." എന്നിട്ട് തിരുമേനി(സ) (ദുൽഹുലൈഫഃയിലെ) പള്ളിയിൽ കയറി രണ്ട് (റക്അത്ത്) നമസ്കരിച്ചു. അനന്തരം അവിടുന്ന് ഒട്ടകപ്പുറത്ത് കയറി. അങ്ങനെ തിരുമേനി(സ)യെയും കൊണ്ട് അവിടുത്തെ ഒട്ടകം ആ മരുഭൂമിയിൽ നിവർന്നു നിന്നപ്പോൾ, ഞാനെന്റെ ദൃഷ്ടി എത്തുന്നിടത്തേക്കെല്ലാം ഒന്നു കണ്ണോടിച്ചു. അപ്പോഴതാ അവിടുത്തെ മുന്നിലും, പിന്നിലും, വലതുഭാഗത്തും, ഇടഭാഗത്തും, നടക്കുന്നവരും, സവാരി ചെയ്യുന്നവരുമായി ധാരാളം ആളുകൾ (നിറഞ്ഞു നിൽക്കുന്നു.) തിരുമേനി(സ) ഞങ്ങളുടെ മധ്യത്തിലും സ്ഥിതി ചെയ്യുന്നു. അവിടുത്തേക്കാണ് ഖുർആൻ അവതരിക്കുന്നത്. അതിന്റെ വ്യാഖ്യാനം ശരിക്കും അറിയുന്നതും തിരുമേനി(സ)ക്ക് മാത്രമാണ്. (അതുകൊണ്ട്) അവിടുന്ന് ചെയ്യുന്നതെല്ലാം ഞങ്ങളും ചെയ്തു കൊണ്ടിരുന്നു. അവിടുന്ന് "ലബ്ബൈകല്ലാഹുമ്മ ലബ്ബൈക ലാ ശരീക ലക ലബ്ബൈക ഇന്നൽ ഹംദ വന്നിഅ്മദ ലക വൽ മുൽക ലാ ശരീക ലക" എന്ന് ഉച്ചത്തിൽ ചൊല്ലിക്കൊണ്ട് ഏകദൈവിസിദ്ധാന്തം പ്രഖ്യാപിച്ചു. (അല്ലാഹുവേ, നിന്റെ വിളിക്ക് ഉത്തരം നൽകിക്കൊണ്ട് ഞാനിതാ വന്നിരിക്കുന്നു. നിനക്ക് യാതൊരു പങ്കുകാരനുമില്ല. നിന്റെ വിളക്കുത്തരം നൽകിക്കൊണ്ട് ഞാനിതാ വന്നിരിക്കുന്നു. നിശ്ചയമായും സർവ്വ സ്തുതിയും, അനുഗ്രഹം ചെയ്യുവാനുള്ള കഴിവും നിനക്കാണ്. ആധിപത്യവും, നിനക്കാണ്. നിനക്ക് യാതൊരു പങ്കുകാരുമില്ല.) ഈ തൽബിയത് ജനങ്ങളും ഉച്ചത്തിൽ ചൊല്ലിക്കൊണ്ടിരുന്നു. തിരുമേനി(സ) അവരെ തടഞ്ഞില്ല. തിരുമേനി(സ)യും തൽബിയത് ചൊല്ലിക്കൊണ്ടേയിരുന്നു. ജാബിർ(റ) പറയുന്നു: ഹജ്ജല്ലാതെ മറ്റൊന്നും അന്നേരം ഞങ്ങൾ ഉദ്ദേശിച്ചിരുന്നില്ല. ഉംറ ഞങ്ങൾക്ക് അറിയുമായിരുന്നില്ല. അങ്ങനെ ഞങ്ങൾ അവിടത്തോടൊപ്പം കഅ്ബയുടെ അടുത്തെത്തിയപ്പോൾ തിരുമേനി(സ) റുക്ന്(ഹജറുൽ അസ്വദ്) കൈകൊണ്ട് തൊടുകയും എന്നിട്ട് മൂന്ന് പ്രാവശ്യം കാലടികൾ അടുപ്പിച്ചു വെച്ചുകൊണ്ട് ഓടിനടക്കുകയും നാല് പ്രാവശ്യം സാധാരണ നടത്തം നടക്കുകയും ചെയ്തു. അനന്തരം അവിടുന്ന് മഖാമ് ഇബ്റാഹീമിലേക്ക് മുന്നേറുകയും, ''മഖാമ് ഇബ്റാഹീമിനെ നിങ്ങൾ നമസ്കാര സ്ഥലമാക്കുക'' എന്ന ഖുർആൻ വാക്യം പാരായണം ചെയ്യുകയും എന്നിട്ട് മഖാമു ഇബ്റാഹീമിനെ കഅ്ബയുടെയും തിരുമേനി(സ)യുടെയും മധ്യത്തിലാക്കിക്കൊണ്ട് രണ്ട് റക്അത്ത് നമസ്കരിക്കുകയും ചെയ്തു. എന്റെ പിതാവ് മുഹമ്മദ്(റ) ഇങ്ങനെ പറയാറുണ്ടായിരുന്നു. തിരുമേനി(സ) ആ രണ്ട് റക്അത്തിൽ, ഇഖ്ലാസ് സൂറതും, കാഫിറൂൻ സൂറതും പാരായണം ചെയ്തിരുന്നു. അദ്ദേഹം ഇത് തിരുമേനി(സ)യെ ഉദ്ധരിച്ചു കൊണ്ടല്ലാതെ പറഞ്ഞിട്ടില്ല എന്നാണ് ഞാൻ വിചാരിക്കുന്നത്. അവിടുന്ന് റുക്നിന്റെ അടുക്കലേക്ക് മടങ്ങുകയും അതിനെ കൈകൊണ്ട് തൊടുകയും ചെയ്തു. ശേഷം തിരുമേനി(സ) വാതിലിലൂടെ സഫായിലേക്ക് പുറപ്പെടുകയും അതിന്റെ അടുത്തെത്തയപ്പോൾ ''നിശ്ചയമായും സ്വഫായും മർവായും അല്ലാഹുവിന്റെ ചിഹ്നങ്ങളിൽ പെട്ടതാണ്'' (2: 158) എന്ന ഖുർആൻ വാക്യം പാരായണം ചെയ്യുകയും, "അല്ലാഹു ആരംഭിച്ചതു കൊണ്ട് ഞാനും ആരംഭിക്കുന്നു." എന്നു പറഞ്ഞു കൊണ്ട് സഫായിൽ നിന്ന് നടക്കാൻ ആരംഭിക്കുകയും ചെയ്തു. അങ്ങനെ കഅ്ബ കാണത്തക്ക ഉയരം വരെ സഫായുടെ മുകളിലേക്ക് കയറുകയും ഖിബ്ലയെ അഭിമുഖീകരിച്ചു കൊണ്ട് അല്ലാഹുവിന്റെ ഏകത്വം പ്രഖ്യാപിക്കുകയും, അവനെ മഹത്വപ്പെടുത്തുകയും, "ലാ ഇലാഹ ഇല്ലല്ലാഹു വഹ്ദഹു ലാ ശരീക ലഹു ലഹുൽ മുൽകു വലഹുൽ ഹംദു വഹുവ അലാ കുല്ലി ശൈഇൻ ഖദീർ, ലാഇലാഹ ഇല്ലല്ലാഹു വഹ്ദഹു അൻജസ വഅ്ദഹു വനസ്വറ അബ്ദഹു വഹസമൽ അഹ്സാബ വഹ്ദഹു" എന്ന് പറയുകയും ചെയ്തു. (അല്ലാഹു ഒഴികെ യാതൊരു ആരാധ്യനുമില്ല. അവൻ ഏകനാണ്. അവന് യാതൊരു പങ്കുകാരനുമില്ല. അവനാണ് ആധിപത്യം. സർവ്വ സ്തുതിയും അവനു തന്നെ. അവൻ എല്ലാ കാര്യങ്ങൾക്കും കഴിവുള്ളവനാണ്. അല്ലാഹു ഒഴികെ യാതൊരു ആരാധ്യനുമില്ല. അവൻ ഏകനാണ്. ഏകനായ അവൻ തന്റെ വാഗ്ദത്തം നിറവേറ്റുകയും, തന്റെ ദാസനെ സഹായിക്കുകയും എല്ലാ വിഭാഗങ്ങളെയും പരാജയപ്പെടുത്തി ആട്ടിയോടിക്കുകുയം ചെയ്തിരിക്കുന്നു.) ഇങ്ങനെ മൂന്നു പ്രാവശ്യം അവിടുന്ന് പറഞ്ഞു: ഇവയുടെ ഇടക്ക് അവിടുന്ന് പ്രാർത്ഥിക്കുകയും ചെയ്തിരുന്നു, അനന്തരം അവിടുന്ന് മർവയിലേക്ക് കേറുവാനായി ഇറങ്ങുകയും, അങ്ങനെ മർവ താഴ്വരയുടെ സമതലത്തിൽ എത്തിയപ്പോൾ അതിലൂടെ ഓടിനടക്കുകയും മർവയിലേക്ക് അൽപ്പം കേറിയപ്പോൾ സാധാരണ നടത്തം നടക്കുകയും ചെയ്തു. അങ്ങനെ അവിടുന്ന് മർവയിൽ എത്തി. എന്നിട്ട് സഫായുടെ മുകളിൽ വെച്ച് ചെയ്ത പ്രകാരം മർവ്വയുടെ മുകളിൽ വെച്ചും ചെയ്തു. മർവയിൽ വെച്ച് നടത്തം അവസാനിച്ചപ്പോൾ അവിടുന്ന് അരളി: "ഞാൻ മുമ്പ് ചെയ്ത കാര്യങ്ങൾ ചെയ്യുവാൻ ഭാവിയിൽ എനിക്കവസരം ലഭിക്കുകയാണെങ്കിൽ, ഞാൻ ബലി മൃഗം കൊണ്ടു വരാതിരിക്കുകയും അത് ഉംറഃ യാക്കുകയും ചെയ്യുന്നതാണ്. അതു കൊണ്ട് നിങ്ങളിൽ ബലിമൃഗം കൂടെ ഇല്ലാത്തവർ ഇത് ഉംറയായി കണക്കാക്കുകയും, എന്നിട്ട് ഇതിൽ നിന്ന് വിരമിക്കുകയും ചെയ്തു കൊള്ളുക." അന്നേരം സുറാഖതുബ്നു മാലികുബ്നു ജുഅ്ശും എഴുന്നേറ്റു ചോദിച്ചു: "അല്ലാഹുവിന്റെ ദൂതരേ, (ഹജ്ജിന് ഇഹ്റാം കെട്ടിവരികയും എന്നിട്ട് അത് ഉംറഃ യാക്കി മാറ്റുകയും ചെയ്യുക എന്നത്) നമ്മുടെ ഈ വർഷത്തേക്കു മാത്രമുള്ള നിയമമാണോ? അതോ എല്ലാ കാലത്തേക്കും ബാധകമായതോ? അന്നേരം തിരുമേനി(സ) അവിടുത്തെ ഇരു കൈകളിലെയും വിരലുകൾ പരസ്പരം കോർത്തുകാണിച്ചു കൊടുത്തു കൊണ്ട് "ഉംറഃ ഹജ്ജിൽ ഉൾപ്പെട്ടിരിക്കുന്നു" എന്ന് രണ്ടു പ്രാവശ്യം അരുളുകയും, "ഇത് ഈ വർഷത്തേക്കു മാത്രമുള്ള നിയമമല്ല, മറിച്ച് എല്ലാ കാലത്തേക്കും ബാധകമായ നിയമമാണ്" എന്ന് ആവർത്തിച്ച് അരുളുകയും ചെയ്തു. അലി(റ) യമനിൽ നിന്ന് റസൂൽ(സ)യുടെ ഒട്ടകങ്ങളെയും കൊണ്ട് വന്നപ്പോൾ ഫാത്വിമ(റ) ഉംറഃ ചെയ്തു വിരമിക്കുകയും, ചായം മുക്കിയ വസ്ത്രം ധരിക്കുകയും, കൺമഷി ഉപയോഗിക്കുകയും ചെയ്തതായി കണ്ടു. തന്നിമിത്തം അതിന്റെ പേരിൽ അലി(റ) അവരോട് പ്രതിഷേധിച്ചു. അപ്പോൾ ഫാത്വിമ(റ) പറഞ്ഞു: നിശ്ചയമായും എന്റെ പിതാവാണ് എന്നോട് ഇതിന് കൽപ്പിച്ചത്. നിവേദകൻ പറയുന്നു: അലി(റ) ഇറാഖിൽ വെച്ചു ഇങ്ങനെ പറയാറുണ്ടായിരുന്നു: ഉടനെ ഫാത്വിമ(റ) ചെയ്ത പ്രവർത്തിയുടെ പേരിൽ തിരുമേനി(സ)യെ അവർക്കെതിരിൽ ഇളക്കി വിടുവാനും അതിനെക്കുറിച്ച് ഞാൻ പ്രകടിപ്പിച്ച അഭിപ്രായത്തെ സംബന്ധിച്ചു വിധി അന്വേഷിക്കുവാനുമായി ഞാൻ റസൂൽ(സ)യുടെ അടുക്കലേക്ക് പോവുകയും, അതിനെക്കുറിച്ച് ഞാൻ ഫാത്വിമ(റ)യോട് പ്രതിഷേധിച്ചു എന്നുള്ള വിവരം തിരുമേനി(സ)യെ അറിയിക്കുകും ചെയ്തു. അപ്പോൾ തിരുമേനി(സ) അരുളി: "അവൾ പറഞ്ഞത് ശരിയാണ്. അവൾ പറഞ്ഞത് ശരിയാണ്. നീ ഹജ്ജിന് ഇഹ്റാം കെട്ടിയപ്പോൾ എന്ത് പറഞ്ഞുകൊണ്ടാണ് ഇഹ്റാം കെട്ടിയത്? അലി(റ) പറഞ്ഞു: അല്ലാഹുവേ, നിന്റെ പ്രവാചകൻ ഏതിന് ഇഹ്റാം കെട്ടിയിരിക്കുന്നുവോ അതിന് ഞാനും ഇഹ്റാം കെട്ടുന്നു എന്നാണ് ഞാൻ പറഞ്ഞത്. തിരുമേനി(സ) അരുളി: "എന്റെ കൂടെ ബലിമൃഗമുണ്ട്. ''അതുകൊണ്ട് ഇതിനെ ബലിഅറുക്കുന്നത് വരെ എനിക്ക് വിരമിക്കുവാൻ പാടില്ല.'' അത് കൊണ്ട് നീയും വിരമിക്കരുത്." നിവേദകൻ പറയുന്നു: റസൂൽ(സ) കൊണ്ടുവന്നതും അലി(റ) യമനിൽ നിന്ന് കൊണ്ടുവന്നതും കൂടി ബലിമൃഗങ്ങൾ ആകെ നൂറെണ്ണമുണ്ടായിരുന്നു. നിവേദകൻ പറയുന്നു: റസൂൽ(സ)യും ബലിമൃഗം കൂടെക്കൊണ്ടുവന്നവരും ഒഴികെയുള്ളവരെല്ലാം മുടി വെട്ടുകയും (ഉംറഃ ചെയ്ത്) വിരമിക്കുകയും ചെയ്തു. ദുൽഹജ്ജ് എട്ടിന് അവർ മിനായിലേക്ക് പുറപ്പെടുകയും, ഹജ്ജിന് ഇഹ്റാം കെട്ടുകയും തിരുമേനി(സ) വാഹനത്തിൽ കയറുകയും ചെയ്തു. തുടർന്ന് മിനായിൽ വെച്ച് തിരുമേനി(സ) ളുഹ്റ്, അസർ, മഗ്രിബ്, ഇശാ, സുബ്ഹി എന്നിവ നമസ്കരിക്കുകയും എന്നിട്ട് സൂര്യൻ ഉദിക്കുന്നതു വരെയുള്ള അൽപ്പ സമയം അവിടെ കഴിച്ചുകൂട്ടുകയും ''നമിറഃ''യിൽ അവിടുത്തേക്ക് വേണ്ടി രോമം (തുകൽ) കൊണ്ട് ഒരു തമ്പ് നിർമ്മിക്കുവാൻ കൽപ്പിക്കുകയും ചെയ്തു. തിരുമേനി(സ) യാത്ര തുടർന്നു. റസൂൽ(സ) (മുസ്ദലിഫഃയിൽ പെട്ട) മശ്അറുൽ ഹറാം എന്ന സ്ഥലത്ത് നിൽക്കും എന്ന് ഖുറൈശികൾ വിചാരിച്ചു. അജ്ഞാന കാലത്ത് അവർ അങ്ങനെ ചെയ്തിരുന്നു. എന്നാൽ റസൂൽ(സ) മശ്അറുൽ ഹറാമും കടന്ന് അറഫയുടെ സമീപം വരെ പോയി. അപ്പോൾ നമിറഃത്തിൽ അവിടുത്തേക്ക് വേണ്ടി നിർമ്മിക്കപ്പെട്ട തമ്പ് കാണുകയും അവിടെ ഇറങ്ങി വിശ്രമിക്കുകയും ചെയ്തു. സൂര്യൻ മധ്യാഹ്നത്തിൽ നിന്ന് തെറ്റിയപ്പോൾ, അവിടുന്ന് ഒട്ടകത്തെ കൊണ്ടു വരാൻ കൽപ്പിക്കുകയും. അതിന്റെ പുറത്ത് കൂടാരം വെച്ചുകെട്ടുകയും ചെയ്തു. ഉടനെ അവിടുന്ന് (വാഹനത്തിൽ കയറി) ഉർനഃ താഴ്വരയിൽ ചെല്ലുകയും ജനങ്ങളെ അഭിമുഖീകരിച്ച് പ്രസംഗിക്കുകയും ചെയ്തു. ആ പ്രസംഗത്തിൽ അവിടുന്ന് അരുളി: "(ആദരണീയമായ) ഈ നാട്ടിൽ (ആദരണീയമായ) ഈ മാസത്തിൽ (ആദരണീയമായ) ഈ ദിവസം എത്ര പവിത്രവും പരിശുദ്ധവുമാണോ അതു പോലെ പവിത്രവും ആദരണീയവുമാണ് നിങ്ങളുടെ രക്തവും നിങ്ങളുടെ സമ്പത്തും. ശ്രദ്ധിക്കുക. എല്ലാ വിധ അനിസ്ലാമിക പ്രവണതകളും ഞാനിതാ ചവിട്ടിത്താഴ്ത്തിയിരിക്കുന്നു. അനിസ്ലാമിക കാലത്തെ രക്തം (അനിസ്ലാമിക കാലത്ത് നടന്ന വധത്തിന് പ്രതികാരം ചെയ്യുവാനുള്ള അവകാശം) എന്റെ പാദങ്ങൾക്കിടയിൽ ഞാനിതാ ചവിട്ടിത്താഴ്ത്തിയിരിക്കുന്നു. (ദുർബ്ബലപ്പെടുത്തിയിരിക്കുന്നു) ഈ വിഷയത്തിൽ ഒന്നാമതായി ഞാനെന്റെ പാദങ്ങൾക്കടിയിൽ വെച്ച് ചവിട്ടിത്താഴ്ത്തുന്നത് റബീഅതുബ്നുൽ ഹാരിസിന്റെ മകനെ വധിച്ചതിന്റെ പ്രതികാരവാകാശമാണ്." അദ്ദേഹം ബനൂ സഅ്ദ് ഗോത്രക്കാരുടെ അടുക്കൽ വളർത്തപ്പെടുന്ന ഒരു ശിശുവായിരുന്നു. ഹുദൈൽ ഗോത്രക്കാർ ആ കുട്ടിയെ വധിച്ചു കളഞ്ഞു: "അനിസ്ലാമിക പലിശയും ഞാനിതാ ചവിട്ടിത്താഴ്ത്തിയിരിക്കുന്നു." ആദ്യമായി ഞാൻ ദുർബ്ബലപ്പെടുത്തുന്നത് അബ്ദുൽ മുത്വലിബിന്റെ മകൻ അബ്ബാസിന് കിട്ടാനുള്ള പലിശയാണ്. അതുമുഴുവൻ ഞാനിതാ റദ്ദ് ചെയ്തിരിക്കുന്നു. സ്ത്രീകളുടെ കാര്യത്തിൽ നിങ്ങൾ അല്ലാഹുവിനെ സൂക്ഷിക്കുക. നിശ്ചയമായും അല്ലാഹു നിശ്ചയിച്ച സംരക്ഷണ ബാധ്യതയോടെയാണ് നിങ്ങൾ അവരെ സ്വീകരിച്ചിരിക്കുന്നത്. അല്ലാഹുവിന്റെ വചനമനുസരിച്ചാണ് നിങ്ങൾ അവരെ ഭാര്യമാരാക്കിയിരിക്കുന്നത്. നിങ്ങളിഷ്ടപ്പെടാത്ത യാതൊരാളെയും നിങ്ങളുടെ ഭവനത്തിൽ പ്രവേശിപ്പിക്കാതിരിക്കുകയെന്നത് അവർക്ക് നിങ്ങളോടുള്ള ബാധ്യതയാണ്. ഈ ബാധ്യത അവർ നിറവേറ്റാതിരുന്നാൽ കഠിനമല്ലാത്ത വിധത്തിൽ നിങ്ങൾ അവരെ അടിക്കുക. അവർക്ക് മിതമായ നിലക്ക് ആഹാരവും വസ്ത്രവും നൽകൽ നിങ്ങളുടെ ബാധ്യതയാണ്. നിശ്ചയമായും ഒരു കാര്യം ഞാൻ നിങ്ങളെ ഏൽപ്പിച്ചിരിക്കുന്നു. അത് നിങ്ങൾ മുറുകെപ്പിടിക്കുന്ന പക്ഷം പിന്നീടൊരിക്കലും നിങ്ങൾക്ക് മാർഗ്ഗഭ്രംശം സംഭവിക്കുകയില്ല. അല്ലാഹുവിന്റെ ഗ്രന്ഥമായ ഖുർആൻ ആണത്. എന്നെ സംബന്ധിച്ച് നിങ്ങൾ ചോദിക്കപ്പെടുന്നതാണ്. അന്നേരം എന്താണ് നിങ്ങൾ മറുപടി പറയുക?" അവർ പറഞ്ഞു: അങ്ങ് പ്രബോധനം ചെയ്യുകയും, ദൗത്യം നിർവ്വഹിക്കുകയും സദുപദേശം നൽകുകയും ചെയ്തിരിക്കുന്നുവെന്ന് ഞങ്ങൾ സാക്ഷ്യം വഹിക്കും. അന്നേരം തിരുമേനി(സ) അവിടുത്തെ ചൂണ്ടുവിരൽ കൊണ്ട് ആകാശത്തേക്കും ജനങ്ങളുടെ നേരെയും മാറിമാറി ചൂണ്ടിക്കാണിച്ചു കൊണ്ട് "അല്ലാഹുവേ, നീ സാക്ഷ്യം വഹിക്കുക. അല്ലാഹുവേ, നീ സാക്ഷ്യം വഹിക്കുക" എന്ന് മൂന്നു പ്രാവശ്യം ആവർത്തിച്ച് പറഞ്ഞു. അനന്തരം അവിടുന്ന് ബാങ്കും ഇഖാമത്തും വിളിച്ച് ളുഹ്റ് നമസ്കരിക്കുകയും ശേഷം ഇഖാമത്ത് വിളിച്ച് അസർ നമസ്കരിക്കുകയും ചെയ്തു. ഈ രണ്ട് നമസ്കാരങ്ങളുടെയും ഇടക്ക് യാതൊരു സുന്നത്ത് നമസ്കാരവും അവിടുന്ന് നമസ്കരിച്ചിട്ടില്ല. തുടർന്ന് തിരുമേനി(സ) വാഹനത്തിൽ കയറി. അറഫഃയിൽ പോവുകയും, അവിടുത്തെ ഒട്ടകത്തിന്റെ കയർ ''സഖ്റാത്തിന്റെ'' നേരെയും ജനങ്ങൾ തടിച്ചു കൂടുന്ന സ്ഥലം മുന്നിലുമാക്കി കഅ്ബയെ അഭിമുഖീകരിച്ചു കൊണ്ട്, സൂര്യൻ അസ്തമിക്കുകയും ശോഭ അൽപ്പം മറയുകയും ചെയ്യുന്നത് വരെ അവിടെ നിൽക്കുകയും ചെയ്തു. അനന്തരം ഉസാമ(റ)വിനെ വാഹനത്തിന്റെ പിന്നിൽ കയറ്റിക്കൊണ്ട് തിരുമേനി(സ) (മുസ്ദലിഫയിലേക്ക്) പുറപ്പെട്ടു. അവിടുന്ന് ഒട്ടകത്തിന്റെ കടിഞ്ഞാൺ വലിച്ച് പിടിച്ചിരുന്നു. തന്നിമിത്തം അതിന്റെ തല അവിടുത്തെ ചവിട്ടിയെ സ്പർശിച്ചു കൊണ്ടിരിക്കുന്നുണ്ടായിരുന്നു. അവിടുന്ന് വലതു കൈകൊണ്ട് ആംഗ്യം മുഖേന, "ഹേ ജനങ്ങളേ! ശാന്തരാവുക" എന്ന് പറയുന്നുണ്ടായിരുന്നു. ഒട്ടകം ഏതെങ്കിലും മണൽകൂനകളിൽ എത്തുമ്പോഴെല്ലാം അതു കയറുന്നത് വരെ അവിടുന്ന് കടിഞ്ഞാൺ അയച്ചു കൊടുത്തിരുന്നു. അങ്ങിനെ അവിടുന്ന് മുസ്ദലിഫയിൽ എത്തുകയും, ഉടനെ അവിടെ വെച്ച് ഒരു ബാങ്കും രണ്ട് ഇഖാമത്തും വിളിച്ചു കൊണ്ട് മഗ്രിബും ഇശാഉം നമസ്കരിക്കുകയും ചെയ്തു. ആ രണ്ട് നമസ്കാരത്തിന്റെ ഇടക്ക് യാതൊരു സുന്നത്ത് നമസ്കാരവും അവിടുന്ന് നമസ്കരിച്ചിട്ടില്ല. അനന്തരം പ്രഭാതം പ്രത്യക്ഷപ്പെടുന്നത് വരെ തിരുമേനി(സ) അവിടെ ചെരിഞ്ഞു കിടക്കുകയും സുബ്ഹി ആയപ്പോൾ, ബാങ്കും ഇഖാമത്തും വിളിച്ചുകൊണ്ട് സുബ്ഹി നമസ്കരിക്കുകയും ചെയ്തു. അവിടുന്ന് ഒട്ടകപ്പുറത്ത് കയറി ''മശ്അറുൽ ഹറാം'' എന്ന സ്ഥലത്ത് (മുസ്ദലിഫയിലുള്ള ഒരു സ്ഥലം) ചെല്ലുകയും ഖിബ്ലയെ അഭിമുഖീകരിച്ചുകൊണ്ട് അല്ലാഹുവിനോട് പ്രാർത്ഥിക്കുകയും, അവനെ മഹത്വപ്പെടുത്തുകയും, അവനല്ലാതെ വേറെ യാതൊരു ആരാധ്യനുമില്ലെന്നും അവൻ ഏകാനാണെന്നും പ്രഖ്യാപിക്കുകയും, ചെയ്തുകൊണ്ട് നല്ലവണ്ണം നേരം പുലരുന്നത് വരെ അവിടെ (മുസ്ദലിഫയിൽ) കഴിച്ചുകുട്ടി. സൂര്യൻ ഉദിക്കുന്നതിന് മുമ്പായി ഫള്ലുബ്നു അബ്ബാസ്(റ)വിനെ വാഹനത്തിന് പിന്നിൽ ഇരുത്തിക്കൊണ്ട് തിരുമേനി(സ) അവിടെ നിന്ന് പുറപ്പെട്ടു. ഫള്ലുബ്നു അബ്ബാസ്(റ) സുമുഖനും സുന്ദരനുമായ ഒരാളായിരുന്നു. അങ്ങനെ തിരുമേനി(സ) പോയിക്കൊണ്ടിരിക്കുമ്പോൾ, കുറച്ച് സ്ത്രീകൾ അവിടുത്തെ അടുത്ത്കൂടെ നടന്ന് പോവുകയുണ്ടായി. ഉടനെ ഫള്ല്(റ) അവരെ നോക്കുവാൻ തുടങ്ങി. അപ്പോൾ അവിടുത്തെ കൈ ഫള്ൽ(റ)വിന്റെ മുഖത്ത്വെച്ച് (ആ സത്രീകളെ നോക്കുന്നത്) തടസ്സപ്പെടുത്തി. അന്നേരം ഫള്ൽ(റ) തന്റെ മുഖം മറു ഭാഗത്തേക്ക് തിരിക്കുകയും അവരെ നോക്കുകയും ചെയ്തു. അപ്പോൾ റസൂൽ(സ) തന്റെ കൈ മറ്റേ ഭാഗത്ത് വെച്ച് ഫളൽ(റ)വിന്റെ മുഖം തിരിച്ചു. അങ്ങനെ അവിടുന്ന് ''ബത്നുമുഹസ്സറി''ൽ എത്തിയപ്പോൾ, വാഹനം അൽപം വേഗത്തിൽ ഓടിക്കുകയും, വലിയ ജംറയിൽ എത്തുന്ന മധ്യവഴിയിൽ പ്രവേശിക്കുകയും മരത്തിനടുത്തുള്ള ജംറത്തുൽ അഖബയിൽ ചെല്ലുകയും എന്നിട്ട് ഏഴ് ചെറിയ കല്ലുകൾ കൊണ്ട് അതിനെ എറിയുകയും ചെയ്തു. ഓരോ കല്ലെറിയുമ്പോഴും അവിടന്ന് തക്ബീർ ചൊല്ലിയിരുന്നു. പ്രസ്തുത കല്ല് ഗോട്ടിയുടെ വലുപ്പമുണ്ടായിരുന്നു. ബത്നുൽ വാദീ എന്ന സ്ഥലത്ത് നിന്നുകൊണ്ടാണ് അവിടന്ന് കല്ലെറിഞ്ഞത്. ശേഷം അവിടന്ന് അറവ് സ്ഥലത്തേക്ക് പോകുകയും അറുപത്തി മൂന്ന് ഒട്ടകങ്ങളെ സ്വകരങ്ങൾ കൊണ്ട് അറുക്കുകയും ശേഷം അലി(റ)ന് കൊടുക്കുകയും ബാക്കിയുള്ളത് അലി(റ) അറുക്കുകയും ഈ ബലികർമ്മത്തിൽ അദ്ദേഹത്തെ പങ്കാളിയാക്കുകുയം ചെയ്തു. പിന്നീട് അറുക്കപ്പെട്ട എല്ലാ ഓരോ ഒട്ടകത്തിൽ നിന്നും ഓരോ കഷ്ണം (മാംസം) എടുക്കുവാൻ അവിടന്ന് കൽപിക്കുകയും നബി(സ)യും അലി(റ)യും ആ മാംസത്തിൽ നിന്ന് ഭക്ഷിക്കുകയും അതിന്റെ കറി കുടിക്കുകകയും ചെയ്തു. തിരുമേനി(സ) വാഹനത്തിൽ കയറി കഅ്ബയുടെ അടുത്തേക്ക് പോകുകയം ഇഫാളയുടെ ത്വവാഫ് ചെയ്യുകയും മക്കയിൽവെച്ച് ളുഹർ നിസ്കരിക്കുകയും ചെയ്തു. ശേഷം തിരുമേനി(സ) അവിടുന്ന് അബ്ദുൽമുത്ത്വലിബിന്റെ സന്തതികളുടെ അടുക്കൽ ചെന്നു. അവർ സംസമിന്റെ അടുക്കൽ വെച്ച് ജലദാനം ചെയ്തുകൊണ്ടിരിക്കുകയാണ്. തിരുമേനി(സ) അരുളി: "അബ്ദുൽമുത്ത്വലിബിന്റെ സന്തതികളേ, നിങ്ങൾ വെള്ളം കോരി ജലദാനം ചെയ്യുക, ജനങ്ങൾ നിങ്ങളുടെ ജലദാനാവകാശം കൈയേറുമെന്നുള്ള ഭയമില്ലായിരുന്നുവെങ്കിൽ നിങ്ങളോടൊപ്പം ഞാനും വെള്ളം കോരി ദാനം ചെയ്യുമായിരുന്നു". അപ്പോൾ അവിടുത്തേക്ക് അവർ ഒരു ബക്കറ്റ് വെള്ളം കോരിക്കൊടുക്കുകയും അവിടന്ന് അത് കുടിക്കുകയും ചെയ്തു. (മു,ദ,ജ)', 'جَعْفَرِ بْنِ مُحَمَّدٍ عَنْ أَبِيهِ قَالَ', 'ജഅ്ഫറുബ്നു മുഹമ്മദ്(റ)', null, null, array['م','د','جه']::text[], array['മു','ദ','ജ']::text[], 'مِثْلِ', 'ദുർബ്ബലപ്പെടുത്തിയിരിക്കുന്നു', 349, 355, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=105 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 361, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: بَعَثَنِي أَبُو بَكْرٍ الصِّدِّيقُ رَضِيَ اللهُ عَنْهُ – فِي الْحَجَّةِ الَّتِي أَمَّرَهُ عَلَيْهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَبْلَ حَجَّةِ الْوَدَاعِ – فِي رَهْطٍ يُؤَذِّنُونَ فِي النَّاسِ يَوْمَ النَّحْرِ: لَا يَحُجُّ بَعْدَ الْعَامِ مُشْرِكٌ، وَلَا يَطُوفُ بِالْبَيْتِ عُرْيَانٌ. قَالَ ابْنُ شِهَابٍ: فَكَانَ حُمَيْدُ بْنُ عَبْدِ الرَّحْمَنِ يَقُولُ: يَوْمُ النَّحْرِ يَوْمُ الْحَجِّ الْأَكْبَرِ، مِنْ أَجْلِ حَدِيثِ أَبِي هُرَيْرَةَ. (ق)', 'അബൂഹുറൈറ(റ): ഹജ്ജതുൽ വിദാഇന് മുമ്പത്തെ വർഷത്തിൽ അബൂബക്കർ(റ)വിനെ അമീറായി നിയമിച്ചു കൊണ്ട് ഒരു സംഘം അനുചരൻമാരെ തിരുമേനി(സ) ഹജ്ജിന് അയച്ചപ്പോൾ ബലിദിനത്തിൽ മിനായിൽ വെച്ച് ഇപ്രകാരം പ്രഖ്യാപിക്കാൻ അബൂബക്കർ(റ) ഒരു സംഘം ആളുകളോടൊപ്പം എന്നെ നിയോഗിച്ചു. അറിയുക! ഈ കൊല്ലത്തിനു ശേഷം ബഹുദൈവാരാധകരാരും തന്നെ ഹജ്ജ് ചെയ്യാൻ പാടില്ല. നഗ്നത മറക്കാതെ ത്വവാഫ് ചെയ്യാനും പാടില്ല. ഇബ്നു ശിഹാബ്(റ) പറയുന്നു: ഹുമൈദുബ്നു അബ്ദുർറഹ്മാൻ(റ) പറയുമായിരുന്നു: ബലിദിനം വലിയ ഹജ്ജിന്റെ ദിനമാണ്; അബൂഹുറൈറ(റ)വിന്റെ ഹദീസ് പ്രകാരം. (ബു,മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 355, 355, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=106 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 362, 'عَنْ عَمْرِو بْنِ الْأَحْوَصِ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ فِي حَجَّةِ الْوَدَاعِ: "يَا أَيُّهَا النَّاسُ، أَلَا أَيُّ يَوْمٍ أَحْرَمُ". ثَلَاثَ مَرَّاتٍ. قَالُوا: يَوْمُ الْحَجِّ الْأَكْبَرِ. قَالَ: "فَإِنَّ دِمَاءَكُمْ وَأَمْوَالَكُمْ وَأَعْرَاضَكُمْ بَيْنَكُمْ حَرَامٌ، كَحُرْمَةِ يَوْمِكُمْ هَذَا، فِي شَهْرِكُمْ هَذَا، فِي بَلَدِكُمْ هَذَا. أَلَا لَا يَجْنِي جَانٍ إِلَّا عَلَى نَفْسِهِ، وَلَا يَجْنِي وَالِدٌ عَلَى وَلَدِهِ، وَلَا مَوْلُودٌ عَلَى وَالِدِهِ. أَلَا إِنَّ الشَّيْطَانَ قَدْ أَيِسَ أَنْ يُعْبَدَ فِي بَلَدِكُمْ هَذَا أَبَدًا، وَلَكِنْ سَيَكُونُ لَهُ طَاعَةٌ فِي بَعْضِ مَا تَحْتَقِرُونَ مِنْ أَعْمَالِكُمْ، فَيَرْضَى بِهَا. أَلَا وَكُلُّ دَمٍ مِنْ دِمَاءِ الْجَاهِلِيَّةِ مَوْضُوعٌ، وَأَوَّلُ مَا أَضَعُ مِنْهَا دَمُ الْحَارِثِ بْنِ عَبْدِ الْمُطَّلِبِ. كَانَ مُسْتَرْضِعًا فِي بَنِي لَيْثٍ، فَقَتَلَتْهُ هُذَيْلٌ. أَلَا وَإِنَّ كُلَّ رِبًا مِنْ رِبَا الْجَاهِلِيَّةِ مَوْضُوعٌ، لَكُمْ رُءُوسُ أَمْوَالِكُمْ لَا تَظْلِمُونَ وَلَا تُظْلَمُونَ. أَلَا، يَا أُمَّتَاهُ، هَلْ بَلَّغْتُ" ثَلَاثَ مَرَّاتٍ. قَالُوا: نَعَمْ. قَالَ: "اللَّهُمَّ اشْهَدْ" ثَلَاثَ مَرَّاتٍ. (د,ت,جه)', 'അംറുബ്നു അഹ്വസ്(റ): ഹജ്ജതുൽ വിദാഇൽ റസൂൽ(സ) ഇപ്രകാരം പറയുന്നത് ഞാൻ കേട്ടു: "ഓ, ജനങ്ങളേ, അറിയുക. ഏത് ദിനമാണ് ഏറ്റവും പവിത്രമായത്. ഇത് മൂന്ന് തവണ പറഞ്ഞു: അവർ പറഞ്ഞു: ഹജ്ജുൽ അക്ബറിന്റെ ദിവസം. റസൂൽ(സ) അരുളി: "നിശ്ചയം രക്തവും സമ്പത്തും അഭിമാനവും നിങ്ങൾക്കിടയിൽ (കളങ്കപ്പെടുത്തൽ) നിഷിദ്ധമാണ്. ഈ ദിനവും മാസവും സ്ഥലവും നിഷിദ്ധമാമായത് പോലെ. അറിയുക തെറ്റ് ചെയ്യുന്നവൻ തന്റെ ശരീരത്തോട് തന്നെയാണ് അക്രമം പ്രവർത്തിക്കുന്നത്. മക്കളുടെ കുറ്റത്തിന്റെ പേരിൽ പിതാവും പിതാവിന്റെ കുറ്റത്തിന്റെ പേരിൽ മക്കളും ശിക്ഷിക്കപ്പെടുകയില്ല. അറിയുക, നിങ്ങളുടെ ഈ നാട്ടിൽ താൻ ആരാധിക്കപ്പെടുമെന്നതിൽ പിശാച് ആശയറ്റവനാണ്. നിങ്ങൾ നിസ്സാരമെന്ന് കരുതുന്ന ചില കാര്യങ്ങളിൽ പക്ഷെ, അവനു വഴിപ്പെടലുകളുണ്ടാവും. അവൻ അതുകൊണ്ട് തൃപ്തിപ്പെടും. അറിയുക, അജ്ഞാന യുഗത്തിലെ പ്രതിക്രിയാ വധങ്ങൾ തള്ളപ്പെട്ടതാണ്. അതിൽ ഞാൻ പ്രഥമമായി എഴുതിത്തള്ളുന്നത് ഹാരിസുബ്നു അബ്ദുൽ മുത്വലിബിന്റെ വധമാണ്. ബനൂ ലൈഥിൽ മുലകുടിക്കുന്നവനായിരുന്നു അവൻ. ഹുദൈൽ ഗോത്രം അവനെ വധിച്ചു. അറിയുക, അജ്ഞാന യുഗത്തിലെ പലിശകളത്രയും തള്ളപ്പെട്ടതാണ്. നിങ്ങൾക്ക് നിങ്ങളുടെ മൂലധനമുണ്ട്. അതിൽ നിങ്ങൾ അക്രമം പ്രവർത്തിക്കുകയോ, അക്രമിക്കപ്പെടുകയോ ചെയ്യരുത്. എന്റെ സമുദായമേ, അറിയുക. ഞാൻ നിങ്ങൾക്ക് എത്തിച്ചു തന്നില്ലെയോ?" മൂന്ന് തവണ ഇപ്രകാരം ചോദിച്ചു: അവർ പറഞ്ഞു: അതെ, റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവേ, നീ സാക്ഷിയാണ്." ഇതും മൂന്ന് തവണ പറഞ്ഞു. (ദ,തു,ജ)', 'عَمْرِو بْنِ الْأَحْوَصِ', 'അംറുബ്നു അഹ്വസ്(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 355, 356, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=106 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 363, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَقَفَ يَوْمَ النَّحْرِ بَيْنَ الْجَمَرَاتِ، فِي الْحَجَّةِ الَّتِي حَجَّ فِيهَا، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَيُّ يَوْمٍ هَذَا". قَالُوا: يَوْمُ النَّحْرِ. قَالَ: "فَأَيُّ بَلَدٍ هَذَا". قَالُوا: هَذَا بَلَدُ اللَّهِ الْحَرَامُ. قَالَ: "فَأَيُّ شَهْرٍ هَذَا". قَالُوا: شَهْرُ اللَّهِ الْحَرَامُ. قَالَ: "هَذَا يَوْمُ الْحَجِّ الْأَكْبَرِ، وَدِمَاؤُكُمْ وَأَمْوَالُكُمْ وَأَعْرَاضُكُمْ عَلَيْكُمْ حَرَامٌ، كَحُرْمَةِ هَذَا الْبَلَدِ، فِي هَذَا الشَّهْرِ، فِي هَذَا الْيَوْمِ". ثُمَّ قَالَ: "هَلْ بَلَّغْتُ". قَالُوا: نَعَمْ. فَطَفِقَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "اللَّهُمَّ اشْهَدْ". ثُمَّ وَدَّعَ النَّاسَ، فَقَالُوا: هَذِهِ حَجَّةُ الْوَدَاعِ. (خ,د,جه)', 'ഇബ്നുഉമർ(റ): ഹജ്ജ് വേളയിൽ ബലി ദിനത്തിൽ ജംറകൾക്കിടയിൽ നിൽക്കെ തിരുമേനി(സ) ചോദിച്ചു: "ഏത് ദിവസമാണ് ഇന്ന്" അവർ പറഞ്ഞു: ബലി ദിനം. റസൂൽ(സ) ചോദിച്ചു: "ഏത് നാടാണ് ഇത്." അവർ മറുപടി നൽകി: ഇത് അല്ലാഹുവിന്റെ പവിത്ര നാടാണ്. റസൂൽ(സ) പറഞ്ഞു: "ഇന്നാണ് ഹജ്ജുൽ അക്ബറിന്റെ ദിനം. നിങ്ങളുടെ സമ്പത്തും അഭിമാനവും രക്തവും പവിത്രമാണ്. ഈ നാടും മാസവും ദിനവും പവിത്രമായതു പോലെ". എന്നിട്ട് റസൂൽ(സ) പറഞ്ഞു: "ഞാൻ നിങ്ങൾക്ക് എത്തിച്ചു തന്നില്ലെയോ?" അവർ പറഞ്ഞു: അതെ. എന്നിട്ട് തിരുമേനി(സ) പറയാൻ തുടങ്ങി: "അല്ലാഹുവേ, നീ സാക്ഷി". എന്നിട്ട് ജനങ്ങളോട് യാത്ര പറഞ്ഞു. അപ്പോൾ അവർ പറഞ്ഞു: ഇത് ഹജ്ജതുൽ വിദാആണ്. (ബു,ദ,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ','د','جه']::text[], array['ബു','ദ','ജ']::text[], null, null, 356, 356, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=106 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 364, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَقَفَ يَوْمَ النَّحْرِ بَيْنَ الْجَمَرَاتِ فِي الْحَجَّةِ الَّتِي حَجَّ، فَقَالَ: "أَيُّ يَوْمٍ هَذَا". قَالُوا: يَوْمُ النَّحْرِ، قَالَ: "هَذَا يَوْمُ الْحَجِّ الْأَكْبَرِ". (د,جه)', 'ഇബ്നുഉമർ(റ): ഹജ്ജ്വേളയിൽ ബലി ദിവസം റസൂൽ(സ) ജംറകൾക്കിടയിൽ നിന്ന് ചോദിച്ചു: "ഈ ദിവസമേതാണ്?" അനുയായികൾ പറഞ്ഞു: ഇത് ബലിയുടെ ദിവസമാണ്. റസൂൽ(സ) പറഞ്ഞു: "ഇത് ഹജ്ജുൽ അക്ബറിന്റെ ദിവസമാകുന്നു." (ദ,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 357, 357, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=106 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 365, 'عَنْ عَبْدِ اللهِ بْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَدِمَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مَكَّةَ فَطَافَ وَسَعَى بَيْنَ الصَّفَا وَالْمَرْوَةَ وَلَمْ يَقْرَبِ الْكَعْبَةَ بَعْدَ طَوَافِهِ بِهَا حَتَّى رَجَعَ مِنْ عَرَفَةَ. (خ)', 'ഇബ്നുഅബ്ബാസ്(റ): തിരുമേനി(സ) (ഹജ്ജിനായി) മക്കയിൽ വന്നപ്പോൾ ത്വവാഫ് ചെയ്തു. സ്വഫാ മർവ്വക്കിടയിൽ നടന്നു. അതിനു ശേഷം അറഫയിൽ നിന്നു മടങ്ങുന്നതു വരെ തിരുമേനി(സ) കഅ്ബയെ സമീപിച്ചില്ല. (ബു)', 'عَبْدِ اللهِ بْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 357, 357, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=107 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 366, 'عَنْ عُرْوَةَ قَالَ: قُلْتُ لِعَائِشَةَ رَضِيَ اللهُ عَنْهَا: مَا أَرَى عَلَيَّ جُنَاحًا أَنْ لَا أَتَطَوَّفَ بَيْنَ الصَّفَا وَالْمَرْوَةِ. قَالَتْ: لِمَ؟ قُلْتُ: لِأَنَّ اللَّهَ عَزَّ وَجَلَّ يَقُولُ: {إِنَّ الصَّفَا وَالْمَرْوَةَ مِنْ شَعَائِرِ اللَّهِ} الْآيَةَ. فَقَالَتْ: لَوْ كَانَ كَمَا تَقُولُ لَكَانَ: فَلَا جُنَاحَ عَلَيْهِ أَنْ لَا يَطَّوَّفَ بِهِمَا. إِنَّمَا أُنْزِلَ هَذَا فِي أُنَاسٍ مِنَ الْأَنْصَارِ، كَانُوا إِذَا أَهَلُّوا أَهَلُّوا لِمَنَاةَ فِي الْجَاهِلِيَّةِ، فَلَا يَحِلُّ لَهُمْ أَنْ يَطَّوَّفُوا بَيْنَ الصَّفَا وَالْمَرْوَةِ، فَلَمَّا قَدِمُوا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِلْحَجِّ ذَكَرُوا ذَلِكَ لَهُ، فَأَنْزَلَ اللَّهُ تَعَالَى هَذِهِ الْآيَةَ، فَلَعَمْرِي مَا أَتَمَّ اللَّهُ حَجَّ مَنْ لَمْ يَطُفْ بَيْنَ الصَّفَا وَالْمَرْوَةِ. وَفِي رِوَايَةٍ: مَا أَتَمَّ اللهُ حَجَّ امْرِئٍ وَلَا عُمْرَتَهُ لَمْ يَطُفْ بَيْنَ الصَّفَا وَالْمَرْوَةِ. (م)', 'ഉർവ്വ(റ): ഞാൻ ആഇശ(റ)യോട് പറഞ്ഞു: സ്വഫക്കും മർവ്വക്കുമിടയിൽ ത്വവാഫ് ചെയ്യാതിരിക്കുന്നതിൽ ഞാൻ ഒരു കുഴപ്പവും കാണുന്നില്ല. അപ്പോൾ ആഇശ(റ) ചോദിച്ചു: എന്തുകൊണ്ട്? ഞാൻ പറഞ്ഞു: കാരണം അല്ലാഹു തആല പറയുന്നു: ''സ്വഫയും മർവയും അല്ലാഹുവിന്റെ അടയാളങ്ങളിൽ പെട്ടതാണ്.'' ആഇശ(റ) പറഞ്ഞു: നീ പറഞ്ഞതു പോലെയാണെങ്കിൽ സൂക്തം ഇപ്രകാരവുമായിരുന്നു. അവ രണ്ടും ത്വവാഫ് ചെയ്യാതിരിക്കുന്നതു കൊണ്ട് അവന് ഒരു കുഴപ്പവുമില്ല. ഈ സൂക്തമിറങ്ങിയത് ഒരു കൂട്ടം അൻസാരികളുടെ കാര്യത്തിലാണ്. അജ്ഞാനകാലത്ത് മനാതിന് വേണ്ടിയായിരുന്നു അവർ തൽബിയത് ചൊല്ലിയിരുന്നത്. അത് കൊണ്ട് തന്നെ സ്വഫക്കും മർവ്വക്കുമിടയിൽ പ്രദക്ഷിണം ചെയ്യൽ അവർക്കു അനുവദനീയമായിരുന്നില്ല. റസൂൽ(സ)യോട് കൂടെ ഹജ്ജിന് വന്നപ്പോൾ അവർ ഇക്കാര്യം അവിടത്തോട് പറഞ്ഞു: അപ്പോൾ അല്ലാഹു മേൽപ്പറഞ്ഞ സൂക്തമിറക്കി. സത്യമായിട്ടും സ്വഫക്കും മർവ്വക്കുമിടയിൽ ത്വവാഫ് ചെയ്യാത്തവന്റെ ഹജ്ജ് അല്ലാഹു പൂർത്തിയാക്കുകയില്ല. മറ്റൊരു നിവേദനം: സ്വഫക്കും മർവ്വക്കുമിടയിൽ പ്രദക്ഷിണം ചെയ്യാത്തവന്റെ ഹജ്ജും ഉംറയും അല്ലാഹു പൂർത്തിയാക്കുകയില്ല. (മു)', 'عُرْوَةَ قَالَ', 'ഉർവ്വ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 357, 357, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=108 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=4 and h.hadith_no=366), 1, 'وَفِي رِوَايَةٍ: مَا أَتَمَّ اللهُ حَجَّ امْرِئٍ وَلَا عُمْرَتَهُ لَمْ يَطُفْ بَيْنَ الصَّفَا وَالْمَرْوَةِ. (م)', 'മറ്റൊരു നിവേദനം: സ്വഫക്കും മർവ്വക്കുമിടയിൽ പ്രദക്ഷിണം ചെയ്യാത്തവന്റെ ഹജ്ജും ഉംറയും അല്ലാഹു പൂർത്തിയാക്കുകയില്ല. (മു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 367, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُمَاقَالَ: لَمْ يَطُفِ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَلَا أَصْحَابُهُ بَيْنَ الصَّفَا وَالْمَرْوَةِ إِلَّا طَوَافًا وَاحِدًا. (م)', 'ജാബിറുബ്നു അബ്ദില്ലാഹ്(റ): റസൂൽ(സ) തങ്ങളും, അനുയായികളും സ്വഫാ മർവ്വാക്കിടയിൽ ഒരു പ്രാവശ്യമല്ലാതെ പ്രദക്ഷിണം ചെയ്തിട്ടില്ല. (മു)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ലാഹ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 358, 358, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=109 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 368, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ قَدِمَ مَكَّةَ طَافَ بِالْبَيْتِ سَبْعًا. فَقَرَأَ: {وَاتَّخِذُوا مِنْ مَقَامِ إِبْرَاهِيمَ مُصَلًّى} [البقرة: ١٢٥]. فَصَلَّى خَلْفَ الْمَقَامِ، ثُمَّ أَتَى الْحَجَرَ فَاسْتَلَمَهُ، ثُمَّ قَالَ: "نَبْدَأُ بِمَا بَدَأَ اللَّهُ بِهِ". فَبَدَأَ بِالصَّفَا وَقَرَأَ: {إِنَّ الصَّفَا وَالْمَرْوَةَ مِنْ شَعَائِرِ اللَّهِ} [البقرة: ١٥٨]. قَالَ ترمذي هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ. (م,د,ت)', 'ജാബിർ(റ): നിശ്ചയം നബി(സ) കഅ്ബാലയത്തിൽ വരികയും ഏഴ് പ്രാവശ്യം പ്രദക്ഷിണം ചെയ്യുകയും ചെയ്തു. എന്നിട്ട് ''ഇബ്റീഹീം നബി(അ)ന്റെ കാലടി പതിഞ്ഞ സ്ഥലം നിങ്ങൾ നിസ്കാര സ്ഥലമാക്കുക''. (അൽബഖറ: 125) എന്ന സൂക്തം ഉരുവിട്ടു. പിന്നീട് മഖാമിന്റെ പിന്നിൽ നിന്ന് നിസ്കരിച്ചു ഹജറിന്റെ അടുത്ത് ചെന്നു മുത്തി പറഞ്ഞു: അല്ലാഹു തുടങ്ങിയതുകൊണ്ട് നാമും തുടങ്ങുന്നു. അങ്ങനെ സ്വഫാ കൊണ്ടാരംഭിക്കുകയും ''നിശ്ചയം സ്വഫായും മർവായും അല്ലാഹുവിന്റെ അടയാളങ്ങളാണ്'' (അൽബഖറഃ 158) എന്ന സൂക്തം ഉരുവിടുകയും ചെയ്തു. (മു,ദ,തു)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], 'البقرة: ١٥٨', null, 358, 358, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=110 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 369, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: إِنَّمَا سَعَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالْبَيْتِ وَبَيْنَ الصَّفَا وَالْمَرْوَةِ، لِيُرِيَ الْمُشْرِكِينَ قُوَّتَهُ. قَالَ ترمذي حَدِيثُ ابْنِ عَبَّاسٍ حَدِيثٌ حَسَنٌ صَحِيحٌ. (ق,ت)', 'ഇബ്നുഅബ്ബാസ്(റ): നിശ്ചയം നബി(സ) കഅ്ബാലയവും, സ്വഫാ മർവ്വക്കിടയിലും പ്രതിക്ഷണം നടത്തിയത് മുശ്രികീങ്ങൾക്ക് അവിടുത്തെ ശക്തി കാണിച്ചു കൊടുക്കാൻ വേണ്ടിയായിരുന്നു. (ബു,മു,തു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 358, 358, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=111 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 370, 'عَنْ كَثِيرِ بْنِ جُمْهَانَ السُّلَمِي قَالَ: رَأَيْتُ ابْنَ عُمَرَ رَضِيَ اللهُ عَنْهُمَا يَمْشِي فِي السَّعْيِ، فَقُلْتُ لَهُ: أَتَمْشِي فِي السَّعْيِ بَيْنَ الصَّفَا وَالْمَرْوَةِ؟ قَالَ: لَئِنْ سَعَيْتُ لَقَدْ رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَسْعَى، وَلَئِنْ مَشَيْتُ لَقَدْ رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَمْشِي، وَأَنَا شَيْخٌ كَبِيرٌ. قَالَ ترمذي هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ. (د,ت,ن)', 'കബീറുബിൻ ജുംഹാനസ്സുലമീ(റ): ഞാൻ ഇബ്നുഉമർ(റ)നെ സഅ്യിന്റെ സമയത്ത് നടക്കുന്നതായി കാണാനിടയായി. ഞാൻ ചോദിച്ചു. സ്വഫാ മർവ്വക്കിടയിലെ സഅ്യിൽ താങ്കൾ നടക്കുന്നുവോ? ഇബ്നുഉമർ(റ) പറഞ്ഞു: ഞാൻ സഅയ് ചെയ്യുന്നെങ്കിൽ റസൂൽ(സ) സഅ്യ് ചെയ്യുന്നത് ഞാൻ കണ്ടിട്ടുണ്ട്. ഞാൻ നടക്കുന്നെങ്കിൽ നബി(സ) നടക്കുന്നതും ഞാൻ കണ്ടിട്ടുണ്ട്. ഞാനൊരു വയോവൃദ്ധനാണ്. (ദ,തു,ന)', 'كَثِيرِ بْنِ جُمْهَانَ السُّلَمِي قَالَ', 'കബീറുബിൻ ജുംഹാനസ്സുലമീ(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 358, 359, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=111 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 371, 'عَنْ أُمِّ وَلَدٍ لِشَيْبَةَ بْنِ عُثْمَانَ رَضِيَ اللهُ عَنْهَا قَالَتْ: رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ يَسْعَى بَيْنَ الصَّفَا وَالْمَرْوَةِ، وَهُوَ يَقُولُ: "لَا يُقْطَعُ الْأَبْطَحُ إِلَّا شَدًّا". (ن,جه)', 'ശൈബതുബ്നു ഉസ്മാന്റെ അടിമസ്ത്രീ(റ): അവർ പറയുന്നു: "ഓടിക്കൊണ്ടല്ലാതെ അബ്ഥഹ് (സ്വഫാ മർവ്വക്കിടയിലുള്ള ചെരുവ്) മുറിച്ചു കടക്കരുത്." എന്ന് പറഞ്ഞു കൊണ്ട് തിരുമേനി(സ) സ്വഫാ മർവ്വക്കിടയിൽ സഅ്യ് ചെയ്യുന്നത് ഞാൻ കണ്ടു. (ന,ജ)', 'أُمِّ وَلَدٍ لِشَيْبَةَ بْنِ عُثْمَانَ', 'ശൈബതുബ്നു ഉസ്മാന്റെ അടിമസ്ത്രീ(റ)', null, null, array['ن','جه']::text[], array['ന','ജ']::text[], null, null, 359, 359, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=111 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 372, 'عَنِ الزُّهْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: سَأَلُوا ابْنَ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: هَلْ رَأَيْتَ رَسُولَ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ رَمَلَ بَيْنَ الصَّفَا وَالْمَرْوَةِ؟ فَقَالَ: كَانَ فِي جَمَاعَةٍ مِنَ النَّاسِ فَرَمَلُوا، فَلَا أُرَاهُمْ رَمَلُوا إِلَّا بِرَمَلِهِ. (ن)', 'സുഹ്രി(റ): അവർ ഇബ്നുഉമർ(റ)വിനോട് ചോദിച്ചു: സഫക്കും മർവക്കുമിടയിൽ റസൂൽ(സ) റംല് നടത്തം നടക്കുന്നത് നിങ്ങൾ കണ്ടിട്ടുണ്ടോ? ഇബ്നുഉമർ(റ) പറഞ്ഞു: റസൂൽ(സ) ഒരു കൂട്ടത്തിലായിരുന്നു. അവർ റംല് നടത്തം നടന്നിരുന്നു. റസൂൽ(സ) റംല് നടത്തം നടക്കാതെ അവർ നടക്കുമെന്ന് എനിക്ക് തോന്നുന്നില്ല. (ന)', 'الزُّهْرِيِّ', 'സുഹ്രി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 359, 359, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=111 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 373, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَقِيَ عَلَى الصَّفَا، حَتَّى إِذَا نَظَرَ إِلَى الْبَيْتِ كَبَّرَ. (ن)', 'ജാബിർ(റ): തീർച്ചയായും റസൂൽ(സ) തങ്ങൾ സ്വഫായുടെ മുകളിൽ കയറി അവിടെ നിന്നും കഅബാലയം ദർശിച്ചപ്പോൾ തക്ബീർ മുഴക്കി. (ന)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 359, 359, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=112 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 374, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا وَقَفَ عَلَى الصَّفَا يُكَبِّرُ ثَلَاثًا، وَيَقُولُ: "لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ" يَصْنَعُ ذَلِكَ ثَلَاثَ مَرَّاتٍ، وَيَدْعُو، وَيَصْنَعُ عَلَى الْمَرْوَةِ مِثْلَ ذَلِكَ. (ن)', 'ജാബിർ(റ): തീർച്ചയായും റസൂൽ(സ) തങ്ങൾ സ്വഫായിൽ കയറി നിന്നാൽ മൂന്നു പ്രാവശ്യം തക്ബീർ ചൊല്ലും. എന്നിട്ട് "അല്ലാഹുവല്ലാതെ ആരാധനക്ക് അർഹനല്ല, അവൻ ഏകനും പങ്കുകാരനില്ലാത്തവനുമാണ്. അവൻ സർവ്വാധിപത്യത്തിനും സർവ്വ സ്തുതികൾക്കുമർഹനാണ്. അവൻ എല്ലാ കാര്യത്തിനും കഴിവുള്ളവനാകുന്നു" എന്ന് മൂന്ന് പ്രാവശ്യം ചൊല്ലുകയും പ്രാർത്ഥിക്കുകയും ചെയ്യും. മർവയിൽ വെച്ചും ഇപ്രകാരം ചെയ്യും. (ന)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 359, 359, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=113 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 375, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: أَحْرَمْتُ مِنَ التَّنْعِيمِ بِعُمْرَةٍ، فَدَخَلْتُ، فَقَضَيْتُ عُمْرَتِي، وَانْتَظَرَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالْأَبْطَحِ حَتَّى فَرَغْتُ، وَأَمَرَ النَّاسَ بِالرَّحِيلِ، قَالَتْ: وَأَتَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْبَيْتَ فَطَافَ بِهِ ثُمَّ خَرَجَ. (د)', 'ആഇശ(റ): ഞാൻ തൻഈമിൽ നിന്ന് ഉംറക്ക് ഇഹ്റാം ചെയ്തു. അപ്രകാരം കഅ്ബാലയത്തിൽ വരികയും ഉംറ നിർവ്വഹിക്കുകയും ചെയ്തു. ഞാനത് അവസാനിപ്പിക്കുവോളം റസൂൽ(സ) എന്നെ അബ്ത്വഹിൽ പ്രതീക്ഷിക്കുകയും ജനങ്ങളോട് യാത്രയാകാൻ കൽപിക്കുകയും ചെയ്തു. ആഇശ(റ) പറയുന്നു: റസൂൽ(സ) കഅ്ബാലയത്തിൽ വരികയും പ്രദക്ഷിണം ചെയ്തശേഷം പുറപ്പെടുകയും ചെയ്തു. (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 359, 360, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=114 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 376, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: خَرَجْتُ مَعَهُ – تَعْنِي مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ – فِي النَّفْرِ الْآخِرِ، فَنَزَلَ الْمُحَصَّبَ، قَالَتْ: ثُمَّ جِئْتُهُ بِسَحَرٍ، فَأَذَّنَ فِي أَصْحَابِهِ بِالرَّحِيلِ، فَارْتَحَلَ، فَمَرَّ بِالْبَيْتِ قَبْلَ صَلَاةِ الصُّبْحِ، فَطَافَ بِهِ حِينَ خَرَجَ، ثُمَّ انْصَرَفَ مُتَوَجِّهًا إِلَى الْمَدِينَةِ. (د)', 'ആഇശ(റ): ഞാൻ റസൂൽ(സ)യോട് കൂടെ അവസാന കൂട്ടത്തിൽ പുറപ്പെട്ടു. പ്രവാചകർ(സ) മുഹസ്സബിൽ ഇറങ്ങി. ഞാൻ റസൂൽ(സ)ക്ക് അത്താഴവുമായി വന്നു. അപ്പോൾ തിരുമേനി(സ) അനുചരരോട് യാത്രക്കൊരുങ്ങാൻ വിളംബംരം ചെയ്തു. അങ്ങനെ യാത്രയായി. സുബ്ഹി നിസ്കാരത്തിന് മുമ്പ് കഅ്ബക്കരികിലൂടെ നടന്നു പോയി. പുറപ്പെടാൻ സമയത്ത് കഅ്ബ ത്വവാഫ് ചെയ്തു. ശേഷം മദീനയുടെ ഭാഗത്തേക്ക് തിരിഞ്ഞു നടന്നു. (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 360, 360, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=114 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 377, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حِينَ أَرَادَ قُدُومَ مَكَّةَ: "مَنْزِلُنَا غَدًا بِخَيْفِ بَنِي كِنَانَةَ حَيْثُ تَقَاسَمُوا عَلَى الْكُفْرِ يَعْنِي ذَلِكَ الْمُحَصَّبَ". وَذَلِكَ أَنَّ قُرَيْشًا وَكِنَانَةَ تَحَالَفَتْ عَلَى بَنِي هَاشِمٍ وَبَنِي عَبْدِالْمُطَّلِبِ أَوْ بَنِي الْمُطَّلِبِ أَنْ لَا يُنَاكِحُوهُمْ وَلَا يُبَايِعُوهُمْ حَتَّى يُسْلِمُوا إِلَيْهِمُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (ق)', 'അബൂഹുറൈറ(റ): മക്കയിലേക്ക് പ്രവേശിക്കാനിരിക്കെ തിരുമേനി(സ) അരുളി: "അല്ലാഹു ഉദ്ദേശിക്കുന്ന പക്ഷം നാളെ നാം ബനൂ കിനാനയുടെ മലഞ്ചെരുവായ ''മുഹസ്സബി''ൽ ഇറങ്ങും. അവിടെ വെച്ച് കൊണ്ടാണ് മക്കയിലെ നേതാക്കൾ സത്യ നിഷേധത്തിലുന്നി നിന്നുകൊണ്ട് പ്രതിജ്ഞ ചെയ്തത്. ആ സംഭവം ഇങ്ങനെയാണുണ്ടായത്: ഖുറൈശികളും കിനാന ഗോത്രക്കാരും ചേർന്ന് ഹാശിം, മുത്വലിബ് എന്നീ കുടുംബങ്ങൾക്കെതിരിൽ ഒരു പ്രതിജ്ഞ ചെയ്തു, തിരുമേനി(സ)യെ അവർക്ക് ഏൽപ്പിച്ചു കൊടുത്താലല്ലാതെ, അവരുമായി ഇടപാട് നടത്തുകയോ വിവാഹ ബന്ധം സ്ഥാപിക്കുകയോ ചെയ്യുകയില്ലെന്ന്. (ബു,മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 360, 360, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=114 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 378, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَلَّى الظُّهْرَ وَالْعَصْرَ وَالْمَغْرِبَ وَالْعِشَاءَ ثُمَّ رَقَدَ رَقْدَةً بِالْمُحَصَّبِ، ثُمَّ رَكِبَ إِلَى الْبَيْتِ فَطَافَ بِهِ. (خ)', 'അനസ്(റ): തിരുമേനി(സ) ഹജ്ജിന് ചെന്നപ്പോൾ മുഹസ്സബിൽ വെച്ചു ളുഹ്റും അസറും മഗ്രിബും ഇശായും നമസ്കരിച്ച ശേഷം കിടന്നുറങ്ങി. പിന്നീട് കഅ്ബയിലേക്ക് വാഹനത്തിൽ പോയി ത്വവാഫ് ചെയ്തു. (ബു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 360, 360, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=114 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 379, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: لَيْسَ التَّحْصِيبُ بِشَيْءٍ إِنَّمَا هُوَ مَنْزِلٌ نَزَلَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (خ)', 'ഇബ്നുഅബ്ബാസ്(റ): മുഹസ്സബിൽ ഇറങ്ങുന്നത് പ്രത്യേക കാര്യമൊന്നുമല്ല. അത് തിരുമേനി(സ) ഇറങ്ങിയ ഒരു സ്ഥലമാണെന്നു മാത്രം. (ബു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 360, 360, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=114 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 380, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: نُزُولُ الْأَبْطَحِ لَيْسَ بِسُنَّةٍ، إِنَّمَا نَزَلَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِأَنَّهُ كَانَ أَسْمَحَ لِخُرُوجِهِ إِذَا خَرَجَ. (م)', 'ആഇശ(റ): അബ്ത്വാഹിൽ ഇറങ്ങൽ പുണ്യമുള്ള കാര്യമല്ല. റസൂൽ(സ) അവിടെ ഇറങ്ങി വിശ്രമിച്ചത് യാത്രാ സൗകര്യത്തിന്റെ പേരിൽ മാത്രമായിരുന്നു. (മു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 361, 361, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=114 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 381, 'عَنْ أُسَامَةَ بْنِ زَيْدٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قُلْتُ: يَا رَسُولَ اللَّهِ، أَيْنَ تَنْزِلُ غَدًا؟ وَذَلِكَ فِي حَجَّتِهِ. قَالَ: "وَهَلْ تَرَكَ لَنَا عَقِيلٌ مَنْزِلًا". ثُمَّ قَالَ: "نَحْنُ نَازِلُونَ غَدًا بِخَيْفِ بَنِي كِنَانَةَ – يَعْنِي: الْمُحَصَّبَ – حَيْثُ قَاسَمَتْ قُرَيْشٌ عَلَى الْكُفْرِ". وَذَلِكَ أَنَّ بَنِي كِنَانَةَ حَالَفَتْ قُرَيْشًا عَلَى بَنِي هَاشِمٍ: أَنْ لَا يُنَاكِحُوهُمْ وَلَا يُبَايِعُوهُمْ. (جه)', 'ഉസാമതുബ്നു സൈദ്(റ): ഞാൻ ചോദിച്ചു: റസൂലേ, നാളെ അങ്ങ് എവിടെയാണ് ഇറങ്ങുന്നത്. ഇത് റസൂൽ(സ)യുടെ ഹജ്ജ് വേളയിലായിരുന്നു. റസൂൽ(സ) പറഞ്ഞു: "അഖീൽ നമുക്ക് വേണ്ടി വല്ല സ്ഥലവും ബാക്കി വെച്ചിട്ടുണ്ടാവുമോ?" ശേഷം തിരുമേനി(സ) പറഞ്ഞു: "നാളെ നാം ബനൂ കിനാനക്കാരുടെ താഴ്വരയായ മഹസ്സ്വബിൽ ഇറങ്ങും. അവിടെ വെച്ചാണ് ഖുറൈശികൾ സത്യ നിഷേധത്തിന്റെ പേരിൽ പ്രതിജ്ഞയെടുത്തത്." അതിങ്ങനെ ആയിരുന്നു: ഖുറൈശികളും കിനാനക്കാരും ഹാശിം സന്തതികൾക്കെതിരെ ഒരു പ്രതിജ്ഞയെടുത്തു; അവരുമായി ഇടപാട് നടത്തുകയോ വിവാഹ ബന്ധം സ്ഥാപിക്കുകയോ ചെയ്യുകയില്ല. (ജ)', 'أُسَامَةَ بْنِ زَيْدٍ', 'ഉസാമതുബ്നു സൈദ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 361, 361, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=114 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 382, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: ادَّلَجَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَيْلَةَ النَّفْرِ مِنَ الْبَطْحَاءِ ادِّلَاجًا. (جه)', 'ആഇശ(റ): നബി(സ) ബത്ഹാഇൽ നിന്ന് രാത്രിയുടെ അവസാന ഭാഗത്തിൽ യാത്ര തുടർന്നു. (ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 361, 361, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=114 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 383, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَبُو بَكْرٍ وَعُمَرُ وَعُثْمَانُ يَنْزِلُونَ بِالْأَبْطَحِ. (ت,جه)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ), അബൂബക്കർ(റ), ഉമർ(റ), ഉസ്മാൻ(റ) എന്നിവർ അബ്ത്വാഹിൽ ഇറങ്ങിയിരുന്നു. (തു,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 361, 361, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=114 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 384, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا أَنَّهُ كَانَ إِذَا أَقْبَلَ بَاتَ بِذِي طُوًى حَتَّى إِذَا أَصْبَحَ دَخَلَ، وَإِذَا نَفَرَ مَرَّ بِذِي طُوًى، وَبَاتَ بِهَا حَتَّى يُصْبِحَ، وَكَانَ يَذْكُرُ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَفْعَلُ ذَلِكَ. (خ)', 'ഇബ്നുഉമർ(റ): അദ്ദേഹം ഹജ്ജിനായി മക്കയിലേക്ക് പുറപ്പെട്ടാൽ ദ്വീതുവാ എന്ന സ്ഥലത്താണ് രാത്രി താമസിച്ചിരുന്നത്. പ്രഭാതമായാൽ മക്കയിൽ പ്രവേശിക്കും. മക്കയിൽ നിന്നു മടങ്ങുമ്പോഴും ദ്വീതുവായിലെത്തി പ്രഭാതം വരേക്കും അവിടെ താമസിക്കും. തിരുമേനി(സ) ഇപ്രകാരമാണ് ചെയ്തിരുന്നതെന്ന് അദ്ദേഹം പറയാറുണ്ടായിരുന്നു. (ബു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 361, 361, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=115 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 385, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَنْزِلُ بِذِي طُوًى، يَبِيتُ بِهِ حَتَّى يُصَلِّيَ صَلَاةَ الصُّبْحِ، حِينَ يَقْدَمُ إِلَى مَكَّةَ، وَمُصَلَّى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذَلِكَ عَلَى أَكَمَةٍ غَلِيظَةٍ، لَيْسَ فِي الْمَسْجِدِ الَّذِي بُنِيَ ثَمَّ، وَلَكِنْ أَسْفَلَ مِنْ ذَلِكَ عَلَى أَكَمَةٍ خَشِنَةٍ غَلِيظَةٍ. (ن)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): റസൂൽ(സ) മക്കയിൽ വരുമ്പോൾ ദീത്വുവയിൽ ഇറങ്ങുകയും സുബ്ഹി നിസ്കാരം വരെ രാത്രി അവിടെ തങ്ങുകയും ചെയ്യുമായിരുന്നു. റസൂൽ(സ)യുടെ നിസ്കാരസ്ഥലം പരുപരുത്ത ഒരു കുന്നിൻമേലായിരുന്നു. അവിടെനിർമ്മിക്കപ്പെട്ട പള്ളിയിൽ ആയിരുന്നില്ല. മറിച്ച് അതിനേക്കാൾ താഴ്ന്ന ഒരു പരുക്കൻ കുന്നിനു മുകളിലായിരുന്നു. (ന)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 361, 362, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=115 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 386, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: كَانَ إِذَا قَدِمَ مَكَّةَ بَاتَ بِذِي طُوًى حَتَّى يُصْبِحَ وَيَغْتَسِلَ، ثُمَّ يَدْخُلَ مَكَّةَ نَهَارًا، وَيَذْكُرُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ فَعَلَهُ. (د)', 'ഇബ്നുഉമർ(റ): അദ്ദേഹം മക്കയിൽ വന്നപ്പോൾ ദീത്വുവയിൽ താമസിച്ചു. പ്രഭാതമായപ്പോൾ കുളിച്ചു. പിന്നെ പകലിൽ മക്കയിൽ പ്രവേശിച്ചു. നബിതങ്ങൾ(സ) ഇപ്രകാരം ചെയ്തതായി അദ്ദേഹം ഓർക്കുന്നു. (ദ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 362, 362, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=115 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 387, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَا مِنْ يَوْمٍ أَكْثَرَ مِنْ أَنْ يُعْتِقَ اللَّهُ فِيهِ عَبْدًا مِنَ النَّارِ مِنْ يَوْمِ عَرَفَةَ، وَإِنَّهُ لَيَدْنُو، ثُمَّ يُبَاهِي بِهِمُ الْمَلَائِكَةَ فَيَقُولُ: مَا أَرَادَ هَؤُلَاءِ". (م)', 'ആഇശ(റ): റസൂൽ(സ) പറഞ്ഞു: "അറഫാദിനം നരകാഗ്നിയിൽ നിന്ന് അല്ലാഹു തന്റെ ദാസന്മാരെ മോചിപ്പിക്കുന്നതിനേക്കാൾ കൂടുതലായി മോചിപ്പിക്കുന്ന യാതൊരു ദിനവുമില്ല. നിശ്ചയമായും (അന്ന്) അവൻ അടുക്കുകയും, അവരെക്കൊണ്ട് മാലാഖമാരുടെ മുമ്പിൽ അഭിമാനം കൊള്ളുകയും ചെയ്യും. അനന്തരം അവൻ ചോദിക്കും: ഇവർ എന്താണുദ്ദേശിക്കുന്നത്." (മു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 362, 362, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=116 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 388, 'عَنْ عَبْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: غَدَوْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ مِنًى إِلَى عَرَفَاتٍ، مِنَّا الْمُلَبِّي وَمِنَّا الْمُكَبِّرُ. (م)', 'അബ്ദില്ലാഹിബിൻ ഉമർ(റ): ഞങ്ങൾ റസൂൽ(സ)യോടൊപ്പം പ്രഭാതത്തിൽ മിനയിൽ നിന്നും അറഫയിലേക്ക് പോയി. ഞങ്ങളുടെ കൂട്ടത്തിൽ തക്ബീർ ചൊല്ലുന്നവരും, തൽബിയത്ത് ചൊല്ലുന്നവരുമുണ്ടായിരുന്നു. (മു)', 'عَبْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرَ', 'അബ്ദില്ലാഹിബിൻ ഉമർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 362, 362, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=117 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 389, 'عَنْ مُحَمَّدِ بْنِ أَبِي بَكْرٍ الثَّقَفِي رَضِيَ اللهُ عَنْهُ: أَنَّهُ سَأَلَ ابْنَ مَالِكٍ رَضِيَ اللهُ عَنْهُ – وَهُمَا غَادِيَانِ مِنْ مِنًى إِلَى عَرَفَةَ – كَيْفَ كُنْتُمْ تَصْنَعُونَ فِي هَذَا الْيَوْمِ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: كَانَ يُهِلُّ الْمُهِلُّ مِنَّا فَلَا يُنْكَرُ عَلَيْهِ، وَيُكَبِّرُ الْمُكَبِّرُ مِنَّا فَلَا يُنْكَرُ عَلَيْهِ. (م)', 'മുഹമ്മദുബ്നു അബീ ബക്രി സഖഫീ(റ): മിനയിൽ നിന്നും അറഫയിലേക്ക് പോകുന്ന സന്ദർഭത്തിൽ അദ്ദേഹം ഇബ്നു മാലിക്(റ)വിനോട് ചോദിച്ചു: നിങ്ങൾ റസൂൽ(സ)യോടൊപ്പം ഇന്നേ ദിവസത്തിൽ എപ്രകാരമായിരുന്നു ചെയ്തിരുന്നത്? ഇബ്നു മാലിക്(റ) പറഞ്ഞു: ഞങ്ങളുടെ കൂട്ടത്തിൽ തഹ്ലീൽ ചൊല്ലുന്നവരുണ്ടായിരുന്നു. തക്ബീർ ചൊല്ലുന്നവരുമുണ്ടായിരുന്നു. ഒരാൾക്കും അവരുടെ പ്രവൃത്തി വിരോധിക്കപ്പെട്ടിരുന്നില്ല. (മു)', 'مُحَمَّدِ بْنِ أَبِي بَكْرٍ الثَّقَفِي', 'മുഹമ്മദുബ്നു അബീ ബക്രി സഖഫീ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 362, 362, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=117 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 390, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: غَدَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ مِنًى حِينَ صَلَّى الصُّبْحَ صَبِيحَةَ يَوْمِ عَرَفَةَ، حَتَّى أَتَى عَرَفَةَ فَنَزَلَ بِنَمِرَةَ، وَهِيَ مَنْزِلُ الْإِمَامِ الَّذِي يَنْزِلُ بِهِ بِعَرَفَةَ، حَتَّى إِذَا كَانَ عِنْدَ صَلَاةِ الظُّهْرِ رَاحَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُهَجِّرًا، فَجَمَعَ بَيْنَ الظُّهْرِ وَالْعَصْرِ، ثُمَّ خَطَبَ النَّاسَ، ثُمَّ رَاحَ فَوَقَفَ عَلَى الْمَوْقِفِ مِنْ عَرَفَةَ. (د)', 'ഇബ്നുഉമർ(റ): അറഫാദിനപ്രഭാതത്തിൽ സുബ്ഹി നിസ്കരിച്ച റസൂൽ(സ) മിനയിൽ നിന്ന് യാത്ര തുടങ്ങി. അറഫയിൽ എത്തിയപ്പോൾ നമിറയിൽ ഇറങ്ങി. അറഫയിൽ അവിടെയാണ് ഭരണാധികാരികൾ ഇറങ്ങാറ്. ളുഹർ നിസ്കാരത്തിന്റെ സമയമായപ്പോൾ തിരുമേനി(സ) ഉച്ചവെയിലിൽ സഞ്ചരിച്ചു. ളുഹ്റും അസറും ജംആക്കി. ശേഷം റസൂൽ(സ) പ്രഭാഷണം നടത്തി. എന്നിട്ട് സഞ്ചരിച്ച് അറഫയിലെ മൗഖിഫിൽ ചെന്ന് നിന്നു. (ദ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 362, 363, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=117 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 391, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: غَدَوْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ مِنًى إِلَى عَرَفَاتٍ، مِنَّا الْمُلَبِّي وَمِنَّا الْمُكَبِّرُ. (م)', 'അബ്ദില്ലാഹിബിൻ ഉമർ(റ): രാവിലെ ഞങ്ങൾ റസൂൽ(സ)യോടൊപ്പം മിനയിൽ നിന്നും അറഫയിലേക്ക് പോയി. ഞങ്ങളുടെ കൂട്ടത്തിൽ തക്ബീർ ചൊല്ലുന്നവരും, തൽബിയത്ത് ചൊല്ലുന്നവരുമുണ്ടായിരുന്നു. (മു)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'അബ്ദില്ലാഹിബിൻ ഉമർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 363, 363, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=118 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 392, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَنْزِلُ بِعَرَفَةَ فِي وَادِي نَمِرَةَ، قَالَ: فَلَمَّا قَتَلَ الْحَجَّاجُ ابْنَ الزُّبَيْرِ أَرْسَلَ إِلَى ابْنِ عُمَرَ: أَيَّ سَاعَةٍ كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَرُوحُ فِي هَذَا الْيَوْمِ؟ قَالَ: إِذَا كَانَ ذَلِكَ رُحْنَا. فَأَرْسَلَ الْحَجَّاجُ رَجُلًا يَنْظُرُ أَيَّ سَاعَةٍ يَرْتَحِلُ. فَلَمَّا أَرَادَ ابْنُ عُمَرَ أَنْ يَرْتَحِلَ قَالَ: أَزَاغَتِ الشَّمْسُ؟ قَالُوا: لَمْ تَزِغْ بَعْدُ. فَجَلَسَ، ثُمَّ قَالَ: أَزَاغَتِ الشَّمْسُ؟ قَالُوا: لَمْ تَزِغْ بَعْدُ. فَجَلَسَ، ثُمَّ قَالَ: أَزَاغَتِ الشَّمْسُ؟ قَالُوا: لَمْ تَزِغْ بَعْدُ. فَجَلَسَ، ثُمَّ قَالَ: أَزَاغَتِ الشَّمْسُ؟ قَالُوا: نَعَمْ. فَلَمَّا قَالُوا: قَدْ زَاغَتْ، ارْتَحَلَ. (د,جه)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) അറഫയിൽ വാദീ നമിറയിൽ ആയിരുന്നു ഇറങ്ങാറുണ്ടായിരുന്നത്. ഇബ്നു സുബൈർ(റ)വിനെ വധിച്ചതിന് ശേഷം ഇബ്നുഉമറി(റ)ന്റെ അടുത്തേക്ക് ആളെ അയച്ചു ഹജ്ജാജ് ചോദിച്ചു: ഈ ദിനത്തിൽ ഏത് സമയത്തായിരുന്നു തിരുമേനി(സ) പുറപ്പെട്ടത്? ഇബ്നുഉമർ(റ) പറഞ്ഞു: ആ സമയമെത്തുമ്പോൾ നാം പുറപ്പെടും. ഇബ്നുഉമർ(റ) എപ്പോഴാണ് പുറപ്പെടുന്നത് എന്ന് വീക്ഷിക്കാൻ ഹജ്ജാജ് ആളെ നിയോഗിച്ചു. പുറപ്പെടാനുദ്ദേശിച്ചപ്പോൾ ഇബ്നുഉമർ(റ) ചോദിച്ചു: സൂര്യൻ മധ്യത്തിൽ നിന്ന് ചാഞ്ഞുവോ? കൂടെയുള്ളവർ പറഞ്ഞു: ഇപ്പോഴും ചാഞ്ഞിട്ടില്ല. അപ്പോൾ ഇബ്നുഉമർ(റ) അവിടെ തന്നെ ഇരുന്നു. വീണ്ടും ചോദിച്ചു: സൂര്യൻ മധ്യത്തിൽ നിന്നും ചാഞ്ഞുവോ? അവർ പറഞ്ഞു: ഇപ്പോഴും നീങ്ങിയിട്ടില്ല. ഇബനുഉമർ(റ) അവിടെ തന്നെ ഇരുന്നു. കുറച്ച് കഴിഞ്ഞ് പിന്നെയും ചോദിച്ചു: സൂര്യൻ ചാഞ്ഞുവോ? ചാഞ്ഞിട്ടില്ലെന്ന് അവർ പ്രത്യുത്തരം നൽകി. ഇബ്നുഉമർ(റ) അവിടെ തന്നെ ഇരുന്നു. പിന്നെയും ചോദിച്ചു: സൂര്യൻ ചാഞ്ഞുവോ? അതെ, സൂര്യൻ മധ്യത്തിൽ നിന്ന് നീങ്ങിയിരിക്കുന്നു. അപ്പോൾ ഇബ്നുഉമർ(റ) പുറപ്പെട്ടു. (ദ,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 363, 363, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=119 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 393, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "كُلُّ عَرَفَةَ مَوْقِفٌ، وَارْتَفِعُوا عَنْ بَطْنِ عَرَفَةَ. وَكُلُّ الْمُزْدَلِفَةِ مَوْقِفٌ، وَارْتَفِعُوا عَنْ بَطْنِ مُحَسِّرٍ. وَكُلُّ مِنًى مَنْحَرٌ، إِلَّا مَا وَرَاءَ الْعَقَبَةِ". (جه)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): റസൂൽ(സ) പറഞ്ഞു: "അറഫ മുഴുവനും മൗഖിഫാണ്. എന്നാൽ ബത്ന് അറഫയിൽ നിന്ന് നിങ്ങൾ മാറി നിൽക്കുക. മുസ്ദലിഫ മുഴുക്കെയും മൗഖിഫാണ്. എന്നാൽ ബത്ന് മുഹസ്സിറിൽ നിന്ന് നിങ്ങൾ മാറി നിൽക്കുക. മിന മുഴുവനും ബലി സ്ഥലമാണ്, അഖബക്ക് പിന്നിലൊഴിക." (ജ)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 364, 364, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=120 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 394, 'عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللهُ عَنْهُ قَالَ: وَقَفَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِعَرَفَةَ فَقَالَ: "هَذِهِ عَرَفَةُ، وَهَذَا هُوَ الْمَوْقِفُ، وَعَرَفَةُ كُلُّهَا مَوْقِفٌ". ثُمَّ أَفَاضَ حِينَ غَرَبَتِ الشَّمْسُ، وَأَرْدَفَ أُسَامَةَ بْنَ زَيْدٍ، وَجَعَلَ يُشِيرُ بِيَدِهِ عَلَى هِينَتِهِ، وَالنَّاسُ يَضْرِبُونَ يَمِينًا وَشِمَالًا، يَلْتَفِتُ إِلَيْهِمْ وَيَقُولُ: "يَا أَيُّهَا النَّاسُ، عَلَيْكُمُ السَّكِينَةَ". ثُمَّ أَتَى جَمْعًا فَصَلَّى بِهِمُ الصَّلَاتَيْنِ جَمِيعًا، فَلَمَّا أَصْبَحَ أَتَى قُزَحَ فَوَقَفَ عَلَيْهِ وَقَالَ: "هَذَا قُزَحُ وَهُوَ الْمَوْقِفُ، وَجَمْعٌ كُلُّهَا مَوْقِفٌ". ثُمَّ أَفَاضَ حَتَّى انْتَهَى إِلَى وَادِي مُحَسِّرٍ، فَقَرَعَ نَاقَتَهُ فَخَبَّتْ حَتَّى جَاوَزَ الْوَادِيَ فَوَقَفَ، وَأَرْدَفَ الْفَضْلَ، ثُمَّ أَتَى الْجَمْرَةَ فَرَمَاهَا، ثُمَّ أَتَى الْمَنْحَرَ فَقَالَ: "هَذَا الْمَنْحَرُ، وَمِنًى كُلُّهَا مَنْحَرٌ". وَاسْتَفْتَتْهُ جَارِيَةٌ شَابَّةٌ مِنْ خَثْعَمٍ فَقَالَتْ: إِنَّ أَبِي شَيْخٌ كَبِيرٌ، قَدْ أَدْرَكَتْهُ فَرِيضَةُ اللَّهِ فِي الْحَجِّ، أَفَيُجْزِئُ أَنْ أَحُجَّ عَنْهُ؟ قَالَ: "حُجِّي عَنْ أَبِيكِ". قَالَ: وَلَوَى عُنُقَ الْفَضْلِ، فَقَالَ الْعَبَّاسُ: يَا رَسُولَ اللَّهِ، لِمَ لَوَيْتَ عُنُقَ ابْنِ عَمِّكَ؟ قَالَ: "رَأَيْتُ شَابًّا وَشَابَّةً، فَلَمْ آمَنِ الشَّيْطَانَ عَلَيْهِمَا". ثُمَّ أَتَاهُ رَجُلٌ فَقَالَ: يَا رَسُولَ اللَّهِ، إِنِّي أَفَضْتُ قَبْلَ أَنْ أَحْلِقَ. قَالَ: "احْلِقْ أَوْ: قَصِّرْ – وَلَا حَرَجَ". قَالَ وَجَاءَ آخَرُ فَقَالَ: يَا رَسُولَ اللَّهِ، إِنِّي ذَبَحْتُ قَبْلَ أَنْ أَرْمِيَ؟ قَالَ: "ارْمِ وَلَا حَرَجَ". قَالَ: ثُمَّ أَتَى الْبَيْتَ فَطَافَ بِهِ، ثُمَّ أَتَى زَمْزَمَ فَقَالَ: "يَا بَنِي عَبْدِ الْمُطَّلِبِ، لَوْلَا أَنْ يَغْلِبَكُمُ النَّاسُ عَنْهُ لَنَزَعْتُ".قَالَ ترمذي هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ. (د,ت,جه)', 'അലി(റ): റസൂൽ(സ) അറഫയിൽ നിന്നു. എന്നിട്ട് പറഞ്ഞു: "ഇത് അറഫയാകുന്നു. ഇത് തന്നെയാണ് മൗഖിഫും(നിൽക്കുന്ന സ്ഥലം). അറഫ മുഴുവൻ മൗഖിഫാണ്." സൂര്യനസ്തമിച്ചപ്പോൾ തിരുമേനി(സ) അറഫയിൽ നിന്നു പോയി. ഉസാമതുബ്നു സൈദ്(റ)വിനെ തന്റെ പിന്നിലിരുത്തി. തിരുമേനി(സ) വളരെ അച്ചടക്കത്തോടെ തിരുകരങ്ങൾ കൊണ്ട് വഴി കാണിച്ചു കൊടുത്തുകൊണ്ടേയിരുന്നു. എന്നാൽ ജനങ്ങൾ ഇടത്തും വലത്തും അടിക്കുകയായിരുന്നു. റസൂൽ(സ) അവരിലേക്ക് തിരിഞ്ഞു: എന്നിട്ട് പറഞ്ഞു: "ഓ ജനങ്ങളേ, നിങ്ങൾ അച്ചടക്കം പാലിക്കുക." പിന്നെ റസൂൽ(സ) മുസ്ദലിഫയിൽ ചെന്നു. അവരെല്ലാവരെയും കൂട്ടി രണ്ട് നിസ്കാരങ്ങൾ നിർവ്വഹിച്ചു. പ്രഭാതമായപ്പോൾ ''ഖുസഹി'' (മുസ്ദലിഫയുടെ താഴ്ഭാഗത്തുള്ള ഒരു മല)ൽ ചെന്നു നിന്നു. എന്നിട്ട് പറഞ്ഞു: "ഇത് ''ഖുസഹ്'' ആണ്. ''ഖുസഹ്'' മൗഖിഫുമാണ്. മുസ്ദലിഫ മുഴുവനും മൗഖിഫാണ്." പിന്നീട് തിരുമേനി(സ) ''മുസഹിർ'' താഴ്വര വരെ സഞ്ചരിച്ചു. റസൂൽ(സ) തന്റെ ഒട്ടകത്തെ അടിച്ചു. അത് വേഗത കൂട്ടി. താഴ്വര മുറിച്ചു കടന്നപ്പോൾ റസൂൽ(സ) നിന്നു. ഫള്ലിനെ തന്റെ പിന്നിലിരുത്തി. എന്നിട്ട് ''ജംറ''യിൽ ചെന്ന് കല്ലെറിഞ്ഞു. പിന്നീട് അറവു കേന്ദ്രത്തിലേക്ക് ചെന്നു. എന്നിട്ട് പറഞ്ഞു: "ഇത് അറവു സ്ഥലമാണ്. മിനാ മുഴുവൻ അറവു സ്ഥലമാണ്." അപ്പോൾ ഖസ്അം ഗോത്രത്തിൽ പെട്ട ഒരു യുവതി റസൂൽ(സ)യോട് ഫത്വ തേടി. അവൾ ചോദിച്ചു: എന്റെ പിതാവ് വളരെ വൃദ്ധനാണ്. അല്ലാഹു ഹജ്ജ് നിർബന്ധമാക്കിയത് അദ്ദേഹത്തിനെത്തിയിരിക്കുന്നു. എന്റെ പിതാവിന് വേണ്ടി ഞാൻ ഹജ്ജ് ചെയ്താൽ മതിയാകുമോ? റസൂൽ(സ) പറഞ്ഞു: "നിന്റെ പിതാവിന് വേണ്ടി നീ ഹജ്ജ് നിർവ്വഹിക്കുക." അലി(റ) പറയുന്നു: തിരുമേനി(സ) ഫള്ലിന്റെ പിരടി തിരിച്ചു. അപ്പോൾ അബ്ബാസ്(റ) ചോദിച്ചു: റസൂലേ, പിതൃസഹോദരപുത്രന്റെ പിരടി എന്തിനാണ് അങ്ങ് തിരിച്ചത്? റസൂൽ(സ) പറഞ്ഞു: "ഞാൻ ഒരു യുവാവിനെയും യുവതിയെയും കണ്ടു. അവരുടെ മേൽ പിശാചിനെ ഞാൻ ഭയക്കാതിരുന്നില്ല." പിന്നെ ഒരാൾ വന്നു പറഞ്ഞു: റസൂലേ, തലമുടി മുറിക്കും മുമ്പ് ഞാൻ ഇഫാളതിന്റെ ത്വവാഫ് ചെയ്തു. റസൂൽ(സ) പറഞ്ഞു: "മുടി മുറിക്കുകയോ വരണ്ടുകയോ ചെയ്യുക. അത് പ്രശ്നമല്ല." മറ്റൊരാൾ വന്നു പറഞ്ഞു: തിരുദൂതരെ, കല്ലെറിയും മുമ്പ് ഞാൻ ബലി അറുത്തു? റസൂൽ(സ) പറഞ്ഞു: "എറിയുക, അതു പ്രശ്നമല്ല." അലി(റ) പറയുന്നു: ശേഷം റസൂൽ(സ) കഅ്ബയിൽ ചെന്ന് പ്രദക്ഷിണം നടത്തി. എന്നിട്ട് സംസമിനരികെ ചെന്നു. തിരുമേനി(സ) പറഞ്ഞു: "അബ്ദുൽ മുത്ത്വലിബിന്റെ സന്തതികളേ, ജനങ്ങൾ നിങ്ങളുടെ ജലദാനാവകാശം കയ്യേറുമായിരുന്നില്ലെങ്കിൽ ഞാനും വെള്ളം കോരി ജലദാനം ചെയ്യുമായിരുന്നു." (ദ,തു,ജ)', 'عَلِيِّ بْنِ أَبِي طَالِبٍ', 'അലി(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 364, 365, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=120 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 395, 'عَنْ يَزِيدَ بْنِ شَيْبَانَ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا وُقُوفًا فِي مَكَانٍ تُبَاعِدُهُ مِنَ الْمَوْقِفِ، فَأَتَانَا ابْنُ مِرْبَعٍ فَقَالَ: إِنِّي رَسُولُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَيْكُمْ، يَقُولُ: "كُونُوا عَلَى مَشَاعِرِكُمْ، فَإِنَّكُمُ الْيَوْمَ عَلَى إِرْثٍ مِنْ إِرْثِ إِبْرَاهِيمَ". (د,ت,جه)', 'യസീദുബ്നു ശൈബാൻ(റ): ഞങ്ങൾ മൗഖിഫിൽ നിന്ന് വിദൂരമായ ഒരു സ്ഥലത്ത് നിൽക്കെ ഇബ്നു മിർബഇൽ അൻസാരി(റ) ഞങ്ങളുടെ അടുത്തേക്കു വന്നുകൊണ്ട് പറഞ്ഞു: ഞാൻ നിങ്ങളിലേക്കുള്ള റസൂൽ(സ)യുടെ ദൂതനാണ്. റസൂൽ(സ) പറയുന്നു: "നിങ്ങൾ ഇപ്പോൾ നിൽക്കുന്നിടത്ത് തന്നെ നിൽക്കുക. നിശ്ചയമായും ഇന്ന് നിങ്ങൾ ഇബ്രാഹീം നബി(അ)ന്റെ പിൻഗാമികളാണ്." (ദ,തു,ജ)', 'يَزِيدَ بْنِ شَيْبَانَ', 'യസീദുബ്നു ശൈബാൻ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 365, 365, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=121 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 396, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَتْ قُرَيْشٌ وَمَنْ دَانَ دِينَهَا يَقِفُونَ بِالْمُزْدَلِفَةِ، وَكَانُوا يُسَمَّوْنَ الْحُمْسَ، وَكَانَ سَائِرُ الْعَرَبِ يَقِفُونَ بِعَرَفَةَ، فَلَمَّا جَاءَ الْإِسْلَامُ أَمَرَ اللَّهُ عَزَّ وَجَلَّ نَبِيَّهُ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يَأْتِيَ عَرَفَاتٍ فَيَقِفَ بِهَا، ثُمَّ يُفِيضَ مِنْهَا، فَذَلِكَ قَوْلُهُ عَزَّ وَجَلَّ: {ثُمَّ أَفِيضُوا مِنْ حَيْثُ أَفَاضَ النَّاسُ} [البقرة: ١٩٩] (م)', 'ആഇശ(റ): ഖുറൈശികളും അവരുടെ മതം പിന്തുടരുന്നവരും മുസ്ദലിഫയിലായിരുന്നു നിന്നിരുന്നത്. ബാക്കിയുള്ള എല്ലാ അറബികളും അറഫയിലുമായിരുന്നു നിന്നിരുന്നത്. അവരെ അൽഹുംസ് എന്ന് വിളിക്കപ്പെരുന്നു. ഇസ്ലാം സമാഗതമായപ്പോൾ അല്ലാഹു തന്റെ പ്രവാചകൻ(സ)യോട് അറഫയിൽ വെന്നു നിൽക്കുവാനും എന്നിട്ട് അവിടെ നിന്ന് പുറപ്പെടുവാനും കൽപ്പിച്ചു. ഈ വിധി ഈ സൂക്തമനുസരിച്ചായിരുന്നു. ''പിന്നീട് ജനങ്ങൾ പുറപ്പെടുന്നിടത്ത് നിന്ന് നിങ്ങളും പുറപ്പെടുക.'' (ബഖറ: 199). (മു,ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م']::text[], array['മു','ന']::text[], 'البقرة: ١٩٩', null, 365, 365, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=121 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 397, 'عن جُبَيْرِ بْنِ مُطْعِمٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَضْلَلْتُ بَعِيرًا لِي، فَذَهَبْتُ أَطْلُبُهُ بِعَرَفَةَ يَوْمَ عَرَفَةَ، فَرَأَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَاقِفًا، فَقُلْتُ: مَا شَأْنُ هَذَا؟ إِنَّمَا هَذَا مِنَ الْحُمْسِ. (ن)', 'ജുബൈർ ബിൻ മുത്വഇം(റ): എന്റെ ഒരു ഒട്ടകം നഷ്ടപ്പെട്ടു. അറഫാ ദിനത്തിൽ അതിനെയന്വേഷിച്ചു ഞാനവിടെച്ചെന്നു. അന്നേരം റസൂൽ(സ) അവടെ നിൽക്കുന്നത് ഞാൻ കണ്ടു. അപ്പോൾ ഞാൻ പറഞ്ഞു: ഇതെന്താണ് കാര്യം, നിശ്ചയം റസൂൽ(സ) ഹുംസിൽ പെട്ടയാളാണല്ലോ. (ന)', 'جُبَيْرِ بْنِ مُطْعِمٍ', 'ജുബൈർ ബിൻ മുത്വഇം(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 365, 365, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=121 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 398, 'عَنْ أُسَامَةَ بْنِ زَيْدٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كُنْتُ رَدِيفَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِعَرَفَاتٍ، فَرَفَعَ يَدَيْهِ يَدْعُو، فَمَالَتْ بِهِ نَاقَتُهُ فَسَقَطَ خِطَامُهَا، فَتَنَاوَلَ الْخِطَامَ بِإِحْدَى يَدَيْهِ وَهُوَ رَافِعٌ يَدَهُ الْأُخْرَى. (ن)', 'ഉസാമതുബ്നു സൈദ്(റ): അറഫയിൽ വെച്ച് ഞാൻ നബി(സ)യുടെ പിന്നിൽ സവാരി ചെയ്യുകയായിരുന്നു. അന്നേരം റസൂൽ(സ) കയ്യുയർത്തി പ്രാർത്ഥിച്ചു. ഇതേസമയം റസൂൽ(സ)യുടെ ഒട്ടകം ചെരിയുകയും അതിന്റെ മൂക്കയർ താഴെ വീഴുകയും ചെയ്തു. അന്നേരം റസൂൽ(സ) രണ്ടാലൊരു കൈ കൊണ്ട് അത് എടുത്തു, മറ്റൊരു കൈ അവിടന്ന് ഉയർത്തിപ്പിടിച്ചിരിക്കുകയായിരുന്നു. (ന)', 'أُسَامَةَ بْنِ زَيْدٍ', 'ഉസാമതുബ്നു സൈദ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 366, 366, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=122 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 399, 'عَنْ عَبَّاسِ بْنِ مِرْدَاسٍ السُّلَمِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ دَعَا لِأُمَّتِهِ عَشِيَّةَ عَرَفَةَ بِالْمَغْفِرَةِ، فَأُجِيبَ: "إِنِّي قَدْ غَفَرْتُ لَهُمْ، مَا خَلَا الظَّالِمَ، فَإِنِّي آخُذُ لِلْمَظْلُومِ مِنْهُ". قَالَ: "أَيْ رَبِّ، إِنْ شِئْتَ أَعْطَيْتَ الْمَظْلُومَ مِنَ الْجَنَّةِ، وَغَفَرْتَ لِلظَّالِمِ" فَلَمْ يُجَبْ عَشِيَّتَهُ. فَلَمَّا أَصْبَحَ بِالْمُزْدَلِفَةِ أَعَادَ الدُّعَاءَ، فَأُجِيبَ إِلَى مَا سَأَلَ. قَالَ: فَضَحِكَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَوْ قَالَ: تَبَسَّمَ. فَقَالَ لَهُ أَبُو بَكْرٍ وَعُمَرُ: بِأَبِي أَنْتَ وَأُمِّي، إِنَّ هَذِهِ لَسَاعَةٌ مَا كُنْتَ تَضْحَكُ فِيهَا، فَمَا الَّذِي أَضْحَكَكَ؟ أَضْحَكَ اللَّهُ سِنَّكَ! قَالَ: "إِنَّ عَدُوَّ اللَّهِ إِبْلِيسَ، لَمَّا عَلِمَ أَنَّ اللَّهَ عَزَّ وَجَلَّ قَدِ اسْتَجَابَ دُعَائِي، وَغَفَرَ لِأُمَّتِي، أَخَذَ التُّرَابَ فَجَعَلَ يَحْثُوهُ عَلَى رَأْسِهِ، وَيَدْعُو بِالْوَيْلِ وَالثُّبُورِ. فَأَضْحَكَنِي مَا رَأَيْتُ مِنْ جَزَعِهِ". (د,جه)', 'അബ്ബാസുബ്നു മിർദാസുസ്സുല്ലമീ(റ): നിശ്ചയം നബി(സ) അറഫയിൽ വെച്ച് രാത്രി സമയത്ത് തന്റെ സമുദായത്തിന് വേണ്ടി പ്രാർത്ഥിച്ചു. ഉടനെയതിന് ഉത്തരം ലഭിച്ചു. "തീർച്ചയായും ഞാൻ അവർക്ക് പൊറുത്ത് കൊടുത്തു. അക്രമിക്കൊഴിച്ച്, അവനിൽ നിന്നും ഞാൻ അക്രമിക്കപ്പെട്ടവർക്ക് പ്രതിഫലം പിടിക്കും." റസൂൽ(സ) ചോദിക്കുന്നു: "രക്ഷിതാവെ, നീ ഉദ്ധേശിച്ചാൽ അക്രമിക്കപ്പെട്ടയാക്ക് സ്വർഗ്ഗം കൊടുക്കുകയും അക്രമിക്ക് പൊറുത്ത് കൊടുക്കുകയും ചെയ്യാവുന്നതാണ്." അപ്പോഴാ രാത്രി സമയം ഉത്തരം നൽകപ്പെട്ടില്ല. പിന്നീട് പ്രഭാത സമയം മുസ്ദലിഫയിലെത്തിയപ്പോൾ അതേ പ്രാർത്ഥന മടക്കി ചെയ്തു. അന്നേരം ചോദിച്ച കാര്യത്തിന് ഉത്തരം നൽകപ്പെട്ടു. ഇബ്നുഅബ്ബാസ്(റ) പറയുന്നു: റസൂൽ(സ) ചിരിച്ചു. അല്ലെങ്കിൽ പുഞ്ചിരിച്ചു. അന്നേരം അബൂബക്കർ(റ)വും ഉമർ(റ)വും തിരുമേനി(സ)യോട് പറഞ്ഞു: എന്റെ ഉമ്മയും ഉപ്പയും അങ്ങേക്ക് ദണ്ഡമാണ്. തീർച്ചയായും അങ്ങ് പിരിക്കാറില്ലാത്ത സമയമാണിത്. പിന്നെ ഇപ്പോൾ അങ്ങയെ ചിരിപ്പിച്ച കാര്യമെന്താണ്? അല്ലാഹു അങ്ങയുടെ പല്ല് വെളിവാകും വിധം ചിരിപ്പിച്ചിരിക്കുന്നു! റസൂൽ(സ) പറഞ്ഞു: "തീർച്ചയായും അല്ലാഹുവിന്റെ ശത്രുവായ പിശാച്, എന്റെ പ്രാർത്ഥനക്കല്ലാഹു ഉത്തരം നൽകിയെന്നും, എന്റെ സമുദായത്തിന് പൊറുത്ത് കൊടുത്തെന്നുമറിഞ്ഞപ്പോൾ മണ്ണെടുത്ത് അവന്റെ തലയിലൂടെ വാരിയിടുന്നു. അവന്റെ നാശം എന്നവൻ വിളിച്ചു പറയുന്നു. അവന്റെ വെപ്രാളം കണ്ടതാണ് എന്നെ ചിരിപ്പിച്ചത്." (ദ,ജ)', 'عَبَّاسِ بْنِ مِرْدَاسٍ السُّلَمِيِّ', 'അബ്ബാസുബ്നു മിർദാസുസ്സുല്ലമീ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 366, 366, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=122 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 400, 'عَنْ زَيْدِ بْنِ أَسْلَمَ رَضِيَ اللهُ عَنْهُ، رَجُلٍ مِنْ بَنِي ضَمْرَةَ رَضِيَ اللهُ عَنْهُ، عَنْ أَبِيهِ أَوْ عَمِّهِ قَالَ: رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ عَلَى الْمِنْبَرِ بِعَرَفَةَ. [قال المنذري: فيه رجل مجهول]', 'സൈദ് ബിൻ അസ്ലം(റ): ളംറ കുടുംബക്കാരനായ അദ്ദേഹം തന്റെ പിതാവിൽ നിന്നോ പിതൃവ്യനിൽ നിന്നോ നിവേദനം: അറഫയിൽ മിമ്പറിൽ റസൂൽ(സ)യെ ഞാൻ കണ്ടു. (സനദിൽ മജ്ഹൂലായ ഒരാളുണ്ട് എന്ന് മുൻദിർ പറഞ്ഞു.)', 'زَيْدِ بْنِ أَسْلَمَ', 'സൈദ് ബിൻ അസ്ലം(റ)', null, null, '{}'::text[], '{}'::text[], 'قال المنذري: فيه رجل مجهول', null, 366, 367, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=123 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 401, 'عن نُبَيْط رَضِيَ اللهُ عَنْهُ قَالَ: رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَخْطُبُ عَلَى جَمَلٍ أَحْمَرَ بِعَرَفَةَ قَبْلَ الصَّلَاةِ. (ن)', 'നുബൈത്(റ): അറഫാദിനത്തിൽ നിസ്കാരത്തിനു മുമ്പ് റസൂൽ(സ) ചുവന്ന ഒട്ടകപ്പുറത്തേറി പ്രസംഗിക്കുന്നത് ഞാൻ കണ്ടു. (ന)', 'نُبَيْط', 'നുബൈത്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 367, 367, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=123 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 402, 'عَنْ سَالِمِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُمَا: أَنَّ عَبْدَ اللَّهِ بْنَ عُمَرَ رَضِيَ اللهُ عَنْهُمَا جَاءَ إِلَى الْحَجَّاجِ بْنِ يُوسُفَ يَوْمَ عَرَفَةَ حِينَ زَالَتِ الشَّمْسُ وَأَنَا مَعَهُ، فَقَالَ: الرَّوَاحَ إِنْ كُنْتَ تُرِيدُ السُّنَّةَ. فَقَالَ: هَذِهِ السَّاعَةَ؟ قَالَ: نَعَمْ. قَالَ سَالِمٌ: فَقُلْتُ لِلْحَجَّاجِ: إِنْ كُنْتَ تُرِيدُ أَنْ تُصِيبَ الْيَوْمَ السُّنَّةَ فَأَقْصِرِ الْخُطْبَةَ وَعَجِّلِ الصَّلَاةَ. فَقَالَ عَبْدُ اللَّهِ بْنُ عُمَرَ: صَدَقَ. (ن)', 'സാലിമുബ്നു അബ്ദില്ല(റ): അറഫാ ദിനം സുര്യൻ മധ്യത്തിൽ നിന്ന് നീങ്ങിയപ്പോൾ അബ്ദുല്ലാഹിബ്നു ഉമർ(റ) ഹജ്ജാജിനടുത്തേക്ക് പോയി. ഞാനും അവരോട് കൂടെയുണ്ടായിരുന്നു. അബ്ദുല്ല(റ) പറഞ്ഞു: സുന്നത് ഉദ്ദേശിക്കുന്നുവെങ്കിൽ നീ ഇപ്പോൾ ഇവിടെ നിന്ന് പുറപ്പെടുക. ഹജ്ജാജ് ചോദിച്ചു: ഈ സമയത്തോ? അബ്ദുല്ല(റ) പറഞ്ഞു: അതെ. സാലിം(റ) പറയുന്നു: അപ്പോൾ ഞാൻ ഹജ്ജാജിനോട് പറഞ്ഞു: ഇന്നത്തെ ദിനത്തിലെ സുന്നത് കിട്ടണമെന്ന് ആഗ്രഹിക്കുന്നുവെങ്കിൽ നീ പ്രഭാഷണം ചുരുക്കുകയും നിസ്കാരം പെട്ടെന്നാക്കുകയും ചെയ്യുക. അപ്പോൾ അബ്ദുല്ല(റ) പറഞ്ഞു: അദ്ധേഹം പറഞ്ഞത് സത്യമാണ്. (ന)', 'سَالِمِ بْنِ عَبْدِ اللَّهِ', 'സാലിമുബ്നു അബ്ദില്ല(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 367, 367, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=124 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 403, 'عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي الصَّلَاةَ لِوَقْتِهَا، إِلَّا بِجَمْعٍ وَعَرَفَاتٍ. (ن)', 'അബ്ദുല്ലാഹിബിൻ മസ്ഊദ്(റ): റസൂൽ(സ) അതാതിന്റെ സമയത്ത് നിസ്കാരം നിർവ്വഹിക്കുമായിരുന്നു. മുസ്ദലിഫയിലും അറഫയിലും ഒഴികെ. (ന)', 'عَبْدِ اللَّهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബിൻ മസ്ഊദ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 367, 367, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=125 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 404, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: غَدَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ مِنًى حِينَ صَلَّى الصُّبْحَ صَبِيحَةَ يَوْمِ عَرَفَةَ، حَتَّى أَتَى عَرَفَةَ فَنَزَلَ بِنَمِرَةَ، وَهِيَ مَنْزِلُ الْإِمَامِ الَّذِي يَنْزِلُ بِهِ بِعَرَفَةَ، حَتَّى إِذَا كَانَ عِنْدَ صَلَاةِ الظُّهْرِ رَاحَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُهَجِّرًا، فَجَمَعَ بَيْنَ الظُّهْرِ وَالْعَصْرِ، ثُمَّ خَطَبَ النَّاسَ، ثُمَّ رَاحَ فَوَقَفَ عَلَى الْمَوْقِفِ مِنْ عَرَفَةَ. (د)', 'ഇബ്നുഉമർ(റ): അറഫാദിനപ്രഭാതത്തിൽ സുബ്ഹി നിസ്കരിച്ച് റസൂൽ(സ) മിനയിൽ നിന്ന് യാത്ര തുടങ്ങി. അറഫയിൽ എത്തിയപ്പോൾ നമിറയിൽ ഇറങ്ങി. അറഫയിൽ അവിടെയാണ് ഭരണാധികാരികൾ ഇറങ്ങാറ്. ളുഹ്ർ നിസ്കാരത്തിന്റെ സമയമായപ്പോൾ തിരുമേനി(സ) ഉച്ചവെയിലിൽ സഞ്ചരിച്ചു. ളുഹ്റും അസറും ജംആക്കി. ശേഷം റസൂൽ(സ) പ്രഭാഷണം നടത്തി. എന്നിട്ട് സഞ്ചരിച്ച് അറഫയിലെ മൗഖിഫിൽ ചെന്ന് നിന്നു. (ദ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 367, 368, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=125 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 405, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَفَاضَ مِنْ عَرَفَةَ، وَجَعَلَ يَقُولُ: "السَّكِينَةَ عِبَادَ اللَّهِ". يَقُولُ بِيَدِهِ هَكَذَا، وَأَشَارَ أَيُّوبُ بِبَاطِنِ كَفِّهِ إِلَى السَّمَاءِ. (ن)', 'ജാബിർ(റ): റസൂൽ(സ) അറഫയിൽ നിന്ന് പുറപ്പെട്ടു. തിരുമേനി(സ) പറയുന്നുണ്ടായിരുന്നു: "അല്ലാഹുവിന്റെ ദാസരേ, അച്ചടക്കം പാലിക്കുക." റസൂൽ(സ) തന്റെ കരങ്ങൾ കൊണ്ട് ഇപ്രകാരം പറഞ്ഞു, അയ്യൂബ്(റ) തന്റെ മുൻകയ്യിന്റെ പള്ള കൊണ്ട് ആകാശത്തേക്ക് ചൂണ്ടി. (ന)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 368, 368, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=126 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 406, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قَالَتْ قُرَيْشٌ: نَحْنُ قَوَاطِنُ الْبَيْتِ، لَا نُجَاوِزُ الْحَرَمَ. فَقَالَ اللَّهُ عَزَّ وَجَلَّ: {ثُمَّ أَفِيضُوا مِنْ حَيْثُ أَفَاضَ النَّاسُ} [البقرة: ١٩٩] (خ)', 'ആഇശ(റ): ഖുറൈശികൾ പറഞ്ഞു: ഞങ്ങൾ കഅ്ബയിൽ താമസിക്കുന്നവരാണ്. ഞങ്ങൾ ഹറം വിട്ട് പോവുകയില്ല. അപ്പോൾ അല്ലാഹു ഇറക്കി. ''ജനങ്ങൾ പുറപ്പെടുന്നതിനനുരസിച്ച് നിങ്ങളും പുറപ്പെടുക.''(അൽ ബഖറ: 199) (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], 'البقرة: ١٩٩', null, 368, 368, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=126 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 407, 'عَنْ أُسَامَةَ بْنِ زَيْدٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: أَفَضْتُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَلَمَّا بَلَغَ الشِّعْبَ الَّذِي يَنْزِلُ عِنْدَهُ الْأُمَرَاءُ نَزَلَ فَبَالَ، فَتَوَضَّأَ، قُلْتُ: الصَّلَاةَ؟ قَالَ: "الصَّلَاةُ أَمَامَكَ". فَلَمَّا انْتَهَى إِلَى جَمْعٍ أَذَّنَ وَأَقَامَ ثُمَّ صَلَّى الْمَغْرِبَ، ثُمَّ لَمْ يَحِلَّ أَحَدٌ مِنَ النَّاسِ حَتَّى قَامَ فَصَلَّى الْعِشَاءَ. (د,ن,جه)', 'ഉസാമതുബ്നു സൈദ്(റ): ഞാൻ റസൂൽ(സ)യോടൊപ്പം പുറപ്പെട്ടു. അങ്ങനെ ഭരണാധികാരികൾ ഇറങ്ങുന്ന മലഞ്ചെരുവിൽ എത്തിയപ്പോൾ റസൂൽ(സ) ഇറങ്ങുകയും മൂത്രമൊഴിച്ച് വുളു എടുക്കുകയും ചെയ്തു. ഞാൻ പറഞ്ഞു: നിസ്കാരം? തിരുമേനി(സ) പറഞ്ഞു: "നിസ്കാരം വരുന്ന സ്ഥലത്ത് വെച്ചാക്കാം." മുസ്ദലിഫയിൽ എത്തിയപ്പോൾ ബാങ്കും ഇഖാമത്തും കൊടുക്കുകയും ശേഷം മഗ്രിബ് നിസ്കരിക്കുകയും ചെയ്തു. ഇശാ നിസ്കരിക്കുവോളം ആരും തന്നെ തങ്ങളുടെ ഒട്ടകക്കയറുകൾ അഴിച്ചില്ല. (ദ,ന,ജ)', 'أُسَامَةَ بْنِ زَيْدٍ', 'ഉസാമതുബ്നു സൈദ്(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 368, 368, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=126 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 408, 'عَنْ عُرْوَةَ قَالَ: سُئِلَ أُسَامَةُ وَأَنَا شَاهِدٌ – أَوْ قَالَ: سَأَلْتُ أُسَامَةَ بْنَ زَيْدٍ رَضِيَ اللهُ عَنْهُمَا – وَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَرْدَفَهُ مِنْ عَرَفَاتٍ، قُلْتُ: كَيْفَ كَانَ يَسِيرُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ أَفَاضَ مِنْ عَرَفَةَ؟ قَالَ: كَانَ يَسِيرُ الْعَنَقَ، فَإِذَا وَجَدَ فَجْوَةً نَصَّ. (م)', 'ഉർവ്വ(റ): ഞാൻ സാക്ഷിയായിരിക്കെ ഉസാമ(റ) ചോദിക്കപ്പെട്ടു: അല്ലെങ്കിൽ ഞാൻ ഉസാമതുബ്നു സൈദ്(റ)നോട് ചോദിച്ചു: - അറഫയിൽ നിന്ന് (മുസ്ദലിഫയിലേക്ക് പോകുമ്പോൾ) റസൂൽ(സ) ഉസാമതിനെ തന്റെ പിന്നിൽ കയറ്റിയിരുന്നു - അറഫയിൽ നിന്ന് (മുസ്ദലിഫയിലേക്ക്) പോകുമ്പോൾ റസൂൽ(സ) എങ്ങനെയായിരുന്നു സഞ്ചരിച്ചിരുന്നത്. ഉസാമത്(റ) പറഞ്ഞു: റസൂൽ(സ) മിതമായ നിലയിൽ നടക്കുമായിരുന്നു. വീതിയുള്ള സ്ഥലത്തെത്തിയാൽ അൽപ്പം വേഗത കൂട്ടും. (മു)', 'عُرْوَةَ قَالَ', 'ഉർവ്വ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 368, 368, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=126 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 409, 'عَنِ ابْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: مَا رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَّى صَلَاةً إِلَّا لِوَقْتِهَا، إِلَّا بِجَمْعٍ: فَإِنَّهُ جَمَعَ بَيْنَ الْمَغْرِبِ وَالْعِشَاءِ بِجَمْعٍ، وَصَلَّى صَلَاةَ الصُّبْحِ مِنَ الْغَدِ قَبْلَ وَقْتِهَا. (ق,د)', 'ഇബ്നുമസ്ഊദ്(റ): റസൂൽ(സ) ഓരോ നിസ്കാരത്തെയും അതിന്റെ സമയത്തല്ലാതെ നിർവ്വഹിക്കുന്നത് ഞാൻ കണ്ടിട്ടില്ല, ''മുസ്ദലിഫയി''ൽ വെച്ച് നിസ്കരിച്ചതൊഴിച്ച്. നിശ്ചയം റസൂൽ(സ) ''മുസ്ദലിഫയി''ൽ വെച്ച് മഗ്രിബും ഇശാഉം ഒരുമിച്ച്- ജംആക്കി നിസ്കരിച്ചു. പിറ്റെ ദിവസത്തെ സുബ്ഹിയും സമയത്തിന് മുമ്പ് നിർവ്വഹിച്ചു. (ബു,മു,ദ)', 'ابْنِ مَسْعُودٍ', 'ഇബ്നുമസ്ഊദ്(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 369, 369, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=127 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 410, 'عن سَلَمَةَ بْنِ كُهَيْلٍ قَالَ: رَأَيْتُ سَعِيدَ بْنَ جُبَيْرٍ أَقَامَ بِجَمْعٍ فَصَلَّى الْمَغْرِبَ ثَلَاثًا ثُمَّ صَلَّى الْعِشَاءَ رَكْعَتَيْنِ، ثُمَّ قَالَ: شَهِدْتُ ابْنَ عُمَرَ رَضِيَ اللهُ عَنْهُمَا صَنَعَ فِي هَذَا الْمَكَانِ مِثْلَ هَذَا وَقَالَ: شَهِدْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَنَعَ مِثْلَ هَذَا فِي هَذَا الْمَكَانِ. (د)', 'സലമത്തുബിൻ കുഹൈൽ(റ): സഈദ് ബിൻ ജുബൈർ(റ) മുസ്ദലിഫയിൽ നിൽക്കുന്നതും മഗ്രിബ് മൂന്ന് റക്അത്തും ഇശാ രണ്ട് റക്അത്തും നിസ്കരിക്കുന്നതും ഞാൻ കണ്ടു. പിന്നീട് അദ്ദേഹം പറഞ്ഞു: ഈ സ്ഥലത്തു വെച്ച് ഇബ്നുഉമർ(റ) ഇപ്രകാരം ചെയ്യുകയും ശേഷം ഇങ്ങനെ പറയുകയും ചെയ്തു. റസൂൽ(സ) ഈ സ്ഥലത്ത് വെച്ച് ഇപ്രകാരം ചെയ്തതിന് ഞാൻ സാക്ഷ്യം വഹിച്ചിട്ടുണ്ട്. (ദ)', 'سَلَمَةَ بْنِ كُهَيْلٍ قَالَ', 'സലമത്തുബിൻ കുഹൈൽ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 369, 369, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=127 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 411, 'عَنْ أَبِي أَيُّوبَ الْأَنْصَارِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: صَلَّيْتُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْمَغْرِبَ وَالْعِشَاءَ، فِي حَجَّةِ الْوَدَاعِ بِالْمُزْدَلِفَةِ. (ق,ن,جه)', 'അബൂ അയ്യൂബിൽ അൻസാരീ(റ): ഹജ്ജതുൽ വിദാഇൽ മുസ്ദലിഫയിൽ വെച്ച് റസൂൽ(സ)യോടൊപ്പം ഞാൻ മഗ്രിബും ഇശാഉം നിസ്കരിച്ചു. (ബു,മു,ന,ജ)', 'أَبِي أَيُّوبَ الْأَنْصَارِيِّ', 'അബൂ അയ്യൂബിൽ അൻസാരീ(റ)', null, null, array['ق','ن','جه']::text[], array['ബു','മു','ന','ജ']::text[], null, null, 369, 369, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=127 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 412, 'عن ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: جَمَعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَيْنَ الْمَغْرِبِ وَالْعِشَاءِ، بِجَمْعٍ، لَيْسَ بَيْنَهُمَا سَجْدَةٌ. وَصَلَّى الْمَغْرِبَ ثَلَاثَ رَكَعَاتٍ، وَصَلَّى الْعِشَاءَ رَكْعَتَيْنِ. فَكَانَ عَبْدُ اللَّهِ يُصَلِّي بِجَمْعٍ كَذَلِكَ حَتَّى لَحِقَ بِاللَّهِ. (م)', 'ഇബ്നുഉമർ(റ): നബി(സ) മുസ്ദലിഫയിൽ മഗ്രിബ്-ഇശാ നിസ്കാരങ്ങൾ ജംആക്കി നിസ്കരിച്ചു. അതിനിടയിൽ സുജൂദില്ലാത്ത വിധം. അങ്ങിനെ മഗ്രിബ് മൂന്നും, ഇശാ രണ്ടും റക്അത്തായി അനുഷ്ഠിച്ചു. അബ്ദുല്ലാഹ്(റ) എന്നവർ വഫാത്താകുവോളം മുസ്ദലിഫയിൽ ഇപ്രകാരം ജംആക്കിയാണ് നിസ്കരിച്ചിരുന്നത്. (മു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 369, 369, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=127 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 413, 'عَنْ سَعِيدِ بْنِ جُبَيْرٍ قَالَ: أَفَضْنَا مَعَ ابْنِ عُمَرَ حَتَّى أَتَيْنَا جَمْعًا، فَصَلَّى بِنَا الْمَغْرِبَ وَالْعِشَاءَ بِإِقَامَةٍ وَاحِدَةٍ، ثُمَّ انْصَرَفَ فَقَالَ: هَكَذَا صَلَّى بِنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي هَذَا الْمَكَانِ. (م)', 'സഈദുബ്നു ജുബൈർ(റ): ഇബ്നു ഉമർ(റ)വിനോടൊപ്പം ഞങ്ങൾ ഇഫാളത്തിന്റെ ത്വവാഫ് ചെയ്തു. ഞങ്ങൾ ജംഅ് എന്ന സ്ഥലത്തെത്തിയപ്പോൾ ഞങ്ങളുമായദ്ധേഹം മഗ്രിബും, ഇശാഉം ഒറ്റ ഇഖാമത്തിലായി നിസ്കരിച്ചു. പിന്നീട് തിരിഞ്ഞു നിന്നു പറഞ്ഞു. ഈ സ്ഥലത്തു വെച്ച് ഇപ്രകാരമാണ് ഞങ്ങളുമായി റസൂൽ(സ) ചെയ്തത്. (മു)', 'سَعِيدِ بْنِ جُبَيْرٍ قَالَ', 'സഈദുബ്നു ജുബൈർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 369, 369, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=127 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 414, 'عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: مَا رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَّى صَلَاةً إِلَّا لِمِيقَاتِهَا إِلَّا صَلَاتَيْنِ: صَلَاةَ الْمَغْرِبِ وَالْعِشَاءِ بِجَمْعٍ، وَصَلَّى الْفَجْرَ يَوْمَئِذٍ قَبْلَ مِيقَاتِهَا. (م)', 'അബ്ദില്ലാഹിബിൻ മസ്ഊദ്(റ): മീഖാത്തിൽ വെച്ച് റസൂൽ(സ) രണ്ട് നിസ്കാരമല്ലാതെ മറ്റൊന്നും അതിന്റെ സമയത്തല്ലാതെ നിർവ്വഹിക്കുന്നത് ഞാൻ കണ്ടിട്ടില്ല. മുസ്ദലിഫയിൽ വെച്ച് നമസ്കരിച്ച ഇശാഉം മഗ്രിബുമായിരുന്നു അവ. അന്നേ ദിവസം സമയത്തിന് മുമ്പായി റസൂൽ(സ) സുബ്ഹി നമസ്കരിച്ചു. (മു)', 'عَبْدِ اللَّهِ بْنِ مَسْعُودٍ', 'അബ്ദില്ലാഹിബിൻ മസ്ഊദ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 369, 370, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=127 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 415, 'عَنْ عَبْدِ الرَّحْمَنِ بْنِ يَعْمَرَ الدِّيْلِي رَضِيَ اللهُ عَنْهُ: أَنَّ نَاسًا مِنْ أَهْلِ نَجْدٍ أَتَوْا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ بِعَرَفَةَ، فَسَأَلُوهُ، فَأَمَرَ مُنَادِيًا فَنَادَى: "الْحَجُّ عَرَفَةُ، مَنْ جَاءَ لَيْلَةَ جَمْعٍ قَبْلَ طُلُوعِ الْفَجْرِ فَقَدْ أَدْرَكَ الْحَجَّ. أَيَّامُ مِنًى ثَلَاثَةٌ، فَمَنْ تَعَجَّلَ فِي يَوْمَيْنِ فَلَا إِثْمَ عَلَيْهِ، وَمَنْ تَأَخَّرَ فَلَا إِثْمَ عَلَيْهِ". (د,ت,ن)', 'അബ്ദുർറഹ്മാൻ(റ): റസൂൽ(സ) അറഫയിലായിരിക്കെ, ഒരു കൂട്ടം നജ്ദുകാർ തിരുമേനി(സ)യോട് വന്നു കൊണ്ട് (ചിലത്) ചോദിച്ചു: റസൂൽ(സ) വിളിച്ചു പറയുന്ന ഒരാളോട് ഇപ്രകാരം പറയാൻ കൽപ്പിച്ചു: "ഹജ്ജ് അറഫയാണ്. വല്ലവനും മുസ്ദലിഫ രാവിൽ ഫജ്റ് ഉദിക്കുന്നിതിന്ന മുമ്പ് വന്നാൽ അവന് ഹജ്ജ് ലഭിക്കും. മിനയിൽ നിൽക്കേണ്ടത് മൂന്ന് ദിനമാണ്. രണ്ട് ദിവസം കഴിഞ്ഞ് ആരെങ്കിലും വേഗം പോയാൽ അവന്റെ മേൽ കുറ്റമുണ്ടാവില്ല. പിന്തിയാലും കുറ്റമുണ്ടാവുകയില്ല." (ദ,തു,ന)', 'عَبْدِ الرَّحْمَنِ بْنِ يَعْمَرَ الدِّيْلِي', 'അബ്ദുർറഹ്മാൻ(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 370, 370, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=128 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 416, 'عَنْ عُرْوَةَ بْنِ مُضَرِّسٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَتَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالْمُزْدَلِفَةِ حِينَ خَرَجَ إِلَى الصَّلَاةِ، فَقُلْتُ: يَا رَسُولَ اللَّهِ، إِنِّي جِئْتُ مِنْ جَبَلَيْ طَيِّئٍ، أَكْلَلْتُ رَاحِلَتِي وَأَتْعَبْتُ نَفْسِي، وَاللَّهِ مَا تَرَكْتُ مِنْ حَبْلٍ إِلَّا وَقَفْتُ عَلَيْهِ، فَهَلْ لِي مِنْ حَجٍّ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ شَهِدَ صَلَاتَنَا هَذِهِ، وَوَقَفَ مَعَنَا حَتَّى نَدْفَعَ، وَقَدْ وَقَفَ بِعَرَفَةَ قَبْلَ ذَلِكَ لَيْلًا أَوْ نَهَارًا، فَقَدْ أَتَمَّ حَجَّهُ وَقَضَى تَفَثَهُ". قَالَ ترمذي هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ. (ت)', 'ഉർവതുബ്നു മുളർരിസ്(റ): മുസ്ദലിഫയിൽ വെച്ച് റസൂൽ(സ) നിസ്കാരത്തിന് പുറപ്പെട്ടപ്പോൾ ഞാന് തിരുമേനി(സ)യെ സമീപിച്ചു. ഞാൻ ചോദിച്ചു: തിരുദുതരെ, ത്വയ്യിഇന്റെ ഇരു പർവ്വതത്തിൽ നിന്നാണ് ഞാൻ വരുന്നത്. എന്റെ ശരീരവും വാഹനവും വല്ലാതെ ക്ഷീണിച്ചു. അല്ലാഹുവാണ് സത്യം. (വഴിയിലെ) എല്ലാ മണൽ കുനയിലും ഞാൻ നിന്നു. എനിക്ക് ഹജ്ജിൽ നിന്ന് വല്ലതുമുണ്ടോ? അപ്പോൾ റസൂൽ(സ) പ്രതിവച്ചിച്ചു: "നമ്മുടെ ഈ നിസ്കാരത്തിന് സാക്ഷിയാവുകയും നാം പോരുന്നത് വരെ നമ്മോട് കുടെ നൽക്കുകയും അതിനു മുമ്പ് അറഫയിൽ ഒരു രാപ്പകൽ നിൽക്കുകയും ചെയ്താൽ അവന്റെ ഹജ്ജ് പൂർത്തിയായിരിക്കുന്നു. അവൻ ഹജ്ജിന്റെ (അന്ത്യ) കർമ്മങ്ങൾ വീട്ടുകയും ചെയ്തിരിക്കുന്നു. (തു)', 'عُرْوَةَ بْنِ مُضَرِّسٍ', 'ഉർവതുബ്നു മുളർരിസ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 370, 370, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=128 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 417, 'عَنْ عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ ابْنُ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ وَنَحْنُ بِجَمْعٍ: سَمِعْتُ الَّذِي أُنْزِلَتْ عَلَيْهِ سُورَةُ الْبَقَرَةِ يَقُولُ فِي هَذَا الْمَكَانِ: "لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ". (ن)', 'അബ്ദുർറഹ്മാൻ ഇബ്നു യസീദ്(റ): ഞങ്ങൾ മുസ്ദലിഫയിൽ നിൽക്കെ ഇബ്നുമസ്ഊദ്(റ) ഞങ്ങളോട് പറഞ്ഞു: സൂറതുൽ ബഖറ ഇറക്കപ്പെട്ട വ്യക്തി ഇവിടെ വെച്ച് ഇങ്ങനെ പറയുന്നത് ഞാൻ കേട്ടു. "ലബ്ബൈകല്ലാഹുമ്മ ലബ്ബൈക്." (ന)', 'عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ', 'അബ്ദുർറഹ്മാൻ ഇബ്നു യസീദ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 370, 371, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=129 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 418, 'عَنْ عَمْرِو بْنِ مَيْمُونٍ قَالَ: حَجَجْنَا مَعَ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ، فَلَمَّا أَرَدْنَا أَنْ نُفِيضَ مِنَ الْمُزْدَلِفَةِ قَالَ: إِنَّ الْمُشْرِكِينَ كَانُوا يَقُولُونَ: أَشْرِقْ ثَبِيرُ، كَيْمَا نُغِيرُ. وَكَانُوا لَا يُفِيضُونَ حَتَّى تَطْلُعَ الشَّمْسُ، فَخَالَفَهُمْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأَفَاضَ قَبْلَ طُلُوعِ الشَّمْسِ. (خ,د,ت,ن,جه)', 'അംറുബ്നു മൈമൂൻ(റ): ഞങ്ങൾ ഉമർ(റ)വിന്റെ കൂടെ ഹജ്ജിന് വന്നു. ഞങ്ങൾ മുസ്ദലിഫയിൽ നിന്ന് പോകാൻ തുനിഞ്ഞപ്പോൾ ഉമർ(റ) പറഞ്ഞു: ബഹുദൈവാരാധകർ സൂര്യനുദിക്കുന്നതിന് മുമ്പ് (മുസ്ദലിഫയിൽ നിന്ന്) പോവുമായിരുന്നില്ല. അവർ പറയുമായിരുന്നു: സബീറെ, നീ പ്രകാശിക്കുക, എന്നാൽ ഞങ്ങൾക്ക് പെട്ടെന്ന് പോകാനാവും. സൂര്യനുദിക്കുന്നതിന് മുമ്പ് അവർ മുസ്ദലിഫയിൽ നിന്ന് പോവുമായിരുന്നു. റസൂൽ(സ) പക്ഷെ അവരോട് വിയോജിച്ചു. അങ്ങനെ ഉമർ(റ) സൂര്യനുദിക്കുന്നതിന് മുമ്പ് മുസ്ദലിഫ വിട്ടു. (ബു,മു,ദ,തു,ന,ജ)', 'عَمْرِو بْنِ مَيْمُونٍ قَالَ', 'അംറുബ്നു മൈമൂൻ(റ)', null, null, array['خ','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 371, 371, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=130 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 419, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: بَعَثَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي ثَقَلٍ مِنْ جَمْعٍ بِلَيْلٍ. (ق)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) എന്നെ കൂടെയുള്ള ദുർബലരുടെ കൂട്ടത്തിൽ മുസ്ദലിഫയിൽ നിന്ന് രാത്രി തന്നെ (മിനായിലേക്ക്) അയച്ചു. (ബു,മു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 371, 371, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=131 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 420, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَدَّمَ ضَعَفَةَ أَهْلِهِ، وَقَالَ: "لَا تَرْمُوا الْجَمْرَةَ حَتَّى تَطْلُعَ الشَّمْسُ". قَالَ ترمذي هذا حَدِيثٌ حَسَنٌ صَحِيحٌ. (ق,ت)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) തന്റെ കുടുംബത്തിലെ ബലഹീനരെ നേരത്തെ അയച്ചു. തിരുമേനി(സ) പറയുകയും ചെയ്തു: "സൂര്യനുദിക്കുന്നത് വരെ നിങ്ങൾ ജംറയെ എറിയരുത്". (ബു,മു,തു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 371, 371, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=131 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 421, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهُمَا أَنَّهَا قَالَتْ: اسْتَأْذَنَتْ سَوْدَةُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَيْلَةَ الْمُزْدَلِفَةِ تَدْفَعُ قَبْلَهُ، وَقَبْلَ حَطْمَةِ النَّاسِ، وَكَانَتِ [امْرَأَةً] ثَبطَةً – يَقُولُ الْقَاسِمُ: وَالثَّبِطَةُ الثَّقِيلَةُ – قَالَتْ: فَأَذِنَ لَهَا، فَخَرَجَتْ قَبْلَ دَفْعِهِ، وَحَبَسَنَا حَتَّى أَصْبَحْنَا فَدَفَعْنَا بِدَفْعِهِ، وَلَأَنْ أَكُونَ اسْتَأْذَنْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَمَا اسْتَأْذَنَتْهُ سَوْدَةُ فَأَكُونَ أَدْفَعُ بِإِذْنِهِ، أَحَبُّ إِلَيَّ مِنْ مَفْرُوحٍ بِهِ. (م)', 'ആഇശ(റ): സൗദ(റ) മുസ്ദലിഫയുടെ രാത്രി, റസൂൽ(സ)യുടെയും, ജനങ്ങളുടെ തിരക്ക് വർദ്ധിക്കുന്നതിന്റെയും മുമ്പായി (മിനായിലേക്ക്) പോകുവാൻ റസൂൽ(സ)യോട് അനുമതി ചോദിച്ചു. അവർ ഒരു തടിച്ച സ്ത്രീയായിരുന്നു. ആഇശ(റ) പറയുന്നു: അപ്പോൾ തിരുമേനി(സ) അവർക്ക് അനുമതി നൽകുകയും അതനുസരിച്ച് അവർ റസൂൽ(സ) പോകുന്നതിന് മുമ്പ് (മിനായിലേക്ക്) പോവുകയും ചെയ്തു. ഞങ്ങൾ പ്രഭാതം വരെ അവിടത്തന്നെ കഴിച്ചു കുട്ടി. അനന്തരം പ്രഭാതത്തിന് ശേഷം തിരുമേനി(സ) പോയപ്പോൾ ഞങ്ങളും പോയി. സൗദ(റ) അനുമതി ചോദിച്ചതു പോലെ ഞാനും തിരുമേനി(സ)യോട് അനുമതി ചോദിക്കുകയും, അനന്തരം തിരുമേനി(സ)യുടെ അനുവാദത്തോടു കൂടി എനിക്കും നേരത്തെ (മിനായിലേക്ക്) പുറപ്പെടാൻ സാധിക്കുകയും ചെയ്തിരുന്നുവെങ്കിൽ അതായിരുന്നു തിരുമേനി(സ)യോടൊപ്പം പോകുന്നതിലുള്ള സന്തോഷത്തേക്കാൾ എനിക്ക് പ്രിയങ്കരം. (മു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م']::text[], array['മു']::text[], 'امْرَأَةً', null, 371, 372, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=131 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 422, 'عَنْ عَبْدِ اللَّهِ مَوْلَى أَسْمَاءَ قَالَ: قَالَتْ لِي أَسْمَاءُ رَضِيَ اللهُ عَنْهَا وَهِيَ عِنْدَ دَارِ الْمُزْدَلِفَةِ: هَلْ غَابَ الْقَمَرُ؟ قُلْتُ: لَا، فَصَلَّتْ سَاعَةً، ثُمَّ قَالَتْ: يَا بُنَيَّ هَلْ غَابَ الْقَمَرُ؟ قُلْتُ: نَعَمْ، قَالَتْ: ارْحَلْ بِي، فَارْتَحَلْنَا حَتَّى رَمَتِ الْجَمْرَةَ، ثُمَّ صَلَّتْ فِي مَنْزِلِهَا، فَقُلْتُ لَهَا: أَيْ هَنْتَاهْ لَقَدْ غَلَّسْنَا، قَالَتْ: كَلَّا أَيْ بُنَيَّ، إِنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَذِنَ لِلظُّعُنِ. (م)', 'അസ്മാഅ്(റ)യുടെ അടിമ അബ്ദുല്ല(റ): അസ്മാഅ്(റ) മുസ്ദലിഫയിലെ താവളത്തിന്റെ അടുക്കൽ വെച്ച് എന്നോട് ചോദിച്ചു: ചന്ദ്രൻ അസ്തമിച്ചുവോ? ഞാൻ പറഞ്ഞു: ഇല്ല. അപ്പോൾ അവർ കുറച്ചു സമയം നമസ്കരച്ചു. പിന്നീട് വീണ്ടും ചോദിച്ചു: എന്റെ കുഞ്ഞിമോനേ, ചന്ദ്രൻ അസ്തമിച്ചുവോ? ഞാൻ പറഞ്ഞു: അതെ. അന്നേരം അവർ പറഞ്ഞു: എന്നാൽ നമുക്ക് പോകാം. ഉടനെ ഞങ്ങൾ (മുസ്ദലിഫയിൽ നിന്ന് മിനായിലേക്ക്) പോവുകയും, അവർ (അസ്മാഅ്) കല്ലെറിയുകയും ചെയ്തു. അനന്തരം അവർ അവരുടെ താവളത്തിൽ വന്ന് (സുബ്ഹി) നമസ്കരിച്ചു. അപ്പോൾ ഞാൻ അവരോട് പറഞ്ഞു: മഹതി, നാം വളരെ നേരത്തെ നിശ്ചിത സമയത്തിന് മുമ്പായി എത്തിയിരിക്കുന്നു. അവർ പറഞ്ഞു: എന്റെ കുഞ്ഞി മോനേ, ഇല്ല. നിശ്ചയമായും റസൂൽ(സ) സ്ത്രീകൾക്ക് മുസ്ദലിഫയിൽ നിന്ന് നേരത്തെ പുറപ്പെടാൻ അനുവാദം നൽകിയിട്ടുണ്ട്. (മു)', 'عَبْدِ اللَّهِ مَوْلَى أَسْمَاءَ قَالَ', 'അസ്മാഅ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 372, 372, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=131 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 423, 'عَنْ بِلَالِ بْنِ رَبَاحٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لَهُ غَدَاةَ جَمْعٍ: "يَا بِلَالُ، أَسْكِتِ النَّاسَ". أَوْ: "أَنْصِتِ النَّاسَ". ثُمَّ قَالَ: "إِنَّ اللَّهَ تَطَوَّلَ عَلَيْكُمْ فِي جَمْعِكُمْ هَذَا، فَوَهَبَ مُسِيئَكُمْ لِمُحْسِنِكُمْ، وَأَعْطَى مُحْسِنَكُمْ مَا سَأَلَ، ادْفَعُوا بِاسْمِ اللَّهِ". [ز: في سنده راو مجهول] (جه)', 'ബിലാൽ(റ): മുസ്ദലിഫയുടെ പ്രഭാതത്തിൽ റസൂൽ(സ) ബിലാൽ(റ)വിനോട് പറഞ്ഞു: "ബിലാലെ, നിങ്ങൾ ജനങ്ങളെ ശാന്തരാക്കുക." അല്ലെങ്കിൽ "നിശബ്ദരാക്കുക." ശേഷം റസൂൽ(സ) അരുളി: "നിങ്ങളുടെ ഈ മുസ്ദലിഫയിൽ വെച്ച് അല്ലാഹു നിങ്ങളെ ആദരിച്ചിരിക്കുന്നു. നിങ്ങളിലെ നല്ലവർ കാരണം പാപികളുടെ പാപം അവൻ പൊറുത്തിരിക്കുന്നു. നന്മ ചെയ്യുന്നവർക്ക് അവർ ചോദിച്ചതൊക്കെ നൽകിയിരിക്കുന്നു. അല്ലാഹുവിന്റെ നാമത്തിൽ നിങ്ങൾ (മുസ്ദലിഫയിൽ നിന്ന്) പോവുക.ജ" ഇതിന്റെ സനദിൽ അറിയപ്പെടാത്ത ഒരു നിവേദകനുണ്ട്. (ജ)', 'بِلَالِ بْنِ رَبَاحٍ', 'ബിലാൽ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده راو مجهول', null, 372, 372, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=132 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 424, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَوْضَعَ فِي وَادِي مُحَسِّرٍ، وَأَفَاضَ مِنْ جَمْعٍ وَعَلَيْهِ السَّكِينَةُ، وَأَمَرَهُمْ بِالسَّكِينَةِ، وَأَمَرَهُمْ أَنْ يَرْمُوا بِمِثْلِ حَصَى الْخَذْفِ، وَقَالَ: "لَعَلِّي لَا أَرَاكُمْ بَعْدَ عَامِي هَذَا". قَالَ ترمذي هذا حَدِيثٌ حَسَنٌ صَحِيحٌ. (ت)', 'ജാബിർ(റ): റസൂൽ(സ) മുഹസ്സിർ താഴ്വര വളരെ വേഗത്തിൽ മുറിച്ചു കടന്നു. റസൂൽ(സ) മുസ്ദലിഫയിൽ നിന്ന് വളരെ അച്ചടക്കത്തോടെ സഞ്ചരിച്ചു. ജനങ്ങളോട് അച്ചടക്കത്തിലിരിക്കാൻ കൽപ്പിക്കുകയും ചെയ്തു. ചെറിയ മിനുസമുള്ള ഉരുണ്ട കല്ല് പോലുള്ളത് കൊണ്ട് എറിയാൻ റസൂൽ(സ) നിർദ്ദേശിച്ചു. ശേഷം തിരുമേനി(സ) അരുളി: "ഈ വർഷത്തിന് ശേഷം ഞാൻ നിങ്ങളെ കണ്ടില്ലെന്ന് വന്നേക്കും." (തു)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 372, 372, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=132 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 425, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّمَا جُعِلَ رَمْيُ الْجِمَارِ، وَالسَّعْيُ بَيْنَ الصَّفَا وَالْمَرْوَةِ، لِإِقَامَةِ ذِكْرِ اللَّهِ". قَالَ ترمذي هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ. (د,ت)', 'ആഇശ(റ): റസൂൽ(സ) പറയുന്നു: "ജംറകൾ എറിയപ്പെടുന്നതും, സ്വഫാ മർവ്വക്കിടയിലുള്ള നടത്തവും അല്ലാഹുവിന്റെ സ്മരണക്ക് വേണ്ടിയാക്കപ്പെട്ടതാണ്." (ദ,തു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 373, 373, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=133 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 426, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَدَّمَ ضَعَفَةَ أَهْلِهِ، وَقَالَ: "لَا تَرْمُوا الْجَمْرَةَ حَتَّى تَطْلُعَ الشَّمْسُ". قَالَ ترمذي هذا حَدِيثٌ حَسَنٌ صَحِيحٌ. (ق,ت)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) തന്റെ കുടുംബത്തിലെ ബലഹീനരെ നേരത്തെ അയച്ചു. തിരുമേനി(സ) പറയുകയും ചെയ്തു: "സൂര്യനുദിക്കുന്നത് വരെ നിങ്ങൾ ജംറയെ എറിയരുത്." (ബു,മു,തു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 373, 373, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=134 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 427, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَرْمِي الْجِمَارَ إِذَا زَالَتِ الشَّمْسُ، قَدْرَ مَا إِذَا فَرَغَ مِنْ رَمْيِهِ صَلَّى الظُّهْرَ. (ت,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): സൂര്യൻ മദ്ധ്യത്തിൽ നിന്നും നീങ്ങിയാൽ റസൂൽ(സ) ജംറകൾ എറിയുമായിരുന്നു. അതിൽ നിന്ന് വിരമിച്ചാൽ ളുഹർ നിസ്കരിക്കാമെന്ന രീതിയിലാണ് അവിടന്ന് എറിഞ്ഞിരുന്നത്. (തു,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 373, 373, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=134 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 428, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّهُ سَأَلَهُ رَجُلٌ مَتَى أَرْمِي الْجِمَارَ؟ قَالَ: إِذَا رَمَى إِمَامُكَ فَارْمِهْ، فَأَعَادَ عَلَيْهِ الْمَسْأَلَةَ، قَالَ: كُنَّا نَتَحَيَّنُ فَإِذَا زَالَتِ الشَّمْسُ رَمَيْنَا. (خ)', 'ഇബ്നുഉമർ(റ): എപ്പോഴാണ് ഞാൻ ജംറകളെ എറിയേണ്ടത്? എന്നൊരാൾ അദ്ദേഹത്തോട് ചോദിച്ചു: നിന്റെ ഇമാം എറിയുമ്പോൾ നീയും എറിഞ്ഞു കൊള്ളുക എന്ന് അദ്ദേഹം പറഞ്ഞു. അയാൾ ചോദ്യം ആവർത്തിച്ചു ഇബ്നുഉമർ(റ) പറഞ്ഞു: ഞങ്ങൾ സമയം പാർത്തിരുന്ന് സൂര്യൻ മദ്ധ്യാഹനത്തിൽ നിന്ന് തെറ്റുമ്പോഴാണ് കല്ലെറിയാറുണ്ടായിരുന്നത്. (ബു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 373, 373, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=134 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 429, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: رَمَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْجَمْرَةَ يَوْمَ النَّحْرِ ضُحًى، وَرَمَى بَعْدَ يَوْمِ النَّحْرِ إِذَا زَالَتِ الشَّمْسُ. (م,د,ت,ن,جه)', 'ജാബിർ(റ): ബലിയുടെ ദിവസം ളുഹാ സമയത്ത് നബിതങ്ങൾ(സ) ജംറകൾ എറിഞ്ഞു. ബലി ദിനത്തിന് ശേഷം സൂര്യൻ മദ്ധ്യത്തിൽ നിന്നും തെറ്റിയതിന് ശേഷമാണ് എറിഞ്ഞത്. (മു,ദ,തു,ന,ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 373, 373, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=134 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 430, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "الِاسْتِجْمَارُ تَوٌّ، وَرَمْيُ الْجِمَارِ تَوٌّ، وَالسَّعْيُ بَيْنَ الصَّفَا وَالْمَرْوَةِ تَوٌّ، وَالطَّوَافُ تَوٌّ، وَإِذَا اسْتَجْمَرَ أَحَدُكُمْ فَلْيَسْتَجْمِرْ بِتَوٍّ". (م)', 'ജാബിർ(റ): റസൂൽ(സ) പറഞ്ഞു: "കല്ലുകൊണ്ടുള്ള ശൗച്യം ഒറ്റയായിരിക്കണം. ജംറയെ എറിയലും ഒറ്റയായിരിക്കണം. സഫാ-മർവകളുടെ ഇടയിലുള്ള നടത്തവും ഒറ്റയായിരിക്കണം. കഅ്ബാപ്രദിക്ഷണവും ഒറ്റയായിരിക്കണം. കല്ലുകൊണ്ട് ശൗച്യം ചെയ്യുകയാണെങ്കിൽ അതും ഒറ്റയാക്കിക്കൊള്ളുക." (ബു)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['م']::text[], array['ബു']::text[], null, null, 373, 374, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=135 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 431, 'عَنِ ابْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: لَمَّا انْتَهَى إِلَى الْجَمْرَةِ الْكُبْرَى جَعَلَ الْبَيْتَ عَنْ يَسَارِهِ وَمِنًى عَنْ يَمِينِهِ، وَرَمَى الْجَمْرَةَ بِسَبْعِ حَصَيَاتٍ، وَقَالَ: هَكَذَا رَمَى الَّذِي أُنْزِلَتْ عَلَيْهِ سُورَةُ الْبَقَرَةِ. (ق,د,ت,ن)', 'ഇബ്നുമസ്ഊദ്(റ): ജംറത്തുൽ കുബ്റാ എറിഞ്ഞുകഴിഞ്ഞപ്പോൾ കഅബാലയത്തെ ഇടതുഭാഗത്തും മിനയെ വലതുവശത്തുമാക്കി. ഏഴ് കല്ലുകൾ കൊണ്ട് ജംറയെ എറിഞ്ഞു. എന്നിട്ടദ്ദേഹം പറഞ്ഞു: സൂറത്തുൽ ബഖറെ ഇറക്കപ്പെട്ടയാളും ഇപ്രകാരമാണ് എറിഞ്ഞത്. (ബു,മു,ദ,തു,ന)', 'ابْنِ مَسْعُودٍ', 'ഇബ്നുമസ്ഊദ്(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 374, 374, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=136 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 432, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا، وَسُئِلَ عَنْ شَيْءٍ مِنْ أَمْرِ الْجِمَارِ؟ قَالَ: مَا أَدْرِي، أَرَمَاهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِسِتٍّ أَوْ بِسَبْعٍ. (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): ജംറകൾ എറിയുന്ന കാര്യമദ്ദേഹത്തോട് ചോദിക്കപ്പെട്ടു. അദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ) ആറോ അതോ ഏഴോ കല്ലുകളുപയോഗിച്ചാണ് എറിഞ്ഞതെന്ന് എനിക്കറിയില്ല. (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 374, 374, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=136 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 433, 'عَنْ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا، عَنِ الْفَضْلِ بْنِ عَبَّاسٍ – رَضِيَ اللهُ عَنْهُم – قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِلنَّاسِ حِينَ دَفَعُوا عَشِيَّةَ عَرَفَةَ وَغَدَاةَ جَمْعٍ: "عَلَيْكُمْ بِالسَّكِينَةِ". وَهُوَ كَافٌّ نَاقَتَهُ، حَتَّى إِذَا دَخَلَ مِنًى فَهَبَطَ حِينَ هَبَطَ مُحَسِّرًا قَالَ: "عَلَيْكُمْ بِحَصَى الْخَذْفِ الَّذِي يُرْمَى بِهِ الْجَمْرَةُ". وَقَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُشِيرُ بِيَدِهِ: "كَمَا يَخْذِفُ الْإِنْسَانُ". (ن)', 'അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ): അറഫാ പ്രദോഷത്തിലും മുസ്ദലിഫയുടെ പ്രഭാതത്തിലും ജനങ്ങൾ പുറപ്പെടുമ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അച്ചടക്കം പാലിക്കുക." റസൂൽ(സ) തന്റെ ഒട്ടകത്തെ തെളിക്കുകയായിരുന്നു. മിനയിലെത്തി ഇറങ്ങി. റസൂൽ(സ) പറഞ്ഞു: "ജംറയിൽ എറിയാൻ നിങ്ങൾ ചെറിയ ഉരുളൻ കല്ലുകൾ ഉപയോഗിക്കുക." നിവേദകൻ പറയുന്നു. റസൂൽ(സ) കരം കൊണ്ട് ആംഗ്യം കാണിച്ചു കൊണ്ട് പറഞ്ഞു: "മനുഷ്യർ എറിയുന്നത് പോലെ." (ന)', 'عَبْدِ اللَّهِ بْنِ عَبَّاسٍ', 'അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 374, 374, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=137 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 434, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ غَدَاةَ الْعَقَبَةِ، وَهُوَ عَلَى نَاقَتِهِ: "الْقُطْ لِي حَصًى". فَلَقَطْتُ لَهُ سَبْعَ حَصَيَاتٍ، هُنَّ حَصَى الْخَذْفِ، فَجَعَلَ يَنْفُضُهُنَّ فِي كَفِّهِ وَيَقُولُ: "أَمْثَالَ هَؤُلَاءِ فَارْمُوا". ثُمَّ قَالَ: "يَا أَيُّهَا النَّاسُ، إِيَّاكُمْ وَالْغُلُوَّ فِي الدِّينِ، فَإِنَّهُ أَهْلَكَ مَنْ كَانَ قَبْلَكُمُ الْغُلُوُّ فِي الدِّينِ". (ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): അഖബയുടെ പ്രഭാതത്തിൽ ഒട്ടകപ്പുറത്തിരുന്ന് റസൂൽ(സ) പറഞ്ഞു: "എനിക്ക് കല്ല് എടുത്ത് തരു." അപ്പോൾ ഞാൻ റസൂൽ(സ)ക്ക് ഏഴു കല്ലുകൾ എടുത്തു കൊടുത്തു. അവ ചെറിയ ഉരുളൻ കല്ലുകളായിരുന്നു. റസൂൽ(സ) അത് കൈപത്തിയിലിട്ട് കുലുക്കിക്കൊണ്ട് പറഞ്ഞു: "ഇതു പോലോത്തത് കൊണ്ട് എറിയുക." ശേഷം റസൂൽ(സ) അരുളി: "ജനങ്ങളേ, നിങ്ങളേയും ദീനിൽ അതിരു കവിഞ്ഞ് പ്രവർത്തിക്കലിനെയും നിങ്ങൾ സൂക്ഷിക്കുക. കാരണം നിങ്ങളുടെ മുൻഗാമികളെ നശിപ്പിച്ചത് ദീനിൽ അതിരുകവിഞ്ഞ് പ്രവർത്തിച്ചതാണ്." (ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن','جه']::text[], array['ന','ജ']::text[], null, null, 374, 375, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=137 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 435, 'عَنِ الزُّهْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: بَلَغَنَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا رَمَى الْجَمْرَةَ الَّتِي تَلِي الْمَنْحَرَ مَنْحَرَ مِنًى رَمَاهَا بِسَبْعِ حَصَيَاتٍ، يُكَبِّرُ كُلَّمَا رَمَى بِحَصَاةٍ، ثُمَّ تَقَدَّمَ أَمَامَهَا فَوَقَفَ مُسْتَقْبِلَ الْقِبْلَةِ رَافِعًا يَدَيْهِ يَدْعُو يُطِيلُ الْوُقُوفَ، ثُمَّ يَأْتِي الْجَمْرَةَ الثَّانِيَةَ فَيَرْمِيهَا بِسَبْعِ حَصَيَاتٍ يُكَبِّرُ كُلَّمَا رَمَى بِحَصَاةٍ، ثُمَّ يَنْحَدِرُ ذَاتَ الشِّمَال فَيَقِفُ مُسْتَقْبِلَ الْبَيْتِ رَافِعًا يَدَيْهِ يَدْعُو، ثُمَّ يَأْتِي الْجَمْرَةَ الَّتِي عِنْدَ الْعَقَبَةِ فَيَرْمِيهَا بِسَبْعِ حَصَيَاتٍ وَلَا يَقِفُ عِنْدَهَا. قَالَ الزُّهْرِيُّ: سَمِعْتُ سَالِمًا يُحَدِّثُ بِهَذَا عَنْ أَبِيهِ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَكَانَ ابْنُ عُمَرَ يَفْعَلُهُ. (ن)', 'സുഹ്രി(റ): മിനയിലെ അറവിടത്തിനടുത്തുള്ള ജംറയിൽ റസൂൽ(സ) കല്ലെറിയുമ്പോൾ ഏഴു കല്ലുകൾ കൊണ്ട് എറിയാറുണ്ടെന്ന് ഞങ്ങൾക്ക് വിവരം കിട്ടി. എറിയുമ്പോഴൊക്കെയും തക്ബീർ ചൊല്ലും. ശേഷം ജംറയുടെ മുന്നിൽ ചെന്ന് ഖിബ്ലക്ക് മുന്നിട്ട് കൈ ഉയർത്തി ഏറെ നേരം നിന്നു പ്രാർത്ഥിച്ചു. പിന്നെ രണ്ടാം ജംറയുടെ അടുത്ത് ചെന്ന് ഏഴ് തവണ എറിയുകയും ഓരോ ഏറിനൊപ്പവും തക്ബീർ മുഴക്കുകയും ചെയ്തു. ശേഷം ഇടതു ഭാഗത്തേക്ക് നീങ്ങുകയും ഖിബ്ലക്ക് മുന്നിട്ട് കൈ ഉയർത്തി പ്രാർത്ഥിച്ചു. എന്നിട്ട് അഖബയുടെ സമീപമുള്ള ജംറയിൽ എറിഞ്ഞു. റസൂൽ(സ) അവിടെ നിന്നില്ല. സുഹ്രി(റ) പറയുന്നു: സാലിം(റ) ഈ ഹദീസ് തന്റെ പിതാവിലുടെ റസൂൽ(സ)യിൽ നിന്നും ഉദ്ധരിക്കുന്നത് ഞാൻ കേട്ടു. ഇബ്നുഉമർ(റ) ഇപ്രകാരം ചെയ്യുമായിരുന്നു. (ന)', 'الزُّهْرِيِّ', 'സുഹ്രി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 375, 375, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=137 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 436, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا أَنَّهُ كَانَ يَرْمِي الْجَمْرَةَ الدُّنْيَا بِسَبْعِ حَصَيَاتٍ، يُكَبِّرُ عَلَى إِثْرِ كُلِّ حَصَاةٍ، ثُمَّ يَتَقَدَّمُ حَتَّى يُسْهِلَ فَيَقُومَ مُسْتَقْبِلَ الْقِبْلَةِ، فَيَقُومُ طَوِيلًا وَيَدْعُو وَيَرْفَعُ يَدَيْهِ ثُمَّ يَرْمِي الْوُسْطَى، ثُمَّ يَأْخُذُ ذَاتَ الشِّمَالِ فَيَسْتَهِلُ وَيَقُومُ مُسْتَقْبِلَ الْقِبْلَةِ فَيَقُومُ طَوِيلًا، وَيَدْعُو وَيَرْفَعُ يَدَيْهِ، وَيَقُومُ طَوِيلًا ثُمَّ يَرْمِي جَمْرَةَ ذَاتِ الْعَقَبَةِ مِنْ بَطْنِ الْوَادِي، وَلَا يَقِفُ عِنْدَهَا، ثُمَّ يَنْصَرِفُ فَيَقُولُ: هَكَذَا رَأَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَفْعَلُهُ. (خ)', 'ഇബ്നുഉമർ(റ): അദ്ദേഹം ഏഴ് കല്ലുകൾ കൊണ്ട് ഏറ്റവും അടുത്ത ജംറയെ എറിയാറുണ്ടായിരുന്നു. ഓരോ കല്ലും എറിഞ്ഞ ഉടനെ തക്ബീർ ചൊല്ലും. പിന്നെ, താഴ്ന്നു കിടക്കുന്ന നിരപ്പുഭൂമിയിലേക്ക് നടന്ന് ഖിബ്ലക്ക് അഭിമുഖമായി നിൽക്കും. അവിടെ ദീർഘ നേരം നിൽക്കും, കൈയുയർത്തി പ്രാർത്ഥിക്കും, പിന്നീട് നടുവിലെ ജംറയിൽ കല്ലെറിയും, അനന്തരം ഇടതു വശത്തേക്ക് നടന്ന് താഴ്ന്ന നിരപ്പായ ഭൂമിയിലെത്തിയാൽ ഖിബ്ലക്ക് അഭിമുഖമായി നിൽക്കും. അവിടെയും ദീർഘ നേരം നിൽക്കും, കൈ രണ്ടുമുയർത്തി പ്രാർത്ഥിക്കും. പിന്നീട് മലഞ്ചെരുവിന്റെ താഴ്ഭാഗത്തു ചെന്ന് ജംറത്തുൽ അഖബായിൽ കല്ലെറിയും. അവിടെ നിൽക്കാതെ മടങ്ങിപ്പോകും. എന്നിട്ട് അദ്ദേഹം പറയും: ഇപ്രകാരമാണ് തിരുമേനി(സ) പ്രവർത്തിക്കുന്നത് ഞാൻ കണ്ടിട്ടുള്ളത്. (ബു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 375, 375, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=137 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 437, 'عَنْ أَسْمَاءَ رَضِيَ اللهُ عَنْهَا أَنَّهَا رَمَتِ الْجَمْرَةَ، قِيلَ لَهَا: إِنَّا رَمَيْنَا الْجَمْرَةَ بِلَيْلٍ؟ قَالَتْ: إِنَّا كُنَّا نَصْنَعُ هَذَا عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (ق,د,ن)', 'അസ്മാഅ്(റ): മഹതി ജംറകളിൽ എറിഞ്ഞു. അവരോട് ഞങ്ങളെല്ലാം രാത്രിയിലാണ് ജംറയിൽ എറിഞ്ഞതെന്ന് പറയപ്പെട്ടു. (അപ്രകാരം ചെയ്തതിനെക്കുറിച്ച് അഭിപ്രായമാരാഞ്ഞു). അസ്മാഅ്(റ) പറഞ്ഞു: നിശ്ചയം ഞങ്ങൾ റസൂൽ(സ)യുടെ കാലത്തിങ്ങനെയാണ് ചെയ്തിരുന്നത്. (ബു,മു,ന,ദ)', 'أَسْمَاءَ', 'അസ്മാഅ്(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ന','ദ']::text[], null, null, 375, 376, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=138 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 438, 'عَنْ عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ رَضِيَ اللهُ عَنْهُ قَالَ: قِيلَ لِعَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ: إِنَّ نَاسًا يَرْمُونَ الْجَمْرَةَ مِنْ فَوْقِ الْعَقَبَةِ، قَالَ: فَرَمَى عَبْدُ اللَّهِ مِنْ بَطْنِ الْوَادِي ثُمَّ قَالَ: مِنْ هَهُنَا– وَالَّذِي لَا إِلَهَ غَيْرُهُ – رَمَى الَّذِي أُنْزِلَتْ عَلَيْهِ سُورَةُ الْبَقَرَةِ. وَفِي رِوَايَةٍ: رَمَى عَبْدُ اللَّهِ الْجَمْرَةَ بِسَبْعِ حَصَيَاتٍ، جَعَلَ الْبَيْتَ عَنْ يَسَارِهِ وَعَرَفَةَ عَنْ يَمِينِهِ، وَقَالَ: هَهُنَا مَقَامُ الَّذِي أُنْزِلَتْ عَلَيْهِ سُورَةُ الْبَقَرَةِ. وَفِي رِوَايَةٍ: رَأَيْتُ ابْنَ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ رَمَى جَمْرَةَ الْعَقَبَةِ مِنْ بَطْنِ الْوَادِي ثُمَّ قَالَ: هَهُنَا وَالَّذِي لَا إِلَهَ غَيْرُهُ مَقَامُ الَّذِي أُنْزِلَتْ عَلَيْهِ سُورَةُ الْبَقَرَةِ. (خ,ن)', 'അബ്ദുർറഹ്മാനുബ്നു യസീദ്(റ): അബ്ദുല്ലാഹിബ്നു മസ്ഊദി(റ)നോട് ചോദിക്കപ്പെട്ടു. ചിലയാളുകൾ അഖബയുടെ മുകളിൽ നിന്ന് എറിയുന്നു? അബ്ദുർറഹ്മാൻ(റ) പറയുന്നു. അബ്ദുല്ലാ(റ) എറിഞ്ഞത് താഴ്വരയുടെ ഉൾഭാഗത്തു നിന്നാണ്. ശേഷം അദ്ദേഹം പറഞ്ഞു: അല്ലാഹുവാണെ സത്യം, അവനല്ലാതെ ആരാധ്യനില്ല. ഈ എറിഞ്ഞ സ്ഥലത്തേക്കാണ് അൽബഖറഃ സൂറത് ഇറക്കപ്പെട്ടത്.
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=4 and h.hadith_no=438), 1, 'وَفِي رِوَايَةٍ: رَمَى عَبْدُ اللَّهِ الْجَمْرَةَ بِسَبْعِ حَصَيَاتٍ، جَعَلَ الْبَيْتَ عَنْ يَسَارِهِ وَعَرَفَةَ عَنْ يَمِينِهِ، وَقَالَ: هَهُنَا مَقَامُ الَّذِي أُنْزِلَتْ عَلَيْهِ سُورَةُ الْبَقَرَةِ.', 'മറ്റൊരു നിവേദന്: അബ്ദുല്ലാ(റ) എറിഞ്ഞത് ഏഴ് കല്ലുകൾ കൊണ്ടാണ്. അദ്ദേഹം കഅബാലയത്തെ ഇടതു ഭാഗത്തും അറഫയെ വലതു വശത്തുമാക്കി പറയുകയുണ്ടായി: ഇവിടെയാണ് അൽബഖറഃ സൂറ ഇറങ്ങിയത്.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=4 and h.hadith_no=438), 2, 'وَفِي رِوَايَةٍ: رَأَيْتُ ابْنَ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ رَمَى جَمْرَةَ الْعَقَبَةِ مِنْ بَطْنِ الْوَادِي ثُمَّ قَالَ: هَهُنَا وَالَّذِي لَا إِلَهَ غَيْرُهُ مَقَامُ الَّذِي أُنْزِلَتْ عَلَيْهِ سُورَةُ الْبَقَرَةِ. (خ,ن)', 'മറ്റൊരു നിവേദന്: അബ്ദുർറഹ്മാൻ(റ): ഇബ്നു മസ്ഊദ്(റ) താഴ്വരയുടെ ഉൾഭാഗത്തു നിന്ന് ജംറകളെ എറിയുന്നതായി ഞാൻ കണ്ടു. പിന്നീട് അദ്ദേഹം പറഞ്ഞു: ആരാധ്യനായി അല്ലാഹു മാത്രം, അവനെ പിടിച്ച് ഞാൻ സത്യം ചെയ്യുന്നു. ഈ സ്ഥലത്താണ് സുറതുൽ ബഖറ ഇറക്കിയത്. (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 439, 'عَنِ الْأَعْمَشِ قَالَ: سَمِعْتُ الْحَجَّاجَ بْنَ يُوسُفَ يَقُولُ وَهُوَ يَخْطُبُ عَلَى الْمِنْبَرِ: أَلِّفُوا الْقُرْآنَ كَمَا أَلَّفَهُ جِبْرِيلُ: السُّورَةُ الَّتِي يُذْكَرُ فِيهَا الْبَقَرَةُ، وَالسُّورَةُ الَّتِي يُذْكَرُ فِيهَا النِّسَاءُ، وَالسُّورَةُ الَّتِي يُذْكَرُ فِيهَا آلُ عِمْرَانَ. قَالَ: فَلَقِيتُ إِبْرَاهِيمَ فَأَخْبَرْتُهُ بِقَوْلِهِ، فَسَبَّهُ وَقَالَ: حَدَّثَنِي عَبْدُ الرَّحْمَنِ بْنُ يَزِيدَ: أَنَّهُ كَانَ مَعَ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ فَأَتَى جَمْرَةَ الْعَقَبَةِ فَاسْتَبْطَنَ الْوَادِي، فَاسْتَعْرَضَهَا فَرَمَاهَا مِنْ بَطْنِ الْوَادِي بِسَبْعِ حَصَيَاتٍ يُكَبِّرُ مَعَ كُلِّ حَصَاةٍ، قَالَ: فَقُلْتُ: يَا أَبَا عَبْدِ الرَّحْمَنِ، إِنَّ النَّاسَ يَرْمُونَهَا مِنْ فَوْقِهَا؟ فَقَالَ: هَذَا – وَالَّذِي لَا إِلَهَ غَيْرُهُ – مَقَامُ الَّذِي أُنْزِلَتْ عَلَيْهِ سُورَةُ الْبَقَرَةِ. (ق,ت,ن,جه)', 'അഅ്മശ്(റ): ഹജ്ജാജുബ്നു യൂസുഫ് ഒരിക്കൽ പ്രസംഗിക്കുമ്പോൾ മിമ്പറിൽ വെച്ച് ഇങ്ങനെ പറയുന്നത് ഞാൻ കേട്ടു: നിങ്ങൾ ഖുർആൻ, ജിബ്രീൽ(അ) ക്രോഡീകരിച്ച പ്രകാരം ക്രോഡീകരിക്കുക. അതായത് പശുവിനെ സംബന്ധിച്ചു പറയുന്ന അധ്യായം, സ്ത്രീകളെ സംബന്ധിച്ച് പറയുന്ന അധ്യായം, ഇംറാൻ കുടുംബത്തെ സംബന്ധിച്ച് പറയുന്ന അധ്യായം (എന്നിങ്ങനെ പേര് പറഞ്ഞു കൊള്ളുക). നിവേദകൻ പറയുന്നു: അനന്തരം ഇബ്റാഹീമിനെ കണ്ടപ്പോൾ ഈ കാര്യം ഞാൻ അദ്ദേഹത്തോട് പറഞ്ഞു. അപ്പോൾ അദ്ദേഹം ഹജ്ജാജിനെ ആക്ഷേപിക്കുകയും ഇങ്ങനെ പറയുകയും ചെയ്തു: അബ്ദുല്ലാഹിബ്നു യസീദ്(റ) എന്നോട് ഇങ്ങനെ പറഞ്ഞിട്ടുണ്ട്: അദ്ദേഹം അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)വിന്റെ കൂടെ (ഹജ്ജ് ചെയ്യുക)യായിരുന്നു. ആ അവസരത്തിൽ അദ്ദേഹം ജംറതുൽ അഖബയുടെ അടുക്കൽ ചെല്ലുകയും അനന്തരം ആ താഴ്വരയുടെ അടിഭാഗത്ത് ചെന്ന് വിലങ്ങനെ നിൽക്കുകയും അങ്ങിനെ അതിന്റെ അടിഭാഗത്ത് നിന്ന് ഏഴ് കല്ലുകൊണ്ട് ജംറയിൽ എറിയുകയും ചെയ്തു. ഓരോ കല്ലെറിയുമ്പോഴും അദ്ദേഹം തക്ബീർ ചൊല്ലിയിരുന്നു. അബ്ദുല്ലാഹിബ്നു യസീദ് പറയുന്നു: അന്നേരം ഞാൻ പറഞ്ഞു: ഏ, അബൂഅബ്ദുർറഹ്മാൻ, ജനങ്ങൾ ഈ താഴ്വരയുടെ മുകളിൽ നിന്നാണ് കല്ലെറിയുന്നത്. ഉടനെ അദ്ദേഹം പറഞ്ഞു: ഏക ആരാധ്യനെത്തന്നെ സത്യം, സൂറതുൽ ബഖറ അവതരിക്കപ്പെട്ട റസൂൽ(സ), കല്ലെറിഞ്ഞ സ്ഥാനം ഇതാണ്." (ബു,മു,തു,ന,ജ)', 'الْأَعْمَشِ قَالَ', 'അഅ്മശ്(റ)', null, null, array['ق','ت','ن','جه']::text[], array['ബു','മു','തു','ന','ജ']::text[], null, null, 376, 377, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=139 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 440, 'عَنْ عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ قَالَ: لَمَّا أَتَى عَبْدُ اللَّهِ بْنُ مَسْعُودٍ –رَضِيَ اللهُ عَنْهُ – جَمْرَةَ الْعَقَبَةِ، اسْتَبْطَنَ الْوَادِيَ وَاسْتَقْبَلَ الْقِبْلَةَ، وَجَعَلَ يَرْمِي الْجَمْرَةَ عَلَى حَاجِبِهِ الْأَيْمَنِ، ثُمَّ رَمَى بِسَبْعِ حَصَيَاتٍ، يُكَبِّرُ مَعَ كُلِّ حَصَاةٍ، ثُمَّ قَالَ: وَاللَّهِ الَّذِي لَا إِلَهَ إِلَّا هُوَ، مِنْ هَاهُنَا رَمَى الَّذِي أُنْزِلَتْ عَلَيْهِ سُورَةُ الْبَقَرَةِ. قَالَ ترمذي هذا حَدِيثٌ حَسَنٌ صَحِيحٌ. (م,ت,ن,جه)', 'അബ്ദുർറഹ്മാനുബ്നു യസീദ്(റ): അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ) ജംറതുൽ അഖബഃയിൽ വന്നപ്പോൾ താഴ്വരയുടെ അടിഭാഗത്ത് ചെന്നു. ഖിബ്ലക്ക് മുന്നിട്ടു. എന്നിട്ട് വലതു ഭാഗം കൊണ്ട് ജംറയെ എറിയാൻ തുടങ്ങി. ശേഷം ഏഴു കല്ലുകൾ കൊണ്ട് എറിഞ്ഞു. ഓരോ ഏറിനൊപ്പവും അവർ തക്ബീർ ചൊല്ലി. എന്നിട്ട് പറഞ്ഞു: അവനല്ലാതെ ആരാധ്യനില്ലാത്ത അല്ലാഹുവേ, ''ബഖറഃ'' എന്ന അധ്യായം ആരുടെ മേൽ ആണോ ഇറക്കപ്പെട്ടത് അവർ എറിഞ്ഞത് ഇവിടെ നിന്നാണ്. ഹദീസ് ഹസനും സ്വഹീഹുമാകുന്നു. (മു,തു,ന,ജ)', 'عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ قَالَ', 'അബ്ദുർറഹ്മാനുബ്നു യസീദ്(റ)', null, null, array['م','ت','ن','جه']::text[], array['മു','തു','ന','ജ']::text[], null, null, 377, 377, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=139 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 441, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: رَأَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَرْمِي عَلَى رَاحِلَتِهِ يَوْمَ النَّحْرِ، وَيَقُولُ: "لِتَأْخُذُوا مَنَاسِكَكُمْ، فَإِنِّي لَا أَدْرِي لَعَلِّي لَا أَحُجُّ بَعْدَ حَجَّتِي هَذِهِ". (م)', 'ജാബിർ(റ): നഹ്റിന്റെ ദിനത്തിൽ റസൂൽ(സ) തങ്ങൾ വാഹനപ്പുറത്തിരുന്ന് എറിയുന്നത് ഞാൻ സ്വപ്നം കണ്ടു. "നിങ്ങളുടെ അമലുകളെ നിങ്ങൾ കൈകൊള്ളുക. നിശ്ചയം എന്റെ ഈ ഹജ്ജിന് ശേഷം ഞാൻ ഹജ്ജ് ചെയ്യാതിരിക്കുമോ എന്നെനിക്കറിയില്ല" എന്ന് റസൂൽ(സ) പറയുന്നുണ്ടായിരുന്നു. (മു)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 377, 377, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=140 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 442, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَمَى الْجَمْرَةَ عَلَى رَاحِلَتِهِ. (ت,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നിശ്ചയം റസൂൽ(സ) അവിടുത്തെ വാഹനപ്പുറത്തേറി ജംറകൾ എറിഞ്ഞു. (തു,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 377, 377, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=140 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 443, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّهُ كَانَ يَأْتِي الْجِمَارَ فِي الْأَيَّامِ الثَّلَاثَةِ بَعْدَ يَوْمِ النَّحْرِ مَاشِيًا، ذَاهِبًا وَرَاجِعًا، وَيُخْبِرُ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَفْعَلُ ذَلِكَ. (د)', 'ഇബ്നുഉമർ(റ): ബലിദിനത്തിന് ശേഷമുള്ള മൂന്ന് ദിനങ്ങളിൽ ജംറയിലേക്ക് പോകുമ്പോഴും മടങ്ങുമ്പോഴും നടന്നായിരുന്നു ഇബ്നുഉമർ(റ) പോയിരുന്നത്. റസൂൽ(സ) ഇപ്രകാരമാണ് ചെയ്തതെന്ന് അവർ അറിയിക്കുകയും ചെയ്തു. (ദ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 377, 377, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=141 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 444, 'عَنْ قُدَامَةَ بْنِ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُ قَالَ: رَأَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَرْمِي الْجِمَارَ عَلَى نَاقَةٍ، لَيْسَ ضَرْبٌ وَلَا طَرْدٌ، وَلَا إِلَيْكَ إِلَيْكَ. قَالَ ترمذي هذا حَدِيثٌ حَسَنٌ صَحِيحٌ. (ت,ن,جه)', 'ഖുദാമതുബ്നു അബ്ദില്ല(റ): റസൂൽ(സ) ഒട്ടകപ്പുറത്തിരുന്ന് കല്ലെറിയുന്നത് ഞാൻ കണ്ടു. റസൂൽ(സ) ആരരെയെങ്കിലും അടിക്കുകയോ ആട്ടുകയോ മാറിനിൽക്കാൻ ആവശ്യപ്പെടുകയോ ചെയ്തില്ല. (തു,ന,ജ)', 'قُدَامَةَ بْنِ عَبْدِ اللَّهِ', 'ഖുദാമതുബ്നു അബ്ദില്ല(റ)', null, null, array['ت','ن','جه']::text[], array['തു','ന','ജ']::text[], null, null, 378, 378, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=142 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 445, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّهُ رَمَى جَمْرَةَ الْعَقَبَةِ وَلَمْ يَقِفْ عِنْدَهَا، وَذَكَرَ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَعَلَ مِثْلَ ذَلِكَ. (خ,ن,جه)', 'ഇബ്നുഉമർ(റ): അദ്ദേഹം ജംറതുൽ അഖബയിൽ എറിഞ്ഞു. അതിന്റെ അടുത്ത് നിന്നില്ല. അദ്ദേഹം പറഞ്ഞു: തീർച്ചയായും റസൂൽ(സ) ഇപ്രകാരം ചെയ്തിരുന്നു. (ബു,ന,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ','ن','جه']::text[], array['ബു','ന','ജ']::text[], null, null, 378, 378, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=143 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 446, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَقَفَ يَوْمَ النَّحْرِ بَيْنَ الْجَمَرَاتِ فِي الْحَجَّةِ الَّتِي حَجَّ، فَقَالَ: "أَيُّ يَوْمٍ هَذَا". قَالُوا: يَوْمُ النَّحْرِ، قَالَ: "هَذَا يَوْمُ الْحَجِّ الْأَكْبَرِ". (د,جه)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) ഹജ്ജ് ചെയ്ത വർഷം ഹജ്ജ്വേളയിൽ ബലി ദിവസം അവിടന്ന് ജംറകൾക്കിടയിൽ നിന്ന് ചോദിച്ചു: "ഈ ദിവസമേതാണ്?" അനുയായികൾ പറഞ്ഞു: ഇത് ബലിയുടെ ദിവസമാണ്. റസൂൽ(സ) പറഞ്ഞു: "ഇത് ഹജ്ജുൽ അക്ബറിന്റെ ദിവസമാകുന്നു." (ദ,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 378, 378, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=143 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 447, 'عَنْ عَاصِمِ بْنِ عَدِيٍّ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَرْخَصَ لِلرِّعَاءِ أَنْ يَرْمُوا يَوْمًا وَيَدْعُوا يَوْمًا. وَفِي رِوَايَةٍ: قَالَ: رَخَّصَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِرِعَاءِ الْإِبِلِ فِي الْبَيْتُوتَةِ: أَنْ يَرْمُوا يَوْمَ النَّحْرِ، ثُمَّ يَجْمَعُوا رَمْيَ يَوْمَيْنِ بَعْدَ يَوْمِ النَّحْرِ، فَيَرْمُونَهُ فِي أَحَدِهِمَا. حَسَنٌ صَحِيحٌ. (ق,ت)', 'ആസിമുബ്നു അദിയ്യ്(റ): ഒരു ദിവസം എറിയാമെന്നും, അടുത്ത ദിവസം എറിയാതിരിക്കാമെന്നും റസൂൽ(സ) ആട്ടിടയർക്ക് ഇളവ് ചെയ്തു കൊടുത്തു.
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=4 and h.hadith_no=447), 1, 'وَفِي رِوَايَةٍ: قَالَ: رَخَّصَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِرِعَاءِ الْإِبِلِ فِي الْبَيْتُوتَةِ: أَنْ يَرْمُوا يَوْمَ النَّحْرِ، ثُمَّ يَجْمَعُوا رَمْيَ يَوْمَيْنِ بَعْدَ يَوْمِ النَّحْرِ، فَيَرْمُونَهُ فِي أَحَدِهِمَا. حَسَنٌ صَحِيحٌ. (ق,ت)', 'മറ്റൊരു നിവേദനം: രാപ്പാർക്കുന്നതിൽ ഒട്ടകത്തെ മേക്കുന്നവർക്ക് റസൂൽ(സ) ഇളവ് ചെയ്തു കൊടുത്തു. ബലി ദിനത്തിൽ എറിയുക. ബലിദിനത്തിന് ശേഷമുള്ള രണ്ട് ദിവസത്തെ ഏറുകൾ ഒരുമിച്ച് രണ്ടാലൊരു ദിവസം എറിയുക. (ബു,മു,തു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 448, 'عَنِ ابْنِ عَبَّاسٍ عَنِ الْفَضْلِ بْنِ عَبَّاسٍ، رَضِيَ اللهُ عَنْهُمْ: أَنَّهُ كَانَ رَدِيفَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَلَمْ يَزَلْ يُلَبِّي حَتَّى رَمَى الْجَمْرَةَ. (ن)', 'ഫള്ലുബ്നുഅബ്ബാസ്(റ): അദ്ദേഹം നബി(സ)യുടെ സഹയാത്രികനായിരുന്നു. അന്നേരം ജംറകളെ എറിയുവോളം നബിതങ്ങൾ തൽബിയത് ചൊല്ലിക്കൊണ്ടിരുന്നു. (ന)', 'ابْنِ عَبَّاسٍ عَنِ الْفَضْلِ بْنِ عَبَّاسٍ،', 'ഫള്ലുബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 378, 379, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=145 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 449, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: إِذَا رَمَى الْجَمْرَةَ فَقَدْ حَلَّ لَهُ كُلُّ شَيْءٍ إِلَّا النِّسَاءَ. قِيلَ: وَالطِّيبُ؟ قَالَ: أَمَّا أَنَا فَقَدْ رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَتَضَمَّخُ بِالْمِسْكِ، أَفَطِيبٌ هُوَ؟. (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): ജംറയിൽ എറിഞ്ഞു കഴിഞ്ഞാൽ സ്ത്രീയല്ലാത്തതെല്ലാം അവന് അനുവദനീയമാണ്. ചോദിക്കപ്പെട്ടു: സുഗന്ധമോ? ഇബ്നുഅബ്ബാസ്(റ) പറഞ്ഞു: തിരുമേനി(സ) മിസ്ക് പുരട്ടുന്നത് ഞാൻ കണ്ടു. അതു സുഗന്ധമാണോ? (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 379, 379, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=146 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 450, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِذَا رَمَى أَحَدُكُمْ جَمْرَةَ الْعَقَبَةِ فَقَدْ حَلَّ لَهُ كُلُّ شَيْءٍ إِلَّا النِّسَاءَ". قَالَ أبو داود: هَذَا حَدِيثٌ ضَعِيفٌ. (د)', 'ആഇശ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളോരോരുത്തരും ജംറത്തുൽ അഖബ എറിഞ്ഞു കഴിഞ്ഞാൽ സ്ത്രീകളൊഴിച്ച് മറ്റെല്ലാം അവന്ന് അനുവദനീയമായി." (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 379, 379, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=146 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 451, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قُلْنَا: يَا رَسُولَ اللَّهِ، أَلَا نَبْنِي لَكَ بَيْتًا بِمِنًى؟ قَالَ: "لَا، مِنًى مُنَاخُ مَنْ سَبَقَ". قَالَ ترمذي هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ. (ت)', 'ആഇശ(റ): ഞങ്ങൾ റസുലുല്ലാഹി(സ)യോട് ചോദിച്ചു: അങ്ങേക്ക് ഞങ്ങൾ മിനായിൽ ഒരു വീടുണ്ടാക്കട്ടെയോ? തിരുമേനി(സ) പറഞ്ഞു: "വേണ്ട, മിന അവിടെ ആദ്യം എത്തുന്നവർക്ക് ഇറങ്ങാനുള്ള ഇടമാണ്." (തു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 379, 379, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=147 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 452, 'عَنْ رَافِعِ بْنِ عَمْرٍو الْمُزَنِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَخْطُبُ النَّاسَ بِمِنًى حِينَ ارْتَفَعَ الضُّحَى عَلَى بَغْلَةٍ شَهْبَاءَ، وَعَلِيٌّ رَضِيَ اللهُ عَنْهُ يُعَبِّرُ عَنْهُ، وَالنَّاسُ بَيْنَ قَاعِدٍ وَقَائِمٍ. (د)', 'റാഫിഉബ്നു അംറുൽ മുസ്നി(റ): മിനായിൽ ളുഹാ സമയത്ത് വെള്ള കോവർ കഴുതപ്പുറത്തിരുന്ന് റസൂൽ(സ) പ്രസംഗിക്കുന്നത് ഞാൻ കണ്ടു. അലി(റ) റസൂൽ(സ)യുടെ പ്രഭാഷണം വ്യാഖ്യാനിക്കുന്നുണ്ടായിരുന്നു. അന്നേരം ജനങ്ങളിൽ ഇരിക്കുന്നവരും നിൽക്കുന്നവരുമുണ്ടായിരുന്നു. (ദ)', 'رَافِعِ بْنِ عَمْرٍو الْمُزَنِيِّ', 'റാഫിഉബ്നു അംറുൽ മുസ്നി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 379, 379, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=148 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 453, 'عَنْ أَبِي أُمَامَةَ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ خُطْبَةَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِمِنًى يَوْمَ النَّحْرِ. (د)', 'അബൂ ഉമാമത്ത്(റ): ബലിയുടെ ദിവസം മിനായിൽ വെച്ച് ഞാൻ റസൂൽ(സ)യുടെ പ്രസംഗം ശ്രവിച്ചു. (ദ)', 'أَبِي أُمَامَةَ', 'അബൂ ഉമാമത്ത്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 379, 379, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=148 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 454, 'عَنْ جُبَيْرِ بْنِ مُطْعِمٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالْخَيْفِ مِنْ مِنًى، فَقَالَ: "نَضَّرَ اللَّهُ امْرَأً سَمِعَ مَقَالَتِي فَبَلَّغَهَا، فَرُبَّ حَامِلِ فِقْهٍ غَيْرُ فَقِيهٍ، وَرُبَّ حَامِلِ فِقْهٍ إِلَى مَنْ هُوَ أَفْقَهُ مِنْهُ. ثَلَاثٌ لَا يُغِلُّ عَلَيْهِنَّ قَلْبُ مُؤْمِنٍ: إِخْلَاصُ الْعَمَلِ لِلَّهِ، وَالنَّصِيحَةُ لِوُلَاةِ الْمُسْلِمِينَ، وَلُزُومُ جَمَاعَتِهِمْ فَإِنَّ دَعْوَتَهُمْ، تُحِيطُ مِنْ وَرَائِهِمْ". [ز: في سنده مدلس رواه بالعنعنة] (جه)', 'ജുബൈറുബ്നു മുത്ഇം(റ): റസൂൽ(സ) മിനയിലെ ഖൈഫിൽ എഴുന്നേറ്റു നിന്നു. എന്നിട്ട് പറഞ്ഞു: "എന്റെ പ്രസംഗം കേട്ട് അത് മറ്റുള്ളവർക്ക് എത്തിച്ചു കൊടുക്കുന്നവനെ അല്ലാഹു പ്രകാശിപ്പിക്കട്ടെ. ജ്ഞാനിയാവാതെ വിജ്ഞാനത്തെ ചുമക്കുന്നവർ എത്രയാണ്. തന്നേക്കാൾ അറിവുള്ളവന് വിജ്ഞാനം പറഞ്ഞുകൊടുക്കുന്നവർ എത്രയാണ്. മൂന്ന് കാര്യങ്ങളുണ്ട്, വിശ്വാസിയുടെ ഹൃദയം അതിൽ ഒരിക്കലും വഞ്ചിക്കുകയില്ല: അല്ലാഹുവിനുള്ള കർമ്മങ്ങളിൽ ആത്മാർത്ഥത, മുസ്ലിം ഭരണാധിപരെ ഉപദേശിക്കൽ, മുസ്ലിം സമുഹത്തോട് ചേർന്നു നിൽക്കൽ; കാരണം അവരുടെ പ്രാർത്ഥന പിന്നിൽ നിന്ന് അവരെ സംരക്ഷിക്കും. (സനദ് മുദല്ലസാണ്.) (ജ)', 'جُبَيْرِ بْنِ مُطْعِمٍ', 'ജുബൈറുബ്നു മുത്ഇം(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده مدلس رواه بالعنعنة', null, 379, 380, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=148 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 455, 'عَنِ الزُّهْرِيِّ رَضِيَ اللهُ عَنْهُ : أَنَّ عُثْمَانَ رَضِيَ اللهُ عَنْهُ إِنَّمَا صَلَّى بِمِنًى أَرْبَعًا لِأَنَّهُ أَجْمَعَ عَلَى الْإِقَامَةِ بَعْدَ الْحَجِّ. (د)', 'സുഹ്രീ(റ): ഉസ്മാൻ(റ) മിനായിൽ വെച്ചു നാല് റക്അത് നിസ്കരിച്ചു. കാരണം ഹജ്ജിന് ശേഷം ഒരു ഇഖാമത്ത് കൊണ്ട് അദ്ദേഹം ജംആക്കിയിരുന്നു. (ദ)', 'الزُّهْرِيِّ', 'സുഹ്രീ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 380, 380, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=149 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 456, 'عَنْ إِبْرَاهِيمَ رَضِيَ اللهُ عَنْهُ قَالَ: إِنَّ عُثْمَانَ رَضِيَ اللهُ عَنْهُ صَلَّى أَرْبَعًا لِأَنَّهُ اتَّخَذَهَا وَطَنًا. (د)', 'ഇബ്റാഹീം(റ): ഉസ്മാൻ(റ) നാല് റക്അത്ത് നിസ്കരിച്ചു. കാരണം മക്കയെ തന്റെ സ്വന്തം നാടായി ഉസ്മാൻ(റ) പരിഗണിച്ചു. (ദ)', 'إِبْرَاهِيمَ', 'ഇബ്റാഹീം(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 380, 380, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=149 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 457, 'عَنِ الزُّهْرِيِّ رَضِيَ اللهُ عَنْهُ ، أَنَّ عُثْمَانَ بْنَ عَفَّانَ رَضِيَ اللهُ عَنْهُ أَتَمَّ الصَّلَاةَ بِمِنًى مِنْ أَجْلِ الْأَعْرَابِ، لِأَنَّهُمْ كَثُرُوا عَامَئِذٍ، فَصَلَّى بِالنَّاسِ أَرْبَعًا لِيُعَلِّمَهُمْ أَنَّ الصَّلَاةَ أَرْبَعٌ. (د)', 'സുഹ്രി(റ): അഅ്റാബികൾ ധാരാളമായി ഉണ്ടായതു കൊണ്ടാണ് ഉസ്മാൻ(റ) മിനായിൽ വെച്ച് നാല് റക്അത്ത് പൂർത്തായായി നിസ്കരിച്ചത്. നിസ്കാരം നാല് റക്അത്താണെന്ന് അറിയിക്കാനാണ് ഉസ്മാൻ(റ) നാല് റക്അത്ത് നിസ്കരിച്ചത്. (ദ)', 'الزُّهْرِيِّ', 'സുഹ്രി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 380, 380, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=149 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 458, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: صَلَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الظُّهْرَ يَوْمَ التَّرْوِيَةِ وَالْفَجْرَ يَوْمَ عَرَفَةَ بِمِنًى. (د,ت)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) തർവിയത്തിന്റെ ദിനത്തിൽ ദുഹ്റും അറഫാ ദിനത്തിൽ സുബ്ഹിയും മിനയിൽ വെച്ച് നിസ്കരിച്ചു. (ദ,തു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 380, 380, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=149 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 459, 'عَنْ عَبْدِ الْعَزِيزِ بْنِ رَفِيعٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: سَأَلْتُ أَنَسَ بْنَ مَالِكٍ رَضِيَ اللهُ عَنْهُ: أَخْبِرْنِي بِشَيْءٍ عَقَلْتَهُ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَيْنَ صَلَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الظُّهْرَ يَوْمَ التَّرْوِيَةِ؟ فَقَالَ: بِمِنًى، قُلْتُ: فَأَيْنَ صَلَّى الْعَصْرَ يَوْمَ النَّفْرِ؟ قَالَ: بِالْأَبْطَحِ، ثُمَّ قَالَ: افْعَلْ كَمَا يَفْعَلُ أُمَرَاؤُكَ. (ق,د,ت,ن)', 'അബ്ദുൽ അസീസുബ്നു റഫീഅ്(റ): ഞാൻ അനസുബ്നുമാലിക്(റ)വിനോട് ചോദിച്ചു. ''റസൂൽ(സ)യെക്കുറിച്ച് താങ്കൾ മനസ്സിലാക്കിയ കാര്യം എനിക്കൊന്നു പറഞ്ഞു തുരൂ. തർവിയത്തിന്റെ ദിനത്തിൽ റസൂൽ(സ) ളുഹ്ർ നിസ്കരിച്ചത് എവിടെയാണ്? അനസുബ്നു മാലിക്(റ) പറഞ്ഞു: മിനയിൽ വെച്ച്. ഞാൻ ചോദിച്ചു: നഫ്റിന്റെ ദിനത്തിൽ അസ്ർ നിസ്കരിച്ചത് എവിടെ വെച്ചാണ്? അനസുബ്നു മാലിക്(റ) പറഞ്ഞു: ''അബ്ത്വാഹിൽ വെച്ച്''. പിന്നീട് അനസുബ്നു മാലിക്(റ) പറഞ്ഞു: താങ്കളുടെ നേതാക്കൾ ചെയ്യുന്ന പോലെ താങ്കളും ചെയ്യുക. (ബു,മു,ദ,തു,ന)', 'عَبْدِ الْعَزِيزِ بْنِ رَفِيعٍ', 'അബ്ദുൽ അസീസുബ്നു റഫീഅ്(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 380, 381, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=149 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 460, 'عَنْ حَارِثَةَ بْنِ وَهْبٍ رَضِيَ اللهُ عَنْهُ قَالَ: صَلَّيْتُ مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِمِنًى – آمَنَ مَا كَانَ النَّاسُ وَأَكْثَرَهُ – رَكْعَتَيْنِ. قَالَ ترمذي هذا حَدِيثٌ حَسَنٌ صَحِيحٌ. (د,ت,ن)', 'ഹാരിസതുബ്നു വഹബ്(റ): മിനായിൽ വെച്ച് റസൂൽ(സ)യുടെ കൂടെ ഞാൻ രണ്ട് റക്അത്ത് നിസ്കരിച്ചു. അതിൽ ഒരുപാട് ആളുകൾ തടിച്ചു കൂടിയിരുന്നു. (ദ,തു,ന)', 'حَارِثَةَ بْنِ وَهْبٍ', 'ഹാരിസതുബ്നു വഹബ്(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 381, 381, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=150 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 461, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَلَقَ رَأْسَهُ فِي حَجَّةِ الْوَدَاعِ. (ق,د,ت)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): റസൂൽ(സ) ഹജ്ജത്തുൽ വദാഇന്റെ ദിവസം തല മുണ്ഡനം ചെയ്തു. (ബു,മു,ദ,തു)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['ق','د','ت']::text[], array['ബു','മു','ദ','തു']::text[], null, null, 381, 381, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=151 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 462, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَمَى جَمْرَةَ الْعَقَبَةِ يَوْمَ النَّحْرِ، ثُمَّ رَجَعَ إِلَى مَنْزِلِهِ بِمِنًى فَدَعَا بِذِبْحٍ فَذُبِحَ، ثُمَّ دَعَا بِالْحَلَّاقِ فَأَخَذَ بِشِقِّ رَأْسِهِ الْأَيْمَنِ فَحَلَقَهُ، فَجَعَلَ يَقْسِمُ بَيْنَ مَنْ يَلِيهِ الشَّعْرَةَ وَالشَّعْرَتَيْنِ، ثُمَّ أَخَذَ بِشِقِّ رَأْسِهِ الْأَيْسَرِ فَحَلَقَهُ ثُمَّ قَالَ: "هَهُنَا أَبُو طَلْحَةَ". فَدَفَعَهُ إِلَى أَبِي طَلْحَةَ. وَفِي رِوَايَةٍ: قَالَ لِلْحَالِقِ: "ابْدَأْ بِشِقِّي الْأَيْمَنِ فَاحْلِقْهُ". (ق,د,ت)', 'അനസ്ബിൻ മാലിക്(റ): നിശ്ചയം റസൂൽ(സ) ബലിയുടെ ദിനത്തിൽ ജംറത്തുൽ അഖബ എറിഞ്ഞു. പിന്നീട് മിനയിലുള്ള കൂടാരത്തിലേക്ക് മടങ്ങുകയും, അറവുമൃഗത്തെ കൊണ്ടുവരാനാവശ്യപ്പെടുകയും അതിനെ അറുക്കുകയും ചെയ്തു. ശേഷം ക്ഷുരകനെ വിളിക്കുകയും വലതു വശത്തെ മുടി കളയുകയും അടുത്തുള്ളവർക്ക് ഒന്നും രണ്ടും മുടികൾ നൽകുകയും ചെയ്തു. പിന്നീട് ഇടതുവശത്തെ മുടി കളഞ്ഞു. എന്നിട്ട് പറഞ്ഞു: "അബൂത്വൽഹ, ഇവിടെ വരു." ആ മുടികൾ അദ്ദേഹത്തിന് നൽകി.
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=4 and h.hadith_no=462), 1, 'وَفِي رِوَايَةٍ: قَالَ لِلْحَالِقِ: "ابْدَأْ بِشِقِّي الْأَيْمَنِ فَاحْلِقْهُ". (ق,د,ت)', 'മറ്റൊരു നിവേദന്: ക്ഷുരകനോട് നബി(സ) പറഞ്ഞു: "വലതുഭാഗത്ത് നിന്ന് തുടങ്ങുക, എന്നിട്ട് വടിക്കുക." (ബു,മു,ദ,തു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 463, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَيْسَ عَلَى النِّسَاءِ حَلْقٌ – وفي رواية: الحَلْقُ – إِنَّمَا عَلَى النِّسَاءِ التَّقْصِيرُ". (د)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "സ്ത്രീകൾ തല മുണ്ഡനം ചെയ്യരുത്. നിശ്ചയം, സ്ത്രീകൾ മുടി വെട്ടുകയാണ് വേണ്ടത്." (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 381, 381, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=151 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=4 and h.hadith_no=463), 1, 'وَفِي رِوَايَةٍ: الحَلْقُ – إِنَّمَا عَلَى النِّسَاءِ التَّقْصِيرُ". (د)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 464, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "اللَّهُمَّ ارْحَمِ الْمُحَلِّقِينَ". قَالُوا: وَالْمُقَصِّرِينَ يَا رَسُولَ اللَّهِ؟ قَالَ: "اللَّهُمَّ ارْحَمِ الْمُحَلِّقِينَ". قَالُوا: وَالْمُقَصِّرِينَ يَا رَسُولَ اللَّهِ؟ قَالَ: "وَالْمُقَصِّرِينَ". (خ)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവെ, മുടി കളയുന്നവർക്ക് നീ കരുണ ചെയ്യേണമേ." ജനങ്ങൾ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, മുടി വെട്ടുന്നവരോ? റസൂൽ(സ) പറഞ്ഞു: "മുടി കളയുന്നവർക്ക് നീ കരുണ ചെയ്യണേ." അവർ ചോദിച്ചു: മുടി വെട്ടുന്നവരും, റസൂലേ? റസൂൽ(സ) പറഞ്ഞു: "മുടി വെട്ടുന്നവർക്കും നീ കരുണ ചെയ്യണേ." (ബു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 381, 382, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=151 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 465, 'عَنْ مُعَاوِيَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَصَّرْتُ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِمِشْقَصٍ. (خ)', 'മുആവിയ(റ): ഞാൻ റസൂൽ(സ)തങ്ങൾക്ക് ഒരു കത്രിക കൊണ്ട് മുടി വെട്ടിക്കൊടുത്തു. (ബു)', 'مُعَاوِيَةَ', 'മുആവിയ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 382, 382, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=151 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 466, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "اللَّهُمَّ اغْفِرْ لِلْمُحَلِّقِينَ". قَالُوا: يَا رَسُولَ اللَّهِ وَلِلْمُقَصِّرِينَ. قَالَ: "اللَّهُمَّ اغْفِرْ لِلْمُحَلِّقِينَ". قَالُوا: يَا رَسُولَ اللَّهِ وَلِلْمُقَصِّرِينَ. قَالَ: "اللَّهُمَّ اغْفِرْ لِلْمُحَلِّقِينَ". قَالُوا: يَا رَسُولَ اللَّهِ وَلِلْمُقَصِّرِينَ. قَالَ: "وَلِلْمُقَصِّرِينَ". (م)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പ്രാർത്ഥിച്ചു: "അല്ലാഹുവേ, മുടി കളയുന്നവർക്ക് നീ പൊറുത്ത് കൊടുക്കണേ". അവർ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, മുടി വെട്ടുന്നവർക്ക് വേണ്ടിയും. റസൂൽ(സ) "അല്ലാഹുവേ, മുടി കളയുന്നവർക്ക് നീ പൊറുത്ത് കൊടുക്കുക." അവർ പറഞ്ഞു: റസൂലേ, മുടി മുറിക്കുന്നവർക്ക് വേണ്ടിയും. റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവേ, മുടി കളയുന്നവർക്ക് നീ പൊറുത്തു കൊടുക്കുക." അവർ പറഞ്ഞു: മുടി വെട്ടുന്നവർക്ക് വേണ്ടിയും. റസൂൽ(സ) തങ്ങൾ പറഞ്ഞു: "മുടി വെട്ടുന്നവർക്കും." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 382, 382, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=151 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 467, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قِيلَ: يَا رَسُولَ اللَّهِ، لِمَ ظَاهَرْتَ لِلْمُحَلِّقِينَ ثَلَاثًا، وَلِلْمُقَصِّرِينَ وَاحِدَةً؟ قَالَ: "إِنَّهُمْ لَمْ يَشُكُّوا". (جه)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) ചോദിക്കപ്പെട്ടു: പ്രവാചകരേ, അങ്ങ് എന്തുകൊണ്ടാണ് തല മുണ്ഡനം ചെയ്തവർക്ക് മൂന്ന് തവണ പ്രാർത്ഥിച്ചത്. മുടി വെട്ടിയവർക്ക് ഒരു തവണയും. റസൂൽ(സ) പറഞ്ഞു: "കാരണം, നിശ്ചയം അവർ സംശയിച്ചില്ല." (ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 382, 382, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=151 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 468, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: لَمْ يُرَخِّصِ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِأَحَدٍ يَبِيتُ بِمَكَّةَ، إِلَّا لِلْعَبَّاسِ، مِنْ أَجْلِ السِّقَايَةِ. (جه)', 'ഇബ്നുഅബ്ബാസ്(റ): മക്കയിൽ രാത്രി താമസിക്കാൻ (മിനയിൽ രാപാർക്കേണ്ട വേളയിൽ) അബ്ബാസ്(റ)വില്ലാതെ മറ്റൊരാൾക്കും നബി(സ) ഇളവ് അനുവദിച്ചിട്ടില്ല. അബ്ബാസ്(റ)വിന് ഇളവു ലഭിച്ചത് ഹജ്ജാജിമാർക്കും മറ്റു യാത്രക്കാർക്കും വെള്ളം കുടിപ്പിക്കുന്ന കാര്യമുണ്ടായത് കൊണ്ടാണ്. (ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 382, 382, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=152 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 469, 'عَنْ عَبْدِ الرَّحْمَنِ بْنِ فَرُّوخٍ رَضِيَ اللهُ عَنْهُ: يَسْأَلُ ابْنَ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: إِنَّا نَتَبَايَعُ بِأَمْوَالِ النَّاسِ، فَيَأْتِي أَحَدُنَا مَكَّةَ، فَيَبِيتُ عَلَى الْمَالِ؟ فَقَالَ: أَمَّا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَبَاتَ بِمِنًى وَظَلَّ. (د)', 'അബ്ദുർറഹ്മാനുബ്നു ഫർറൂഖ്(റ): അദ്ദേഹം ഇബ്നുഉമർ(റ)വിനോട് ചോദിച്ചു: ഞങ്ങൾ ജനങ്ങളുടെ സ്വത്തുകൾ വിൽക്കുന്നുണ്ട്. അതുകൊണ്ട് ഞങ്ങളിൽ ഒരാൾ മക്കയിൽ പോയി സ്വത്തിന്റെ കൂടെ രാത്രി കഴിച്ചു കൂടട്ടെ? ഇബ്നുഉമർ(റ) പറഞ്ഞു: റസൂൽ(സ) രാത്രിയും പകലും മിനയിൽ കഴിച്ചു കൂട്ടി. (ദ)', 'عَبْدِ الرَّحْمَنِ بْنِ فَرُّوخٍ', 'അബ്ദുർറഹ്മാനുബ്നു ഫർറൂഖ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 382, 382, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=152 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 470, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: اسْتَأْذَنَ الْعَبَّاسُ بْنُ عَبْدِالْمُطَّلِبِ رَضِيَ اللهُ عَنْهُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يَبِيتَ بِمَكَّةَ لَيَالِيَ مِنًى مِنْ أَجْلِ سِقَايَتِهِ فَأَذِنَ لَهُ. (ق)', 'ഇബ്നുഉമർ(റ): വെള്ളം കുടിപ്പിക്കേണ്ട ആവശ്യത്തിന് മിനയിൽ രാത്രി താമസിക്കേണ്ട ദിവസം മക്കയിൽ നിൽക്കാൻ അബ്ബാസുബ്നു അബ്ദുൽമുത്വലിബ് റസൂൽ(സ)യോട് സമ്മതം തേടിയതിനാൽ റസൂൽ(സ) അനുമതി നൽകി. (ബു,മു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 383, 383, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=152 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 471, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَقَامَ فِي عُمْرَةِ الْقَضَاءِ ثَلَاثًا. (د)', 'ഇബ്നുഅബ്ബാസ്(റ): വീണ്ടെടുപ്പ് ഉംറ വേളയിൽ മൂന്ന് ദിവസം റസൂൽ(സ) (മക്കയിൽ) താമസിച്ചു. (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 383, 383, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=153 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 472, 'عَنْ عَبْدِ الرَّحْمَنِ بْنِ حُمَيْدٍ قَالَ: سَمِعْتُ عُمَرَ بْنَ عَبْدِ الْعَزِيزِ يَقُولُ لِجُلَسَائِهِ: مَا سَمِعْتُمْ فِي سُكْنَى مَكَّةَ؟ فَقَالَ السَّائِبُ بْنُ يَزِيدَ: سَمِعْتُ الْعَلَاءَ – أَوْ قَالَ: الْعَلَاءَ بْنَ الْحَضْرَمِيِّ – قَالَ: قَال رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "يُقِيمُ الْمُهَاجِرُ بِمَكَّةَ بَعْدَ قَضَاءِ نُسُكِهِ ثَلَاثًا". (م)', 'അബ്ദുർറഹ്മാനുബ്നു ഹുമൈദ്: (മക്കയിൽ നിന്ന് ഹിജ്റ പോയവർ) മക്കയിൽ വന്ന് താമസിക്കുന്നതിനെക്കുറിച്ച് റസൂൽ(സ) വല്ലതും പറയുന്നത് നിങ്ങളാരെങ്കിലും കേട്ടിട്ടുണ്ടോ? എന്ന് ഉമർ ബിൻ അബ്ദുൽ അസീസ് തന്റെ സദസ്യരോട് ചോദിക്കുന്നത് ഞാൻ കേട്ടു. അപ്പോൾ സാഇബുബ്നു യസീദ് പറഞ്ഞു: അലാഅ്(റ) ഇപ്രകാരം പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്. തിരുമേനി(സ) പറഞ്ഞു: "മക്കയിൽ നിന്ന് ഹിജ്റ പോയവന് ഹജ്ജ് കർമ്മങ്ങളെല്ലാം കഴിഞ്ഞ ശേഷം മൂന്ന് ദിവസം മക്കയിൽ താമസിക്കാം." (മു)', 'عَبْدِ الرَّحْمَنِ بْنِ حُمَيْدٍ قَالَ', 'അബ്ദുർറഹ്മാനുബ്നു ഹുമൈദ്', null, null, array['م']::text[], array['മു']::text[], null, null, 383, 383, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=153 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 473, 'عَنْ عَلْقَمَةَ بْنِ نَضْلَةَ الْكِنَانِي قَالَ: تُوُفِّيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَبُو بَكْرٍ وَعُمَرُ، وَمَا تُدْعَى رِبَاعُ مَكَّةَ إِلَّا السَّوَائِبَ، مَنِ احْتَاجَ سَكَنَ، وَمَنِ اسْتَغْنَى أَسْكَنَ. [ز: مرسل] (جه)', 'അൽഖമതുബ്നു നള്ലതൽ കിനാനി(റ): പ്രവാചകർ(സ)യും അബൂബക്കർ(റ)വും ഉമർ(റ)വും വഫാതായി. മക്കയിലെ വീടുകളെ സവാഇബ്(ഉടമകളില്ലാത്ത ആർക്കും ഉപയോഗിക്കാവുന്ന വീടുകൾ) എന്നായിരുന്നു വിളിച്ചിരുന്നത്. ആവശ്യമുള്ളവർക്ക് താമസിക്കാം. ആവശ്യമില്ലാത്തവർക്ക് മറ്റുള്ളവരെ താമസിപ്പിക്കാം. (ഹദീസ് മുർസലാകുന്നു.) (ജ)', 'عَلْقَمَةَ بْنِ نَضْلَةَ الْكِنَانِي قَالَ', 'അൽഖമതുബ്നു നള്ലതൽ കിനാനി(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: مرسل', null, 383, 383, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=154 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 474, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جَاءَ إِلَى السِّقَايَةِ فَاسْتَسْقَى فَقَالَ الْعَبَّاسُ: يَا فَضْلُ اذْهَبْ إِلَى أُمِّكَ فَأْتِ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِشَرَابٍ مِنْ عِنْدِهَا، فَقَالَ: "اسْقِنِي". قَالَ: يَا رَسُولَ اللَّهِ إِنَّهُمْ يَجْعَلُونَ أَيْدِيَهُمْ فِيهِ، قَالَ: "اسْقِنِي". فَشَرِبَ مِنْهُ، ثُمَّ أَتَى زَمْزَمَ وَهُمْ يَسْقُونَ وَيَعْمَلُونَ فِيهَا فَقَالَ: "اعْمَلُوا فَإِنَّكُمْ عَلَى عَمَلٍ صَالِحٍ". ثُمَّ قَالَ: "لَوْلَا أَنْ تُغْلَبُوا لَنَزَلْتُ حَتَّى أَضَعَ الْحَبْلَ عَلَى هَذِهِ". يَعْنِي عَاتِقَهُ وَأَشَارَ إِلَى عَاتِقِهِ. (خ)', 'ഇബ്നുഅബ്ബാസ്(റ): ജലം ദാനം ചെയ്യുന്ന കേന്ദ്രത്തിലേക്കു ചെന്ന് തിരുമേനി(സ) വെള്ളം ആവശ്യപ്പെട്ടു. അപ്പോൾ അബ്ബാസ്(റ) ഫള്ൽ(റ)വിനോട് പറഞ്ഞു: ഫള്ലേ, നീ ഉമ്മയുടെ അടുത്തു ചെന്ന് തിരുമേനി(സ)ക്ക് കുടിക്കാൻ കുറച്ചു വെള്ളം വാങ്ങിക്കൊണ്ടുവാ. തിരുമേനി(സ) പറഞ്ഞു: "എനിക്ക് വെള്ളം നൽകുക." അബ്ബാസ്(റ) പറഞ്ഞു: ദൈവ ദുതരെ, ആ വെള്ളത്തിൽ ആളുകൾ കയ്യിടാറുണ്ട്. തിരുമേനി(സ) വീണ്ടും ആവശ്യപ്പെട്ടു: "എനിക്ക് വെള്ളം നൽകു." അവിടന്ന് ആ വെള്ളം തന്നെ കുടിച്ചു. തിരുമേനി(സ) സംസമിന്റെയടുത്തേക്കു ചെന്നു. ജനങ്ങൾ അവിടെ ജലദാനശ്രമത്തിൽ ഏർപ്പെട്ടിരിക്കുകയായിരുന്നു. തിരുമേനി(സ) അവരോട് പറഞ്ഞു: "നിങ്ങൾ ചെയ്യുക, കാരണം ഒരു സൽക്കർമ്മത്തിലാണ് നിങ്ങളുള്ളത്." തുടർന്ന് അരുളി: "നിങ്ങൾക്ക് ഈ ജോലി നഷ്ടപ്പെടുമോ എന്ന ഭയമില്ലായിരുന്നെങ്കിൽ ഞാനും നിങ്ങളോടൊപ്പം ഇറങ്ങി വെള്ളം വലിക്കുന്ന കയർ ഇതാ ഇവിടെ -തിരുമേനി(സ) തന്റെ പിരടിയിലേക്ക് ചുണ്ടിക്കാണിച്ചു- വെക്കുമായിരുന്നു." (ബു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 383, 384, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=155 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 475, 'عَنْ مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرٍ قَالَ: كُنْتُ عِنْدَ ابْنِ عَبَّاسٍ– رَضِيَ اللهُ عَنْهُمَا – جَالِسًا، فَجَاءَهُ رَجُلٌ، فَقَالَ: مِنْ أَيْنَ جِئْتَ؟ قَالَ: مِنْ زَمْزَمَ. قَالَ: فَشَرِبْتَ مِنْهَا كَمَا يَنْبَغِي؟ قَالَ: وَكَيْفَ؟ قَالَ: إِذَا شَرِبْتَ مِنْهَا فَاسْتَقْبِلِ الْقِبْلَةَ، وَاذْكُرِ اسْمَ اللَّهِ، وَتَنَفَّسْ ثَلَاثًا، وَتَضَلَّعْ مِنْهَا، فَإِذَا فَرَغْتَ فَاحْمَدِ اللَّهَ عَزَّ وَجَلَّ، فَإِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ آيَةَ مَا بَيْنَنَا وَبَيْنَ الْمُنَافِقِينَ إِنَّهُمْ لَا يَتَضَلَّعُونَ مِنْ زَمْزَمَ". (جه)', 'മുഹമ്മദുബ്നു അബ്ദിർറഹ്മാനുബ്നു അബീബക്കർ(റ): ഞാൻ ഇബ്നുഅബ്ബാസ്(റ)വിന്റെ കൂടെ ഇരിക്കുകയായിരുന്നു. അപ്പോൾ ഒരാൾ ഇബ്നുഅബ്ബാസ്(റ)വിന്റെ അടുത്ത് വന്നു. ഇബ്നുഅബ്ബാസ്(റ) ചോദിച്ചു: നിങ്ങൾ എവിടെ നിന്നാണ് വരുന്നത്. ആഗതൻ പറഞ്ഞു: സംസമിന്റെ അടുത്ത് നിന്ന്. ഇബ്നുഅബ്ബാസ്(റ) പറഞ്ഞു: കുടിക്കേണ്ട പോലെ നീ കുടിച്ചുവോ? ആഗതൻ ചോദിച്ചു: അതെങ്ങനെയാണ്. ഇബ്നുഅബ്ബാസ്(റ) പറഞ്ഞു: സംസം കുടിക്കുമ്പോൾ ഖിബ്ലക്ക് മുന്നിടുകയും അല്ലാഹുവിന്റെ നാമം ഓർക്കുകയും ചെയ്യുക. മൂന്ന് തവണ നിശ്വസിക്കുകയും, വയർ നിറയെ കുടിക്കുകയും ചെയ്യുക. കുടി കഴിഞ്ഞാൽ നിങ്ങൾ അല്ലാഹുവിനെ സ്തുതിക്കുക. കാരണം തിരുമേനി(സ) പറഞ്ഞു: "നമ്മുടെയും കപട വിശ്വാസികളുടെയും ഇടയിലുള്ള തെളിവ് അവർ സംസം വയർ നിറയെ കുടിക്കുകയില്ല." എന്നതാകുന്നു." (ജ)', 'مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرٍ قَالَ', 'മുഹമ്മദുബ്നു അബ്ദിർറഹ്മാനുബ്നു അബീബക്കർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 384, 384, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=155 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 476, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: سَقَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ زَمْزَمَ فَشَرِبَ وَهُوَ قَائِمٌ، قَالَ عَاصِمٌ فَحَلَفَ عِكْرِمَةُ مَا كَانَ يَوْمَئِذٍ إِلَّا عَلَى بَعِيرٍ. (خ)', 'ഇബ്നുഅബ്ബാസ്(റ): ഞാൻ റസൂൽ(സ)ക്ക് സംസം വെള്ളം കുടിക്കാൻ നൽകിയപ്പോൾ അവിടന്ന് നിന്നുകൊണ്ട് കുടിച്ചു. ആസിം(റ) പറയുന്നു: ആ ദിവസം തിരുമേനി(സ) ഒട്ടകപ്പുറത്തു നിന്ന് തീരെ ഇറങ്ങിയിട്ടില്ലെന്ന് ഇക്രിമ(റ) സത്യം ചെയ്യുന്നു. (ബു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 384, 384, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=156 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 477, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّهَا كَانَتْ تَحْمِلُ مِنْ مَاءِ زَمْزَمَ، وَتُخْبِرُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَحْمِلُهُ. قَالَ ترمذي هَذَا حَدِيثٌ حَسَنٌ غَرِيبٌ. (ت)', 'ആഇശ(റ): അവർ സംസം വെള്ളം കൊണ്ടു പോകുമായിരുന്നു. റസൂൽ(സ) സംസം കൊണ്ടുപോകാറുണ്ടെന്ന് അവർ അറിയിക്കുകയും ചെയ്തു. (തു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 384, 385, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=157 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 478, 'عَنْ بَكْرِ بْنِ عَبْدِ اللَّهِ الْمُزَنِيِّ قَالَ: كُنْتُ جَالِسًا مَعَ ابْنِ عَبَّاسٍ عِنْدَ الكَعْبَةِ، فَأَتَاهُ أَعْرَابِيٌّ فَقَالَ: مَا لِي أَرَى بَنِي عَمِّكُمْ يَسْقُونَ الْعَسَلَ وَاللَّبَنَ، وَأَنْتُمْ تَسْقُونَ النَّبِيذَ؟ أَمِنْ حَاجَةٍ بِكُمْ، أَمْ مِنْ بُخْلٍ؟ فَقَالَ ابْنُ عَبَّاسٍ: الْحَمْدُ لِلَّهِ، مَا بِنَا مِنْ حَاجَةٍ، وَلَا بُخْلٍ، قَدِمَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى رَاحِلَتِهِ وَخَلْفَهُ أُسَامَةُ، فَاسْتَسْقَى فَأَتَيْنَاهُ بِإِنَاءٍ مِنْ نَبِيذٍ، فَشَرِبَ، وَسَقَى فَضْلَهُ أُسَامَةَ وَقَالَ: "أَحْسَنْتُمْ وَأَجْمَلْتُمْ، كَذَا فَاصْنَعُوا". فَلَا نُرِيدُ تَغْيِيرَ مَا أَمَرَ بِهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (م)', 'ബക്റുബ്നു അബ്ദുല്ല(റ): ഞാൻ ഇബ്നുഅബ്ബാസ്(റ)വിനോടു കൂടെ കഅ്ബയുടെ അരികിൽ ഇരിക്കുകയായിരുന്നു. അപ്പോൾ ഒരു അഅ്റാബി വന്ന് ഇബ്നുഅബ്ബാസ്(റ)വിനോട് ചോദിച്ചു: നിങ്ങളുടെ പിതൃസഹോദര സന്തതികൾ പാലും തേനും കുടിക്കുന്നു. നിങ്ങളാണെങ്കിൽ ഈത്തപ്പഴച്ചാറാണ് കുടിക്കുന്നത്. ലുബ്ധത കൊണ്ടാണോ അതല്ലെങ്കിൽ നിങ്ങൾക്ക് പ്രത്യേകമായ വല്ല ആവശ്യവും കൊണ്ടാണോ നിങ്ങൾ ഇങ്ങനെ ചെയ്യുന്നത? ഇബ്നുഅബ്ബാസ്(റ) പറഞ്ഞു: അല്ലാഹുവിന് സ്തുതി. ഞങ്ങൾക്ക് പ്രത്യേക ആവശ്യവുമില്ല, പിശുക്കുമില്ല. റസൂൽ(സ) തന്റെ വാഹനത്തിൽ മക്കയിൽ വന്നു. പിന്നിൽ ഉസാമയുണ്ടായിരുന്നു. റസൂൽ(സ) കുടിക്കാൻ വെള്ളം ആവശ്യപ്പെട്ടു. അപ്പോൾ ഞങ്ങൾ ഈത്തപ്പഴച്ചാർ കൊണ്ടു വന്നു. റസൂൽ(സ) അതു കുടിച്ചു. ബാക്കിയുള്ളത് ഉസാമക്ക് കൊടുക്കുകയും ചെയ്തു. എന്നിട്ട് റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ ചെയ്തത് നന്നായിട്ടുണ്ട്, ഭംഗിയുമായിട്ടുണ്ട്. ഇതുപോലെ ഇനിയും ചെയ്യുക." തിരുമേനി(സ) കൽപ്പിച്ചതിൽ മാറ്റം വരുത്താൻ ഞങ്ങളാഗ്രഹിക്കുന്നില്ല. (മു)', 'بَكْرِ بْنِ عَبْدِ اللَّهِ الْمُزَنِيِّ قَالَ', 'ബക്റുബ്നു അബ്ദുല്ല(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 385, 385, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=158 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 479, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ اشْتَرَى هَدْيَهُ مِنْ قُدَيْدٍ. (ت)', 'ഇബ്നുഉമർ(റ): നിശ്ചയം നബിതങ്ങൾ അവിടുത്തെ ഹദ്‌യ ഖുദൈദിൽ നിന്നുമാണ് മേടിച്ചത്. (തു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 385, 385, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=159 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 480, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَهْدَى عَامَ الْحُدَيْبِيَةِ فِي هَدَايَا رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جَمَلًا كَانَ لِأَبِي جَهْلٍ، فِي رَأْسِهِ بُرَةُ فِضَّةٍ – وفي رواية: بُرَةٌ مِنْ ذَهَبٍ – يَغِيظُ بِذَلِكَ الْمُشْرِكِينَ. (د)', 'ഇബ്നുഅബ്ബാസ്(റ): ഹുദൈബിയ്യയുടെ വർഷം, തിരുമേനി(സ) തന്റെ ബലി മൃഗങ്ങളുടെ കൂട്ടത്തിൽ, ബഹുദൈവവിശ്വാസികളെ ദേഷ്യം പിടിപ്പിക്കാൻ, അബൂ ജഹ്ലിന്റെ ഒട്ടകത്തെയും ഉൾപ്പെടുത്തി. അതിന്റെ തലയിൽ വെള്ളിയുടെ -ഒരു നിവേദനപ്രകാരം: സ്വർണ്ണത്തിന്റെ- മൂക്കുകുത്തിയുണ്ടായിരുന്നു. (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ന']::text[], null, null, 385, 385, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=159 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=4 and h.hadith_no=480), 1, 'وَفِي رِوَايَةٍ: بُرَةٌ مِنْ ذَهَبٍ – يَغِيظُ بِذَلِكَ الْمُشْرِكِينَ. (د)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 481, 'عَنْ سَلَمَةَ بْنِ الْأَكْوَعِ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ فِي بُدْنِهِ جَمَلٌ. [ز: في إسناده ضعيف] (جه)', 'സലമത്തുബ്നു അക്‌വഅ്(റ): തീർച്ചയായും നബി(സ)യുടെ അറവ് നടത്തപ്പെടാനുള്ള മൃഗങ്ങളുടെ കൂട്ടത്തിൽ ഒട്ടകമുണ്ടായിരുന്നു. (ഇതിന്റെ സനദിൽ ബലഹീനതയുണ്ട്.) (ജ)', 'سَلَمَةَ بْنِ الْأَكْوَعِ', 'സലമത്തുബ്നു അക്‌വഅ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', null, 385, 386, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=159 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 482, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّهُ بَلَغَهَا أَنَّ ابْنَ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا يَقُولُ: مَنْ أَهْدَى هَدْيًا حَرُمَ عَلَيْهِ مَا يَحْرُمُ عَلَى الْحَاجِّ حَتَّى يُنْحَرَ هَدْيُهُ، فَقَالَتْ عَائِشَةُ: لَيْسَ كَمَا قَالَ ابْنُ عَبَّاسٍ أَنَا فَتَلْتُ قَلَائِدَ هَدْيِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِيَدَيَّ ثُمَّ قَلَّدَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِيَدَيْهِ ثُمَّ بَعَث بِهَا مَعَ أَبِي فَلَمْ يَحْرُمْ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ شَيْءٌ أَحَلَّهُ اللَّهُ لَهُ حَتَّى نُحِرَ الْهَدْيُ. (خ)', 'ആഇശ(റ): വല്ലവനും ഒരു ബലിമൃഗത്തെ കൊടുത്തയച്ചാൽ അതിനെ ബലിയറുക്കുന്നത് വരെ ഹാജിമാർക്ക് ഹറാമായതെല്ലാം ആ കൊടുത്തയച്ചവനും ഹറാമാകുമെന്ന് ഇബ്നുഅബ്ബാസ്(റ) പറഞ്ഞത് മഹതി അറിഞ്ഞു. അപ്പോൾ മഹതി പറഞ്ഞു: ഇബ്നുഅബ്ബാസ്(റ) പറയുന്നത് പോലെയല്ല കാര്യം. തിരുമേനി(സ)യുടെ ബലിമൃങ്ങളുടെ കഴുത്തിൽ കെട്ടാനുള്ള കയർ ഞാനെന്റെ കൈകൊണ്ടാണ് പിരിച്ചത്. തിരുമേനി(സ) തന്റെ കൈകൾ കൊണ്ടത് കെട്ടി. എന്റെ പിതാവിന്റെ വശം അത് കൊടുത്തയച്ചു. ആ ബലിയറുക്കുന്നത് വരെയുള്ള കാലത്ത് അല്ലാഹു അനുവദിച്ച യാതൊരു കാര്യവും തിരുമേനിക്ക് ഹറാമായിരുന്നില്ല. (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 386, 386, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=160 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 483, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَهْدَى غَنَمًا وَفِي رِوَايَةٍ عَنْهَا أَنَّهُ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَلَّدَ الْغَنَمَ وَأَقَامَ فِي أَهْلِهِ حَلَالًا. (خ)', 'ആഇശ(റ): തിരുമേനി(സ) ബലിയറുക്കാൻ വേണ്ടി മൃഗങ്ങളെ കൊടുത്തയച്ചു. ആഇശ(റ)യിൽ നിന്നു തന്നെ മറ്റൊരു നിവേദനത്തിൽ: തിരുമേനി(സ) ഒരാടിന്റെ കഴുത്തിൽ ബലിയടയാളം കെട്ടിക്കൊടുത്തയച്ചു. ഇഹ്റാമിന്റെ യാതൊരു ബാധ്യതകളുമില്ലാതെ തന്നെ അവിടന്ന് സ്വകുടുംബത്തിൽ താമസിച്ചു. (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 386, 386, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=160 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=4 and h.hadith_no=483), 1, 'وَفِي رِوَايَةٍ عَنْهَا أَنَّهُ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَلَّدَ الْغَنَمَ وَأَقَامَ فِي أَهْلِهِ حَلَالًا. (خ)', 'മറ്റൊരു നിവേദനത്തിൽ: തിരുമേനി(സ) ഒരാടിന്റെ കഴുത്തിൽ ബലിയടയാളം കെട്ടിക്കൊടുത്തയച്ചു. ഇഹ്റാമിന്റെ യാതൊരു ബാധ്യതകളുമില്ലാതെ തന്നെ അവിടന്ന് സ്വകുടുംബത്തിൽ താമസിച്ചു. (ബു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 484, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ: أَنَّهُمْ كَانُوا إِذَا كَانُوا حَاضِرِينَ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالْمَدِينَةِ بَعَث بِالْهَدْيِ، فَمَنْ شَاءَ أَحْرَمَ وَمَنْ شَاءَ تَرَكَ. (ن)', 'ജാബിർ(റ): അവർ റസൂൽ(സ)യോടൊപ്പം മദീനയിൽ ഹാജറാവുമ്പോൾ ഹദ്‌യ കൊടുത്തയക്കും. ഉദ്ധേശിക്കുന്നവർ ഇഹ്റാം ചെയ്യും. ഉദ്ധേശിക്കുന്നവർ ഉപേക്ഷിക്കും. (ന)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 386, 386, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=160 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 485, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: صَلَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الظُّهْرَ بِذِي الْحُلَيْفَةِ، ثُمَّ دَعَا بِنَاقَتِهِ فَأَشْعَرَهَا فِي صَفْحَةِ سَنَامِهَا الْأَيْمَنِ وَسَلَتَ الدَّمَ، وَقَلَّدَهَا نَعْلَيْنِ، ثُمَّ رَكِبَ رَاحِلَتَهُ، فَلَمَّا اسْتَوَتْ بِهِ عَلَى الْبَيْدَاءِ أَهَلَّ بِالْحَجِّ. (م)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) (ഹജ്ജതുൽ വദാഇന് പോയപ്പോൾ) ദുൽഹുലൈഫയിൽ വെച്ച് ളുഹ്ർ നമസ്കരിച്ചു. ശേഷം അവിടത്തെ ഒട്ടകത്തെ കൊണ്ടുവരാൻ ആവശ്യപ്പെടുകയും എന്നിട്ട് അതിന്റെ പുഞ്ഞയുടെ വലഭാഗത്ത് മുറിയാക്കി അൽപ്പം രക്തം ഒലിപ്പിക്കുകയും രണ്ട് ചെരുപ്പ് അതിന്റെ കഴുത്തിൽ കെട്ടിത്തൂക്കുകയും ചെയ്തു. ശേഷം അവിടന്ന് വാഹനപ്പുറത്ത് കയറുകയും, വാഹനം തിരുമേനി(സ)യെയും കൊണ്ട് ബൈദാഅ് എന്ന സ്ഥലത്ത് വെച്ച് ശരിക്കും നിവർന്ന് നിന്നപ്പോൾ അവിടന്ന് ഹജ്ജിന് ഉച്ചത്തിൽ തൽബിയത്ത് ചൊല്ലുകയും ചെയ്തു. (മു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 386, 387, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=161 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 486, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: فَتَلْتُ قَلَائِدَهَا مِنْ عِهْنٍ كَانَ عِنْدِي. (خ)', 'ആഇശ(റ): ബലി മൃഗങ്ങളുടെ കഴുത്തിൽ കെട്ടാനുള്ള കയർ എന്റെ കയ്യിലുണ്ടായിരുന്ന രോമം കൊണ്ട് ഞാൻ തന്നെയാണ് പിരിച്ചത്. (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 387, 387, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=162 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 487, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كُنْتُ أَفْتِلُ قَلَائِدَ هَدْيِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كُلَّهَا غَنَمًا، ثُمَّ لَا يُحْرِمُ. قَالَ ترمذي هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ. (ت)', 'ആഇശ(റ): ഞാൻ റസൂൽ(സ)യുടെ ബലിമൃഗത്തിന്റെ കഴുത്തിൽ കെട്ടാനുള്ള കയർ പിരിക്കുമായിരുന്നു. അവ മുഴുവൻ ആടുകളായിരുന്നു. പിന്നീട് റസൂൽ(സ) ഇഹ്റാം ചെയ്തില്ല. (തു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 387, 387, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=162 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 488, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا أَنَّهَا قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُهْدِي مِنَ الْمَدِينَةِ، فَأَفْتِلُ قَلَائِدَ هَدْيِهِ، ثُمَّ لَا يَجْتَنِبُ شَيْئًا مِمَّا يَجْتَنِبُهُ الْمُحْرِمُ. (ن)', 'ആഇശ(റ): തിരുമേനി(സ) മദീനയിൽനിന്ന് ബലിമൃഗത്തെ കൊടുത്തയക്കുമായിരുന്നു. ഞാൻ തിരുമേനിയുടെ ബലിമൃഗത്തിന്റെ കയർ പിരിച്ചുണ്ടാക്കും. മുഹ്രിം വെടിയുന്നതൊന്നും തിരുമേനി(സ) വെടിഞ്ഞിരുന്നില്ല. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 387, 387, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=162 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 489, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: أَهْدَى عُمَرُ بْنُ الْخَطَّاب نَجِيبًا، فَأَعْطَى بِهَا ثَلَاث مِائَةِ دِينَار، فَأَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ، إِنِّي أَهْدَيْتُ نَجِيبًا، فَأَعْطَيْتُ بِهَا ثَلَاث مِائَةِ دِينَار، أَفَأَبِيعُهَا وَأَشْتَرِي بِثَمَنِهَا بُدْنًا؟ قَالَ: "لَا، انْحَرْهَا إِيَّاهَا". قَالَ أَبُو داود: هَذَا كَانَ لِأَنَّهُ أَشْعَرَهَا. (د)', 'ഇബ്നുഉമർ(റ): ഉമർ(റ) ബലിക്ക് വേണ്ടി മുന്തിയ ഇനം കുതിരയെ കൊണ്ടു പോയി. അതിന് മുന്നൂറ് ദീനാർ വാഗ്ദാനം ചെയ്യപ്പെട്ടു. അപ്പോൾ ഉമർ(റ) റസൂൽ(സ)യുടെ അടുക്കൽ ചെന്നു ചോദിച്ചു: റസൂലേ, ഞാൻ മുന്തിയ ഇനം ഒട്ടകത്തെ ബലിക്കായി കൊണ്ടുവന്നിരിക്കുന്നു. എനിക്ക് അതിന് മുന്നൂറ് ദീനാർ വാഗ്ദാനം ചെയ്യപ്പെട്ടിരിക്കുന്നു. ഞാനത് വിറ്റ് ആ വിലക്ക് ഒരു ഒട്ടകത്തെ വാങ്ങട്ടെയോ? റസൂൽ(സ) പറഞ്ഞു: "വേണ്ട. അതിനെ തന്നെ അറുക്കുക." അബൂദാവൂദ്(റ) പറയുന്നു: ഇങ്ങനെ പറഞ്ഞ് ഉമർ(റ) അതിന് അടയാളമിട്ടത് കൊണ്ടാണ്. (ദ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 387, 387, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=163 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 490, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَأَى رَجُلًا يَسُوقُ بَدَنَةً، فَقَالَ: "ارْكَبْهَا". فَقَالَ: يَا رَسُولَ اللَّهِ، إِنَّهَا بَدَنَةٌ؟ فَقَالَ: "ارْكَبْهَا وَيْلَكَ" فِي الثَّانِيَةِ أَوْ فِي الثَّالِثَةِ. (م)', 'അബൂഹുറൈറ(റ): നബിതങ്ങൾ(സ) ഒരു ഒട്ടകത്തെ തെളിച്ചു കൊണ്ടുവരുന്നയാളെ കണ്ടു. അദ്ധേഹത്തോട് പറഞ്ഞു: "അതിന്റെ പുറത്ത് കയറി യാത്രചെയ്യുക." അദ്ദേഹം പറഞ്ഞു: ഇത് ബലിമൃഗമാണ്. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "താങ്കളെന്തു മോശമാണ് ചെയ്യുന്നത്. അതിന്റെ പുറത്ത് കയറി യാത്ര ചെയ്യുക." രണ്ടാമത്തെയോ, മൂന്നാമത്തെയോ പ്രാവശ്യത്തിലോ ആണ് ഇപ്രകാരം പറഞ്ഞത്. (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 387, 388, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=164 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 491, 'عَنْ أَبِي الزُّبَيْرِ قَالَ: سَمِعْتُ جَابِرَ بْنَ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُمَا سُئِلَ عَنْ رُكُوبِ الْهَدْيِ، فَقَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "ارْكَبْهَا بِالْمَعْرُوفِ إِذَا أُلْجِئْتَ إِلَيْهَا، حَتَّى تَجِدَ ظَهْرًا". (م)', 'അബുസ്സുബൈർ(റ): ബലിമൃഗത്തിന്റെ സവാരി ചെയ്യുന്നത് സംബന്ധിച്ച് ജാബിറുബ്നു അബ്ദുല്ല(റ)യോട് ചോദിക്കുന്നത് ഞാൻ കേട്ടു. അന്നേരം അദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ) ഇങ്ങനെ പറയുന്നത് ഞാൻ കേട്ടിരിക്കുന്നു: "നിനക്ക് ആവശ്യം നേരിട്ടാൽ, മറ്റൊരു വാഹനം ലഭിക്കുന്നത് വരെ, നല്ല നിലക്ക് (അതിനെ വിഷമിപ്പിക്കാത്ത വിധത്തിൽ) നീ അതിനെ സവാരി ചെയ്തു കൊള്ളുക." (മു)', 'أَبِي الزُّبَيْرِ قَالَ', 'അബുസ്സുബൈർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 388, 388, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=164 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 492, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُرَّ عَلَيْهِ بِبَدَنَةٍ، فَقَالَ: "ارْكَبْهَا". قَالَ: إِنَّهَا بَدَنَةٌ. قَالَ: "ارْكَبْهَا". قَالَ: فَرَأَيْتُهُ رَاكِبَهَا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فِي عُنُقِهَا نَعْلٌ. (ق,جه)', 'അനസുബ്നു മാലിക്(റ): നബി(സ)യുടെ അരികിലൂടെ ഒരു ഒട്ടകവുമായി ഒരാൾ നടന്ന് പോകുകയുണ്ടായി. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അതിന്മേൽ യാത്ര ചെയ്യുക." അയാൾ പറഞ്ഞു. ഇത് ബലിമൃഗമാണ് റസൂൽ(സ) പറഞ്ഞു: "അതിന്മേൽ യാത്ര ചെയ്യു." അനസുബ്നു മാലിക്(റ) പറയുന്നു: അയാളതിന്റെ പുറത്ത് കയറി റസൂൽ(സ)യോടൊപ്പം യാത്ര ചെയ്യുന്നത് ഞാൻ കണ്ടു. അതിന്റെ പിരടിയിൽ ചെരുപ്പുമുണ്ടായിരുന്നു. (ബു,മു,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ق','جه']::text[], array['ബു','മു','ജ']::text[], null, null, 388, 388, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=164 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 493, 'عَنْ نَاجِيَةَ الْخُزَاعِيِّ رَضِيَ اللهُ عَنْهُ – صَاحِبِ بُدْنِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ – قَالَ: قُلْتُ: يَا رَسُولَ اللَّهِ، كَيْفَ أَصْنَعُ بِمَا عَطِبَ مِنَ الْبُدْنِ؟ قَالَ: "انْحَرْهَا، ثُمَّ اغْمِسْ نَعْلَهَا فِي دَمِهَا، ثُمَّ خَلِّ بَيْنَ النَّاسِ وَبَيْنَهَا، فَيَأْكُلُوهَا". قَالَ ترمذي هذا حَدِيثٌ حَسَنٌ صَحِيحٌ. (د,ت,ن,جه)', 'നാജിയതുൽ ഖുസാഈ(റ): അദ്ദേഹം റസൂൽ(സ)യുടെ ഒട്ടകക്കാരനായിരുന്നു. അദ്ദേഹം പറയുന്നു: ഞാൻ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, ഒട്ടകത്തിന് മരണം സംഭവിക്കാവുന്ന വല്ലതും സംഭവിച്ചാൽ ഞാനെന്താണ് ചെയ്യേണ്ടത്? റസൂൽ(സ) അരുളി: "നീ അതിനെ അറുക്കുക. എന്നിട്ട് അതിന്റെ ലാട ആ രക്തത്തിൽ കഴുകുക. ശേഷം അത് ജനങ്ങൾക്ക് വിട്ടു കൊടുക്കുക. അപ്പോൾ അവർ അത് ഭക്ഷിക്കും." (ദ,തു,ന,ജ)', 'نَاجِيَةَ الْخُزَاعِيِّ', 'നാജിയതുൽ ഖുസാഈ(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 388, 388, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=165 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 494, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ ذُؤَيْبًا أَبَا قَبِيصَةَ حَدَّثَهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَبْعَثُ مَعَهُ بِالْبُدْنِ، ثُمَّ يَقُولُ: "إِنْ عَطِبَ مِنْهَا شَيْءٌ، فَخَشِيتَ عَلَيْهِ مَوْتًا، فَانْحَرْهَا، ثُمَّ اغْمِسْ نَعْلَهَا فِي دَمِهَا، ثُمَّ اضْرِبْ بِهِ صَفْحَتَهَا، وَلَا تَطْعَمْهَا أَنْتَ وَلَا أَحَدٌ مِنْ أَهْلِ رُفْقَتِكَ". (م)', 'ഇബ്നുഅബ്ബാസ്(റ): ദുവൈബ് അബൂഖുബൈസ്(റ) അദ്ദേഹത്തോട് പറഞ്ഞു: നബി(സ) അദ്ദേഹത്തിന്റെ കൂടെ ബലിഒട്ടകങ്ങളെ (ഹറമിലേക്ക്) കൊടുത്തയക്കാറുണ്ടായിരുന്നു. അന്നേരം അവിടന്ന് ഇങ്ങനെ പറയാറുണ്ടായിരുന്നു. "അതിൽ വല്ലതും നടക്കാൻ കഴിയാത്ത വണ്ണം ക്ഷീണിക്കുകയും, ചത്തുപോകുമെന്ന് നിനക്ക് തോന്നുകയും ചെയ്താൽ നീ അതിനെ അറുത്തു കൊള്ളുക. അനന്തരം അതിന്റെ (ബലിയടയാളം കെട്ടിയ) ചെരുപ്പ് അതിന്റെ രക്തത്തിൽ മുക്കുകയും എന്നിട്ട് അതുകൊണ്ട് ആ മൃഗത്തിന്റെ ഉയർന്നു കിടക്കുന്ന പാർശ്വത്തിൽ രക്തം പുരട്ടുകയും ചെയ്തുകൊള്ളുക. നീയും നിന്റെ കൂട്ടുകാരിൽ നിന്നുള്ള യാതൊരാളും അതിൽ നിന്ന് യാതൊന്നും ഭക്ഷിക്കുകയുമരുത്." (മു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 388, 389, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=165 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 495, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: بَعَثَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فُلَانًا الْأَسْلَمِيَّ، وَبَعَثَ مَعَهُ بِثَمَانِ عَشْرَةَ بَدَنَةً، فَقَالَ: أَرَأَيْتَ إِنْ أُزْحِفَ عَلَيَّ مِنْهَا شَيْءٌ؟ قَالَ: تَنْحَرُهَا، ثُمَّ تَصْبُغُ نَعْلَهَا فِي دَمِهَا، ثُمَّ اضْرِبْهَا عَلَى صَفْحَتِهَا، وَلَا تَأْكُلْ مِنْهَا أَنْتَ وَلَا أَحَدٌ مِنْ أَصْحَابِكَ. أَوْ قَالَ: مِنْ أَهْلِ رُفْقَتِكَ". (م,د,ن)', 'ഇബ്നുഅബ്ബാസ്(റ): അസ്‌ലമിയ്യയിൽ പെട്ട ഒരാളോടൊപ്പം റസൂൽ(സ) പതിനെട്ട് ഒട്ടങ്ങളെ അയച്ചു. അയാൾ ചോദിച്ചു: ഇവയിൽ നിന്ന് ഏതിനെങ്കിലും പരിക്ക് പറ്റിയാൽ ഞാനെന്താണ് ചെയ്യേണ്ടത്? റസൂൽ(സ) പറഞ്ഞു: "അതിനെ അറുക്കുക, അതിന്റെ ലാട ആ രക്തത്തിൽ മുക്കുകയും അതുമായി പിരടിയിൽ അടയാളമിടുകയും ചെയ്യുക. നീയോ നിന്റെ കൂടെയുള്ളവരോ അതിൽ നിന്ന് തിന്നരുത്." (മു,ദ,ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['م','د','ن']::text[], array['മു','ദ','ന']::text[], null, null, 389, 389, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=165 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 496, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كُنَّا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي سَفَرٍ، فَحَضَرَ الْأَضْحَى، فَاشْتَرَكْنَا: فِي الْبَقَرَةِ سَبْعَةً، وَفِي الْجَزُورِ عَشَرَةً. قَالَ ترمذي هَذَا حَدِيثٌ حَسَنٌ غَرِيبٌ. (ت,ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): ഞങ്ങൾ റസൂൽ(സ)യോട് കൂടെ ഒരു യാത്രയിലായിരുന്നു. അതിനിടെ അറിവിന്റെ സമയമെത്തി. അപ്പോൾ ഞങ്ങൾ ഒട്ടകത്തിൽ പത്തും പശുവിൽ ഏഴും ആളുകൾ വീതം പങ്കു ചേർന്നു. അതു നടത്തി. (തു,ന,ജു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ت','ن','جه']::text[], array['തു','ന','ജു']::text[], null, null, 389, 389, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=166 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 497, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: نَحَرْنَا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَامَ الْحُدَيْبِيَةِ الْبَقَرَةَ عَنْ سَبْعَةٍ، وَالْبَدَنَةَ عَنْ سَبْعَةٍ. قَالَ ترمذي هذا حَدِيثٌ حَسَنٌ صَحِيحٌ. (م,ت,ن)', 'ജാബിർ(റ): ഹുദൈബിയ്യാ വർഷത്തിൽ റസൂൽ(സ)യോടൊപ്പം ഞങ്ങൾ ഏഴാളുകൾ വീതം ഒരു ഒട്ടകത്തിലും, പശുവിലും പങ്കുചേർന്ന് നഹ്റ് (അറവ്) നടത്തി. (മു,തു,ന)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['م','ت','ن']::text[], array['മു','തു','ന']::text[], null, null, 389, 389, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=166 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 498, 'عَنْ جَابِرِ بنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: خَرَجْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُهِلِّينَ بِالْحَجِّ، فَأَمَرَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ نَشْتَرِكَ فِي الْإِبِلِ وَالْبَقَرِ، كُلُّ سَبْعَةٍ مِنَّا فِي بَدَنَةٍ. (م)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): ഞങ്ങൾ റസൂൽ(സ)യോടൊപ്പം ഹജ്ജിന് ഇഹ്റാം ചെയത് പുറപ്പെട്ടു. അന്നേരം റസൂൽ(സ) ഞങ്ങളോട് ഒട്ടകത്തിലും, പശുവിലും ഏഴാളുകൾ വീതം ഓരോ മൃഗത്തിൽ പങ്കുചേരാൻ കൽപ്പിച്ചു. (ജ)', 'جَابِرِ بنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['م']::text[], array['ജ']::text[], null, null, 389, 389, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=166 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 499, 'عَنْ جَابِرِ بنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: ذَبَحَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ عَائِشَةَ بَقَرَةً يَوْمَ النَّحْرِ. (م)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): നഹ്റിന്റെ ദിവസം ആഇശ(റ)ക്ക് വേണ്ടി റസൂൽ(സ) ഒരു പശുവിനെ അറുത്തു. (മു)', 'جَابِرِ بنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 389, 389, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=167 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 500, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: خَرَجْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِخَمْسٍ بَقِينَ مِنْ ذِي الْقَعْدَةِ تَقَدَّمَ، وَفِي هَذِهِ الرِّوَايَةِ زِيَادَةٌ: فَدُخِلَ عَلَيْنَا يَوْمَ النَّحْرِ بِلَحْمِ بَقَرٍ، فَقُلْتُ: مَا هَذَا؟ قَال نَحَرَ رَسُولُ اللهِ صَلَّى الله عليه وسلَّمَ عَنْ أَزْوَاجِهِ. (خ)', 'ആഇശ(റ): ദുൽഖഅദ് 25ന് ഞങ്ങൾ തിരുമേനി(സ)യോടൊപ്പം ഹജ്ജിനായി പുറപ്പെട്ടുവെന്ന് ആഇശ(റ)യിൽ നിന്നുള്ള നിവേദനം മുമ്പ് വന്നിട്ടുണ്ട്. ഈ രിവായതിൽ ഇതുകൂടിയുണ്ട്: ബലിദിനത്തിൽ ഒരാൾ ഞങ്ങളുടെയടുക്കൽ കുറച്ചു പശുമാംസം കൊണ്ടു വന്നു. ഞാൻ ചോദിച്ചു: ഇതെന്താണ്? തിരുമേനി(സ) തന്റെ ഭാര്യമാർക്കു വേണ്ടി ബലിയറുത്തതാണിത് എന്ന് അയാൾ പറഞ്ഞു. (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 390, 390, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=168 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 501, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَصْحَابَهُ كَانُوا يَنْحَرُونَ الْبَدَنَةَ مَعْقُولَةَ الْيُسْرَى، قَائِمَةً عَلَى مَا بَقِيَ مِنْ قَوَائِمِهَا. (د)', 'ജാബിർ(റ): ഒട്ടകത്തിന്റെ ഇടതു കാലുകൾ കെട്ടി മറ്റു കാലുകളിൽ നിർത്തിയിട്ടായിരുന്നു റസൂൽ(സ)യും അനുചരൻമാരും ഒട്ടകത്തെ അറുത്തിരുന്നത്. (ദ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 390, 390, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=169 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 502, 'عَنْ زِيَادِ بْنِ جُبَيْرٍ: أَنَّ ابْنَ عُمَرَ رَضِيَ اللهُ عَنْهُمَا أَتَى عَلَى رَجُلٍ وَهُوَ يَنْحَرُ بَدَنَتَهُ بَارِكَةً، فَقَالَ: ابْعَثْهَا قِيَامًا مُقَيَّدَةً، سُنَّةَ نَبِيِّكُمْ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (م)', 'സിയാദുബ്നു ജുബൈർ(റ): ഒരിക്കൽ ഒരു മനുഷ്യൻ തന്റെ ബലിഒട്ടകത്തെ കിടത്തി അറുക്കുമ്പോൾ, ഇബ്നുഉമർ അദ്ദേഹത്തിന്റെ അരികിലൂടെ നടന്ന് പോവുകയുണ്ടായി. ഉടനെ ഇബ്നുഉമർ(റ) പറഞ്ഞു: നീ അതിനെ എഴുന്നേൽപ്പിച്ച് ബന്ധിച്ച ശേഷം നിറുത്തി അറുക്കുക, അതാണ് നമ്മുടെ റസൂൽ(സ)യുടെ സുന്നത്ത്. (മു)', 'زِيَادِ بْنِ جُبَيْرٍ', 'സിയാദുബ്നു ജുബൈർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 390, 390, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=169 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 503, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ قَالَ: لَمَّا نَحَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بُدْنَهُ، فَنَحَرَ ثَلَاثِينَ بِيَدِهِ، وَأَمَرَنِي فَنَحَرْتُ سَائِرَهَا. (د)', 'അലി(റ): റസൂൽ(സ) തന്റെ ഒട്ടകങ്ങളിൽ മുപ്പതെണ്ണത്തെ സ്വന്തം കരങ്ങൾ കൊണ്ട് അറുത്തു. അവശേഷിച്ചവയെ അറുക്കാൻ എന്നോട് കൽപ്പിക്കുകയും ഞാനവയെ അറക്കുകയും ചെയ്തു. (ദ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 390, 390, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=170 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 504, 'عَنْ عَبْدِ اللَّهِ بْنِ قُرْطٍ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ أَعْظَمَ الْأَيَّامِ عِنْدَ اللَّهِ تَبَارَكَ وَتَعَالَى يَوْمُ النَّحْرِ، ثُمَّ يَوْمُ الْقَرِّ". وَقُرِّبَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَدَنَاتٌ خَمْسٌ، أَوْ سِتٌّ، فَطَفِقْنَ يَزْدَلِفْنَ إِلَيْهِ بِأَيَّتِهِنَّ يَبْدَأُ، فَلَمَّا وَجَبَتْ جُنُوبُهَا قَالَ: "مَنْ شَاءَ اقْتَطَعَ". (د,ن)', 'അബ്ദുല്ലാഹിബ്നു ഖുർത്(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ അടുക്കൽ ഏറ്റവും മഹോന്നതമായ ദിനം ബലി ദിനവും പിന്നെ വിശ്രമ ദിനവുമാണ്." അഞ്ചോ ആറോ ഒട്ടകങ്ങളെ റസൂൽ(സ)യുടെ സമീപത്തേക്ക് കൊണ്ടു വന്നു. ആദ്യം ഏത് അറക്കപ്പെടുമെന്നറിയാൻ അവകൾ റസൂൽ(സ)യുടെ അരികിലേക്ക് അടുക്കാൻ തുടങ്ങി. അവകൾ മരിച്ച് വീണപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ആവശ്യമുള്ളവർ മുറിച്ചു കൊണ്ടുപോവുക." (ദ,ന)', 'عَبْدِ اللَّهِ بْنِ قُرْطٍ', 'അബ്ദുല്ലാഹിബ്നു ഖുർത്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 390, 391, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=170 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 505, 'عَنْ غُرْفَةَ بْنِ الْحَارِثِ الْكِنْدِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: شَهِدْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي حَجَّةِ الْوَدَاعِ وَأُتِيَ بِالْبُدْنِ، فَقَالَ: "ادْعُوا لِي أَبَا حَسَنٍ". فَدُعِيَ لَهُ عَلِيٌّ رَضِيَ اللهُ عَنْهُ، فَقَالَ لَهُ: "خُذْ بِأَسْفَلِ الْحَرْبَةِ". وَأَخَذَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِأَعْلَاهَا، ثُمَّ طَعَنَا بِهَا فِي الْبُدْنِ، فَلَمَّا فَرَغَ رَكِبَ بَغْلَتَهُ، وَأَرْدَفَ عَلِيًّا رَضِيَ اللهُ عَنْهُ. (د)', 'ഗുർഫതുബ്നു ഹാരിസ്(റ): തിരുമേനി(സ)യുടെ വിടവാങ്ങൽ ഹജ്ജിൽ ഞാൻ പങ്കെടുത്തിരുന്നു. ഒരു ഒട്ടകം കൊണ്ടു വരപ്പെട്ടു. റസൂൽ(സ) പറഞ്ഞു: "അബൂഹസനെ (അലി(റ)വിനെ) വിളിക്കൂ." അലി(റ)വിനെ വിളിച്ചു കൊണ്ടു വന്നു. റസൂൽ(സ) അലി(റ)വിനോട് പറഞ്ഞു: "നീ കുന്തത്തിന്റെ അടിഭാഗം പിടിക്കുക." റസൂൽ(സ) മുകൾ ഭാഗവും പിടിച്ചു. എന്നിട്ട് രണ്ട് പേരും കൂടി ഒട്ടകത്തെ കുത്തി. അറുത്ത് കഴിഞ്ഞപ്പോൾ തിരുമേനി(സ) തന്റെ കോവർ കഴുതയുടെ പുറത്ത് കയറുകയും അലി(റ)വിനെ പിന്നിലിരുത്തുകയും ചെയ്തു. (ദ)', 'غُرْفَةَ بْنِ الْحَارِثِ الْكِنْدِيِّ', 'ഗുർഫതുബ്നു ഹാരിസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 391, 391, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=170 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 506, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ قَالَ: أَمَرَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ أَقُومَ عَلَى بُدْنِهِ، وَأَنْ أَتَصَدَّقَ بِلَحْمِهَا وَجُلُودِهَا وَأَجِلَّتِهَا، وَأَنْ لَا أُعْطِيَ الْجَزَّارَ مِنْهَا، قَالَ: "نَحْنُ نُعْطِيهِ مِنْ عِنْدِنَا". (م)', 'അലി(റ): റസൂൽ(സ)യുടെ ബലി ഒട്ടകങ്ങളെ അറുത്തു വിതരണം ചെയ്യുന്നതിന്റെ മേൽനോട്ടം വഹിക്കുവാനും, അതിന്റെ മാംസം, തോൽ, പുറത്ത് വിരിക്കുന്ന വസ്ത്രം എന്നിവ ദാനം ചെയ്യുവാനും, കശാപ്പ്കാരന് (പ്രതിഫലമായി) അതിൽ നിന്ന് യാതൊന്നും കൊടുക്കാതിരിക്കുവാനും തിരുമേനി(സ) എന്നോട് കൽപ്പിച്ചു. അലി(റ) പറയുന്നു: അവന് (കശാപ്പുകാരന്) ഞങ്ങളുടെ സ്വന്തം വകയാണ് കൂലി കൊടുത്തിരുന്നത്. (മു)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 391, 391, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=171 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 507, 'عَنْ جَابِرِ بْنِ عَبْدِاللَّهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: كُنَّا لَا نَأْكُلُ مِنْ لُحُومِ بُدْنِنَا فَوْقَ ثَلَاثِ مِنًى فَرَخَّصَ لَنَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: كُلُوا وَتَزَوَّدُوا فَأَكَلْنَا وَتَزَوَّدْنَا. (خ)', 'ജാബിർ(റ): മിനായിൽ താമസിക്കുന്ന മൂന്ന് ദിവസമല്ലാതെ ബലിമൃഗങ്ങളുടെ മാംസം ഞങ്ങൾ ഭക്ഷിക്കാറില്ലായിരുന്നു. തിരുമേനി(സ) ഞങ്ങൾക്കതിൽ ഇളവ് അനുവദിച്ച്കൊണ്ട് പറഞ്ഞു: "നിങ്ങളത് ഭക്ഷിക്കുകയും സൂക്ഷിച്ചു വെക്കുകയും ചെയ്യുക." അതിന് ശേഷം ഞങ്ങളത് ഭക്ഷിക്കുകയും സൂക്ഷിച്ചു വെക്കുകയും ചെയ്തു. (ബു)', 'جَابِرِ بْنِ عَبْدِاللَّهِ', 'ജാബിർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 391, 391, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=172 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 508, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ قَالَ: أَمَرَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ أَقُومَ عَلَى بُدْنِهِ، وَأَنْ أَتَصَدَّقَ بِلَحْمِهَا وَجُلُودِهَا وَأَجِلَّتِهَا، وَأَنْ لَا أُعْطِيَ الْجَزَّارَ مِنْهَا، قَالَ: نَحْنُ نُعْطِيهِ مِنْ عِنْدِنَا. (م)', 'അലി(റ): റസൂൽ(സ)യുടെ ബലി ഒട്ടകങ്ങളെ അറുത്തു വിതരണം ചെയ്യുന്നതിന്റെ മേൽനോട്ടം വഹിക്കുവാനും, അതിന്റെ മാംസം, തോൽ, പുറത്ത് വിരിക്കുന്ന വസ്ത്രം എന്നിവ ധർമ്മം ചെയ്യുവാനും, കശാപ്പുകാരന് (പ്രതിഫലമായി) അതിൽ നിന്ന് യാതൊന്നും കൊടുക്കാതിരിക്കുവാനും തിരുമേനി(സ) എന്നോട് കൽപ്പിച്ചു. അലി(റ) പറയുന്നു: അവന് (കശാപ്പുകാരന്) ഞങ്ങളുടെ സ്വന്തം വകയാണ് കൂലി കൊടുത്തിരുന്നത്. (മു)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 392, 392, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=173 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 509, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مِنًى كُلُّهَا مَنْحَرٌ، وَكُلُّ فِجَاجِ مَكَّةَ طَرِيقٌ وَمَنْحَرٌ، وَكُلُّ عَرَفَةَ مَوْقِفٌ، وَكُلُّ الْمُزْدَلِفَةِ مَوْقِفٌ". (د,جه)', 'ജാബിർ(റ): റസൂൽ(സ) പറഞ്ഞു: "മിനാ പ്രദേശം മുഴുവൻ ഭാഗവും അറവ് നടത്താനുള്ളതാണ്. മക്കയുടെ മുഴുവൻ ഇടവീഥികളും വഴികളും അറവു നടത്താനുള്ള സ്ഥലവുമാണ്. അറഫ മുഴുവനും നിൽക്കാനുള്ള സ്ഥലമാണ്. മുസ്ദലിഫ മുഴുവനും നിൽക്കാനുള്ള സ്ഥലമാണ്." (ദ,ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 392, 392, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=174 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 510, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "وَقَفْتُ هَا هُنَا بِعَرَفَةَ وَعَرَفَةَ كُلُّهَا مَوْقِفٌ، وَوَقَفْتُ هَا هُنَا بِجَمْعٍ وَجَمْعٌ كُلُّهَا مَوْقِفٌ، وَنَحَرْتُ هَهُنَا، وَمِنًى كُلُّهَا مَنْحَرٌ، فَانْحَرُوا فِي رِحَالِكُمْ". (د)', 'ജാബിർ(റ): റസൂൽ(സ) പറഞ്ഞു: "അറഫയിൽ ഞാൻ ഇവിടെ നിന്നു, അറഫ മുഴുവനും മൗഖിഫാണ്. മുസ്ദലിഫയിൽ ഞാൻ ഇവിടെ നിന്നു. മുസ്ദലിഫ മുഴുവൻ മൗഖിഫാണ്. ഇവിടെ വെച്ച് ഞാൻ ബലി അറുത്തു. മിന മുഴുക്കെയും ബലിയിടമാണ്. നിങ്ങൾ നിൽക്കുന്നിടത്ത് വെച്ച് അറക്കുക." (ദ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 392, 392, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=174 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 511, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّهُ كَانَ يَنْحَرُ فِي الْمَنْحَرِ، يَعْنِي مَنْحَرَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (خ)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): അദ്ദേഹം റസൂൽ(സ) അറവു നടത്തിയ സ്ഥലത്തു വെച്ച് അറവു നടത്തുമായിരുന്നു. (ബു)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 392, 392, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=175 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 512, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا أَنَّهُ قَالَ: وَقَفَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي حَجَّةِ الْوَدَاعِ بِمِنًى يَسْأَلُونَهُ، فَجَاءَهُ رَجُلٌ فَقَالَ: يَا رَسُولَ اللَّهِ، إِنِّي لَمْ أَشْعُرْ فَحَلَقْتُ قَبْلَ أَنْ أَذْبَحَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "اذْبَحْ وَلَا حَرَجَ". وَجَاءَ رَجُلٌ آخَرُ فَقَالَ: يَا رَسُولَ اللَّهِ، لَمْ أَشْعُرْ فَنَحَرْتُ قَبْلَ أَنْ أَرْمِيَ، قَالَ: "ارْمِ وَلَا حَرَجَ". قَالَ: فَمَا سُئِلَ يَوْمَئِذٍ عَنْ شَيْءٍ قُدِّمَ أَوْ أُخِّرَ إِلَّا قَالَ: "اصْنَعْ وَلَا حَرَجَ". (ق,د,ت,جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): റസൂൽ(സ) ഹജ്ജത്തുൽ വിദാഇൽ മിനയിൽ നിൽക്കെ ജനങ്ങൾ പല കാര്യങ്ങളും ചോദിച്ചു തുടങ്ങി. ഒരാൾ ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരേ, ഞാൻ അറവ് നടത്തുന്നതിന് മുമ്പ് മുടി കളഞ്ഞു, എനിക്കറിയില്ലായിരുന്നു?. അപ്പോൾ റസൂൽ(സ) മറുപടി പറഞ്ഞു: "അറവ് നടത്തുക, ഒരു കുഴപ്പവുമില്ല." മറ്റൊരാൾ വന്നന്വേഷിച്ചു: അല്ലാഹുവിന്റെ ദൂതരേ, ഞാൻ ഏറ് നടത്തുന്നതിന് മുമ്പായി അറവു നടത്തിയിരിക്കുന്നു, എനിക്ക്റിയില്ലായിരുന്നു. റസൂൽ(സ) പറഞ്ഞു: "എറിയുക, ഒരു കുഴപ്പവുമില്ല." ചിലത് ആദ്യവും മറ്റേത് ശേഷവുമായി ചെയ്തതിനെ സംബന്ധിച്ച് ചോദിക്കപ്പെട്ടതിനെല്ലാം റസൂൽ(സ) മറുപടി പറഞ്ഞത്, "ചെയ്തു കൊള്ളൂ, പ്രശ്നമില്ല." എന്നാണ്. (ബു,മു,ദ,തു,ജ)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 392, 393, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=176 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 513, 'عَنْ أُسَامَةَ بْنِ شَرِيكٍ رَضِيَ اللهُ عَنْهُ قَالَ: خَرَجْتُ مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَاجًّا، فَكَانَ النَّاسُ يَأْتُونَهُ، فَمَنْ قَالَ: يَا رَسُولَ اللَّهِ، سَعَيْتُ قَبْلَ أَنْ أَطُوفَ، أَوْ قَدَّمْتُ شَيْئًا، أَوْ أَخَّرْتُ شَيْئًا، فَكَانَ يَقُولُ: "لَا حَرَجَ لَا حَرَجَ، إِلَّا عَلَى رَجُلٍ اقْتَرَضَ عِرْضَ رَجُلٍ مُسْلِمٍ وَهُوَ ظَالِمٌ، فَذَلِكَ الَّذِي حَرِجَ وَهَلَكَ". (د)', 'ഉസാമതുബ്നു ശരീക്(റ): ഞാൻ പ്രവാചകർ(സ)യുടെ കൂടെ ഹജ്ജിന് പുറപ്പെട്ടു. ജനങ്ങൾ തിരുമേനി(സ)യുടെ അടുത്തേക്ക് വരുമായിരുന്നു. റസൂലേ, ത്വവാഫ് ചെയ്യുന്നതിന് മുമ്പ് ഞാൻ സഅ്യ് ചെയ്തു. അതല്ലെങ്കിൽ ഞാൻ ഒരു കർമ്മത്തെ മുന്തിച്ചു, അല്ലെങ്കിൽ പിന്തിച്ചു എന്നൊക്കെ ആരെങ്കിലും പറഞ്ഞാൽ പ്രവാചകർ(സ) പറയും: "കുഴപ്പമില്ല, കുഴപ്പമില്ല, മുസ്‌ലിമിന്റെ അഭിമാനം അപഹരിച്ചവന് ഒഴികെ. അവൻ അക്രമിയാണ്. അവനാണ് ശിക്ഷക്ക് പാത്രമായവനും നശിച്ചവനും." (ദ)', 'أُسَامَةَ بْنِ شَرِيكٍ', 'ഉസാമതുബ്നു ശരീക്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 393, 393, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=176 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 514, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سُئِلَ عَمَّنْ ذَبَحَ قَبْلَ أَنْ يَحْلِقَ، أَوْ حَلَقَ قَبْلَ أَنْ يَذْبَحَ؟ قَالَ: "لَا حَرَجَ". (ق,د,ت,جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): നിശ്ചയം റസൂൽ(സ)യോട് മുടികളയുന്നതിന് മുമ്പ് അറവു നടത്തിയ ഒരാളെക്കുറിച്ച് ചോദിക്കപ്പെട്ടു. അല്ലെങ്കിൽ അറവു നടത്തുന്നതിനു മുമ്പ് മുടികളഞ്ഞയാളെക്കുറിച്ച്. റസൂൽ(സ) പറഞ്ഞു: "കുറ്റമില്ല." (ബു,മു,ദ,തു,ജ)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 393, 393, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=176 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 515, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَعَدَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِمِنًى يَوْمَ النَّحْرِ لِلنَّاسِ، فَجَاءَهُ رَجُلٌ فَقَالَ: يَا رَسُولَ اللَّهِ، إِنِّي حَلَقْتُ قَبْلَ أَنْ أَذْبَحَ؟ قَالَ: "لَا حَرَجَ". ثُمَّ جَاءَهُ آخَرُ فَقَالَ: يَا رَسُولَ اللَّهِ، إِنِّي نَحَرْتُ قَبْلَ أَنْ أَرْمِيَ؟ قَالَ: "لَا حَرَجَ". فَمَا سُئِلَ يَوْمَئِذٍ عَنْ شَيْءٍ قُدِّمَ قَبْلَ شَيْءٍ إِلَّا قَالَ: "لَا حَرَجَ". (جه)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): നബി(സ) ബലി ദിവസം മിനയിൽ ജനങ്ങളുടെ സംശയം പൂർത്തീകരണത്തിന് വേണ്ടി ഇരുന്നു കൊടുത്തു. അപ്പോഴൊരാൾ വന്ന് ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരെ, ഞാൻ അറവ് നടത്തുന്നതിന് മുമ്പ് മുടികളഞ്ഞു? റസൂൽ(സ) പറഞ്ഞു: "കുഴപ്പമില്ല". പിന്നീട് മറ്റൊരാൾ വന്നു ചോദിച്ചു. അല്ലാഹുവിന്റെ ദൂതരെ, തീർച്ചയായും ഞാൻ എറിയുന്നതിന്റെ മുമ്പ് അറവ് നടത്തി? റസൂൽ(സ) പറഞ്ഞു: "കുഴപ്പമില്ല." അന്നേ ദിവസം മറ്റൊന്നിന്റെ മുമ്പ് ചെയ്ത കാര്യങ്ങളെക്കുറിച്ച് ചോദിക്കപ്പെട്ടപ്പോഴെല്ലാം റസൂൽ(സ) "കുഴപ്പമില്ല." എന്നാണ് മറുപടി പറഞ്ഞത്. (ജ)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 393, 393, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=176 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 516, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: مَا سُئِلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَمَّنْ قَدَّمَ شَيْئًا قَبْلَ شَيْءٍ إِلَّا يُلْقِي بِيَدَيْهِ كِلْتَيْهِمَا: "لَا حَرَجَ". (خ,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): ഒരു കർമ്മം മറ്റൊരു കർമ്മത്തെ മുൻ കടന്നതിനെക്കുറിച്ച് ചോദിക്കപ്പെട്ടപ്പോഴൊക്കെയും "പ്രശ്നമില്ലെന്ന്" റസൂൽ(സ) ഇരു കരങ്ങൾ കൊണ്ടും ആംഗ്യം കാണിക്കാതിരുന്നില്ല. (ബു,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ','جه']::text[], array['ബു','ജ']::text[], null, null, 393, 393, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=176 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 517, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُسْأَلُ يَوْمَ مِنًى، فَيَقُولُ: "لَا حَرَجَ، لَا حَرَجَ". فَأَتَاهُ رَجُلٌ فَقَالَ: حَلَقْتُ قَبْلَ أَنْ أَذْبَحَ؟ قَالَ: "لَا حَرَجَ". قَالَ: رَمَيْتُ بَعْدَ مَا أَمْسَيْتُ؟ قَالَ: "لَا حَرَجَ". (خ,د,ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): മിനായിൽ നിൽക്കുന്ന ദിവസം റസൂൽ(സ)യോട് പലകാര്യങ്ങളും ചോദിക്കപ്പെട്ടു. റസൂൽ(സ) മറുപടി പറയും: "കുഴപ്പമില്ല, കുഴപ്പമില്ല." ഒരാൾ വന്നു ചോദിച്ചു. ഞാൻ അറവു നടത്തുന്നതിന് മുമ്പ് മുടി കളഞ്ഞു? റസൂൽ(സ) പറഞ്ഞു: "കുഴപ്പമില്ല." അയാൾ ചോദിച്ചു: വൈകുന്നേരത്താണ് ഞാൻ എറിഞ്ഞത്? റസൂൽ(സ) പറഞ്ഞു: "കുഴപ്പമില്ല" (ബു,ദ,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ','د','ن','جه']::text[], array['ബു','ദ','ന','ജ']::text[], null, null, 394, 394, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=176 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 518, 'عَنْ جَابِرِ بن عبد الله رَضِيَ اللهُ عَنْهُمَا قَالَ: ذَبَحَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ عَائِشَةَ بَقَرَةً يَوْمَ النَّحْرِ. (م)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): നഹ്റിന്റെ ദിവസം ആഇശ(റ)ക്ക് വേണ്ടി റസൂൽ(സ) ഒരു പശുവിനെ അറുത്തു. (മു)', 'جَابِرِ بن عبد الله', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 394, 394, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=176 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 519, 'عَنْ عَائِشَةَ وَابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُم: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَخَّرَ طَوَافَ الزِّيَارَةِ إِلَى اللَّيْلِ. (خ,د,ت,جه)', 'ആഇശ(റ): റസൂൽ(സ) സന്ദർശന ത്വവാഫ് രാത്രിയിലേക്ക് പിന്തിച്ചു. (ബു,ദ,തു,ജ)', 'عَائِشَةَ وَابْنِ عَبَّاسٍ', 'ആഇശ(റ)', null, null, array['خ','د','ت','جه']::text[], array['ബു','ദ','തു','ജ']::text[], null, null, 394, 394, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=177 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 520, 'عَنْ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَمْ يَرْمُلْ فِي السَّبْعِ الَّذِي أَفَاضَ فِيهِ. (د,جه)', 'അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ): തീർച്ചയായും നബിതങ്ങൾ(സ) ഇഫാളത്തിന്റെ ത്വവാഫിൽ ഏഴിലും റംല് നടത്തം നടന്നിട്ടില്ല. (ദ,ജ)', 'عَبْدِ اللَّهِ بْنِ عَبَّاسٍ', 'അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 394, 394, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=177 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 521, 'عَنْ زَيْنَبَ بِنْتِ أَبِي سَلَمَةَ، عَنْ أُمِّ سَلَمَةَ – رَضِيَ اللهُ عَنْهُم – قَالَتْ: كَانَتْ لَيْلَتِي الَّتِي يَصِيرُ إِلَيَّ فِيهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَسَاءَ يَوْمِ النَّحْرِ، فَصَارَ إِلَيَّ، وَدَخَلَ عَلَيَّ وَهْبُ بْنُ زَمْعَةَ وَمَعَهُ رَجُلٌ مِنْ آلِ أَبِي أُمَيَّةَ مُتَقَمِّصَيْنِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِوَهْبٍ: "هَلْ أَفَضْتَ أَبَا عَبْدِ اللَّهِ". قَالَ: لَا وَاللَّهِ يَا رَسُولَ اللَّهِ، قَالَ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "انْزِعْ عَنْكَ الْقَمِيصَ". قَالَ: فَنَزَعَهُ مِنْ رَأْسِهِ، وَنَزَعَ صَاحِبُهُ قَمِيصَهُ مِنْ رَأْسِهِ، ثُمَّ قَالَ: وَلِمَ يَا رَسُولَ اللَّهِ؟ قَالَ: "إِنَّ هَذَا يَوْمٌ رُخِّصَ لَكُمْ إِذَا أَنْتُمْ رَمَيْتُمُ الْجَمْرَةَ أَنْ تَحِلُّوا" يَعْنِي مِنْ كُلِّ مَا حُرِمْتُمْ مِنْهُ إِلَّا النِّسَاءَ: "فَإِذَا أَمْسَيْتُمْ قَبْلَ أَنْ تَطُوفُوا هَذَا الْبَيْتَ صِرْتُمْ حُرُمًا، كَهَيْئَتِكُمْ قَبْلَ أَنْ تَرْمُوا الْجَمْرَةَ حَتَّى تَطُوفُوا بِهِ". (د)', 'ഉമ്മു സലമ(റ)യിൽ നിന്ന് സൈനബ് ബിൻത് അബീസലമ(റ): റസൂൽ(സ) എന്റെ അരികിലേക്ക് വരാനുള്ള രാത്രി ബലി ദിനം കഴിഞ്ഞുള്ള രാത്രിയായിരുന്നു. റസൂൽ(സ) എന്റെ അടുത്തേക്ക് വന്നു. വഹബുബ്നു സംഅയും അബൂ ഉമയ്യ ഗോത്രത്തിലെ ഒരാളും കടന്നു വന്നു. അവർ രണ്ട് പേരും ഖമീസ് ധരിച്ചിരുന്നു. തിരുമേനി(സ) വഹബിനോട് പറഞ്ഞു: "ഓ അബൂഅബ്ദില്ലാ, നിങ്ങൾ ഇഫാളത്തിന്റെ ത്വവാഫ് ചെയ്തുവോ?" വഹബ് പറഞ്ഞു: അല്ലാഹുവാണ് സത്യം, ഇല്ല റസൂലേ. റസൂൽ(സ) പറഞ്ഞു: "നിന്റെ ഖമീസ് ഊരുക." വഹബും കൂടെ ഉള്ളയാളും തങ്ങളുടെ തലയിൽ നിന്ന് ഖമീസ് ഊരി. എന്നിട്ട് ചോദിച്ചു: എന്തിന് റസൂലേ? റസൂൽ(സ) പ്രതിവചിച്ചു: "ജംറയിൽ എറിഞ്ഞാൽ തഹല്ലുലാവാൻ ഇളവു നൽകപ്പെട്ട ദിനമാണത്." അഥവാ സ്ത്രീകളല്ലാത്ത വിലക്കപ്പെട്ട എല്ലാത്തിൽ നിന്നും. "നിങ്ങൾ കഅ്ബ പ്രദക്ഷിണം ചെയ്യുന്നതിന് മുമ്പ് സൂര്യൻ അസ്തമിച്ചാൽ ത്വവാഫ് ചെയ്യുന്നത് വരെ നിങ്ങൾ മുഹ്റിമീങ്ങൾ തന്നെ ആയിരിക്കും, ജംറ എറിയുന്നതിനുള്ള മുമ്പുള്ള അതേ അവസ്ഥ." (ദ)', 'زَيْنَبَ بِنْتِ أَبِي سَلَمَةَ، عَنْ أُمِّ سَلَمَةَ –', 'ഉമ്മു സലമ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 394, 395, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=177 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 522, 'عَنِ الْحَارِثِ بْنِ عَبْدِ اللَّهِ بْنِ أَوْسٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَتَيْتُ عُمَرَ بْنَ الْخَطَّاب رَضِيَ اللهُ عَنْهُ فَسَأَلْتُهُ عَنِ الْمَرْأَةِ تَطُوفُ بِالْبَيْتِ يَوْمَ النَّحْرِ، ثُمَّ تَحِيضُ؟ قَالَ: لِيَكُنْ آخِرُ عَهْدِهَا بِالْبَيْتِ، قَالَ: فَقَالَ الْحَارِثُ: كَذَلِكَ أَفْتَانِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: فَقَالَ عُمَرُ: أَرِبْتَ عَنْ يَدَيْكَ، سَأَلْتَنِي عَنْ شَيْءٍ سَأَلْتَ عَنْهُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِكَيْ مَا أُخَالِفَ. (د,ت,ن)', 'ഹാരിസുബ്നു അബ്ദില്ല(റ): ഞാൻ ഉമർ(റ)വിന്റെ അടുത്ത് ചെന്നു. ബലിദിനം ത്വവാഫ് ചെയ്തതിനു ശേഷം ആർത്തവമുണ്ടായ സ്ത്രീയെക്കുറിച്ച് ഞാൻ ചോദിച്ചു. ഉമർ(റ) പറഞ്ഞു: അവളുടെ അവസാന കർമ്മം കഅ്ബയിലായിരിക്കണം. അപ്പോൾ ഹാരിസ് പറഞ്ഞു: റസൂൽ(സ) ഇപ്രകാരം എനിക്ക് ഫത്‌വ തന്നിട്ടുണ്ട്. ഉമർ(റ) പറഞ്ഞു: നിന്റെ കരങ്ങൾ നശിക്കട്ടെ. റസൂൽ(സ)യോട് ചോദിച്ച ഒരു കാര്യത്തെക്കുറിച്ച് എന്നോട് നീ ചോദിക്കുന്നു. അങ്ങനെ ഒരു പക്ഷെ, എന്റേത് റസൂൽ(സ)യിൽ നിന്ന് ഭിന്നമാകും. (ദ,തു,ന)', 'الْحَارِثِ بْنِ عَبْدِ اللَّهِ بْنِ أَوْسٍ', 'ഹാരിസുബ്നു അബ്ദില്ല(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 395, 395, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=177 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 523, 'عَنِ الْحَارِثِ بْنِ عَبْدِ اللَّهِ بْنِ أَوْسٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ حَجَّ هَذَا الْبَيْتَ أَوِ اعْتَمَرَ فَلْيَكُنْ آخِرُ عَهْدِهِ بِالْبَيْتِ" فَقَالَ لَهُ عُمَرُ: خَرَرْتَ مِنْ يَدَيْكَ، سَمِعْتَ هَذَا مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَلَمْ تُخْبِرْنَا بِهِ. (د,ت)', 'ഹാരിസുബ്നു അബ്ദില്ലാഹിബ്നു ഔസ്(റ): റസൂൽ(സ) പറയുന്നതായി ഞാൻ കേട്ടു: "വല്ലവനും കഅ്ബയിൽ വന്ന് ഹജ്ജോ ഉംറയോ നിർവ്വഹിക്കുന്നുവെങ്കിൽ അവന്റെ അവസാന പ്രവ്യത്തി കഅ്ബയിലായിരിക്കണം." അപ്പോൾ ഹാരിസി(റ)നോട് ഉമർ(റ) പറഞ്ഞു: നിന്റെ കൈ നശിച്ചു പോകട്ടെ. നീ റസൂൽ(സ)യിൽ നിന്നിത് കേട്ടു. എന്നിട്ട് ഞങ്ങളെ അത് അറിയിച്ചില്ല. (ദ,തു)', 'الْحَارِثِ بْنِ عَبْدِ اللَّهِ بْنِ أَوْسٍ', 'ഹാരിസുബ്നു അബ്ദില്ലാഹിബ്നു ഔസ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 395, 395, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=177 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 524, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ النَّاسُ يَنْصَرِفُونَ فِي كُلِّ وَجْهٍ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا يَنْفِرَنَّ أَحَدٌ، حَتَّى يَكُونَ آخِرُ عَهْدِهِ بِالْبَيْتِ". (م)', 'ഇബ്നുഅബ്ബാസ്(റ): ജനങ്ങൾ എല്ലാ ഭാഗത്തുകൂടെയും പിരിഞ്ഞു പോവുകയായിരുന്നു. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "തന്റെ അവസാന കർമ്മം മസ്ജിദുൽ ഹറമിലാവാതെ ആരും മടങ്ങിപ്പോവരുത്." (മു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 395, 395, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=177 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 525, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: أَحْرَمْتُ مِنَ التَّنْعِيمِ بِعُمْرَةٍ، فَدَخَلْتُ، فَقَضَيْتُ عُمْرَتِي، وَانْتَظَرَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالْأَبْطَحِ حَتَّى فَرَغْتُ، وَأَمَرَ النَّاسَ بِالرَّحِيلِ، قَالَتْ: وَأَتَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْبَيْتَ فَطَافَ بِهِ ثُمَّ خَرَجَ. (د)', 'ആഇശ(റ): ഞാൻ തൻഈമിൽ നിന്ന് ഉംറക്ക് ഇഹ്റാം ചെയ്തു. കഅ്ബാലയത്തിൽ വരികയും ഉംറ നിർവ്വഹിക്കുകയും ചെയ്തു. ഞാനത് അവസാനിപ്പിക്കുവോളം റസൂൽ(സ) എന്നെ അബ്ത്വഹിൽ കാത്തിരിക്കുകയും ജനങ്ങളോട് യാത്രയാകാൻ കൽപിക്കുകയും ചെയ്തു. ആഇശ(റ) പറയുന്നു: റസൂൽ(സ) കഅ്ബാലയത്തിൽ വരികയും പ്രദക്ഷിണം ചെയ്തശേഷം പുറപ്പെടുകയും ചെയ്തു. (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 395, 395, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=178 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 526, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: خَرَجْتُ مَعَهُ – تَعْنِي مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ – فِي النَّفْرِ الْآخِرِ، فَنَزَلَ الْمُحَصَّبَ، قَالَتْ: ثُمَّ جِئْتُهُ بِسَحَرٍ، فَأَذَّنَ فِي أَصْحَابِهِ بِالرَّحِيلِ، فَارْتَحَل، فَمَرَّ بِالْبَيْتِ قَبْلَ صَلَاةِ الصُّبْحِ، فَطَافَ بِهِ حِينَ خَرَجَ، ثُمَّ انْصَرَفَ مُتَوَجِّهًا إِلَى الْمَدِينَةِ. (د)', 'ആഇശ(റ): ഞാൻ റസൂൽ(സ)യോട് കൂടെ അവസാന സംഘത്തിൽ പുറപ്പെട്ടു. പ്രവാചകർ(സ) മുഹസ്സബിൽ ഇറങ്ങി. ഞാൻ റസൂൽ(സ)ക്ക് അത്താഴവുമായി വന്നു. അപ്പോൾ തിരുമേനി(സ) അനുചരരോട് യാത്രക്കൊരുങ്ങാൻ വിളംബരം ചെയ്തു. അങ്ങനെ യാത്രയായി. സുബ്ഹി നിസ്കാരത്തിന് മുമ്പ് കഅ്ബക്കരികിലൂടെ നടന്നു പോയി. പുറപ്പെടാൻ സമയത്ത് കഅ്ബ ത്വവാഫ് ചെയ്തു. ശേഷം മദീനയുടെ ഭാഗത്തേക്ക് തിരിഞ്ഞു നടന്നു. (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 395, 396, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=178 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 527, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَفَاضَ يَوْمَ النَّحْرِ، ثُمَّ رَجَعَ فَصَلَّى الظُّهْرَ بِمِنًى. قَالَ نَافِعٌ: فَكَانَ ابْنُ عُمَرَ يُفِيضُ يَوْمَ النَّحْرِ، ثُمَّ يَرْجِعُ فَيُصَلِّي الظُّهْرَ بِمِنًى، وَيَذْكُرُ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَعَلَهُ. (م)', 'ഇബ്നുഉമർ(റ): നിശ്ചയം റസൂൽ(സ) നഹ്റ് ദിനത്തിൽ ഇഫാളത്തിന്റെ ത്വവാഫ് ചെയ്തു. പിന്നീട് മടങ്ങി വരികയും മിനയിൽ വെച്ച് ളുഹർ നിസ്കരിക്കുകയും ചെയ്തു. നാഫിഅ്(റ) പറഞ്ഞു: ഇബ്നുഉമർ(റ) നഹ്റിന്റെ ദിനത്തിൽ ഇഫാളത്ത് ചെയ്യുകയും പിന്നീട് മടങ്ങി മിനയിൽ വെച്ച് ളുഹർ നിസ്കരിക്കുകയും റസൂൽ(സ) ഇപ്രകാരം ചെയതിരുന്നുവെന്ന് പറയുകയും ചെയ്യും. (മു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 396, 396, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=179 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 528, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: حَاضَتْ صَفِيَّةُ بِنْتُ حُيَيٍّ بَعْدَ مَا أَفَاضَتْ، قَالَتْ عَائِشَةُ: فَذَكَرْتُ حِيضَتَهَا لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَحَابِسَتُنَا هِيَ". قَالَتْ: فَقُلْتُ: يَا رَسُولَ اللَّهِ، إِنَّهَا قَدْ كَانَتْ أَفَاضَتْ وَطَافَتْ بِالْبَيْتِ، ثُمَّ حَاضَتْ بَعْدَ الْإِفَاضَةِ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "فَلْتَنْفِرْ". (م)', 'ആഇശ(റ): (ഹജ്ജതുൽ വദാഇന്റെ അവസരത്തിൽ) ഇഫാളയുടെ ത്വവാഫ് ചെയ്ത ശേഷം സ്വഫിയ്യ(റ)ക്ക് ആർത്തവമുണ്ടായി. ആഇശ(റ) പറയുന്നു: അപ്പോൾ ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരെ, അവർ ഇഫാളയുടെ ത്വവാഫ് ചെയ്തിട്ടുണ്ട്. അതിന്റെ ശേഷമാണ് അവർക്ക് ആർത്തവമുണ്ടായത്." അപ്പോൾ തിരുമേനി(സ) അരുളി: "എന്നാൽ അവൾ മട(ങ്ങുവാൻ ഒരു)ങ്ങിക്കൊള്ളട്ടെ." (മു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 396, 396, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=180 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 529, 'عَنِ الْحَارِثِ بْنِ عَبْدِ اللَّهِ بْنِ أَوْسٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَتَيْتُ عُمَرَ بْنَ الْخَطَّاب رَضِيَ اللهُ عَنْهُ فَسَأَلْتُهُ عَنِ الْمَرْأَةِ تَطُوفُ بِالْبَيْتِ يَوْمَ النَّحْرِ، ثُمَّ تَحِيضُ؟ قَالَ: لِيَكُنْ آخِرُ عَهْدِهَا بِالْبَيْتِ، قَالَ: فَقَالَ الْحَارِثُ: كَذَلِكَ أَفْتَانِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: فَقَالَ عُمَرُ: أَرِبْتَ عَنْ يَدَيْكَ، سَأَلْتَنِي عَنْ شَيْءٍ سَأَلْتَ عَنْهُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِكَيْ مَا أُخَالِفَ. (د,ت,ن)', 'ഹാരിസുബ്നു അബ്ദില്ല(റ): ഞാൻ ഉമർ(റ)വിന്റെ അടുത്ത് ചെന്നു. ബലിദിനം ത്വവാഫ് ചെയ്തതിനു ശേഷം ആർത്തവമുണ്ടായ സ്ത്രീയെക്കുറിച്ച് ഞാൻ ചോദിച്ചു. ഉമർ(റ) പറഞ്ഞു: അവളുടെ അവസാന കർമ്മം കഅ്ബയിലായിരിക്കണം. അപ്പോൾ ഹാരിസ് പറഞ്ഞു: റസൂൽ(സ) ഇപ്രകാരം എനിക്ക് ഫത്‌വ തന്നിട്ടുണ്ട്. ഉമർ(റ) പറഞ്ഞു: നിന്റെ കരങ്ങൾ നശിക്കട്ടെ. റസൂൽ(സ)യോട് ചോദിച്ച ഒരു കാര്യത്തെക്കുറിച്ച് എന്നോട് നീ ചോദിക്കുന്നു. അങ്ങനെ ഒരു പക്ഷെ, എന്റേത് റസൂൽ(സ)യിൽ നിന്ന് ഭിന്നമാകും. (ദ,തു,ന)', 'الْحَارِثِ بْنِ عَبْدِ اللَّهِ بْنِ أَوْسٍ', 'ഹാരിസുബ്നു അബ്ദില്ല(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 396, 397, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=180 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 530, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: رُخِّصَ لِلْحَائِضِ أَنْ تَنْفِرَ إِذَا أَفَاضَتْ، قَالَ: وَسَمِعْتُ ابْنَ عُمَرَ رَضِيَ اللهُ عَنْهُمَا يَقُولُ: إِنَّهَا لَا تَنْفِرُ ثُمَّ سَمِعْتُهُ يَقُولُ بَعْدُ: إِنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَخَّصَ لَهُنَّ. (خ)', 'ഇബ്നുഅബ്ബാസ്(റ): ആദ്യം ഇഫാളതിന്റെ ത്വവാഫ് ചെയ്തിട്ടുണ്ടെങ്കിൽ അവസാനത്തെ വദാഇന്റെ ത്വവാഫ് കൂടാതെ ഋതുമതികളായ സ്ത്രീകൾക്ക് മക്ക വിടാമെന്ന് തിരുമേനി(സ) അനുവദിച്ചിട്ടുണ്ട്. ഇബ്നുഅബ്ബാസ്(റ) പറയുന്നു: ഋതുമതികൾ വദാഇന്റെ ത്വവാഫ് കൂടാതെ മക്ക വിട്ടു പോകാൻ പാടില്ലെന്ന് ഇബ്നുഉമർ(റ) പറയുന്നത് ഞാൻ കേട്ടു. തിരുമേനി(സ) അവർക്ക് ഇളവു നൽകിയിട്ടുണ്ടെന്ന് ശേഷം അദ്ദേഹം പറയുന്നതും ഞാൻ കേട്ടിട്ടുണ്ട്. (ബു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 397, 397, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=180 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 531, 'عَنِ ابْنِ جُرَيْجٍ: أَخْبَرَنِي عَطَاءٌ قَالَ: كَانَ ابْنُ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا يَقُولُ: لَا يَطُوفُ بِالْبَيْتِ حَاجٌّ وَلَا غَيْرُ حَاجٍّ إِلَّا حَلَّ. قُلْتُ لِعَطَاءٍ: مِنْ أَيْنَ يَقُولُ ذَلِكَ؟ قَالَ: مِنْ قَوْلِ اللَّهِ تَعَالَى: {ثُمَّ مَحِلُّهَا إِلَى الْبَيْتِ الْعَتِيقِ} [الحج: ٣٣] قَالَ: قُلْتُ: فَإِنَّ ذَلِكَ بَعْدَ الْمُعَرَّفِ. فَقَالَ: كَانَ ابْنُ عَبَّاسٍ [رَضِيَ اللهُ عَنْهُمَا] يَقُولُ: هُوَ بَعْدَ الْمُعَرَّفِ وَقَبْلَهُ، وَكَانَ يَأْخُذُ ذَلِكَ مِنْ أَمْرِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ أَمَرَهُمْ أَنْ يَحِلُّوا فِي حَجَّةِ الْوَدَاعِ. (م)', 'ഇബ്നുജുറൈജ്: അത്വാഅ് എന്നോട് പറഞ്ഞു: ഇബ്നുഅബ്ബാസ്(റ) പറയുമായിരുന്നു. ഹജ്ജ് ചെയ്യുന്നവനാണെങ്കിലും അല്ലെങ്കിലും കഅ്ബ ത്വവാഫ് ചെയ്താൽ അവൻ തഹല്ലുലാവും. അത്വാഇനോട് ഞാൻ ചോദിച്ചു: എന്ത് അടിസ്ഥാനത്തിലാണ് ഇബ്നുഅബ്ബാസ്(റ) അങ്ങനെ പറയുന്നത്. അത്വാഅ്(റ) പറഞ്ഞു: ''പിന്നീട് അവയുടെ ബലികർമ്മത്തിന് അനുവദിക്കപ്പെട്ട സ്ഥലം പുരാതന വീടിന്നടുത്താണ്'' (ഹജ്ജ്: 33) എന്ന സൂക്തത്തിന്റെ അടിസ്ഥാനത്തിൽ. ഞാൻ പറഞ്ഞു: അത് അറഫക്ക് ശേഷമാണ്. അത്വാഅ്(റ) പറഞ്ഞു: ഇബ്നുഅബ്ബാസ്(റ) പറയുമായിരുന്നു: അറഫക്ക് ശേഷവും മുമ്പും അങ്ങനെ തന്നെയാണ്. ഹജ്ജതുൽ വിദാഇൽ (അറഫയിൽ നിൽക്കുന്നതിന് മുമ്പ്) തഹല്ലുലാവാൻ റസൂൽ(സ) അവരോട് കൽപ്പിച്ചതിൽ നിന്ന് ഇബ്നുഅബ്ബാസ്(റ) ഇത് മനസ്സിലാക്കി. (മു)', 'ابْنِ جُرَيْجٍ', 'ഇബ്നുജുറൈജ്', null, null, array['م']::text[], array['മു']::text[], 'رَضِيَ اللهُ عَنْهُمَا', null, 397, 397, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=181 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 532, 'عَنْ عَائِشَةَ وَابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُم: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَخَّرَ طَوَافَ الزِّيَارَةِ إِلَى اللَّيْلِ. (خ,د,ت,جه)', 'ആഇശ(റ), ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) സന്ദർശന ത്വവാഫ് രാത്രിയിലേക്ക് പിന്തിച്ചു. (ബു,ദ,തു,ജ)', 'عَائِشَةَ وَابْنِ عَبَّاسٍ', 'ആഇശ(റ)', null, null, array['خ','د','ت','جه']::text[], array['ബു','ദ','തു','ജ']::text[], null, null, 397, 397, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=182 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 533, 'عَنْ عَائِشَةَ وَابْنِ عَبَّاسٍ، رَضِيَ اللهُ عَنْهُم: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَخَّرَ طَوَافَ يَوْمِ النَّحْرِ إِلَى اللَّيْلِ. (د,ت,ن,جه)', 'ആഇശ(റ), ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) നഹ്റ് ദിനത്തിലെ ത്വവാഫിനെ രാത്രിയിലേക്ക് പിന്തിച്ചു. (ദ,തു,ന,ജ)', 'عَائِشَةَ وَابْنِ عَبَّاسٍ،', 'ആഇശ(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 397, 397, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=182 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 534, 'عَنِ الْمِسْوَرِ بْنِ مَخْرَمَةَ – رَضِيَ اللهُ عَنْهُمَا – وَمَرْوَانَ بْنِ الْحَكَمِ قَالَ: خَرَجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ زَمَنَ الْحُدَيْبِيَةِ فِي بِضْعَ عَشْرَةَ مِائَةً مِنْ أَصْحَابِهِ، حَتَّى إِذَا كَانُوا بِذِي الْحُلَيْفَةِ قَلَّدَ الْهَدْيَ وَأَشْعَرَ، وَأَحْرَمَ بِالْعُمْرَةِ. (ن)', 'മിസ്‌വറുബ്നു മഖ്റമ(റ): ഹുദൈബിയാ സമയത്ത് ആയിരത്തിൽപരം അനുയായികളുമായി റസൂൽ(സ) പുറപ്പെട്ടു. ദുൽഹുലൈഫയിൽ എത്തിയപ്പോൾ ബലിമൃഗത്തെ കെട്ടുകയും അടയാളം വെക്കുകയും ഉംറക്ക് വേണ്ടി ഇഹ്റാം ചെയ്യുകയും ചെയ്തു. (ന)', 'الْمِسْوَرِ بْنِ مَخْرَمَةَ –', 'മിസ്‌വറുബ്നു മഖ്റമ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 398, 398, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=183 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 535, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَدْ أُحْصِرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَحَلَقَ رَأْسَهُ وَجَامَعَ نِسَاءَهُ وَنَحَرَ هَدْيَهُ، حَتَّى اعْتَمَرَ عَامًا قَابِلًا. (خ)', 'ഇബ്നുഅബ്ബാസ്(റ): ഹുദൈബിയ്യാ സന്ധിയുടെ വർഷത്തിൽ, തിരുമേനി(സ)യെ ബഹുദൈവവിശ്വാസികൾ ഉംറയിൽ നിന്നു തടഞ്ഞു. അന്നേരം തിരുമേനി(സ) തലമുണ്ഡനം ചെയ്തു. ഭാര്യമാരുമായി സഹവസിച്ചു. ബലിയറുക്കുകയും ചെയ്തു. എന്നിട്ട് അടുത്ത വർഷം ഉംറ നിർവ്വഹിച്ചു. (ബു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 398, 398, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=183 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 536, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا أنه كان يَقُولُ: أَلَيْسَ حَسْبُكُمْ سُنَّةَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ إِنْ حُبِسَ أَحَدُكُمْ عَنِ الْحَجِّ طَافَ بِالْبَيْتِ وَبِالصَّفَا وَالْمَرْوَةِ ثُمَّ حَلَّ مِنْ كُلِّ شَيْءٍ؟ حَتَّى يَحُجَّ عَامًا قَابِلًا فَيُهْدِي أَوْ يَصُومُ إِنْ لَمْ يَجِدْ هَدْيًا. (خ)', 'ഇബ്നുഉമർ(റ): നിങ്ങൾക്ക് തിരുമേനി(സ)യുടെ സുന്നത് മതിയാവുകയില്ലേ? നിങ്ങളെ ആരെങ്കിലും ഹജ്ജിൽ നിന്നു തടഞ്ഞാൽ, കഅ്ബ ത്വവാഫ് ചെയ്തു സ്വഫാ മർവ്വക്കിടയിൽ നടന്നു കൊണ്ട് അവൻ ഇഹ്റാമിൽ നിന്നു പൂർണ്ണമായും വിരമിച്ചു കൊള്ളട്ടെ. അടുത്ത കൊല്ലം ഹജ്ജു നിർവ്വഹിക്കട്ടെ. അന്നേരം ബലിയറുക്കുകയോ അതിനു സാധിച്ചില്ലെങ്കിൽ പകരം വ്രതമനുഷ്ഠക്കുകയോ ചെയ്യാം. (ബു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 398, 398, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=183 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 537, 'عَنِ الْمِسْوَرِ رَضِيَ اللهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، نَحَرَ قَبْلَ أَنْ يَحْلِقَ، وَأَمَرَ أَصْحَابَهُ بِذَلِكَ. (خ)', 'മിസ്‌വർ(റ): നിശ്ചയം റസൂൽ(സ) മുടികളയുന്നതിന്റെ മുമ്പ് അറവ് നടത്തുകയും , അനുയായികളെ അതിന് കൽപ്പിക്കുകയും ചെയ്തു. (ബു)', 'الْمِسْوَرِ', 'മിസ്‌വർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 398, 398, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=183 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 538, 'عَنْ عِكْرِمَةَ قَالَ: سَمِعْتُ الْحَجَّاجَ بْنَ عَمْرٍو الْأَنْصَارِيَّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ كُسِرَ أَوْ عَرِجَ – وفي رواية: أَوْ مَرِضَ – فَقَدْ حَلَّ، وَعَلَيْهِ الْحَجُّ مِنْ قَابِلٍ". قَالَ عِكْرِمَةُ: سَأَلْتُ ابْنَ عَبَّاسٍ وَأَبَا هُرَيْرَةَ – رَضِيَ اللهُ عَنْهُم – عَنْ ذَلِكَ فَقَالَا: صَدَقَ. (د)', 'ഇക്‌രിമ(റ): ഹജ്ജാജുബ്നു അംറിൽ അൻസാരി(റ) പറയുന്നതായി ഞാൻ കേട്ടു: തിരുമേനി(സ) അരുളി: "എല്ലു പൊട്ടുകയോ മുടന്തനാവുകയോ - മറ്റൊരു നിവേദത്തിൽ: രോഗിയാവുകയോ - ചെയ്താൽ അവൻതഹല്ലുലാകും. അടുത്ത വർഷം അവൻ ഹജ്ജ് ചെയ്യണം." ഇക്‌രിമ(റ) പറയുന്നു: അബൂഹുറൈറ(റ)യോടും ഇബ്നുഅബ്ബാസ്(റ)വിനോടും ഞാൻ ഇതിനെ കുറിച്ച് ചോദിച്ചു: അവർ പറഞ്ഞു: സത്യമാണ് പറഞ്ഞത്. (ദ)', 'عِكْرِمَةَ قَالَ', 'ഇക്‌രിമ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 398, 398, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=183 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=4 and h.hadith_no=538), 1, 'وَفِي رِوَايَةٍ: أَوْ مَرِضَ – فَقَدْ حَلَّ، وَعَلَيْهِ الْحَجُّ مِنْ قَابِلٍ". قَالَ عِكْرِمَةُ: سَأَلْتُ ابْنَ عَبَّاسٍ وَأَبَا هُرَيْرَةَ – رَضِيَ اللهُ عَنْهُم – عَنْ ذَلِكَ فَقَالَا: صَدَقَ. (د)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 539, 'عَنْ عَمْرِو بْنِ مَيْمُونٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ أَبَا حَاضِرٍ الْحِمْيَرِيَّ يُحَدِّثُ أَبِي مَيْمُونَ بْنَ مِهْرَانَ قَالَ: خَرَجْتُ مُعْتَمِرًا عَامَ حَاصَرَ أَهْلُ الشَّامِ ابْنَ الزُّبَيْرِ بِمَكَّةَ، وَبَعَثَ مَعِي رِجَالٌ مِنْ قَوْمِي بِهَدْيٍ، فَلَمَّا انْتَهَيْنَا إِلَى أَهْلِ الشَّامِ مَنَعُونَا أَنْ نَدْخُلَ الْحَرَمَ، فَنَحَرْتُ الْهَدْيَ مَكَانِي، ثُمَّ أَحْلَلْتُ، ثُمَّ رَجَعْتُ، فَلَمَّا كَانَ مِنَ الْعَامِ الْمُقْبِلِ خَرَجْتُ لِأَقْضِيَ عُمْرَتِي، فَأَتَيْتُ ابْنَ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا فَسَأَلْتُهُ، فَقَالَ: أَبْدِلِ الْهَدْيَ، فَإِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمَرَ أَصْحَابَهُ أَنْ يُبَدِّلُوا الْهَدْيَ الَّذِي نَحَرُوا عَامَ الْحُدَيْبِيَةِ فِي عُمْرَةِ الْقَضَاءِ. (د)', 'അംറുബ്നു മൈമൂൻ(റ): എന്റെ പിതാവ് മൈമൂനിബിൻ മിഹ്റാൻ പറയുന്നതായി അബൂ ഹാളിറിൽ ഹിംയരി(റ) ഉദ്ദരിക്കുന്നത് ഞാൻകേട്ടു: മൈമൂൻ(റ) പറയുന്നു: ഇബ്നുസുബൈർ(റ)വിനെ മക്കയിൽ ശാമുകാർ ഉപരോധിച്ച വർഷം ഞാൻ ഉംറക്കായി പുറപ്പെട്ടു. എന്റെ സമൂഹത്തിലെ ചിലയാളുകൾ ബലിമൃഗങ്ങൾ എന്റെ കൂടെ അയച്ചു. ശാമുകാർ പവിത്രമണ്ണിൽ പ്രവേശിപ്പിക്കാതെ എന്നെ തടഞ്ഞു വെച്ചു. ഞാൻ ബലിമൃഗങ്ങളെ അവിടെ വെച്ചു തന്നെ അറുക്കുകയും തഹല്ലുലാവുകയും ചെയ്തു. അടുത്ത വർഷം എന്റെ ഉംറ വീണ്ടെടുക്കാൻ ഞാൻ പുറപ്പെട്ടു. ഞാൻ ഇബ്നുഅബ്ബാസ്(റ)വിനെ സമീപിച്ച് ഇതിനെക്കുറിച്ച് ചോദിച്ചു: ഇബ്നുഅബ്ബാസ്(റ) പറഞ്ഞു: പുതിയ ബലിമൃഗങ്ങളെ കൊണ്ടു വരിക. കാരണം ഹുദൈബിയ്യാ വർഷം അവർ അറുത്ത ബലി മൃഗങ്ങൾക്ക് പകരം ''ഉംറതുൽ ഖളാഇ''ൽ പുതിയ ബലിമൃഗങ്ങളെ അറുക്കാൻ റസൂൽ(സ)തന്റെ അനുചരരോട് കൽപ്പിച്ചു. (ദ)', 'عَمْرِو بْنِ مَيْمُونٍ', 'അംറുബ്നു മൈമൂൻ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 398, 399, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=183 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 540, 'عَنْ عَبْدِ اللَّهِ بْنِ مَعْقِلٍ قَالَ: قَعَدْتُ إِلَى كَعْبِ بْنِ عُجْرَةَ فِي الْمَسْجِدِ، فَسَأَلْتُهُ عَنْ هَذِهِ الْآيَةِ {فَفِدْيَةٌ مِنْ صِيَامٍ أَوْ صَدَقَةٍ أَوْ نُسُكٍ} [البقرة: ١٩٦] قَالَ كَعْبٌ: فِيَّ أُنْزِلَتْ، كَانَ بِي أَذًى مِنْ رَأْسِي، فَحُمِلْتُ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَالْقَمْلُ يَتَنَاثَرُ عَلَى وَجْهِي، فَقَالَ: "مَا كُنْتُ أُرَى الْجُهْدَ بَلَغَ بِكَ مَا أَرَى، أَتَجِدُ شَاةً". قُلْتُ: لَا. قَالَ: فَنَزَلَتْ هَذِهِ الْآيَةُ: {فَفِدْيَةٌ مِنْ صِيَامٍ أَوْ صَدَقَةٍ أَوْ نُسُكٍ}. قَالَ: فَالصَّوْمُ ثَلَاثَةُ أَيَّامٍ، وَالصَّدَقَةُ عَلَى سِتَّةِ مَسَاكِينَ: لِكُلِّ مِسْكِينٍ نِصْفُ صَاعٍ مِنْ طَعَامٍ، وَالنُّسُكُ شَاةٌ. (ق,ت,جه)', 'അബ്ദുല്ലാഹിബ്നു മഅ്ഖൽ(റ): ഒരിക്കൽ കഅ്ബുബ്നു ഉജ്റത്(റ) പള്ളയിലിരിക്കുമ്പോൾ ഞാൻ അവരുടെ സമീപത്ത് ചെന്നിരിക്കുകയും ''നോമ്പ്, അല്ലങ്കിൽ ധർമ്മം അതുമല്ലെങ്കിൽ ബലി. ഇതിൽ ഏതെങ്കിലും ഒന്ന് പ്രായശ്ചിത്തം കൊടുക്കുക.'' (2: 196) എന്ന സൂക്തത്തെക്കുറിച്ച് അവരോട് ചോദിക്കുകയും ചെയ്തു. അപ്പോൾ കഅ്ബ്(റ) പറഞ്ഞു: ഈ സൂക്തം എന്റെ കാര്യത്തിൽ അവതരിച്ചതാണ്. എന്റെ തലയിൽ പേൻ അധികരിക്കുകയും മുഖത്തുകൂടി വീണുകൊണ്ടിരിക്കുകയും ചെയ്തു കൊണ്ടിരിക്കെ ഞാൻ തിരുമേനി(സ)യുടെ അടുക്കലെത്തി. റസൂൽ(സ) പറഞ്ഞു: "നീ വല്ലാതെ വിഷമിക്കുന്നതായി ഞാൻ കാണുന്നു. നിനക്ക് ഒരാടിനെ കിട്ടുമോ?" ഞാൻ പറഞ്ഞു: ഇല്ല. അപ്പോഴാണ് പ്രസ്തുത സൂക്തം ഇറങ്ങിയത്. ഇതിലെ നോമ്പ് എന്നത് മൂന്ന് ദിവസം നോമ്പെടുക്കലും, സ്വദഖയെന്നാൽ ഒരു ദരിദ്രന് അര സ്വാഅ് എന്ന തോതിൽ ആറ് ദരിദ്രക്ക് ഭക്ഷണം ധർമ്മം ചെയ്യലും, നുസുക് എന്നാൽ ആടിനെ ബലി നൽകലുമാണ്. (ബു,മു,തു,ജ)', 'عَبْدِ اللَّهِ بْنِ مَعْقِلٍ قَالَ', 'അബ്ദുല്ലാഹിബ്നു മഅ്ഖൽ(റ)', null, null, array['ق','ت','جه']::text[], array['ബു','മു','തു','ജ']::text[], 'البقرة: ١٩٦', null, 399, 399, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=184 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 541, 'عَنْ أَبِي أُمَامَةَ التَّيْمِيُّ رَضِيَ اللهُ عَنْهُ قَالَ: كُنْتُ رَجُلًا أُكَرِّي فِي هَذَا الْوَجْهِ، وَكَانَ نَاسٌ يَقُولُونَ لِي: إِنَّهُ لَيْسَ لَكَ حَجٌّ، فَلَقِيتُ ابْنَ عُمَرَ رَضِيَ اللهُ عَنْهُمَا، فَقُلْتُ: يَا أَبَا عَبْدِ الرَّحْمَنِ، إِنِّي رَجُلٌ أُكَرِّي فِي هَذَا الْوَجْهِ، وَإِنَّ نَاسًا يَقُولُونَ لِي: إِنَّهُ لَيْسَ لَكَ حَجٌّ؟ فَقَالَ ابْنُ عُمَرَ: أَلَيْسَ تُحْرِمُ وَتُلَبِّي، وَتَطُوفُ بِالْبَيْتِ، وَتُفِيضُ مِنْ عَرَفَاتٍ، وَتَرْمِي الْجِمَارَ؟ قَالَ: قُلْتُ: بَلَى، قَالَ: فَإِنَّ لَكَ حَجًّا، جَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَسَأَلَهُ عَنْ مِثْلِ مَا سَأَلْتَنِي عَنْهُ، فَسَكَتَ عَنْهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَلَمْ يُجِبْهُ، حَتَّى نَزَلَتْ هَذِهِ الْآيَةُ: {لَيْسَ عَلَيْكُمْ جُنَاحٌ أَنْ تَبْتَغُوا فَضْلًا مِنْ رَبِّكُمْ} [البقرة: ١٩٨] فَأَرْسَلَ إِلَيْهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَقَرَأَ عَلَيْهِ هَذِهِ الْآيَةَ، وَقَالَ: "لَكَ حَجٌّ". (د)', 'അബൂഉമാമതുത്തൈമീ(റ): ഈ ലക്ഷ്യത്തിന് (ഹജ്ജിന് യാത്ര ചെയ്യാൻ) വേണ്ടി യാത്ര മൃഗങ്ങളെ വാടകക്കു കൊടുക്കുന്ന ആളായിരുന്നു ഞാൻ. ജനങ്ങൾ എന്നോട് പറയുമായിരുന്നു: തീർച്ചയായും നിനക്ക് ഹജ്ജില്ല. ഇബ്നുഉമർ(റ)വിനെ കണ്ടുമുട്ടിയപ്പോൾ ഞാൻ ചോദിച്ചു: ഓ അബാ അബ്ദിർറഹ്മാൻ, ഹജ്ജിന് യാത്ര ചെയ്യാൻ വേണ്ടി മൃഗങ്ങളെ വാടകക്കു കൊടുക്കുന്നവനാണ് ഞാൻ. ജനങ്ങൾ നിനക്ക് ഹജ്ജില്ല എന്നോട് പറയുന്നു. ഇബ്നുഉമർ(റ) ചോദിച്ചു: നീ ഇഹ്റാം ചെയ്യുകയും തൽബിയത് ചൊല്ലുകയും കഅ്ബ പ്രദക്ഷിണം നടത്തുകയും അറഫയിൽ നിന്ന് മടങ്ങുകയും ജംറകളിൽ എറിയുകയും ചെയ്തിട്ടില്ലെയോ? നിവേദകൻ പറയുന്നു: ഞാൻ പറഞ്ഞു: അതെ, ഇബ്നുഉമർ(റ) പറഞ്ഞു: നിനക്ക് ഹജ്ജുണ്ട്. ഒരാൾ റസൂൽ(സ)യുടെ അരികിൽ വന്ന് നീ എന്നോട് ചോദിച്ചതു പോലെ ചോദിച്ചു: റസൂൽ(സ) മൗനം പാലിച്ചു. മറുപടി നൽകിയില്ല. അങ്ങനെ ഈ സൂക്തമിറങ്ങി. ''നിങ്ങളുടെ നാഥനിൽ നിന്നുള്ള അനുഗ്രഹങ്ങൾ നിങ്ങൾ തേടുന്നതിൽ കുറ്റമൊന്നുമില്ല.'' (2: 198) അപ്പോൾ തിരുമേനി(സ) ചോദ്യകർത്താവിനടുത്തേക്ക് ആളെ അയച്ചു. എന്നിട്ട് ഈ സൂക്തം ഓതിക്കൊടുത്തു. റസൂൽ(സ) പറഞ്ഞു: "നിനക്ക് ഹജ്ജുണ്ട്." (ദ)', 'أَبِي أُمَامَةَ التَّيْمِيُّ', 'അബൂഉമാമതുത്തൈമീ(റ)', null, null, array['د']::text[], array['ദ']::text[], 'البقرة: ١٩٨', null, 399, 400, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=185 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 542, 'عَنْ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّاسَ فِي أَوَّلِ الْحَجِّ كَانُوا يَتَبَايَعُونَ بِمِنًى، وَعَرَفَةَ، وَسُوقِ ذِي الْمَجَازِ، وَمَوَاسِمِ الْحَجِّ، فَخَافُوا الْبَيْعَ وَهُمْ حُرُمٌ، فَأَنْزَلَ اللَّهُ سُبْحَانَهُ: {لَيْسَ عَلَيْكُمْ جُنَاحٌ أَنْ تَبْتَغُوا فَضْلًا مِنْ رَبِّكُمْ} فِي مَوَاسِمِ الْحَجِّ. (د)', 'അബ്ദുല്ലാഹിബ്നുഅബ്ബാസ്(റ): ഹജ്ജിന്റെ പ്രാരംഭ കാലത്ത് മിന, അറഫ, ദീമജാസിലെ മാർക്കറ്റ്, ഹജ്ജിന്റെ വേള എന്നിവിടങ്ങളിൽ വെച്ച് ജനങ്ങൾ കച്ചവടം ചെയ്യാറുണ്ടായിരുന്നു. ശേഷം മുഹ്‌രിമായിരിക്കെ കച്ചവടം നടത്താൻ അവർ ഭയന്നു. അപ്പോൾ അല്ലാഹു ഈ സൂക്തമിറക്കി. ഹജ്ജിന്റെ കാലത്ത് ''നിങ്ങളുടെ നാഥനിൽ നിന്നുള്ള അനുഗ്രഹങ്ങൾ തേടുന്നതിൽ കുറ്റമൊന്നുമില്ല.'' (ദ)', 'عَبْدِ اللَّهِ بْنِ عَبَّاسٍ', 'അബ്ദുല്ലാഹിബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 400, 400, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=185 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 543, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا قَفَلَ مِنَ الْجُيُوشِ، أَوِ السَّرَايَا أَوِ الْحَجِّ أَوِ الْعُمْرَةِ، إِذَا أَوْفَى عَلَى ثَنِيَّةٍ أَوْ فَدْفَدٍ كَبَّرَ ثَلَاثًا، ثُمَّ قَالَ: "لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ. آيِبُونَ تَائِبُونَ عَابِدُونَ سَاجِدُونَ، لِرَبِّنَا حَامِدُونَ، صَدَقَ اللَّهُ وَعْدَهُ، وَنَصَرَ عَبْدَهُ، وَهَزَمَ الْأَحْزَابَ وَحْدَهُ". (م)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): റസൂൽ(സ) യുദ്ധം, സൈന്യത്തെ അയക്കൽ, ഹജ്ജ്, ഉംറ എന്നിവ കഴിഞ്ഞ് തിരിച്ചുവരുമ്പോൾ വല്ല കുന്നിൻ മുകളിലോ ഉയർന്ന സ്ഥലത്തോ കയറിയാൽ മൂന്ന് പ്രാവശ്യം തക്ബീർ ചൊല്ലുകയും പിന്നെ ഇപ്രകാരം പറയുകയും ചെയ്യുമായിരുന്നു: "അല്ലാഹുവല്ലാതെ ആരാധ്യനില്ല. അവൻ ഏകനും പങ്കുകാരില്ലാത്തവനുമാണ്. അവന്നാണ് ആധിപത്യം, അവന്നാണ് സർവ്വസ്തുതിയും, അവൻ എല്ലാറ്റിനും കഴിവുള്ളവനാകുന്നു. ഞങ്ങൾ ഞങ്ങളുടെ നാഥനെ സ്തുതിക്കുകയും അവന് സാഷ്ടാംഗമർപ്പിക്കുകയും അവനെ ആരാധിക്കുകയും അവനിലേക്ക് പശ്ചാത്തപിച്ച് മടങ്ങുകയും ചെയ്തു കൊണ്ടിതാ തിരിച്ചു വരുന്നു. അല്ലാഹു അവന്റെ വാഗ്ദത്തം സാക്ഷാൽകരിക്കുകയും തന്റെ അടിമയെ സഹായിക്കുകയും തനിച്ച് സഖ്യകക്ഷികളെയെല്ലാം ആട്ടിയോടിക്കുകയും ചെയ്തിരിക്കുന്നു." (മു)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 400, 400, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=186 where b.volume_id=2 and b.book_no=4 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
